P.entries["subzone:scarlet-base-camp"] = {n="Багряний Базовий Табір",s="Багряний Базовий Табір — укріплена застава на східному березі Озера Мерельдар у Східних Чумних Землях, трохи на захід від Руки Тіра. Його барикади позначають зовнішній рубіж оборони Багряного Хрестового Походу.",h="Багряний Базовий Табір — укріплена застава на східному березі Озера Мерельдар у Східних Чумних Землях, трохи...",kw={"багряний базовий табір","застава","озеро мерельдар","рука тіра","багряний хрестовий похід"},ang={["class:Paladin"]="Табір відбиває трагічне спотворення спадщини Срібної Длані: праведна завзятість у захисті святої землі Лордерона переродилася тут в агресивну параною щодо інших уцілілих.",["race:Undead"]="Застава — пряме нагадування про живих фанатиків, які прагнуть вичистити Відступників із Лордерона так само безжально, як полюють на безтямну Погибель."},sec={{t="Передова лінія на Озері Мерельдар",b="Багряний Базовий Табір, що стоїть на східному березі Озера Мерельдар, — обнесене барикадами укріплення трохи на захід від Руки Тіра. Він позначає зовнішню позицію Багряного Хрестового Походу в зачумленій сільській місцевості."},{t="Щит для твердині",b="Рука Тіра — одна з твердинь Багряного Хрестового Походу в Лордероні. Табір лежить на її західних підступах, у краї, де Похід прагне відвоювати землю в нежиті й з підозрою ставиться до чужинців."}},faq={{q="Для чого потрібен Багряний Базовий Табір?",a="Табір — забарикадоване укріплення Багряного Хрестового Походу на східному березі Озера Мерельдар, трохи на захід від Руки Тіра.",al={"що таке багряний базовий табір","чому тут багряний табір","призначення базового табору"}},{q="Хто очолює сили в таборі?",a="Командир первісного табору в класичній версії не названий. Це позиція Багряного Хрестового Походу біля Руки Тіра.",al={"хто очолює багряний базовий табір","командир табору","лідери багряного табору"}},{q="Чи ворожі тутешні мешканці до мандрівників?",a="Багряний Хрестовий Похід ворожий до чужинців з обох фракцій і вважає їх можливими носіями чуми чи агентами Погибелі.",al={"чи нападе багряний базовий табір","чи ворожий багряний табір","чи вони дружні"}},{q="Де стоїть табір відносно Озера Мерельдар?",a="Він стоїть на східному березі Озера Мерельдар, трохи на захід від Руки Тіра.",al={"озеро мерельдар біля багряного табору","де багряний табір","табір біля руки тіра"}}},fp="17,203,31.197.0,21.221.0,45.117.0,43.107.0,39.138.0,47.67.0"}
P.entries["subzone:scarlet-basilica"] = {n="Багряна Базиліка",s="Багряна Базиліка — величний собор у самому серці Руки Тіра у Східних Чумних Землях. Це найвищий осередок духовної й військової влади Багряного Хрестового Походу на сході. Під проводом Лорда-хрестоносця Вальдельмара її зали стали непохитним оплотом фанатиків проти Погибелі.",h="Багряна Базиліка — величний собор у самому серці Руки Тіра у Східних Чумних Землях.",kw={"багряна базиліка","собор","рука тіра","вальдельмар","багряний хрестовий похід"},ang={["class:Paladin"]="Базиліка — спотворений пам'ятник святій відданості, що збилася з путі: колишні лицарі Срібної Длані обернули свій запал на безжальний фанатизм.",["race:Undead"]="Для Відступників базиліка — один із найукріпленіших форпостів фанатиків, які прагнуть цілковито знищити всю нежить, байдуже, чи має вона власну волю."},sec={{t="Серце східного Походу",b="Багряна Базиліка, що гордо височіє над укріпленим анклавом Руки Тіра, — головний собор і командний центр Багряного Хрестового Походу у Східних Чумних Землях. Духовне серце ордену — Багряний Монастир далеко на заході, у Галявинах Тірісфалю, а ця базиліка тримає вцілілу територіальну твердиню хрестоносців серед зачумлених жахіть Лордерона. Добірні хрестоносці люто стережуть собор, де перебуває Лорд-хрестоносець Вальдельмар: він керує місцевою обороною й завзято знищує кожного чужинця, що наважиться підійти."}},faq={{q="Що таке Багряна Базиліка?",a="Багряна Базиліка — величний собор у місті-фортеці Рука Тіра у Східних Чумних землях. Це головний осідок релігійної й військової влади Багряного Хрестового Походу в краї.",al={"багряна базиліка інформація","що це за собор","церква руки тіра"}},{q="Хто очолює сили в Базиліці?",a="Силами в Багряній Базиліці командує Лорд-хрестоносець Вальдельмар — один із високопоставлених ватажків Багряного Хрестового Походу, що тримає Руку Тіра проти Погибелі й інших, кого орден має за ворогів.",al={"хто в багряній базиліці","вальдельмар","бос багряної базиліки"}},{q="Як вона порівнюється з Багряним Монастирем?",a="Багряний Монастир на Галявинах Тірісфалю — головний духовний штаб ордену, а Багряна Базиліка — його східний відповідник, могутній релігійний і укріплений осередок глибоко в Чумних Землях.",al={"монастир проти базиліки","чи це багряний монастир"}},{q="Чи раді в Базиліці мандрівникам?",a="Ні. Багряний Хрестовий Похід скотився в божевільну ненависть до чужинців і вірить, що кожен, хто не вбраний у його багряні кольори, заражений нежиттям. На зайд з Альянсу й з Орди нападають одразу.",al={"чи може альянс зайти","чи ворожа багряна базиліка","чи можна відвідати"}}},fp="16,315,28.565.0,29.223.0,41.202.0,47.237.0,42.209.0"}
P.entries["subzone:scarlet-monastery"] = {n="Багряний Монастир",s="Багряний Монастир, що стоїть на північно-східних пагорбах Галявин Тірісфалю, колись був мирним осередком науки й богослужіння Церкви Святого Світла. Після падіння Лордерону він став добре укріпленою твердинею фанатичного Багряного Хрестового Походу. Кожного, хто наближається без червоних барв, мають за заразного носія чуми і страчують на місці.",h="Багряний Монастир, що стоїть на північно-східних пагорбах Галявин Тірісфалю, колись був мирним осередком...",kw={"багряний монастир","багряний хрестовий похід","моґрейн","вайтмейн","монастир","собор","тірісфаль"},ang={["class:Paladin"]="Колись цей комплекс готував паладинів під проводом Срібної Длані, тож його переродження на нетерпимий бастіон фанатизму — гірке видовище для вірних святих воїнів.",["faction:Horde"]="Монастир стоїть просто на порозі Андерсіті, тож його добре озброєні хрестоносці — діяльна, смертельна загроза землям Відступників."},sec={{t="Від святині до твердині",b="До Третьої війни цей комплекс знали просто як Старий Монастир. Під опікою духівництва Лордерону й покровительством шляхетних домів він був важливим осередком богословських студій, священних архівів і вишколу паладинів. Коли Королівство Лордерон упало перед Погибеллю, уцілілі рештки Срібної Длані повернули собі це місце як передовий бастіон для ударів по нежиті, що зайняла Столицю — стольне місто королівства. Коли ж захисники виродилися в ревний Багряний Хрестовий Похід, вони укріпили обитель, обернувши її мирні бібліотеки, сади й собор на озброєну цитадель."},{t="Бастіон фанатизму",b="Поділений на чотири окремі крила — осквернений цвинтар, простору бібліотеку, збройову палату й великий собор, — Монастир нині вміщує величезний гарнізон під командою Багряного командира Моґрейна та Верховної інквізиторки Вайтмейн. Тутешні хрестоносці бачать у всіх чужинцях — живих чи нежиті, Альянсі чи Орді — носіїв чуми. Поки Відступники прагнуть знищити гарнізон, що загрожує самому їхньому порогу, провід Альянсу дедалі більше вважає жорстокий екстремізм Хрестового Походу небезпечним збоченням Світла."}},faq={{q="Чому тут стоїть Багряний Монастир?",a="Спершу його збудували за часів королівства Лордерон як мирну обитель для навчання: тут зберігали священні писання й навчали паладинів. Після падіння королівства вцілілі хрестоносці захопили й укріпили його, зробивши військовим плацдармом проти нежиті на Галявинах Тірісфалю.",al={"що таке багряний монастир","чому збудували монастир у тіріфалі","призначення монастиря"}},{q="Чому Багряний Хрестовий Похід нападає на членів Альянсу?",a="Фанатизм Походу переріс у цілковиту параною. Хрестоносці вірять, що кожен, хто бував за межами їхніх укріплених поселень, може нести чуму нежиття Погибелі, і не ризикують із чужинцями — хоч би якої вони були раси й вірності.",al={"чому багряні вороги альянсу","чи багряний похід з альянсом","чому хрестоносці нападають на людей"}},{q="Хто очолює сили в Монастирі?",a="Гарнізон тримає Багряний командир Моґрейн, що керує військовими діями із собору, і Верховна інквізиторка Вайтмейн — ревна жриця, славетна своєю відданістю й силою воскрешати.",al={"бос багряного монастиря","лідери монастиря","хто керує багряним походом"}},{q="Які чотири крила має комплекс?",a="Комплекс поділено на чотири окремі частини: Кладовище, де повно неспокійних мерців і катівень; Бібліотеку, що береже історичні архіви й фоліанти; Зброярню, де Похід кує зброю й обладунки; і Собор — духовне серце й осідок командира.",al={"секції монастиря","які крила в багряному монастирі","планування монастиря"}}},fp="17,382,28.595.0,23.524.0,34.281.0,53.264.0,42.212.0,39.286.0"}
P.entries["subzone:scarlet-monastery-armory"] = {n="Зброярня Багряного Монастиря",s="Зброярня — укріплене військове крило Багряного Монастиря, де кують зброю й навчають новобранців для Багряного Хрестового Походу. За замкненою залізною брамою шеренги ревних піхотинців і хрестоносців муштруються під суворою рукою Герода, Багряного Чемпіона.",h="Зброярня — укріплене військове крило Багряного Монастиря, де кують зброю й навчають новобранців для Багряного...",kw={"зброярня","багряний монастир","герод","багряний чемпіон","зала чемпіонів","багряний ключ"},ang={["class:Warrior"]="Зброярня — справжній полігон смертельного бою, де багряні воїни показують убивчі стійки, обеззброєння й знаменитий вихор Герода.",["faction:Horde"]="Поки Багряний Хрестовий Похід стягує військо просто під брамою Андерсіті, сплюндрувати їхні арсенали й убити їхнього чемпіона — життєво важливо для виживання Відступників."},sec={{t="Кузня фанатизму",b="Колись монастир був частиною мирного притулку для духівництва Лордерону, але після Третьої війни його повністю переробили. Тепер Зброярня — головна кузня, склад зброї та бойовий полігон Походу. Від відкритих тренувальних дворів до глибоких збройових зал шеренги багряних піхотинців, чаклунів і хрестоносців невтомно готуються знищувати Погибель і всіх, кого вважають зараженими. Крило відгороджене від Великого Вестибюлю, і потрапити туди можна лише з Багряним Ключем, який знаходять у сусідній Бібліотеці."},{t="Зала Чемпіонів",b="У серці крила лежить Зала Чемпіонів, де вишикувалися височенні статуї легендарних героїв із минулого Походу. Наглядає за залою Герод — брутальний воїн, чия лють і вихори серед хрестоносців уже стали легендою. Герод особисто навчає нове покоління фанатиків, і коли в бою йому доводиться скрутно, його відчайдушні новобранці вриваються до зали, щоб битися й гинути за свого чемпіона."}},faq={{q="Як потрапити до Зброярні?",a="Двері Зброярні у Великому Вестибюлі міцно замкнені. Щоб їх відчинити, треба пройти в крило Бібліотеки й дістати Багряний Ключ зі скрині за арканістом Доаном в Атенеумі — або взяти із собою розбійника, вправного у зламуванні замків.",al={"зброярня замкнена","як відімкнути зброярню","багряний ключ зброярня","відчинити двері зброярні"}},{q="Хто очолює війська в Зброярні?",a="Крилом командує Герод, відомий як Багряний Чемпіон. Він стоїть у Залі Чемпіонів, муштрує вояків і проводить новобранців крізь жорсткі бойові випробування.",al={"бос зброярні","хто керує зброярнею","хто головний у зброярні","герод зброярня"}},{q="Яке призначення цього крила для Багряного Хрестового Походу?",a="Це головний арсенал і військова академія Походу. Тут великі кузні, зброярні для піхотинців і хрестоносців і плаци просто неба, де вояків гартують, перш ніж послати по всьому Тірісфалю й Чумних Землях.",al={"чому існує зброярня","що вони тут роблять","призначення зброярні"}},{q="Чиї статуї вшановано в Залі Чемпіонів?",a="Статуї прославляють найшанованіших мучеників і героїв ордену, зокрема ранніх бійців і чемпіонів, як-от Бареана Вествінда, Ормана зі Стромґарда й Феррена Маркуса.",al={"статуї зброярні","статуї зали чемпіонів","статуї в залі героду"}}},fp="24,276,19.544.0,21.418.0,33.236.0,35.179.0,57.256.0,51.167.0"}
P.entries["subzone:scarlet-monastery-cathedral"] = {n="Собор Багряного Монастиря",s="Собор — духовне й військове серце Багряного Монастиря, де міститься внутрішнє святилище Походу. Колись тиха зала молитви для духівництва Лордерону, тепер він — осідок влади Верховної інквізиторки Вайтмейн і Багряного командира Моґрейна, який стережуть найвідданіші фанатики Походу.",h="Собор — духовне й військове серце Багряного Монастиря, де міститься внутрішнє святилище Походу.",kw={"собор","багряний монастир","вайтмейн","моґрейн","каплиця хрестоносця","сади каплиці"},ang={["faction:Alliance"]="Для Альянсу Похід — трагічне, зіпсоване перекручення Святого Світла й гордої спадщини Лордерону, тож командувачі в Саутшорі посилають героїв покласти край цьому божевіллю.",["faction:Horde"]="Собор, що небезпечно близько до Андерсіті, ховає фанатиків, які присяглися повністю винищити Відступників і всіх союзників з Орди, що стоять поруч із ними."},sec={{t="Святилище фанатизму",b="Колись Собор був мирним осередком просвіти й молитви для духівництва Лордерону, але після Третьої війни поринув у божевілля. Коли королівство впало під натиском Погибелі, уцілілі фанатики обернули комплекс на фортецю непримиренної ненависті. За доглянутою обителлю Садів Каплиці лежить велична Каплиця Хрестоносця, де жерці й воїни збираються, віддані своєму хрестовому походу. Усіх чужинців — незалежно від раси чи фракції — вони вважають носіями чуми нежиття, яких треба очистити клинком і святим вогнем."},{t="Верховна інквізиторка та її командир",b="Сили, що стоять у Соборі, підкоряються безпосередньо Багряному командирові Моґрейну, який тримає залогу в залізній дисципліні. Та справжнє серце фанатизму цієї твердині — Верховна інквізиторка Вайтмейн. Грізна володарка Світла, вона завдяки божественній відданості здатна воскрешати полеглих чемпіонів просто в розпалі бою. Удвох із Моґрейном вони утримують внутрішню каплицю від кожного, хто посміє прорватися крізь браму монастиря, — і доводять, що хватка Походу на півночі Лордерону досі смертоносно міцна."}},faq={{q="Для чого потрібен Собор?",a="Це внутрішній оплот і священний престол Багряного Хрестового Походу в Монастирі. Тут найвищі ватажки ордену правлять служби й керують військовими походами по всіх Галявинах Тірісфалю.",al={"призначення собору","навіщо йти в собор","що це за місце"}},{q="Хто очолює тут Багряний Хрестовий Похід?",a="Гарнізоном командує Багряний командир Моґрейн, а духовна влада належить Верховній інквізиторці Вайтмейн — грізній і ревній жриці.",al={"хто бос тут","боси собору","вайтмейн моґрейн"}},{q="Чому двері до Собору замкнені?",a="Важкі ворота крила Собору замкнені, щоб непрохані гості не вдерлися до внутрішнього святилища. Щоб увійти, потрібен Багряний Ключ, який зберігається в крилі Бібліотеки Монастиря.",al={"собор замкнений","як відчинити собор","де ключ"}},{q="Чому хрестоносці нападають на інших живих людей?",a="Доведений до параноїдального божевілля тим, як Погибель знищила Лордерон, Похід вірить, що всі чужинці — носії чуми нежиття. Він не має справ із зовнішніми фракціями й страчує кожного, хто наближається до його твердинь.",al={"чому нападають на альянс","багряний похід злий","чому хрестоносці ворожі"}}},fp="27,313,15.561.0,37.517.1,31.224.0,35.160.0,40.190.0,52.243.0"}
P.entries["subzone:scarlet-monastery-graveyard"] = {n="Кладовище Багряного Монастиря",s="Кладовище Багряного Монастиря — поховальне крило величного релігійного комплексу на північному сході Галявин Тірісфалю. Колись тихе місце спочинку для духівництва й знаті Лордерону, нині воно моторошно занедбане: його заполонили неупокоєні мерці й зіпсована магія полеглого хрестоносця — мага крові Талноса.",h="Кладовище Багряного Монастиря — поховальне крило величного релігійного комплексу на північному сході Галявин...",kw={"кладовище","багряний монастир","маг крові талнос","гробниця честі","покинута обитель","гробовий мох"},ang={["profession:Herbalism"]="Волога осквернена земля Покинутої Обителі — одне з найнадійніших місць на півночі Лордерону, де можна зібрати Гробовий Мох.",["race:Undead"]="Заклиначі й аптекарі Відступників бачать у Кладовищі похмурий доказ лицемірства Походу: фанатики засуджують Відступників, а в їхньому ж підвалі гниє маг крові з нежиті."},sec={{t="Осквернена святиня",b="До Третьої війни цей обгороджений цвинтар був мирним місцем поховання для духівництва Лордерону. Коли Багряний Хрестовий Похід укріпив монастир проти нежиті, його фанатична пильність так і не змогла очистити власні склепи. Нині Кладовище занедбане, і тут кишить нечисть. Неупокоєні духи, неспокійні мерці й незграбні почвари блукають Палатою Спокути та оповитою туманом Покинутою Обителлю. Замість освяченого спочинку мертві знайшли безкінечні муки під байдужим поглядом Походу."},{t="Скверна зсередини",b="У глибині цвинтаря стоїть Гробниця Честі, де гниє найбільша насмішка з догматів Походу — маг крові Талнос. Колись він мав лиху славу в Поході через жорстокі тортури, якими «очищав» новобранців, а потім заразився чумою нежиття й повстав кістяною почварою, що метає стріли тіні й вогонь. Хрестоносці нагорі проповідують повне винищення чуми нежиття — а самі ховають у своїй освяченій землі гнилого полеглого чаклуна."}},faq={{q="Звідки нежить у твердині Багряного Хрестового Походу?",a="Проводом Походу заволодів фанатизм: хрестоносців посилають назовні вбивати живих чужинців і воювати в Тірісфалі. Тож склепи й поховання монастиря цілком занедбані, і приспані рештки чуми та неспокійні духи померлого духовенства безперешкодно повстають.",al={"чому нежить на кладовищі монастиря","нежить багряного монастиря","чому тут привиди"}},{q="Хто такий маг крові Талнос?",a="Талнос колись був садистом-магом Багряного Хрестового Походу, сумно відомим жорстокими тортурами, якими «очищав» новобранців. Він підхопив чуму нежиття й повстав кістяком-жахіттям, що нині править оскверненими склепами Гробниці Честі.",al={"талнос історія","хто такий маг крові талнос","бос кладовища"}},{q="Де в монастирі розташоване крило Кладовища?",a="Увійшовши до Великого Вестибюля Багряного Монастиря, ви побачите вхід до Кладовища — це крайній лівий портал. На відміну від Зброярні й Собору, ключ для нього не потрібен.",al={"де кладовище монастиря","як знайти крило кладовища","які двері до кладовища"}},{q="Що таке Покинута Обитель?",a="Покинута Обитель — сад і цвинтар просто неба між вхідними склепами й Гробницею Честі. Тут повно надгробків, блукаючих гулів і вологої землі, багатої на Гробовий Мох.",al={"покинута обитель","подвір'я кладовища"}}},fp="27,310,19.531.0,22.463.0,57.314.0,25.233.0,57.190.0,29.185.0"}
P.entries["subzone:scarlet-monastery-library"] = {n="Бібліотека Багряного Монастиря",s="Бібліотека — східне крило Багряного Монастиря в Галявинах Тірісфалю, колись присвячене святій науці й духівництву Лордерону. Тепер її стережуть бойові пси й фанатики, а всередині зберігаються прадавні архіви й рідкісні фоліанти, яких палко прагнуть учені й маги обох фракцій.",h="Бібліотека — східне крило Багряного Монастиря в Галявинах Тірісфалю, колись присвячене святій науці й...",kw={"бібліотека","багряний монастир","атенеум","арканіст доан","псар локсі","компендіум полеглих"},ang={["class:Mage"]="Атенеум — обов'язкове місце паломництва для амбітних магів, які шукають прадавніх обрядів сили й хочуть випробувати себе проти руйнівного чаклунства арканіста Доана.",["faction:Alliance"]="У Бібліотеці зберігаються священні записи про полеглих героїв Лордерону й історії титанів, які Зала Дослідників в Айронфорджі відчайдушно хоче вирвати з рук хрестоносців."},sec={{t="Архіви Лордерону",b="До Третьої війни монастир був осередком знань і просвіти для духівництва Лордерону. У східних галереях зберігалися величезні архіви релігійної думки, історичні хроніки й тайнознавчі трактати. Коли Багряний Хрестовий Похід укріпив монастир проти Погибелі, ці сховища лишилися, а тихі зали обернулися на озброєну твердиню. Нині псарі ганяють слідчих псів подвір'ями, а бойові маги патрулюють між полицями, стережучи від чужинців історичні томи, як-от Компендіум Полеглих, і прадавні дослідження про титанів."},{t="Охоронці Атенеуму",b="Щоб прорватися до Бібліотеки, треба пройти повз Псаря Локсі в Обителі Ловчого: його вишколені пси винюхують лазутчиків, які шукають шляху до внутрішніх покоїв. За Галереєю Скарбів лежить Атенеум, яким опікується арканіст Доан. Цей грізний маг, що володіє нищівним вогнем і захисними чарами, працює на самоті й люто боронить накопичені Походом знання від кожного, хто наважиться вдертися в серце комплексу."}},faq={{q="Де в Багряному Монастирі розташована Бібліотека?",a="Увійшовши до Великого Вестибюля комплексу Багряного Монастиря на Галявинах Тірісфалю, до крила Бібліотеки ви потрапите через крайній правий портал.",al={"вхід у бібліотеку","які двері до бібліотеки","як знайти крило бібліотеки"}},{q="Навіщо шукачів пригод посилають до Бібліотеки?",a="Учені, жерці й маги з Альянсу та Орди шукають цінні тексти, що зберігаються в її стінах. Серед найважливіших — Компендіум Полеглих, знання про Титанів, яких шукають історики Айронфорджа, і давні посібники з магії для молодих чарівників.",al={"навіщо йти в бібліотеку","завдання бібліотеки","що в бібліотеці"}},{q="Хто править крилом Бібліотеки?",a="Внутрішнє святилище Бібліотеки, Атенеум, очолює арканіст Доан — могутній багряний чаклун. Зовнішній двір стереже Псар Локсі зі своїми лютими собаками-слідчими.",al={"бос бібліотеки","хто керує бібліотекою","хто очолює бібліотеку"}},{q="Що за Багряний Ключ тут можна знайти?",a="У скриньці в Атенеумі арканіста Доана лежить Багряний Ключ — без нього не відімкнути важкі залізні двері до Зброярні й Собору монастиря.",al={"ключ доана","багряний ключ","де багряний ключ"}}},fp="25,282,21.587.0,26.457.0,50.155.0,40.258.0,27.198.0,35.175.0"}
P.entries["subzone:scarlet-raven-tavern"] = {n="Таверна «Багряний Крук»",s="Таверна «Багряний Крук» — осередок громадського життя й головний заїзд Даркшира, що дає прихисток біля вогнища посеред мороку Сутінколісся. Під орудою Шинкаря Смітса тут збираються змучені місцеві, перехожі шукачі пригод і нажахані мандрівники, що тікають від жахів за межами міста.",h="Таверна «Багряний Крук» — осередок громадського життя й головний заїзд Даркшира, що дає прихисток біля...",kw={"таверна багряний крук","таверна","шинкар смітс","даркшир","сутінколісся","заїзд"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що перетинають південний кордон, «Багряний Крук» — одне з небагатьох безпечних вогнищ і місць відпочинку між Лісом Елвінн і Перевалом Мертвого Вітру.",["profession:Cooking"]="У меню заїзду є місцеві страви на кшталт Сутінкових Крабових Котлет — їх жадають навіть такі зневірені мандрівники, як Тремтій, коли ховаються на цвинтарі."},sec={{t="Тьмяний прихисток",b="Таверна «Багряний Крук», що стоїть неподалік серця Даркшира, підтримує вогонь у своєму вогнищі, хоч вічні сутінки й душать довколишній ліс. Колись тут вирувало життя: Маршал Гаґґард і Вартові Стормвінда заходили на кухоль після патрулів. Нині справи підупали разом із безпекою міста. Шинкар Смітс наливає похмурим, стривоженим відвідувачам, що тулються тут від холоду й страху. І все ж таверна лишається незамінним перехрестям чуток — саме звідси мандрівники починають шукати відповіді на темні явища, що поглинають край."},{t="Таємниці й крадені кухлі",b="Таверна не лише дає прихисток — тут зберігаються частинки кількох таємниць, що поступово розкриваються. Відлюдний мандрівник Тремтій кілька днів винаймав тут кімнату, ночами гарячково строчив у щоденнику, а потім утік із міста, рятуючись від страхітливих Темних Вершників. Давні міські плітки й збережені записи про гостей під цим дахом ведуть і до давно забутих постатей на кшталт Сталвана Містмантла, тож шинок Смітса — перше місце, куди зазирають допитливі слідчі, коли шукають історію неспокійних мерців Сутінколісся."}},faq={{q="Хто тримає Таверну «Багряний Крук»?",a="Господар таверни — Шинкар Смітс. У корчмі є також корчмар та інша прислуга, що обслуговує мандрівників у Даркширі.",al={"корчмар даркшира","хто власник багряного крука","шинкар сміттс"}},{q="Чому в таверні така похмура атмосфера?",a="Прокляття, що нависло над Сутінколіссям, задушило торгові шляхи й до смерті налякало місцевих. Довкола в лісах нишпорять нежить, дикі воргени й тіньові вершники, тож відвідувачі тут — перелякані городяни й відчайдушні найманці, а не безтурботні мандрівники.",al={"чому в багряному крукові похмуро","атмосфера корчми даркшира"}},{q="Чи зупинявся Тремтій у «Багряному Круку»?",a="Тремтій зупинявся в таверні й гарячково записував щось у щоденник, перш ніж утекти з міста. Чому він так учинив — з'ясовується під час розслідування в Сутінколіссі.",al={"кімната тремтія","тремтій таверна","чи жив тремтій тут"}},{q="Як ця таверна пов'язана з Легендою про Сталвана?",a="Старі відвідувачі й давні міські записи, що збереглися в таверні й довкола неї, містять підказки про Сталвана Містмантла, який колись часто бував у містечку, перш ніж його спіткали трагедія й ганьба.",al={"зв'язок зі сталваном","сталван містмантл корчма даркшира"}}},fp="20,330,12.576.0,24.516.1,34.117.0,41.266.0,38.153.0,63.184.0"}
P.entries["subzone:scarlet-watch-post"] = {n="Багряна Сторожова Застава",s="Багряна Сторожова Застава — відособлена сторожова вежа на скелястих пагорбах північно-східних Галявин Тірісфалю, одразу на північ від Багряного Монастиря. Її тримає пильний гарнізон хрестоносців, і єдине її призначення — берегти вразливий північний фланг монастиря від обхідних нападів.",h="Багряна Сторожова Застава — відособлена сторожова вежа на скелястих пагорбах північно-східних Галявин...",kw={"багряна сторожова застава","багряний хрестовий похід","сторожова вежа","багряний монастир","капітан мелраш","тірісфаль"},ang={["faction:Horde"]="Хрестоносці вважають усіх чужинців — живих чи мертвих — зараженими носіями нежиті, тож ця сторожова застава — суто ворожа земля для будь-яких мандрівників Орди, що зважаться на ці пагорби.",["race:Undead"]="Для Відступників Багряний Хрестовий Похід — смертельна загроза просто на порозі Андерсіті; зачистка таких відособлених веж розриває мережу зв'язку фанатиків і убезпечує північний Тірісфаль."},sec={{t="Охорона північного підступу",b="Багряна Сторожова Застава на скелястих висотах за Багряним Монастирем — важливий бастіон раннього попередження для фанатиків унизу. Поки південна дорога до монастирської брами людна й добре укріплена, скелясті кручі вздовж північного узбережжя Тірісфалю дають спокусливий обхідний шлях для диверсантів. Щоб закрити цю сліпу пляму, Багряний Хрестовий Похід тримає цю укріплену кам'яну вежу — одну з кількох застав хрестоносців, розкиданих по Галявинах Тірісфалю. Під суворим командуванням Капітана Мелраша змішаний загін неофітів, передових бійців і побожних братів-ченців невпинно пильнує кручі, щоб ні Погибель, ні Відступники не заскочили орден зі спини."}},faq={{q="Для чого потрібна Багряна Сторожова Застава?",a="Застава захищає Багряний Монастир від обхідного удару. Головний вхід монастиря дивиться на південь, на дороги Тірісфалю, а тил спускається до північних нетрів і вразливий для злагоджених нападів. Застава дає вартовим змогу помітити й перехопити будь-яких зайд, що спробують обійти монастир з півночі.",al={"чому тут багряна сторожова застава","призначення багряної сторожової застави","роль хрестоносців"}},{q="Хто командує Багряною Сторожовою Заставою?",a="Гарнізоном у вежі командує Капітан Мелраш. У його оборонному загоні — особисті охоронці, авангардні бійці, новачки-неофіти й брати-чаклуни.",al={"лідер багряної сторожової застави","хто командує багряною заставою","капітан мелраш"}},{q="Чи пов'язана Багряна Сторожова Застава з іншими вежами Тірісфалю?",a="Так. Це одна з чотирьох окремих застав хрестоносців, що оперізують північ і захід Галявин Тірісфалю. Ці кам'яні вежі утворюють оборонний периметр, щоб стежити за Погибеллю й стримувати поширення Відступників з Андерсіті.",al={"вежі тіріфалю","застави хрестоносців тіріфаль","інші багряні вежі"}}},fp="18,297,30.721.0,46.327.0,36.192.0,66.241.0"}
P.entries["subzone:scholomance"] = {n="Сколомансія",s="Сколомансія, схована глибоко в криптах під Каер Дарроу, — найголовніша академія темних мистецтв і некромантії Погибелі. Тут смертні й нежить разом вивчають чуму нежиття та ліплення плоті під садистським наставництвом Темного Майстра Ґандлінґа й пильним оком ліча Раса Фроствіспера.",h="Сколомансія, схована глибоко в криптах під Каер Дарроу, — найголовніша академія темних мистецтв і некромантії...",kw={"сколомансія","каер дарроу","ґандлінґ","рас фроствіспер","барови","некромантія","кел'тузад"},ang={["class:Mage"]="Викривлені уроки Сколомансії — цілковите збочення магічної науки: тут дослідження теорії магії поступилися місцем гнилі, тіні й нечестивому оскверненню.",["race:Undead"]="Заклиначі-Відступники знають Сколомансію надто добре й дивляться на неї з холодною відразою: чимало найпідліших методів поневолення й біологічної війни Погибелі відточили саме в цих класах."},sec={{t="Згубна угода",b="До Третьої війни Каер Дарроу був гордим осідком дому Баровів — багатого аристократичного роду, якому належали розлогі землі по всьому Лордерону, зокрема Брілл, Таррен Мілл і Саутшор. Боячись утратити статки й страшачись смерті, Барови піддалися спокусливим обіцянкам Кел'Тузада про вічне життя. Вони віддали Культу Проклятих свою фортецю й родові катакомби, а культ віддячив вельможам тим, що перебив їх і перетворив розлогі крипти на таємний вишкільний табір некромантів."},{t="Школа Некромантії",b="Під моторошними наземними руїнами Каер Дарроу вирує справжня кузня Погибелі. У цих вогких залах випробовували на живих слугах перші штами чуми й зшивали докупи перших потворних гидот. Нині сюди злітаються смертні послушники, щоб удосконалити владу над темною магією під наглядом директора — Темного Майстра Ґандлінґа — та крижаного вартового Раса Фроствіспера, а неупокоєні рештки роду Баровів навіки мучаться в цих стінах."}},faq={{q="Що таке Сколомансія?",a="Сколомансія — таємна академія некромантії, якою керують Культ Проклятих і Погибель. Вона розташована під острівною фортецею Каер Дарроу й навчає смертних некромантів, дослідників чуми й майстрів плоті.",al={"що це за місце","лор сколомансії","поясніть сколомансію"}},{q="Кому належать Каер Дарроу й склепи?",a="Спершу фортеця належала Дому Баровів — одній із найзаможніших шляхетних родин Лордерона. Прагнучи безсмертя, вони віддали своє родове гніздо Кел'Тузаду, але їх убили й підняли як нежить-невільників у їхніх же власних залах.",al={"кому це належало","дім баровів","родина баровів"}},{q="Хто тепер керує академією?",a="Темний Майстер Ґандлінґ — підступний смертний директор школи, що наглядає за навчанням і муками. Крім того, від імені Погибелі це місце пильно стереже ліч Рас Фроствіспер.",al={"хто бос","хто керує сколомансією","директор"}},{q="Які жахіття тут створили?",a="Сколомансія була першою кузнею Культу Проклятих. Сектанти випробовували на слугах родини Баровів ранні різновиди чуми нежиття й зшивали в її лабораторіях перших гидот Погибелі.",al={"що тут створили","експерименти сколомансії","поганьби"}}},fp="11,304,14.507.0,24.467.1,20.241.0,36.242.0,25.195.0,33.243.0"}
P.entries["subzone:scholomance-classic"] = {n="Сколомансія (класична)",s="Сколомансія — підземна академія некромантії, схована в криптах під Каер Дарроу в Західних Чумних Землях. Її заснували Кел'Тузад і Культ Проклятих, і тепер це найголовніший вишкільний центр Погибелі для смертних заклиначів, які прагнуть опанувати смерть.",h="Сколомансія — підземна академія некромантії, схована в криптах під Каер Дарроу в Західних Чумних Землях.",kw={"сколомансія","каер дарроу","кел'тузад","культ проклятих","рас фроствіспер","ґандлінґ","рейвеніан"},ang={["class:Mage"]="Сколомансія — потворне перекручення вченої традиції Даларана: ось що буває, коли знання Кірін-Тору цілком віддають некромантії й тліну.",["class:Paladin"]="Для лицарів Срібної Длані очистити осквернені зали під Каер Дарроу — нагальний обов'язок: це удар просто по джерелу, з якого Погибель черпає смертних ватажків."},sec={{t="Школа в гробницях",b="Ще до того, як Третя війна спустошила Лордерон, архімаг-ренегат Кел'Тузад шукав прибічників для свого Культу Проклятих. Щедрих покровителів він знайшов у багатому роді Баровів, володарях Каер Дарроу, які віддали свої землі й крипти в обмін на обіцяне безсмертя. Натомість культ вирізав їх і підняв як жахливу нежить. Під зруйнованою фортецею культисти перебудували давні катакомби, що збереглися ще з часів Аратору, на академію темних мистецтв. Тут, подалі від пильних очей, смертні послушники вчаться творити чуму, зв'язувати душі й ліпити плоть, відточуючи ту мерзенну магію, що розтрощила Лордерон."},{t="Ліч і директор",b="Хоча Кел'Тузад тепер керує справами Погибелі з висоти, школа працює на повну силу. Безсмертний ліч Рас Фроствіспер стереже школу в ім'я Погибелі, а смертний некромант Темний Майстер Ґандлінґ є її директором і наставляє честолюбних чаклунів у жахливих дослідах. Учнів, які виявляють слабкість, скидають у катакомби на поживу Рейвеніану — ненажерному мертвякові, що чатує в нижніх склепах."}},faq={{q="Що таке Сколомансія?",a="Сколомансія — таємна академія некромантії під орудою Культу Проклятих. Розташована в глибоких склепах під острівною фортецею Каер Дарроу, вона навчає смертних чаклунів темних мистецтв Погибелі.",al={"що це за місце","лор сколомансії","поясніть сколомансію"}},{q="Хто тепер править Сколомансією?",a="Від імені Погибелі за фортецею наглядає ліч Рас Фроствіспер, а справами смертних і навчанням керує Темний Майстер Ґандлінґ — безжальний директор школи.",al={"хто керує сколомансією","хто головний","бос сколомансії"}},{q="Як Погибель заволоділа Каер Дарроу?",a="Після Другої війни фортецею володіла шляхетна родина Баровів. Спокушені обіцянками Кел'Тузада про вічне життя, вони переписали своє родове гніздо й склепи на Культ Проклятих. Культ «дотримав» угоди, вирізавши Баровів і піднявши їх як нежить.",al={"історія баровів","хто володів кер дарроу","як культ захопив сколомансію"}},{q="Чому школа замкнена?",a="Величезні залізні ворота запечатали, щоб захистити дослідження академії й закличників від зайд. Щоб відчинити двері, потрібна Відмичка, яку виготовляють за складним обрядом, що охоплює всі Чумні Землі.",al={"двері сколомансії замкнені","як зайти в сколомансію","скелетний ключ сколомансії"}}},fp="21,270,21.603.0,19.465.0,20.211.0,26.179.0,40.271.0,25.208.0"}
P.entries["subzone:screaming-gully"] = {n="Волаючий Яр",s="Волаючий Яр — перша розлога підземна печера одразу за входом до Печер Стогонів. Залита протиприродним сяйвом грибів і мілкою водою, вона править за зовнішній оплот спотворених Друїдів Ікла та їхніх мутованих звірів.",h="Волаючий Яр — перша розлога підземна печера одразу за входом до Печер Стогонів.",kw={"волаючий яр","печери стогонів","леді анакондра","друїди ікла","девіантні раптори","креш"},ang={["class:Druid"]="Для друїдів Кола Кенарія Волаючий Яр — болюче видовище: тут їхні занепалі побратими, що зійшли зі шляху кігтя й неба й віддалися зміїній порчі."},sec={{t="Поріг Жахіття",b="Ступивши за поріг Печер Стогонів, мандрівник одразу потрапляє у Волаючий Яр — відлунну прірву, де вітер стогне в підземних розколинах. Тут, далеко від посушливих Пусток нагорі, яр заріс вологими хащами, оповитий задушливим туманом і повний лютих звірів, спотворених Смарагдовим Жахіттям. Над залою пильнує Володарка іклів Леді Анакондра в оточенні послушників Друїдів Ікла та лютих девіантних рапторів, а мілкими протоками внизу патрулюють прадавні кусючі черепахи на кшталт Креша."}},faq={{q="Де розташований Волаючий Яр?",a="Волаючий Яр — перша велика зала, до якої ви потрапляєте, щойно пройдете крізь портал до Печер Стогонів під північними Пустками.",al={"розташування волаючого яру","де волаючий яр","як знайти волаючий яр"}},{q="Чому він зветься Волаючим Яром?",a="Печери Стогонів дістали свою назву через виття й стогін підземної пари й вітрів, що виходять крізь скельні розколини, а цей широкий вхідний провал приймає на себе найгучнішу луну цих криків.",al={"чому волаючий яр","походження назви волаючого яру"}},{q="Хто править Волаючим Яром?",a="Залою опікується Леді Анакондра — одна з головних Володарок Ікла, що разом із Наралексом піддалася скверні Смарагдового Жахіття.",al={"бос волаючого яру","хто у волаючому ярі","лідер волаючого яру"}},{q="Хто блукає цією залою?",a="У яру живуть девіантні раптори, зіпсовані Друїди Ікла й блукаючі водяні істоти — зокрема давня черепаха Креш, що бродить затопленим дном.",al={"моби волаючого яру","вороги волаючого яру"}}},fp="15,265,26.511.0,37.165.0,37.209.0,35.145.0,33.162.0"}
P.entries["subzone:scuttle-coast"] = {n="Дріботливе Узбережжя",s="Дріботливе Узбережжя — побитий хвилями східний берег Дуротару між Гострим Пагорбом і Фортецею Тіраґард. Скелястий пляж усіяний затонулими уламками флоту Кул Тірасу під проводом Адмірала Дейліна Праудмура, тож це жваве місце для збирачів Орди й невідступне нагадування про недавню морську війну.",h="Дріботливе Узбережжя — побитий хвилями східний берег Дуротару між Гострим Пагорбом і Фортецею Тіраґард.",kw={"дріботливе узбережжя","уламки","кораблі","кул тірас","праудмур","краби","макрури","дуротар"},ang={["faction:Horde"]="Розбиті корпуси, якими всіяний цей пляж, стоять суворими пам'ятниками обороні Дуротару від загарбницького флоту Дейліна Праудмура.",["profession:Engineering"]="У затоплених трюмах Альянсу вздовж берега лишилися покинуті гномські пристрої, металобрухт і хитромудрі механізми, що так і просяться на розбирання й вивчення."},sec={{t="Уламки флоту",b="Дріботливе Узбережжя, що тягнеться вздовж східного краю Дуротару до Великого Моря, набуло свого похмурого вигляду під час вторгнення Великого Адмірала Дейліна Праудмура. Коли флот Кул Тірасу напав на молоду державу Дуротар, люті бої з Ордою загнали чимало людських кораблів на зубчасті мілини й розтрощили їх на тріски. Нині берег завалений порослими мушлями колодами, поламаним такелажем і врятованими бочками з вантажем. Для сусідніх таборів Гострого Пагорба узбережжя — водночас і невідступна загроза безпеці, і цінне джерело віднайдених припасів та покинутих механізмів Альянсу."},{t="Збирачі та припливи",b="Назва Дріботливого Узбережжя нагадує не лише про затоплені кораблі, навмисне пущені на дно чи посаджені на мілину під час боїв, а й про рої крабів та макрур, які порпаються в гниючому мотлосі. Хоч прибережна звірина й небезпечні припливи відлякують випадкових мандрівників, збирачі Орди час від часу прочісують уламки, щоб дістати цінне спорядження, зокрема гномські технічні деталі, покинуті в трюмах затонулих кораблів."}},faq={{q="Звідки взялися всі ці корабельні уламки?",a="Розтрощені кораблі належали флоту Кул Тірасу під командуванням Великого Адмірала Даліна Праудмура. Вони розбилися об скелясті мілини Дуротару під час невдалого військового походу адмірала проти щойно заснованої Орди.",al={"чому тут кораблі","чиї розбиті кораблі","затонулі кораблі дуротару"}},{q="Чому воно зветься Дріботливим Узбережжям?",a="Назва має подвійне значення. Вона натякає і на бойові кораблі, що пішли на дно вздовж узбережжя під час морських боїв, і на численних макрур та крабів, що дрібно снують скелястими пісками.",al={"чому дріботливе узбережжя","походження назви дріботливого узбережжя"}},{q="Що шукає Орда на узбережжі?",a="Розвідники й збирачі Орди обшукують розбиті трюми, шукаючи придатні інструменти, припаси й кинуті гномські механізми, які лишили сили Альянсу.",al={"що орки рятують","орда рятує дріботливе узбережжя"}},{q="Чи безпечно подорожувати Дріботливим Узбережжям?",a="Ні. Окрім підступних хвиль і гострих скель, у прибої нишпорять ворожі прибережні істоти на кшталт макрур, а трохи на південь, у Фортеці Тіраґард, окопалися озброєні вцілілі з Кул Тірасу.",al={"небезпеки дріботливого узбережжя","чи небезпечне дріботливе узбережжя"}}},fp="13,315,21.634.0,20.450.0,41.229.0,35.198.0,46.153.0,36.187.0"}
P.entries["subzone:sea-of-cinders"] = {n="Море Жарин",s="Море Жарин — простір випаленої, обвітреної землі в південній частині Палючої Ущелини, просто на північ від Гори Блекрок. Стихійний жар і безупинні пориви вітру сплюндрували цю рівнину: з неї раз у раз вириваються попіл і жарини, тож у цьому задушливому мертвому краї мало що здатне вижити.",h="Море Жарин — простір випаленої, обвітреної землі в південній частині Палючої Ущелини, просто на північ від...",kw={"море жарин","палюча ущелина","гора блекрок","рагнарос","попіл","жарини"},ang={["profession:Mining"]="Нестійкий, потрісканий від жару камінь біля підніжжя Гори Блекрок часто відкриває багаті поклади руди й жили темного заліза — для тих, кому стане сміливості шукати їх серед летючого попелу.",["race:Dwarf"]="Для дворфів Бронзбірда й Вайлдгаммерів мандрівка цими палаючими пустелями — похмуре нагадування про безумство Тауріссана й темні сили, що розтрощили Гори Редріджу."},sec={{t="Пустеля жарин",b="Море Жарин, що простяглося між скелястими урвищами Палючої Ущелини й грізною громадою Гори Блекрок, дістало свою назву від задушливого серпанку з пилу й палючого піску, який безупинно мете його рівнинами. Коли століття тому Володаря вогню Рагнароса викликали у смертний світ, страшний струс розколов Гори Редріджу й обернув довколишній край на суху купу шлаку. Море Жарин — один із найбезплідніших слідів того катаклізму: непридатна для життя рівнина, де сама земля не хоче охолонути."},{t="Небезпека під схилами",b="Море Жарин межує з північним підступом до Гори Блекрок, тож мандрівникам і збирачам часто нема іншого вибору, як перетинати ці пекучі рівнини. Вітри тут здіймають густі хмари сліпучого попелу, які ховають раптові розколини, стихійних жахіть і бродячих хижаків, звиклих до палючої спеки. Ворожа природа, а ще дворфи Темного Заліза, що вважають цей край своїм, — тож будь-який перехід через жарини вимагає пильності й поспіху."}},faq={{q="Що таке Море Жарин?",a="Це безплідна, вкрита попелом рівнина на півдні Палючої Ущелини, під самим північним схилом Гори Блекрок. Її вкриває тліюча земля й летючі іскри.",al={"що таке море жарин","лор моря жарин","де море жарин"}},{q="Чому земля тут безперестанку горить?",a="Століття тому цей край геть спустошило, коли чаклун-тан Тауріссан під час Війни Трьох Молотів викликав Володаря вогню Рагнароса. Нищівне виверження розпекло землю й розтрощило гори, і рівнини досі тліють.",al={"чому все горить","чому тут жарини","чому земля димить"}},{q="Чи живе тут хтось?",a="У самому Морі Жарин немає жодного організованого поселення. Задушлива спека, погане повітря й брак води унеможливлюють постійне життя, тож тут лише блукають звірі, вогняні елементалі й патрулі, пов'язані з Горою Блекрок.",al={"хто тут живе","мешканці моря жарин","поселення"}},{q="Чим небезпечні мандри цими краями?",a="Окрім ворожих звірів і дворфів Темного Заліза, що чатують біля гори, смертельне саме довкілля. Повітря густе від сліпучої сажі й палючого попелу, а пласку землю всюди прорізають глибокі гарячі розколини.",al={"чи безпечно","небезпеки моря жарин"}}},fp="14,313,21.560.0,24.462.0,27.182.0,37.270.0,22.272.0,44.212.0"}
P.entries["subzone:sentinel-hill"] = {n="Сентінел Гілл",s="Сентінел Гілл — головна твердиня Альянсу у Вестфолі й командний центр Народного ополчення. Довкола — зарослі поля, гноли-мародери й ворожі розбійники, тож цей укріплений пагорб — єдиний надійний оплот для законослухняних мешканців краю.",h="Сентінел Гілл — головна твердиня Альянсу у Вестфолі й командний центр Народного ополчення.",kw={"сентінел гілл","вестфол","народне ополчення","ґраян стаутмантл","вежа вартових","альянс"},ang={["faction:Alliance"]="Сентінел Гілл — ваша єдина укріплена застава й осередок постачання у Вестфолі, опора Альянсу проти розбійників і грабіжників.",["race:Human"]="Те, що фермерам Вестфолу довелося самим збирати тут ополчення, показує, як глибоко загрузло королівство в кризі, поки трон стоїть порожній."},sec={{t="Твердиня серед пилу",b="Сентінел Гілл височіє на узвишші в центрі Вестфолу й править за життєво важливий прихисток на беззаконних землях. Тут є таверна, схожа на казарму, гніздо грифонів, звідки летять до Стормвінда й далі, кузня та лісопилка, а над усім панує велична Вежа Вартових. Довколишні землі дісталися розбійникам і хижим звірам, але табір утримує хиткий периметр, де мандрівники, знесилені фермери й новобранці можуть перевести подих під пильним оком досвідчених захисників."},{t="Серце ополчення",b="Королівська армія застрягла в Стормвінді й не може виділити вояків на захист віддалених земель, тож Ґраян Стаутмантл заснував Народне ополчення просто на цьому пагорбі. Звідси добровольці висилають розвідників, завдають ударів по гнолах Річколапів і розслідують організований розбій, що шматує покинуті хутори Вестфолу. Сентінел Гілл — не розкішна фортеця й не затишний сховок, а робочий табір на передовій, сповнений рішучості повернути колишню житницю королівства."}},faq={{q="Чому Стормвінд не прислав воїнів боронити Сентінел Гілл?",a="Король Варіан Рінн зник, сили королівства розпорошені, тож регентство Стормвінда здебільшого покинуло західні провінції напризволяще. Місцеві мешканці й ветерани мусили самі створити Народне ополчення, щоб утримати Сентінел Гілл і захистити те, що лишилося від Вестфолу.",al={"чому немає стормвіндської варти","де армія стормвінда","чому тут ополчення"}},{q="Хто очолює Сентінел Гілл?",a="Ґраян Стаутмантл командує Народним ополченням біля підніжжя Вежі Вартових. Він організовує місцеву оборону, збирає відомості про довколишні загрози й спрямовує заїжджих шукачів пригод проти гнолів і грабіжників, що підступають до поселення.",al={"хто керує сентінел гіллом","командир сентінел гілла","ґріан стаутмантл"}},{q="Що зараз загрожує пагорбу?",a="На табір постійно тиснуть агресивні гноли Річколапів із західних рівнин, а ще підступний злагоджений саботаж Братства Дефіас, що ховається на покинутих фермах.",al={"що нападає на сентінел гілл","вороги сентінел гілла","хто нападає"}},{q="Які послуги є тут для мандрівників?",a="Сентінел Гілл має все, що потрібно на прикордонні: розпорядника грифонів із польотами до Стормвінда й інших застав Альянсу, корчмаря, поштову скриньку, крамарів і ремонт біля місцевої кузні.",al={"послуги сентінел гілла","політ сентінел гілл","чи є тут корчма"}}},fp="13,276,21.516.0,20.514.0,59.292.0,34.253.0,40.211.0,47.234.0"}
P.entries["subzone:sentinel-tower"] = {n="Вежа Вартових",s="Вежа Вартових вінчає вершину Сентінел Гілла — це головний оглядовий пункт і штаб захисників Вестфолу. Звідси Ґраян Стаутмантл і Народне ополчення відчайдушно обороняються від бандитів, гнолів і дедалі темнішої тіні Братства Дефіас.",h="Вежа Вартових вінчає вершину Сентінел Гілла — це головний оглядовий пункт і штаб захисників Вестфолу.",kw={"вежа вартових","сентінел гілл","ґраян стаутмантл","народне ополчення","вестфол"},ang={["faction:Alliance"]="Вежа Вартових — утілення стійкості простих підданих Альянсу, що б'ються за рідну землю, поки знатні лорди в Стормвінді заплющують на це очі.",["race:Human"]="Для людей королівства ця вежа — болісне нагадування: хліборобська житниця Стормвінда ледве тримається проти заколоту, що виріс на власному ґрунті."},sec={{t="Варта над Диким Заходом",b="Вежа Вартових, зведена на гребені Сентінел Гілла, — військове серце неспокійного Вестфолу. Офіційна армія Стормвінда здебільшого відсутня й допомоги не дає, тож місцеві добровольці й ветерани об'єдналися, щоб звести центральний редут. Із кам'яної вежі дозорці бачать усю курну рівнину — від покинутих гарбузових грядок до туманних берегів — і вчасно попереджають, коли на дорогах з'являються розбійники чи загони гнолів."},{t="Штаб ополчення",b="Вежа — командний пункт Ґраяна Стаутмантла й осередок місцевого проводу. Довкола — нашвидкуруч зведені укріплення, поранені біженці й утомлені вояки, тож вона водночас править і за штаб, і за притулок для хуторян, вигнаних зі своїх земель. Тут по крихтах збирають відомості про Братство Дефіас і гуртують добровольців для злагоджених ударів по синдикату, який задушив цей край."}},faq={{q="Хто керує у Вежі Вартових?",a="З вежі діями керує Ґраян Стаутмантл. Як очільник Народного ополчення, він організовує захист фермерів Вестфолу, що лишилися без домівок, і набирає охочих шукачів пригод.",al={"лідер вежі вартових","хто керує вежею вартових","хто керує вежею"}},{q="Чому вежа така важлива для Вестфолу?",a="Це єдиний укріплений гарнізон і спостережний пост, що лишився на центральних рівнинах. Стормвінд майже не захищає Вестфол, тож вежа — останній організований оплот порядку й безпеки для біженців у краї.",al={"чому вежа вартових важлива","призначення вежі вартових"}},{q="Хто живе у вежі й довкола неї?",a="Тут ви побачите офіцерів ополчення, вартових на чатах, інтендантів і родини фермерів, що покинули свої зруйновані землі й шукають прихистку під її міцними кам'яними мурами.",al={"хто у вежі вартових","мешканці вежі вартових"}},{q="За якими загрозами стежать із вежі?",a="Вартові стежать за пересуваннями гнолів Річколапів, за мурлоками, що заповзають углиб суходолу з узбережжя, а понад усе — за грабіжниками й розбійниками з Братства Дефіас.",al={"вороги вежі вартових","від чого стереже вежа"}}},fp="14,299,24.456.0,27.450.0,35.196.0,42.229.0,34.188.0,40.185.0"}
P.entries["subzone:sentry-point"] = {n="Дозорний Мис",s="Дозорний Мис — людська сторожова вежа на материковому краю Багна Пилоброду, що стереже насипний міст до Острова Терамор. Її утримують сили Терамору, стежачи за всіма, хто в'їжджає до острівної цитаделі Леді Джайни Праудмур і виїжджає з неї.",h="Дозорний Мис — людська сторожова вежа на материковому краю Багна Пилоброду, що стереже насипний міст до...",kw={"дозорний мис","острів терамор","багно пилоброду","сторожова вежа","міст","терамор"},ang={["faction:Alliance"]="Для мандрівників, що прибувають із небезпечних трясовин Багна Пилоброду, Дозорний Мис — гостинний поріг безпеки Острова Терамор.",["faction:Horde"]="Вежа — суворе нагадування про військову присутність Терамору на материку Калімдору; її пильно охороняють від будь-яких розвідників Орди."},sec={{t="Брама Терамору",b="Дозорний Мис, що стоїть на західному кінці довгого мосту між Островом Терамор і підступними болотами Багна Пилоброду, — перша лінія оборони твердині на материку. Кам'яна розвідувальна вежа пильнує болотяну дорогу, щоб ні ворожі болотяні звірі, ні мандрівні таурени Ґрімтотем, ні рейдери Орди не могли непомітно наблизитися до острівного міста."}},faq={{q="Для чого потрібен Дозорний Мис?",a="Це пост раннього попередження й прикордонний пункт Острова Терамор. Вартові тут стежать за рухом на болотяній дорозі й попереджають міську варту про загрози, що наближаються.",al={"призначення дозорного мису","що це за вежа","чому тут дозорний мис"}},{q="Хто тримає цю заставу?",a="На заставі несе службу й утримує її Варта Терамору під командуванням Леді Джайни Праудмур та її офіцерів.",al={"хто володіє дозорним мисом","чи дозорний мис альянсу","сторожова вежа терамору"}},{q="Чи безпечний Дозорний Мис для мандрівників з Орди?",a="Ні. Хоча Леді Джайна Праудмур прагне миру з Ордою, вартові на цій заставі охороняють землі Альянсу й одразу нападуть на членів Орди, що вдеруться сюди.",al={"чи може орда на дозорний мис","чи дружній дозорний мис до орди"}}},fp="12,269,22.378.0,30.193.0,26.140.0,41.190.0"}
P.entries["subzone:sepulcher"] = {n="Гробниця",s="Гробниця — головне поселення й твердиня Відступників у Срібноліссі. Колись звичайне лордеронське кладовище й склеп над західним узбережжям, тепер це укріплений прихисток Орди від загроз довкола.",h="Гробниця — головне поселення й твердиня Відступників у Срібноліссі.",kw={"гробниця","відступники","орда","срібнолісся","кладовище"},ang={["faction:Horde"]="Для кожного мандрівника Орди, що прямує на південь із Галявин Тірісфалю, Гробниця — єдиний надійний прихисток на багато миль довкола, де можна полагодити спорядження й вирушити в політ.",["race:Undead"]="Гробниця — плацдарм боротьби Відступників за приборкання Срібнолісся: звідси керують діями проти вірних Погибелі недобитків, решток Кірін-Тору й диких воргенів."},sec={{t="Святилище в тумані",b="Гробниця, що стоїть на пагорбах над узбережжям Лордерона, спершу була тихим кладовищем і склепом при західній дорозі. Після Третьої війни щойно звільнені Відступники пристосували давнє кам'яне склепіння та його землі під важливу заставу. Оточена ворожими силами з усіх боків — дикими воргенами на півдні, недобитками Погибелі на сході й чарівниками Кірін-Тору, що стежать з Амбермілла, — Гробниця дає мандрівникам Срібнолісся рідкісний прихисток, припаси й командування."}},faq={{q="Чим була Гробниця до приходу Відступників?",a="До Третьої війни й падіння королівства Лордерон це був звичайний придорожній цвинтар і кам'яний склеп, де місцеві селяни ховали своїх померлих.",al={"історія гробниці","чим була гробниця","хто збудував гробницю"}},{q="Чому Гробниця така важлива для Відступників?",a="Це єдиний укріплений осередок Відступників у Срібноліссі. З цього центрального місця розвідники й командири Відступників можуть стежити за магами Даларану, що підступають, за рештками Погибелі й за звірячою загрозою воргенів, що поширюється біля Фортеці Шадовфенг.",al={"чому гробниця важлива","відступники в сілверпайні","роль гробниці"}},{q="Чи раді тут мандрівникам з інших рас Орди?",a="Так. Хоча базою керують і живуть у ній лише Відступники — вартові смерті, крамарі й аптекарі, — це офіційний прихисток Орди, де можуть відпочити й поторгувати орки, тролі й таурени, що проходять краєм.",al={"чи можуть орки в гробницю","чи гробниця дружня до орди","орда в гробниці"}},{q="Що загрожує Гробниці?",a="Поселення затиснуте ворожими силами: на сході блукає Погибель, на південному сході Кірін-Тор тримає Амбермілл, а на півдні лісами нишпорять люті воргени.",al={"загрози гробниці","вороги сілверпайну","що нападає на гробницю"}}},fp="9,261,20.549.0,52.153.0,46.254.0,58.231.0,36.178.0"}
P.entries["subzone:serpent-s-coil"] = {n="Кільця Змія",s="Кільця Змія — звивиста мережа печер і спалених таборів у східних хребтах Спустошених Земель. Ця місцина, всіяна обгорілими орчими спорудами, що лишилися з давніх воєн, править за відлюдний прихисток для темних культистів і самотніх дослідників.",h="Кільця Змія — звивиста мережа печер і спалених таборів у східних хребтах Спустошених Земель.",kw={"кільця змія","спустошені землі","культисти","аллістарж","присяжні тіні","печери"},ang={["class:Warlock"]="Присяжні Тіні в Кільцях Змія правлять обряди підкорення й переховують могутні артефакти, тож печера — похмуре відображення безрозсудного вивчення демонів.",["race:Gnome"]="Самотній гном-дослідник глибоко в печері, що кишить культистами, — яскравий приклад того, на які безстрашні чи безрозсудні кроки готовий гномський розум, аби розгадати заборонену магію."},sec={{t="Лабіринт попелу й каменю",b="Звивиста стежка й печери Кілець Змія, вирубані в зубчастих східних скелях Спустошених Земель, в'ються повз зруйновані орчі хижі, що пам'ятають Першу й Другу війни. У тунелях ховаються не прості звірі, а гуртки культистів Присяжних Тіні та послідовників темних мистецтв, яких вабить залишкова демонічна енергія, що просякла червоні пустирі. Глибоко в звивистих порожнинах дивні постаті віддаються власним одержимостям далеко від пильних очей Замку Незерґард."},{t="Лігво культистів",b="Печери давно слугують плацдармом для культистів Архімага Аллістаржа, які шанують демонічних владик і експериментують зі зловісними артефактами на кшталт Амулета Аллістаржа. Навіть коли влада їхнього господаря слабне, вірні фанатики Присяжних Тіні й далі патрулюють закрути печер, правлять обряди на службі Кіріта Проклятого й ховаються за обгорілими барикадами."}},faq={{q="Що таке Кільця Змія?",a="Кільця Змія — звивиста мережа печер і каньйон на сході Спустошених Земель, відомі обвугленими оркськими руїнами й зловісними мешканцями.",al={"кільця змія","що це за печера","кільця змія спустошені землі"}},{q="Звідки тут старі оркські споруди?",a="Табірні споруди сягають часів Першої й Другої воєн, коли Стара Орда пройшла крізь сусідній Темний Портал і укріпила довколишній край, доки не зазнала поразки.",al={"чому тут орківські руїни","орківські споруди спустошених земель","спалені хатини"}},{q="Хто живе в Кільцях Змія?",a="У печерах засіли сектанти-Тіньоприсяжні, що служать Архімагові Аллістаржу й темним силам, а також поодинокі дослідники незвичайної магії Спустошених Земель.",al={"хто тут","вороги кілець змія","хто контролює печеру"}},{q="Чому гном з Альянсу отаборився в печері, де довкола сама небезпека?",a="Касим Шарім проводить глибоко в печері власні небезпечні магічні дослідження: він ризикує поруч із сектантами, щоб вивчати могутні демонічні артефакти, розкидані по цих землях.",al={"гном у печері","касім шарім","чому тут касім"}}},fp="14,274,28.474.0,16.369.1,23.148.0,38.180.0,32.177.0,73.188.0"}
P.entries["subzone:sewers"] = {n="Каналізація",s="Каналізація — розлога підземна дренажна мережа, що дає ще один вхід просто до Андерсіті. Вона пролягає під пагорбами на захід від зруйнованого палацу Лордерона й дає змогу приборкувачам кажанів і обережним мандрівникам оминути хиткі підйомники, що спускаються з тронної зали.",h="Каналізація — розлога підземна дренажна мережа, що дає ще один вхід просто до Андерсіті.",kw={"каналізація","андерсіті","кажани","тірісфаль","лордерон","таємний вхід"},ang={["faction:Alliance"]="Кожен, хто достатньо безрозсудний чи відважний, щоб штурмувати столицю Відступників, знає: каналізація — єдиний потаємний шлях повз добре захищені руїни на поверхні.",["race:Undead"]="Для Відступників каналізація — важлива життєва артерія й повітряний коридор, що пов'язує Андерсіті з рештою Лордерона, не створюючи заторів біля підйомників у дворі."},sec={{t="Чорний хід до катакомб",b="До того як чума знищила Лордерон, ці кам'яні водостоки були звичайною каналізацією королівської столиці. Та у Відступників Сильвани Віндраннер стічні тунелі стали частиною зовнішньої оборони Андерсіті. Прохід виходить на поверхню на захід від руїн, поблизу спірної Багряної Вартової Вежі в Галявинах Тірісфалю, і веде рівним, прямим схилом усередину. Приборкувачі кажанів Відступників використовують цей печерний хід, щоб швидко переносити вершників до підземних кілець, цілком оминаючи повільні підйомники-клітки. Оскільки він обходить добре укріплені двори на поверхні, це небезпечне вразливе місце, яке ворожі лазутчики постійно намагаються використати."}},faq={{q="Куди виходить тунель каналізації?",a="Канал виходить на пологі пагорби Галявин Тірісфалю, трохи на захід від головної брами Руїн Лордерона. Неподалік — Багряна сторожова вежа, що дивиться на озеро.",al={"куди виходить каналізація","вихід з каналізації підміської","чорний вхід каналізації"}},{q="Навіщо комусь користуватися каналізацією замість головного входу?",a="Головний шлях до Андерсіті — це залізні клітки-підйомники з палацових руїн, а вони повільні й небезпечні під час нападу. Каналізація — прямий похилий шлях, яким літають кажани Відступників і яким можна швидко вибратися, не чекаючи на підйомник.",al={"чому каналізація","каналізація проти ліфтів","чорний хід підміської"}},{q="Чи безпечна каналізація від нападників з Альянсу?",a="Навряд. Вона оминає укріплену браму й тронну залу Лордерона, тож відчайдушні розвідники й ударні загони Альянсу найохочіше обирають саме її, щоб прокрастися просто до столиці Відступників.",al={"чи альянс нападе на каналізацію","чи охороняється каналізація","оборона каналізації підміської"}}},fp="6,312,29.696.0,41.190.0,61.273.0,40.221.0"}
P.entries["subzone:shadow-grave"] = {n="Тіньова Могила",s="Тіньова Могила — кам'яний склеп на вершині похилого цвинтаря над Похоронним Подзвоном у Галявинах Тірісфалю. Це фізична точка пробудження, де щойно звільнені Відступники скидають заціпеніння смерті й послаблену владу, яку над ними мав Король-Ліч.",h="Тіньова Могила — кам'яний склеп на вершині похилого цвинтаря над Похоронним Подзвоном у Галявинах Тірісфалю.",kw={"тіньова могила","склеп","пробудження","похоронний подзвін","гробар мордо","відступники","тірісфаль"},ang={["race:Undead"]="Кожен шукач пригод з-поміж Відступників починає свою путь на холодних кам'яних плитах цього склепу, розплющуючи очі на похмуру дійсність нежиття й вільної волі."},sec={{t="Колиска Відступників",b="Тіньова Могила, схована в скелястих передгір'ях за Могилами Похоронного Подзвону, — простий кам'яний мавзолей із надзвичайним призначенням. У його вологих склепіннях трупи, підняті для безтямної служби Погибелі, поступово пробуджуються до вільної волі. Під пильним оком доглядачів на кшталт Гробаря Мордо ці щойно звільнені мерці підводяться з кам'яних плит і роблять перші тремтливі кроки у світ, що їх зневажає, рушаючи стежкою вниз до Похоронного Подзвону, щоб присягнути Королеві Баньші."}},faq={{q="Для чого потрібна Тіньова Могила?",a="Це склеп, де щойно пробуджені Відступники приходять до тями. Замість лишатися безмозкими невільниками Погибелі в землі, воскреслі повертають собі вільну волю в цій гробниці й починають друге життя на службі Сильвані Віндраннер.",al={"призначення тіньової могили","що таке тіньова могила","склеп тіньової могили"}},{q="Де розташована Тіньова Могила?",a="Тіньова Могила стоїть на вершині пагорба над могилами Похоронного Подзвону, під південними горами Галявин Тірісфалю. Від її входу ґрунтова стежка в'ється вниз до поселення Похоронний Подзвін.",al={"де тіньова могила","розташування тіньової могили","тіньова могила на мапі"}},{q="Хто тут опікується щойно пробудженими?",a="Гробар Мордо наглядає за щойно пробудженими в гробниці: він перевіряє, чи ті, хто встає з кам'яних плит, повернули собі розум і чи придатні служити справі Відступників.",al={"хто в тіньовій могилі","нпс тіньової могили","де гробар морд"}}},fp="12,244,22.531.0,34.255.0,34.217.0,37.174.0"}
P.entries["subzone:shadow-hold"] = {n="Твердиня Тіні",s="Твердиня Тіні — розлогий підземний комплекс, схований у зачумленому каньйоні Джеденару в західному Скверноліссі. Колись це було священне курганне лігво нічних ельфів, а тепер його захопила й осквернила Рада Тіней, зробивши своїм головним бастіоном у Калімдорі.",h="Твердиня Тіні — розлогий підземний комплекс, схований у зачумленому каньйоні Джеденару в західному...",kw={"твердиня тіні","рада тіней","джеденар","лорд бейнголлоу","арко'нарін","чорнокнижники","сквернолісся"},ang={["class:Warlock"]="У найглибших закутках Твердині Тіні зберігаються рідкісні демонічні реагенти, як-от Зоротський Зоряний Пил. Здобути їх можна лише хитрим проникненням, завоювавши прихильність Лорда Бейнголлоу.",["race:NightElf"]="Для нічних ельфів твердиня — жахливе видовище: курганне лігво предків, осквернене мулом скверни, клітками для в'язнів і демонічними обрядами."},sec={{t="Осквернене святилище",b="Під оскверненою червоною землею Джеденару лежить Твердиня Тіні — величезний підземний лабіринт, вирубаний на місці давнього курганного лігва нічних ельфів. Там, де колись спочивали сплячі друїди, що оберігали Смарагдовий Сон, тепер звивистими коридорами, освітленими вогнем скверни, никають темні чорнокнижники й демонічні слуги. На найглибших ярусах культ має грізні сили під проводом жахолорда Лорда Бейнголлоу, Принца Ксаваліса та Тіньового Лорда Фел'дана, тож це найвищий осередок демонічного впливу в краї."},{t="Жахіття в глибинах",b="Рада Тіней використовує печери, щоб координувати осквернення Сквернолісся й проводити жорстокі допити. Розвідники Альянсу, зокрема нічна ельфійка Арко'нарін Старшейд і паладин-людина Трей Лайтфордж, потрапили до рук культистів глибоко у твердині. Арко'нарін вижила завдяки вчасному порятунку, а Трея закатували до смерті кати культу. Його дух на якийсь час обернувся на злобу, але згодом знайшов спокій. Смарагдове Коло й місцеві шамани невпинно працюють, щоб пробити темні бар'єри, які захищають твердиню, і завдати удару її демонічним володарям."}},faq={{q="Чим була Твердиня Тіні до того, як її захопила Рада Тіней?",a="Спершу Твердиня Тіні була давнім курганним лігвом нічних ельфів, присвяченим друїдам, що спали, доглядаючи землю, і спілкуванню зі Смарагдовим Сном. Після Третьої війни й демонічного зіпсуття Сквернолісся Рада Тіней захопила підземний комплекс і осквернила його священні зали, обернувши їх на фортецю Скверни.",al={"історія твердині тіні","хто збудував твердиню тіні","чим була твердиня тіні"}},{q="Хто править у Твердині Тіні?",a="Твердинею керує жахолорд Лорд Бейнголлоу разом із могутніми помічниками — сатиром Принцом Ксавалісом і чорнокнижником Тіньовим Лордом Фел'даном, що командує смертними сектантами.",al={"бос твердині тіні","хто керує твердинею тіні","лідери твердині тіні"}},{q="Навіщо шукачеві пригод мирно пробиратися до Твердині Тіні?",a="Знавці темних мистецтв, яким потрібні могутні реагенти для виклику, як-от Зоротський Зоряний Пил, часом заходять у твердиню під виглядом вірних сектантів Ради Тіней. Лорд Бейнголлоу дозволяє торгувати з чужинцями, лише якщо вони доведуть вірність, викриваючи шпигунів і зрадників у його лавах.",al={"проникнути у твердиню тіні","маскування ради тіней","зоротіанський зоряний пил"}},{q="Що сталося з полоненими у твердині?",a="Нічну ельфійку Арко'нарін Старшейд і паладина Трея Лайтфорджа схопили, коли вони розвідували Раду Тіней. Трея закатувала до смерті сектантка Ракайя, а Арко'нарін шукачі пригод визволили з клітки й згодом повернули рештки Трея, щоб гідно його поховати.",al={"в'язні джеденара","трей лайтфорж і арконарін","клітка твердині тіні"}}},fp="11,252,19.501.0,19.573.1,60.318.0,29.197.0,58.293.1,42.281.1"}
P.entries["subzone:shadowbreak-ravine"] = {n="Яр Тіньового Зламу",ang={["class:Warlock"]="Темні кола призову й зосереджена присутність Скверни роблять цей потаємний каньйон наочним свідченням того, як далеко сягає темне мистецтво Палаючого Клинка."},sec={{t="Потаємний анклав Скверни",b="Tucked deep into the barren mountain ridges southeast of Magram Village, Shadowbreak Ravine provides the Burning Blade with a secluded staging ground away from the eyes of wandering centaur tribes. Amid strange, oversized mushrooms and grim ritual encampments, cultists labor alongside summoned demons. Here, dark practitioners invoke fel energies and tend heavy ritual chains, using the natural isolation of the ravine to marshal reinforcements and maintain a firm demonic foothold within the badlands of Desolace."}},faq={{q="Що таке Яр Тіньового Зламу?",a="Shadowbreak Ravine is a hidden mountain ravine situated in southeastern Desolace, just beyond Magram Village. It serves as a concealed camp and staging ground for demonic minions and cultists serving the Burning Blade.",al={"інформація про яр тіньового зламу","що це за місце","де яр тіньового зламу"}},{q="Хто займає яр?",a="У яру засіли сектанти Палаючого Клинка, що діють пліч-о-пліч із демонами. Захищена місцевість яру дає їм змогу правити темні обряди й підтримувати ширший наступ по всьому краю.",al={"хто тут живе","моби яру тіньового зламу","вороги яру тіньового зламу"}},{q="Що можна знайти в яру?",a="У яру — темні обрядові споруди, масивні залізні ланцюги й помітні велетенські гриби, що проростають серед осквернених Скверною таборів, захованих у гірських розколинах.",al={"що в яру тіньового зламу","пам'ятки яру тіньового зламу"}}},fp="18,243,23.515.0,27.218.0,24.209.0,45.176.0"}
P.entries["subzone:shadowfang-keep"] = {n="Фортеця Шадовфенг",s="Фортеця Шадовфенг, що височіє на суворій кручі над Селом Пайрвуд у південному Срібноліссі, — темне лігво божевільного Архімага Аруґала та його диких воргенів. Колишня Фортеця Сільверлейн упала під натиском ненажерливих вовкоподібних звірів, викликаних під час Третьої війни, і тепер її давні зали населяють привиди вбитої знаті й кишать вовчі жахіття.",h="Фортеця Шадовфенг, що височіє на суворій кручі над Селом Пайрвуд у південному Срібноліссі, — темне лігво...",kw={"фортеця шадовфенг","архімаг аруґал","воргени","барон сільверлейн","село пайрвуд","срібнолісся","фенрус"},ang={["class:Mage"]="Фортеця Шадовфенг — похмуре нагадування про пиху Кірін-Тору й про лихо, до якого призводять нестримні виклики з інших вимірів.",["faction:Horde"]="Для Відступників Аруґалові воргени — непередбачувана загроза, що розповзається просто на порозі зовнішніх земель Андерсіті в Срібноліссі й вимагає швидкого знищення."},sec={{t="Падіння Сільверлейнів",b="До Третьої війни ця височенна твердиня звалася Фортецею Сільверлейн — родовим гніздом Барона Сільверлейна й осередком влади для сусіднього Села Пайрвуд. Коли Погибель пронеслася Лордероном, відчайдушні чарівники вдалися до заборонених засобів, щоб спинити хвилю нежиті. Спираючись на дослідження інших вимірів даларанського мага Ура, Архімаг Аруґал викликав в Азерот позавимірних воргенів. Дикі звірі шматували Погибель, але швидко вийшли з-під контролю. Шаленіючи по всьому південному Срібноліссю, зграя взяла твердиню в облогу й вирізала Барона Сільверлейна, його родину й оборонців Командира Спрінґвейла. Провина й горе зламали розум Аруґала: замість тікати, він захопив фортецю, перейменував її на Фортецю Шадовфенг і назвав жахливих хижаків своїми «дітьми»."},{t="Примарний оплот",b="Нині Фортеця Шадовфенг — осердя вовчого прокляття, що дедалі ширше мучить Срібнолісся. Аруґал живе в найвищій обсерваторії в оточенні своїх ненажерливих воргенів — зокрема зграй Мунрейдж і Шадовфенг — та зловісних звірів на кшталт його величезного улюбленого вовка Фенруса. Нижче його святилища неспокійні привиди колишніх володарів фортеці, як-от Барон Сільверлейн і Командир Спрінґвейл, лишаються ув'язненими в муках, приречені без кінця боронити зали, яких не вберегли за життя. З цих мурів Аруґал простягає свій підступний вплив до Села Пайрвуд і навколишніх лісів, становлячи страшну загрозу для сусідів-Відступників, що прагнуть очистити ліс від його божевілля."}},faq={{q="Як звалася Фортеця Шадовфенг до того, як її захопив Аруґал?",a="Спершу вона звалася Фортецею Сільверлейн. Це було родове гніздо Барона Сільверлейна, вельможі, чиє військо на чолі з паладином Командиром Спрінґвейлом опікувалося Селом Пайрвуд і довколишніми землями, доки їх не заполонили воргени.",al={"стара назва","хто володів шадовфенгом","фортеця сільверлейн"}},{q="Навіщо Аруґал викликав сюди воргенів?",a="Під час Третьої війни Погибель нещадно громила сили Даларану й піднімала вбитих чарівників як нежить. Усупереч застереженням Кірін-Тору, архімаг Аруґал скористався дослідженнями чарівника Ура й викликав воргенів з іншого виміру, щоб переломити хід війни. Вони справді винищили нежить, але швидко обернулися проти живих і розбіглися по Срібноліссю.",al={"навіщо аруґал викликав воргенів","історія аруґала","як воргени потрапили сюди"}},{q="Хто зараз править Фортецею Шадовфенг?",a="Фортецю тримає Архімаг Аруґал. Збожеволівши від провини за те, що випустив чудовиськ, він прийняв воргенів як своїх «дітей» і править із висот фортеці разом зі своєю смертоносною зграєю.",al={"хто тепер править шадовфенгом","хто живе у фортеці шадовфенг","фортеця аруґала"}},{q="Чому у Фортеці Шадовфенг є привиди?",a="Це привиди Барона Сільверлейна, Командира Спрінґвейла й колишніх мешканців фортеці. Коли воргени ринули до фортеці й вирізали всіх, хто був усередині, духи мешканців лишилися прикуті до каміння й приречені блукати зруйнованими коридорами.",al={"привид сільверлейн","привид коменданта спрінґвейла","нежить усередині шадовфенгу"}},{q="Як Село Пайрвуд пов'язане з фортецею?",a="Пайрвуд лежить у тіні фортеці й здавна підлягав Баронові Сільверлейну. Під дедалі сильнішим впливом Аруґала селян уразило прокляття воргенів: удень вони схожі на звичайних людей, а під нічним небом обертаються на скажених звірів.",al={"пайрвуд і шадовфенг","прокляття пайрвуду"}}},fp="15,366,24.815.0,17.707.0,56.237.0,38.369.0,36.195.0,40.253.0,55.270.1"}
P.entries["subzone:shadowglen"] = {n="Тінедол",s="Тінедол — відлюдна сутінкова долина в північно-східному гіллі Тельдрассила. Над нею височіє велике дерево-курган Алдрассил; це безпечний прихисток, де молоді нічні ельфи роблять перші кроки на службі, перш ніж вирушити в широкий світ.",h="Тінедол — відлюдна сутінкова долина в північно-східному гіллі Тельдрассила.",kw={"тінедол","алдрассил","стартова зона","нічні ельфи","тельдрассил","печера тіньової нитки","долина"},ang={["faction:Alliance"]="Розташований високо в гіллі Тельдрассила й далеко за охоронюваними портами, Тінедол — одна з найзахищеніших і найвідособленіших долин-святилищ Альянсу.",["race:NightElf"]="Кожен молодий нічний ельф починає свою діяльну путь тут, серед захищеного коріння Алдрассила, отримуючи перші благословення й настанови, перш ніж зустріти небезпеки Калімдору."},sec={{t="Захищена колиска",b="Тінедол, схований у північно-східній кроні Тельдрассила, оточений високими хребтами, що відгороджують його від решти світу. Залита вічними сутінками долина зосереджена довкола Алдрассила — велетенського дерева-кургану, у чиєму видовбаному стовбурі живуть старійшини, жриці й наставники молодих нічних ельфів, що починають навчання. Єдиний шлях із долини веде на південь вузьким гірським проходом до Села Зоряного Вітерця й Доланаара, тож Тінедол — одне з найзахищеніших самою природою й наймирніших святилищ Світового Дерева."},{t="Тіні підкрадаються",b="Попри тихе усамітнення, Тінедол не зовсім вільний від небезпек. На крайньому північному заході лежить Печера Тіньової Нитки — темна печера, що кишить отруйними павуками, які постійно загрожують тихому гаю. Навіть на незайманих гілках Тельдрассила потрібна пильність, і захисникам-початківцям доручають відганяти набридливу гидь і дику живність, перш ніж вирушати в ширші простори гілля."}},faq={{q="Що таке Тінедол?",a="Тінедол — захищений стартовий гай нічних ельфів у північно-східній частині Тельдрассила. Це мирний, відлюдний прихисток довкола великого дерева Алдрассил, де новачки навчаються в наставників, перш ніж вирушити мандрувати Світовим Деревом.",al={"що це за місце","лор тінедолу","про тінедол"}},{q="Що за величезне дерево в центрі долини?",a="Це Алдрассил — дерево-курган, що становить серце Тінедолу. Його видовбане нутро править за оселю громади й осередок навчання, де нічні ельфи-новачки зустрічають наставників класів, учителів і доглядачів.",al={"велике дерево в тінедолі","алдрассил","дерево тінедолу"}},{q="Які загрози є в Тінедолі?",a="Головна загроза — на північному заході, у Печері Тіньової Нитки: печера кишить отруйними павуками, що раз у раз виповзають у гай. Молодим захисникам доручають винищувати павуків і втихомирювати неспокійну місцеву живність.",al={"чому тут павуки","небезпеки тінедолу","печера тіньової нитки"}},{q="Як вийти з Тінедолу?",a="Тінедол повністю оточений хребтами, за винятком єдиної стежки на південь. Цей вузький гірський прохід веде на південь, до Села Зоряного Вітерця й поселення Доланаар.",al={"вихід із тінедолу","куди веде стежка","як вибратися з тінедолу"}}},fp="10,269,18.533.0,16.444.0,19.264.0,51.216.0,33.239.0,28.197.0"}
P.entries["subzone:shadowprey-village"] = {n="Село Тіньової Здобичі",s="Село Тіньової Здобичі — віддалене рибальське поселення Орди на скелястому південному березі Узбережжя Сар'теріс у Пустограї. Тут живуть переважно рибалки-тролі з племені Темного Списа, а таурени тримають корчму та інші служби; це важливий прибережний форпост і торговельна рятівна нитка посеред безплідного пустиря.",h="Село Тіньової Здобичі — віддалене рибальське поселення Орди на скелястому південному березі Узбережжя...",kw={"село тіньової здобичі","пустограй","тролі","темний спис","рибальство","узбережжя сар'теріс","орда"},ang={["faction:Horde"]="Для мандрівників Орди, що перетинають Пустограй, Село Тіньової Здобичі — єдиний прибережний перепочинок, вузол польотів і безпечна база постачання на південь від Цвинтаря Кодо.",["race:Troll"]="Село Тіньової Здобичі — рідкісний осередок прибережної культури Темного Списа в центральному Калімдорі, де видно споконвічну майстерність племені в рибальстві з острогою, пірнанні й виживанні на узбережжі."},sec={{t="Притулок на узбережжі",b="Притулившись до скель південного Пустограю, Село Тіньової Здобичі дає безпечну гавань у краї, відомому кланами кентаврів і безлюдними пустирями. Поселення — передусім табір рибалок-тролів, чий улов годує не лише їхнє село, а й форпости в глибині краю, як-от Заставу Духоходів. Попри скелястий берег, високі дерев'яні пристані сягають далеко в океан, тож місцеві рибалки виходять на глибину й пірнають по молюсків серед затонулих уламків, якими всіяне Узбережжя Сар'теріс."},{t="Прибережні випробування",b="Тримати прикордонний порт у Пустограї — справа, повна небезпек. Окрім кентаврів-мародерів у глибині краю, виживання села випробовує й сам океан. У місцевих водах лютує ненажерлива морська живність — передусім жахлива косатка Блаббергат, що пожирає рибні запаси, — а з південних берегів насуваються войовничі лобстроки. Союзники-таурени, серед них Тайга Вайзмейн і господарі корчми та сідала вітрокрилів, допомагають зміцнювати оборону й тримати відкритими торгові шляхи по всьому Калімдору."}},faq={{q="Чому Село Тіньової Здобичі важливе для Орди?",a="Пустограй — негостинна пустка, бідна на природні багатства. Село Тіньової Здобичі — єдиний морський порт Орди в краї: сюди привозять життєво важливі улови риби й молюсків, щоб годувати гарнізони на кшталт Застави Духоходів, а ще тут є сідало вітрокрилів із польотами до Гір Кам'яного Кігтя, Тандер Блафа й Фераласу.",al={"навіщо село тіньової здобичі","чому тіньова здобич тут","роль тіньової здобичі для орди"}},{q="Хто очолює Село Тіньової Здобичі?",a="Єдиного офіційного вождя в селі немає. Це вільна громада тролів-рибалок: старійшини, як-от Май'Лагії, підтримують зв'язки з гостями на кшталт Кола Кенарія, а мешканці-таурени, як-от Тайга Вайзмейн, дбають про безпеку узбережжя й місцеву оборону.",al={"лідер тіньової здобичі","хто керує тіньовою здобиччю","май'лахі"}},{q="Чому в тролівському селі послуги ведуть таурени?",a="Тіньова Здобич почалася як рибальська застава тролів Темного Списа, але роль місцевого осередку постачання привабила ширшу господарську машину Орди. Таурени опікуються спільною інфраструктурою: ведуть корчму, стайні й сідало вітрокрилів, що сполучає порт із Малгором і далі.",al={"таурени в тіньовій здобичі","чому тут таурени","таурени тіньової здобичі"}},{q="Що турбує рибалок?",a="Окрім ворожих кентаврів у глибині краю, селу дошкуляє брак риби, бо величезна косатка на прізвисько Салобрюх пожирає прибережні косяки, а ще на південних припливних мілинах кишать лобстроки.",al={"проблеми тіньової здобичі","бламбутроб","загрози тіньової здобичі"}}},fp="18,298,21.503.0,20.497.0,49.317.0,29.300.0,61.319.0,41.217.0"}
P.entries["subzone:shadowsong-shrine"] = {n="Святиня Шедовсонг",s="Святиня Шедовсонг — зруйноване святилище на схилі пагорба на заході Азшари, неподалік кордону з Ашенвалем. Тут блукають неспокійні духи прадавніх Високороджених; місце носить славетне ім'я роду Шедовсонгів, хоча його справжній історичний зв'язок із ними досі оповитий таємницею.",h="Святиня Шедовсонг — зруйноване святилище на схилі пагорба на заході Азшари, неподалік кордону з Ашенвалем.",kw={"святиня шедовсонг","джарод шедовсонг","маєв","високороджені","привиди","війна прадавніх","азшара"},ang={["race:NightElf"]="Для нічних ельфів ім'я Шедовсонг викликає глибоку шану завдяки тому, як Джарод вів військо у Війні Прадавніх, тож осквернення цього місця змученими привидами Високороджених особливо трагічне."},sec={{t="Спадщина з привидами",b="Святиня Шедовсонг, що стоїть на високому пагорбі над розтрощеними землями Азшари, давно лежить у порослих руїнах. Як і більшу частину довколишнього узбережжя, її досі терзають примари Високороджених, що блукають серед поваленого каміння й прагнуть погасити кожне смертне життя, яке посміє ступити на їхні володіння. Святиня має спільне ім'я з двома легендарними постатями історії калдореїв: Джародом Шедовсонгом, мимовільним полководцем, що очолив опір нічних ельфів у Війні Прадавніх, і його сестрою Маєв — невблаганною наглядачкою Іллідана Стормрейджа. Чи звели це святилище на честь їхніх звершень, чи воно сягає часів, коли родина мала вагу ще до Розколу, — таємниця, що загубилася у віках."}},faq={{q="Що таке Святиня Шедовсонг?",a="Це давні руїни нічних ельфів на узвишші на заході Азшари. Нині вони напівзруйновані й занедбані, і їх заполонили ворожі примари Високородних.",al={"що це за місце","інформація про святиню шедовсонг","руїни на пагорбі ашара"}},{q="На честь кого названо святиню?",a="Вона носить ім'я славетного роду Шедовсонгів — передусім Джарода Шедовсонга, героя Війни Прадавніх, і його старшої сестри Маєв, знаменитої наглядачки. Проте чи вшановує святиня когось із них безпосередньо, достеменно не записано.",al={"джаред шедовсонг","майєв шедовсонг","чому шедовсонг"}},{q="Чому в святині блукають привиди?",a="Як і багато руїн по всій Азшарі, це місце спустошив Великий Розкол десять тисяч років тому. Духи Високородних, що загинули в катаклізмі, досі прикуті до каміння, замкнені в божевіллі й ворожі до живих.",al={"чому тут привиди","високородні привиди ашара","привиди святині шедовсонг"}},{q="Де розташована святиня?",a="Вона стоїть на вершині пагорба на заході Азшари, на схід від лісистого кордону з Ашенвалем і неподалік від застави Мис Талрендіс.",al={"де святиня шедовсонг","розташування святині шедовсонг","як знайти святиню шедовсонг"}}},fp="17,306,16.730.0,26.158.0,30.265.0,26.242.0,28.131.0"}
P.entries["subzone:shadowthread-cave"] = {n="Печера Тіньової Нитки",s="Печера Тіньової Нитки — волога печера в північно-західних скелях Тінедолу на Тельдрассилі. Здавна заселена тутешніми павуками Вебвуда, вона нещодавно стала небезпечно агресивною під владою їхньої матки — Ґітіісс Мерзенної.",h="Печера Тіньової Нитки — волога печера в північно-західних скелях Тінедолу на Тельдрассилі.",kw={"печера тіньової нитки","павуки","вебвуд","ґітіісс мерзенна","тінедол","тельдрассил","виводок"},ang={["class:Druid"]="Нестримна агресія виводку Вебвуда в Печері Тіньової Нитки — тривожний знак для друїдів, що природна гармонія Тельдрассила глибоко порушена.",["race:NightElf"]="Для молодих нічних ельфів очищення Печери Тіньової Нитки та вбивство Ґітіісс Мерзенної — одне з найперших випробувань у захисті священної домівки від скверни, що підкрадається."},sec={{t="Неспокійний виводок",b="Печера Тіньової Нитки в тінистій околиці Тінедолу здавна була природним лігвом велетенських павуків Тельдрассила. Раніше ці павуки тихо співіснували з молодим гіллям Світового Дерева. Та віднедавна їхня вдача стала люто територіальною. Товсті шари павутиння Вебвуда тепер душать кам'яні коридори, а агресивність виводку становить пряму загрозу молодим калдореям, що роблять перші кроки за межі Алдрассила."},{t="Ґітіісс Мерзенна",b="Головна загроза, що чаїться в найтемніших закутках печери, — Ґітіісс Мерзенна, жахлива матка виводку, чия лють далеко перевершує звичайних павуків Вебвуда. Вартових і друїдів нічних ельфів-новачків посилають до печери стримати навалу павуків і вбити Ґітіісс, щоб скверна, яка торкнулася живності Тельдрассила, не поглинула святилище Тінедолу цілком."}},faq={{q="Де розташована Печера Тіньової Нитки?",a="Печера Тіньової Нитки — у північно-західному куті Тінедолу, під скелястим схилом на межі долини, де починають свій шлях нічні ельфи на Тельдрассилі.",al={"розташування печери тіньової нитки","де печера тіньової нитки","знайти печеру тіньової нитки"}},{q="Чому павуки в печері такі агресивні?",a="Павуки жили в печері завжди, але мерзенна хвороба й дедалі більший розлад рівноваги на Тельдрассилі звели з розуму місцевих звірів, і павуки Вебвуда стали надзвичайно лютими.",al={"чому павуки ворожі","скверна павуків тіньової нитки","чому павуки нападають"}},{q="Хто така Ґітіісс Мерзенна?",a="Ґітіісс Мерзенна — величезна отруйна павучиха-матріарх Вебвуда, що засіла в найглибшій точці Печери Тіньової Нитки. Вона праматір агресивного поріддя, що загрожує юним калдореям у Тінедолі.",al={"ґітіісс","хто така ґітіісс","бос павуків тіньової нитки"}},{q="Чим цінна печера, попри небезпеку?",a="Печера аж напхана шарами густого природного шовку павуків Вебвуда — цінного й міцного матеріалу для ремесел, який тчуть нескінченні рої павуків, що живуть у її темних залах.",al={"шовк тіньової нитки","павучий шовк тіньової долини"}}},fp="17,263,24.490.0,17.400.0,35.151.0,46.192.0,25.200.0,48.183.0"}
P.entries["subzone:shady-rest-inn"] = {n="Корчма «Затишний Спочинок»",s="Корчма «Затишний Спочинок» колись була гостинним придорожнім притулком, збудованим людьми біля дороги між Пустками й Островом Терамор. Нині від неї лишилися тільки обвуглені колоди й тліючий попіл після раптового жорстокого підпалу. Трагедія зламала корчмаря й посіяла напругу по всьому болоту, поки слідчі перебирають згарище в пошуках доказів.",h="Корчма «Затишний Спочинок» колись була гостинним придорожнім притулком, збудованим людьми біля дороги між...",kw={"затишний спочинок","корчма","багно пилоброду","підпал","ґрімтотем","джеймс гайал","терамор"},ang={["faction:Alliance"]="Знищення корчми — серйозний пролом у безпеці на головному суходільному шляху до Острова Терамор: воно загрожує мандрівникам і роздмухує страх перед прихованими ворогами.",["race:Tauren"]="Жорстокий, неспровокований наліт клану Ґрімтотем загрожує зруйнувати крихкий мир між Ордою й силами Джайни Праудмур у Багні Пилоброду."},sec={{t="Попіл на кордоні",b="Збудована для мандрівників, що долали небезпечний шлях між Багном Пилоброду й Пустками, Корчма «Затишний Спочинок» була острівцем цивілізованого затишку серед суворої глушини. Усе скінчилося, коли корчму раптово знищила нищівна пожежа. Корчмар Джеймс Гайал вижив у вогні, але полум'я забрало життя його дружини й дитини. Травмований і вбитий горем, Гайал лишився ні з чим, а згарище стало місцем злочину, яке пильно досліджує влада Терамору, відчайдушно намагаючись з'ясувати, хто підпалив корчму."},{t="Павутина підозр",b="Перші розслідування підпалу вказували на людей-дезертирів і підозрілих солдатів: під важку підозру потрапили такі постаті, як Павал Ріт і Лейтенант Колдвелл, — обидва згодом передчасно загинули. Проте речові докази, знайдені в попелі, — зокрема характерні сліди копит і ритуальні знаки — показали, що напад був не просто внутрішньою зрадою. Підпал учинили безжальні таурени Ґрімтотем, які завдають ударів із глибини болота, щоб посіяти розбрат між Терамором і його сусідами."}},faq={{q="Що сталося з Корчмою «Затишний Спочинок»?",a="На корчму напали й спалили її дощенту. Спершу підозрювали дезертирів і вояків-відступників з Альянсу, і слідчі досі перебирають попіл у пошуках доказів, хто насправді стоїть за підпалом.",al={"чому корчма затишний спочинок згоріла","що сталося з корчмою","хто спалив затишний спочинок"}},{q="Кому належала корчма й хто її тримав?",a="Корчму «Затишний Спочинок» тримав Джеймс Гайал. Він пережив пожежу, але його дружина й дитина загинули у вогні, і це глибоко його травмувало.",al={"корчмар затишного спочинку","хто тримав затишний спочинок","джеймс гайал"}},{q="Де розташована Корчма «Затишний Спочинок»?",a="Руїни лежать біля головної дороги на заході Багна Пилоброду, неподалік від кордону, де болото переходить у Пустки.",al={"розташування затишного спочинку","де корчма затишний спочинок"}},{q="Хто такі Павал Ріт і Лейтенант Колдвелл?",a="Це люди, яких запідозрили на початку розслідування пожежі. Обидва загинули, перш ніж слідчі встигли дістати з них зізнання чи остаточно з'ясувати, наскільки вони були причетні.",al={"хто такий ріт","лейтенант колдвелл затишний спочинок","ріт і колдвелл"}}},fp="14,361,19.565.0,18.526.1,36.201.1,31.136.0,36.126.0,45.200.1"}
P.entries["subzone:shalzaru-s-lair"] = {n="Лігво Шалзару",s="Лігво Шалзару — розлога напівзатоплена печера на північному краю Острова Жаху у Фераласі. Це головна твердиня наг Гребеня Ненависті й притулок їхнього грізного володаря Шалзару. Із цих вологих тунелів зміюваті загарбники керують своїм наступом просто на південь від Твердині Перистого Місяця.",h="Лігво Шалзару — розлога напівзатоплена печера на північному краю Острова Жаху у Фераласі.",kw={"лігво шалзару","лорд шалзару","наги","острів жаху","твердиня перистого місяця","фералас"},ang={["faction:Alliance"]="Наги Гребеня Ненависті, що збираються в цій печері, загрожують шляхам постачання й спокою Твердині Перистого Місяця, тож знищити Шалзару та його кубло — першочергове завдання для Вартових та їхніх союзників.",["race:NightElf"]="Мерзенні наги, що паплюжать прадавні прибережні руїни Фераласу, — болісне нагадування про Розкол і про те, як Високородні скотилися до потворної скверни."},sec={{t="Зміїне кубло на мілині",b="Лігво Шалзару, вирубане в урвистих кручах на північному кінці Острова Жаху, складається з величезної головної печери та меншої бічної зали, сполучених затопленими підземними протоками. Усередині кишать зміїні вартові Гребеня Ненависті й чарівниці, які пильно стоять на сторожі. У найглибших закутках живе Лорд Шалзару — зміюватий володар, що керує всім кублом Гребеня Ненависті на острові. Лігво розташоване так близько до Острова Сардор, що становить пряму й постійну загрозу для Вартових нічних ельфів, які стоять залогою в Твердині Перистого Місяця просто за протокою."}},faq={{q="Де розташоване Лігво Шалзару?",a="Лігво Шалзару — на північному краю Острова Жаху, що лежить просто на південь від Острова Сардор і Твердині Перистого Місяця біля західного узбережжя Фераласу.",al={"де лігво шалзару","розташування лігва шалзару","як знайти лігво шалзару"}},{q="Хто такий Шалзару?",a="Шалзару — могутній воєначальник наг і володар племені Гребеня Ненависті, що живе на Острові Жаху. Він командує своїми силами з глибин затоплених печер лігва.",al={"хто такий шалзару","лор шалзару","бос лігва шалзару"}},{q="Хто живе в цій печері?",a="Печера кишить нагами Гребеня Ненависті — здебільшого пильними зміями-вартовими, що стережуть сухі проходи, і чаклунками, що спрямовують магію над підземними водами.",al={"вороги лігва шалзару","моби печери наг"}},{q="Чому це лігво важливе для місцевих нічних ельфів?",a="Острів Жаху лежить просто через протоку від Твердині Перистого Місяця, тож скупчення наг у Лігві Шалзару — пряма військова загроза для сил Шандріс Фезермун і безпеки Острова Сардор.",al={"чому нічним ельфам важливий шалзару","загроза наг перистому місяцю"}}},fp="15,343,29.575.0,33.177.0,16.176.0,33.185.0,52.245.0"}
P.entries["subzone:shaper-s-terrace"] = {n="Тераса Формувальника",s="Тераса Формувальника — загадковий оглядовий майданчик із прадавньою архітектурою титанів, що височіє на північних кручах над Притулком Маршала. Названа на честь Каз'ґорота Формувальника, вона мовчки свідчить про первісні експерименти, які сформували Кратер Ун'Ґоро.",h="Тераса Формувальника — загадковий оглядовий майданчик із прадавньою архітектурою титанів, що височіє на...",kw={"тераса формувальника","титани","каз'ґорот","ун'ґоро","дворфи","руїни"},ang={["race:Dwarf"]="Для дворфів, які шукають свого титанічного родоводу, Тераса Формувальника — ще одна спокуслива нагода зазирнути в архітектуру Каз'ґорота й величні творіння творців."},sec={{t="Спадок титанів",b="Над буйною доісторичною западиною Кратера Ун'Ґоро, на Терасі Формувальника, стоять монументальні кам'яні споруди, які лишили по собі титани. Вважають, що це високе плато присвячене Каз'ґороту Формувальнику; воно свідчить про небесних зодчих, які плекали кратер як живу лабораторію для ранніх форм життя на Азероті. З цих піднесених каменів прадавні сутності колись спостерігали за рослинами й тваринами внизу та спрямовували їхній розвиток. Холодні кам'яні арки й масивні металеві постаменти разюче й загадково контрастують із дикою природою, що буяє просто під ними."}},faq={{q="Що таке Тераса Формувальника?",a="Тераса Формувальника — висока пам'ятка титанів на північних кручах Кратера Ун'Ґоро, просто над Притулком Маршала. Тут стоять кам'яні споруди, пов'язані з титанами, що колись формували цю землю.",al={"тераса формувальника","що це за тераса","тераса ун'ґоро"}},{q="Хто такий «Формувальник»?",a="Назва тераси вказує на Каз'ґорота Формувальника — одного з титанів-творців, що в давнину допомагали створювати й плекати світ Азероту.",al={"хто такий формувальник","хазґорот","хто створив терасу формувальника"}}},fp="16,272,22.577.0,29.204.0,21.143.0"}
P.entries["subzone:shatter-scar-vale"] = {n="Долина Розтрощеного Шраму",s="Долина Розтрощеного Шраму — випалена улоговина в центральному Скверноліссі, трохи на північ від Водоспаду Кривавої Отрути. Саме сюди в Третю війну врізалися демонічні інфернали, впавши на північ Калімдору. Нині кратери досі палають вогнем скверни, і тут ховаються рештки Палаючого Легіону.",h="Долина Розтрощеного Шраму — випалена улоговина в центральному Скверноліссі, трохи на північ від Водоспаду...",kw={"долина розтрощеного шраму","інфернали","палаючий легіон","кратери","сквернолісся","третя війна"},ang={["class:Druid"]="Тліючі шрами цієї долини — відкриті рани на душі Калімдору, які не загояться, доки творіння Легіону ще палають.",["class:Warlock"]="Насичені скверною ядра інферналів, що бродять цими кратерами, — потужні провідники хаотичної магії, які лишилися після вторгнення Легіону."},sec={{t="Удар інферналів",b="У Третю війну Палаючий Легіон обрушив на північний Калімдор зливу живих облогових машин. Долина Розтрощеного Шраму прийняла на себе основний удар цього небесного натиску. Демонічні інфернали падали з неба, проривалися крізь давні крони й вибивали в землі глибокі кратери. Нищівні удари розтрощили місцевість, залишивши почорнілі западини, що й досі тліють нечестивим вогнем. Хоч Легіон і розбили біля Гори Гіджал, інфернали й дрібніші демони так і не розсіялися, міцно закріпившись у пошрамованій землі."}},faq={{q="Чому земля вкрита кратерами?",a="Кратери з'явилися під час Третьої війни, коли Палаючий Легіон бомбардував ліс інферналами. Ці громіздкі створіння з каменю Скверни падали з неба, мов метеори, вгризалися в землю й лишали по всій долині тліючі шрами від ударів.",al={"кратери скверноліссі","чому долина розтрощеного шраму в кратерах","що зробило кратери"}},{q="Хто блукає Долиною Розтрощеного Шраму?",a="Долину досі заполоняють створіння й слуги Палаючого Легіону. Живі інфернали й далі стережуть тліючі вирви, а поряд блукають інші дрібніші демони, що лишилися, коли навала захлинулася.",al={"які моби тут","вороги долини розтрощеного шраму"}},{q="Де розташована Долина Розтрощеного Шраму?",a="Долина Розтрощеного Шраму лежить у центрі Сквернолісся, просто на північ від Водоспаду Кривавої Отрути, на східному боці головної лісової стежки.",al={"розташування долини розтрощеного шраму","де долина розтрощеного шраму"}}},fp="17,294,23.559.0,37.260.0,38.214.0,35.153.0"}
P.entries["subzone:shattered-strand"] = {n="Розтрощене Узмор'я",s="Розтрощене Узмор'я — дике скелясте узбережжя вздовж північного краю Затоки Бур в Азшарі. Тут панують гуркітливий прибій і прадавні руїни, що розсипаються, а пляж аж кишить небезпечними морськими звірами й племенами водяних істот.",h="Розтрощене Узмор'я — дике скелясте узбережжя вздовж північного краю Затоки Бур в Азшарі.",kw={"розтрощене узмор'я","затока бур","азшара","гідри","морські гіганти","храм арккорана","вежа ельдари"},ang={["class:Hunter"]="Узмор'я — дике випробувальне поле, повне грізних гідр і прибережних звірів, ідеальне для тих, хто шукає могутніх звірів-супутників або вивчає хижу фауну узбережжя Калімдору."},sec={{t="Підступне узбережжя",b="Розтрощене Узмор'я, що тягнеться вздовж північного краю Затоки Бур, — далеко не мирний берег. На кам'янистих пляжах і приливних мілинах повно агресивних істот: велетенських морських гігантів, багатоголових гідр і клацливих макрур, а поряд стоять табори прибережних мурлоків. Над хвилями нависають ельфійські споруди, що розсипаються, — зокрема прадавній Храм Арккорана й самотня Вежа Ельдари. Для мандрівників, що пробираються підступними кручами Азшари, спуститися на цю відлюдну смугу узбережжя означає зустрітися з одними з найнебезпечніших загроз краю, що живуть і у воді, і на суходолі."}},faq={{q="Де розташоване Розтрощене Узмор'я?",a="Розтрощене Узмор'я — північне узбережжя Затоки Бур на сході Азшари, під височенними кручами краю.",al={"розташування розтрощеного узмор'я","де розтрощене узмор'я","розтрощене узмор'я на мапі"}},{q="Хто живе на Розтрощеному Узмор'ї?",a="Узбережжям нишпорять люті гідри, величезні морські велетні, закуті в панцир макрури й гурти ворожих мурлоків, що патрулюють припливні мілини.",al={"моби розтрощеного узмор'я","хто живе на розтрощеному узмор'ї","звірі розтрощеного узмор'я"}},{q="Які відомі руїни є на пляжі?",a="На узбережжі стоять давні споруди Високородних — передусім Храм Арккорана й сусідня Вежа Ельдари, що височіє над затокою.",al={"руїни розтрощеного узмор'я","будівлі на розтрощеному узмор'ї","пам'ятки розтрощеного узмор'я"}},{q="Чи безпечне Розтрощене Узмор'я для безтурботних прогулянок?",a="Ні. Пляж відрізаний від світу, швидко втекти звідси важко через прямовисні скелі довкола, і тут аж кишить хижими морськими звірами й могутніми велетнями.",al={"чи небезпечне розтрощене узмор'я","рівень розтрощеного узмор'я"}}},fp="16,239,23.622.0,38.149.0,44.148.0,48.144.0,52.161.0"}
P.entries["subzone:shifting-mire"] = {n="Мінлива Твань",s="Мінлива Твань — велике мулисте серце Болота Скорботи, що лежить трохи на захід від Ставка Сліз. Свою назву вона отримала через дивний, неспокійний мул під каламутною водою, який ніби дрейфує й збирається докупи під впливом незримої сили.",h="Мінлива Твань — велике мулисте серце Болота Скорботи, що лежить трохи на захід від Ставка Сліз.",kw={"мінлива твань","болото скорботи","загублені","болотяні ягуари","кроколіски","мул"},ang={["class:Hunter"]="Через сплутані хащі й мінливі води вистежувати здобич тут нелегко, тож мисливцям слід бути напоготові, щоб їх не заскочили потайні болотяні ягуари й отруйні скорботні прядильники, які ховаються в заростях."},sec={{t="Живе болото",b="Мінлива Твань простягається через усю серцевину боліт — це моторошний простір, де важко знайти тверду опору під ногами. Мул на дні болота зсувається й збивається докупи, наче його рухає жива воля, яку пробуджує дивна енергія, що просякає торф. Серед мулу, що повільно пливе, нишпорять хижі болотяні ягуари, величезні скорботні прядильники й голодні пилозубі кроколіски, а потопленими стежками блукають ватаги зламаних дренеїв, відомих як Загублені."}},faq={{q="Чому вона зветься Мінливою Тванню?",a="Назва походить від надзвичайно дрібного мулу на дні болота. Замість осідати, як звичайний намул, він під дією загадкового потоку енергії збирається, дрейфує й тече болотами, наче живий.",al={"походження назви мінливої твані","чому мінлива твань","чому земля рухається"}},{q="Хто живе в Мінливій Твані?",a="Твань кишить небезпечними звірами: пилкозубі кроколіски чатують на мілинах, велетенські скорботні прядильники плетуть павутиння на гілках, а болотяні ягуари підкрадаються непомітно. Тут часто блукають і Загублені — дренеї, спотворені й вигнані з рідного світу.",al={"моби мінливої твані","що в мінливій твані"}},{q="Де розташована Мінлива Твань?",a="Вона охоплює центральну частину Болота Скорботи, просто на захід від великого озера, відомого як Ставок Сліз.",al={"розташування мінливої твані","де мінлива твань"}}},fp="13,252,12.460.0,35.237.0,41.269.0,35.139.0"}
P.entries["subzone:shimmer-ridge"] = {n="Мерехтливий Хребет",s="Мерехтливий Хребет — суворе високогір'я на півночі Дун Мороґу, просто на захід від Брами Айронфорджа. Скелясті висоти, зайняті ворожими тролями Морозогривами, складаються з двох таборів, з'єднаних хистким мостом, і славляться як єдине місце, де можна зібрати потужне мерехтливе зілля.",h="Мерехтливий Хребет — суворе високогір'я на півночі Дун Мороґу, просто на захід від Брами Айронфорджа.",kw={"мерехтливий хребет","мерехтливе зілля","морозогриви","тролі","травництво","дун мороґ"},ang={["profession:Herbalism"]="Поки звичайні рослини ледве животіють у морозному кліматі Дун Мороґу, лише на Мерехтливому Хребті ростуть цінні кошики мерехтливого зілля, доглянуті серед таборів Морозогривів.",["race:Dwarf"]="Мерехтливий Хребет у тіні брами Айронфорджа — прикре нагадування про невідступну загрозу Морозогривів і небезпечне джерело добірного мерехтливого зілля для легендарного дворфського стауту."},sec={{t="Твердиня Морозогривів",b="Мерехтливий Хребет на скелястих схилах одразу на захід від величної брами Айронфорджа служить дієвим редутом племені тролів Морозогривів. Поділений на два табори обабіч провалля й з'єднаний дерев'яним прогоном, анклав пильно охороняють тролі-збирачі та їхні приручені гірські вепри. Близькість до головної дороги та дворфської столиці робить його постійною загрозою для мандрівників і гірських патрулів, які мусять повсякчас остерігатися зухвалих набігів із висоти."},{t="Ціна мерехтливого зілля",b="Окрім вигідного розташування, хребет славиться мерехтливим зіллям — рослиною, яку вирощують тролі Морозогриви. Місцеві дворфські пивовари цінують його для міцних, насичених високогірних елів, а деінде його так просто не збереш. Відважні горяни та молоді новобранці часто ризикують потрапити в засідку Морозогривів чи під ікла диких вепрів лише заради того, щоб зібрати свіжі кошики дорогоцінної рослини просто з тролячих грядок."}},faq={{q="Де розташований Мерехтливий Хребет?",a="Мерехтливий Хребет — на півночі Дун Мороґу, просто на захід від величезної Брами Айронфорджа, що веде до дворфійської столиці.",al={"розташування мерехтливого хребта","де мерехтливий хребет","знайти мерехтливий хребет"}},{q="Хто тримає Мерехтливий Хребет?",a="Хребет займає місцеве плем'я тролів-Морозогривів: вони отаборилися двома таборами, сполученими мостом, і боронять висоти разом зі своїми прирученими вепрами.",al={"хто на мерехтливому хребті","вороги мерехтливого хребта","тролі мерехтливого хребта"}},{q="Що таке мерехтлива трава й чому її шукають?",a="Мерехтлива трава — особлива гірська рослина, що буяє на холодних схилах хребта. Місцеві дворфійські пивовари дуже її цінують як неодмінний складник особливих, смачних рецептів гірського елю.",al={"навіщо мерехтлива трава","що таке мерехтлива трава","призначення мерехтливої трави"}},{q="Чому дворфи не виженуть тролів остаточно?",a="Військо Айронфорджа зайняте ширшою обороною й зовнішніми справами, тож місцеві загрози на кшталт таборів Морозогривів у Дун Мороґу полишено місцевим горянам і заїжджим новобранцям.",al={"чому айронфордж ігнорує мерехтливий хребет","айронфордж проти морозогривів","відповідь дворфів на мерехтливий хребет"}}},fp="13,282,22.510.0,24.439.0,31.140.0,27.168.0,47.205.0,54.202.0"}
P.entries["subzone:shimmering-flats"] = {n="Мерехтливі Низини",s="Мерехтливі Низини — безкраї солончаки на південно-східному краю Тисячі Голок, на межі з пустелею Танаріс. Колись тут було дно прадавнього озера, а тепер ця випалена сонцем рівнина славиться шаленими механічними змаганнями на Перегонах Міражу та суворими пустельними звірами.",h="Мерехтливі Низини — безкраї солончаки на південно-східному краю Тисячі Голок, на межі з пустелею Танаріс.",kw={"мерехтливі низини","солончаки","перегони міражу","гоблінська інженерія","гномська інженерія","силітиди"},ang={["profession:Engineering"]="Солончаки — місце прощі для інженерів: тут усе всіяне брухтом, тут випробовують пальне й ганяють машини на шаленій швидкості, і все це живить нескінченне суперництво гоблінських і гномських механіків.",["race:Gnome"]="На Перегонах Міражу гномські пілоти та механоступи відважно обстоюють гордість гномської інженерії проти нестабільних, вибухових конструкцій суперників-гоблінів."},sec={{t="Ложе солі та швидкості",b="Мерехтливі Низини простягаються під сліпучим південним сонцем — величезне висохле дно озера без жодної рослинки, де тут і там біліють вибілені сонцем кістки черепах і навіть дерев'яний остов прадавнього вітрильника. Цілковито рівна, без жодного горбка поверхня робить низини найкращим на Калімдорі полігоном для експериментальних машин. У самому центрі солончаків лежать Перегони Міражу, де гноми й гобліни-винахідники безупинно змагаються, чиї ракетні автомобілі, гірокоптери й двигуни розженуться найшвидше, — і часто це закінчується вогняними аваріями та димними вирвами на білій кірці."},{t="Небезпеки солончаків",b="Окрім ревіння двигунів на трасі, улоговина зовсім не мирна. Загартовані василіски, агресивні скорпіди й стерв'ятники, що кружляють у небі, полюють на все, що сповільнюється на відкритому просторі. Південніше земля стає підступною довкола Розкопок Іржавого Молота. Спершу їх розробляли дворфійські рудошукачі, потім за них змагалася Орда, а тоді кар'єр зовсім покинули: кайла пробили підземні тунелі, і на південний край низин вирвався рій лютих силітидів."}},faq={{q="Звідки посеред пустелі розбитий корабель?",a="Колись Мерехтливі Низини були величезним внутрішнім озером, що давно висохло. Корабельні уламки на півночі низин — пам'ять про ту давню водойму, що лишилася, коли озеро випарувалося й обернулося на безкраї солончаки, які видно нині.",al={"корабель на мерехтливих низинах","човен на солончаках","розбитий човен у тисячі голок"}},{q="Чому тут разом гноми й гобліни?",a="Суцільна пласка соляна кірка — ідеальна місцевість для випробувань реактивних автомобілів і найновіших механізмів. Замість воювати за землю, місцеві гноми й гобліни влаштували Перегони Міражу, щоб підживлювати своє технічне суперництво, безкінечно намагаючись перевершити одне одного в швидкості, інженерії й безрозсудній відвазі.",al={"історія перегонів","чому вони змагаються","гноми й гобліни на солончаках"}},{q="Що сталося з дворфійськими розкопками на півдні?",a="Розкопки Растмолів заклали дворфи-археологи, на яких невдовзі напав загін Орди на чолі з Моктаром Кріном. А тоді копачі ненароком пробилися в підземний вулик силітидів, випустивши рої комашиних жахіть, що прогнали всіх і заполонили південь низин.",al={"історія растмолу","що сталося з растмолом","комахи на солончаках"}},{q="Куди веде дорога через Мерехтливі Низини?",a="Якщо йти слідами на південний схід через солончаки, вийдете просто до гірського перевалу, що відкривається в неозору пустелю Танарісу й до нейтрального порту Ґаджетзан.",al={"куди веде мерехтлива низина","як дістатися до танарісу","вихід у танаріс"}}},fp="16,303,23.588.0,19.504.0,59.255.0,41.336.0,51.298.0,54.164.0"}
P.entries["subzone:shining-strand"] = {n="Осяйне Узмор'я",s="Осяйне Узмор'я — смуга берега Озера Лордамер на сході Срібнолісся, що тягнеться на південь від Руїн Лордерона до суворих передгір'їв Альтерака. Колись тут панували агресивні мурлоки-Темноплавці, а тепер береги стали спірною землею, де табори Відступників стежать за водою й сходяться в сутичках із воргенами, що наступають.",h="Осяйне Узмор'я — смуга берега Озера Лордамер на сході Срібнолісся, що тягнеться на південь від Руїн Лордерона...",kw={"осяйне узмор'я","озеро лордамер","темноплавці","аптекар берард","нова чума","срібнолісся"},ang={["faction:Horde"]="Узмор'я — зручний, хоч і небезпечний, шлях уздовж Озера Лордамер, що з'єднує північні підступи до Срібнолісся з переходами до Гір Альтерак.",["race:Undead"]="Утримання Осяйного Узмор'я захищає південний озерний фланг Андерсіті й дає цінні зразки для досліджень нової чуми, які веде Королівське Аптекарське Товариство."},sec={{t="Спірне узбережжя",b="Осяйне Узмор'я, що тягнеться східним краєм Срібнолісся, межує з туманними водами Озера Лордамер. Колись плем'я мурлоків-Темноплавців заснувало на цих мілинах кілька агресивних поселень, і кожен, хто намагався йти дорогою вздовж озера, наражався на смертельну небезпеку. Хоч Темноплавці здебільшого перебралися на схід, до Світанкових Островів, на березі аж ніяк не спокійно. Розвідники й аптекарі Відступників закріпилися на узмор'ї, відбиваючись від диких воргенів, що виходять із глибини лісу, і пильно стежачи і за водами, і за пагорбами на межі з Альтераком."},{t="Алхімічний урожай",b="Окрім стратегічного розташування між Лордероном і південними кордонами, Осяйне Узмор'я та сусідні води рано привернули увагу Королівського Аптекарського Товариства. Покійний Аптекар Берард записував спостереження про дивні затверділі пухлини, вирізані в місцевих мурлоків-Темноплавців, і припускав, що їхня спотворена будова може стати цінним каталізатором для нової чуми молодої держави Сильвани Віндраннер."}},faq={{q="Де розташоване Осяйне Узмор'я?",a="Осяйне Узмор'я — східне узбережжя Срібнолісся на березі Озера Лордамер. Воно починається трохи на південь від Руїн Лордерона й упирається в нерівні пагорби, що відділяють Срібнолісся від Гір Альтерак.",al={"розташування осяйного узмор'я","де осяйне узмор'я","узбережжя сілверпайну"}},{q="Які небезпеки чатують на Осяйному Узмор'ї?",a="Табори Відступників на узмор'ї раз у раз відбиваються від воргенів, що виходять із лісів Срібнолісся. Колись мурлоки-Темноплавці мали на березі опорні пункти, але більшість із них перебралася на сусідні Світанкові Острови, хоча на мілинах досі чатують водяні загрози.",al={"монстри осяйного узмор'я","що на осяйному узмор'ї","вороги осяйного узмор'я"}},{q="Чому цей край цікавить Королівське Аптекарське Товариство?",a="Покійний Аптекар Берард записав, що місцеві мурлоки-Темноплавці мають затверділі пухлини з особливими властивостями. Товариство побачило в цих наростах перспективний складник для своїх досліджень, спрямованих на створення нової смертоносної чуми.",al={"аптекар берард","чума осяйного узмор'я","пухлина нової чуми"}},{q="Куди поділися місцеві мурлоки?",a="Під натиском Відступників, що зачищали узбережжя, плем'я Темноплавців перенесло свої головні табори із суходолу на Світанкові Острови посеред Озера Лордамер.",al={"де мурлоки сілверпайну","розташування віл фіна","мурлоки осяйного узмор'я"}}},fp="14,349,21.638.0,18.433.1,36.238.0,48.285.0,60.241.0,31.175.0"}
P.entries["subzone:shrine-of-aessina"] = {n="Святилище Аессіни",s="Святилище Аессіни — священна ельфійська пам'ятка в лісах південно-західного Ашенвалю, присвячена давньому духові лісу, природи й диких створінь. Воно лежить між Постом Маестри й Астранааром і лишається тихим прихистком серед дедалі гостріших прикордонних чвар.",h="Святилище Аессіни — священна ельфійська пам'ятка в лісах південно-західного Ашенвалю, присвячена давньому...",kw={"святилище аессіни","аессіна","дика богиня","святилище","ашенваль"},ang={["class:Druid"]="Давнє святилище на честь живого духу диких лісів має глибоке значення для тих, хто присвятив себе збереженню природної рівноваги Калімдору.",["race:NightElf"]="Для калдореїв святилище — уособлення століть гармонії з корінними духами Ашенвалю, якій тепер постійно загрожують чужі сили."},sec={{t="Святилище глибокого лісу",b="Святилище Аессіни, що сховалося на захід від Астранаару, вшановує таємничу Дику Богиню — утілення серця й духу глибоких лісів. Покоління нічних ельфів та їхніх лісових родичів шанували це тихе місце, єднаючись тут із природою далеко від гамірних доріг. Проте тепер, коли Орда проникає в Ашенваль, щоб рубати ліс і закріплюватися, мир у священних місцях по всьому краю став хитким."}},faq={{q="Хто така Аессіна?",a="Аессіна — шанований давній дух природи й Дикий Бог, пов'язаний із серцем незайманих лісів. Нічні ельфи й лісові створіння вшановують її як живу душу природи, втілення дикої пущі.",al={"лор аессіни","хто така аессіна","святилище богині аессіни"}},{q="Де розташоване Святилище Аессіни?",a="Святилище лежить на південному заході Ашенвалю, на південний захід від Посту Маестри й на захід від поселення Астранаар.",al={"розташування святилища аессіни","де святилище аессіни","знайти святилище аессіни"}},{q="Чому це місце важливе для нічних ельфів?",a="Святилище — давня свята обитель, присвячена лісовим духам. Такі місця безпосередньо пов'язують суспільство нічних ельфів і друїдські традиції з дикою природою Калімдору.",al={"важливість святилища аессіни","священне місце нічних ельфів"}}},fp="17,295,29.432.0,15.208.0,39.121.0,49.188.0"}
P.entries["subzone:shrine-of-the-dormant-flame"] = {n="Святиня Приспаного Полум'я",s="На найвищій вершині на північний захід від Долини Випробувань стоїть Святиня Приспаного Полум'я — відлюдне святилище, яке шанують шамани Орди. Під проводом його самотнього хранителя Телфа Джулама посвячувані здійснюють небезпечний підйом, щоб поспілкуватися зі стихією вогню й довести свою духовну майстерність.",h="На найвищій вершині на північний захід від Долини Випробувань стоїть Святиня Приспаного Полум'я — відлюдне...",kw={"святиня приспаного полум'я","шамани","вогонь","вогняний тотем","телф джулам","вершина","дуротар"},ang={["class:Shaman"]="Кожен молодий шаман з орків чи тролів має здійснити виснажливий підйом на цю скелю, щоб розпалити духовний зв'язок із вогнем і здобути свій Вогняний Тотем.",["faction:Horde"]="Схована в горах над Дуротаром, ця відлюдна святиня зберігає прадавні стихійні обряди, життєво важливі для духовного серця нової Орди."},sec={{t="Вершина випробування й полум'я",b="Щоб дістатися Святині Приспаного Полум'я, треба здолати вузьку звивисту стежку, що починається біля Річки Південної Люті на південно-західному краю її водозбору. Високо над червоними скелями Дуротару гірська вершина відкриває панорамний краєвид на околиці, та один хибний крок над прірвою означає певну смерть. У цьому тихому прихистку блукає Телф Джулам — самотній відлюдник, якому доручено наглядати за священними обрядами. Для майбутніх шаманів з орків і тролів, що проходять обряд Поклику Вогню, жаровня святині — горнило, де вони мають розпалити приспане вугілля жариною переможеного елементаля, доводячи, що здатні спілкуватися з руйнівними духами полум'я й шанувати їх."}},faq={{q="Як дістатися до Святині Приспаного Полум'я?",a="Стежка починається біля Річки Південної Люті, на південно-західному краю її водозбору, трохи на північний захід від Долини Випробувань. Вузька гірська стежка спіраллю обвиває вершину й веде просто нагору.",al={"як дістатися до святині приспаного полум'я","шлях до приспаного полум'я","піднятися на гору приспаного полум'я"}},{q="Чому ця святиня важлива для шаманів?",a="Святиня — священне місце, де шамани Орди вчаться розуміти стихію вогню й керувати нею. На шляху до Поклику Вогню новачки мусять піднятися на цю вершину, щоб приготувати обрядовий напій і розпалити приспану жаровню.",al={"призначення святині приспаного полум'я","чому шамани йдуть сюди","святиня поклику вогню"}},{q="Хто такий Телф Джулам?",a="Телф Джулам — самотній троль-відлюдник, хранитель святині. Він провадить молодих шаманів крізь випробування, варить вогняний напій, що пробуджує їхній духовний зір, і випробовує їхню рішучість.",al={"хто такий телф джулам","нпс приспаного полум'я","хранитель святині"}},{q="Що буде, коли розпалиш жаровню?",a="Шамани, що зібрали потрібні обрядові складники й здолали ворожого вогняного елементаля, кладуть його палаючу жарину в жаровню. Це пожертва, що доводить: вони мають досить сили й дисципліни, щоб приборкати непокірний дух полум'я.",al={"жаровня приспаного полум'я","розпалити полум'я","завдання жаровні святині"}}},fp="27,297,27.723.0,49.218.0,39.242.0,19.211.0,41.245.0"}
P.entries["subzone:shrine-of-the-fallen-warrior"] = {n="Святиня Полеглого Воїна",s="На відлюдному кряжі на захід від Перехрестя лежить Святиня Полеглого Воїна — тихий пам'ятник, з якого видно безкраї червоні савани Пусток. Тут стоїть кам'яний постамент з ініціалами «МК» і спочиває тіло полеглого орка-воїна, а оберігає це місце лагідний Цілитель Духів на ім'я Койтер.",h="На відлюдному кряжі на захід від Перехрестя лежить Святиня Полеглого Воїна — тихий пам'ятник, з якого видно...",kw={"святиня полеглого воїна","цілитель духів","койтер","пам'ятник","перехрестя","пустки"},ang={["class:Warrior"]="Воїни всіх рас часто приходять на цей пагорб у тихе паломництво, щоб віддати шану полеглому братові по зброї, який хоробро бився, перш ніж стати легендою.",["faction:Horde"]="Це самотнє місце спочинку в самому серці земель Орди втілює честь, обов'язок і жертовність, на яких тримаються шаманські й воїнські традиції Калімдору."},sec={{t="Тиха варта",b="Святиня Полеглого Воїна, що сховалася високо на пагорбах на північний захід від Перехрестя, — напрочуд урочистий прихисток серед пилу й небезпек Пусток. Щоб знайти її, мандрівникам доведеться піднятися звивистою стежкою на південний захід від вершини, аж до пологого кургану. На його верхівці стоїть різьблений кам'яний пам'ятник, на постаменті якого вирізьблено ініціали «МК». Перед ним спочиває закутий в обладунки орк-воїн, а вдень і вночі його стереже Цілитель Духів на ім'я Койтер. Тут не сурмлять бойові роги — лише тиша й роздуми на честь героя, що колись ходив землями Калімдору."},{t="Значення пам'ятника",b="У самому світі гри святиня — незгасна шана полеглому герою Орди, чия душа перебуває під опікою духів. Поза ним пам'ятник — щира данина, яку художники гри створили на честь Мішеля Койтера, улюбленого ілюстратора, що пішов із життя під час розробки світу. Спочилий воїн точно повторює власного бета-персонажа Койтера, Твінкрузера, — і так його присутність назавжди закарбована під відкритим небом Калімдору."}},faq={{q="Де розташована Святиня Полеглого Воїна?",a="Святиня стоїть на вершині пагорба на захід від Перехрестя на півночі Пусток. Щоб дістатися туди, знайдіть підніжжя кряжа на південний захід від узвишшя й ідіть звивистою стежкою вгору, до трав'янистого горбка.",al={"розташування святині","де святиня","як дістатися до святині полеглого воїна"}},{q="Хто той орк, що лежить на постаменті?",a="У грі він уособлює шанованого полеглого воїна. Насправді ж його створено за образом Твінкрузера — орка-воїна, яким грав покійний художник Blizzard Мішель Койтер на ранніх етапах розробки.",al={"хто мертвий орк","особа полеглого воїна","твінкрузер"}},{q="Що означає вирізьблене на камені «MK»?",a="Рунічні ініціали «MK» вшановують Мішеля Койтера — провідного художника, що помер у 2004 році під час створення світу гри.",al={"що означає мк","ініціали мк","літери на камені"}},{q="Хто той Цілитель Духів, що стоїть біля святині?",a="Цілителя Духів звуть Койтер. На відміну від звичайних Цілителів Духів, яких бачать лише духи загиблих, Койтер стоїть на чатах, і його добре бачать живі мандрівники, що піднімаються на пагорб.",al={"цілитель духів койтер","ангел біля святині","хто привид"}},{q="Чи пов'язані з цією святинею якісь завдання?",a="Ні. Святиня Полеглого Воїна не входить до жодного ланцюжка завдань чи протистояння фракцій. Це лише урочисте місце роздумів, пам'яті й шани.",al={"завдання святині","завдання полеглого воїна","чи є тут завдання"}}},fp="28,327,14.608.0,27.487.0,50.210.0,37.199.0,46.121.0,52.209.0,49.162.0"}
P.entries["subzone:si-7-stormwind-city"] = {n="SI:7 (Стормвінд)",s="Захований у східному куті Старого Міста, цей непоказний кам'яний маєток містить штаб SI:7 — елітної служби розвідки й шпигунства Королівства Стормвінд. За його важкими дверима очільник шпигунів Майстер Матіас Шоу та його старші агенти тихо стежать за загрозами королівству й керують таємними агентами по всій країні.",h="Захований у східному куті Старого Міста, цей непоказний кам'яний маєток містить штаб SI:7 — елітної служби...",kw={"si:7","розвідка","матіас шоу","старе місто","шпигуни","стормвінд"},ang={["class:Rogue"]="Для розбійників Альянсу будівля SI:7 — важливий професійний осередок, де можна пройти поглиблене навчання, придбати отрути й отримати таємні доручення просто від очільника шпигунів Матіаса Шоу.",["faction:Alliance"]="Як невидимий фундамент оборони Стормвінда, розвідувальна мережа SI:7 забезпечує військо Альянсу важливими відомостями про загрози трону."},sec={{t="Серце шпигунства королівства",b="To the casual passerby in Old Town, this fortified stone structure looks little different from a standard manor or military barracks. In truth, it serves as the nerve center for Stormwind Intelligence, Section 7. Directed by Master Mathias Shaw, SI:7 gathers intelligence, conducts surveillance, and executes covert operations to protect the kingdom from subversion. While the city guard patrols the open cobblestones and the Royal Guard defends Stormwind Keep, SI:7 works in the margins, training handlers and dispatching stealthy operatives against foreign enemies, saboteurs, and domestic unrest alike."},{t="Пильне око в тінях",b="Король Варіан Рінн загадково зник, а Братство Дефіас сіє хаос у Вестфолі й Сутінколіссі, тож у штабі безупинно вирує таємна робота. Донесення стікаються сюди від глибоко законспірованих розвідників з усіх людських земель. У підвалах і тренувальних залах, обвішаних зброєю, відточують смертоносні прийоми й роздають завдання, щоб знешкодити загрози задовго до того, як вони дістануться тронної зали короля-хлопчика."}},faq={{q="Що таке SI:7?",a="SI:7 — це Розвідка Стормвінда, Відділ 7. Це найкраща служба таємного шпигунства, розвідки й ліквідацій на службі корони Стормвінда.",al={"що таке сі:7","хто такі сі:7","значення сі:7"}},{q="Хто очолює SI:7 у Стормвінді?",a="Організацію очолює з цієї будівлі Майстер Матіас Шоу. Він наглядає за всіма польовими завданнями, мережами розвідки й стратегічною розвідкою для корони.",al={"лідер сі:7","бос сі:7","хто керує сі:7"}},{q="Де в місті розташована ця будівля?",a="Штаб — у Старому Місті, на південно-східному краю кварталу, біля каналу й тренувальних дворів.",al={"де сі:7","розташування сі:7","як дістатися до сі:7"}},{q="Чому SI:7 так цікавиться Вестфолом?",a="SI:7 стежить за підривною діяльністю по всіх землях Стормвінда, а Братство Дефіас — найнебезпечніше повстання в королівстві. Люди Шоу розставили по Вестфолу агентів під прикриттям і розвідників, щоб вистежити проводирів Братства й перерізати його шляхи постачання.",al={"братство дефіас сі:7","чому сі:7 стежить за дефіасом"}}},fp="21,345,32.605.0,29.438.1,13.159.0,28.175.0,43.127.0,38.297.0"}
P.entries["subzone:silver-stream-mine"] = {n="Шахта Срібного Потоку",s="Шахта Срібного Потоку — вичерпана дворфійська копальня на півночі Лох Модану, між Станцією Алґаз і Каменетесною Греблею. Колись багата срібна жила королівства Айронфордж, вироблену порожнину перетворили на склад Ліги Шахтарів, доки її не заполонила паскудь. Сьогодні в тунелях засіли кобольди Тунельні Пацюки, що ховають викрадене спорядження й рідкісні мінеральні дивовижі.",h="Шахта Срібного Потоку — вичерпана дворфійська копальня на півночі Лох Модану, між Станцією Алґаз і...",kw={"шахта срібного потоку","кобольди","ліга шахтарів","заряджені самоцвіти розлому","лох модан"},ang={["class:Mage"]="Учні магів спускаються в небезпечні тунелі, повні кобольдів, саме по Заряджені Самоцвіти Розлому — незамінний інгредієнт для ритуальних шат.",["race:Dwarf"]="Для дворфів Шахта Срібного Потоку — прикра втрата здобутого тяжкою працею господарства: незграбні кобольди тепер паскудять шановний склад айронфорджської Ліги Шахтарів."},sec={{t="Від багатої жили до складу",b="Колись Шахта Срібного Потоку давала багато цінної руди, щедро поповнюючи запаси срібла Айронфорджа. З часом дворфійські кайла вгризлися так глибоко, що вичерпали головні жили, і розлогі зали перетворилися на порожній підземний комплекс. Замість кидати здобуті тяжкою працею виробки, Ліга Шахтарів обернула шахти на надійний склад для інструментів, ящиків рудокопів і спорядження з усього краю. Це також єдине відоме джерело рідкісних Заряджених Самоцвітів Розлому, по які приходять допитливі знавці таємної магії, шукаючи тонких кравецьких інгредієнтів."},{t="Навала кобольдів",b="Тихий склад недовго лишався безпечним. Агресивні кобольди Тунельні Пацюки, яких привабив запах занедбаних інструментів, воску свічок і забутих підземних щілин, хмарою ринули в шахти. Доглядачів із Ліги Шахтарів швидко вигнали на холод Лох Модану. Тепер кобольди з шаленим запалом стережуть вкрадені дворфійські ящики, а біля задніх входів забуто лежать старі розтрощені орківські катапульти й вози — мовчазні нагадування про давніші прикордонні сутички."}},faq={{q="Для чого спершу використовували Шахту Срібного Потоку?",a="Спершу це була прибуткова срібна копальня дворфів Айронфорджа. Коли жили вичерпалися, Ліга Шахтарів Айронфорджа перетворила порожні підземні зали на склад інструментів і приладдя для розкопок.",al={"що таке шахта срібного потоку","історія срібного потоку","навіщо збудували срібний потік"}},{q="Хто нині займає шахту?",a="Шахту цілком заполонили кобольди-Тунельні Пацюки. Вони прогнали дворфів-доглядачів і тепер стережуть тунелі, ховаючи покинуті ящики Ліги й вишкрібаючи останні рештки руди.",al={"хто в шахті срібного потоку","моби срібного потоку","що всередині срібного потоку"}},{q="Навіщо маги ходять до Шахти Срібного Потоку?",a="Шахта — єдине відоме джерело Заряджених Самоцвітів Розлому. Ці непостійні камені, чутливі до магії, шукають чарівники Альянсу, щоб ткати могутні зачаровані мантії.",al={"завдання магів срібний потік","заряджені самоцвіти розлому","мантії магів срібного потоку"}},{q="Що за зруйновані катапульти за шахтою?",a="За шахтою стоять розбиті оркські вози й зруйновані катапульти — вивітрені рештки давніших воєн, що колись загрожували шляхам між Лох Моданом і північними гірськими перевалами.",al={"орківські вози за срібним потоком","зламані катапульти лох модан","облогові машини орди лох модан"}}},fp="18,394,31.556.0,20.490.0,52.233.0,32.202.0,42.169.0,46.195.0"}
P.entries["subzone:silverwind-refuge"] = {n="Притулок Срібного Вітру",s="Притулок Срібного Вітру — тихе поселення нічних ельфів у південно-центральному Ашенвалі, трохи на північ від Озера Містраль. Під захистом Вартових і союзних водяних елементалів воно гостинно приймає мандрівників на лісових стежках.",h="Притулок Срібного Вітру — тихе поселення нічних ельфів у південно-центральному Ашенвалі, трохи на північ від...",kw={"притулок срібного вітру","озеро містраль","корчма","травництво","вартові","ашенваль"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що перетинають Ашенваль, Притулок Срібного Вітру — надійний табір, де можна відпочити, поповнити припаси й підучити ремесла, не йдучи аж до Астранаару.",["profession:Herbalism"]="Притулок — важлива зупинка в Ашенвалі для збирачів: тут можна навчитися травництва просто на місці, серед багатої флори Озера Містраль."},sec={{t="Лісовий прихисток",b="Притулок Срібного Вітру, що лежить між спокійними водами Озера Містраль і Озером Ірисів на півночі, — поряд з Астранааром один із головних перевалочних пунктів нічних ельфів у центральному Ашенвалі. Тут є затишна корчма, ремісники та наставники, які навчають мандрівників травництва, алхімії, білування й полювання. Під охороною стійких Вартових і місцевих духів води цей прихисток — мирна зупинка для союзників, що мандрують тінистим прадавнім лісом."}},faq={{q="Хто тримає Притулок Срібного Вітру?",a="Притулок Срібного Вітру — поселення Альянсу, яке збудували й утримують нічні ельфи. Його пильно охороняють Вартові, а також водяні елементалі, що допомагають берегти ці спокійні угіддя.",al={"хто володіє притулком срібного вітру","чи срібний вітер альянсу чи орди","хто живе в срібному вітрі"}},{q="Де розташований Притулок Срібного Вітру?",a="Він на півдні центрального Ашенвалю, просто на північ від Озера Містраль і на південь від Озера Ірисів.",al={"розташування притулку срібного вітру","де притулок срібного вітру","як дістатися до срібного вітру"}},{q="Які послуги є в притулку?",a="Мандрівники знайдуть тут корчму, крамарів і наставників травництва, алхімії, білування та мисливських умінь.",al={"що в притулку срібного вітру","наставники срібного вітру","торговці срібного вітру"}}},fp="17,253,18.477.0,31.191.0,35.107.0,38.147.0"}
P.entries["subzone:silverwing-grove"] = {n="Гай Срібнокрилих",s="Гай Срібнокрилих, що сховався в південно-центральному Ашенвалі біля Озера Впалого Неба, — місце збору Вартових Срібнокрилих. З цієї укріпленої улоговини воїни нічних ельфів збирають сили Альянсу, щоб відкинути лісорубів клану Бойової Пісні, які прорубуються крізь ліс.",h="Гай Срібнокрилих, що сховався в південно-центральному Ашенвалі біля Озера Впалого Неба, — місце збору...",kw={"гай срібнокрилих","вартові срібнокрилих","ущелина бойової пісні","альянс","ашенваль"},ang={["faction:Alliance"]="Гай — головне місце збору для героїв Альянсу, які готуються вступити в криваві сутички в Ущелині Бойової Пісні.",["race:NightElf"]="Для калдореїв Гай Срібнокрилих — утілення непохитної рішучості зупинити нищення священних дерев сокирами клану Бойової Пісні."},sec={{t="Передова лісової війни",b="Гай Срібнокрилих, захований під смарагдовими кронами на південний захід від Застави Срібнокрилих, — важливий військовий плацдарм Вартових Срібнокрилих. Це не тихий лісовий притулок, а бойове серце запеклої боротьби нічних ельфів за землю проти лісорубень Орди в Ущелині Бойової Пісні. Тут збираються високі офіцери Альянсу, припаси й розвідники: звідси організовують сутички й скликають героїв боронити прадавній Ашенваль від орківської експансії."}},faq={{q="Для чого потрібен Гай Срібнокрилих?",a="Гай Срібнокрилих — плацдарм Вартових Срібнокрилих. Тут військо нічних ельфів та їхні союзники з Альянсу організовують опір вирубці лісу кланом Бойової Пісні й вирушають у нескінченне протистояння в Ущелині Бойової Пісні.",al={"чому тут гай срібнокрилих","що таке гай срібнокрилих","призначення гаю срібнокрилих"}},{q="Де розташований Гай Срібнокрилих?",a="Він на півдні центрального Ашенвалю, на південний захід від Застави Срібнокрилих і трохи на захід від Озера Впалого Неба.",al={"розташування гаю срібнокрилих","де гай срібнокрилих","як знайти гай срібнокрилих"}},{q="Хто діє з Гаю Срібнокрилих?",a="У гаю стоять Вартові Срібнокрилих разом із військовими командирами Альянсу — зокрема Бригадним Генералом Альянсу, — інтендантами й офіцерами на кшталт Вартової Фарсонг, які керують боротьбою з Ордою.",al={"хто в гаю срібнокрилих","нпс гаю срібнокрилих","хто керує гаєм срібнокрилих"}},{q="Чи можуть гравці Орди увійти до Гаю Срібнокрилих?",a="Ні. Гай — діюча військова застава, повна ворожих вартових Альянсу, які одразу нападуть на будь-яких членів Орди, що наблизяться.",al={"чи ворожий гай срібнокрилих","чи може орда в гай срібнокрилих","орда гай срібнокрилих"}}},fp="16,273,28.504.0,40.250.0,34.116.0,37.228.0,41.159.0"}
P.entries["subzone:silverwing-outpost"] = {n="Застава Срібнокрилих",s="Застава Срібнокрилих — укріплений гарнізон нічних ельфів у південно-центральному Ашенвалі, на схід від Річки Фалфаррен. Під командуванням Дуріель Мунфаєр це найсхідніший оплот Альянсу проти Орди в спірному лісі.",h="Застава Срібнокрилих — укріплений гарнізон нічних ельфів у південно-центральному Ашенвалі, на схід від Річки...",kw={"застава срібнокрилих","дуріель мунфаєр","вартові срібнокрилих","торек","фронт","ашенваль"},ang={["faction:Alliance"]="Застава Срібнокрилих — ваш важливий передовий редут на ордівському березі річки, що стримує розширення орків від Застави Розщепленого Дерева.",["faction:Horde"]="Для Орди застава — нестерпна скалка в боці Застави Розщепленого Дерева, що перекриває вам шляхи пересування й постачання південним Ашенвалем."},sec={{t="На схід від Фалфаррену",b="Застава Срібнокрилих, що лежить на південний захід від Застави Розщепленого Дерева й трохи на північ від кордону з Пустками, займає вкрай небезпечну позицію. Вона стоїть на східному березі Річки Фалфаррен — на запекло спірній території, яку патрулює Орда, — і прикриває собою володіння нічних ельфів у глибині лісу. Дуріель Мунфаєр та її Вартові Срібнокрилих перебувають у постійній облозі: орки неподалік сповнені рішучості цілком вигнати нічних ельфів із цього краю."},{t="Нескінченний фронт",b="Сутички довкола Застави Срібнокрилих — одні з найзапекліших в Ашенвалі. Бойові загони орків із Застави Розщепленого Дерева, як-от нападники під проводом Торека, раз у раз влаштовують засідки під стінами гарнізону. Для Орди знешкодити заставу конче необхідно, щоб убезпечити дорогу й розширити заготівлі без постійної загрози контрударів Вартових."}},faq={{q="Де розташована Застава Срібнокрилих?",a="Вона на півдні центрального Ашенвалю — на південний захід від Застави Розщепленого Дерева, на північ від кордону з Пустками й на східному боці Річки Фалфаррен.",al={"розташування застави срібнокрилих","де застава срібнокрилих","застава срібнокрилих на мапі"}},{q="Хто командує Заставою Срібнокрилих?",a="Заставою командує Дуріель Мунфаєр — офіцерка нічних ельфів, що очолює Вартових Срібнокрилих, які боронять східні краї лісу.",al={"лідер срібнокрилих","хто очолює заставу срібнокрилих","дуріел місячний вогонь"}},{q="Чому Орда так завзято атакує цю заставу?",a="Застава Срібнокрилих стоїть просто на східному боці Річки Фалфаррен, неподалік від Застави Розщепленого Дерева. Звідси Вартові можуть перерізати шляхи постачання Орди й безпосередньо загрожувати оркським справам в Ашенвалі.",al={"чому нападати на срібнокрилих","інтерес орди до срібнокрилих","сплінтертрі проти срібнокрилих"}},{q="Хто такі Вартові Срібнокрилих?",a="Вартові Срібнокрилих — войовничий орден воїтельок і мисливиць нічних ельфів, що присвятили себе захисту Ашенвалю від вторгнень — насамперед від лісозаготівельних таборів і бойових загонів Орди, що підступають дедалі ближче.",al={"що таке срібнокрилі","лор вартових срібнокрилих","фракція срібнокрилих"}}},fp="18,248,21.501.0,18.384.1,36.150.0,32.142.0,55.217.0,33.213.0"}
P.entries["subzone:sishir-canyon"] = {n="Каньйон Сішир",s="Каньйон Сішир — дика ущелина в Горах Кам'яного Кігтя, що прорізає шлях на схід крізь скелясті височини. Тут кишать жахливі глибокомохові павуки, а все довкола обснуване павутинням; це небезпечний підхід до Руїн Ельдре'тара. Ті, хто зважиться пройти його заплутаними глибинами, муситимуть мати справу з отруйними павуками та їхньою матір'ю виводку.",h="Каньйон Сішир — дика ущелина в Горах Кам'яного Кігтя, що прорізає шлях на схід крізь скелясті височини.",kw={"каньйон","павуки","бесселет","павутиння","руїни ельдре'тара","гори кам'яного кігтя"},ang={["class:Hunter"]="Небезпечне павутиння та отруйні глибокомохові павуки роблять Каньйон Сішир суворим випробуванням для мисливців, які вистежують і ловлять диких звірів у тісноті ущелини.",["race:NightElf"]="Захоплений павуками каньйон відрізає легкий і безпечний шлях до Руїн Ельдре'тара — спадщини предків, тож вартовим і вченим калдореїв доводиться пробиватися крізь густі павучі гнізда, щоб дістатися свого минулого."},sec={{t="Обснований прохід",b="Каньйон Сішир, що відгалужується від гірських доріг хребта Кам'яного Кігтя, — підступний природний коридор до прадавніх Руїн Ельдре'тара. Це зовсім не тиха гірська стежка: ущелину геть заполонили глибокомохові павуки. Їхні липкі шовкові полотнища та грона яєчних коконів укривають кам'янисту землю й скельні стіни, перетворюючи яр на живе гніздо. Мандрівники й вартові, що прямують до ельфійських руїн за ним, мусять прорубувати собі шлях крізь рої лютих павуків-ткачів."},{t="Володіння Бесселет",b="У найглибшому закутку каньйону чатує Бесселет — величезна й смертоносна матір виводку глибокомохових павуків. Її отрута й жахливі розміри наводять страх на кожного, хто намагається очистити прохід. Місцеві сили в Кам'яному Кігті насторожено стежать за каньйоном і попереджають шукачів пригод: хто полізе в обснувані закутки, зіткнеться не лише з розрізненими павуками, а й із верховним хижаком, що люто стереже свій виводок."}},faq={{q="Що таке Каньйон Сішир?",a="Каньйон Сішир — ущелина в Горах Кам'яного Кігтя, де кишать павуки: вона в'ється від головних гірських стежок до давніх Руїн Ельдре'тару.",al={"де каньйон сішир","розташування каньйону сішир"}},{q="Хто живе в каньйоні?",a="Каньйон цілком захопили хижі павуки Глибокого Моху. Вони вкрили яр густим павутинням і коконами з яйцями й полюють на все, що потрапляє в їхні володіння.",al={"монстри каньйону сішир","павуки каменекігтя"}},{q="Хто така Бесселет?",a="Бесселет — грізна павучиха-матріарх, що живе глибоко в Каньйоні Сішир. Вона очолює виводок Глибокого Моху й становить найбільшу загрозу для мандрівників, що проходять цим краєм.",al={"бесселет","гігантський павук каньйону сішир"}},{q="Куди веде Каньйон Сішир?",a="Якщо йти каньйоном на схід, вийдете просто до Руїн Ельдре'тару — давньої пам'ятки нічних ельфів високо в горах.",al={"що в кінці каньйону сішир","шлях крізь каньйон сішир"}}},fp="13,352,15.507.0,18.412.0,22.148.0,34.180.0,17.178.0,30.134.0"}
P.entries["subzone:skittering-dark"] = {n="Шурхотлива Пітьма",s="Шурхотлива Пітьма — покинута шахта й темна лісова улоговина на заході Срібнолісся. Її заполонили агресивні велетенські павуки, і печера та ліси довкола густо обплетені павутинням і небезпечні для необачних звірів і мандрівників.",h="Шурхотлива Пітьма — покинута шахта й темна лісова улоговина на заході Срібнолісся.",kw={"шурхотлива пітьма","павуки","шахта","кретіс","срібнолісся"},ang={["faction:Horde"]="Мандрівникам Орди в Срібноліссі варто це знати: павуки Шурхотливої Пітьми влаштовують засідки на необачну здобич, що забрідає з довколишніх лісів до їхніх обплетених павутинням лігв."},sec={{t="Обплетена павутинням улоговина",b="Шурхотлива Пітьма, що сховалася серед пагорбів трохи на схід від західного узбережжя Потоку Північного Припливу, колись була діючою шахтою. Сьогодні її штреки геть задушені павутинням і стали розлогим гніздом велетенських павуків. Біля входу никає тіниста прядильниця Кретіс, а павуки полюють на все, що підійде надто близько."}},faq={{q="Що таке Шурхотлива Пітьма?",a="Це покинута копальня на заході Срібнолісся, яку цілком заполонили велетенські павуки. Печери й довколишні дерева густо обплутані липким павутинням і кишать хижими павуками.",al={"шурхотлива пітьма шахта","що це за шахта","павуча печера сілверпайн"}},{q="Хто верховодить павуками в копальні?",a="Єдиного володаря цього виводку не відомо. Найстрашніший серед павуків — Кретіс Шедовспіннер, рідкісний і небезпечний прядильник, що нишпорить у копальні й довкола неї.",al={"бос павуків","бос шурхотливої пітьми","матріарх"}},{q="Де розташована Шурхотлива Пітьма?",a="Вона сховалася серед пагорбів на заході Срібнолісся, трохи на схід від узбережжя, відомого як Потік Північного Припливу.",al={"розташування шурхотливої пітьми","як знайти шурхотливу пітьму"}}},fp="15,240,15.324.0,28.197.0,34.159.0,37.117.0"}
P.entries["subzone:skull-rock"] = {n="Череп-скеля",s="Череп-скеля — печера в східних прибережних скелях Дуротару, просто на схід від Оргріммара. Вона служить укріпленим ковеном демонічного культу Палаючого Клинка просто під носом у столиці.",h="Череп-скеля — печера в східних прибережних скелях Дуротару, просто на схід від Оргріммара.",kw={"череп-скеля","печера","культисти","палаючий клинок","ґазз'уз","чорнокнижник","дуротар"},ang={["class:Warlock"]="Темні мистецтва, що практикують у Череп-скелі, показують нестримне поширення демонічного впливу, який Орда Тралла прагне викорінити й узяти під контроль.",["faction:Horde"]="Очистити Череп-скелю від культистів украй важливо, щоб убезпечити прибережні підступи до Дуротару й захистити Оргріммар від підривної діяльності зсередини."},sec={{t="Лігво культистів",b="Схована під скелями північно-східного Дуротару, Череп-скеля — одна з найнебезпечніших твердинь культу Палаючого Клинка в цьому краї. Темні культисти, орки-шанувальники Скверни та прикликачі збираються глибоко у звивистих тунелях, щоб практикувати демонічні мистецтва й плести змови проти молодої Орди. Осередок очолює небезпечний чорнокнижник Ґазз'уз, чиї дії безпосередньо загрожують сусідній брамі Оргріммара та мандрівникам на східному узбережжі."}},faq={{q="Що таке Череп-скеля?",a="Череп-скеля — система печер на північному сході Дуротару, на узбережжі. Тут засіли сектанти Палаючого Клинка, що під її природним прикриттям плетуть змови проти Орди Тралла.",al={"печера череп-скеля","де череп-скеля","що в череп-скелі"}},{q="Хто тримає Череп-скелю?",a="Печеру заполонив культ Палаючого Клинка на чолі з орком-чорнокнижником Ґазз'узом, що засів у найглибшій залі печери.",al={"хто веде череп-скелю","хто керує череп-скелею","бос череп-скелі"}},{q="Чому ця печера турбує Орду?",a="Вона так близько до Оргріммара, що це серйозна загроза безпеці. Палаючий Клинок прагне підточити нове королівство Тралла й знову кинути орків у рабство до демонів.",al={"чому очищати череп-скелю","чому череп-скеля небезпечна"}}},fp="10,195,17.478.0,19.183.0,24.118.0,40.175.0"}
P.entries["subzone:slag-pit"] = {n="Шлакова Яма",s="Шлакова Яма — розлогі підземні копальні всередині Казана в Палючій Ущелині. Ними керують безжальні погоничі й работорговці Темного Заліза, а у вогняних тунелях під тінню Гори Блекрок гарують підневільні робітники. Непроханим гостям доведеться мати справу не лише з ворожими дворфами-наглядачами, а й із ненажерливими інцендозаврами, що нишпорять на нижніх рівнях.",h="Шлакова Яма — розлогі підземні копальні всередині Казана в Палючій Ущелині.",kw={"шлакова яма","казан","палюча ущелина","копальня","темне залізо","інцендозаври"},ang={["profession:Mining"]="Глибокі шахти Шлакової Ями врізаються просто в багате на мінерали черево Палючої Ущелини, тож тут можна розжитися добірною рудою — прибутково, хоч і надзвичайно небезпечно.",["race:Dwarf"]="Для дворфів Айронфорджа жорстокість работорговців Темного Заліза в Шлаковій Ямі — суворе нагадування про гірку прірву між кланами."},sec={{t="Підземна каторга",b="Шлакова Яма, вирубана в глибинах Казана, — невтомна промислова машина дворфів Темного Заліза в Палючій Ущелині. Вдень і вночі поневолених робітників женуть видобувати багаті руди й мінерали під батогом жорстоких наглядачів і погоничів. Тут важко й задушливо: усе заполонили пекуча спека, їдкий пил і брязкіт залізних кайл. Дворфи Темного Заліза тримають на своїх копальнях безжальну дисципліну й люто відбивають будь-яке втручання ззовні в постачання до Глибин Блекрок."},{t="Глибини ями",b="Окрім жорстокості работорговців, самі тунелі смертельно небезпечні і для робітників, і для непроханих гостей. На нижніх рівнях копалень земля розступається й відкриває розпечені печери, де живуть інцендозаври — люті рептилії, споконвічні мешканці вогняного підземелля. Попри постійну загрозу опинитися в пащі цих підземних хижаків, господарі з Темного Заліза женуть своїх робітників дедалі глибше в скелю, байдужі до життів, які це забирає."}},faq={{q="Де розташована Шлакова Яма?",a="Шлакова Яма — глибоко в Казані, величезному кратері розкопок у центрі Палючої Ущелини. Її тунелі розгалужуються просто під наземними копальнями.",al={"розташування шлакової ями","де шлакова яма","як дістатися до шлакової ями"}},{q="Хто тримає Шлакову Яму?",a="Копальнею цілком заправляє клан Темного Заліза. Рабовласники й наглядачі Темного Заліза патрулюють штольні, тримаючи всіх у жорсткій дисципліні й змушуючи бранців копати цілодобово.",al={"хто керує шлаковою ямою","фракція шлакової ями","темне залізо шлакова яма"}},{q="Чому раби нападають на зайд?",a="Поневолені робітники від природи не ворожі до чужинців, але страх перед господарями з Темного Заліза в них глибокий. Якщо поряд нападуть на рабовласника чи наглядача, перелякані робітники кинуться його захищати, щоб уникнути жорстокої кари.",al={"чому раби нападають","ворожі раби","раби-робітники агресивні"}},{q="Хто живе в Шлаковій Ямі?",a="Окрім дворфів Темного Заліза та їхніх рабів, у найглибших куточках ями кишать інцендозаври — агресивні ящероподібні хижаки з вогняною лускою, що нишпорять підземними тунелями.",al={"монстри шлакової ями","інсендозаври","звірі шлакової ями"}}},fp="8,370,17.539.0,17.505.0,30.181.0,26.185.0,42.256.0,36.197.0"}
P.entries["subzone:slaughter-hollow"] = {n="Лощина Різанини",s="Лощина Різанини — відлюдне огряче городище, заховане серед засніжених висот Гір Альтерак. Ним володіє брутальний клан Трощихребтів, і це радше грубий табір, ніж жваве поселення. Мандрівникам нема чого сюди потикатися, хіба що вони полюють на огрів або досліджують замерзлі гірські перевали.",h="Лощина Різанини — відлюдне огряче городище, заховане серед засніжених висот Гір Альтерак.",kw={"лощина різанини","альтерак","огри","хребтоломи","різз лусболт","бранці"},ang={["race:Gnome"]="Прикрий полон Різза Лусболта в Трощихребтів — суворе застереження для винахідників і розвідників, які блукають перевалами Альтерака непідготовленими."},sec={{t="Лігво огрів",b="Лощина Різанини, захована високо в горах на межі Гілсбреда й Альтерака, править за табір місцевим огрям-Трощихребтам. Як і безліч інших огрячих городищ на нагір'ї, вона завалена саморобними вогнищами, обгризеними кістками й грубими курінями. Тоді як за інші огрячі лігва в горах раз у раз спалахують сутички через землю чи вкрадені припаси, Лощина Різанини здебільшого лишається тихою — великі військові походи обходять її стороною."},{t="Бранці й мандрівники",b="Через свою відлюдність городище часом стає в'язницею для бідолашних бранців, схоплених на гірських стежках. Між мандрівниками ходять чутки про нещасного гнома на ім'я Різз Лусболт, що опинився тут замкненим у грубій клітці й намагається торгуватися з кожним перехожим. Таким нещасним бранцям рідко щастить устояти перед апетитом клану Трощихребтів."}},faq={{q="Що таке Лощина Різанини?",a="Лощина Різанини — табір огрів у Горах Альтерак, де живе клан Трощихребтів. Тут примітивні житла-кургани й вогнища, звичні для гірських огрських поселень.",al={"лор лощини різанини","що це за місце","лощина різанини гілсбрад"}},{q="Хто живе в Лощині Різанини?",a="У лощині живуть лише огри-Трощихребти — той самий клан, що тримає сусідні руїни Міста Альтерак і різні довколишні застави.",al={"хто тут","моби лощини різанини","хто контролює лощину різанини"}},{q="Чи є тут завдання?",a="Жодне офіційне завдання не посилає шукачів пригод просто до Лощини Різанини. Це здебільшого відлюдне лігво, на яке натрапляють, досліджуючи гори.",al={"завдання лощини різанини","чи є завдання в лощині різанини","навіщо йти сюди"}},{q="Хто той гном, що сидить тут у клітці?",a="У клітці в лощині тримають гнома на ім'я Різз Лусболт: він пропонує свій крам кожному, хто його знайде.",al={"різз лусболт","гном у клітці","торговець лощини різанини"}}},fp="16,307,14.439.0,22.381.0,25.183.0,30.145.0,26.151.0,29.112.0"}
P.entries["subzone:slaughtered-lamb"] = {n="Зарізане Ягня",s="Захована в Кварталі магів Стормвінда, таверна «Зарізане Ягня» здається лише тихим і сумнівним шинком. Але під її підлогою розлогі катакомби ховають святилище й тренувальні зали заборонених чорнокнижників Альянсу.",h="Захована в Кварталі магів Стормвінда, таверна «Зарізане Ягня» здається лише тихим і сумнівним шинком.",kw={"зарізане ягня","таверна","чорнокнижники","квартал магів","зардет","стормвінд"},ang={["class:Warlock"]="Катакомби внизу — ваш головний прихисток у Стормвінді: тут наставники класу, обряди підкорення демонів і завдання, без яких не опанувати темних мистецтв.",["faction:Alliance"]="Хоча Альянс стоїть за Світло й порядок, «Зарізане Ягня» відкриває мовчазну готовність королівства терпіти темну магію у своїй тіні."},sec={{t="Тонке прикриття",b="На поверхні «Зарізане Ягня» не пропонує нічого, крім темних кутків і нечисленних відвідувачів, яких обслуговує шинкар Джарел Мур, що радить випадковим гостям триматися подалі від тіней. І це попередження буквальне. Спустившись задніми ходами, можна знайти підземний комплекс склепів і кіл виклику, де людські чорнокнижники та їхні колеги, що перебралися сюди з Каз Модану, відкрито вивчають таємниці скверни, сховавшись від несхвальних очей Церкви Святого Світла й Кірін-Тору."},{t="Рахунок вельможі",b="Тримати осередок скверни в серці столиці — постійний ризик. Коли Лорд Баурлес К. Вішок дізнався про чорнокнижників у підвалі, він пригрозив підняти Дім Вельмож і звернутися до трону з вимогою повного розслідування. Насправді ж аристократ просто хотів відкрутитися від руйнівного рахунку за випивку. Перш ніж його галас привернув справжню увагу, Зардет із Чорного Кігтя влаштував так, що Вішок випив смертельне зілля, — і назавжди заткнув рота пройдисвітові, зберігши таємниці сховку."}},faq={{q="Що насправді відбувається під «Зарізаним Ягням»?",a="Катакомби під таверною — таємне святилище чорнокнижників Стормвінда. Знавці демонології й тіньової магії збираються там, щоб навчати учнів, викликати демонів і практикувати мистецтва Скверни, заборонені на вулицях нагорі.",al={"що під зарізаним ягням","підвал зарізаного ягняти","хто в зарізаному ягняті"}},{q="Чи знає міська варта Стормвінда про чорнокнижників?",a="Таверна тримається на хиткій завісі правдоподібного заперечення. Церква Святого Світла й Академія Магів глибоко не довіряють магії Скверни, тож ковен мусить діяти потай і рішуче затикати рота кожному, хто погрожує викрити його перед королівською владою.",al={"чи знає варта про чорнокнижників","чому чорнокнижників не арештовують","чи зарізане ягня незаконне"}},{q="Хто такий лорд Вішок і що з ним сталося?",a="Лорд Баурлес К. Вішок — вельможа й завсідник таверни, що викрив чорнокнижників, які ховаються внизу. Він здійняв галас у Домі Вельмож і домагався повного розслідування, сподіваючись переконати короля закрити заклад.",al={"баурлс вішок","доля лорда вішока","хто такий вішок"}},{q="Чому сюди приходять гноми-чорнокнижники?",a="After the fall of Gnomeregan, its warlock masters relocated to Ironforge, where Magni keeps a careful watch on them. Lago Blackwrench sends novices to Gakin the Darkbinder in the Slaughtered Lamb for training.",al={"гноми-чорнокнижники стормвінд","чорнокнижники каз модану"}}},fp="16,244,15.486.0,15.511.1,49.240.0,54.287.0,47.236.1,32.209.0"}
P.entries["subzone:slither-rock"] = {n="Звивиста Скеля",s="Звивиста Скеля — відлюдна печера в далеких північно-східних скелях Палаючих Степів, за небезпечним Шляхом Крил Жаху. Це самотній прихисток Сайруса Терепентуса, гострого на язик чорного драконорода з власними прихованими намірами.",h="Звивиста Скеля — відлюдна печера в далеких північно-східних скелях Палаючих Степів, за небезпечним Шляхом...",kw={"звивиста скеля","сайрус терепентус","драконород","палаючі степи","печера"},sec={{t="Відлюдна печера",b="Звивисту Скелю, сховану серед випалених скель за Шляхом Крил Жаху, легко не помітити посеред вогняних пустирів Палаючих Степів. Далеко від гуркітливих кузень і орчих ватаг Шпиля Блекрок у цій віддаленій печері живе самотній чорний драконород Сайрус Терепентус. Хоча драконороди зазвичай — люто віддані воїни чорного драконячого роду, Сайрус зберігає тут дивну, сварливу незалежність: він охоче розмовляє зі смертними мандрівниками, замість того щоб убивати їх на місці, — хоча й не скупиться на образи."}},faq={{q="Де розташована Звивиста Скеля?",a="Звивиста Скеля — у далекому північно-східному куті Палаючих Степів. Щоб дістатися до неї, мандрівникам доведеться пройти повз чорних драконячих створінь, що патрулюють Шлях Крил Жаху.",al={"розташування звивистої скелі","де звивиста скеля","знайти звивисту скелю"}},{q="Хто живе у Звивистій Скелі?",a="У печері живе Сайрус Терепентус — самотній чорний драконород. На відміну від більшості родичів, що одразу нападають на смертних, Сайрус охоче розмовляє з чужинцями, хоча вдачу має злу й зверхню.",al={"хто на звивистій скелі","моб звивистої скелі","нпс звивистої скелі"}},{q="Навіщо шукачеві пригод шукати цю печеру?",a="Шукачі пригод проходять небезпечним Шляхом Крил Жаху, щоб попросити в Сайруса Терепентуса поради й допомоги. Попри різку вдачу, драконород має спільних ворогів із мандрівниками, що протистоять чорному драконячому роду та його темним володарям.",al={"навіщо йти на звивисту скелю","завдання звивистої скелі","призначення сайруса"}}},fp="12,249,17.566.0,30.173.0,26.212.0,43.238.0"}
P.entries["subzone:slithering-scar"] = {n="Звивистий Шрам",s="Звивистий Шрам — розлогий вулик силітидів, що панує над південними кручами Кратера Ун'Ґоро. Це дім агресивного рою Ґоріші; його прориті тунелі й органічні шпилі — небезпечне вторгнення комах у первісну западину.",h="Звивистий Шрам — розлогий вулик силітидів, що панує над південними кручами Кратера Ун'Ґоро.",kw={"звивистий шрам","силітиди","ґоріші","вулик","ун'ґоро","кристалічні пілони"},ang={["class:Druid"]="Агресивне поширення вулика Ґоріші загрожує тендітній, неприборканій життєвій силі кратера, тож проти цієї неприродної навали треба бути пильними."},sec={{t="Вулик Ґоріші",b="Вигризений у червоній землі й скелях південного Ун'Ґоро, Звивистий Шрам стоїть чужорідним наростом серед буйного доісторичного краєвиду. Вуликом керують силітиди Ґоріші — організований різновид комахоподібних істот, що поточили кручі, наче соти, вологими норами й кладковими камерами. У цих підземних лабіринтах робітники й копачі доглядають величезні кладки яєць і личинок поряд із велетенськими виводками ос. Та ще тривожніше те, що колонія вирощує молодих силітидних колосів — жахливих велетнів, які мають прорубати собі шлях крізь усе живе в кратері. Дивні кристалічні утворення, вкраплені у вулик, пульсують неприродним резонансом і стають осередками темної, злагодженої волі колонії."},{t="Відсутній оберіг",b="Учені й дослідники, які обходять околиці Ун'Ґоро, часто помічають тривожну дивину в розташуванні вулика. Прадавні кристалічні пілони стоять на варті вздовж північної, східної та західної меж западини, але на півдні такого стовпа немає. Саме крізь цю незахищену прогалину Ґоріші й прокопалися всередину із сусідніх пустель. Чи силітиди навмисно підточили забутий південний оберіг, чи просто вдерлися туди, де первісний захист кратера був найслабшим, — досі лишається тривожною загадкою для тих, хто стежить за їхнім стрімким поширенням."}},faq={{q="Що таке Звивистий Шрам?",a="Це вулик силітидів, вирубаний у південних скельних стінах Кратера Ун'Ґоро, де живе рій Ґоріші.",al={"що це за місце","огляд звивистого шраму","вулик ун'ґоро"}},{q="Що тут роблять силітиди?",a="Рій Ґоріші риє величезні підземні тунелі, доглядає розплідні зали, повні личинок і яєць, і вирощує велетенських колосів силітидів, щоб запанувати над кратером.",al={"навіщо тут силітиди","мета силітидів ун'ґоро","ціль горішів"}},{q="Чому на півдні немає пілона, як в інших краях?",a="Північний, східний і західний краї Ун'Ґоро позначені давніми кришталевими пілонами, а на південній скелі їх немає. Звивистий Шрам з'явився саме там, де бракує цієї захисної межі.",al={"чому немає південного пілона","де південний пілон","пропущений південний пілон"}},{q="Які небезпечні створіння живуть у вулику?",a="Окрім легіонів робітників, розорювачів і жалоносців, Шрамом блукають колоси, що підростають, і горезвісно люті праматері, як-от Виводкова Матір Завас.",al={"боси вулика","помітні комахи","матір кладки завас"}}},fp="15,247,16.730.0,14.602.0,28.117.0,33.181.0,58.205.0,42.159.0"}
P.entries["subzone:sludge-fen"] = {n="Багнисте Болото",s="Багнисте Болото — отруйне промислове нафтове родовище Венчурної Компанії на північному сході Пусток. Колись тут було чисте, кришталево-блакитне озерце, але відколи гобліни звели бурові вишки й машини, водойма перетворилася на масну трясовину. Роботами керує Наглядач Луґвізл, і родовище постійно приваблює промислових шпигунів і диверсантів від суперників із Раджета.",h="Багнисте Болото — отруйне промислове нафтове родовище Венчурної Компанії на північному сході Пусток.",kw={"багнисте болото","венчурна компанія","наглядач луґвізл","нафта","подрібнювач","пустки"},ang={["class:Druid"]="Багнисте Болото — гидке свідчення неприродної експлуатації. Друїди Орди спускаються в його масні глибини під час Випробування Морського Лева, щоб здобути Половину Амулета Водної Спритності.",["profession:Engineering"]="Венчурна Компанія тримає тут передові подрібнювачі й машини, тож це місце — непереборна спокуса для крадіжок креслень, особливих деталей і секретів ремесла, які замовляють із Раджета."},sec={{t="Промислове спустошення",b="До приходу Венчурної Компанії Багнисте Болото було незайманим озерцем кришталево чистої води, яке живили природні джерела посеред посушливих Пусток. Гнана невситимою жадобою прибутку, Венчурна Компанія розгорнула над улоговиною широкі нафтові бурові роботи й перетворила водойму на заповнене мулом сховище, вкрите густими промисловими відходами. Під орудою Наглядача Луґвізла гобліни-бурильники, інженери й наглядачі цілодобово качають сиру нафту, не зважаючи на руйнування природи. Тепер вода загусла від стоків і отруйних залишків, а місцеве водне життя задихається під мастилом."},{t="Корпоративне суперництво й шпигунство",b="Машини й новітні подрібнювачі на болоті зробили його ласою ціллю для промислових крадіжок. У сусідньому Раджеті інженер Спілки Винахідників Спаттервалв опинився під жорстким тиском: йому треба наздогнати Венчурну Компанію з її передовою технікою для лісозаготівель і копалень. Замість винаходити власні креслення, Спаттервалв послав свого агента Візлкренка захопити подрібнювач Венчурної Компанії просто на Багнистому Болоті. Та Візлкренк необачно викрав машину, не прихопивши ключа запалювання, тож найманців часто втягують у трясовину, щоб відібрати ключі в Луґвізла й вивести викрадену бойову машину крізь стрій розлючених працівників Венчурної Компанії."}},faq={{q="Яким було Багнисте Болото до приходу Венчурної Компанії?",a="Спершу Багнисте Болото було улоговиною з чистою кришталево-блакитною водою. Венчурна Компанія занапастила цю природну оазу, збудувавши просто на ній нафтову вежу й переробку, і втопила довколишні болота в сирій нафті й хімічних відходах.",al={"минуле багнистого болота","чи болото завжди було забруднене","історія багнистого болота"}},{q="Хто керує роботами на Багнистому Болоті?",a="Нафтовим полем від імені Венчурної Компанії керує Наглядач Луґвізл. Він наглядає за робітниками — наглядачами, бурильниками й інженерами — разом із помічниками, як-от Наглядач Ґліббі й Наглядач Ґриллз.",al={"бос багнистого болота","хто керує багнистим болотом","наглядач лагвізл"}},{q="Чому посеред болота стоїть викрадений подрібнювач?",a="Гобліна Візлкренка послав Спаттервалв із Раджета викрасти досконалішу конструкцію подрібнювача Венчурної Компанії. Проте той стрибнув у кабіну, не роздобувши спершу ключа запалювання, і застряг серед ворожих робітників Венчурної Компанії.",al={"подрібнювач візлкранка","гоблін у подрібнювачі","чому подрібнювач застряг"}},{q="Навіщо друїди пірнають у ці забруднені води?",a="Друїдів Орди, що проходять Випробування Морського Лева, посилають на дно отруєного ставка, щоб дістати з затопленої скриньки Половину Амулета Водної Спритності, — це перевіряє їхню витривалість у мерзенному довкіллі.",al={"завдання друїдів багниста болото","половина кулона водної спритності","випробування водної форми"}}},fp="10,379,22.621.0,31.676.1,60.247.0,37.207.0,65.258.0,46.226.0"}
P.entries["subzone:solliden-farmstead"] = {n="Хутір Соллідена",s="Хутір Соллідена — діюча людська гарбузова ферма в західних Галявинах Тірісфалю, одразу на північ від Похоронного Подзвону. Це рідкісний виняток у північному Лордероні: живі тутешні фермери, що пережили Чуму Нежиті й запекло тримаються своєї землі під тінню Багряного Хрестового Походу.",h="Хутір Соллідена — діюча людська гарбузова ферма в західних Галявинах Тірісфалю, одразу на північ від...",kw={"хутір соллідена","гарбузи","живі фермери","багряний хрестовий похід","нова чума","аптекар йогаан","тірісфаль"},ang={["faction:Alliance"]="Бачити живих людей, що обробляють землю Лордерона, — проблиск надії, та гірка правда в тому, що ці відрізані від світу вцілілі дивляться на громадян Стормвінда з тією ж ксенофобською ненавистю, що й на нежить.",["race:Undead"]="Для щойно воскреслих Відступників Хутір Соллідена — негайний урок реальної політики: живі лордеронці, що зневажають те, ким ви стали, слугують водночас сировиною для аптекарських отрут і потенційним південним плацдармом."},sec={{t="Непокірний залишок",b="Поки більша частина Лордерона обернулася на руїну й гниль, поля Хутора Соллідена досі дають здорові врожаї. Поселення веде свій родовід від тих століть, коли дворянські родини-переселенці зі Строму придбали піонерські наділи по всьому Тірісфалю. Сьогодні ці вцілілі люди-фермери живуть під пильним щитом Багряного Хрестового Походу, що патрулює з сусідньої вежі. Травмовані й замкнуті, вони боронять свою садибу з непохитною ворожістю, нападаючи на всіх чужинців, що наближаються, — і з Орди, і з Альянсу."},{t="Очі в Андерсіті",b="Для Відступників, що лише виходять із Похоронного Подзвону, Солліден — і загроза, і ресурс. Королівське Аптекарське Товариство накинуло оком на бездоганні гарбузи ферми як на першокласний органічний матеріал для випробувань своєї Нової Чуми. Тим часом офіцери Відступників на кшталт Вартового Смерті Сіммера посилають новобранців-початківців грабувати поля, красти ці гарбузи для Аптекаря Йогаана в Бріллі й провчити живих."}},faq={{q="Чому на Галявинах Тірісфалю живі люди обробляють землю?",a="Фермери Соллідена — корінні люди Лордерона, які дивом уникли зараження під час Третьої війни. Під захистом Багряного Хрестового Походу, що патрулює із сусідньої вежі, вони вперто обробляють землю, а не тікають із рідного краю.",al={"чому живі люди в тіріфалі","хто ці фермери","живі люди тіріфалю"}},{q="Чому фермери Соллідена ворожі до гравців Альянсу?",a="Пережите падіння Лордерона зробило фермерів підозріливими, озлобленими й геть недовірливими до всіх, хто не з їхнього кола. Під захистом фанатичного Багряного Хрестового Походу вони вважають усіх зайд можливою загрозою чи зараженими мародерами й нападають і на мандрівників Альянсу, і на мандрівників Орди без розбору.",al={"чому фермери нападають на альянс","чи вони альянс","чому червоні до альянсу"}},{q="Навіщо Відступникам гарбузи з Хутора Соллідена?",a="Аптекарям Королівського Аптекарського Товариства потрібна свіжа, незіпсована органіка, щоб випробовувати й удосконалювати свою Нову Чуму. Великі незаражені гарбузи, що ростуть на землі Соллідена, — ідеальні живі носії для вирощування отруйних штамів.",al={"навіщо відступникам гарбузи","завдання з гарбузами","гарбузи аптекарського товариства"}},{q="Хто такий Вартовий Смерті Сіммер і чому він націлився на ферму?",a="Вартовий Смерті Сіммер — офіцер Відступників біля Похоронного Подзвону. Він посилає молодих Відступників напасти на ферму, викрасти десять гарбузів для Аптекаря Йогаана в Бріллі й провчити людей та їхніх захисників із Багряного Хрестового Походу.",al={"чому вбивати фермерів","завдання смертевартового сіммера","жнива жнив"}}},fp="18,295,17.511.0,21.395.0,55.257.0,57.315.0,58.243.0,58.238.0"}
P.entries["subzone:sorrow-hill"] = {n="Пагорб Скорботи",s="Пагорб Скорботи — розлогий цвинтар на південь від Андоргала в Західних Чумних Землях. Колись тут знаходили вічний спочинок прості люди, солдати й вельможі, та чумні казани неподалік обернули цвинтар на велике кубло неупокоєної нежиті.",h="Пагорб Скорботи — розлогий цвинтар на південь від Андоргала в Західних Чумних Землях.",kw={"пагорб скорботи","цвинтар","гробниця утера","андоргал","табір студеного вітру","гулі"},ang={["class:Paladin"]="Пагорб Скорботи — місце глибокої жалоби й шани для паладинів: вони приходять сюди вклонитися Гробниці Утера й відганяють нежить, що оскверняє землю довкола місця спочинку їхнього наставника.",["faction:Alliance"]="Цвинтар неподалік від Табору Студеного Вітру — це і стратегічний пункт на шляху до Андоргала, і священне місце спочинку полеглих захисників Лордерону."},sec={{t="Тягар могил",b="До Третьої війни Пагорб Скорботи був головним цвинтарем Андоргала й довколишніх містечок. Коли Погибель випустила чуму нежиття, гробарі не встигали ховати мертвих. Довкола доглянутих склепів невдовзі виросли мілкі, ледь позначені ями. Зрештою нажахані вцілілі зовсім облишили звичні поховання й стали спалювати тіла рідних на великому багатті південніше — зі страху, що ті повстануть. Ще до остаточного падіння містечка рештки його мешканців поховали лорда Утера Світлоносця на найвищому місці цвинтаря — звідти пагорб і дістав свою скорботну назву."},{t="Повсталі мерці",b="Мерзенні чумні казани Погибелі по всьому краю давно осквернили Пагорб Скорботи. Поховані тут солдати й містяни тепер блукають серед оповитих імлою надгробків як кістяні шкуродери й ненажерливі гулі, а скелети-маги та місцевий командир Погибелі загніздилися в південно-східних склепах. Цвинтар лежить просто при дорозі між Табором Студеного Вітру й Андоргалом, тож і Альянс, і Срібний світанок раз у раз висилають сюди загони, щоб прорідити ряди нежиті й утримати важливий плацдарм у цьому краї."}},faq={{q="Чому цей цвинтар назвали Пагорбом Скорботи?",a="Він дістав цю назву під час падіння Лордерона, коли вцілілі мешканці Андоргала зазнали страшних утрат від Погибелі. Останнє, що вони зробили разом, перш ніж утекти, — поховали свого полеглого героя, лорда Утера Світлоносця, у величній гробниці на вершині пагорба.",al={"значення назви пагорба скорботи","чому пагорб скорботи"}},{q="Чому тут стільки мілких могил?",a="Коли чума нежиття вразила Андоргал, люди вмирали так швидко, що мешканці не встигали будувати пристойні гробниці. Вони поспіхом копали ледь позначені могили, доки навала не стала такою нищівною, що від поховань узагалі відмовилися й почали масово спалювати тіла.",al={"неглибокі могили пагорба скорботи","чому могили погано позначені"}},{q="Хто похований на Пагорбі Скорботи?",a="Окрім тисяч полеглих вояків і мешканців Андоргала, на цвинтарі стоїть велична гробниця Утера Світлоносця. Тут також місце спочинку гармаша Дарґала й пам'ятник Джозефу Редпату, чиє тіло було знищено.",al={"відомі могили пагорба скорботи","хто похований тут"}},{q="Чим небезпечний Пагорб Скорботи сьогодні?",a="Зіпсовані чумними казанами Короля-Ліча, мерці цвинтаря повстали кістяками-шкуродерами, слинавими гулями й кістяками-магами. На чолі з командиром Погибелі, що засів у південно-східному склепі, ця нежить загрожує південному підступу до Андоргала.",al={"погибіль на пагорбі скорботи","хто контролює пагорб скорботи"}}},fp="11,257,18.667.0,20.521.0,41.275.0,42.265.0,29.248.0,40.260.0"}
P.entries["subzone:sorrowmurk"] = {n="Скорботна Мла",s="Скорботна Мла — підступні болотяні простори просто на схід від Ставка Сліз на Болоті Скорботи. Тут здавна патрулюють зелені дракони, що стережуть підступи до Затонулого Храму, тож ця місцина й досі — одна з найнебезпечніших на східних болотах.",h="Скорботна Мла — підступні болотяні простори просто на схід від Ставка Сліз на Болоті Скорботи.",kw={"скорботна мла","зелені дракони","ставок сліз","затонулий храм","болото скорботи","грізне море"},ang={["class:Druid"]="Скорботна скверна, що торкнулася вартових Смарагдового Сну в цих болотах, робить тутешніх зелених драконів трагічним видовищем для кожного слуги природи."},sec={{t="Небезпечне прикордоння",b="Скорботна Мла тягнеться вздовж східного краю Ставка Сліз — це густа, похмура трясовина, що межує з Грізним Морем. Роками у воді й серед сплутаного гілля кишіло люте зелене драконороди й величезні дрейки — рештки виводку, посланого стерегти затоплений Храм Атал'Гаккара. Через них лише досвідчені мандрівники наважуються бродити цими розмоклими нетрями."}},faq={{q="Де розташована Скорботна Мла?",a="Скорботна Мла лежить у найсхіднішій частині Болота Скорботи, одразу за Ставком Сліз і затонулими руїнами Храму Атал'Гаккара, на межі з узбережжям.",al={"розташування скорботної млі","де скорботна мла","скорботна мла на мапі"}},{q="Хто живе в Скорботній Млі?",a="Край славиться зеленими драконячими створіннями — агресивними драконородами й великими драконами, що люто патрулюють болото довкола храмових вод.",al={"моби скорботної млі","що живе в скорботній млі","вороги скорботної млі"}},{q="Чому в Скорботній Млі зелені дракони?",a="Ізера доручила зеленому драконячому родові пильнувати Ставок Сліз і стежити, щоб зло, затоплене в Храмі Атал'Гаккара, лишалося під замком.",al={"чому тут дракони","зелений політ болото скорботи","дракони храму"}}},fp="10,272,17.411.0,32.173.0,38.151.0,46.159.0"}
P.entries["subzone:south-gate-outpost"] = {n="Застава Південної Брами",s="Застава Південної Брами — укріплений дворфійський гірський пост на Проході Південної Брами між Дун Мороґом і Лох Моданом. Горяни, що тримають засніжену південну дорогу, оберігають постійний потік мандрівників між морозними висотами Айронфорджа й помірною долиною Озера.",h="Застава Південної Брами — укріплений дворфійський гірський пост на Проході Південної Брами між Дун Мороґом і...",kw={"застава південної брами","прохід південної брами","горяни","дун мороґ","лох модан"},ang={["faction:Alliance"]="Застава — надійний військовий прихисток на одному з головних внутрішніх шляхів постачання Каз Модану, що тримає відкритим прохід між столицею та східними поселеннями.",["race:Dwarf"]="Для дворфів, що вперше покидають Долину Холодного Хребта й Дун Мороґ, Застава Південної Брами — останній холодний орієнтир перед спуском у яскраві, залиті сонцем землі Лох Модану."},sec={{t="Вартові південної дороги",b="Застава Південної Брами, що стоїть посередині високого гірського розрізу Проходу Південної Брами, позначає межу між засніженими схилами Дун Мороґу й зеленою улоговиною Лох Модану. Тут несуть службу айронфорджські горяни, яким доручено патрулювати кам'янисті серпантини й тримати небезпечних звірів подалі від головного шляху. На відміну від своїх родичів, що ледве дають собі раду на Заставі Північної Брами, тутешні захисники здебільшого вже убезпечили свою ділянку дороги, тож мандрівники, прочани й торгові вози, що прямують до Телсамара, можуть подорожувати відносно безпечно."}},faq={{q="Для чого потрібна Застава Південної Брами?",a="Це укріплений прикордонний пост і гарнізон біля Проходу Південної Брами. Горяни, що стоять тут, тримають засніжену дорогу між Дун Мороґом і Лох Моданом вільною від гірських звірів і ворожих зайд.",al={"навіщо застава південної брами","призначення застави південної брами","що це за застава"}},{q="Чому тут набагато спокійніше, ніж на Заставі Північної Брами?",a="Гарнізон Застави Південної Брами успішно прорідив агресивних звірів біля самої дороги. Натомість Заставі Північної Брами доводиться відбиватися від сильніших навал серед дикішої гірської місцевості, тож південний прохід порівняно спокійний.",al={"різниця між північною і південною брамою","чи безпечна південна брама","південна брама проти північної"}},{q="Куди веде дорога через Заставу Південної Брами?",a="На захід, угору перевалом, ви потрапите на засніжене нагір'я Дун Мороґу, у бік Айронфорджа. На схід, униз, дорога веде просто в помірну долину Лох Модану, в'ючись до поселення Телсамар.",al={"куди веде дорога","кінець дороги південної брами","шлях проходу південної брами"}}},fp="18,291,29.544.0,42.228.0,57.255.0,52.251.0"}
P.entries["subzone:south-gate-pass"] = {n="Прохід Південної Брами",s="Прохід Південної Брами — головний гірський шлях, що з'єднує засніжені висоти Дун Мороґу з улоговиною Лох Модану. Оточений дворфійськими тунелями й дозорними постами, він править за найкоротшу дорогу між Айронфорджем і поселенням Телсамар.",h="Прохід Південної Брами — головний гірський шлях, що з'єднує засніжені висоти Дун Мороґу з улоговиною Лох...",kw={"прохід південної брами","застава південної брами","дун мороґ","лох модан","телсамар"},ang={["faction:Alliance"]="Прохід — важлива внутрішня артерія, що з'єднує Айронфордж зі східними землями Альянсу; його утримують і охороняють Королівські горяни.",["race:Dwarf"]="Для дворфів, що покидають Дун Мороґ, Прохід Південної Брами — поріг, де крижане гірське повітря поступається відкритим долинам і кар'єрам Лох Модану."},sec={{t="Дорога на схід",b="Прохід Південної Брами, прорубаний просто крізь хребет Каз Модану, з'єднує високі гори Дун Мороґу з пологою долиною Лох Модану на сході. Залишивши позаду холодні схили, мандрівники виходять крізь кам'яні арки в тепліше серце дворфійських земель. Оскільки шлях веде просто до Телсамара, ним постійно ходять горяни, гінці й щойно вишколені шукачі пригод, що вирушають зі столиці."},{t="Поріг під охороною",b="Від диких звірів і трогів, що никають довкола, прохід захищає Застава Південної Брами, де дворфійські горяни постійно несуть варту. Хоч тут загалом безпечніше, ніж у диких нетрях углибині долини, мандрівникам радять триматися дороги, бо ворожі звірі й мандрівні загрози раз у раз прощупують підступи."}},faq={{q="Куди веде Прохід Південної Брами?",a="На захід тунелями ви потрапите на засніжене нагір'я Дун Мороґу, на дорогу до Айронфорджа. На схід шлях спускається в улоговину Лох Модану, просто до поселення Телсамар.",al={"куди веде прохід південної брами","кінець проходу південної брами","дорога південної брами"}},{q="Чи безпечно подорожувати Проходом Південної Брами?",a="Сама дорога відносно безпечна завдяки дворфійським вартовим із Застави Південної Брами, але на довколишніх кручах і схилах за виходом із тунелю водяться ведмеді, павуки й троги, що підступають дедалі ближче.",al={"чи небезпечний прохід південної брами","загрози проходу південної брами"}},{q="Чому цим проходом користуються частіше, ніж Перевалом Північної Брами?",a="Прохід Південної Брами — найпряміший і найзручніший суходільний шлях між Дун Мороґом і Телсамаром, тож його обирають для місцевої торгівлі, обозів із припасами й мандрівників до центру Лох Модану.",al={"південна брама проти північної","чому користуватися південною брамою"}}},fp="15,259,13.416.0,19.325.0,32.214.0,34.211.0,48.220.0"}
P.entries["subzone:south-seas"] = {n="Південні Моря",s="Південні Моря — неосяжні, залиті сонцем води, що розділяють південні землі Калімдору й Східних Королівств. Вони омивають береги Танарісу й Долини Стренглторну і славляться прибутковими торговими шляхами, підступними рифами й зухвалими піратськими командами.",h="Південні Моря — неосяжні, залиті сонцем води, що розділяють південні землі Калімдору й Східних Королівств.",kw={"південні моря","пірати","кезан","зандалар","тель'абім","торгові шляхи"},ang={["class:Rogue"]="Беззаконні Південні Моря — життєва сила піратських картелів і каперів: тут безмежні можливості для шахраїв, які знаються на абордажах, контрабанді й підступній політиці портових гаваней.",["profession:Cooking"]="Екзотичні води й узбережжя Південних Морів дають цінну океанську рибу, велетенських кальмарів і славетні солодкі банани, які привозять із відлюдних островів на кшталт Тель'Абіму."},sec={{t="Прикордоння зірвиголів",b="Південні Моря простягаються на південь від Великого Моря й Виру та омивають пустелі Танарісу й буйні джунглі Долини Стренглторну. Відколи десять тисяч років тому Великий Розкол розтрощив первісний континент, цей океан плекав далекі тропічні острови, унікальних морських тварин і незалежні торгові мережі. Гоблінські судноплавні картелі, що діють із таких гаваней, як Порт Стімвідла й Буті Бей, підтримують хиткі морські шляхи. Проте ці води славляться беззаконням: тут кишать корсари, буканіри Кривавого Вітрила й морські хижаки, що полюють на кожне судно, яке наважиться відпливти далеко від берега."},{t="Приховані глибини й далекі острови",b="За прибережними торговими шляхами лежить мозаїка легендарних островів і затонулих небезпек. Серед відомих земель Південних Морів — батьківщина гоблінів Кезан, прадавній тролячий острів Зандалар, розбійницька твердиня Острів Здобичі й щедрі на врожаї береги Тель'Абіму. Та морякам-торговцям загрожують не лише головорізи: у глибших водах живуть колосальні велетенські кальмари, первісні морські черепахи й наги, що чатують біля прадавніх руїн, поглинутих хвилями. Щоб ходити цими водами, потрібні досвідчені капітани, надійні карти й чимала вогнева міць."}},faq={{q="З якими краями межують Південні Моря?",a="На півдні Калімдору Південні Моря омивають узбережжя Танарісу біля запечатаної брами Ульдуму. А за океаном на сході вони б'ються об береги Долини Стренглторну та її віддалених островів, як-от Острів Ягуеро й Острів Йоджамба.",al={"де південні моря","межі південних морів","яке це узбережжя"}},{q="Хто контролює судноплавство в Південних Морях?",a="Жодна сила не панує в Південних Морях. Картель Стімвідл тримає головну торгову лінію між Портом Стімвідла й Буті Беєм, але постійно воює за води з піратськими зграями-суперниками — Буканірами Кривавого Вітрила й Флібустьєрами Південних морів.",al={"хто керує південними морями","торгівля південних морів","порти південних морів"}},{q="Які небезпечні істоти живуть у цих водах?",a="Відкриті хвилі кишать небезпеками — від ненажерливих велетенських кальмарів і прибережних рифових акул до закутих у панцир велетенських черепах. Під час Другої війни клан Орди Штормового Розорювача навіть ловив тутешніх велетенських черепах, щоб переробити їх на підводні судна. А острови краю ховають м'ясоїдних кажанів-кривокрилів і патрулі наг, що чатують у засідці.",al={"монстри південних морів","морські чудовиська танарісу","істоти південних морів"}},{q="Які відомі острови лежать у Південних Морях?",a="Серед відомих островів у глибоких водах — гоблінський торговий осередок Кезан, піратське кубло Острів Здобичі, багатий на фрукти Тел'Абім і Зандалар — давнє королівство тролівської імперії. Ближче до узбереж лежать менші прикмети, як-от Острів Йоджамба й Острів Ягуеро.",al={"острови південних морів","кезан зандалар південні моря","список островів південних морів"}}},fp="10,284,25.656.0,31.584.0,33.241.0,40.273.0,46.341.0,47.286.0"}
P.entries["subzone:south-tide-s-run"] = {n="Південна Течія Припливу",s="Південна Течія Припливу — самотнє південно-західне узбережжя Срібнолісся, що тягнеться вздовж холодних вод Великого Моря. Ці вологі піски й прибій, що облямовують лісисті нутрощі краю, — південна пара до Потоку Північного Припливу.",h="Південна Течія Припливу — самотнє південно-західне узбережжя Срібнолісся, що тягнеться вздовж холодних вод...",kw={"південна течія припливу","узбережжя","велике море","срібнолісся"},ang={["race:Undead"]="Дике південно-західне узбережжя лежить далеко від захисту Гробниці, тож це безлюдне прикордоння, куди Відступники рідко ступають."},sec={{t="Західний берег",b="Південна Течія Припливу, що тягнеться південно-західним краєм Срібнолісся, — безлюдна межа між лісом і Великим Морем. На відміну від захищених східних доріг, що ведуть униз до Стіни Ґреймейна, цей відкритий берег бере на себе всю силу західних припливів і лишається похмурою дикою місциною, майже не зачепленою поселеннями в глибині краю."}},faq={{q="Де розташована Південна Течія Припливу?",a="Південна Течія Припливу займає південно-західне узбережжя Срібнолісся на межі з відкритими просторами Великого Моря.",al={"де південна течія припливу","розташування південної течії","південна течія на мапі"}},{q="Чим Південна Течія Припливу відрізняється від Потоку Північного Припливу?",a="Обидва — довгі смуги пляжу вздовж західного берега Срібнолісся, але Південна Течія Припливу охоплює південну частину узбережжя, а Потік Північного Припливу тягнеться північним заходом, біля кордону з Галявинами Тірісфалю.",al={"північна течія проти південної","різниця течій припливу"}},{q="Чи є поселення на Південній Течії Припливу?",a="На самому пляжі немає ні великих поселень, ні застав. Відступники здебільшого діють углибині краю, біля головних шляхів, тож узбережжя лишається відлюдним.",al={"містечка південної течії","хто живе в південній течії"}}},fp="16,238,17.353.0,34.119.0,55.234.0,49.159.0"}
P.entries["subzone:southern-gold-road"] = {n="Південна Золота Дорога",s="Південна Золота Дорога — важливий пустельний тракт, що тягнеться південною половиною Пусток і з'єднує центральні рівнини з Великим Підйомником. Це незамінна артерія торгівлі в краї: нею рухаються каравани, припаси й мандрівники між віддаленими куточками Калімдору.",h="Південна Золота Дорога — важливий пустельний тракт, що тягнеться південною половиною Пусток і з'єднує...",kw={"південна золота дорога","золотий шлях","великий підйомник","тисяча голок","каравани","пустки"},ang={["faction:Horde"]="Дорога — хребет шляхів постачання Орди між центральним перехрестям Пусток і південними заставами поблизу Тисячі Голок."},sec={{t="Артерія півдня",b="Офіційно Південна Золота Дорога починається біля кам'яного мосту, що розділяє північну й південну половини Пусток, і тягнеться просто на південь, аж до Великого Підйомника, яким спускаються в Тисячу Голок. Як і північна частина, що зветься просто Золотим Шляхом, цей курний тракт має назву завдяки нескінченному потоку прибуткових купецьких караванів. Попри постійні напади місцевих племен шипогривів і хижаків, що никають саваною, це один із найжвавіших далеких шляхів континенту, яким возять товари між віддаленими заставами й гамірними портами."},{t="Перехрестя далеких країв",b="Дорогою користується не лише місцева Орда. Шукачі пригод і загартовані торговці, що прямують до таких далеких місць, як Ґаджетзан у південних пустелях Танаріса, Обердайн на туманних берегах Темного Узбережжя чи священні гаї Нічного Притулку в Місячному Гаю, топчуть цей випалений сонцем простір. Для тих, хто подорожує нутрощами Калімдору пішки, подолати Південну Золоту Дорогу — виснажливий обряд посвяти."}},faq={{q="Де починається й закінчується Південна Золота Дорога?",a="Офіційно дорога починається від мосту, що розділяє північну й південну половини Пусток, і тягнеться на південь аж до краю Тисячі Голок біля Великого Підйомника.",al={"шлях південної золотої дороги","маршрут південної золотої дороги","де південна золота дорога"}},{q="Чому вона зветься Золотою?",a="Шлях названо на честь багатих торгових караванів, що регулярно ним ходять, перевозячи коштовні товари, руду й монети через серце Калімдору.",al={"чому золота","походження назви золотої дороги","значення золотої дороги"}},{q="Яка різниця між Золотим Шляхом і Південною Золотою Дорогою?",a="Межа — міст через центральний розлам Пусток. На північ від нього дорога зветься просто Золотим Шляхом, а відтинок, що веде на південь до Великого Підйомника, — Південною Золотою Дорогою.",al={"золотий шлях проти південної золотої дороги","дві золоті дороги"}},{q="Хто подорожує цим відтинком дороги?",a="Окрім місцевих гінців і патрулів Орди, цим шляхом користуються крамарі й дослідники, що мандрують між далекими краями, — він сполучає, наприклад, Ґаджетзан на далекому півдні з Темним Узбережжям і Місячним Гаєм на далекій півночі.",al={"хто користується південною золотою дорогою","каравани південної золотої дороги"}}},fp="18,301,19.606.0,29.443.0,48.191.0,31.158.0,72.228.0,39.226.0"}
P.entries["subzone:southern-savage-coast"] = {n="Південне Дике Узбережжя",s="Південне Дике Узбережжя — довга смуга пляжів і припливних вод уздовж південно-західної частини Долини Стренглторну. З одного боку до нього підступають зрадливі глибини Південних Морів, а на самому березі чатують хижі звірі, ворожі наги й одвічна загроза прибережних нальотників.",h="Південне Дике Узбережжя — довга смуга пляжів і припливних вод уздовж південно-західної частини Долини...",kw={"південне дике узбережжя","південні моря","мерзенний риф","наги","долина стренглторну","корсари"},ang={["class:Hunter"]="Широкі відкриті пляжі — чудові угіддя, щоб вистежувати земноводну дичину, прибережних хижих котів і василісків: тут видно далеко, і це куди краще, ніж задушливі хащі в глибині суходолу."},sec={{t="Підступна берегова лінія",b="Південне Дике Узбережжя тягнеться західним краєм південних джунглів — там, де суходіл поступається теплим течіям Південних Морів. Від північного Дикунського Узбережжя його відділяють затоплені руїни й небезпеки Мерзенного Рифу. Узбережжя оминає затоки біля Арени Ґурубаші та Джерела Нек'мані, а за Буті Беєм і Мисом Жанейро поступово сходить нанівець. Пляжі хоч і відкритіші за задушливі джунглі в глибині суходолу, та мандрівникам доводиться відбиватися від агресивних плазунів-хижаків, наг, що полюють на мілинах, і корсарів, які пропливають повз і видивляються на березі легку здобич."}},faq={{q="Де починається й закінчується Південне Дике Узбережжя?",a="Воно охоплює південно-західне узбережжя Долини Стренглторну: починається нижче Мерзенного Рифу й тягнеться на південь повз Буті Бей і Мис Жанейро, де переходить у Дикий Берег.",al={"розташування південного дикого узбережжя","де південне дике узбережжя","межі дикунського узбережжя"}},{q="Чим воно відрізняється від північного Дикунського Узбережжя?",a="Ці дві смуги узбережжя розділяє Мерзенний Риф. Північне Дикунське Узбережжя тягнеться вздовж вод Великого Моря на півночі Стренглторну, а Південне Дике Узбережжя лежить уздовж нижнього мису на межі з Південними Морями.",al={"різниця між дикунським і південним","чому два дикунські узбережжя","межа гидкого рифу"}},{q="Які загрози чекають мандрівників на пляжі?",a="На відкритих пісках повно лютих ящірок-василісків, клацаючих кроколісків, ворожих наг, що виповзають із мілин, і патрулів піратів, які ревно бережуть свої ділянки.",al={"чи небезпечне південне дике узбережжя","моби південного дикого узбережжя","загрози вздовж узбережжя"}},{q="Чи контролює це узбережжя Буті Бей?",a="Ні. Нападники Чорної Води й картель Стімвідл тримають лише гавань Буті Бею та найближчі підступи до неї. Дикі пляжі на північ і на південь лишаються беззаконною, неприборканою землею.",al={"чи бутті бей володіє пляжем","контроль стімвіддлів над узбережжям","гоблінська територія"}}},fp="21,281,23.616.0,51.203.0,51.226.0,50.167.0,38.205.0"}
P.entries["subzone:southfury-river"] = {n="Річка Південної Люті",s="Річка Південної Люті — одна з найпомітніших водних артерій центрального Калімдору: стрімка й широка, вона прокладає собі шлях на південь від висот Гори Гіджал. Річка слугує природним кордоном між Азшарою та Ашенвалем, а також між Дуротаром і Пустками, а неподалік Раджета впадає у Велике Море.",h="Річка Південної Люті — одна з найпомітніших водних артерій центрального Калімдору: стрімка й широка, вона...",kw={"річка","південна лють","дуротар","пустки","азшара","ашенваль","оргріммар"},ang={["faction:Horde"]="Річка Південної Люті — західний оборонний рубіж Дуротару й природний шлях, що з'єднує столицю із серцем Пусток."},sec={{t="Природний рубіж",b="Річка Південної Люті бере початок високо на Горі Гіджал, зривається каскадами водоспадів і мчить крізь центральний Калімдор. Її бурхливі води — чітка межа на мапі: вони відділяють священні ліси Ашенвалю від прадавньої Азшари, а посушливі пагорби Дуротару — від савани Пусток. Лише кілька мостів наважуються перетнути її бистру течію — передусім масивна переправа, що стереже задню браму Оргріммара, і міст, який з'єднує Дуротар із Пустками. Зрештою річка каскадом водоспаду обривається у Велике Море трохи на північний схід від нейтрального порту Раджет."},{t="Стратегічне значення",b="Для Орди Річка Південної Люті — водночас щит і життєво важливий природний шлях. Вона прикриває західні підступи до Дуротару й Оргріммара від раптового наземного наступу та несе свіжу гірську воду крізь випалений, висушений сонцем край. Трохи на північ від західної переправи до Оргріммара лежить унікальне перехрестя, де сходяться чотири великі краї: Ашенваль, Азшара, Дуротар і Пустки. Хто тримає цю вируючу ріку, той береже шляхи постачання між Оргріммаром і віддаленими поселеннями Орди."}},faq={{q="Де починається й закінчується Річка Південної Люті?",a="Річка Південної Люті бере початок у високогір'ї Гори Гіджал і спадає мальовничими водоспадами в низини. Вона тече на південь між Ашенвалем, Азшарою, Дуротаром і Пустками, а тоді водоспадом обривається у Велике Море на північний схід від Раджета.",al={"витік річки південної люті","куди тече південна лють","гирло південної люті"}},{q="З якими краями межує річка?",a="На півночі річка відділяє Ашенваль від Азшари, а на півдні — Пустки від Дуротару. Цікаво, що на північ від західного мосту Оргріммара є місце, де на берегах річки сходяться всі чотири краї.",al={"які зони на південній люті","межі південної люті"}},{q="Де мандрівники можуть перетнути Річку Південної Люті?",a="Через Річку Південної Люті перекинуто три головні мости: один сполучає Азшару з Ашенвалем, другий веде до задньої брами Оргріммара, а великий міст сполучає Дуротар із Пустками.",al={"мости південної люті","як перетнути південну лють","мости над південною люттю"}},{q="Чому річка важлива для Оргріммара?",a="Річка — грізна природна перепона, що захищає західний фланг Оргріммара й Дуротару. Крім того, її свіжі гірські води — безцінне джерело життя для цього посушливого краю.",al={"південна лють оргріммар","чому орді важлива південна лють"}}},fp="15,301,22.606.0,20.552.0,45.251.0,34.213.0,46.196.0,40.208.0"}
P.entries["subzone:southmoon-ruins"] = {n="Руїни Південного Місяця",s="Руїни Південного Місяця — прадавні кам'яні рештки на півдні Танарісу, трохи на північ від Долини Вартових. Їх давно захопили грубі огри Дюнного Молота, а розсипане муровання зберігає сліди прадавньої тролячої цивілізації, що панувала в пустелі, поки її не поглинули піски.",h="Руїни Південного Місяця — прадавні кам'яні рештки на півдні Танарісу, трохи на північ від Долини Вартових.",kw={"руїни південного місяця","дюнний молот","огри","тролячі руїни","долина вартових","танаріс"},ang={["race:Dwarf"]="Дворфійські мандрівники, що перетинають південний Танаріс, не знайдуть у Південному Місяці нічого, крім вивітреного тролячого муровання й огрів Дюнного Молота, що отаборилися серед нього.",["race:Troll"]="Для тролів Темного Списа ці розбиті колони — тверезий погляд на занепалу велич їхніх далеких тролячих родичів, що опинилися в злиднях під пустельним сонцем."},sec={{t="Каміння серед мінливих пісків",b="Руїни Південного Місяця, що здіймаються з розпеченої пустки південного Танарісу, — вивітрене свідчення прадавніх тролячих імперій, які колись володіли південними землями Калімдору. Як і в сусідніх руїнах Східного Місяця та Полуденної Тіні, тутешні кам'яні колони й вівтарі тисячоліттями витримували вітер і їдкий пісок. Місце часто правило за убогий табір для огрів Дюнного Молота, які анітрохи не шанують майстерність минулого й використовують прадавні споруди лише як прихисток і свою територію."},{t="Таємниці під уламками",b="Архітектурні рештки безсумнівно тролячі, але про народ, що звів каміння Південного Місяця, і про те, чому він його покинув, відомо мало. Усе, що вони лишили по собі, поховане під мінливим піском, а огрям, які отаборилися серед колон, до цього байдуже."}},faq={{q="Хто збудував Руїни Південного Місяця?",a="Руїни Південного Місяця — давні тролівські руїни, вивітрені рештки тролівської цивілізації, що колись володіла південними краями нинішньої пустелі Танаріс.",al={"хто збудував південний місяць","історія південного місяця","чи це тролячі руїни"}},{q="Хто нині живе в руїнах?",a="Здавна руїни займають огри Дюнного Молота, що забрели в Танаріс і забрали собі під табори різні напівзруйновані давні застави, прогнавши інших мародерів.",al={"хто тут живе","моби південного місяця","дюнний молот на південному місяці"}},{q="Де розташовані Руїни Південного Місяця?",a="Вони лежать у південній половині Танарісу, на північний захід від Долини Вартових і на південь від центральних пустельних пусток.",al={"розташування південного місяця","де руїни південного місяця","як знайти південний місяць"}}},fp="15,295,28.499.0,26.276.0,41.160.0,33.195.0,38.130.0"}
P.entries["subzone:southpoint-tower"] = {n="Вежа Південного Мису",s="Вежа Південного Мису — зруйнована лордеронська дозорна вежа на західному кордоні Передгір'я Гілсбреда, з якої видно дорогу до Срібнолісся. Колись тут стояла людська варта, а тепер розбиту споруду обжили розвідники Відступників, що стежать за пересуваннями Альянсу в краї.",h="Вежа Південного Мису — зруйнована лордеронська дозорна вежа на західному кордоні Передгір'я Гілсбреда, з якої...",kw={"вежа південного мису","гілсбред","срібнолісся","відступники","леш","розвідка"},ang={["faction:Alliance"]="У зруйнованій вежі сидить ворожий шпигун, що стежить за дорогою до Срібнолісся, тож розвідники, які захищають людські поселення Гілсбреда, неминуче беруть її на приціл.",["race:Undead"]="Вежа — незамінний розвідувальний пункт для Відступників біля кордону зі Срібноліссям, звідки можна стежити за пересуваннями людських загонів із Гілсбреда."},sec={{t="Зруйнований вартовий",b="Вежа Південного Мису стоїть трохи на південь від шляху, що з'єднує Срібнолісся з Передгір'ям Гілсбреда. Королівство Лордерон звело її, щоб стерегти рух між східними полями й західними лісами. Після Третьої війни, коли Погибель знищила королівство, кам'яна кладка почала руйнуватися. Нині вежа стоїть без даху, кришиться й лишається самотнім пам'ятником людського панування на роздертих землях."},{t="Очі над пагорбами",b="Попри руйнування, вежа досі цінна як оглядовий пункт. Відступники тримають тут заставу й розміщують своїх агентів — як-от Скрадача Смерті Леша, — щоб стежити за місцевими патрулями Альянсу, сусідніми людськими поселеннями на Полях Гілсбреду та мандрівниками на головному шляху. Через самотнє розташування просто біля ворожих земель вежа часто стає осередком сутичок."}},faq={{q="Де розташована Вежа Південного Мису?",a="Вежа Південного Мису стоїть на західному краю Передгір'я Гілсбреда, просто на південь від дороги до Срібнолісся й трохи на захід від Полів Гілсбреду.",al={"розташування вежі південного мису","де вежа південного мису","знайти вежу південного мису"}},{q="Хто зараз тримає Вежу Південного Мису?",a="Вежу тримають Відступники. У її зруйнованих стінах стоїть агент на ім'я Скрадач Смерті Леш, що стежить за дорогою й за силами Альянсу поблизу.",al={"хто у вежі південного мису","хто володіє вежею південного мису","фракція вежі південного мису"}},{q="Чому вежа в руїнах?",a="Вежу розбили й покинули під час падіння Лордерона, коли Погибель спустошувала край. Її так і не відбудували, тож лишилися тільки розбиті кам'яні стіни.",al={"чому вежа зруйнована","хто зруйнував вежу південного мису"}},{q="Чому гравці Альянсу нападають на цю заставу?",a="На посту стоїть самотній розвідник-Відступник, що стежить за людськими землями. Відрізаний від своїх біля кордону, він — легка й спокуслива ціль для мандрівників Альянсу між Саутшором і західними дорогами.",al={"чому вбивати скрадача смерті леша","альянс нападає на вежу південного мису"}}},fp="16,286,17.431.0,17.407.0,34.162.0,40.173.0,26.163.0,44.214.0"}
P.entries["subzone:southshore"] = {n="Саутшор",s="Саутшор — приморський людський порт у Передгір'ї Гілсбреда й одна з небагатьох уцілілих твердинь Альянсу в занепалому Лордероні. Колись сонне рибальське селище, тепер це оплот в облозі, якому постійно загрожують гарнізон Відступників у Таррен Міллі, свавільні розбійники Синдикату й прибережні потвори.",h="Саутшор — приморський людський порт у Передгір'ї Гілсбреда й одна з небагатьох уцілілих твердинь Альянсу в...",kw={"саутшор","альянс","таррен мілл","магістрат генрі малеб","маршал редпат","гілсбред"},ang={["faction:Alliance"]="Саутшор — ваш головний прихисток, джерело завдань і військовий редут на півночі Лордерона, що дає необхідну підтримку проти Відступників і Синдикату.",["faction:Horde"]="Для Орди — особливо для Відступників із сусіднього Таррен Мілла — Саутшор уособлює вперту твердиню Альянсу, що засіла на землі, яку відвоювали мерці."},sec={{t="Маяк у Лордероні",b="Саутшор уперше прославився під час Першої війни, коли на його берег висадилися човни з біженцями, що вціліли після падіння королівства Стормвінд. Хоч під час Другої війни за нього билися й навіть захоплювали, його відбудували, і згодом він пережив жахи Третьої війни. Сьогодні, коли решта Лордерона лежить у руїнах або під владою Відступників, Саутшор лишається затято вірним Великому Альянсу. Він дає прихисток людям, що втратили домівки, ветеранам-паладинам Срібної Длані й ученим Кірін-Тору."},{t="В облозі з усіх боків",b="Попри мальовничі доки й славетний черепаховий суп, життя в Саутшорі небезпечне. Під проводом Магістрата Генрі Малеба й Маршала Редпата містечко бореться з невпинним тиском. На півночі Відступники Таррен Мілла ведуть запеклу прикордонну війну за панування над Гілсбредом. У глибині суходолу розбійники-аристократи із Синдикату нападають на шляхи постачання й убивають місцевих ватажків, а огри, мурлоки й наги постійно турбують межі містечка."}},faq={{q="Чому Саутшор досі вірний Альянсу, хоча Лордерон упав?",a="Саутшор уник цілковитого знищення під час навали Погибелі. Його вцілілі мешканці-люди підтвердили давню присягу Великому Альянсу й отримують від Стормвінда військову та господарську підтримку, щоб утримувати плацдарм на півночі.",al={"чому саутшор вірний альянсу","хто контролює саутшор","саутшор альянс лордерон"}},{q="Чому між Саутшором і Таррен Міллом такі запеклі бої?",a="Таррен Мілл тримають Відступники, а Саутшор — головний оплот Альянсу в краї. Обидві сторони вважають Передгір'я Гілсбреда своїм по праву, тож на кордоні майже безупинно тривають сутички, набіги й диверсії.",al={"війна саутшора й таррен міла","чому б'ються саутшор і таррен мілл","конфлікт гілсбреду"}},{q="Хто очолює містечко Саутшор?",a="Цивільними справами опікується Магістрат Генрі Малеб, що обійняв посаду після того, як Синдикат убив попереднього магістрата. Військовою обороною й безпекою містечка керує Маршал Редпат.",al={"лідер саутшора","хто керує саутшором","магістрат малеб"}},{q="Що, окрім Відступників, загрожує Саутшору?",a="Окрім Відступників, Саутшор мусить відбиватися від прибережних мурлоків і наг, огрів-Трощихребтів, що спускаються з Гір Альтерак, і злочинного Синдикату, що засів у Твердині Дурнгольд.",al={"вороги саутшора","загрози саутшору"}}},fp="10,321,21.528.0,22.451.0,70.248.0,70.235.0,33.201.0,58.183.0"}
P.entries["subzone:southshore-town-hall"] = {n="Ратуша Саутшора",s="Ратуша Саутшора — адміністративний осередок південного узбережжя Передгір'я Гілсбреда, один з останніх дієвих осередків цивільної влади Лордерона. Звідси Магістрат Генрі Малеб керує місцевою обороною й урядує вцілілими мешканцями міста. Для Альянсу ратуша — життєво важливий центр у боротьбі за опору на зачумленій півночі.",h="Ратуша Саутшора — адміністративний осередок південного узбережжя Передгір'я Гілсбреда, один з останніх дієвих...",kw={"ратуша саутшора","саутшор","генрі малеб","магістрат","альянс","лордерон"},ang={["faction:Alliance"]="Для поборників Альянсу, що прибувають на північ, Ратуша Саутшора — головна цивільна застава, яка представляє владу в краї й дає важливі доручення проти навколишніх загроз.",["race:Human"]="Людям ратуша зворушливо нагадує про втрачену славу Лордерона: тут дієвий магістрат досі тримає прапори розбитого королівства."},sec={{t="Оплот цивільної влади",b="Тоді як більша частина Лордерона лежить у руїнах під скверною Погибелі й натиском Відступників, ратуша Саутшора зберігає подобу непорушеного людського врядування. Магістрат Генрі Малеб щодня порядкує справами зі свого кабінету тут, працюючи пліч-о-пліч із посадовцями на кшталт Кундріка Зандена, щоб забезпечити місто ресурсами й зберегти громадський лад. У краї, оточеному агресивною нежиттю, розбійниками Синдикату й запеклими прикордонними сутичками Гілсбреда, ратуша — нервовий центр, що спрямовує боротьбу міста за виживання перед безупинними загрозами."}},faq={{q="Хто керує містечком із Ратуші Саутшора?",a="Магістрат Генрі Малеб — головний цивільний очільник Саутшора: він вершить справи містечка з ратуші, керуючи обороною й управлінням уцілілого людського поселення.",al={"хто керує саутшором","мер саутшора","хто тут головний"}},{q="Яке стратегічне значення Ратуші Саутшора?",a="Це один з останніх осідків законної цивільної влади Лордерона на півночі. Члени Альянсу звертаються до ратуші по вказівки, винагороди й узгодження дій проти Відступників і розбійників Синдикату, що підступають дедалі ближче.",al={"чому ратуша важлива","значення саутшора"}},{q="Хто ще працює в ратуші?",a="Поряд із Магістратом Генрі Малебом у ратуші працюють урядовці, як-от Кундрік Занден, що допомагають вести місцеві справи й підтримують життя містечка.",al={"хто в ратуші саутшора","кундрік занден","нпс ратуші"}},{q="Як ратуша підтримує зв'язки з рештою Альянсу?",a="Хоча Саутшор історично належав до королівства Лордерон, тепер містечко та його влада значною мірою покладаються на Альянс, отримуючи підкріплення й припаси, щоб боронити цей відрізаний прибережний оплот від довколишніх ворогів.",al={"чи саутшор альянсу","зв'язки зі стормвіндом"}}},fp="20,389,23.520.0,49.201.0,57.228.0,36.174.0,61.231.0"}
P.entries["subzone:southwind-village"] = {n="Село Південного Вітру",s="Село Південного Вітру — руїни застави нічних ельфів серед пісків Силітусу, де живуть привиди. Кіражі стерли його з лиця землі під час Війни Мінливих Пісків, і тепер його вулицями блукають неспокійні духи полеглих захисників, а довкола нишпорять силітиди.",h="Село Південного Вітру — руїни застави нічних ельфів серед пісків Силітусу, де живуть привиди.",kw={"село південного вітру","вальстанн стаґгелм","війна мінливих пісків","кіражі","привиди","силітус"},ang={["class:Druid"]="Зруйновані споруди, схожі на гаї, і змучені духи давніх друїдів, що лишилися в Селі Південного Вітру, — похмуре нагадування про те, що втратила природа в боротьбі з ордами комах.",["race:NightElf"]="Для нічних ельфів Село Південного Вітру — одна з найболісніших поразок у їхній історії, а змучені привиди, що блукають його розваленими мурами, — це їхні побратими-калдореї, які досі чекають на спокій."},sec={{t="Трагедія в пісках",b="Тисячу років тому, під час прадавньої Війни Мінливих Пісків, Село Південного Вітру було однією з головних твердинь нічних ельфів. Коли легіони кіражів прорвали оборону, Вальстанн Стаґгелм — син архідруїда Фандрала Стаґгелма — повів загін, щоб утримати село. Оборона завершилася цілковитою катастрофою: захисників-калдореїв здолали й вирізали, а самого Вальстанна забрав у полон Генерал Раджакс. Село зруйнували вщент, і від колишніх будівель під пекучим сонцем лишилися самі уламки."},{t="Змучені мерці",b="Минуло тисячоліття, відколи село впало, а воно й досі — відкрита рана пустелі. Жах того нападу був такий нестерпний, що духи вбитих Вартових і друїдів з нічних ельфів не змогли піти далі. Збожеволілі від жаху своїх останніх миттєвостей, ці неспокійні привиди на чолі з Примарою Ембермуна без кінця блукають серед розвалених кам'яних мурів і кидаються на кожного, хто їх потривожить, а в дюнах довкола рояться хижі силітиди."}},faq={{q="Що сталося з Селом Південного Вітру?",a="Село Південного Вітру знищено тисячу років тому під час Війни Мінливих Пісків. Ненажерливе військо кіраджі заполонило гарнізон нічних ельфів, безжально вирізало захисників і зрівняло заставу з землею.",al={"чому село південного вітру зруйноване","лор південного вітру","що знищило село південного вітру"}},{q="Хто такий Валстанн Стаґгелм?",a="Валстанн Стаґгелм — улюблений син Верховного друїда Фандрала Стаґгелма. Він очолив відчайдушну оборону Села Південного Вітру від комашиної навали, але його військо було знищене, а самого його полонив командир кіраджі Генерал Раджакс.",al={"валстанн стаґгелм південний вітер","син фендрала стаґгелма","хто обороняв південний вітер"}},{q="Чому тут привиди нічних ельфів?",a="Раптова й жорстока різанина захисників замкнула їхні душі в руїнах. Духи вбитих друїдів і Вартових приречені вічно переживати свою останню, моторошну битву, а над ними досі нависає Примара Ембермуна.",al={"духи південного вітру","чому в південному вітрі привиди","тінь бурштинового місяця"}},{q="Чи пов'язані ці комахи з тим, що знищило село?",a="Так. Силітиди, що роються довкола руїн, — частина тієї самої комашиної навали, пов'язаної з кіраджі, тієї сили, що століття тому вдерлася в Силітус і знищила заставу.",al={"силітиди південний вітер","чи комахи пов'язані з південним вітром"}}},fp="17,249,22.540.0,18.438.0,35.214.0,26.242.0,36.239.0,51.183.0"}
P.entries["subzone:spirit-rise"] = {n="Узвишшя Духів",s="Узвишшя Духів — північно-західна столова гора Тандер Блафа, головне святилище тауренської столиці для духовних і шаманських студій. Тут, під опікою духовних провідників на кшталт племені Скайчейсер, нагорі стоять священні зали навчання, а внизу печера спускається до Ставків Видінь.",h="Узвишшя Духів — північно-західна столова гора Тандер Блафа, головне святилище тауренської столиці для...",kw={"узвишшя духів","тандер блаф","шамани","ставки видінь","зала духів","стихії"},ang={["class:Shaman"]="Для шаманів Орди Узвишшя Духів — важливе місце збору: тут можна порадитися з наставниками, провести стихійні обряди й поєднатися з духами предків.",["race:Tauren"]="Узвишшя втілює глибоке духовне коріння вашого народу й дарує розраду від мирських обов'язків поруч із містичними водами Ставків Видінь."},sec={{t="Святилище духів",b="Узвишшя Духів, що височіє над рівнинами Малгору, віддане єднанню зі стихіями й духами предків. З'єднане з центральною горою мотузяними мостами, воно прихищає Залу Духів і павільйон Духовного зцілення, де молоді й бувалі шамани збираються, щоб поглибити зв'язок із землею, повітрям, вогнем і водою. Плем'я Скайчейсер має на узвишші помітну присутність і веде шукачів давніми традиціями."},{t="Печери й переходи",b="Під продуваними вітром хатинами й тотемними святинями просто неба вхід веде вглиб самої гори — до сповнених пари Ставків Видінь, священної підземної печери, де провидці вдивляються у води, яких торкнулися духи."}},faq={{q="Чим славиться Узвишшя Духів?",a="Узвишшя Духів — духовне серце Тандер Блафа, присвячене насамперед шаманським практикам, зціленню й спілкуванню з духами природи та предків. Тут же вхід до Ставків Видінь.",al={"що таке узвишшя духів","призначення узвишшя духів","навіщо йти на узвишшя духів"}},{q="Яке плем'я тауренів верховодить на Узвишші Духів?",a="Тут має помітний вплив плем'я Скайчейзерів, що плекає духовні традиції, обряди ворожіння й навчання шаманів, якими славиться це узвишшя.",al={"хто керує узвишшям духів","плем'я узвишшя духів","плем'я небоходців"}},{q="Що можна знайти під Узвишшям Духів?",a="Спуск крізь узвишшя веде до Ставків Видінь — вологої підземної печери з гарячими водами, де провидці й духовні практики медитують і шукають видінь.",al={"печера узвишшя духів","що під узвишшям духів","вхід у ставки видінь"}}},fp="11,286,26.464.0,19.201.0,30.207.0,51.151.0,39.181.0"}
P.entries["subzone:spirit-rock"] = {n="Камінь Духів",s="Камінь Духів — священна скеля на суворих кручах над Долиною Випробувань у Дуротарі. Дістатися до неї можна звивистою стежкою, відомою як Прихована Стежка; це відлюдне святе місце, де посвячувані безпосередньо спілкуються зі стихійними силами землі.",h="Камінь Духів — священна скеля на суворих кручах над Долиною Випробувань у Дуротарі.",kw={"камінь духів","шамани","духи землі","сапта","прихована стежка","долина випробувань","дуротар"},ang={["class:Shaman"]="Камінь Духів — важливий обряд посвяти для молодих шаманів з орків і тролів, які піднімаються Прихованою Стежкою, щоб випити Земляну Сапту й укласти перший зв'язок із духами каменю та ґрунту."},sec={{t="Святилище стихій",b="Над червоним каньйоном, де молоді воїни та розвідники Орди починають навчання, Камінь Духів стоїть як вівтар єднання з духами. Відокремлений від гамору Долини Випробувань, він доступний лише Прихованою Стежкою, що в'ється скелястим гребенем. Майбутні шамани здійснюють паломництво до цього пустельного виступу, щоб випити традиційну сапту й, пронизавши завісу тілесного світу, почути гуркіт і шепіт самої землі."}},faq={{q="Для чого потрібен Камінь Духів?",a="Камінь Духів — священне місце, куди приходять здебільшого шамани-початківці Орди. Випивши біля каменя особливий напій — Земляну Сапту, — новачки здобувають духовний зір, потрібний, щоб безпосередньо спілкуватися з духами землі.",al={"призначення каменя духів","що відбувається біля каменя духів","навіщо камінь духів"}},{q="Як дістатися до Каменя Духів?",a="Камінь Духів — високо в скелях над Долиною Випробувань на південному заході Дуротару. Потрапити туди можна Прихованою Стежкою — вузькою непозначеною стежкою, що в'ється з дна каньйону в скелясті пагорби.",al={"як дістатися до каменя духів","шлях до каменя духів","розташування каменя духів"}},{q="Що таке сапта?",a="Сапта — обрядовий стихійний напій, який готують наставники шаманів. Випивши його, шукач бачить світ інакше й може помічати прояви стихій, невидимі для звичайних чуттів.",al={"земна сапта","що таке сапта","напій сапта"}}},fp="11,255,27.445.0,29.236.0,29.217.0,16.204.0"}
P.entries["subzone:splintertree-post"] = {n="Застава Розщепленого Дерева",s="Застава Розщепленого Дерева — головна фортеця Орди у східному Ашенвалі, на північний захід від Пагорба Вогню Скверни. Заснована Ґроммашем Хеллскрімом і кланом Бойової Пісні під час Третьої війни, вона слугує потужно укріпленим оплотом проти нічних ельфів і плацдармом для захоплення нових земель.",h="Застава Розщепленого Дерева — головна фортеця Орди у східному Ашенвалі, на північний захід від Пагорба Вогню...",kw={"застава розщепленого дерева","орда","бойова пісня","ґроммаш хеллскрім","фортеця","ашенваль"},ang={["faction:Horde"]="Застава Розщепленого Дерева — головний табір для шукачів пригод, що пробиваються крізь Ашенваль: тут можна полагодити спорядження, перепочити й вирушити в політ до інших куточків Калімдору.",["race:NightElf"]="Для нічних ельфів ця фортеця — гіркий шрам на тілі Ашенвалю: її заснував той самий воєначальник, що вбив Кенарія, а тримають загарбники, які рубають їхні прадавні дерева."},sec={{t="Прикордонна твердиня",b="Застава Розщепленого Дерева, вирубана просто в прадавньому лісі, — головний військовий і постачальний осередок Орди у східному Ашенвалі. Її заснували Ґроммаш Хеллскрім і клан Бойової Пісні, коли орки вперше вдерлися в ліс під час Третьої війни, і вона досі лишається добре озброєним анклавом, який обороняють переважно розвідники й воїни — орки та таурени. Тут є господар вітрокрилів, корчма й надійні шляхи постачання до Оргріммара, тож застава — опора спірної присутності Орди під кронами лісу."},{t="Постійна загроза відплати",b="Застава Розщепленого Дерева живе в постійній готовності. Нічні ельфи не забули й не пробачили Ґроммашеві того, що він накоїв під час війни, і не миряться з орківськими вирубками та набігами на Астранаар. Тож поселення раз у раз зазнає відплатних ударів і партизанських нападів Вартових, що ховаються в довколишньому лісі, і вартові гарнізону не мають спокою ні вдень, ні вночі."}},faq={{q="Хто заснував Заставу Розщепленого Дерева?",a="Її заснували Ґроммаш Хеллскрім і клан Бойової Пісні, коли орки під час Третьої війни вперше вдерлися в Ашенваль, щоб заготовляти деревину й закріпитися тут.",al={"хто заснував розщеплене дерево","засновник розщепленого дерева","ґром розщеплене дерево"}},{q="Чому нічні ельфи так часто нападають на цю базу?",a="Нічні ельфи вважають Розщеплене Дерево незаконним і блюзнірським вторгненням на землі предків. Ворожнеча тягнеться ще від жорстоких походів Ґроммаша в Третій війні, а підживлюють її вирубка лісу Ордою й сутички з сусідньою ельфійською твердинею Астранаар.",al={"чому ельфи нападають","напади вартових на розщеплене дерево","рейди нічних ельфів"}},{q="Які зручності й можливості для подорожей тут є?",a="На Заставі Розщепленого Дерева є корчма, доглядач стайні, поштова скринька, ремонт обладунків і розпорядник польотів на вітрокрилах із маршрутами до Оргріммара, Перехрестя та інших застав Орди по всьому Калімдору.",al={"політ розщепленого дерева","послуги розщепленого дерева","корчма розщепленого дерева"}},{q="Хто зараз у гарнізоні Розщепленого Дерева?",a="Поселення населяють переважно орки й таурени — досвідчені розвідники, вартові й офіцери передової, яким доручено втримати прикордоння.",al={"охорона розщепленого дерева","хто живе в розщепленому дереві","раси розщепленого дерева"}}},fp="17,296,21.505.0,34.402.0,30.168.0,51.264.0,53.198.0,52.156.0"}
P.entries["subzone:splithoof-crag"] = {n="Круча Розколотого Копита",s="Круча Розколотого Копита — укріплене поселення кентаврів Ґалак під північними скелями Тисячі Голок. Поряд зі столовими горами це один з головних осередків племені, що стереже вхід до Твердині Розщепленого Копита. Мандрівникам, які йдуть дном каньйону, доводиться мати справу з агресивними дозорами Ґалак, що никають біля круч.",h="Круча Розколотого Копита — укріплене поселення кентаврів Ґалак під північними скелями Тисячі Голок.",kw={"круча розколотого копита","кентаври ґалак","тисяча голок","роздвоєне копито","печери","таурени"},ang={["faction:Horde"]="Контроль над проходом під кручами вкрай важливий, щоб безпечно мандрувати між південними Пустками, Заставою Вільного Вітру та Мерехтливими Низинами.",["race:Tauren"]="Через давню ворожнечу між тауренами й кентаврами Круча Розколотого Копита — нагальна турбота розвідників Орди, які стежать за ворогами по всій Тисячі Голок."},sec={{t="Твердиня Ґалак",b="Круча Розколотого Копита тулиться до прямовисної північної скельної стіни Тисячі Голок, трохи на схід від височенного Шпиля Темної Хмари. Це давній осередок кентаврів Ґалак із грубими наметовими таборами й ґрунтовими стежками, що в'ються поміж скель. У серці селища, під самою кручею, лежить Твердиня Розщепленого Копита — підземна печера, де зберігається Роздвоєне Копито, прадавня реліквія кентаврів, яку оберігає священна жаровня."},{t="Оборона печер",b="Ґалак люто обстоюють цей куток каньйону й нападають на всіх мандрівників, експедиції Орди та тауренських розвідників, які забредуть під їхні кручі. Поки Ґрімтотеми сидять на височенних шпилях неподалік, кентаври міцно тримають цей яр і печери, видовбані глибоко під каменем."}},faq={{q="Хто живе на Кручі Розколотого Копита?",a="Поселення належить племені кентаврів Ґалак — одному з помітних кланів, що живуть у Тисячі Голок поряд із ворожими тауренами-Ґрімтотемами.",al={"хто на кручі розколотого копита","моби розколотого копита","кентаври розколотого копита"}},{q="Де розташована Круча Розколотого Копита?",a="Вона лежить біля північної стіни каньйону Тисячі Голок, просто на схід від Шпиля Темної Хмари.",al={"де круча розколотого копита","розташування розколотого копита"}},{q="Що в Твердині Розщепленого Копита?",a="Твердиня Розщепленого Копита — центральна печера селища. Глибоко в її залах кентаври Ґалак стережуть Роздвоєне Копито — давній артефакт племені, захищений священним полум'ям, що палає в давній жаровні.",al={"що таке твердиня розщепленого копита","печера розколотого копита"}},{q="Чи в союзі тутешні кентаври з сусідніми Ґрімтотемами?",a="Ні. Кентаври Ґалак і таурени-Ґрімтотеми зі Шпиля Темної Хмари — запеклі суперники, що борються за панування над цією частиною каньйону.",al={"ґрімтотеми й ґалак","кентаври й таурени"}}},fp="14,336,18.447.0,21.318.0,28.145.0,32.105.0,30.196.0,54.155.0"}
P.entries["subzone:splithoof-hold"] = {n="Твердиня Розщепленого Копита",s="Твердиня Розщепленого Копита — глибока печерна твердиня, видовбана в камені Кручі Розколотого Копита в Тисячі Голок. Її тримає плем'я кентаврів Ґалак: печера править за укріплене лігво, а в ній стоїть Прадавня Жаровня, де вічно горить священне полум'я.",h="Твердиня Розщепленого Копита — глибока печерна твердиня, видовбана в камені Кручі Розколотого Копита в Тисячі...",kw={"твердиня розщепленого копита","кентаври ґалак","священне полум'я","печера","тисяча голок","жаровня"},ang={["class:Shaman"]="Вічне полум'я, що палає глибоко в темній кам'яній печері, неминуче привертає увагу кожного духовидця, налаштованого на первісні таємниці вогняної стихії.",["race:Tauren"]="Кентаври Ґалак лишаються заклятими кровними ворогами тауренів, тож будь-яка їхня твердиня в Тисячі Голок — пряма загроза спокою Застави Вільного Вітру."},sec={{t="Оплот кентаврів",b="Твердиня Розщепленого Копита, захована всередині Кручі Розколотого Копита, — укріплений сховок кентаврів Ґалак. На відміну від обвітреного дна каньйону, ця замкнена печера дає їм прихисток, вузькі проходи, які легко боронити, і надійне укриття від племен-суперників і мандрівників, що йдуть крізь Голки."},{t="Священне Полум'я",b="У темних глибинах твердині стоїть прадавня жаровня, у якій горить Священне Полум'я. Цей містичний вогонь палає без упину: для кентаврів він — осердя сили й предмет обрядового шанування, а для духовних шукачів з усього каньйону — велика загадка."}},faq={{q="Де розташована Твердиня Розщепленого Копита?",a="Твердиня Розщепленого Копита — серед круч і укріплень Кручі Розколотого Копита, біля північних скель Тисячі Голок. Вхід до неї — печера посеред головного поселення кентаврів.",al={"розташування твердині розщепленого копита","де твердиня розщепленого копита","як знайти твердиню розщепленого копита"}},{q="Хто тримає Твердиню Розщепленого Копита?",a="Печеру тримає плем'я кентаврів Ґалак, що люто боронить її від чужинців, звірів і сусідніх тауренів із Застави Вільного Вітру.",al={"хто живе в твердині розщепленого копита","моби розщепленого копита","хто володіє твердинею розщепленого копита"}},{q="Що всередині твердині?",a="Окрім ворожих захисників-кентаврів Ґалак, у печері стоїть Давня Жаровня — артефакт, що підтримує вічне горіння містичного Священного Полум'я в глибині скелі.",al={"що в твердині розщепленого копита","де давня жаровня","священне полум'я розщепленого копита"}}},fp="14,255,17.285.0,16.278.0,32.203.0,28.156.0,24.174.0"}
P.entries["subzone:stagalbog"] = {n="Стаґалбоґ",s="Стаґалбоґ — густа, просякнута водою смуга трясовини на півдні Болота Скорботи. Вона межує з південним гірським пасмом трохи нижче від Ставка Сліз і досі лишається неприборканою глушиною.",h="Стаґалбоґ — густа, просякнута водою смуга трясовини на півдні Болота Скорботи.",kw={"стаґалбоґ","болото скорботи","ставок сліз","трясовина","травництво","затонулий храм"},ang={["class:Hunter"]="Тихі смуги між болотяною водою й гірськими кручами роблять Стаґалбоґ чудовим місцем, щоб вистежувати місцевих болотяних звірів.",["profession:Herbalism"]="Волога земля Стаґалбоґу, куди майже не зазирає сонце, — чудове місце для болотяних рослин, які процвітають подалі від протоптаних стежок."},sec={{t="Південна трясовина",b="Стаґалбоґ, що простягається в тіні південних скель, — типовий куточок Болота Скорботи: стояча вода, похилений очерет і сплутані зарості. Він лежить одразу на південь від затонулих руїн Храму Атал'Гаккара, затиснутий між оскверненим озером і скелястою межею краю. Окрім дикої звірини, тут немає нічого — цивілізація так і не закріпилася в цих місцях."},{t="У тіні храму",b="Стаґалбоґ межує зі Ставком Сліз, тож сюди часто докочуються тіні й скверна, що просочуються із Затонулого Храму."}},faq={{q="Де розташований Стаґалбоґ?",a="Стаґалбоґ лежить у південній частині Болота Скорботи, просто на південь від Ставка Сліз, і тягнеться вздовж підніжжя південного гірського хребта.",al={"розташування стаґалбоґа","де стаґалбоґ","як знайти стаґалбоґ"}},{q="Які загрози блукають цим болотом?",a="На болоті живуть місцеві болотяні звірі й хижі створіння.",al={"моби стаґалбоґа","монстри стаґалбоґа"}}},fp="9,206,17.378.0,20.131.0,31.174.0,44.72.0"}
P.entries["subzone:stagalbog-cave"] = {n="Печера Стаґалбоґ",s="Печера Стаґалбоґ — волога підземна печера в Стаґалбоґу, на сході Болота Скорботи. Тут облаштували укріплене лігво болотяні мурлоки та їхній зловісний духовний провідник — Болотний Мовець.",h="Печера Стаґалбоґ — волога підземна печера в Стаґалбоґу, на сході Болота Скорботи.",kw={"печера стаґалбоґ","мурлоки","болотний мовець","болотяне плем'я","болото скорботи"},sec={{t="Лігво Болотяного племені",b="Печера Стаґалбоґ, що ховається в похмурих східних драговинах Болота Скорботи, захищає місцевих мурлоків від невпинних болотяних дощів. Ці земноводні створіння, відомі як Болотяне плем'я, ревно стережуть звивисті печерні зали разом зі своїм верховним містиком — Болотним Мовцем. Мандрівники, що підходять до потопленої трясовини Стаґалбоґу, часто чують, як їхні булькітливі поклики луною розлітаються над моховитими берегами, відганяючи чужинців від гнізд."}},faq={{q="Що таке Печера Стаґалбоґ?",a="Печера Стаґалбоґ — природна печера в Стаґалбоґу, на сході Болота Скорботи. Її здебільшого займає люте поселення мурлоків Болотного племені.",al={"де печера стаґалбоґ","що в печері стаґалбоґ"}},{q="Хто править печерою?",a="У печері панує Болотне плем'я та його ватажок — Болотний Мовець, впливовий мурлок-містик, що наглядає за обрядами й обороною племені у вологих печерних залах.",al={"бос печери стаґалбоґ","болотяний мовець","хто веде мурлоків"}},{q="Чи є поблизу дружні поселення?",a="Печеру оточують дикі, ворожі болота. Проте в ширшому Болоті Скорботи на заході стоїть застава Орди Стонард, а нейтральні мандрівники й гобліни часом розвідують довколишні водойми.",al={"найближче містечко","торговці біля стаґалбоґа"}}},fp="14,228,22.480.0,23.177.0,19.179.0,38.216.0"}
P.entries["subzone:staghelm-point"] = {n="Мис Стаґгелма",s="Мис Стаґгелма — прадавня сторожова вежа нічних ельфів на скелястій вершині в північно-східному Силітусі. Звідси видно дюни, що наступають, і недалекі печери Сутінкового Проходу, тож вежа несе варту проти прадавніх загроз, що чигають у пустелі.",h="Мис Стаґгелма — прадавня сторожова вежа нічних ельфів на скелястій вершині в північно-східному Силітусі.",kw={"мис стаґгелма","силітус","сутінковий прохід","рало'шан","війна мінливих пісків","калдореї"},ang={["class:Druid"]="Вежа носить ім'я Стаґгелмів і дає змогу в задумі споглядати зіпсований посушливий дикий край, що кидає виклик рівновазі природи.",["race:NightElf"]="Мис Стаґгелма пробуджує урочисту пам'ять про Війну Мінливих Пісків і суворо нагадує, якою тяжкою ціною калдореї стримали жахіття, що ховаються під Силітусом."},sec={{t="Мовчазна варта над пісками",b="Мис Стаґгелма, що високо здіймається над посушливими рівнинами північно-східного Силітусу, увінчує самотня вежа нічних ельфів. Застава — наче самотній вартовий, що стежить за пустелею й за культистами, які ховаються в тінях сусідніх печер на кшталт Сутінкового Проходу. Вежу стереже Рало'шан Вічний Вартовий, а над нею кружляє бронзовий дракон. Вона носить горде й трагічне ім'я роду Стаґгелмів — нагадування про величезні жертви, яких калдореї зазнали під час прадавньої Війни Мінливих Пісків."}},faq={{q="Хто живе на Мисі Стаґгелма?",a="Самотню вежу стереже Рало'шан Вічний Вартовий, а в небі над нею безупинно патрулює величний бронзовий дракон із Виводку Ноздорму.",al={"хто на мисі стаґгелма","нпс мису стаґгелма","рало'шан"}},{q="Які небезпеки чатують поблизу?",a="Унизу, куди в'ється стежка від вершини, лежить Сутінковий Прохід — печера з табором довкола, що кишать фанатиками культу Молота Присмерку.",al={"небезпеки мису стаґгелма","вороги поблизу","сутінковий прохід"}}},fp="14,257,30.531.0,28.165.0,24.154.0"}
P.entries["subzone:starbreeze-village"] = {n="Село Зоряного Вітерця",s="Село Зоряного Вітерця — покинуте поселення нічних ельфів на схід від Доланаара на Тельдрассилі. Колись тихе лісове сільце, воно нещодавно дісталося збожеволілим фурболгам племені Вузлошкірів. Зруйноване поселення тепер стоїть як кричущий символ скверни, що просочується в коріння Світового Дерева.",h="Село Зоряного Вітерця — покинуте поселення нічних ельфів на схід від Доланаара на Тельдрассилі.",kw={"село зоряного вітерця","покинуте село","фурболги","вузлошкіри","фероцитас","урусон","тельдрассил"},ang={["class:Druid"]="Божевілля, що пожирає фурболгів-Вузлошкірів, і осквернення Села Зоряного Вітерця — прямий виклик обов'язку Кола Кенарія відновити рівновагу живності Тельдрассила.",["race:NightElf"]="Бачити, як ельфійське поселення так близько до Доланаара обертається на руїну, — болісне нагадування про хистке становище Тельдрассила й скверну, що гризе Світове Дерево."},sec={{t="Занепале сільце",b="Село Зоряного Вітерця, що лежить на південний схід від Тінедолу, просто за дорогою від Доланаара, колись було домівкою мирних родин нічних ельфів під гіллям Тельдрассила. Сьогодні село в руїнах, а його дерев'яні будівлі заполонили агресивні фурболги-Вузлошкіри. Здичавілі від лиховісної скверни, що вразила гілля Світового Дерева, звіролюди вигнали ельфійських мешканців і тепер люто боронять зруйновані землі."},{t="Загроза Фероцитаса",b="Присутність Вузлошкірів у селі — не звичайний територіальний наскок. На околиці поселення чаїться Фероцитас, Пожирач Снів — загадкова зіпсута сутність, чия присутність свідчить, що фурболгів зводить з розуму темна, нечиста магія. Разом із такими здоровенними звірами, як Урусон, що нишпорить стежками, ці загарбники роблять Село Зоряного Вітерця справжньою небезпекою для мандрівників східного Тельдрассила."}},faq={{q="Чому Село Зоряного Вітерця покинуте?",a="Село захопили, коли фурболги-Вузлошкіри стали жертвою скверни, що розповзається Тельдрассилом. Збожеволілі й люті, фурболги напали на мешканців — нічних ельфів, — і тим довелося тікати, покинувши свої домівки.",al={"що сталося з зоряним вітерцем","чому зоряний вітерець зруйнований","зоряний вітерець порожній"}},{q="Хто тепер живе в Селі Зоряного Вітерця?",a="Нині в селі отаборилися ворожі фурболги-Вузлошкіри. Серед помітних постатей — Урусон, що блукає довкола з патрулем, і зіпсована істота, відома як Фероцитас, Пожирач Снів.",al={"хто в зоряному вітерці","моби зоряного вітерця","хто захопив зоряний вітерець"}},{q="Де розташоване Село Зоряного Вітерця?",a="Село Зоряного Вітерця лежить на сході Тельдрассилу, на південний схід від Тінедолу й на схід від Доланаару.",al={"де зоряний вітерець","зоряний вітерець на мапі","як знайти зоряний вітерець"}},{q="Хто такий Фероцитас, Пожирач Снів?",a="Фероцитас — небезпечна зіпсована істота на околицях Села Зоряного Вітерця, пов'язана з темними силами, що доводять місцеве плем'я Вузлошкірів до шаленства.",al={"лор фероцитаса","хто такий фероцитас","фероцитас зоряний вітерець"}}},fp="18,322,15.444.0,23.426.1,36.225.0,36.174.0,36.104.0,33.169.0"}
P.entries["subzone:starfall-village"] = {n="Селище Зорепаду",s="Селище Зорепаду — тихий притулок нічних ельфів, що затишно вмостився біля засніженої дороги у Вінтерспрінгу. Це єдиний аванпост Альянсу в скутій морозом долині: тут знаходять дах над головою й припаси ті, хто наважився кинути виклик лютому північному холоду. А ще селище пильнує сусіднє курганне лігво.",h="Селище Зорепаду — тихий притулок нічних ельфів, що затишно вмостився біля засніженої дороги у Вінтерспрінгу.",kw={"селище зорепаду","вінтерспрінг","альянс","нічні ельфи","курганне лігво","евірлук"},ang={["faction:Alliance"]="Селище Зорепаду — єдине поселення Альянсу у Вінтерспрінгу, тож у цьому підступному й віддаленому гірському краї саме тут ви зможете перепочити, придбати товари й розпитати дорогу.",["race:NightElf"]="Для нічних ельфів Зорепад — важливий північний аванпост, що стоїть біля тихого, безлюдного курганного лігва."},sec={{t="Прихисток Альянсу серед снігів",b="Селище Зорепаду лежить на північний захід від гоблінського торговельного містечка Евірлук і на південь від Каменю Морозних Шаблезубів. Це єдиний оплот цивілізації Альянсу у Вінтерспрінгу. Складене з традиційних дерев'яних осель нічних ельфів, поселення править за пристанище для подорожніх: тут можна поповнити конче потрібні припаси й погрітися біля теплого вогнища, сховавшись від суворої гірської негоди. Попри мирний вигляд, селище завжди насторожі, адже поруч із ним — тихе, безлюдне курганне лігво."}},faq={{q="Що таке Селище Зорепаду?",a="Селище Зорепаду — анклав нічних ельфів у Вінтерспрінгу. Це головний прихисток і табір постачання Альянсу в долині: тут є нічліг, торгівля й настанови для розвідників, що прямують до Каменя Морозних Шаблезубів чи досліджують сусідні курганні лігва.",al={"зорепад","містечко зорепад","що це за місце"}},{q="Чи можуть гравці Орди користуватися послугами Селища Зорепаду?",a="Ні. Селище Зорепаду служить лише нічним ельфам і Альянсу. Мандрівників Орди, що забредуть надто близько, місцеві захисники зустрінуть вороже.",al={"чи дружній зорепад до орди","чи орда може користуватися зорепадом","селище зорепаду орда"}},{q="Що за курганне лігво біля селища?",a="Печера просто за селищем — порожнє курганне лігво. Такі прихистки зазвичай дають сховок друїдам, поки їхні духи мандрують Смарагдовим Сном, але тут не спить жоден друїд.",al={"курганне лігво зорепаду","печера біля зорепаду"}},{q="Де розташоване Селище Зорепаду?",a="Селище стоїть біля головної засніженої дороги через Вінтерспрінг, на північний захід від гоблінського поселення Евірлук і на південь від Каменя Морозних Шаблезубів.",al={"розташування зорепаду","як дістатися до зорепаду","де зорепад"}}},fp="16,277,30.476.0,25.269.0,56.168.0,43.185.0,34.157.0"}
P.entries["subzone:steamwheedle-port"] = {n="Порт Стімвідла",s="Порт Стімвідла — гамірна прибережна застава на східному березі Танарісу, напряму пов'язана з Ґаджетзаном. Ним керує нейтральний картель Стімвідл, і порт править за важливий морський зв'язок із далекими островами на кшталт Кезану, водночас постійно відбиваючись від Піратів Південних морів, що підступають дедалі ближче.",h="Порт Стімвідла — гамірна прибережна застава на східному березі Танарісу, напряму пов'язана з Ґаджетзаном.",kw={"порт стімвідла","картель стімвідл","кезан","пірати південних морів","ґаджетзан","танаріс"},ang={["class:Rogue"]="Постійні тертя між гоблінськими купцями й сусідніми Піратами Південних морів відкривають прибуткові можливості для кишенькових злодіїв, розвідників і тих, хто береться повертати вкрадене за винагороду.",["profession:Engineering"]="Порт — неоціненний склад деталей і припасів, завезених прямо з Кезану, тож це природний осередок пліток і креслень для майстрів-механіків."},sec={{t="Брама на мінливих пісках",b="Порт Стімвідла, що тулиться до дюн на березі Південних Морів, дає пустельному місту Ґаджетзан у глибині суходолу прямий вихід до морської торгівлі. Поселенням керує картель Стімвідл, і тут вирує життя: портові робітники, торговці й капітани, що зважуються ходити підступними водами. Кораблі постачання регулярно курсують між портом і далекими гоблінськими твердинями, зокрема Кезаном, привозячи на південь Калімдору цінні механічні деталі, предмети розкоші й сировину."},{t="Пірати й дивні вчені",b="Життя в порту аж ніяк не мирне. Трохи південніше вздовж узбережжя лежить Бухта Загублених такелажників — лігво зухвалих Флібустьєрів Південних морів, які регулярно грабують гоблінські судна, крадуть вантажі й оспорюють владу над узбережжям. Окрім портових вантажників, що торгуються за кожну монету, і знервованих купців, які намагаються повернути вкрадені вантажі, порт дає прихисток і незвичним мандрівникам — як-от загадковому тролеві на ім'я Єх'кінья, що подалі від сторонніх очей вивчає прадавніх і зловісних духів світу."}},faq={{q="Хто тримає Порт Стімвідла?",a="Поселення збудував і ним керує картель Стімвідл — головне торговельне об'єднання нейтральних гоблінів. Доки ви в добрих стосунках із Ґаджетзаном і Картелем, тут радо приймають мандрівників і Альянсу, і Орди.",al={"хто володіє портом стімвідла","фракція порту стімвідла","чи дружній порт стімвідла"}},{q="Куди ходять кораблі з цього порту?",a="Порт — морський зв'язок Картелю через Південні Моря: звідси ходять кораблі, зокрема, до острова Кезан та інших торгових осередків краю, проте пасажирських рейсів для шукачів пригод він не має.",al={"куди пливуть кораблі зі стімвідла","поромна переправа стімвідла"}},{q="Чому поблизу так багато піратів?",a="Флібустьєри Південних морів облаштували свою базу трохи на південь, у Бухті Загублених такелажників. Вони часто захоплюють вантажі, що прибувають, грабують припаси на причалах і полюють на тих, хто відстав, уздовж берега, — це головна місцева загроза гоблінській торгівлі.",al={"пірати бухти загублених такелажників","пірати південних морів танаріс"}},{q="Хто такий Єх'кінья?",a="Єх'кінья — дивакуватий троль-учений, що зупинився в порту. Він наймає відчайдушних шукачів пригод, щоб ті вирушили в далекі краї й зловили духовні сутності — як-от верескунів із Фераласу, — для досліджень забутих первісних обрядів.",al={"призначення єх'кіньї","троль у порту стімвідла"}}},fp="17,282,31.468.0,28.464.0,31.238.0,41.226.0,37.237.0,17.212.0"}
P.entries["subzone:steelgrill-s-depot"] = {n="Склад Стілґрила",s="Склад Стілґрила — гамірна інженерна майстерня й ремонтна станція просто на схід від Хараноса в Дун Мороґу. Під наглядом Белдіна Стілґрілла та його бригади майстрів вона служить передовим осередком обслуговування машин, постачання для тінкерів і збору брухту.",h="Склад Стілґрила — гамірна інженерна майстерня й ремонтна станція просто на схід від Хараноса в Дун Мороґу.",kw={"склад стілґрила","інженерія","майстерня","белдін стілґрілл","харанос","дун мороґ"},ang={["profession:Engineering"]="Склад — лабораторія просто неба, оточена паровими машинами й припасами для майстрування, тож для інженерів-початківців, що мандрують Дун Мороґом, це природне місце перепочинку.",["race:Gnome"]="Тісно співпрацюючи з дворфськими господарями, гномські тінкери-вигнанці часто користуються вогнями кузні складу та запасними деталями, щоб їхні врятовані механізми не зупинялися."},sec={{t="Оплот пари та сталі",b="Склад Стілґрила трохи осторонь засніженої дороги на схід від Хараноса гуде брязкотом металу, шипінням парових клапанів і гулом дослідних двигунів. Дворфські шахтарі та дивакуваті гноми-інженери збираються тут серед важкої техніки, крокуючих механізмів і купи сирої руди, вивезеної з сусідніх кар'єрів. Поки Дун Мороґ потерпає від невпинних безчинств трогів і нестачі деталей, Белдін Стілґрілл зі своєю бригадою підтримує машини Альянсу в робочому стані, тож для мандрівників, яким на лютому морозі потрібні запчастини чи технічна порада, склад — незамінна зупинка."}},faq={{q="Що таке Склад Стілґрила?",a="Склад Стілґрила — інженерна майстерня й застава в Дун Мороґу, трохи далі дорогою на схід від Хараноса. Тут обслуговують рудокопів, майстрів і польових техніків, що доглядають важкі машини.",al={"склад стілґрила","що це за місце","стілґрили"}},{q="Хто керує складом?",a="Складом керує родина Стілґрилів, зокрема Белдін Стілґрілл, разом з іншими дворфійськими й гномськими майстрами, що доглядають довколишні машини й наглядають за видобутком.",al={"хто керує стілґрилом","лідер складу стілґрила","белбі стілґрил"}},{q="Які послуги тут є?",a="На складі є крамарі, ремонт і наставники для ремісників, які хочуть удосконалити свою інженерну майстерність і вміння збирати ресурси в польових умовах.",al={"наставники стілґрила","що тут можна робити","послуги складу стілґрила"}}},fp="18,272,28.601.0,27.200.0,19.189.0,33.150.0"}
P.entries["subzone:stendel-s-pond"] = {n="Ставок Стендела",s="Ставок Стендела — невелика водойма, можливо, отруєна, на південний захід від Сентінел Гілла у Вестфолі. Довкола нишпорять гноли, поряд видніються могили, але попри зловісні небезпеки це одне з небагатьох місць у висохлому краї, де можна порибалити в прісній воді.",h="Ставок Стендела — невелика водойма, можливо, отруєна, на південний захід від Сентінел Гілла у Вестфолі.",kw={"ставок стендела","вестфол","сентінел гілл","шавлієва риба","рибальство","гноли"},ang={["faction:Alliance"]="Ставок лежить неподалік Сентінел Гілла, але через табори гнолів лишається неприборканою загрозою на південних рубежах Народного ополчення.",["profession:Cooking"]="Шавлієву рибу з цих каламутних вод цінують кухарі — для своїх рибних страв."},sec={{t="Небезпечний водопій",b="Ставок Стендела, захований на південний захід від Сентінел Гілла, дарує тиху перерву серед курних рівнин Вестфолу, хоча небезпека завжди поруч. Мулкими берегами бродять гноли, а розкидані кістяки й дві самотні могили натякають, що чи то вода, чи то звірі довкола смертельні для необачних подорожніх. Та рибалки все одно ризикують сюди ходити заради косяків шавлієвої риби."}},faq={{q="Де розташований Ставок Стендела?",a="Він лежить на південний захід від Сентінел Гілл у центрі Вестфолу, трохи збоку від курних стежок, що ведуть на південь.",al={"розташування ставка стендела","де ставок стендела","знайти ставок стендела"}},{q="Хто чатує довкола ставка?",a="Мулистими берегами ставка нишпорять гноли Річколапів, що ревно бережуть свої угіддя й нападають на кожного, хто наближається до води.",al={"хто тут живе","монстри ставка стендела","гноли ставка стендела"}},{q="Чому біля берега кістяки й могили?",a="Кістяки й дві безіменні могили свідчать про смертельні небезпеки цього місця. Чи мандрівники стали жертвами гнолів, чи отруїлися смердючою водою зі ставка, лишається зловісною таємницею.",al={"чиї це могили","чому скелети","могила біля ставка"}}},fp="14,267,25.355.0,32.117.0,36.116.0,48.177.0"}
P.entries["subzone:stillwater-pond"] = {n="Ставок Тихої Води",s="Ставок Тихої Води — тиха застояна водойма одразу на захід від Брілла в Галявинах Тірісфалю. Колись улюблене місце пікніків і купання живих дітей Лордерона, він перетворився на каламутну калюжу, де водяться кістяні риби й нишпорять небезпечні падложери.",h="Ставок Тихої Води — тиха застояна водойма одразу на захід від Брілла в Галявинах Тірісфалю.",kw={"ставок тихої води","ставок","брілл","пікніки","кістяні риби","бейн","темні гончаки","тірісфаль"},ang={["class:Hunter"]="Уражена чумою живність довкола ставка, зокрема здичавілі темні гончаки на кшталт Бейна, робить цю місцину небезпечними мисливськими угіддями для розвідників, що патрулюють околиці Брілла.",["race:Undead"]="Для Відступників, що зберегли спогади про життя в Лордероні, Ставок Тихої Води — похмуре нагадування про втрачені дитячі дні пікніків і купання на його колись прозорих берегах."},sec={{t="Зруйнований перепочинок",b="До Третьої війни й спустошень Чуми Нежиті Ставок Тихої Води був тихим прихистком для люду Галявин Тірісфалю. Родини з сусідніх сіл збиралися на його трав'янистих берегах на пообідні пікніки, а діти, замалі для підступних глибин Озера Світлої Води, вчилися плавати на його мілинах. Сьогодні ідилічні води стали мертвими й сірими. Живі давно зникли, лишивши тільки кістяних риб, що шмигають під поверхнею, і блукаючу нежить, що тиняється довколишніми лісами."},{t="Нишпорки в імлі",b="Хоч тут спокійніше, ніж на обложених дорогах і спірних фермах Тірісфалю, Ставок Тихої Води має власні небезпеки. Каламутні води напувають лише уражених чумою звірів галявин — насамперед лютого темного гончака на ім'я Бейн, що нишпорить берегом. Мандрівникам, які зрізають шлях західними луками дорогою до Брілла, слід ступати обережно: хижі звірі й безцільні зомбі часто тиняються край води."}},faq={{q="Яким був Ставок Тихої Води до чуми?",a="За часів людського Лордерона Ставок Тихої Води був мальовничим і улюбленим місцем для пікніків. Він мілкий і спокійніший за просторе Озеро Світлої Води, тож родини часто приводили сюди малечу безпечно поплавати.",al={"історія ставка тихої води","для чого був ставок тихої води","місце для плавання тіріфалю"}},{q="Чи живе тепер щось у воді?",a="Звичайні водяні мешканці не пережили отруєння Тірісфалю. Під сірою гладдю плавають лише оживлені кістяки риб, що лишилися після скверни Погибелі.",al={"риба ставка тихої води","що живе в ставку тихої води","істоти ставка тихої води"}},{q="Які небезпечні створіння блукають біля ставка?",a="Окрім безмозкої нежиті, що блукає галявинами, найгорезвісніша загроза на березі — Бейн, надзвичайно сильний і лютий темний гончак, що полює на необачних мандрівників.",al={"монстри ставка тихої води","хто такий бейн","темна гончак біля брилля"}},{q="Де розташований Ставок Тихої Води?",a="Ставок Тихої Води лежить у центрі Галявин Тірісфалю, просто на захід від містечка Брілл і на південний захід від більшого Озера Світлої Води.",al={"де ставок тихої води","розташування ставка тихої води","як знайти ставок тихої води"}}},fp="15,272,16.533.0,20.437.0,48.231.0,42.196.0,46.178.0,33.129.0"}
P.entries["subzone:stonard"] = {n="Стонард",s="Стонард — укріплена застава Орди серед південних драговин Болота Скорботи. Його збудували ще під час Першої війни, а для сучасної Орди він став важливим опорним пунктом на півдні Східних Королівств і спостережним постом, звідки стежать за Спустошеними Землями.",h="Стонард — укріплена застава Орди серед південних драговин Болота Скорботи.",kw={"стонард","орда","перша війна","темний портал","болото скорботи","шамани"},ang={["class:Shaman"]="Стонард славиться як головний осередок на півдні Східних Королівств, де шамани Орди можуть знайти настанови й навчання далеко від Калімдору.",["faction:Horde"]="Стонард — єдиний укріплений опорний пункт Орди між Пустищами на півночі й Долиною Стренглторну на заході."},sec={{t="Пам'ятка Першої війни",b="Стонард — одне з найдавніших орківських поселень в Азероті. Його заснували, коли Стара Орда ринула крізь Темний Портал у край, що колись звався Чорною Трясовиною, і разом із сестринською заставою Рокард Стонард тримав лінії загарбників. Після Другої війни поселення покинули, і воно зазнало руйнувань, але Нова Орда Тралла відбудувала Стонард і поставила там гарнізон. Тепер, із традиційним орківським Великим Залом і укріпленими землянками, ця застава — важливий острівець влади Орди серед дикої й небезпечної трясовини."},{t="Прикордонна застава",b="Сучасний Стонард — водночас табір дослідників і плацдарм. Картографи й розвідники розходяться довколишніми драговинами, щоб нанести на мапу ще не досліджене болото й стежити за ворожими місцевими звірами, заблукалими дренеями та затонулим Храмом Атал'Гаккара на сході. І головне: Стонард дає Орді організований плацдарм просто на північ від розтрощених Спустошених Земель, тож Орда не спускає ока з приспаного Темного Порталу."}},faq={{q="Чому Стонард важливий для Орди?",a="Стонард дає Орді укріплений військовий і господарський осередок глибоко на півдні Східних Королівств. Звідси розвідники досліджують небезпечне Болото Скорботи, звідси вирушають напади на сусідній Затонулий Храм, і тут стоїть постійний гарнізон неподалік від Спустошених Земель.",al={"чому стонард тут","призначення стонарда","що таке стонард"}},{q="Скільки років Стонарду?",a="Він сягає часів Першої війни — це одне з найперших оркських поселень на Азероті. Засноване Старою Ордою невдовзі після того, як вона пройшла крізь Темний Портал, після Другої війни воно занепало, доки Нова Орда Тралла не відбудувала його.",al={"історія стонарда","коли збудували стонард","хто заснував стонард"}},{q="Що сталося з його поселенням-побратимом, Рокардом?",a="Рокард заснували разом зі Стонардом під час Першої війни. Але якщо Стонард Орда відновила, то Рокард захопили огри-Дредмоли й перетворили на ворожу твердиню, відому як Твердиня Жахокулака в Спустошених Землях.",al={"що таке рокард","історія рокарда","сестринське місто стонарда"}},{q="Чи можна полетіти чи дістатися просто до Стонарда?",a="Так. Зі Стонарда є польоти через увесь континент — до Карґата, Полум'яного Гребеня, Базового Базового Табору Ґром'ґол і нейтрального порту Буті Бей.",al={"політ до стонарда","як дістатися до стонарда","портали стонарда"}}},fp="7,270,24.519.0,16.452.0,38.289.0,19.260.0,48.235.0,42.150.0"}
P.entries["subzone:stone-cairn-lake"] = {n="Озеро Кам'яного Кургану",s="Озеро Кам'яного Кургану — кільцеподібна водойма на північному сході Лісу Елвінн. У його центрі лежить острів, увінчаний Дозором Героїв — меморіалом полеглим у Першій війні. Колись тихе місце для роздумів, нині озеро тривожать ворожі мурлоки на берегах і чародії-відступники, що зайняли острів.",h="Озеро Кам'яного Кургану — кільцеподібна водойма на північному сході Лісу Елвінн.",kw={"озеро кам'яного кургану","озеро","дозор героїв","мурлоки","чародії-відступники","мідь","ліс елвінн"},ang={["profession:Mining"]="Кручі й пагорби довкола Озера Кам'яного Кургану мають одне з найгустіших скупчень покладів міді в усьому Лісі Елвінн, тож це вигідна зупинка для майбутніх ковалів та інженерів.",["race:Human"]="Центральний острів — глибоко особистий меморіал для королівства Стормвінд, що вшановує загиблих, коли королівство впало під час Першої війни."},sec={{t="Пам'ятник в облозі",b="Озеро Кам'яного Кургану завдячує назвою помітному кам'яному меморіалу, зведеному на великому острові в його центрі. Цей пам'ятник, відомий як Дозор Героїв, поставили на честь тяжких людських втрат у Першій війні проти Орди орків. Колись родини та прочани безпечно діставалися острова, щоб ушанувати полеглих, дивлячись через спокійні води на урочисту кам'яну кладку. Та нині небезпечні чародії-відступники розбили табір просто біля меморіалу, перетворивши місце священної пам'яті на ворожий редут."},{t="Береги озера",b="Довкола кільцеподібного озера тягнеться мальовничий берег, що стає дедалі небезпечнішим для місцевих і мандрівників. Плем'я войовничих мурлоків захопило південні береги, поставило вздовж води грубі хатини й дошкуляє кожному, хто наблизиться. Окрім небезпек, пагорби й виступи довкола озера багаті на мінеральні жили, тож околиця — часта мета шукачів і шахтарів, готових знехтувати тутешніми загрозами."}},faq={{q="Чому воно зветься Озером Кам'яного Кургану?",a="Озеро названо за Дозором Героїв — пам'ятником-курганом, зведеним на острові посередині на честь вояків і мирних мешканців Альянсу, що загинули в Першій війні.",al={"походження назви озера кам'яного кургану","чому кам'яний курган","звідки назва"}},{q="Хто зараз займає острів посеред озера?",a="Острів заполонили чарівники-відступники й ренегати, що прогнали звичайних прочан і влаштували довкола меморіалу укріплений табір.",al={"хто на острові","чарівники на острові","розбійники-маги на озері"}},{q="Чому біля води зібралися мурлоки?",a="Місцеве плем'я мурлоків оселилося на південних мілинах і берегах річки: вони збудували примітивні хижі й забрали собі багаті на рибу води.",al={"мурлоки кам'яного кургану","мурлоки озера","хатини південного берега"}},{q="Як зветься меморіал на острові?",a="Пам'ятник відомий як Дозор Героїв: це кам'яний курган, який часто звуть Каменем Пам'яті.",al={"назва меморіалу на острові","назва пам'ятника","святиня кам'яного кургану"}}},fp="16,325,19.553.0,18.454.0,34.181.0,46.140.0,42.160.0,42.110.0"}
P.entries["subzone:stonebull-lake"] = {n="Озеро Кам'яного Бика",s="Озеро Кам'яного Бика — тихе водоймище у формі підкови, що огортає Село Бладгуф у центральному Малгорі. Живлене чистими водами, що стікають із рівнин, воно дає прісну воду, вдосталь риби й мирні береги молодим тауренам, які дорослішають під проводом Кайрна Бладгуфа.",h="Озеро Кам'яного Бика — тихе водоймище у формі підкови, що огортає Село Бладгуф у центральному Малгорі.",kw={"озеро кам'яного бика","село бладгуф","малгор","риба","міст","тандер блаф"},ang={["race:Tauren"]="Для тауренів, що облаштовують домівки по всьому Малгору, Озеро Кам'яного Бика — лагідна пожива й нагадування про щедрість Земної Матері біля їхньої столиці."},sec={{t="Води рівнини",b="Огинаючи Село Бладгуф із трьох боків, Озеро Кам'яного Бика визначає географію центрального Малгору. Дерев'яний міст перетинає найвужче місце озера, несучи головну ґрунтову дорогу між поселенням і великим плато Тандер Блафа на півночі. Спокійні води повняться місцевою рибою, тож береги облюбували мисливці на спочинку, втомлені мандрівники й рибалки-учні, що опановують ремесло під безкраїм відкритим небом."}},faq={{q="Де розташоване Озеро Кам'яного Бика?",a="Озеро Кам'яного Бика лежить у центрі Малгору. Воно підковою огинає Село Бладгуф, оточуючи поселення з трьох боків.",al={"розташування озера кам'яного бика","де озеро кам'яного бика","озеро мулґору"}},{q="Для чого міст через озеро?",a="Міст перетинає найвужчу частину Озера Кам'яного Бика й несе головну дорогу, що сполучає Село Бладгуф просто з Тандер Блафом на півночі.",al={"міст озера кам'яного бика","міст біля крівавого копита","дорога над озером кам'яного бика"}},{q="Чому Озеро Кам'яного Бика важливе для тауренів?",a="Озеро — важливе джерело прісної води й рибальське угіддя для мешканців Села Бладгуф. А ще це тихе місце для роздумів і зібрань юних тауренських сміливців, що навчаються в центрі Малгору.",al={"чому озеро кам'яного бика важливе","призначення озера кам'яного бика"}}},fp="14,298,19.448.0,32.132.0,44.147.0,46.222.0"}
P.entries["subzone:stonefield-farm"] = {n="Ферма Стоунфілдів",s="Ферма Стоунфілдів — діюча садиба на півдні Лісу Елвінн. Тут живе родина Стоунфілдів, що давно загрузла в запеклій ворожнечі із сусідами Маклюрами.",h="Ферма Стоунфілдів — діюча садиба на півдні Лісу Елвінн.",kw={"ферма стоунфілдів","ферма","ворожнеча","маклюри","томмі джо стоунфілд","ґолдшир","ліс елвінн"},ang={["race:Human"]="Для людей, що починають шлях із Нортширу, чвари між Стоунфілдами й Маклюрами — легковажний погляд на сільське життя королівства поза загрозою розбійників і гнолів."},sec={{t="Гірка садиба",b="Ферма Стоунфілдів серед хвилястої зелені на південь від Ґолдшира вирощує збіжжя для королівства, водночас плекаючи люту, десятиліттями давню образу на сусідні Виноградники Маклюрів. Злопам'ятство між господарствами породжує дрібні сварки, взаємні звинувачення в крадіжках і постійну напругу. Та за ворожими перепалками юний Томмі Джо Стоунфілд таємно покохав Мейбелл Маклур, і це тихе кохання може або перекинути міст між родинами, або розпалити ще більший гнів."}},faq={{q="Що за ворожнеча між Стоунфілдами й Маклурами?",a="Родини Стоунфілдів і Маклурів давно й уперто ворогують на півдні Лісу Елвінн. Вони постійно звинувачують одна одну в самочинному вторгненні, дрібних крадіжках і всіляких лихих учинках і не хочуть співпрацювати навіть у простих сусідських справах.",al={"ворожнеча стоунфілдів і маклурів","чому стоунфілди б'ються","суперники стоунфілдів"}},{q="Хто живе на Фермі Стоунфілдів?",a="Господарює на фермі рід Стоунфілдів — зокрема Бабуся Стоунфілд, Ма Стоунфілд і юний Томмі Джо Стоунфілд.",al={"нпс стоунфілдів","хто на фермі стоунфілдів"}},{q="Яка таємниця в Томмі Джо Стоунфілда?",a="Попри запеклу ворожнечу двох родин, Томмі Джо Стоунфілд потай закоханий у Мейбелл Маклур. Закохані покладаються на співчутливих мандрівників, що передають їхні листи й подарунки, поки родини нічого не помічають.",al={"таємниця томмі джо","романс томмі джо","кохання стоунфілдів"}}},fp="15,190,18.517.0,58.248.0,29.124.0,38.239.0"}
P.entries["subzone:stonefire-tavern"] = {n="Таверна «Кам'яний Вогонь»",s="Таверна «Кам'яний Вогонь» — головний заїзд для мандрівників у гірському місті Айронфорджі. Вона стоїть у гамірних Торгових Рядах, одразу на північ від міської брами, і дає шукачам пригод з усього Каз Модану тепле вогнище, міцний дворфійський ель і місце для відпочинку.",h="Таверна «Кам'яний Вогонь» — головний заїзд для мандрівників у гірському місті Айронфорджі.",kw={"таверна","кам'яний вогонь","айронфордж","торгові ряди","корчма","ель"},ang={["faction:Alliance"]="Як найближча велика корчма до головної брами Айронфорджа, «Кам'яний Вогонь» часто стає головним місцем збору для мандрівників Альянсу в дворфійській столиці.",["race:Dwarf"]="Для дворфів, що повертаються з походів Каз Моданом, Таверна «Кам'яний Вогонь» — перше місце в столиці, де можна вхопити холодний кухоль елю Файрбрю й послухати місцеві плітки."},sec={{t="Серце Торгових Рядів",b="Таверна «Кам'яний Вогонь» стоїть одразу на північ від брами фортеці, у Торгових Рядах, і вважається найкращим шинком Айронфорджа. Її тримає Шинкар Файрбрю разом зі своєю донькою Ґвенною: утомлені подорожні знаходять тут ситні страви, місцеве пиво й нічліг під горою. Хто ховається від лютих гірських снігів Дун Мороґу, хто обмінюється байками й припасами, перш ніж вирушити вглиб міста, — мандрівники з усіх куточків Альянсу раз у раз збираються біля її ревучого вогнища."}},faq={{q="Де розташована Таверна «Кам'яний Вогонь»?",a="Таверна стоїть у кварталі Майдан в Айронфорджі, за кілька кроків на північ від головної міської брами.",al={"розташування таверни кам'яний вогонь","корчма айронфорджа","де кам'яний вогонь"}},{q="Хто тримає Таверну «Кам'яний Вогонь»?",a="Таверною керує Шинкар Файрбрю з допомогою своєї доньки, Ґвенни Файрбрю.",al={"хто керує кам'яним вогнем","корчмар кам'яного вогню","корчма вогняного пива"}},{q="Чи можуть мандрівники прив'язати тут камінь повернення?",a="Так. Шинкар Файрбрю радо приймає мандрівників Альянсу, які хочуть зробити Таверну «Кам'яний Вогонь» своєю домівкою в Айронфорджі.",al={"прив'язати камінь у айронфорджі","домашня корчма айронфорджа","камінь повернення кам'яний вогонь"}},{q="Які зручності поблизу?",a="Просто біля входу до таверни стоїть міська поштова скринька, а довколишній Майдан повний банків, крамарів і торгових припасів.",al={"послуги кам'яного вогню","поштова скринька біля кам'яного вогню"}}},fp="16,284,20.513.0,38.120.0,34.97.0,43.122.0,26.136.0"}
P.entries["subzone:stonemaul-ruins"] = {n="Руїни Кам'яного Молота",s="Руїни Кам'яного Молота — розтрощені рештки Села Кам'яного Молота, колись гордого калімдорського поселення огрів Кам'яного Молота. Після того як чорні дракони вигнали клан, той утік на північ, а колишній дім заполонили вогнегриві драконороди.",h="Руїни Кам'яного Молота — розтрощені рештки Села Кам'яного Молота, колись гордого калімдорського поселення...",kw={"руїни кам'яного молота","кам'яний молот","огри","багно пилоброду","мок'морокк","рекссар","чорні дракони"},ang={["faction:Horde"]="Огри Кам'яного Молота — вірні союзники, що проливали кров пліч-о-пліч з Ордою Тралла проти Кул Тірасу. Допомагаючи їм дати відсіч чорним драконам, ви шануєте цей союз."},sec={{t="Злет і занепад родового дому",b="Перебравшись до Калімдору, огри Кам'яного Молота заснували поселення серед каламутних боліт Багна Пилоброду. Село прославилося, коли повелитель звірів Рекссар пройшов смертельні випробування клану, убив його жорстокого вождя Кор'ґалла й підняв огрів на захист молодої Орди від сил адмірала Праудмура. Після війни Рекссар лишив на чолі огра Мок'Морокка. Під себелюбним правлінням Мок'Морокка село занепало, а зрештою чорні дракони напали на нього зненацька й розтрощили. Уцілілі огри втекли на північ і заснували Село Папоротяної Стіни, а виводок Оніксії цілком заволодів руїнами."},{t="Боротьба за повернення",b="Нині руїни міцно затиснуті в межах Драконячої Мряки й кишать вогнегривими драконородами, що доглядають гніздовища виводку поблизу. Поки Володар Мок'Морокк став боягузом і вдовольняється бездіяльністю в Папоротяній Стіні, старші й гордовитіші члени клану, як-от Тарґ і Драз'Зілб, не хочуть зрікатися рідної землі. Діючи з Папоротяної Стіни, вони закликають чемпіонів Орди вирізати драконородів-загарбників і трощити драконячі яйця — у надії, що одного дня Кам'яний Молот повернеться й відвоює село предків."}},faq={{q="Хто раніше жив у Руїнах Кам'яного Молота?",a="Поселення, яке тоді звалося Селом Кам'яного Молота, збудував і населяв клан огрів Кам'яного Молота, щойно прибувши до Калімдору.",al={"хто тут жив","історія руїн кам'яного молота","хто збудував село кам'яного молота"}},{q="Чому село покинули?",a="Чорний драконячий рід Оніксії напав на поселення й прогнав огрів, перетворивши село на гніздовище драконородів-Вогнегривів.",al={"чому село зруйноване","що сталося з селом кам'яного молота","хто напав на кам'яний молот"}},{q="Куди поділися вцілілі огри?",a="Уцілілі відступили на північ, у Багно Пилоброду, під проводом Володаря Мок'Морокка й заснували Село Папоротяної Стіни як тимчасову твердиню.",al={"де огри тепер","розташування огрів кам'яного молота"}},{q="Як із цим місцем пов'язаний Рекссар?",a="Рекссар прийшов сюди, щоб залучити огрів до боротьби з Кул Тірасом. Він пройшов їхнє випробування, убив у двобої їхнього тирана-воєначальника Кор'ґалла й недовго був вождем, а тоді передав владу Мок'Морокку.",al={"рекскар кам'яний молот","рекскар вождь огрів"}},{q="Чи збираються огри відвоювати руїни?",a="Так. Мок'Морокк боявся діяти, але інші ватажки Кам'яного Молота, як-от Тарґ і Драз'Зілб, охоче наймають шукачів пригод з Орди, щоб ті прорідили драконородів-Вогнегривів і підготували повернення в рідний дім.",al={"чи повернуться огри","відвоювання кам'яного молота"}}},fp="15,257,30.654.0,28.522.0,36.124.0,30.146.0,33.144.0,43.201.0,38.196.0"}
P.entries["subzone:stonesplinter-valley"] = {n="Долина Кам'яного Уламка",s="Долина Кам'яного Уламка — сувора гірська долина на південному заході Лох Модану, яку заполонили ворожі троги. Колись незаймана альпійська улоговина, тепер вона перетворилася на укріплений табір під грубою орудою трогівського ватажка Ґраумуґа.",h="Долина Кам'яного Уламка — сувора гірська долина на південному заході Лох Модану, яку заполонили ворожі троги.",kw={"долина кам'яного уламка","троги","ґраумуґ","лох модан","телсамар","горяни"},ang={["faction:Alliance"]="Очищення Долини Кам'яного Уламка вберігає важливі шляхи постачання через Лох Модан, які стали вразливими, відколи сили Айронфорджа розпорошені по всьому королівству.",["race:Dwarf"]="Навала трогів тут — образа для безпеки Лох Модану, і горяни Телсамара покладаються на міцних родичів-дворфів, щоб вичистити громил Ґраумуґа, що підступають."},sec={{t="Гамірна твердиня трогів",b="Долина Кам'яного Уламка, що сховалася серед скелястих схилів південно-західного Лох Модану, колись була тихою альпійською улоговиною. Тому спокою настав кінець, коли хвилі підземних трогів видерлися на поверхню по всьому Каз Модану. Захопивши долину, плем'я Кам'яного Уламка швидко перетворило скелясті ущелини на грубі укріплення: риє лігва, ставить барикади й полює на все, що забреде надто близько. Через їхню численність долина стала відкритою раною на дорогах південного Лох Модану, і горяни з Телсамара змушені наймати відчайдушних найманців, щоб ті проріджували лави трогів і знищили їхнього велетенського ватажка Ґраумуґа."}},faq={{q="Де розташована Долина Кам'яного Уламка?",a="Вона врізана в гори в південно-західному куті Лох Модану, трохи на південь від головної дороги, що веде повз Хребет Сивої Лапи.",al={"розташування долини кам'яного уламка","де долина кам'яного уламка","долина троггів лох модан"}},{q="Хто править Долиною Кам'яного Уламка?",a="Табором заправляє грубий ватажок трогів на ім'я Ґраумуґ: із найглибшого кутка долини він спрямовує набіги племені на місцевих мандрівників і патрулі.",al={"хто керує троггами кам'яного уламка","ґраумуг","бос троггів лох модан"}},{q="Звідки в Лох Модані троги?",a="Трогів відкопали глибоко під землею під час дворфійських розкопок в інших куточках Каз Модану. Гнані безглуздою люттю, окремі ватаги вибралися на поверхню, і плем'я Кам'яного Уламка обрало цю відлюдну гірську долину своїм головним плацдармом.",al={"чому трогги в лох модані","звідки трогги","походження троггів лох модан"}},{q="Чому дворфам важливо очистити долину?",a="Долина небезпечно близько до дворфійських поселень, копалень і гірських доріг. Якщо лишити укріплене військо трогів Кам'яного Уламка без нагляду, це загрожуватиме мандрівникам на півдні Лох Модану й ще більше виснажить і без того розпорошені патрулі горян.",al={"чому воювати з троггами кам'яного уламка","проблема з троггами телсамара"}}},fp="20,234,23.646.0,38.136.0,31.171.0,38.260.0,50.267.0"}
P.entries["subzone:stonetalon-peak"] = {n="Пік Кам'яного Кігтя",s="Пік Кам'яного Кігтя — прадавнє святилище нічних ельфів у зеленій високогірній долині на північно-західному краю Гір Кам'яного Кігтя. Священне для калдореїв і доглянуте місцевими друїдами, воно є головним оплотом Альянсу серед цих скелястих висот.",h="Пік Кам'яного Кігтя — прадавнє святилище нічних ельфів у зеленій високогірній долині на північно-західному...",kw={"пік кам'яного кігтя","нічні ельфи","святилище","оракул","третя війна","альянс"},ang={["class:Druid"]="Святилище тісно пов'язане з історією Кола Кенарія та священним Лігвом Кігтя, тож для охоронців дикої природи це важливе місце прощі й оборони.",["faction:Alliance"]="Пік Кам'яного Кігтя — ваша єдина укріплена опора в західних горах: тут можна перепочити, полетіти далі й отримати допомогу із завданнями посеред ворожої території."},sec={{t="Священна гірська долина",b="Високо над посушливим пилом нижніх хребтів Пік Кам'яного Кігтя розкривається пишним, оповитим туманом святилищем. Цю долину здавна вважали священною й просякнутою прадавньою магією: тут збереглися руїни, вік яких сягає тисячоліть, — з тих часів, коли в краї стояли храми на честь королеви Азшари, ще до Великого Розколу. Нині вартові калдореїв і друїди знову мирно доглядають це місце: тут затишний притулок із підземною обителлю друїдів і важливою пристанню гіпогрифів Альянсу."},{t="Перехрестя долі",b="Окрім ідилічних лісів і прадавніх руїн, Пік Кам'яного Кігтя має й історичну вагу з часів Третьої війни. Ведені видіннями Медіва, людська експедиція Джайни Праудмур і Орда Тралла підіймалися на ці небезпечні висоти, шукаючи загадкового Оракула, що жив у глибоких печерах гори. Та доленосна зустріч змусила заклятих ворогів відкласти мечі й заклала підвалини хиткого союзу, який вистояв проти Палаючого Легіону біля Гори Гіджал. Сьогодні пік надійно стережуть вартові, хоча вилазки Орди в низинах не дають захисникам розслабитися."}},faq={{q="Чому Пік Кам'яного Кігтя такий зелений порівняно з рештою гір?",a="Пік Кам'яного Кігтя лежить у захищеній високогірній улоговині, просякнутій давньою магією. Дбайливий догляд нічних ельфів і друїдів із сусіднього Лігва Кігтя зберіг тут буйний лісистий прихисток, де рослинність квітне всупереч обвугленим зубчастим скелям унизу.",al={"чому пік кам'яного кігтя зелений","чому там ліс","погода піку кам'яного кігтя"}},{q="Що сталося тут під час Третьої війни?",a="Послухавши пророчих застережень Пророка Медіва, і Джайна Праудмур, і Тралл прийшли на Пік Кам'яного Кігтя, шукаючи Оракула в печерах гори. Їхня зустріч у кам'яних глибинах привела до історичного перемир'я, що об'єднало людей і орків проти Палаючого Легіону.",al={"що сталося на піку кам'яного кігтя","джайна й тралл кам'яний кіготь","оракул кам'яного кігтя"}},{q="Хто зараз тримає Пік Кам'яного Кігтя?",a="Пік — застава Альянсу, яку захищають і доглядають Вартові нічних ельфів і друїди. Це головний безпечний прихисток, осередок завдань і пункт польотів для шукачів пригод з Альянсу в Горах Кам'яного Кігтя.",al={"чи пік кам'яного кігтя альянсу чи орди","хто живе на піку кам'яного кігтя","фракція піку кам'яного кігтя"}},{q="Які давні руїни тут є?",a="Напівзруйновані колони й мармурові споруди, розкидані долиною, — рештки давньої імперії нічних ельфів: колись тут були храмові угіддя, присвячені Королеві Азшарі, ще до її падіння в божевілля й Великого Розколу.",al={"руїни піку кам'яного кігтя","давній храм кам'яного кігтя","храм азшари"}}},fp="15,269,22.491.0,21.593.0,70.293.0,40.291.0,39.233.0,36.239.0"}
P.entries["subzone:stonewatch"] = {n="Кам'яна Варта",s="Кам'яна Варта — укріплена твердиня в центрі Гір Редріджу, збудована, щоб захищати довколишні людські землі від вторгнень із півночі. Колись тут стояли солдати Стормвінда, а тепер фортецю тримають у жорстокому кулаці орки Блекрок, і вона становить безпосередню загрозу для сусіднього Лейкшира.",h="Кам'яна Варта — укріплена твердиня в центрі Гір Редріджу, збудована, щоб захищати довколишні людські землі...",kw={"кам'яна варта","фортеця","орки блекрок","морґант","ґат'ілзоґґ","гори редріджу"},ang={["faction:Alliance"]="Кам'яна Варта — один із найнебезпечніших плацдармів ворожих орків у самому серці земель Альянсу, тож її повернення життєво важливе для безпеки Редріджу.",["race:Human"]="Різанина 12-го Шабельного полку й падіння фортеці — болісні нагадування про вразливість Лейкшира й політичну байдужість Стормвінда."},sec={{t="Захоплений бастіон",b="Кам'яна Варта, що височіє над урвищами біля Водоспаду Кам'яної Варти, складається з міцної вежі та фортеці, зведених, щоб стерегти підступи з боку Палаючих Степів. Спершу її тримали захисники Лейкшира, але укріплення впало, коли чорнокнижник-ренегат Морґант уклав союз із кланом Блекрок. Сповнені темної магії, орки-загарбники розгромили місцевий людський гарнізон — 12-й Шабельний полк — і захопили фортецю. Згодом Морґант обернувся проти союзників і відступив до сусідньої Вежі Ілґалара з армією гнолів Тіньової Шкури, але орки Блекрок і далі міцно тримають фортецю під командою Генерала Ґат'Ілзоґґа та Лейтенанта Таріл'зуна."},{t="Загроза для Лейкшира",b="Поки в Кам'яній Варті стоїть ворожий орочий гарнізон, Лейкшир опинився просто на прицілі неминучого завоювання. Байдужий чи паралізований Дім Вельмож у Стормвінді відрізав місто від вагомої воєнної допомоги, тож Магістрат Соломон і Маршал Марріс змушені наймати найманців і добровольців. Обезголовити фортецю, знищивши і Таріл'зуна, і Ґат'Ілзоґґа, — головна відчайдушна надія міста зняти облогу з краю."}},faq={{q="Хто зараз тримає Кам'яну Варту?",a="Кам'яну Варту зайняв клан орків Блекрок під командуванням Генерала Ґат'Ілзоґґа і його лейтенанта Таріл'зуна. Вони вигнали королівський гарнізон і тепер використовують твердиню як плацдарм для нападів по всьому Редріджу.",al={"хто в кам'яній варті","хто тримає кам'яну варту","вороги кам'яної варти"}},{q="Як люди втратили Кам'яну Варту?",a="Фортеця впала під час злагодженого наступу клану Блекрок, підсиленого темним чаклунством людини-чорнокнижника, відступника Морґанта. Разом вони розбили захисників 12-го Шабельного полку й захопили весь комплекс.",al={"падіння кам'яної варти","як упала кам'яна варта","історія кам'яної варти"}},{q="Чому Стормвінд не пошле військо, щоб її відвоювати?",a="Стормвінд відмовився виділити досить війська для прикордонних земель, полишивши Магістрата Соломона й Маршала Марріса боронити Редрідж самотужки. Лейкшир покладається на заїжджих шукачів пригод і найманців, щоб контратакувати Кам'яну Варту.",al={"чому немає допомоги стормвінда","підкріплення лейкшира"}},{q="Як Кам'яна Варта пов'язана з Вежею Ілґалара?",a="Спершу Морґант допоміг оркам Блекрок захопити Кам'яну Варту, але невдовзі після перемоги зрадив своїх союзників. Він звів поблизу Вежу Ілґалара, щоб зібрати власну свиту зачарованих невільників і гнолів-гнолів Тіньової Шкури, і нападає і на орків, і на людей.",al={"вежа ілґалара","морґант кам'яна варта"}}},fp="10,295,17.689.0,23.484.0,34.240.0,35.228.0,52.247.0,69.264.0"}
P.entries["subzone:stonewatch-falls"] = {n="Водоспад Кам'яної Варти",s="Водоспад Кам'яної Варти — мальовничий водоспад і глибоке гірське плесо на сході Гір Редріджу, яких живлять води, що витікають з Озера Незрушного. Він спадає схилом під грізними висотами Кам'яної Варти, а його відлюдні води захопило вороже плем'я мурлоків.",h="Водоспад Кам'яної Варти — мальовничий водоспад і глибоке гірське плесо на сході Гір Редріджу, яких живлять...",kw={"водоспад кам'яної варти","водоспад","мурлоки","кам'яна варта","гори редріджу"},ang={["faction:Alliance"]="Поселення мурлоків біля Водоспаду Кам'яної Варти — ще одне небезпечне гніздо потвор, що допікає мандрівникам і без того обложеного східного Редріджу."},sec={{t="Небезпечна гірська чаша",b="Витікаючи зі східної річки Озера Незрушного, Водоспад Кам'яної Варти спадає скелястою місцевістю під твердинею орків Блекрок — Кам'яною Вартою. Падаюча вода видовбала глибоке плесо, сховане біля підніжжя гори. Попри природну красу, мандрівники рідко зупиняються помилуватися краєвидом: плесо заполонила зграя лютих мурлоків, що будує грубі очеретяні халупи й нападає на кожного, хто необачно ступить на берег."}},faq={{q="Звідки береться вода Водоспаду Кам'яної Варти?",a="Водоспад живить річка, що витікає зі східного боку Озера Незрушного й спадає вниз у відлюдну гірську улоговину під кручами Кам'яної Варти.",al={"звідки вода водоспаду кам'яної варти","початок водоспаду кам'яної варти","джерело річки кам'яної варти"}},{q="Хто живе біля Водоспаду Кам'яної Варти?",a="Береги водоспаду займає місцеве плем'я мурлоків. Вони живляться рибою з глибокого гірського ставка й ставлять уздовж берегів грубі навіси та прибережні хижі.",al={"що біля водоспаду кам'яної варти","мурлоки водоспаду","моби біля водоспаду"}},{q="Чи пов'язаний Водоспад Кам'яної Варти з Фортецею Кам'яної Варти?",a="Водоспад — біля підніжжя схилу просто під Кам'яною Вартою та її зруйнованою фортецею. Орки Блекрок тримають укріплені висоти нагорі, а мурлоки панують у водяній улоговині внизу.",al={"зв'язок водоспаду з фортецею","чи фортеця біля водоспаду","стосунки кам'яної варти"}}},fp="16,292,25.441.0,53.165.0,44.178.0,49.190.0"}
P.entries["subzone:stonewatch-keep"] = {n="Фортеця Кам'яної Варти",s="Фортеця Кам'яної Варти — укріплена кам'яна твердиня, що нависає над сходом Гір Редріджу; колись її звело й утримувало Королівство Стормвінд. Тепер її захопило військо орків Блекрок, і вона стала передовою базою, звідки їхні воєначальники тероризують Лейкшир.",h="Фортеця Кам'яної Варти — укріплена кам'яна твердиня, що нависає над сходом Гір Редріджу; колись її звело й...",kw={"фортеця кам'яної варти","орки блекрок","ґат'ілзоґґ","таріл'зун","лейкшир","гори редріджу"},ang={["faction:Alliance"]="Фортеця Кам'яної Варти — болюче нагадування про виснажені кордони Стормвінда; очистити її мури конче потрібно, щоб захистити вразливих мешканців Лейкшира.",["race:Human"]="Людські захисники пролили кров, боронячи ці стіни, і визволення фортеці допомагає помститися за полеглих солдатів і бранців, захоплених кланом Блекрок."},sec={{t="Полеглий бастіон",b="Фортеця Кам'яної Варти колись захищала східні кряжі й оберігала поселенців Лейкшира від ворожих вторгнень. Цей мир розлетівся на друзки, коли чорнокнижник-ренегат Морґант уклав союз із кланом Блекрок. Посилені темною магією, орки з лютою жорстокістю штурмували фортецю, розгромили людських захисників і захопили її. Хоча згодом Морґант покинув союзників, звів сусідню Вежу Ілґалара й підкорив місцевих гнолів, загарбники Блекрок таки зміцнили свою владу над Кам'яною Вартою й перетворили колишній бастіон Альянсу на укріплений плацдарм для наступу на долину."},{t="Престол воєначальника",b="Тепер у фортеці стоїть важкий гарнізон воїнів Блекрок, а керують нею грізний орочий воєначальник Ґат'Ілзоґґ і його жорстокий лейтенант Таріл'зун. З кам'яних мурів ці командири спрямовують набіги по всьому Редріджу й захоплюють бранців — як-от Капрала Кішана зі Стормвінда. Військо королівства розпорошене й не може вислати цілий полк, щоб звільнити фортецю, тож Магістрат Соломон і Маршал Марріс змушені наймати вільних поборників, які проберуться в твердиню й покарають верхівку Блекрок, перш ніж Лейкшир остаточно впаде."}},faq={{q="Кому зараз належить Фортеця Кам'яної Варти?",a="Фортецю нині займає клан Блекрок на чолі з місцевим воєначальником Ґат'Ілзоґґом і його лейтенантом Таріл'зуном. Доки її не захопили, це була твердиня Альянсу, що захищала містечко Лейкшир.",al={"хто контролює фортецю кам'яної варти","хто живе у фортеці кам'яної варти","вороги фортеці кам'яної варти"}},{q="Як орки Блекрок захопили фортецю?",a="Клан Блекрок уклав союз із людиною-чорнокнижником, відступником Морґантом. Підсилені його темним чаклунством, орки здійснили лютий напад, що змів людських захисників Кам'яної Варти.",al={"як орки захопили кам'яну варту","падіння фортеці кам'яної варти","чому впала кам'яна варта"}},{q="Чому армія Стормвінда не відвоює Фортецю Кам'яної Варти?",a="Армія Стормвінда здебільшого полишила Редрідж напризволяще через внутрішні чвари й брак війська по всьому королівству. Тож очільникам Лейкшира доводиться покладатися на незалежних шукачів пригод, щоб дати раду загрозі.",al={"чому немає армії стормвінда","де вартові","допомога армії лейкшира"}},{q="Як Морґант пов'язаний із цією фортецею?",a="Морґант допоміг клану Блекрок захопити Фортецю Кам'яної Варти, але невдовзі після перемоги зрадив орків. Він перебрався звідти й звів власне лігво — Вежу Ілґалара, — а виконувати свою волю змусив зачарованих гнолів-гнолів Тіньової Шкури замість орків.",al={"морґант кам'яна варта","чи морґант у фортеці"}}},fp="15,277,16.665.0,18.585.0,35.214.0,44.202.0,54.219.0,47.240.0"}
P.entries["subzone:stonewatch-tower"] = {n="Вежа Кам'яної Варти",s="Вежа Кам'яної Варти — кам'яна сторожова вежа в захопленій твердині Кам'яної Варти на північному сході Редріджу. Колись її доглядали захисники Лейкшира, а тепер клан Блекрок захопив цю заставу, щоб стежити за довколишніми кряжами й убезпечити свій гірський бастіон.",h="Вежа Кам'яної Варти — кам'яна сторожова вежа в захопленій твердині Кам'яної Варти на північному сході...",kw={"вежа кам'яної варти","вежа","орки блекрок","кам'яна варта","гори редріджу"},ang={["faction:Alliance"]="Вежа Кам'яної Варти — похмуре нагадування про те, як далеко клан Блекрок просунувся в землі Стормвінда, поки головне військо королівства відсутнє.",["race:Human"]="Для жителів Лейкшира орочі стяги над вежами Кам'яної Варти — постійна загроза самому їхньому існуванню."},sec={{t="Захоплений дозорний пост",b="Збудована Королівством Стормвінд, щоб стерегти високі гірські перевали над Озером Незрушним, Вежа Кам'яної Варти була передовою розвідувальною посестрою Фортеці Кам'яної Варти. З її висоти вартові легко бачили східні кряжі й попереджали Лейкшир про будь-яку загрозу з Палаючих Степів. Ця мережа раннього попередження розвалилася, коли орки Блекрок Генерала Ґат'Ілзоґґа спустилися з висот, розгромили людських захисників і забрали твердиню для власних воєнних потреб. Нині вежа наїжачилася вартовими Блекрок, і жоден розвідник Альянсу не підійде до фортеці непоміченим."}},faq={{q="Що таке Вежа Кам'яної Варти?",a="Це укріплена людська сторожова вежа в комплексі Кам'яної Варти на північному сході Гір Редріджу. Збудована, щоб захищати край, нині вона в руках загарбників із клану Блекрок.",al={"лор вежі кам'яної варти","що це за вежа","дозорна вежа кам'яної варти"}},{q="Хто зараз тримає Вежу Кам'яної Варти?",a="Вежу займають орки клану Блекрок під командуванням Генерала Ґат'Ілзоґґа, що відбив твердиню в місцевих людей Редріджу.",al={"хто володіє вежею кам'яної варти","хто у вежі","вороги вежі кам'яної варти"}},{q="Чому вежа важлива для орків Блекрок?",a="З її висоти клан Блекрок бачить сили Альянсу, що наближаються, і стереже підступ до своєї головної фортеці — Фортеці Кам'яної Варти.",al={"чому оркам потрібна вежа","стратегічне значення вежі кам'яної варти"}},{q="Чи може Лейкшир повернути вежу?",a="Лейкширу бракує війська, щоб самотужки відвоювати Кам'яну Варту, тож він покладається на мандрівних шукачів пригод, які проріджують гарнізон Блекрок у вежі й фортеці.",al={"чи лейкшир поверне вежу","плани лейкшира щодо вежі"}}},fp="16,281,18.624.0,25.214.0,40.149.0,49.151.0,32.168.0"}
P.entries["subzone:stonewrought-dam"] = {n="Каменетесна Гребля",s="Каменетесна Гребля — колосальне інженерне диво дворфів на північному краю Лох Модану. Вона стримує води Лоху, утворюючи величезне високогірне озеро, і водночас осушує Багнокрай унизу, перетворюючи його на придатні для життя болота.",h="Каменетесна Гребля — колосальне інженерне диво дворфів на північному краю Лох Модану.",kw={"каменетесна гребля","франклорн форджрайт","темне залізо","гіндервір","лох модан","багнокрай"},ang={["profession:Engineering"]="Для будь-якого інженера гребля — взірцевий урок керування водою й несучої механіки каменетесання, що не поступається навіть великим спорудам під Айронфорджем.",["race:Dwarf"]="Гребля — пам'ятник давньому дворфійському каменярству й архітектурній винахідливості, хоча її походження від Темного Заліза лишається болючою й суперечливою темою серед істориків Айронфорджа."},sec={{t="Диво дворфійського ремесла",b="Каменетесна Гребля, що перетинає каньйон на схід від Дун Алґаза, вважається одним із найбільших будівельних тріумфів дворфійської цивілізації. Спроєктована майстром-архітектором Темного Заліза Франклорном Форджрайтом, гребля зведена за його новаторською технікою каменетесання. Затримавши води гірської улоговини, гребля подвоїла площу Лоху й водночас поступово знизила рівень води на півночі, тож болотиста улоговина Багнокраю постала з колись цілком затопленої долини."},{t="Диверсії й оборона",b="Хоч греблю збудовано під проводом архітектора Темного Заліза, нині вона служить Айронфорджу — і стала головною ціллю диверсантів Темного Заліза, що діють із південних гір. Через недавні напади й спроби проникнення Айронфорджу довелося поставити тут гарнізон під орудою Головного Інженера Гіндервіра VII. Вартові й інженери вдень і вночі патрулюють кладку, знаючи, що будь-який прорив катастрофічно спустошить Лох і обрушить нищівну повінь на Багнокрай унизу."}},faq={{q="Хто збудував Каменетесну Греблю?",a="Її спроєктував і керував будівництвом славетний архітектор Темного Заліза Франклорн Форджрайт, що винайшов каменетесну техніку будівництва. Хоча її звів майстер із Темного Заліза, нині вона служить королівству Бронзбірдів.",al={"хто збудував каменетесну греблю","творець греблі","архітектор греблі"}},{q="Що буде, якщо гребля прорветься?",a="Прорив обернувся б катастрофою. Озеро швидко витекло б, лишивши від Лох Модану порожній кратер багнюки, а вода ринула б униз, у Багнокрай, нестримною нищівною повінню.",al={"якщо гребля прорветься","що як гребля впаде","зруйнована гребля"}},{q="Чому на неї нападають дворфи Темного Заліза?",a="Клан Темного Заліза прагне вдарити по життєво важливій інфраструктурі Айронфорджа й розхитати край. Зруйнувавши греблю, вони перерізали б шляхи постачання, затопили б північні болота й завдали б болючого удару по гордості Бронзбірдів.",al={"чому нападають на греблю","напад темного заліза на греблю"}},{q="Хто зараз відповідає за оборону греблі?",a="Повсякденною роботою й укріпленнями греблі керує Головний Інженер Гіндервір VII, що разом із силами Айронфорджа викорінює диверсантів.",al={"хто керує греблею","інженер греблі"}}},fp="16,239,25.518.0,20.490.0,31.218.0,31.209.0,39.225.0,48.162.0"}
P.entries["subzone:stonewrought-pass"] = {n="Каменетесний Прохід",s="Каменетесний Прохід — підземний тунель, прорубаний просто крізь південні гори Лох Модана до спустошених просторів Палючої Ущелини. Цей прохід, майстерно збудований славетним архітектором Франклорном Форджрайтом, сполучає Долину Королів із Долиною Пилового Вогню. Важкі залізні брами замикають обидва його кінці, захищаючи мирні дворфійські землі від вулканічних жахіть на півдні.",h="Каменетесний Прохід — підземний тунель, прорубаний просто крізь південні гори Лох Модана до спустошених...",kw={"каменетесний прохід","тунель","лох модан","палюча ущелина","франклорн форджрайт","брама"},ang={["faction:Alliance"]="Цей замкнений прохід, який стережуть дворфійські горяни, захищає вразливі поселення Лох Модана від вулканічних загроз, що визрівають у Палючій Ущелині.",["race:Dwarf"]="Тунель — свідчення інженерного генія Франклорна Форджрайта, хоча тепер він упирається в похмурі, загарбані землі ваших заблудлих родичів із Темного Заліза."},sec={{t="Брама, висічена в камені",b="Каменетесний Прохід висік у скельній основі легендарний майстер-архітектор Франклорн Форджрайт, якого прославила ще й велетенська Каменетесна Гребля. Прохід — прямий коридор між мальовничим спокоєм Лох Модана й випаленими пустелями Палючої Ущелини. Він починається в Лох Модані неподалік велетенської Долини Королів і прорізає гірський хребет аж до Долини Пилового Вогню. Оскільки Палючою Ущелиною заволоділи дворфи Темного Заліза й вогняні звірі, горяни Айронфорджа тримають прохід надійно замкненим за важкими брамами, щоб небезпека не перекинулася на північ."}},faq={{q="Куди веде Каменетесний Прохід?",a="Прохід прорізає гірський хребет наскрізь, сполучаючи Долину Королів на південному краю Лох Модану з Долиною Пилового Вогню на півночі Палючої Ущелини.",al={"куди веде каменетесний прохід","з'єднання тунелю","пекуча ущелина до лох модану"}},{q="Хто спроєктував цей тунель?",a="Його спроєктував видатний дворфійський архітектор Франклорн Форджрайт — легендарний майстер, уславлений по всьому Каз Модану Каменетесною Греблею та іншими монументальними кам'яними спорудами.",al={"хто збудував каменетесний прохід","архітектор проходу","франклорн фордж райт тунель"}},{q="Чому ворота замкнені?",a="Ворота міцно засунуті з обох боків, щоб вогняні чудовиська й ворожі дворфи Темного Заліза з Палючої Ущелини не вдерлися в заселені землі Лох Модану. Горянин Пебблбітті стереже вхід із боку Лох Модану й пропускає лише з дозволу.",al={"замкнена брама","чому прохід замкнений","як відчинити браму"}}},fp="17,396,25.591.0,38.181.0,25.190.0,25.272.0"}
P.entries["subzone:stormrage-barrow-dens"] = {n="Курганні Лігва Штормової Люті",s="Курганні Лігва Штормової Люті — прадавня підземна святиня, видовбана під священною долиною Місячного Гаю. Названі на честь Малфуріона Стормрейджа, ці тихі земляні покої — місце спочинку, де друїди поринають у довгий цілющий сон, щоб мандрувати Смарагдовим Сном.",h="Курганні Лігва Штормової Люті — прадавня підземна святиня, видовбана під священною долиною Місячного Гаю.",kw={"курганні лігва","штормова лють","малфуріон стормрейдж","місячний гай","смарагдовий сон","тіранда віспервінд","ріг кенарія"},ang={["class:Druid"]="Для друїдів обох рас Курганні Лігва Штормової Люті — священне серце спадщини Кенарія, зразок традиційних підземних святинь, де старші друїди переходять між Азеротом і Смарагдовим Сном.",["race:NightElf"]="Це підземелля має для калдореїв величезну історичну вагу: воно береже пам'ять і про тисячолітню варту їхніх сплячих чоловіків, і про небезпечний спуск Тіранди Віспервінд, щоб пробудити Малфуріона проти Палаючого Легіону."},sec={{t="Покої сплячих",b="Курганні лігва — священні притулки на всіх землях нічних ельфів: це безпечні підземні сховки, де тіла друїдів можуть лежати непорушно, поки ті надовго поринають у Смарагдовий Сон. Курганні Лігва Штормової Люті особливо шановані у священному краю Місячного Гаю. Названі на честь верховного друїда Малфуріона Стормрейджа, ці звивисті земляні зали зберігають і давню шану, і тиху варту. Хоч дехто з друїдів, як-от Клінтар Дрімвокер, досі безпечно спить у їхніх нішах, відсутність самого великого верховного друїда кидає сумну тінь на видовбане коріння й мирні сяйливі ліхтарі."},{t="Відлуння Третьої війни",b="У відчайдушні дні Третьої війни ці лігва опинилися на межі повної загибелі. Жахолорд Тіхондріус і сили Палаючого Легіону прагнули знищити сплячих друїдів, перш ніж ті встигнуть згуртуватися. Верховна жриця Тіранда Віспервінд пробилася крізь демонів-загарбників і ворожих зіпсованих звірів глибоко в ці земляні тунелі, щоб засурмити в Ріг Кенарія, — і пробудила Малфуріона Стормрейджа в останню мить. Після поразки Архімонда біля Гори Гіджал Малфуріон повернувся до Місячного Гаю, щоб єднатися з духами, але його сутність знову відплила в Сон, лишивши побратимів стерегти ці священні земляні глибини."}},faq={{q="Для чого потрібні Курганні Лігва Штормової Люті?",a="Курганні лігва — захищені, тихі підземні прихистки для друїдів нічних ельфів. Поки їхній розум і дух мандрують неосяжними шляхами Смарагдового Сну, їхні смертні тіла місяцями чи роками лежать нерухомі й беззахисні, тож їм потрібне тихе й надійне місце, де вони безпечно спочивають під пильним оком побратимів.",al={"для чого курганні лігва","чому спати в курганних лігвах","призначення курганних лігв штормової люті"}},{q="Чи перебуває зараз у цих лігвах Малфуріон Стормрейдж?",a="Відомо, що Малфуріон Стормрейдж спочивав у курганних лігвах під час Третьої війни, доки Тіранда його не розбудила. Коли війна скінчилася й почалися суперечки про те, чи садити нове Світове Дерево, він поринув у глибоке єднання з природою, і його дух загубився в Смарагдовому Сні, тож тепер про його місце спочинку дбає Коло Кенарія.",al={"де малфуріон","чи малфуріон у курганних лігвах","чи можна знайти малфуріона тут"}},{q="Хто зараз спить у цих лігвах?",a="Серед друїдів, що спочивають у лігвах, — Клінтар Дрімвокер: він лежить у глибокому сні під землею, поки його дух мандрує безтілесними стежками природи.",al={"хто спить тут","клінтар сновидець","сплячі друїди місячної поляни"}},{q="Що сталося з цим місцем під час Третьої війни?",a="Під час Третьої війни жахолорд Тіхондріус і демонічні сили Палаючого Легіону вдерлися до курганних лігв, щоб перебити сплячих друїдів нічних ельфів. Верховна Жриця Тіранда Віспервінд повела загін у глибини, пробилася крізь демонів, засурмила в Ріг Кенарія й розбудила Малфуріона.",al={"третя війна курганні лігва","напад тіхондріуса на місячну поляну","пробудження тайранди"}}},fp="21,283,26.620.0,23.651.0,49.330.0,51.334.0,44.189.0,49.326.0"}
P.entries["subzone:stormwind-city"] = {n="Стормвінд",s="Стормвінд — велична столиця Королівства Стормвінд і військове та політичне серце Альянсу. Відбудований із попелу після знищення в Першій війні, він стоїть як найбільший уцілілий бастіон людської могутності в Азероті після падіння північних королівств.",h="Стормвінд — велична столиця Королівства Стормвінд і військове та політичне серце Альянсу.",kw={"стормвінд","столиця","альянс","королівство стормвінд","собор світла","варіан рінн","болвар фордрагон"},ang={["faction:Alliance"]="Стормвінд — головний військовий, морський і духовний осередок Альянсу на півдні Східних Королівств, що однаково радо приймає дворфів, гномів і посланців нічних ельфів.",["race:Human"]="Для людей усього Азерота білі мури Стормвінда уособлюють витривалість, виживання й незгасну славу людства після цілковитої втрати північних королівств."},sec={{t="Відбудований маяк",b="Заснований понад тисячоліття тому нащадками араті, що рушили на південь, Стормвінд розквітнув як жвава прибережна столиця, оперезана кам'яними валами й живлена швидкими річковими млинами. Ця велич скінчилася в Першій війні, коли Орда орків узяла місто в облогу, пробила його оборону й спалила дощенту, змусивши сера Андуїна Лотара вести вцілілих біженців через Велике Море до Лордерону. Після перемоги Альянсу в Другій війні Гільдія каменярів узялася за грандіозне завдання — відбудувати столицю в сяйливу твердиню з білого каменю, мереживом каналів і стрімкими шпилями, що височіє на північ від Лісу Елвінн і сьогодні."},{t="Серце Альянсу",b="Коли Лордерон розтрощила Погибель, а Даларан тяжко зруйнувала Третя війна, Стормвінд став головним прихистком і твердинею людства. Його широкі проспекти й оборонні мури патрулюють дисципліновані міські вартові Стормвінда, а шпилі Собору Світла ведуть віру й відданість південних королівств. Та під його впорядкованими кварталами й церемоніальними брамами тліє тихе політичне сум'яття: Король Варіан Рінн загадково зник, і на троні лишився його юний син Андуїн під регентством Верховного Лорда Болвара Фордрагона та нашіптування королівської радниці Леді Катрани Престор."}},faq={{q="Чому Стормвінд відбудували після Першої війни?",a="Під час Першої війни оркська Орда сплюндрувала й спалила Стормвінд. Коли Великий Альянс Лордерона переміг орків у Другій війні, біженці-люди повернули собі королівство предків. Королівський двір доручив Гільдії Каменярів звести на старих руїнах нове, ще величніше місто-фортецю.",al={"хто відбудував стормвінд","відбудова стормвінда","чому стормвінд виглядає новим"}},{q="Хто зараз править Стормвіндом?",a="Формально на троні сидить король-хлопчик Андуїн Рінн — після раптового й незбагненного зникнення його батька, короля Варіана Рінна. Андуїн ще юний, тож справжня влада — у руках Верховного Лорда Болвара Фордрагона, що є регентом і командувачем оборони королівства.",al={"хто король стормвінда","хто править стормвіндом","правитель стормвінда"}},{q="Чому головна людська столиця — Стормвінд, а не Лордерон?",a="Під час Третьої війни північне королівство Лордерон знищили зсередини чума нежиття й Погибель. Лордерон зруйновано, інші північні людські держави спустошено, тож Стормвінд — найбагатше, найцілісніше й найлюдніше людське королівство, що вціліло на Азероті.",al={"що сталося з лордероном","чому не столиця лордерона","чи стормвінд останнє місто"}},{q="Які військові сили захищають місто?",a="Мир у кварталах і на мурах підтримує міська варта Стормвінда. Ширшу оборону земель і охорону короля забезпечують лицарі королівства, гарнізон Фортеці Стормвінда й паладини Церкви Світла.",al={"хто охороняє стормвінд","армія стормвінда","міська варта"}}},fp="14,298,16.651.0,21.636.0,46.327.0,35.292.0,61.301.0,38.284.0"}
P.entries["subzone:stormwind-gate"] = {n="Брама Стормвінда",s="Брама Стормвінда — монументальний укріплений вхід, що сполучає Ліс Елвінн зі Стормвіндом. Під невпинною охороною королівських вартових цей поріг — головна межа між спокійними лісами та величною Долиною Героїв.",h="Брама Стормвінда — монументальний укріплений вхід, що сполучає Ліс Елвінн зі Стормвіндом.",kw={"брама стормвінда","брама","вхід","долина героїв","вартові","стормвінд","ліс елвінн"},ang={["faction:Alliance"]="Брама уособлює безпеку й незламність Великого Альянсу: для солдатів у дорозі та молодих шукачів пригод це перший проблиск величі.",["race:Human"]="Для людей Стормвінда повернутися крізь ці кам'яні арки означає повернутися додому, у безпеку, після довгих мандрів Елвінном і далі."},sec={{t="Поріг королівства",b="Брама Стормвінда, що височіє над південною дорогою Лісу Елвінн, служить і оборонним оплотом, і церемоніальним порогом столиці. Міські вартові Стормвінда невпинно стежать за кам'яним порталом, охороняючи підступи з лісу, а регулярні патрулі крокують між зовнішньою аркою та Долиною Героїв. Попри тривалі заворушення по всьому Елвінну, величезна брама з заліза й каменю лишається широко відчиненою, щоб вітати мандрівників, купців і захисників, що повертаються, у серці Альянсу."}},faq={{q="Куди веде Брама Стормвінда?",a="Пройшовши браму з Лісу Елвінн, ви потрапляєте просто в Долину Героїв — величний вхід до Стормвінда, обабіч якого стоять височенні пам'ятники героям Другої війни.",al={"куди веде брама стормвінда","що за брамою","вхід у стормвінд"}},{q="Чому браму лишають відчиненою, якщо в Лісі Елвінн небезпечно?",a="Стормвінд живе відкритою торгівлею й безперервним рухом мандрівників із Ґолдшира та з усього Альянсу. Хоча довколишнім лісам дошкуляють розбійники й Дефіас, місто не замикається від власних мешканців і торгівлі, а ставить на прохід пильну варту.",al={"чому брами відчинені","чи закрита брама стормвінда","чому відчинено"}},{q="Хто охороняє браму?",a="Біля входу стоїть міська варта Стормвінда. Двоє вартових чатують одразу зовні, у Лісі Елвінн, ще двоє стережуть внутрішній прохід, а озброєні піхотинці патрулюють міст через Долину Героїв.",al={"охорона брами стормвінда","хто обороняє браму"}},{q="Чи відбуваються біля брами особливі події?",a="Так. Відкрита місцевість довкола Брами Стормвінда часто приймає великі міські свята й сезонні зібрання Альянсу — це просторе місце для зібрань поза тісними кварталами.",al={"свята біля брами стормвінда","події біля брами"}}},fp="14,246,28.536.0,35.176.0,56.267.0,21.226.0,42.193.0"}
P.entries["subzone:stormwind-keep"] = {n="Фортеця Стормвінда",s="Фортеця Стормвінда височіє над столицею як кам'яна твердиня й осідок влади Королівства Стормвінд. Відбудована після руйнування в Першу війну, нині вона прихищає королівський двір юного короля-хлопчика Андуїна Рінна та його регента, Верховного Лорда Болвара Фордрагона.",h="Фортеця Стормвінда височіє над столицею як кам'яна твердиня й осідок влади Королівства Стормвінд.",kw={"фортеця стормвінда","андуїн рінн","болвар фордрагон","двір","стормвінд","трон"},ang={["faction:Alliance"]="Фортеця — серце східного воєнного командування Альянсу, звідки Болвар Фордрагон і маршали керують обороною від нових загроз в Елвінні, Вестфолі й далі.",["race:Human"]="Відбудована з попелу після спустошень Першої війни, фортеця — свідчення стійкості й гордості людей Стормвінда."},sec={{t="Відроджена цитадель",b="Фортеця Стормвінда, що стоїть на плато над усім містом, — водночас палац і воєнний бастіон. Первісну твердиню спалила дотла Стара Орда, коли наприкінці Першої війни вбили короля Ллейна. Знову зведена на старих підвалинах після того, як Альянс повернув королівство, відбудована фортеця вміщує не лише велику тронну залу й Воєнну Кімнату, а й тихі садові дворики та простору Королівську Бібліотеку."},{t="Розколотий двір",b="За стягами й полірованим каменем фортеці ховається непевний мир. Король Варіан Рінн загадково зник дорогою на дипломатичну зустріч у Тераморі, і правління лягло на десятирічного короля Андуїна Рінна. Фактично ж правлять Верховний Лорд Болвар Фордрагон і шляхетна Леді Катрана Престор. Поки Болвар опікується обороною й воєнними справами, двірську політику паралізують чвари аристократів, тож віддалені землі лишаються вразливими, а корона — глибоко неуважною."}},faq={{q="Хто зараз править у Фортеці Стормвінда?",a="Формально трон посідає король Андуїн Рінн, але йому лише десять років, тож правлять регент Верховний Лорд Болвар Фордрагон і королівська порадниця Леді Катрана Престор.",al={"хто головний","хто править стормвіндом","хто король"}},{q="Що сталося з королем Варіаном Рінном?",a="Король Варіан за загадкових обставин зник, коли плив за море на мирну конференцію в Тераморі. Через його раптове зникнення трон спорожнів, і Болвар із двором мусили коронувати юного Андуїна, щоб зберегти політичну стабільність.",al={"де варіан","варіан зник","що сталося з королем"}},{q="Чи зруйнували фортецю в Першій війні?",a="Так. Після того як Ґарона вбила короля Ллейна Рінна, Стара Орда захопила місто й зрівняла фортецю з землею. Нинішню твердиню відбудували на давніх підмурках після перемоги Альянсу в Другій війні.",al={"чи орки зруйнували фортецю","руйнування замку першою війною"}},{q="Які головні крила фортеці можна відвідати?",a="У комплексі є головна тронна зала, Воєнна Кімната одразу за нею, Палата Прохача для прохачів, відкритий дворик-сад, Королівська Галерея й Королівська Бібліотека.",al={"кімнати фортеці","що всередині фортеці","крила фортеці стормвінда"}}},fp="14,269,19.466.0,15.482.1,38.178.0,35.249.0,40.232.0,48.194.0"}
P.entries["subzone:stormwind-stockade"] = {n="В'язниця Стормвінда",s="Захована під каналами вздовж північного краю Кварталу магів, В'язниця — головний каземат суворого режиму в Стормвінді. Призначена для вбивць, політичних бунтарів і чужоземних ворогів, ця підземна фортеця нещодавно поринула в цілковитий хаос після злагодженого бунту в'язнів.",h="Захована під каналами вздовж північного краю Кварталу магів, В'язниця — головний каземат суворого режиму в...",kw={"в'язниця стормвінда","бунт","базіл тредд","дефіас","дім вельмож","стормвінд"},ang={["class:Rogue"]="Бунт оголює діяльність Братства Дефіас і Базіла Тредда, даючи змогу побачити, наскільки організованим став злочинний світ просто під носом у корони.",["faction:Alliance"]="В'язниця стоїть просто в столиці, тож її приборкання життєво важливе для громадської безпеки; зачистивши її зали, ви побачите, як глибоко Братство Дефіас проникло в Стормвінд."},sec={{t="В'язниця в облозі",b="Зазвичай нею опікується Наглядач Телвотер, і саме сюди королівство кидає найнебезпечніших в'язнів — від головорізів і агентів Дефіас до полонених орків Блекрок і дворфів Темного Заліза. Проте жорстокий бунт, організований хитрим змовником Дефіас Базілом Треддом, цілком витіснив тюремну варту. Тепер в'язні вільно розгулюють нижніми камерами, перетворивши твердиню на фортецю бунту. Телвотер, якому ледве вдалося втримати вхід, покладається на вільних шукачів пригод, які мають зануритися в підземні коридори й придушити заколот, доки той не вихлюпнувся в канали."},{t="Бюрократія й закулісні оборудки",b="У В'язниці сидять не лише звичайні вуличні злочинці: вона давно служить розмінною монетою для продажного Дому Вельмож. Убивцям і цінним в'язням, яких засудили до смерті деінде, — як-от грабіжникові могил Декстренові Ворду із Сутінколісся чи воєначальникові Блекрок Тарґорру Жахливому з Редріджу, — аристократи відклали страту, щоб використовувати їх як політичних пішаків. Навіть сусідній Айронфордж звернув на це увагу й потай наймає найманців, щоб стратити таких небезпечних в'язнів, як Кам Діпф'юрі, коли людська бюрократія гальмує справедливе правосуддя."}},faq={{q="Де вхід до В'язниці Стормвінда?",a="Вхід — у кварталі каналів у Стормвінді, на північному вигині, біля самого мосту до Кварталу магів. Двері з вартою ведуть кам'яними сходами просто вниз, до підземних камер.",al={"вхід у в'язницю","як дістатися до в'язниці","розташування в'язниці"}},{q="Хто почав бунт у в'язниці?",a="Заколот задумав і розпалив Базіл Тредд — високопоставлений ватажок Братства Дефіас, ув'язнений у в'язниці. Під його проводом в'язні здолали вартових, захопили зброю й цілком заволоділи підземними блоками камер.",al={"хто такий базіл тред","хто почав бунт","хто керує в'язницею"}},{q="Звідки у в'язниці Стормвінда орки й дворфи Темного Заліза?",a="Стормвінд хапає найнебезпечніших ворогів у всіх спірних землях. Зокрема, Тарґорра Жахливого схопили в Горах Редріджу, а Кам Діпф'юрі уособлює загрозу Темного Заліза. Замість швидкої страти чимало з них опинилися тут як військовополонені або їх лишили живими указом вельмож заради політичних вигод.",al={"чому орки у в'язниці","в'язні темного заліза"}},{q="Чому Сутінколісся й Редрідж просять убивати тутешніх в'язнів?",a="Віддалені поселення на кшталт Даркширу й Лейкшира засудили до страти злочинців — як-от Декстрена Ворда й Тарґорра Жахливого, — але Дім Вельмож відклав їхні страти. Розлючені бюрократичним втручанням Стормвінда, місцеві очільники потай наймають мечників, щоб обійти королівську тяганину й довести справу до кінця.",al={"завдання сутінколісся про в'язницю","злочин і кара","що посієш"}}},fp="18,322,20.626.0,32.583.1,46.230.0,39.264.0,61.332.0,67.307.0"}
P.entries["subzone:stormwind-stockade-classic"] = {n="В'язниця Стормвінда (класична)",s="В'язниця Стормвінда — укріплена підземна в'язниця під кварталом каналів у Стормвінді. Спершу збудована для дрібних злочинців, жорстоких найманців і політичних бунтарів, нещодавно вона поринула в хаос після жорстокого бунту в'язнів.",h="В'язниця Стормвінда — укріплена підземна в'язниця під кварталом каналів у Стормвінді.",kw={"в'язниця стормвінда","бунт","тарґорр жахливий","декстрен ворд","базіл тредд","стормвінд"},ang={["faction:Alliance"]="Бунт просто під вулицями столиці — гостре приниження для правління Верховного Лорда Болвара Фордрагона: він показує, наскільки вразливий Стормвінд зсередини, поки короля немає.",["race:Human"]="Для людей із віддалених містечок негаразди у В'язниці доводять, що Домові Вельмож куди більше болить юридична тяганина в столиці, ніж захист прикордонних поселень від убивць."},sec={{t="В'язниця повстала",b="Захована біля каналів між Старим Містом і Кварталом магів, В'язниця — головна каральна установа Королівства Стормвінд. Під орудою Наглядача Телвотера підземний комплекс тримає найнебезпечніших лиходіїв королівства: головорізів Братства Дефіас, орка-грабіжника з Блекрок, огра й навіть дворфа-лазутчика з Темного Заліза. Нещодавно злагоджений тюремний бунт, організований хитрим злочинцем Базілом Треддом, здолав гарнізон: уцілілих вартових вигнали, а внутрішні зали цілком опинилися під владою каторжників."},{t="Бюрократія й відплата",b="Лихо у В'язниці оголює глибокі тріщини в управлінні Стормвінда. Кількох сумнозвісних в'язнів, як-от жах Блекрок Тарґорра Жахливого й грабіжника могил Декстрена Ворда, що торгував тілами, давно засудили до смерті, але їх тримали живими завдяки безкінечним відстрочкам страти, які влаштовували впливові вельможі. Розлючені зволіканням аристократів, сусідні поселення на кшталт Лейкшира й Даркшира, а також дворфійський гарнізон у Дун Модрі цілком обійшли королівські канали й найняли сторонніх шукачів пригод, щоб ті вдерлися досередини й серед загального безладу стратили головних ватажків."}},faq={{q="Де розташована В'язниця Стормвінда?",a="Вхід до В'язниці — у Стормвінді, на північному березі каналу, на переході між Старим Містом і кварталами Собору та магів.",al={"вхід у в'язницю","як дістатися до в'язниці","розташування в'язниці"}},{q="Хто зараз керує в'язницею?",a="Офіційний наглядач — Наглядач Телвотер, але під час бунту його вигнали. Фактично в'язницю тепер контролює в'язень, що розпалив заколот, — Базіл Тредд — разом із союзними бунтівниками Дефіас.",al={"хто керує в'язницею","бос в'язниці","базіл тред"}},{q="Чому в Стормвінді за ґратами орки й дворфи Темного Заліза?",a="Стормвінд тримає тут цінних військовополонених і диверсантів. Тарґорр Жахливий — полонений орк Блекрок, нападник із сусідніх гір, а Кам Діпф'юрі — ворожий дворф Темного Заліза, ув'язнений за підривну діяльність проти Альянсу.",al={"чому в в'язниці орки","кам дипфурі","таргорр жахливий"}},{q="Чому засуджених убивць лишили живими, а не стратили?",a="Бюрократія й політичне втручання високопоставлених вельмож Стормвінда раз у раз відкладали страти засуджених на кшталт Декстрена Ворда й Тарґорра, викликаючи обурення у віддалених краях — Редріджі й Сутінколіссі.",al={"чому їх не стратили","вельможі стормвінда","страта декстрена варда"}}},fp="28,265,18.586.0,27.590.1,30.162.0,36.231.0,64.239.0,60.218.0"}
P.entries["subzone:stoutlager-inn"] = {n="Корчма «Міцний Лагер»",s="Корчма «Міцний Лагер» — жваве серце Телсамара й головний прихисток для мандрівників у Лох Модані. Сховавшись під пологими пагорбами біля озера, вона пропонує теплі вогнища, міцний дворфійський ель і гамірне місце зустрічей для шукачів пригод і місцевих мешканців.",h="Корчма «Міцний Лагер» — жваве серце Телсамара й головний прихисток для мандрівників у Лох Модані.",kw={"корчма міцний лагер","телсамар","лох модан","дворфійський ель","корчма","нічліг"},ang={["faction:Alliance"]="Корчма — важливий збірний пункт і безпечний прихисток для шукачів пригод з Альянсу, що прямують на північ до Багнокраю чи патрулюють неспокійні долини довкола озера.",["race:Dwarf"]="Для дворфів із клану Бронзбірдів «Міцний Лагер» — знайоме тепло домівки, славетне щирою гостинністю, свіжим елем і надійним товариством далеко від Айронфорджа."},sec={{t="Гостинне вогнище серед пагорбів",b="Корчма «Міцний Лагер», що стоїть у самому Телсамарі, — осередок громадського життя західного Лох Модану. Рудокопи, горяни й мандрівники, що йдуть між Дун Мороґом і Багнокраєм, зупиняються тут, щоб обмінятися чутками, знайти нічліг і випити ситного дворфійського пива. Поки нетрі за Телсамаром стають дедалі небезпечнішими через трогів і кобольдів, товсті кам'яні стіни й палахкі вогнища «Міцного Лагеру» дають надійний прихисток."}},faq={{q="Які послуги надає Корчма «Міцний Лагер»?",a="Корчма пропонує звичні для таверни зручності: корчмаря, що прив'язує камені повернення, ліжка для втомлених мандрівників і місцевих крамарів із харчами та напоями в дорогу Лох Моданом.",al={"послуги корчми міцний лагер","що в корчмі","корчмар телсамара"}},{q="Де розташована Корчма «Міцний Лагер»?",a="Вона стоїть у самому центрі Телсамара — головного містечка Альянсу на заході Лох Модану, біля головної дороги.",al={"розташування корчми","де міцний лагер","знайти корчму міцний лагер"}},{q="Чому корчма така важлива для Телсамара?",a="Окрім їжі й нічлігу, Корчма «Міцний Лагер» — це міський майдан і осередок новин. Тут місцеві горяни оголошують винагороди, а мандрівники планують вилазки в довколишні пагорби.",al={"чому корчма популярна","лор таверни телсамара"}}},fp="14,255,31.482.0,50.207.0,36.126.0,41.193.0"}
P.entries["subzone:strahnbrad"] = {n="Странбрад",s="Странбрад — зруйноване людське поселення на північно-східних висотах Гір Альтерак, біля кордону із Західними Чумними Землями. Колись знане як місце, де принц Артас Менетіл уперше дав відсіч нападникам-оркам Блекрок, містечко відтоді занепало й стало укріпленою твердинею злочинного Синдикату.",h="Странбрад — зруйноване людське поселення на північно-східних висотах Гір Альтерак, біля кордону із Західними...",kw={"странбрад","артас менетіл","синдикат","гори альтерак","ґол'дір","блекрок"},ang={["class:Paladin"]="Ходячи бруківкою Странбрада, ви згадуєте ранні, ще не заплямовані дні принца Артаса Менетіла й Утера Світлоносця, — гірке нагадування про те, як низько впали герої Лордерона.",["faction:Horde"]="Те, що Синдикат поневолив орка Ґол'діра, робить Странбрад нагальною ціллю для героїв Орди, які прагнуть ударити по людських розбійниках і врятувати свого родича."},sec={{t="Містечко трагедії",b="Странбрад спершу належав королівству Альтерак, а після Другої війни увійшов до Лордерона, і його лихо почалося напередодні Третьої війни. Орки клану Блекрок напали на поселення, щоб захопити людей для жертвоприношень Палаючому Легіону, і принц Артас Менетіл разом із Лицарями Срібної Длані вирушив на захист містечка. Хоч Артас прогнав нападників і вбив їхнього наглядача рабів, містечко зазнало тяжких втрат. Коли невдовзі по тому Лордерон упав під натиском Погибелі, Странбрад кинули напризволяще стихіям."},{t="Лабети Синдикату",b="Сьогодні Странбрад став важливим осередком діяльності Синдикату — угруповання вигнаної альтерацької знаті й злочинців, що замишляють повернути своє занепале королівство. Тут патрулюють люди-розбійники й грабіжники, а покинута ратуша й кузня правлять за схованки й плацдарми. Синдикат тримає в зруйнованому містечку припаси й підневільних робітників, зокрема нещасних бранців на кшталт орка Ґол'діра, якого розвідники Орди з Таррен Мілла намагаються визволити."}},faq={{q="Чим Странбрад важливий в історії?",a="У Странбраді для принца Артаса Менетіла почалася Третя війна. Утер Світлоносець послав його захистити поселення від орків Блекрок, що лютували в окрузі, і саме тут Артас уперше уславився: урятував мешканців і порубав оркських нападників.",al={"чому странбрад важливий","артас странбрад","історія странбрада"}},{q="Хто тепер тримає Странбрад?",a="Странбрад у руках Синдикату. Ці люди-розбійники, вірні занепалим шляхетним родам Альтераку, укріпили зруйновану ратушу й кузню й зробили їх головним плацдармом для своїх задумів у горах.",al={"хто володіє странбрадом","моби странбрада","хто живе в странбраді"}},{q="Якому королівству спершу належав Странбрад?",a="До Першої війни Странбрад входив до королівства Альтерак. Після того як Альтерак зрадив Альянс у Другій війні, містечко перейшло під владу королівства Лордерон.",al={"альтерак чи лордерон странбрад","королівство странбрада"}},{q="Чому Орду цікавить це містечко?",a="Синдикат схопив орка на ім'я Ґол'дір і змусив його до жорсткої рабської праці в руїнах Странбрада. Агенти Орди з Таррен Мілла на чолі з Краском посилають сюди шукачів пригод, щоб прорвати оборону Синдикату й визволити Ґол'діра.",al={"завдання орди странбрад","круск странбрад","ґол'дір странбрад"}}},fp="10,344,17.552.0,20.482.0,41.275.0,28.226.0,50.207.0,40.243.0"}
P.entries["subzone:stratholme"] = {n="Стратгольм",s="Колись Стратгольм був перлиною Іствілду й другим за величиною містом Королівства Лордерон. У Третю війну тут відбулося сумнозвісне Очищення, яке влаштував принц Артас Менетіл, коли містяни з'їли зерно, заражене Чумою нежиття. Нині зруйнований мегаполіс досі палає й слугує головною твердинею Погибелі в північному Лордероні.",h="Колись Стратгольм був перлиною Іствілду й другим за величиною містом Королівства Лордерон.",kw={"стратгольм","очищення стратгольма","артас менетіл","мал'ганіс","орден срібної длані","культ проклятих","погибель"},ang={["class:Paladin"]="Для паладинів Стратгольм — свята земля, що обернулася трагедією: тут народився Орден Срібної Длані, і тут Артас розтрощив те саме братство, вимагаючи вбити невинних містян.",["faction:Alliance"]="Зруйноване місто — моторошний пам'ятник падінню Лордерона. Воно нагадує мандрівникам з Альянсу про страшну ціну, сплачену, коли північні королівства впали від чуми й зради."},sec={{t="Колиска паладинів і торгівлі",b="Задовго до свого занепаду Стратгольм був наріжним каменем північної цивілізації. Він постав століття тому, коли Араті поширювали свої володіння на Іствілд, і виріс у друге за величиною поселення Лордерона, славетне святими храмами й священною водою, здатною протистояти темному чаклунству. Перед Другою війною архієпископ Алонсус Фаол зібрав соратників у міській каплиці й заснував Орден Срібної Длані, висвятивши в лицарі таких легенд, як Утер Світлоносець. Протягом тієї війни Стратгольм був важливим портом, осередком постачання й північним центром переробки нафти для Альянсу Лордерона; він вистояв під натиском Старої Орди й відбудувався після перемоги."},{t="Очищення і вічна руїна",b="Доля Стратгольма вирішилася, коли Культ Проклятих переправив на міські ринки партії зараженого зерна з Андоргала. Тисячі людей, нічого не підозрюючи, з'їли отруєне борошно. Коли принц Артас прибув разом з Утером і Джайною Праудмур, він побачив, що зараза поширилася надто далеко, щоб її вилікувати. Вирішивши, що лише різанина не дасть Мал'Ганісу здобути ціле військо, Артас наказав знищити всіх містян. Цей злочин відштовхнув від нього Утера й Джайну і став початком сходження принца в безумство. Місто віддали вогню, а згодом Погибель перебралася в димні руїни й зробила їх своєю столицею в краї."}},faq={{q="Чому Стратгольм досі горить?",a="Коли під час Третьої війни принц Артас вичищав місто, його вояки підпалювали будинки й вулиці, щоб знищити заражених мешканців і зупинити поширення нежиття. Неприродне, отруєне чумою полум'я тліє відтоді й досі, живлене темною некромантичною силою й шаленою навалою Погибелі.",al={"чому стратгольм горить","вогонь у стратгольмі","дим стратгольма"}},{q="Що таке Очищення Стратгольма?",a="Очищення — це поголовна різанина мешканців Стратгольма, яку вчинив принц Артас Менетіл. Після того як місто з'їло зерно, заражене чумою нежиття, Артас вирішив стратити всіх мешканців — і хворих, і здорових, — перш ніж вони повстануть вояками Погибелі. Це рішення зруйнувало його союзи й зламало його моральний компас.",al={"очищення стратгольма","чистка артаса","чистка стратгольма"}},{q="Яку історичну роль відіграв Стратгольм для Срібної Длані?",a="Стратгольм — колиска Лицарів Срібної Длані. У міській Каплиці Алонсуса архієпископ Алонсус Фаол ще до Другої війни заснував паладинський орден і помазав його перших п'ятьох членів, серед яких були Утер Світлоносець, Туральйон і Сайдан Датроган.",al={"походження срібної длані","каплиця алонсуса","орден срібної руки стратгольм"}},{q="Що сталося тут із Тіріоном Фордрінгом?",a="Через кілька років після Другої війни Верховного Лорда Тіріона Фордрінга судили за зраду в Залі Правосуддя Стратгольма — за те, що він заступився за шляхетного орка-відлюдника Ейтріґґа. Суд Утера й ватажків Альянсу позбавив Тіріона титулу й вигнав його. Згодом він визволив Ейтріґґа під час нападу на місто, який очолив Тралл.",al={"суд над тіріоном фордрінгом","суд тіріона стратгольм","суд ейтріґґа"}}},fp="10,367,28.666.0,28.622.0,32.295.0,35.340.0,59.268.0,38.304.0"}
P.entries["subzone:stratholme-classic"] = {n="Стратгольм (класичний)",s="Стратгольм, колись найгордіша перлина північного Лордерона й колиска Срібної Длані, тепер — палаюча руїна й столиця Погибелі в цьому краї. Місто, поділене між фанатичним Багряним Хрестовим Походом і легіонами нежиті Барона Рівендера, досі охоплене нескінченною жорстокою війною.",h="Стратгольм, колись найгордіша перлина північного Лордерона й колиска Срібної Длані, тепер — палаюча руїна й...",kw={"стратгольм","барон рівендер","кел'тузад","багряний хрестовий похід","площа хрестоносців","погибель","підземелля"},ang={["class:Paladin"]="Осквернення Стратгольма глибоко ранить паладинів: це і священна колиска Срібної Длані, і цвинтар, де Артас розтоптав настанови Утера.",["faction:Alliance"]="Для Альянсу Стратгольм — це катастрофічне падіння Лордерона, що нагадує воякам і вцілілим про страшну ціну Третьої війни."},sec={{t="Проклята столиця",b="До Третьої війни Стратгольм був північною опорою Лордерона й священною колискою Лицарів Срібної Длані. Його доля вирішилася, коли принц Артас влаштував у місті чистку, вирізавши власних підданих після того, як заражене зерно занесло чуму в його мури. Тліючий і зруйнований, Стратгольм перейшов до Погибелі. Сьогодні під верховною владою ліча Кел'Тузада й польовим командуванням Барона Рівендера місто слугує головною базою сили нежиті в Чумних Землях."},{t="Розколотий фронт",b="Стратгольм поділений між двома лютими силами, що невпинно проливають кров. На заході фанатичний Багряний Хрестовий Похід укріпив Площу Хрестоносців і Багряний Бастіон під командуванням Великого хрестоносця Сайдана Датрогана. На сході лежать бойні й некрополі Погибелі, яких захищають височенні зикурати й лицар смерті Барон Рівендер. Кожен, хто входить до міста, мусить пробиратися крізь цей нищівний перехресний вогонь серед палаючих кам'яниць і неспокійних духів."}},faq={{q="Чому Стратгольм досі горить?",a="Принц Артас підпалив місто під час свого горезвісного очищення в Третій війні, щоб зупинити поширення чуми нежиття. Пожежі так і не згасли до кінця: їх підтримують темна магія, некромантія й нескінченні вуличні бої між Погибеллю й Багряним Хрестовим Походом.",al={"чому стратгольм горить","хто спалив стратгольм","вогонь стратгольма"}},{q="Хто зараз тримає Стратгольм?",a="Влада поділена. Великий Хрестоносець Датроган командує вцілілим загоном Багряного Хрестового Походу, що укріпився в західному бастіоні, а лицар смерті Барон Рівендер править східними руїнами для Погибелі під владою Кел'Тузада.",al={"хто править стратгольмом","хто головний","лідери стратгольма"}},{q="Яке історичне значення має місто для паладинів?",a="Стратгольм — колиска Ордену Срібної Длані: тут архієпископ Алонсус Фаол уперше висвятив Утера Світлоносця й перших паладинів. Його падіння — найглибша трагедія в історії ордену.",al={"срібна длань стратгольм","історія паладинів стратгольма"}},{q="Як потрапити на бік міста, підвладний Погибелі?",a="Шукачі пригод можуть пробитися туди від самої головної брами, але до східного кварталу Погибелі можна потрапити й просто через Службовий Вхід. Щоб пройти цією задньою брамою, потрібен ключ Магістрата Бартіласа, хоча вправні розбійники, могутні ковальські відмички чи гоблінська вибухівка теж її відчинять.",al={"ключ чорного ходу","службовий вхід стратгольм","як зайти на бік нежиті"}}},fp="20,296,18.522.0,18.475.0,32.278.0,34.232.0,60.223.0,57.327.0"}
P.entries["subzone:stratholme-main-gate"] = {n="Головна Брама Стратгольма",s="Головна Брама Стратгольма — величний палаючий вхід до північного мегаполісу Лордерона на північному заході Східних Чумних Земель. Вона веде прямо зруйнованими проспектами міста до Королівської Площі та укріплень хрестоносців усередині.",h="Головна Брама Стратгольма — величний палаючий вхід до північного мегаполісу Лордерона на північному заході...",kw={"головна брама","стратгольм","королівська площа","торговий ряд","багряний бастіон","артас"},ang={["class:Paladin"]="Стояти перед цією брамою для паладинів — велике горе: саме тут Срібна Длань розкололася, коли Артас розпустив орден у день, коли вирізав Стратгольм.",["race:Human"]="Головна арка колись була величним порогом другого за величиною міста Лордерона, а тепер це некрополь, задушений попелом."},sec={{t="Ворота до полеглої перлини",b="Колись Стратгольм був гордістю північного Лордерона й славився як колиска Ордену Срібної Длані. Нині його величезна арочна головна брама позначає поріг нескінченного жахіття. Саме тут у Третю війну принц Артас повстав проти свого наставника, Утера Світлоносця, і вирізав власних підданих, перш ніж Чума нежиття встигла їх забрати. Відтоді місто палає без упину й стало головною твердинею Погибелі в краї."},{t="Багряний підступ",b="За головною брамою шлях веде просто в руїни Королівської Площі й Торгового Ряду, а далі — до укріпленого кварталу, відомого як Багряний Бастіон. Фанатики Багряного Хрестового Походу пробилися крізь цей вхід, щоб відвоювати місто й вичистити мерців, і облаштували табір серед руїн. Проте хрестоносці опинилися в оточенні нездоланних потвор нежиті й ведуть виснажливу війну, якої не можуть виграти проти темних сил, що керують обороною Стратгольма."}},faq={{q="Куди веде ця брама?",a="Головна Брама — величний парадний вхід до Стратгольма, що відкривається просто на Королівську Площу й Торговий Ряд. Це головний шлях до Багряного Бастіону — кварталу, за який бореться Багряний Хрестовий Похід.",al={"куди веде головна брама стратгольма","що таке головна брама","парадний вхід стратгольма"}},{q="Чому місто за цією брамою досі горить?",a="Під час Третьої війни принц Артас вичистив місто й підпалив його, щоб зупинити поширення чуми нежиття. Темна некромантична магія, нечестиве полум'я й нестримна скверна Погибелі відтоді підтримують невгасиму пожежу в зруйнованому місті.",al={"чому місто горить","хто спалив стратгольм","вогонь стратгольма"}},{q="Чим ця брама відрізняється від Службового Входу?",a="Обидва входи ведуть до того самого величезного зруйнованого міста, але з протилежних кінців. Головна Брама веде до кварталів, де ще є живі й де тримаються багряні, а Службовий Вхід відкривається на східні вулиці, підвладні бойням Погибелі й Баронові Рівендеру.",al={"головна брама проти службового входу","який вхід у стратгольм","двері стратгольма"}},{q="Хто тримає місцевість одразу за Головною Брамою?",a="Перші вулиці за аркою сходжують шкандибаючі зомбі, гулі, кістяки-жахіття й блукаючі тіні, а Багряний Хрестовий Похід тримає обложений бастіон далі вглибині вулиць.",al={"хто всередині головної брами","моби біля парадного входу"}}},fp="20,259,25.472.0,20.494.0,26.214.0,49.258.0,66.289.0,55.203.0"}
P.entries["subzone:stratholme-service-entrance"] = {n="Службовий Вхід Стратгольма",s="Службовий Вхід Стратгольма — укріплений задній вхід біля Брами Східного Муру на півночі Східних Чумних Земель. Він дає прямий і потайний доступ до східного кварталу палаючого міста, який контролює Погибель, оминаючи величні передні ворота.",h="Службовий Вхід Стратгольма — укріплений задній вхід біля Брами Східного Муру на півночі Східних Чумних Земель.",kw={"службовий вхід","стратгольм","брама східного муру","барон рівендер","площа старійшин","погибель"},ang={["class:Paladin"]="Для лицарів Світла цей поріг веде просто в осквернену некромантичну машинерію Погибелі. Це прямий шлях, щоб знищити Рівендера й повернути полеглу честь святого міста.",["class:Rogue"]="Службова брама — класичне тактичне проникнення: вона дозволяє шукачам пригод оминути укріплені лінії фронту й тихо прослизнути в технічні проходи міста."},sec={{t="Проломлений бастіон",b="While the monumental Main Gate of Stratholme opens into King's Square and provides a route toward the Scarlet Bastion, the Service Entrance breaches the city's eastern fortification at Eastwall Gate. Today, it leads directly into the corrupted heart of the metropolis: Elders' Square and the blighted pathways leading toward Baron Rivendare's slaughterhouses."},{t="Лігво Погибелі",b="Venturing through the service portal offers a shorter approach to the Scourge's eastern districts. The surrounding alleys crawl with gargoyles, crypt fiends, and cultists guarding the dread ziggurats. For the Argent Dawn and daring adventurers seeking to strike at the ruling death knight directly, this hidden iron gate serves as the primary staging point for surgical strikes against the Lich King's commanders."}},faq={{q="Де розташований Службовий Вхід Стратгольма?",a="Вхід — біля Брами Східного Муру, під північними горами Східних Чумних земель, трохи на схід від головних руїн Стратгольма. Він сховався в кам'яній арці укріпленого муру.",al={"розташування службового входу","де чорна брама","бічний вхід стратгольма на мапі","як знайти чорний хід стратгольма"}},{q="Чим цей вхід відрізняється від Головної Брами Стратгольма?",a="The Main Gate opens into King's Square and provides a route across the city toward the Scarlet Bastion. The Service Entrance opens near Elders' Square, giving a shorter approach to the undead-held eastern districts and Slaughter Square.",al={"чорний хід проти парадного","різниця службового входу","який вхід у стратгольм"}},{q="Чому він зветься Службовим Входом?",a="Це задній вхід біля Брами Східного Муру, що оминає парадний підступ до міста. Яке міське призначення він мав спершу, не уточнюється.",al={"чому службовий вхід","лор службового входу"}},{q="Хто тримає цю частину міста?",a="Квартал за брамою міцно в руках Погибелі під наглядом Барона Рівендера і його прислужників, що доглядають зикурати — опору їхньої темної магії на Площі Старійшин.",al={"хто контролює чорну браму","боси службового входу","лідер сторони нежиті"}}},fp="27,253,18.359.0,19.413.0,49.202.0,60.236.0,38.124.0,35.182.0"}
P.entries["subzone:stromgarde-keep"] = {n="Фортеця Стромгард",s="Фортеця Стромгард — побита й розділена столиця занепалого людського королівства Стромґард в Аратійському нагір'ї. Колись вона була гордою колискою людської цивілізації під назвою Стром, а тепер фортецю поділили між собою ворожі розбійники Синдикату, огри Каменекулаків, що вдерлися сюди, і жменька відчайдушних королівських захисників на чолі з Принцом Ґаленом Троллбейном.",h="Фортеця Стромгард — побита й розділена столиця занепалого людського королівства Стромґард в Аратійському...",kw={"фортеця стромгард","стромґард","стром","аратор","торадін","троллбейн","синдикат"},ang={["faction:Alliance"]="Стромґард був одним із засновників Альянсу Лордерону в Другу війну. Його обложені захисники — один з останніх вірних оплотів на півночі, і вони відчайдушно борються, щоб не загинути остаточно.",["race:Human"]="Стромґард — прадавнє серце всієї вашої раси: тут перші людські племена об'єдналися під проводом Торадіна й навчилися тайної магії у високих ельфів. Гірко бачити, як його заполонили злочинці й огри."},sec={{t="Колиска людства",b="Задовго до того, як здобути теперішню назву, ця фортеця постала майже три тисячоліття тому як Стром — перша столиця об'єднаної людської імперії Аратор за короля Торадіна. Звідси люди рушили до перемоги над лісовими тролями, і тут народилося людське чарівництво: маги з високих ельфів навчали першу сотню людських чародіїв. З плином століть, коли піднялися й розквітли молодші королівства-сестри — Даларан, Лордерон і Стормвінд, — вплив Строму згас. Уперта династія Троллбейнів, що лишилася тут, перейменувала місто на Стромґард, і всю Другу війну воно лишалося гордим оплотом воїнів, опорою Альянсу Лордерону проти Орківської Орди."},{t="Розбитий оплот",b="Після спустошення Третьої війни Стромґард зрештою не витримав нових лих і зрад. Нині величне кам'яне місто розколоте на три ворожі частини. Аристократи-зрадники з Синдикату засіли у великій внутрішній цитаделі, а брутальні огри Каменекулаків заполонили колишнє святилище магічного кварталу. Притиснуті в останньому кварталі, Принц Ґален Троллбейн і знесилене військо Стромґарда ведуть виснажливу криваву війну на кілька фронтів лише для того, щоб їхня прадідівська домівка не лишилася тільки спогадом."}},faq={{q="Хто зараз тримає Фортецю Стромгард?",a="Зруйноване місто поділене на три запекло оспорювані частини. Підступний Синдикат тримає центральну внутрішню фортецю, огри-Каменекулаки, що вдерлися сюди, зайняли зруйнований квартал магів, а Принц Ґален Троллбейн очолює рештки війська Стромґарда в останньому кварталі.",al={"хто живе в стромґарді","хто володіє фортецею стромґард","хто в стромґарді"}},{q="Що таке Імперія Аратор?",a="Імперія Аратор — найперша об'єднана людська держава, заснована майже три тисячі років тому королем Торадіном. Її столицею був Стром, що стояв саме там, де нині височіє Фортеця Стромгард.",al={"що таке імперія аратор","перше людське королівство","імперія аратор"}},{q="Чому місто в руїнах?",a="Стромґард був могутньою силою аж до кінця Другої війни, але в хаосі після Третьої війни королівство опинилося вразливим і відрізаним від світу. Зрада зсередини, напади злочинного Синдикату, що скористався нагодою, і навала огрів-Каменекулаків розтрощили оборону міста.",al={"чому стромґард зруйнований","що сталося зі стромґардом"}},{q="Хто такий Ґален Троллбейн?",a="Принц Ґален Троллбейн — королівський нащадок і командир уцілілих сил Стромґарда. Зі свого обложеного оплоту у фортеці він керує відчайдушною обороною і від Синдикату, і від огрів.",al={"принц троллбейн","хто такий ґален"}}},fp="15,342,18.693.0,19.547.0,39.293.0,31.208.0,25.300.0,23.208.0"}
P.entries["subzone:sun-rock-retreat"] = {n="Притулок Сонячної Скелі",s="Притулок Сонячної Скелі — прихована святиня Орди високо серед центральних вершин Гір Кам'яного Кігтя, трохи південніше Озера Міркфаллон. Тут верховодять таурени й орки, і це головний плацдарм та пункт постачання Орди в краї. А ще селище стоїть на священній землі, яку таурени здавна шанують за її глибокий духовний відгук.",h="Притулок Сонячної Скелі — прихована святиня Орди високо серед центральних вершин Гір Кам'яного Кігтя, трохи...",kw={"притулок сонячної скелі","орда","таурени","ан'ше","святиня","шамани"},ang={["faction:Horde"]="Як головний плацдарм Орди в Горах Кам'яного Кігтя, Притулок Сонячної Скелі — важливий пункт поповнення припасів і вузол польотів посеред спірних вершин.",["race:Tauren"]="Для шу'гало Притулок Сонячної Скелі — більше, ніж застава: це священна земля, благословенна Ан'ше, де шамани століттями ходили царством духів."},sec={{t="Священна гавань серед вершин",b="Притулок Сонячної Скелі, захований у гірській улоговині на південь від Озера Міркфаллон, здавна мав для тауренів духовне значення. За давнім переказом, Ан'ше — Сонце — поцілувало саме ту вершину, на якій стоїть селище. Ще задовго до приходу Орди тауренські шамани й прочани ходили сюди на обряди, що прочиняють завісу смертного світу, і черпали силу з міцного зв'язку цієї землі з царством духів."},{t="Прикордонна застава",b="Сьогодні Притулок Сонячної Скелі — головна база Орди в Горах Кам'яного Кігтя. Орки й таурени пліч-о-пліч зміцнюють тут опору проти ворожих гарпій, місцевих вартових нічних ельфів і промислового грабунку Венчурної Компанії. Як осередок, що поєднує торгові й повітряні шляхи між Тандер Блафом, Перехрестям і кордонами Ашенвалю, притулок дає прихисток, провізію та духовну настанову тим, хто наважується йти крізь ці скелі."}},faq={{q="Що таке Притулок Сонячної Скелі?",a="Притулок Сонячної Скелі — головна застава Орди в Горах Кам'яного Кігтя. Тут живуть здебільшого таурени й орки, і це мирний прихисток, торговий пункт і командний пост для героїв Орди, що діють у краї.",al={"що таке сонячна скеля","притулок сонячної скелі","хто керує сонячною скелею"}},{q="Чому це місце священне для тауренів?",a="Тауренська легенда каже, що Ан'ше, Сонце, торкнулося гори, де нині стоїть притулок. Ця земля має давній зв'язок зі світом духів, тож здавна сюди приходять на прощу — шукати видінь і спілкуватися з предками.",al={"чому сонячна скеля священна","ансе кам'яний кіготь","лор сонячної скелі тавренів"}},{q="Що загрожує притулку?",a="Притулку доводиться протистояти агресивним гарпіям, що ревно бережуть свої володіння, ворожим нічним ельфам, що стережуть священні ліси, і руйнівному видобутку та вирубці Венчурної Компанії, що нищить природу.",al={"загрози сонячній скелі","хто нападає на сонячну скелю","вороги кам'яного кігтя"}},{q="Куди літають звідси?",a="Притулок Сонячної Скелі має сідало вітрокрилів із прямими польотами до головних місць центрального Калімдору — зокрема до Перехрестя в Пустках і до тауренської столиці Тандер Блаф.",al={"польоти сонячної скелі","політ у притулок сонячної скелі","майстер польотів сонячної скелі"}}},fp="16,391,27.428.0,16.496.0,25.221.0,39.234.0,35.212.0,43.192.0"}
P.entries["subzone:sundown-marsh"] = {n="Призахідне Болото",s="Призахідне Болото — найглибші, найзахідніші закутки Багнокраю, де застояні води сходяться з підступною звіриною. Попри раптори, слизи й гнолів, що там нишпорять, на його багнистому краю тримає самотню садибу дивакувата парочка.",h="Призахідне Болото — найглибші, найзахідніші закутки Багнокраю, де застояні води сходяться з підступною...",kw={"призахідне болото","фрадд свіфтґір","венна сілкбірд","вітряк","кроколіски","багнокрай"},ang={["race:Gnome"]="Те, що Фрадд Свіфтґір і Венна Сілкбірд процвітають зі своїм вітряком посеред небезпечної багнюки, доводить: гномська винахідливість здатна облаштувати затишний дім будь-де."},sec={{t="Дика й каламутна вирва",b="Призахідне Болото заховане на північному заході Багнокраю: глибока вода, густа багнюка й безліч хижаків. Велетенські кроколіски, мінливі слизи, мандрівні раптори й ревні до своєї території гноли-Мохошкірі вільно блукають у тумані. Через небезпечну місцевість більшість мандрівників тримаються лише головної брукованої дороги між Гаванню Менетіл і Айронфорджем, тож цей глибокий закуток лишається здебільшого диким."},{t="Життя на краю трясовини",b="Серед небезпек болота стоїть самотня кам'яна хатина з вітряком, що невтомно крутиться на даху. Там гном Фрадд Свіфтґір і дворфійка Венна Сілкбірд дивом заробляють на життя, нишпорячи болотом. Вони продають дивовижі й рідкісні торгові рецепти, видобуті з трясовини, мандрівникам, яким вистачить сміливості пробратися повз войовничих мешканців болота."}},faq={{q="Де розташоване Призахідне Болото?",a="Призахідне Болото — на північному заході Багнокраю. Це одна з найнижчих і найглибших частин боліт, далеко від головних королівських доріг.",al={"розташування призахідного болота","де призахідне болото","болото багнокраю"}},{q="Хто живе на Призахідному Болоті?",a="Тут у невеликій кам'яній хатці з вітряком живе дивна парочка — гном Фрадд Свіфтґір і дворфійка Венна Сілкбірд. Вони нишпорять болотом у пошуках дивовиж і продають рідкісний крам заїжджим мандрівникам.",al={"хто живе тут","нпс призахідного болота","хатина свіфтгір"}},{q="Які небезпеки чатують на Призахідному Болоті?",a="На болоті кишать небезпечні звірі й чудовиська — велетенські кроколіски, мерзенні слизи, болотяні звірі, раптори й ворожі гноли-Мохошкірі, тож охоти до безтурботних прогулянок тут не буде.",al={"монстри призахідного болота","небезпеки призахідного болота","вороги призахідного болота"}},{q="Навіщо шукачеві пригод іти на Призахідне Болото?",a="Окрім полювання на місцевих звірів, мандрівники приходять до хатки з вітряком, щоб поторгувати з Фраддом Свіфтґіром і Венною Сілкбірд, які пропонують рідкісні рецепти й дивні знахідки з довколишніх боліт.",al={"навіщо йти на призахідне болото","причини йти на призахідне болото","торговці призахідного болота"}}},fp="13,240,25.423.0,28.341.0,31.193.0,27.205.0,43.181.0,50.216.0"}
P.entries["subzone:sunnyglade"] = {n="Сонячна Галявина",s="Сонячна Галявина колись була багатим і заможним людським поселенням королівства Стормвінд за часів Першої війни. Спустошене й зрештою покинуте, коли лінія фронту розвалилася, зруйноване поселення нині занепадає під темним впливом культу Молота Присмерку.",h="Сонячна Галявина колись була багатим і заможним людським поселенням королівства Стормвінд за часів Першої...",kw={"сонячна галявина","стормвінд","перша війна","молот присмерку","вежа мага","стара орда"},ang={["class:Mage"]="Самотня вежа чарівника в Сонячній Галявині — моторошне нагадування про ранню людську магію: Стара Орда пощадила її лише для того, щоб розібрати по кісточках тайнознавчі знання людей.",["race:Human"]="Зарослі камені Сонячної Галявини — сумний пам'ятник віддаленим поселенням, які довелося покинути, коли Стормвінд мусив відступити під час Першої війни."},sec={{t="Падіння золотого містечка",b="До того як Перша війна розшматувала південь Азерота, Сонячна Галявина славилася багатством і затишним достатком. Цей спокій брутально обірвався, коли вдерлася Стара Орда. Загони орків-грабіжників напали на містечко й поневолили вцілілих мешканців, лишивши неушкодженою тільки самотню вежу чарівника, щоб вивчати тайнознавче мистецтво людських чаклунів. Сили Стормвінда спробували визволити полонених селян і відбудувати поселення, але Орда, що наступала, крок за кроком поглинала навколишні Річкові Галявини. Вирішивши, що віддалену провінцію втрачено, командувачі Стормвінда врешті відвели сили на захист рідних земель — і Сонячна Галявина лишилася на поталу руйнації."},{t="Отруєний прихисток",b="Нині Сонячна Галявина лежить далеко за безпечними межами відродженого королівства Стормвінд. Знаменита кам'яна вежа мага напрочуд уціліла і в Першій війні, і в подальші роки занедбання, але мирного містечка довкола неї вже немає. Натомість відлюдні руїни захопили фанатики культу Молота Присмерку, які обертають колись квітучу долину на знаряддя власних зловісних задумів."}},faq={{q="Що сталося із Сонячною Галявиною?",a="Під час Першої війни Стара Орда напала на Сонячну Галявину й сплюндрувала її. Людям удалося визволити полонених селян і спробувати відбудуватися, але зрештою Стормвінд покинув край Річкових Галявин, щоб зосередитися на обороні своїх головних земель.",al={"що таке сонячна галявина","історія сонячної галявини","чому сонячна галявина зруйнована"}},{q="Хто тепер тримає Сонячну Галявину?",a="Руїни Сонячної Галявини нині займає культ Молота Присмерку, що отаборився серед зруйнованих хат і давньої вежі чарівника.",al={"хто живе в сонячній галявині","вороги сонячної галявини","сутінки сонячної галявини"}},{q="Чому орки під час Першої війни лишили вежу магів цілою?",a="Коли Стара Орда плюндрувала Сонячну Галявину, вона навмисно залишила чарівну вежу містечка, щоб її чорнокнижники й командири могли вивчати людську магію й розгадати її таємниці.",al={"орківська вежа магів сонячна галявина","лор вежі сонячної галявини"}},{q="Чому Стормвінд не повернув містечко після війни?",a="Коли Перша війна розгорілася, проводирі Стормвінда визнали Річкові Галявини втраченими й спрямували всі військові сили на оборону серця королівства, покинувши Сонячну Галявину.",al={"чому покинуто","стормвінд сонячна галявина"}}},fp="10,277,21.665.0,17.396.0,28.256.0,28.151.0,68.168.0,52.193.0"}
P.entries["subzone:swamplight-manor"] = {n="Маєток Болотних Вогників",s="Маєток Болотних Вогників — іронічно названа напіврозвалена дерев'яна халупа глибоко на Відьминому Пагорбі в Багні Пилоброду. Це дивакуватий дім і кухня Джарла «Болотне Око» — відлюдника, відомого на все болото своїми дивними кулінарними смаками. Попри скромну й моторошну відлюдність, сад довкола приховує таємницю, що привертає увагу і Терамору, і Села Папоротяної Стіни.",h="Маєток Болотних Вогників — іронічно названа напіврозвалена дерев'яна халупа глибоко на Відьминому Пагорбі в...",kw={"маєток болотних вогників","відьмин пагорб","багно пилоброду","джарл","болотне око","кулінарія","шпигун"},ang={["faction:Alliance"]="Розвідники Терамору, яких послав Капітан Ґарран Ваймс, пильно стежать за чутками довкола маєтку — особливо щодо зниклих розвідників і перехопленого листування Орди.",["profession:Cooking"]="Для кулінарів, що наважуються забрести в болота, Джарл — ексцентрична вершина болотяного збиральництва: він готує місцеві страви з істот, до яких більшість кухарів боїться навіть торкнутися."},sec={{t="Притулок відлюдника в трясовині",b="Попри пишну назву, Маєток Болотних Вогників — аж ніяк не панська садиба. Це лише перекошена, побита негодою халупа, захована серед заклятих боліт Відьминого Пагорба. Її єдиний мешканець, дивак-відлюдник Джарл «Болотне Око», живе самотою серед туману, багнюки й неспокійних болотяних привидів. Джарл проводить дні, вигадуючи незвичні місцеві делікатеси з тутешньої живності, і часто наймає мандрівних шукачів пригод, щоб ті добували для його дивного ремесла химерні інгредієнти — жаб'ячі лапки з болота чи очі тварюк."},{t="Таємниці саду",b="Мандрівники зазвичай натрапляють на маєток, шукаючи дивної кухні чи сховку від духів Відьминого Пагорба, проте ця земля приховує значно темніший прикордонний конфлікт. Під купою пухкої землі в Джарловому саду закопано викинутий звіт орківського шпигуна, а поряд — відрубана голова. І варта Терамору під командою Капітана Ґаррана Ваймса, і сили Орди в Селі Папоротяної Стіни дуже хочуть заполучити ці документи, тож зарослий клаптик землі відлюдника несподівано став гарячою точкою в місцевій холодній війні."}},faq={{q="Чому крихітна халупа зветься «Маєтком»?",a="Назва суто іронічна. Будівля — не більше ніж сира, обшарпана дерев'яна халупа, яку з дивацькою вигадкою так назвав її відлюдний мешканець Ярл «Болотне Око», щоб протиставити її похмурій тузі Відьминого Пагорба.",al={"походження назви маєтку болотних вогників","чому маєток","чи справжній маєток"}},{q="Хто живе в Маєтку Болотних Вогників?",a="Тут самотою живе Ярл «Болотне Око» — горезвісний напівбожевільний відлюдник і кухар, що обрав життя на відшибі серед проклятого болота. Він наймає заїжджих мандрівників, щоб ті приносили йому дивні кулінарні складники й допомагали з місцевими духами.",al={"хто такий ярл болотне око","мешканець маєтку болотних вогників","хто тут живе"}},{q="Що закопано в городі біля хати?",a="У купі розкопаної землі на подвір'ї Ярла заховано загублене донесення шпигуна, написане орком, а поряд — відрубану голову. І влада Альянсу в Тераморі, і розвідники Орди із Села Папоротяної Стіни прагнуть заволодіти цими відомостями.",al={"земляна купа маєтку","розпушена земля болотних вогників","звіт орківського шпигуна"}},{q="Чи можуть до Ярла приходити гравці і Альянсу, і Орди?",a="Так. Ярл живе так далеко від цивілізації, що тримається нейтралітету: охоче приймає допомогу й міняється рецептами і з мандрівниками Альянсу, і з мандрівниками Орди.",al={"чи ярл нейтральний","чи орда може говорити з ярлом","фракція болотних вогників"}}},fp="16,407,30.551.0,21.545.1,37.222.0,30.238.0,37.238.1,47.159.0"}
P.entries["subzone:swarming-pillar"] = {n="Роїстий Стовп",s="Роїстий Стовп — височенне скельне громаддя в серці Силітусу, яке силітиди цілком заполонили й переробили на свій лад. Він стоїть трохи на південь від Цитаделі Кенаріуса, а назву дістав від невпинних хмар крилатих комах, що дзижчать довкола його вершин і підземних входів.",h="Роїстий Стовп — височенне скельне громаддя в серці Силітусу, яке силітиди цілком заполонили й переробили на...",kw={"роїстий стовп","силітиди","вулик","силітус","цитадель кенаріуса","комахи"},ang={["class:Druid"]="Вулик біля Роїстого Стовпа, що стоїть так близько до Цитаделі Кенаріуса, — пряма зневага до природного ладу й постійна загроза для варти Кола Кенарія."},sec={{t="Шпиль із хітину й піску",b="Роїстий Стовп, що різко здіймається з мінливих дюн центрального Силітусу, — похмурий пам'ятник нестримному поширенню силітидів. Колись це було звичайне скельне громаддя, а тепер його поточили нори й укрили смолисті виділення рою. Трохи на південь від Цитаделі Кенаріуса він безупинно виплоджує виводки крилатих робітників і солдатів; їхні темні хмари заповнюють сухе пустельне повітря й застерігають мандрівників триматися подалі."},{t="Серце вулика",b="Хоч який величезний і грізний Роїстий Стовп на поверхні, це лише зовнішній виступ розлогої підземної мережі. Під його кам'яною оболонкою лежать глибокі тунелі й печерні виводкові камери, на яких тримається один із найбільших вуликів краю. Коло Кенарія з великою тривогою стежить за шпилем: його виводки прямо загрожують справам друїдів і натякають на моторошну злагодженість, що стоїть за навалою комах."}},faq={{q="Що таке Роїстий Стовп?",a="Роїстий Стовп — величезна скеля в центрі Силітусу, яку захопили силітиди й обернули на діючий вулик. Його легко впізнати за нескінченним роєм летючих комах, що кружляють довкола вершини.",al={"роїстий стовп","що це за стовп","шпиль силітидів силітус"}},{q="Де розташований Роїстий Стовп?",a="Він посеред пустелі, недалеко просто на південь від Цитаделі Кенаріуса.",al={"де роїстий стовп","розташування роїстого стовпа"}},{q="Чому довкола нього літає стільки комах?",a="У скелі розташований один із головних вуликів Силітусу — величезний розплідник і перевалочний пункт для крилатих силітидів, що патрулюють довколишні пустельні піски.",al={"чому довкола комахи","літаючі комахи стовпа силітусу","літаючі силітиди"}},{q="Чи пов'язаний Роїстий Стовп із вуликами під піском?",a="Так. Видимий шпиль — лише верхівка величезної підземної колонії, видовбаної глибоко в скельній основі й пісках під Силітусом.",al={"тунелі вуликів","підземний стовп силітидів"}}},fp="15,288,26.462.0,17.444.0,28.213.0,37.99.0,44.172.0,63.146.0"}
P.entries["subzone:tabetha-s-farm"] = {n="Ферма Табети",s="Глибоко в найкаламутніших закутках Трясовини лежить Ферма Табети — відлюдне обійстя з невеликою дерев'яною хатиною, скромним городом і власною пристанню. Попри підступне болото довкола, цей прихисток слугує потаємною схованкою для чарівниці-відлюдниці Табети.",h="Глибоко в найкаламутніших закутках Трясовини лежить Ферма Табети — відлюдне обійстя з невеликою дерев'яною...",kw={"ферма табети","табета","трясовина","багно пилоброду","маги","чорнокнижники","сфера орагіла"},ang={["class:Mage"]="Ваші наставники в столицях високо цінують езотеричні знання Табети й посилають до її ферми вправних заклинателів, щоб дослідити нестабільні сплески мани й давні реліквії сили.",["class:Warlock"]="Хоч Табета й живе як тиха болотяна відлюдниця, вона — одна з небагатьох заклинательок, здатних допомогти вам очистити потужні енергії, пов'язані зі Сферою Орагіла."},sec={{t="Прихисток відлюдниці",b="Захована в західних болотах Багна Пилоброду, Ферма Табети кидає виклик немилосердному довкіллю. Обійстя з побитої негодою хатини, невеликих грядок і пристані для плавання каламутними протоками болота дає тихий притулок, далекий від політичного суперництва Терамору й Села Папоротяної Стіни. Тут відлюдна чарівниця-людина Табета живе майже в повній самоті й займається езотеричними дослідженнями таємної магії та Скверни без втручання Даларану чи місцевої влади."},{t="Осередок таємної сили",b="Попри віддаленість, ферма приваблює знавців магічних мистецтв з усього Калімдору та Східних Королівств. Магів, що прагнуть опанувати потужні сплески таємної енергії, і чорнокнижників, яким потрібна допомога в очищенні нестабільних артефактів на кшталт Сфери Орагіла, посилають саме на Табетин поріг."}},faq={{q="Хто живе на Фермі Табети?",a="На фермі живе дивакувата чарівниця Табета: вона доглядає невеликий город, причал і садибу серед небезпечних болотяних створінь Трясовини.",al={"хто така табета","хто живе тут","мешканці ферми табети"}},{q="Навіщо маги ходять аж до цієї ферми?",a="Наставники магів по всьому світу посилають до Табети здібних учнів, щоб ті поглибили свої чарівні знання. Вона глибоко знається на непостійних сплесках мани, давніх реліквіях і первісних силах, про які в міських академіях рідко навчають.",al={"навіщо маги ходять до табети","завдання магів пилотрясина","завдання класу мага табета"}},{q="Навіщо сюди приходять чорнокнижники?",a="Чорнокнижники шукають знань Табети про вигнання духів і стихійні енергії, коли треба очистити й приборкати небезпечні артефакти, — найперше під час обрядів очищення Сфери Орагіла.",al={"завдання чорнокнижників табета","очисна куля орахіла","чорнокнижник табета"}},{q="Чи в союзі Ферма Табети з Ордою чи з Альянсом?",a="Табета тримається нейтрально й ділиться мудрістю з мандрівниками незалежно від їхньої вірності. Її ферма не залежить ні від Терамора Джайни Праудмур, ні від сил Орди в Селі Папоротяної Стіни.",al={"чи табета альянсу","чи табета орди","чи табета нейтральна"}}},fp="14,275,20.507.0,26.286.0,28.148.0,45.240.0,29.196.0,56.221.0"}
P.entries["subzone:tahonda-ruins"] = {n="Руїни Тагонди",s="Руїни Тагонди — вибілені сонцем рештки давнього поселення тауренів, поглинутого сіллю й піском Мерехтливих Низин. Про мешканців, що колись тут жили, пам'ятають мало, а серед гнилих жердин наметів і пошматованої шкіри тепер нишпорять небезпечні солекамінні василіски.",h="Руїни Тагонди — вибілені сонцем рештки давнього поселення тауренів, поглинутого сіллю й піском Мерехтливих...",kw={"руїни тагонди","таурени","василіски","мерехтливі низини","танаріс","руїни"},ang={["race:Tauren"]="Натрапити на забуте тауренське поселення, що тоне в солі Тисячі Голок, — зворушливе нагадування про небезпеки, з якими стикалися ваші предки-кочівники, мандруючи Калімдором."},sec={{t="Під шаром солі",b="Руїни Тагонди, що лежать на півдні Мерехтливих Низин біля проходу до Танарісу, — сумний пам'ятник покинутому тауренському минулому. Селище загинуло давно, і його вивітрені споруди поступово поглинула мінлива біла сольова кірка. Дехто підозрює, що мешканців прогнали місцеві солекамінні василіски, але на вцілілих спорудах лишилися дивні сліди. Два чіткі набори з трьох паралельних розривів прорізають шкіру зруйнованої оселі — схоже, селище спіткав жорстокий кінець від пазурів могутніх хижаків чи ворожих загарбників, перш ніж пустеля забрала решту."}},faq={{q="Чим спершу були Руїни Тагонди?",a="Колись Тагонда була тауренським селом на сухих просторах Мерехтливих Низин. З часом село занепало, і його поступово поглинули мінливі піски й соляна кірка.",al={"що таке руїни тагонди","хто збудував тагонду","історія руїн тагонди"}},{q="Чому село покинули?",a="Жодні записи не зберегли, що саме спіткало село. Нині руїни заполонили люті василіски Солекаменю, які, можливо, й прогнали поселенців. Проте глибокі трипалі розриви на вцілілих шкіряних житлах свідчать про раптовий жорстокий напад.",al={"чому тагонда зруйнована","що знищило тагонду","що сталося з тагондою"}},{q="Хто тепер живе в руїнах?",a="Рештки села цілком заполонили ворожі василіски Солекаменю, що гріються на сонці серед гниючих дерев'яних жердин і пошарпаних шкіряних наметів.",al={"моби тагонди","що в руїнах тагонди","звірі тагонди"}}},fp="13,290,23.605.0,39.186.0,30.272.0,37.163.0"}
P.entries["subzone:tainted-scar"] = {n="Осквернений Шрам",s="Осквернений Шрам — каньйон на південному заході Спустошених Земель, що кишить демонами й просяк мерзенною магією Скверни від сусіднього Темного Порталу. Нині це головна твердиня решток Палаючого Легіону в Азероті, якою командує вартовий загибелі Лорд Каззак.",h="Осквернений Шрам — каньйон на південному заході Спустошених Земель, що кишить демонами й просяк мерзенною...",kw={"осквернений шрам","спустошені землі","палаючий легіон","каззак","демони","даіо","інфернали"},ang={["class:Warlock"]="Осквернений Шрам дуже цікавить досвідчених чорнокнижників: вони розшукують Даіо Старезного біля його демонічного вівтаря, щоб навчитися підкоряти вогняних інферналів і командувати ними.",["faction:Alliance"]="Командувачі Альянсу пильно стежать за каньйоном, бо бояться, що окопане демонічне військо Лорда Каззака може ринути на північ — до Болота Скорботи чи земель Стормвінда."},sec={{t="Оплот Легіону",b="Колись тут були буйні болота прадавньої Чорної Трясовини, та хаотична енергія Скверни, що сочиться з Темного Порталу, цілком висмоктала з цієї спустошеної улоговини життя й пофарбувала її в колір запеченої крові. Після поразки Архімонда на Горі Гіджал під час Третьої війни вцілілі сили Палаючого Легіону зібралися на півдні. Велетенський еред'рун Лорд Каззак зробив Осквернений Шрам своєю твердинею: він розставив добірних демонів на його почорнілих узвишшях і послав грізних поплічників на кшталт Разеліха Осквернителя панувати над спустошеними червоними землями."},{t="Нечестиві мешканці",b="Хоча більшість смертних уникає Шраму під страхом болісної смерті, знавцям темних мистецтв його насичена Сквернею енергія видається непереборно привабливою. Ексцентричний чорнокнижник-людина на ім'я Даіо Старезний оселився біля зруйнованого демонічного вівтаря з видом на всі ці жахи: він використовує демонів, що аж кишать довкола, для темних ритуалів і вчить молодих чорнокнижників викликати й підкоряти грізних інферналів."}},faq={{q="Що таке Осквернений Шрам?",a="Це каньйон на південному заході Спустошених Земель, глибоко зіпсований демонічною магією, що йде від Темного Порталу. Колись він був частиною Чорної Трясовини, а тепер зачах і обернувся на безплідну криваво-червону пустку, де живуть майже самі високопоставлені демони Палаючого Легіону.",al={"що таке осквернений шрам","лор оскверненого шраму","чому земля червона"}},{q="Хто править Оскверненим Шрамом?",a="Демонами, що зібралися тут, командує Лорд Каззак — височенний командир вартових загибелі Палаючого Легіону. Після поразки Легіону в Третій війні він згуртував уцілілих демонів на півдні, щоб утримати смертоносний плацдарм на Азероті.",al={"хто веде демонів","бос оскверненого шраму","лорд казак осквернений шрам"}},{q="Чому серед демонів тут живе старий чоловік?",a="Цей відлюдник — Даіо Старезний, літній чорнокнижник, що наважився прийти до Шраму, щоб черпати з нього могутню енергію лей-ліній Скверни. Замість тікати від демонів, він править тут темні обряди біля вівтаря й навчає досвідчених чорнокнижників викликати інферналів.",al={"хто такий даїо","даїо немічний","відлюдник оскверненого шраму"}},{q="Чи пов'язаний Осквернений Шрам із Темним Порталом?",a="Так. Коли Темний Портал уперше прорвав межу між світами, хаотична енергія Нижнього Світу ринула в довколишні болота. Осквернений Шрам увібрав величезну кількість цих чарівних викидів, і земля назавжди спотворилася, обернувшись на негостинний демонічний оплот.",al={"осквернений шрам і темний портал","чому він зіпсований"}}},fp="12,280,23.561.0,18.385.0,25.273.0,27.232.0,49.263.0,49.266.0"}
P.entries["subzone:talonbranch-glade"] = {n="Галявина Кігтегілки",s="Галявина Кігтегілки — тихий прихисток нічних ельфів серед зачумлених пагорбів північного Сквернолісся. Розташована трохи на південь від Твердині Деревопащих, вона дає рідкісний притулок із чистим місячним світлом, безпекою й перельотами на гіпогрифах посеред оскверненої глушини.",h="Галявина Кігтегілки — тихий прихисток нічних ельфів серед зачумлених пагорбів північного Сквернолісся.",kw={"галявина кігтегілки","нічні ельфи","місячний колодязь","гіпогриф","твердиня деревопащих","сквернолісся","альянс"},ang={["faction:Alliance"]="Галявина Кігтегілки — ваша найпівнічніша робоча застава в Скверноліссі: тут є важливі перельоти, ремонт і прихисток біля Твердині Деревопащих.",["race:NightElf"]="Незаймана вода місячного колодязя на галявині свідчить про незгасну милість Елуни серед тяжкої демонічної зарази, що душить давній ліс."},sec={{t="Маяк серед зарази",b="Галявина Кігтегілки, що стоїть на узвишші біля тунелю до Твердині Деревопащих, — найпівнічніший оплот Альянсу в Скверноліссі. Ця застава, зосереджена довкола захищеної ельфійської ложі й діючого місячного колодязя, дає важливий прихисток від демонічної скверни, що поглинула довколишній ліс. Розвідники Альянсу, Вартові та шукачі пригод зупиняються на галявині, щоб відпочити, відновити сили й спланувати вилазки глибше в заражений ліс або далі до Вінтерспрінгу й Місячного Гаю."},{t="Перехрестя півночі",b="Окрім природного й духовного захисту, Галявина Кігтегілки — важливий транспортний вузол. Гіпогрифи, що стоять тут, переносять мандрівників до Обердайна на Темному Узбережжі та до Евірлука на засніжених просторах за Твердинею Деревопащих. Вона лишається самотньою пильною заставою, що тримає оборону проти тіней Ради Тіней, які підступають дедалі ближче, і зграй здичавілих звірів, що блукають оскверненими долинами."}},faq={{q="Що таке Галявина Кігтегілки?",a="Це табір Альянсу на півночі Сквернолісся — прихисток, місце відпочинку й пункт польотів для Вартових, друїдів і мандрівників, що перетинають зіпсований ліс.",al={"кігтегілка","призначення галявини кігтегілки","що це за місце"}},{q="Куди літає звідси розпорядник польотів?",a="Доглядач гіпогрифів на Галявині Кігтегілки має прямі польоти до кількох застав Альянсу й нейтральних поселень, зокрема до Обердайну, Евірлука й Місячного Гаю.",al={"польоти кігтегілки","точки польоту","куди можна полетіти"}},{q="Чи можна пити воду з місячного колодязя?",a="Так. На відміну від отруєних ставків і зіпсованих джерел по всьому Скверноліссю, місячний колодязь на Галявині Кігтегілки й досі благословенний Елуною й не торкнутий демонічною скверною.",al={"місячний колодязь кігтегілки","чи чиста вода","зіпсований колодязь"}},{q="Наскільки це близько до Твердині Деревопащих?",a="Галявина Кігтегілки лежить просто на південь від входу до Твердині Деревопащих — це останнє місце відпочинку перед тим, як вирушити тунелями фурболгів до Вінтерспрінгу чи Місячного Гаю.",al={"де твердиня деревопащих","шлях до вінтерспрінгу"}}},fp="17,255,22.502.0,25.395.0,26.165.0,41.142.0,43.170.0,36.176.0"}
P.entries["subzone:talondeep-path"] = {n="Стежка Глибокого Кігтя",s="Стежка Глибокого Кігтя — звивистий підземний тунель, що пронизує гірський хребет між Ашенвалем і Горами Кам'яного Кігтя. Тут не трапляється ні ворожих істот, ні подорожніх: це тихий природний підземний перехід, що з'єднує Озеро Містраль із Кручею Вітрорізу.",h="Стежка Глибокого Кігтя — звивистий підземний тунель, що пронизує гірський хребет між Ашенвалем і Горами...",kw={"тунель","підземний перехід","ашенваль","озеро містраль","круча вітрорізу","гори кам'яного кігтя"},ang={["profession:Mining"]="Звивисті скельні ніші печери прорізають глибоку кам'яну основу хребта, тож вона — природний орієнтир для тих, хто мандрує між багатими на руду Ашенвалем і Кам'яним Кігтем."},sec={{t="Тихий гірський прохід",b="Під суворим гребенем, що розділяє Ашенваль і Гори Кам'яного Кігтя, захована Стежка Глибокого Кігтя — тихий підземний шлях. Він з'єднує ліси трохи на захід від Озера Містраль із північно-західними околицями Кручі Вітрорізу. На відміну від небезпечних наземних стежок, де чатують хижаки й воюють ворожі сторони, у тунелі моторошно спокійно: ні ворожих звірів, ні таборів — лише безліч звивистих бічних кишень, розколин і природних ніш у скелі. Нагорі ще проглядають рештки прадавньої дороги — натяк на те, що колись мандрівники долали високі вершини, поки ця захищена печера не стала найзручнішим шляхом крізь камінь."}},faq={{q="Куди веде Стежка Глибокого Кігтя?",a="Тунель сполучає південний захід Ашенвалю з північним сходом Гір Кам'яного Кігтя. Його північний вхід — трохи на захід від Озера Містраль, а південний вихід відкривається на північно-західний бік Кручі Вітрорізу.",al={"куди веде стежка глибокого кігтя","зв'язки стежки глибокого кігтя","виходи тунелю глибокого кігтя"}},{q="Чи є в тунелі чудовиська чи вороги?",a="Ні. Усередині печери напрочуд спокійно: тут немає ні ворожих чудовиськ, ні звірів, ні дружніх персонажів, тож це безпечний прохід для мандрівників крізь гірський вододіл.",al={"чи безпечна стежка глибокого кігтя","моби стежки глибокого кігтя","загрози стежки глибокого кігтя"}},{q="Що за руїни над печерою?",a="Просто над печерою гірським кряжем тягнуться рештки зарослої наземної дороги. Схоже, ще до появи проходу крізь видовбане нутро гори існував давніший, підступний шлях суходолом через кручі.",al={"дорога над стежкою","наземний шлях кам'яного кігтя"}},{q="Чий це тунель — Альянсу чи Орди?",a="Жодна фракція тунелю не тримає. Це цілком неукріплена нейтральна дика місцевість, якою безпечно ходять пішки мандрівники будь-якої вірності між спірним лісом і горами.",al={"хто контролює стежку глибокого кігтя","фракція стежки глибокого кігтя"}}},fp="14,267,21.684.0,35.211.0,48.194.0,36.211.0,46.198.0"}
P.entries["subzone:talondeep-vale"] = {n="Долина Глибокого Кігтя",s="Долина Глибокого Кігтя — тиха лісиста улоговина в південно-центральному Ашенвалі. Вона межує з Притулком Срібного Вітру, Руїнами Зоряного Пилу та входом до Гір Кам'яного Кігтя і править мандрівникам за мирний зелений коридор на шляху південним Калімдором.",h="Долина Глибокого Кігтя — тиха лісиста улоговина в південно-центральному Ашенвалі.",kw={"долина глибокого кігтя","ашенваль","гори кам'яного кігтя","притулок срібного вітру","руїни зоряного пилу"},ang={["race:NightElf"]="Ці стежки в долині, поблизу священних вод Озера Містраль і Руїн Зоряного Пилу, добре знайомі вартовим і стражам, що патрулюють південний Ашенваль."},sec={{t="Затишна долина",b="Долина Глибокого Кігтя, що сховалася під густими кронами південно-центрального Ашенвалю, — перехрестя кількох знаних місць. Зі сходу її обрамлює Притулок Срібного Вітру, поблизу лежать моторошні Руїни Зоряного Пилу, а далі здіймається кам'янистий підйом до Гір Кам'яного Кігтя. Затінена прадавніми деревами, долина лишається диким лісовим краєм, яким проходять стражі й вартові нічних ельфів та випадкові мандрівники, прямуючи між серцем лісу й високими скелями за ним."}},faq={{q="Де розташована Долина Глибокого Кігтя?",a="Долина Глибокого Кігтя лежить на півдні центрального Ашенвалю, між Притулком Срібного Вітру, давніми Руїнами Зоряного Пилу й південним гірським перевалом до Гір Кам'яного Кігтя.",al={"де долина глибокого кігтя","розташування долини глибокого кігтя","як знайти долину глибокого кігтя"}},{q="Куди веде стежка на південь через долину?",a="Стежка через долину веде мандрівників до Стежки Глибокого Кігтя — підйому крізь скелясті висоти, що сполучає ліси Ашенвалю просто з посушливими вершинами Гір Кам'яного Кігтя.",al={"шлях на південь через долину","куди веде прохід глибокого кігтя","дорога до кам'яного кігтя"}},{q="На які прикмети поблизу варто зважати мандрівникам?",a="Долина межує з Притулком Срібного Вітру на сході й із затопленими Руїнами Зоряного Пилу, де під кронами дерев досі стоять давні рештки нічних ельфів.",al={"пам'ятки біля долини глибокого кігтя","що поруч із долиною глибокого кігтя"}}},fp="14,256,18.502.0,32.183.0,54.208.0,49.174.0"}
P.entries["subzone:tarren-mill"] = {n="Таррен Мілл",s="Таррен Мілл — обложена застава Відступників у північній частині Передгір'я Гілсбреда, під Горами Альтерак. Колись мирне людське хліборобське село, тепер це головний оплот Орди в Гілсбреді, що постійно воює з містечком Альянсу Саутшор на півдні.",h="Таррен Мілл — обложена застава Відступників у північній частині Передгір'я Гілсбреда, під Горами Альтерак.",kw={"таррен мілл","відступники","орда","саутшор","гілсбред","застава"},ang={["faction:Horde"]="Таррен Мілл — ваш єдиний великий прихисток у Передгір'ї Гілсбреда: тут є доглядач кажанів, припаси й важлива військова підтримка проти сил Альянсу, що наступають із Саутшора.",["race:Undead"]="Захоплення Таррен Мілла розширює південні кордони володінь королеви Сильвани, перетворюючи колись горде хліборобське містечко Лордерона на стратегічну твердиню проти живих."},sec={{t="Від зерна до могили",b="До Третьої війни Таррен Мілл був квітучим хліборобським містечком, вірним королівству Лордерон. Під час Другої війни він прославився, коли сили Альянсу визволили полонених лучників із високих ельфів із сусідніх орківських таборів, і це забезпечило Альянсові Лордерона повну підтримку Кель'Таласу. Проте сьогодні колишніх живих мешканців містечка вже немає — їхнє місце зайняли Відступники. Будівлі обвітрені й струхлявілі, поля порожні, а старий млин мовчить, поки нові мешканці-нежить укріплюють поселення від постійних загроз — гірських звірів, злочинців Синдикату й загонів Альянсу."},{t="Передова Гілсбреда",b="Таррен Мілл — важлива передова база Орди в краї. Він стоїть просто навпроти порту Альянсу Саутшор, і дорога між двома поселеннями перетворилася на відкрите поле бою. Мандрівники Орди використовують Таррен Мілл, щоб відтісняти людських фермерів і вояків, що засіли в Гілсбреді, організовувати удари по дворфах-копачах у Дун Ґароку й убезпечувати підступні дороги, що ведуть у засніжені скелі Гір Альтерак."}},faq={{q="Хто зараз тримає Таррен Мілл?",a="Таррен Мілл цілком у руках Відступників: це головний осередок завдань і застава Орди в Передгір'ї Гілсбреда.",al={"хто володіє таррен міллом","чи таррен мілл орди чи альянсу","фракція таррен мілла"}},{q="Чому Таррен Мілл і Саутшор воюють?",a="Таррен Мілл — південний рубіж Відступників і Орди в Лордероні, а Саутшор — останній великий оплот Альянсу в краї. Вони так близько одне від одного, що війна за землю неминуча: обидві сторони змагаються за родючі угіддя Гілсбреда й стратегічні дороги.",al={"саутшор проти таррен мілла","чому воюють із саутшором","війна гілсбреду"}},{q="Яким був Таррен Мілл до чуми?",a="Це було мирне людське поселення хліборобів і мірошників королівства Лордерон. Під час Другої війни вояки Альянсу звільнили неподалік від містечка полонених лучників — високих ельфів, і це скріпило військовий союз Кель'Таласу з Альянсом Лордерона.",al={"історія таррен мілла","хто тут жив раніше","лор таррен мілла"}},{q="Що, окрім Альянсу, загрожує Таррен Міллу?",a="Окрім сил Саутшора, Таррен Міллу доводиться протистояти місцевим розбійникам Синдикату, гірським єті й ограм, що спускаються з вершин Альтераку, і лютим гірським звірам, що блукають передгір'ям.",al={"вороги таррен мілла","місцеві небезпеки гілсбреду"}}},fp="11,317,19.631.0,23.462.0,35.138.0,44.306.0,44.250.0,59.201.0"}
P.entries["subzone:temple-gardens"] = {n="Храмові Сади",s="Храмові Сади — тихе, сповнене води серце Дарнасуса, що оточує невеликі острівці трохи на північ від Храму Місяця. Тут, серед мостів і бездоганної зелені, розташовані міський банк і чарівний портал-дерево, що веде до підніжжя Тельдрассила.",h="Храмові Сади — тихе, сповнене води серце Дарнасуса, що оточує невеликі острівці трохи на північ від Храму...",kw={"храмові сади","дарнасус","банк","портал","рут'теран","тельдрассил"},ang={["faction:Alliance"]="Кожен гість, що прибуває кораблем до пристані, мусить пройти крізь портал із Рут'терана в ці тихі води, щоб потрапити до решти міста.",["race:NightElf"]="Сади уособлюють гармонію дикої природи й міської архітектури, якою визначається дарнасуська культура: тут, посеред буденних справ, можна знайти спокій для роздумів."},sec={{t="Серце ельфійської столиці",b="Храмові Сади розкинулися на водах у центрі Дарнасуса й слугують роздоріжжям столиці нічних ельфів. Дерев'яні мости з'єднують їхні доглянуті острівці з Ценаріонським Анклавом на півночі, гамірними терасами на сході та величним святилищем — Храмом Місяця — на півдні. Нічні ельфи дбайливо плекають плинні води й буйну зелень цього куточка, і тут панує спокій, що дарує відпочинок і мандрівникам, і жрицям."},{t="Брама до Тельдрассила",b="Окрім міського сховища й банку на головному острові, Храмові Сади мають неабияке значення для всіх, хто прибуває до Світового Дерева чи залишає його. На західному березі садів стоїть величезний сяйливий рожевий портал-дерево. Ця чарівна арка миттєво переносить мандрівників крізь гілля донизу, до Селища Рут'теран біля підніжжя Тельдрассила, і пов'язує відокремлені верхні віти з прибережною пристанню та маршрутами польотів."}},faq={{q="Що за сяйний рожевий портал у садах?",a="Сяйний портал у дереві на західному краю садів — головний шлях між кроною Тельдрассилу та його підніжжям. Ступивши в нього, мандрівники миттю опиняються в Селищі Рут'теран, звідки кораблі й гіпогрифи сполучають нічних ельфів із Темним Узбережжям і рештою світу.",al={"рожевий портал у садах","портал дерева дарнасус","телепортер дарнасуса"}},{q="Де розташований банк Дарнасуса?",a="Головний міський банк — просто в Храмових Садах, у відкритому ельфійському павільйоні на найбільшому центральному острові кварталу.",al={"де банк дарнасуса","розташування банку","банкір дарнасуса"}},{q="Чому вони звуться Храмовими Садами?",a="Квартал названо на честь величного Храму Місяця, що стоїть одразу біля садів, уздовж їхньої південної межі.",al={"походження назви храмових садів","чому храмові сади"}},{q="Які квартали сполучені з Храмовими Садами?",a="Мости від садів розходяться через воду майже до кожного кварталу: на півночі — Ценаріонський Анклав, на сході — Тераса Ремісників, Тераса Воїнів і Тераса Торговців, а на півдні — Храм Місяця.",al={"куди ведуть храмові сади","мости з храмових садів"}}},fp="14,273,26.462.0,21.431.0,47.289.0,36.136.0,39.141.0,46.219.0"}
P.entries["subzone:temple-of-arkkoran"] = {n="Храм Арккорана",s="Храм Арккорана — прадавні руїни нічних ельфів на північно-східних скелях Азшари над Розтрощеним Узмор'ям. Колись його звели на честь Елуни, а тепер напівзруйновану споруду захопив могутній морський велетень Арккорок разом зі своїми морськими посіпаками.",h="Храм Арккорана — прадавні руїни нічних ельфів на північно-східних скелях Азшари над Розтрощеним Узмор'ям.",kw={"храм","арккоран","арккорок","елуна","азшара","макрури","морський велетень"},ang={["class:Priest"]="Хоч серед вивітреного каміння досі проступають прадавні символи Елуни, у цих побитих морем руїнах не лишилося й сліду божественного єднання.",["race:NightElf"]="Бачити, як священний дім Елуни перетворився на гніздовище макрур і морських велетнів, — гірке нагадування про пишноту, втрачену десять тисяч років тому."},sec={{t="Святиня, яку забрало море",b="Як і чимало величних руїн на узбережжі Азшари, Храм Арккорана колись був святилищем богині місяця Елуни — аж поки Розкол не зруйнував прадавню імперію нічних ельфів. Тепер його вивітрені мармурові сходи й поламані колонади заполонили чудовиська припливів. На найвищому ярусі храму панує морський велетень Арккорок, а довкола нього — віддані макрури й люті мурлоки, які жорстоко боронять узбережжя від будь-яких сухопутних зайд."}},faq={{q="Для чого спершу збудували Храм Арккорана?",a="Задовго до того, як споруда дістала нинішню назву, це був храм нічних ельфів, присвячений поклонінню Елуні. Він обернувся на руїни під час Великого Розколу разом із рештою довколишньої прибережної цивілізації.",al={"історія храму арккорана","хто збудував храм арккорана","що це за храм"}},{q="Хто такий Арккорок?",a="Арккорок — могутній морський велетень, що облаштував собі дім у колишньому храмі нічних ельфів. Він живе на найвищому помості руїн і панує над довколишнім берегом і прибережними звірами, що тут живуть.",al={"хто такий арккорок","арккорок морський велетень","хто править арккораном"}},{q="Хто стереже храмові угіддя?",a="Храм і довколишні тераси патрулюють агресивні макрури й мурлоки — клацуни, щипачі й муложиви Арккорана. А на довколишніх пляжах Розтрощеного Узмор'я живуть гідри й інші морські велетні.",al={"моби храму арккорана","що живе в храмі арккорана","вороги храму арккорана"}}},fp="18,270,37.478.0,53.228.0,16.208.0,40.238.0"}
P.entries["subzone:temple-of-atal-hakkar"] = {n="Храм Атал'Гаккара",s="Храм Атал'Гаккара, більш відомий як Затонулий Храм, — затоплена твердиня, яку звели вигнані жерці-тролі, віддані богові крові Гаккару. Століття тому зелені дракони занурили його в болото, але затоплені зали храму й досі лишаються осередком заборонених ритуалів і темної скверни.",h="Храм Атал'Гаккара, більш відомий як Затонулий Храм, — затоплена твердиня, яку звели вигнані жерці-тролі...",kw={"храм атал'гаккара","затонулий храм","гаккар","атал'аї","ізера","джаммал'ан пророк"},ang={["class:Druid"]="Скверна, що вразила вартових Ізери — зелених драконів — у глибинах храму, б'є в самісіньке серце Смарагдового Сну й вимагає негайного розслідування.",["race:Troll"]="Для тролів Темного Списа ці руїни — похмуре нагадування про скроплене кров'ю безумство, що зруйнувало прадавню Імперію Ґурубаші, і про вічну загрозу Гаккара Душолупа."},sec={{t="Гнів зеленої зграї",b="Понад тисячу років тому руйнівна громадянська війна розколола Імперію Ґурубаші, коли жрецтво Атал'аї спробувало викликати Гаккара Душолупа. Вигнані на північ, уцілілі фанатики звели на Болоті Скорботи величезний кам'яний храм, щоб завершити свою темну справу. Дізнавшись про їхній задум, Ізера, Аспект драконів, вбила зикурат глибоко в трясовину й затопила його зали під Ставком Сліз. Вартових — зелених драконів — лишили стерегти затоплені руїни, щоб Гаккар ніколи не повернувся."},{t="Сон, що обернувся жахіттям",b="Замість того щоб поховати культ, затоплення храму дало Атал'аї усамітнення, і вони безперешкодно продовжували свої криваві жертвоприношення. За століття скверна почала роз'їдати вартових зсередини: дракони-стражі піддаються безумству, а Атал'аї під проводом Джаммал'ана Пророка готують шлях для аватара Гаккара. Тепер і Орда, і Альянс стривожено стежать за затопленим зикуратом, бо з глибин болота просочуються темні чутки."}},faq={{q="Чому храм під водою?",a="Ізера, Аспект зеленого драконячого роду, власноруч занурила храм під води болота, щоб не дати тролям Атал'ай викликати на Азерот бога крові Гаккара.",al={"чому храм під водою","хто потопив храм","як він затонув"}},{q="Хто такі Атал'ай?",a="Атал'ай — фанатична секта тролів-жерців, вигнана з південної Імперії Ґурубаші за магію крові й спроби викликати Гаккара Душолупа у світ живих.",al={"лор атал'аїв","хто збудував затонулий храм","жерці атал'ай"}},{q="Чому тут зелені дракони?",a="Ізера доручила загону зелених драконів пильнувати затонулі руїни й не пускати туди зайд, щоб Гаккара ніколи не змогли викликати. На жаль, чимало цих вартових збожеволіли й піддалися темній скверні.",al={"чому дракони на болоті","зелений політ затонулий храм"}},{q="Як потрапити до храму?",a="Треба запливти в затоплені руїни зі Ставка Сліз, пробратися затопленими переходами Зруйнованої Зали й піднятися кам'яними коридорами на кшталт Зали Масок.",al={"як зайти в затонулий храм","вхід у затонулий храм","потрапити в атал'гаккар"}}},fp="21,301,25.529.0,26.462.0,29.183.0,20.188.0,33.223.0,33.178.0"}
P.entries["subzone:temple-of-the-moon"] = {n="Храм Місяця",s="Храм Місяця в Дарнасусі — духовне серце нічних ельфів і осідок влади на Тельдрассилі. Святилище, яким опікується Верховна Жриця Тіранда Віспервінд, є головною оселею Сестринства Елуни. У його високих мармурових ярусах ховається священна місячний колодязь, чиї благословенні води зцілюють і єднають із Місячною Богинею.",h="Храм Місяця в Дарнасусі — духовне серце нічних ельфів і осідок влади на Тельдрассилі.",kw={"храм місяця","елуна","тіранда","сестринство елуни","місячний колодязь","дарнасус","жриці"},ang={["class:Priest"]="Для жерців Альянсу, а надто для нічних ельфів, храм — найвище джерело божественного покликання Елуни й оселя їхніх найдосвідченіших наставників.",["race:NightElf"]="Храм — культурне, духовне й громадське осердя сучасного калдорейського життя, де під одним дахом поєднано Сестринство Елуни й управління Тельдрассилом."},sec={{t="Святилище Місячної Богині",b="Храм Місяця звели невдовзі після Третьої війни, коли нічні ельфи оселилися на Тельдрассилі. Це одна з найбільших кам'яних споруд, збудованих руками сучасних калдореїв. Більшість мармуру для нього видобули на материковому Калімдорі й переправили через море за допомогою магії. Посеред храму розлилася широка місячний колодязь під наглядом статуї Гайдене, і освячені води випромінюють тиху силу. Храм — не лише місце молитви й тихих роздумів для прочан, а й політична вершина Дарнасуса: тут перебуває Верховна Жриця Тіранда Віспервінд, що веде свій народ на порозі непевної нової доби."},{t="Оплот Сестринства",b="На тихих терасах храму жриці Сестринства Елуни виконують волю богині — і в духовних справах, і в ратних. Звідси по всьому північному Калімдору розсилають посланниць і сестер, щоб розвідати загрози чи допомогти місцевим вартовим, — як-от Жриця Ґвенніт Блай'Леґґонд, що розпитує про події вздовж берегів Темного Узбережжя. Послушниці й досвідчені жриці збираються під зоряним склепінням, щоб опановувати божественні закляття, доглядати поранених і берегти святилище від скверни ззовні."}},faq={{q="Хто очолює Храм Місяця?",a="Храмом опікується Верховна Жриця Тіранда Віспервінд. Як очільниця Сестринства Елуни й фактична голова уряду калдореїв, вона приймає на верхніх ярусах і керує і духовними, і військовими справами Дарнасуса.",al={"лідер храму місяця","хто в храмі","де тайранда"}},{q="Як збудували храм на Тельдрассилі?",a="Тельдрассил виріс із гілок посеред океану, але сам храм — одна з небагатьох великих кам'яних споруд Дарнасуса. Мармур і камінь для нього добули на суходолі Калімдору й перенесли на вершину світового дерева за допомогою магії.",al={"як збудували храм місяця","кам'яний храм дарнасуса походження"}},{q="Що за ставок посеред храму?",a="Ставок посередині — священний місячний колодязь під наглядом статуї Гайдене. Його води глибоко освячені й шануються як пряме благословення Елуни: Сестринство використовує їх для обрядів очищення, медитацій і могутньої цілющої магії.",al={"місячний колодязь храму","вода в храмі місяця"}},{q="Які послуги тут можуть знайти гравці?",a="Храм — головне місце навчання жерців у Дарнасусі. Шукачі пригод також приходять сюди, щоб звітувати Верховній Жриці Тіранді Віспервінд і отримати настанови чи доручення від Сестринства Елуни.",al={"що в храмі елуни","наставники храму дарнасуса"}}},fp="18,378,29.664.0,24.544.0,33.245.0,39.261.0,45.247.0,36.220.0"}
P.entries["subzone:terrace-of-repose"] = {n="Тераса Спочинку",s="Тераса Спочинку — бездоганно доглянутий сад-подвір'я просто перед входом до Багряного Монастиря в Галявинах Тірісфалю. Її доглядає Багряний Хрестовий Похід, і це одне з небагатьох місць на півночі Лордерону, якого зовсім не торкнулася Чума нежиття: тут зелені живоплоти й чиста вода.",h="Тераса Спочинку — бездоганно доглянутий сад-подвір'я просто перед входом до Багряного Монастиря в Галявинах...",kw={"тераса спочинку","багряний монастир","галявини тірісфалю","сад","фонтан","чума нежиття"},ang={["class:Paladin"]="Жива рослинність і незабруднена вода в Тірісфалі — переконливий доказ того, що ця земля здатна загоїтися, хай навіть нині за нею доглядають непохитні фанатики.",["race:Undead"]="Для Відступників бездоганна зелень тераси — різке й гірке нагадування про світ живих, який їх відкидає, — світ, який доглядають смертні вороги, що прагнуть лише очистити Лордерон від їхнього роду."},sec={{t="Оаза серед зарази",b="Тераса Спочинку, що лежить трохи на північ від величного входу до Багряного Монастиря, — майже нереальна протилежність гниючим лісам Галявин Тірісфалю. Поки решта Лордерону задихається під сірою імлою, на отруєній землі й у застояних болотах, ця тераса може похвалитися буйними, акуратно підстриженими живоплотами й справним фонтаном зі свіжою, незараженою водою. Для фанатиків Багряного Хрестового Походу сад — відчутний доказ їхньої божественної праведності й чистоти, священний оплот, що показує: свята відданість може відвернути скверну Погибелі."}},faq={{q="Чому тут чиста трава й вода, коли Тірісфаль мертвий?",a="Тераса Спочинку вціліла від чуми нежиття. Невсипущою пильністю — і, можливо, палкою відданістю Святому Світлу — Багряний Хрестовий Похід зберіг тут ґрунт, висадив буйні живоплоти й підтримує чисте, свіже джерело води, цілком вільне від гнилі довкола.",al={"чому тут зелено","чиста вода багряного монастиря","незіпсована тераса спочинку"}},{q="Де саме розташована Тераса Спочинку?",a="Вона одразу перед входом до комплексу Багряного Монастиря, серед північно-східних пагорбів Галявин Тірісфалю.",al={"де тераса спочинку","розташування тераси спочинку","вхід у сад монастиря"}},{q="Для чого хрестоносці використовують терасу?",a="Вона не лише підступ до їхнього укріпленого монастиря, а й тихий прихисток незіпсованої землі, де хрестоносці можуть відпочити, поміркувати й побачити ідеалізований образ королівства Лордерон таким, яким воно було до Третьої війни.",al={"сад хрестоносців","призначення тераси спочинку"}}},fp="17,314,22.565.0,60.300.0,47.135.0,42.239.0"}
P.entries["subzone:terror-run"] = {n="Стежка Жаху",s="Стежка Жаху — небезпечна смуга землі в південно-західній частині Кратера Ун'Ґоро, просто на захід від комашиних вуликів Звивистого Шраму. Як і обіцяє її грізна назва, тут нишпорять хижі звірі — від велетенських дияволозаврів до ненажерливих діеметродонів і птеррордаксів, що пікірують з неба.",h="Стежка Жаху — небезпечна смуга землі в південно-західній частині Кратера Ун'Ґоро, просто на захід від...",kw={"стежка жаху","дияволозаври","птеррордакси","червоні кристали сили","ун'ґоро","мисливець"},ang={["class:Hunter"]="Широкі рівнини Стежки Жаху — смертельне випробувальне поле з одними з найлютіших звірів Калімдору: від прудких рапторів і хижих птеррордаксів до велетенських дияволозаврів."},sec={{t="Полювання просто неба",b="Стежка Жаху простягається південно-західним уступом Кратера Ун'Ґоро й цілком виправдовує свою зловісну славу. Люті птеррордакси кружляють у вологому повітрі, а внизу, серед низьких чагарів, блукають велетенські діеметродони, стегодони й верховні хижаки — дияволозаври. Ця місцина лежить у самій тіні гірського краю кратера, незатишно затиснута поряд зі стрекотливими чужорідними насипами Звивистого Шраму. Уздовж східного краю рівнини лежать рештки табору, який покинула експедиція Віллідена Маршала, — тверезе нагадування про дослідників, яких первісні хижаки кратера застали зненацька."},{t="Червоні кристали й прадавні хижаки",b="Окрім самого лише скупчення голодних звірів, Стежка Жаху вабить і натуралістів, і шукачів пригод геологічною рідкістю: це головне місце в кратері, де з родючого ґрунту проступають дивовижні Червоні кристали сили. Багряні утворення гудуть первісною енергією, як і сині, зелені та жовті кристали, що трапляються в інших куточках западини. Та щоб прожити достатньо довго й зібрати їх, доведеться мати справу з повновладними мисливцями рівнин — зокрема з дияволозаврами, що гніздяться тут і не терплять жодних порушників на глибокому півдні."}},faq={{q="Чому ця місцевість зветься Стежкою Жаху?",a="Назва відбиває смертельне скупчення найгрізніших хижаків, що полюють у цьому відкритому коридорі. Між величезними дияволозаврами, діметродонами, що ревно бережуть свої ділянки, і пильними птеррордаксами в небі кожен, хто перетинає рівнину пішки, ризикує тікати щодуху, рятуючи життя.",al={"значення стежки жаху","чому стежка жаху","хто назвав стежку жаху"}},{q="Що тут можна знайти, окрім небезпечних звірів?",a="Стежка Жаху — єдине місце в Кратері Ун'Ґоро, де із землі можна добути Червоні Кристали Сили. А на її східному краю є покинутий дослідницький табір, який лишила експедиція Віллідена Маршала під час небезпечного обстеження кратера.",al={"що в стежці жаху","кристали стежки жаху","ресурси стежки жаху"}},{q="Що за покинутий табір на східному краю?",a="Покинутий табір належав учасникам експедиції Віллідена Маршала. Учені й дослідники мусили кинути своє обладнання й тікати, коли місцеві звірі змели їхню позицію.",al={"табір маршала стежка жаху","покинутий табір дослідників","табір загубленої експедиції"}},{q="Де лежить Стежка Жаху відносно інших прикмет?",a="Вона охоплює південний захід Кратера Ун'Ґоро — просто на захід від вуликів силітидів, відомих як Звивистий Шрам, і на південь від центрального вулкана, Хребта Вогняного Шлейфу.",al={"розташування стежки жаху","де стежка жаху"}}},fp="10,310,18.617.0,34.534.0,35.276.0,48.257.0,47.214.0,57.172.0"}
P.entries["subzone:terror-wing-path"] = {n="Шлях Крил Жаху",s="Шлях Крил Жаху — скелястий каньйон, що в'ється східними околицями Палаючих Степів. Тут кишать дракончата й дракониди чорного драконячого роду, і саме цей небезпечний шлях веде у віддалений північно-східний куток Пусток.",h="Шлях Крил Жаху — скелястий каньйон, що в'ється східними околицями Палаючих Степів.",kw={"шлях крил жаху","палаючі степи","дракончата","чорні дракони","волчан","каньйон"},ang={["class:Hunter"]="Круті схили й літаючі дракончата роблять Шлях Крил Жаху полігоном для стрільців, що вистежують драконячих звірів серед диму й вітрів каньйону."},sec={{t="Гніздовище драконородів",b="Шлях Крил Жаху, врізаний у скелясті, вкриті попелом передгір'я східних Палаючих Степів, завдячує своєю назвою повітряним хижакам і драконородам, які ним заволоділи. Виводки чорного драконячого роду никають цими ущелинами, люто стережуть кладки й полюють на кожного, кому вистачить дурості забрести в їхню тінь. Попіл і кіптява вкривають кам'яні стежки, тож будь-яка подорож попід стінами каньйону — ризикована справа."},{t="Небезпечний прохід",b="Чорні дракони патрулюють долину з кінця в кінець, а часом тут бачать і рідкісного магмового велетня Волчана. Лише найдосвідченіші шукачі пригод наважуються на цю подорож, і то рідко поодинці, — проте тільки цим шляхом можна дістатися прихованої печери Звивистої Скелі в далекому північно-східному кутку Пусток."}},faq={{q="Хто живе на Шляху Крил Жаху?",a="Шлях заполонили дракончики, драконячі пташенята й більші драконячі створіння чорного роду. Вони агресивно патрулюють схили й полюють на наземну здобич по всьому східному перевалу.",al={"моби крил жаху","що тут","драконороди крил жаху"}},{q="Куди веде Шлях Крил Жаху?",a="Він в'ється східною частиною Палаючих Степів до віддаленого північно-східного кута краю, де за ним ховається печера Звивиста Скеля.",al={"куди веде шлях крил жаху","маршрут крил жаху","напрямки шляху крил жаху"}},{q="Чому чорний драконячий рід такий діяльний у цьому каньйоні?",a="Чорний драконячий рід міцно тримає Палаючі Степи під Горою Блекрок. Шлях Крил Жаху дає йому гніздовища, мисливські угіддя й східний рубіж, що стереже фланги гори.",al={"чому дракони тут","чорний драконячий політ крила жаху","присутність драконячого роду"}}},fp="16,239,17.411.0,18.300.0,40.173.0,33.156.0,52.214.0"}
P.entries["subzone:terrordale"] = {n="Террордейл",s="Террордейл — зруйноване поселення на північно-західному краю Східних Чумних Земель, де блукають привиди. Містечко межує із зачумленим Чумноліссям і Тунелем Жахоппавутини, де кишать павуки, а його руїни заполонили Погибель і неупокоєні мерці.",h="Террордейл — зруйноване поселення на північно-західному краю Східних Чумних Земель, де блукають привиди.",kw={"террордейл","привиди","авґустус торкнутий","еґан","ґрейсон шедовбрейкер","бойовий скакун","паладин"},ang={["class:Paladin"]="Террордейл — важливе місце випробувань для досвідчених паладинів: Лорд Ґрейсон Шедовбрейкер велить кандидатам на бойового скакуна вирушити до зруйнованого селища й вигнати його ридаючих духів.",["race:Human"]="Зруйновані будинки Террордейлу — тверезе нагадування про падіння північного Лордерона, де духи простих містян і після смерті лишаються в пастці на власних подвір'ях."},sec={{t="Примарний притулок на узліссі",b="Колись Террордейл був тихим поселенням на півночі Лордерона, але впав перед Погибеллю разом з усім королівством. Нині село стоїть у похмурих руїнах біля входу до Тунелю Жахоппавутини. Його вулиці заполонили неспокійні тіні й блукаюча нежить, а дерева Чумнолісся підступають до гнилих зрубів. Серед цього запустіння залишитися наважилися лише кілька диваків, як-от чудернацький торговець Авґустус Торкнутий і мисливець на привидів Еґан, який намагається звільнити змучених духів, що застрягли між світами."},{t="Неспокій духів і вигнання",b="Мука загибелі Террордейлу була така глибока, що матеріальний світ буквально прогинається під тягарем страждань світу духів. Духи Террордейлу застигли у вічній агонії, прикуті до землі своїм трагічним кінцем. Через таке скупчення духовного осквернення досвідчених паладинів під проводом Срібної Длані й Лорда Ґрейсона Шедовбрейкера посилають сюди правити обряди суду й жертви. Вони проганяють муку, і це для них священне випробування святої дисципліни."}},faq={{q="Що таке Террордейл?",a="Террордейл — покинуте, зруйноване село на північному заході Східних Чумних земель. Воно лежить трохи на захід від Чумнолісся й на південь від Тунелю Жахоппавутини, і його цілком заполонили жахіття Погибелі й змучені привиди.",al={"де террордейл","що це за містечко","лор террордейла"}},{q="Хто досі лишається в містечку?",a="Серед руїн тиняються двоє диваків: Еґан — безстрашний мисливець за привидами, що намагається заспокоїти й звільнити замкнених духів, і Авґустус Торкнутий — напівбожевільний самітник-нежить і крамар, одержимий пошуками своїх старих книг обліку й пожитків.",al={"хто такий еґан","хто такий авґустус","живі нпс террордейла"}},{q="Як це містечко пов'язане з випробуваннями паладинів?",a="Лорд Ґрейсон Шедовбрейкер посилає до Террордейла паладинів, що прагнуть здобути священного бойового коня. Паладини мають вигнати тутешніх змучених духів освяченою водою, довівши духовну стійкість, розсудливість і самопожертву, яких вимагають від добірного лицаря Світла.",al={"кінь паладина террордейл","вигнання нечистого террордейл","лорд ґрейсон тінезламувач"}}},fp="10,252,34.553.0,34.478.0,19.219.0,37.245.0,46.281.0"}
P.entries["subzone:terrorweb-tunnel"] = {n="Тунель Жахоппавутини",s="Тунель Жахоппавутини — підземний прохід крізь гори між Террордейлом і Річкою Тондроріл. У ньому кишать склепні потвори Погибелі — неупокоєні неруби, тож ця підземна коротка дорога через західний кордон Східних Чумних Земель дуже небезпечна.",h="Тунель Жахоппавутини — підземний прохід крізь гори між Террордейлом і Річкою Тондроріл.",kw={"тунель жахоппавутини","склепні потвори","неруби","террордейл","річка тондроріл","тіріон фордрінг"},ang={["class:Paladin"]="Південний вихід тунелю — за кілька кроків від вигнаного верховного лорда Тіріона Фордрінга. Його присутність біля цього гнійного вулика — самотня варта проти повзучої навали Погибелі."},sec={{t="Підземне зараження",b="Тунель Жахоппавутини, пробитий просто крізь гори обабіч Річки Тондроріл, з'єднує заражене село Террордейл із берегами річки на півдні. Тут немає звичних гулів чи скелетів-вартових: цей темний підземний обхід цілком захопили склепні потвори — муміфіковані нерубські павукоподібні, яких Король-Ліч підняв собі на службу. Пройшовши прохід, можна оминути довгі манівці схилами гір, але доведеться продиратися крізь густе павутиння й уникати велетенських нерубських наглядачів, що патрулюють темряву."}},faq={{q="Куди веде Тунель Жахоппавутини?",a="Тунель прорізає гірський хребет наскрізь на північний захід від Террордейла. Його північний вхід відкривається в Террордейл, а південний вихід — на скелясті береги над Річкою Тондроріл.",al={"шлях тунелю жахоппавутини","куди веде жахоппавутина","зв'язки жахоппавутини"}},{q="Хто живе в тунелі?",a="Тунель кишить склеповими потворами — нерубами-нежиттю, павуками-володарями давнього Нортренду, піднятими в лави Погибелі. Серед них тунелями часом нишпорять грізні нерубські наглядачі, тож мандрувати тут надзвичайно небезпечно.",al={"моби жахоппавутини","хто живе в тунелі жахоппавутини","монстри тунелю"}},{q="Хто поблизу, за тунелем?",a="Вигнаний паладин Тіріон Фордрінг тримає скромний табір над Річкою Тондроріл, неподалік від південного виходу з тунелю.",al={"хто за тунелем","тіріон біля жахоппавутини","нпс біля тунелю жахоппавутини"}},{q="Звідки в Чумних Землях неруби?",a="Підкоривши підземне королівство Аз'жол-Неруб у Нортренді, Король-Ліч оживив полеглих нерубів як склепових потвор. Коли Погибель вдерлася в Лордерон, цих павукоподібних штурмовиків послали на південь, щоб зміцнити владу Культу Проклятих над краєм.",al={"чому тут склепові поганці","неруби в чумних землях"}}},fp="16,272,26.538.0,33.207.0,34.240.0,33.134.0,37.271.0"}
P.entries["subzone:thalanaar"] = {n="Таланаар",s="Таланаар — відлюдна застава нічних ельфів просто на межі між зеленими нетрями Фераласу й посушливими каньйонами Тисячі Голок. Це головна східна брама Альянсу до Фераласу: тут утомлені мандрівники знаходять важливе сідало гіпогрифів і прихисток під лісовим наметом. Застава невелика, але вона — ключова ланка між материковим Калімдором і віддаленою Твердинею Перистого Місяця.",h="Таланаар — відлюдна застава нічних ельфів просто на межі між зеленими нетрями Фераласу й посушливими...",kw={"таланаар","фералас","тисяча голок","гіпогрифи","застава","альянс"},ang={["faction:Alliance"]="Коли ви рушаєте на захід від підступних плато Тисячі Голок до диких джунглів Фераласу, Таланаар стає вашим першим безпечним притулком і надійним вузлом польотів.",["race:NightElf"]="Застава — пост Вартових, що пильно стежить за кордоном і вітає родичів, які повертаються під прадавній лісовий намет Фераласу, до тіні предків."},sec={{t="Брама до забутих нетрів",b="Таланаар стоїть у природній вузькій шийці, де розпечений пісковик Тисячі Голок поступається місцем густому туманному лісовому наметові Фераласу, — це перша ознака присутності нічних ельфів для мандрівників зі сходу. Застава — лише укріплений гай із кількома міцними павільйонами та вартовими на чатах, проте розташування в неї надзвичайно важливе. Тут знаходять притулок розвідники, гінці й ремісники Альянсу, що вирушають у дикий ліс, — це надійний плацдарм проти звірів, огрів і загонів Орди, що блукають південним Калімдором."},{t="Важлива повітряна ланка",b="Подорож суходолом через південний Калімдор сповнена небезпек, тож головне призначення Таланаару — сполучення. Тутешній приборкувач гіпогрифів пов'язує відлюдні нетрі Фераласу просто з Островом Терамор за морем, Ґаджетзаном у Танарісі та острівним оплотом — Твердинею Перистого Місяця — на заході. Сюди навідуються й ремісники: вони шукають майстрів-шкірників, що під лісовим гіллям навчають давнього мистецтва обробки диких шкур."}},faq={{q="Що таке Таланаар?",a="Таланаар — невеликий прикордонний табір нічних ельфів біля східного входу до Фераласу, саме там, де край межує з Тисячею Голок. Це застава Альянсу, де можна знайти прихисток, найнеобхідніші припаси й політ.",al={"огляд таланаару","що це за місце","табір таланаар"}},{q="Куди може відправити мене розпорядник польотів?",a="Із сідала гіпогрифів Таланаару можна полетіти до Твердині Перистого Місяця біля західного узбережжя Фераласу, до Острова Терамор у Багні Пилоброду й до нейтрального гоблінського порту Ґаджетзан у Танарісі.",al={"польоти таланаару","куди можна полетіти","майстер польотів таланаару"}},{q="Навіщо ремісникам шукати Таланаар?",a="На заставі живе Кариссія Мунгантер — майстриня-наставниця рідкісної традиції Племінної шкіряної справи, до якої з'їжджаються вправні ремісники з усього Калімдору.",al={"наставники таланаару","шкіряна справа таланаар","карисія місяцелов"}},{q="Чи безпечний Таланаар для шукачів пригод з Орди?",a="Ні. Таланаар — тверде поселення Альянсу під охороною вартових нічних ельфів, які одразу нападуть на будь-кого з Орди.",al={"чи дружній таланаар до орди","орда в таланаарі"}}},fp="9,422,35.537.0,19.450.0,18.223.0,36.186.0,38.172.0,40.128.0"}
P.entries["subzone:thalassian-base-camp"] = {n="Талассійський Базовий Табір",s="Талассійський Базовий Табір, що примостився на високому хребті північної Азшари, — опорний пункт експедиції ельфів крові, які розкопують прадавні таємні реліквії. Спершу табір фінансувала Орда за угодою, але щойно почалися розкопки, його провідники порушили слово. Тепер серед червоних наметів і перетертих на порох магічних артефактів темні ритуали призову натякають на справжні цілі експедиції.",h="Талассійський Базовий Табір, що примостився на високому хребті північної Азшари, — опорний пункт експедиції...",kw={"табір","ельфи крові","азшара","рімторі","блискучий пил","зрада","орда"},ang={["class:Mage"]="Унікальний спосіб, у який ельфи крові перетворюють артефакти на Блискучий Пил, дає рідкісний, хоч і небезпечний, погляд на талассійські методи — ними цікавиться навіть Архімаг Ксилем.",["faction:Horde"]="Орда не прощає зламаних клятв: Магус Рімторі взяла ваші гроші, а віддячила лише зрадою, тож цей табір — законна ціль для відплати."},sec={{t="Зламана угода",b="Експедиція ельфів крові, що отаборилася на схід від Урсолана, не мала б ворогувати з мандрівниками з Оргріммара. Її провідниця, Магус Рімторі, уклала з Ордою офіційну угоду: в обмін на постачання, гроші та збройний супровід крізь небезпечні дикі землі Азшари її дослідники мали ділитися всіма знайденими магічними скарбами. Проте щойно базовий табір укріпили, а з ельфійських руїн витягли перші реліквії, Рімторі цілком відмовилася від угоди й прогнала посланців Орди. Поки Рімторі зі збройним почтом обшукує глибші закутки, Магістр Гокгелм пильнує хребет і стереже табір від відплати."},{t="Пил і демонологія",b="Ельфи крові прийшли сюди не лише впорядковувати історію. Вони володіють незвичною технікою: перетирають знайдені магічні дивовижі на Блискучий Пил — очищений порошок, зовсім не схожий на звичайні рештки від зачарування. Ним уже зацікавився Архімаг Ксилем. Та ще тривожніше інше: вище на хребтах табору лежить Калдорейський фоліант призову. Це аж ніяк не наукове дослідження реліквій Високородних — фоліант викриває зловісну готовність прорвати завісу й закликати демонів просто в руїни Азшари."}},faq={{q="Чому тут, в Азшарі, ельфи крові?",a="Вони — частина чарівних розкопок під проводом Магус Рімторі. Вони перетнули Калімдор, щоб видобувати з руїн давнього Калімдору могутні чарівні артефакти, шукаючи силу, яку можна було б черпати й висмоктувати після знищення Сонячного Колодязя.",al={"чому в ашарі ельфи крові","призначення талассійського табору","хто тут живе"}},{q="Чому Орда ворожа до цього табору?",a="Магус Рімторі взяла в Орди гроші й ресурси, пообіцявши поділитися знахідками експедиції. Та щойно її сили надійно закріпилися на півночі Азшари, вона порушила угоду, відмовилася віддавати будь-яку данину, і Орда тепер прагне помсти.",al={"чому орда нападає на талассійський табір","зрада мага рімторі","лор завдання зради"}},{q="Хто очолює Талассійський Базовий Табір?",a="Загальна очільниця експедиції — Магус Рімторі, хоча вона часто мандрує Азшарою в супроводі особистих охоронців. За її відсутності повсякденне командування табором переходить до Магістра Гокгелма.",al={"хто керує талассійським табором","бос табору","магістр яструбиний шолом"}},{q="Що таке Блискучий Пил?",a="Це чарівний залишок, що утворюється за особливою методикою ельфів крові, коли вони подрібнюють зачаровані реліквії. На відміну від звичайного пилу, який добувають розчаровуванням, його незвичайні властивості викликали неабиякий інтерес дивакуватого Архімага Ксилема.",al={"магічний пил ксилем","блискучий пил лор","чому дробити чарівні речі"}},{q="Що за Калдорейський Фоліант Виклику на кряжі?",a="Цей давній фоліант лежить на кряжі над табором, і за його допомогою можна викликати сюди демонів. Він викриває, що експедиція Рімторі займається значно темнішими справами, ніж просто пошук історичних реліквій.",al={"книга на пагорбі","калдорейський том","демонська книга ашара"}}},fp="20,415,18.654.0,19.532.1,36.238.0,38.249.0,35.211.0,24.271.0,52.221.0"}
P.entries["subzone:thandol-span"] = {n="Міст Тандол",s="Міст Тандол — пара велетенських кам'яних дворфійських мостів, що з'єднують Багнокрай у Каз Модані з Аратійським нагір'ям на півдні Лордерону. Здавна прославлений як диво інженерної думки й життєво важлива артерія між північними та південними королівствами, нині він у катастрофічному стані після диверсії лазутчиків із клану Темного Заліза.",h="Міст Тандол — пара велетенських кам'яних дворфійських мостів, що з'єднують Багнокрай у Каз Модані з...",kw={"міст тандол","темне залізо","каз модан","багнокрай","айронфордж","дун модр","горяни"},ang={["faction:Alliance"]="Міст — єдиний прямий суходільний зв'язок між Каз Моданом і обложеними північними заставами Лордерону, тож його оборона вкрай важлива для всієї війни.",["race:Dwarf"]="Для дворфів Айронфорджа Міст — і шедевр їхніх каменярів, і болюче поле бою, де родичі з Темного Заліза принесли руйнування просто під їхні двері."},sec={{t="Перерізана артерія",b="Міст Тандол звели після Війни Трьох Молотів, щоб поєднати Айронфордж із кланом Вайлдгаммерів з Орлиного Піку, і він належить до найвеличніших звершень дворфійського каменярства. Здатний витримати цілі армії на марші, у Другу війну він був ключовим суходільним коридором між Лордероном і Каз Моданом — зокрема, саме ним пройшов на південь контрнаступ сера Андуїна Лотара. Нині переправа тяжко поранена. Диверсанти Темного Заліза на чолі з Балґарасом Мерзенним і Камом Діпф'юрі завдали нищівного удару з недалекого Дун Модра: вибухівкою вони вщент зруйнували один із мостів і загрожують остаточно перерізати суходільний шлях між союзними краями."},{t="Бій за переправу",b="За вцілілий міст досі точаться бої, і його пильно стережуть. Горяни з Айронфорджа відчайдушно борються, щоб зберегти останню дорогу й відбити саперів Темного Заліза, і зазнають тяжких втрат. Якщо міст упаде, північна торгівля й переміщення військ майже цілком залежатимуть від морських шляхів, а сили Альянсу, розкидані по Аратійському нагір'ю, лишаться без швидкої підмоги."}},faq={{q="Що таке Міст Тандол?",a="Це величезний дворфійський кам'яний міст із двома арками, перекинутий через глибокий каньйон між Багнокраєм на півночі Каз Модану й Аратійським нагір'ям на півдні Лордерона.",al={"огляд моста тандол","що це за міст","міст тандол"}},{q="Чому один із мостів зруйновано?",a="Дворфи Темного Заліза завдали удару із захопленої застави Дун Модр і потужною вибухівкою зруйнували один із двох прогонів, намагаючись перерізати шляхи постачання Альянсу.",al={"хто підірвав міст","зруйнований тандол","чому міст тандол зламаний"}},{q="Навіщо спершу збудували Міст Тандол?",a="Дворфи Айронфорджа збудували міст після Війни Трьох Молотів, щоб розвивати торгівлю, дипломатію й міцні зв'язки зі своїми родичами-Вайлдгаммерами, що жили на півночі за каньйоном.",al={"хто збудував міст тандол","історія тандола","навіщо збудували"}},{q="Чи переходили тут війська під час Другої війни?",a="Так. Хоча Стара Орда оминула мости, вдершись у Лордерон морем, згодом сер Андуїн Лотар повів через Міст контрнаступ Альянсу, щоб відкинути орків назад у Каз Модан.",al={"друга війна міст тандол","орки на мосту тандол","лотар міст тандол"}}},fp="12,349,18.687.0,26.422.0,25.167.0,33.175.0,42.182.0,44.204.0"}
P.entries["subzone:the-den"] = {n="Лігво",s="Лігво — захищена печера в серці Долини Випробувань на південному заході Дуротару. Головна опорна база для молодих шукачів пригод з орків і тролів, вона дає бойову та магічну підготовку, перш ніж вони вирушать у широкий світ.",h="Лігво — захищена печера в серці Долини Випробувань на південному заході Дуротару.",kw={"лігво","печера","долина випробувань","новобранці","наставники","ґорнек","дуротар"},ang={["race:Orc"]="Кожен молодий орк починає свій шлях у Лігві, скидаючи заціпеніння таборів для інтернованих і кривавого мороку, щоб заслужити своє місце дисципліною і працею.",["race:Troll"]="Після спустошення Островів Темного Списа молоді тролі Темного Списа навчаються в Лігві пліч-о-пліч із союзниками-орками, доводячи свою вправність під прапором Орди."},sec={{t="Колиска Орди",b="Сховане в червоних стінах каньйону Долини Випробувань, Лігво служить суворим полігоном. У його висіченому в скелі сутінковому нутрі бійці, чаклуни й мисливці-новачки з'являються до ветеранів на кшталт Ґорнека та Зуріти Фарґейз. Саме тут пташенята отримують перші бойові настанови, припаси та початкові обряди посвяти, які гартують їх до суворої дійсності Дуротару й більших випробувань, що чекають на нову Орду."},{t="Пильна застава",b="Окрім того, що тут розмістилися наставники класів і припаси, Лігво працює як діючий польовий редут. Посилаючи новобранців винищувати місцеву звірину та войовничих шипогривів, наглядачі водночас тримають долину під суворим і пильним наглядом."}},faq={{q="Для чого потрібне Лігво?",a="Лігво — головний командний пункт і тренувальний прихисток у Долині Випробувань. Тут орки й тролі Темного Списа, що лише починають свій шлях, опановують основи свого класу, купують припаси й отримують доручення, які доводять їхню вірність Орді й готовність до бою.",al={"що таке лігво","чому лігво тут","призначення лігва"}},{q="Хто керує в Лігві?",a="Табором опікуються досвідчені наглядачі, як-от Ґорнек і Наглядач Тазз'ріл, а також духовні й чарівні наставники на кшталт Зуріти Фарґейз і Канаґи Ерткаллер — разом вони навчають нове покоління воїнів і містиків.",al={"хто керує лігвом","хто головний","наглядач лігва"}},{q="Чи можна тут навчитися основних ремесел?",a="Ні. У Лігві є лише наставники класів і звичайні крамарі зі спорядженням. Новачкам доведеться податися на північ — до Гострого Пагорба чи далі до Оргріммара, — щоб опанувати основні ремесла, як-от Ковальство, Шкіряну справу чи Гірничу справу.",al={"наставники професій лігво","чи можна вивчити ковальство","навчання гірництва в лігві"}}},fp="7,253,19.447.0,18.241.0,31.278.0,31.254.0,39.223.0"}
P.entries["subzone:the-loch"] = {n="Озеро",s="Озеро — величезна прісна водойма, що панує в долині Лох Модан. Його стримує монументальна Каменетесна Гребля; це найбільша водойма Каз Модану й життєва сила довколишніх дворфійських поселень.",h="Озеро — величезна прісна водойма, що панує в долині Лох Модан.",kw={"озеро","лох модан","каменетесна гребля","трешадони","телсамар"},ang={["faction:Alliance"]="Спокійні води Озера дають прісну воду й торгові шляхи між центральною долиною Айронфорджа й довколишніми заставами.",["race:Dwarf"]="Озеро — предмет гордощів Айронфорджа: воно показує, як дворфійське каменярство й Каменетесна Гребля можуть приборкати природу, щоб живити поселення на кшталт Телсамара."},sec={{t="Серце долини",b="Озеро, що займає середину Лох Модану, — одне з найбільших внутрішніх озер відомого світу; змагатися з ним можуть хіба Озеро Лордамер і Озеро Дарроумер на півночі. Його води годують місцевих рибалок і правлять за мирне тло для містечка Телсамар і ближніх мисливських хуторів. Проте під спокійною поверхнею никають агресивні трешадони й прісноводні хижаки, тож перепливати його небезпечно."},{t="Каменетесна перепона",b="Озеро має свій нинішній спокійний вигляд завдяки майстерній дворфійській інженерії. На півночі стоїть величезна Каменетесна Гребля — архітектурне диво, зведене поперек гірської ущелини, щоб озеро не вилилося в Багнокрай унизу. Утримувати цю колосальну споруду конче потрібно, щоб зберегти природу долини й безпеку Каз Модану."}},faq={{q="Що таке Озеро?",a="Озеро — величезне гірське озеро, що заповнює центр долини Лох Модан у Каз Модані. Це одна з найбільших прісних водойм світу, і від неї залежать і краєвид, і життя місцевих дворфів.",al={"лор озера","що за озеро","озеро лох модан"}},{q="Чому озеро не міліє?",a="З півночі озеро стримує Каменетесна Гребля — височенна дворфійська споруда. Вона тримає незліченні галони води, які інакше ринули б униз гірським перевалом у низинний Багнокрай.",al={"чому озеро не міліє","що тримає озеро","призначення каменетесної греблі"}},{q="Чи безпечно купатися в Озері?",a="Не зовсім. На березі й помостах повно місцевих рибалок, але в глибших водах живуть хижі трешадони й клацаючі звірі, що часто нападають на необачних мандрівників, які запливають далеко від берега.",al={"монстри озера","купання в озері","істоти озера"}},{q="Наскільки велике Озеро порівняно з іншими озерами?",a="Це найбільша водойма континенту Каз Модан і третє за величиною відоме озеро Східних Королівств — після Озера Лордамер та Озера Дарроумер у Лордероні.",al={"найбільше озеро","розмір озера","наскільки велике озеро"}}},fp="8,227,19.414.0,24.373.0,17.221.0,28.225.0,31.194.0,46.181.0"}
P.entries["subzone:thelgen-rock"] = {n="Камінь Тельґен",s="Камінь Тельґен — розлога мережа печер, урізана в південну гірську стіну Багнокраю. Вона кишить отруйними павуками й славиться рідкісними жилами нестійкої Інцендицитової Руди.",h="Камінь Тельґен — розлога мережа печер, урізана в південну гірську стіну Багнокраю.",kw={"камінь тельґен","інцендицитова руда","павуки","печери","лох модан","багнокрай"},ang={["profession:Mining"]="Глибокі тунелі Каменя Тельґен ховають рідкісні поклади Інцендицитової Руди, що вабить рудошукачів у небезпеку під горою."},sec={{t="Печера, заплетена павутинням",b="Камінь Тельґен, що тулиться до південних гір між Багнокраєм і Лох Моданом, — глибока підземна мережа печер, яку заполонили агресивні павуки. Проходи густо заплетені павутинням і кишать отруйними павуками, тож потрапити в печери вкрай небезпечно. Попри навалу, гірники й шукачі пригод спускаються в її глибини заради цінних покладів Інцендицитової Руди, вкраплених у скелясті тунелі."}},faq={{q="Чим небезпечний Камінь Тельґен?",a="У печерах Каменя Тельґен повно великих отруйних павуків. Мандрівники, що заходять у звивисті тунелі, легко можуть опинитися в пастці серед павутиння й загинути від отруйних укусів.",al={"небезпеки каменя тельґен","чому камінь тельґен небезпечний","павуки каменя тельґен"}},{q="Навіщо сюди приходять шукачі й рудокопи?",a="У печерах є багаті поклади Інцендицитової Руди — вогненного, нестійкого мінералу, який шукають дворфійські шукачі й інженери. Попри павучу навалу, відважні рудокопи заходять усередину, щоб добути зразки зі стін печери.",al={"навіщо йти до каменя тельґен","руда каменя тельґен","руда інсендіциту"}},{q="Де розташований Камінь Тельґен?",a="Камінь Тельґен лежить уздовж південного гірського кряжа Багнокраю, на південь від головної дороги, що сполучає Гавань Менетіл із гірським перевалом Дун Алґаз.",al={"розташування каменя тельґен","де камінь тельґен"}}},fp="12,197,19.443.0,34.212.0,40.227.0,30.153.0"}
P.entries["subzone:thelsamar"] = {n="Телсамар",s="Телсамар — головне дворфійське поселення Лох Модану, що притулилося на західних кручах над великим озером. Розташоване на головній дорозі між Дун Мороґом і Багнокраєм, воно слугує гамірним осередком торгівлі, гостинності й громадської оборони від трогів і огрів, що наступають довкола.",h="Телсамар — головне дворфійське поселення Лох Модану, що притулилося на західних кручах над великим озером.",kw={"телсамар","лох модан","корчма міцний лагер","горяни","дворфи","долина кам'яного уламка"},ang={["profession:Cooking"]="Кулінари часто зупиняються в Корчмі «Міцний Лагер», щоб вивчити місцевий рецепт ситних кров'янок із м'яса тутешніх ведмедів, павуків і вепрів.",["race:Dwarf"]="Для дворфів, що покидають холодний Дун Мороґ, Телсамар — перший смак тепліших низин: чудовий ель, міцні кам'яні вогнища й служба в лавах горян."},sec={{t="Серце Лох Модану",b="Телсамар — головний оплот мирного дворфійського життя в долині. Збудований із традиційного для Каз Модану каменю й дерева, він має жваву Корчму «Міцний Лагер», сідало грифонів, ремісничі майстерні й чимало крамарів. Оскільки містечко стоїть просто на шляху, що з'єднує Прохід Південної Брами до Дун Мороґу з Перевалом Алґаз до Багнокраю, майже всі мандрівники краю проходять під його теплими вогнищами й міцними дахами."},{t="Біда на прикордонні",b="Попри затишок, Телсамар у постійній небезпеці. На півдні троги, що сунуть із Долини Кам'яного Уламка, загрожують околицям містечка, а на Хребті Сивої Лапи никають ведмеді й хижі звірі. Регулярні війська Айронфорджа розпорошені по всьому королівству, тож місцевий магістрат і горяни дуже покладаються на мандрівних шукачів пригод і найманців, щоб патрулювати торгові шляхи й відбивати ворогів, що підступають."}},faq={{q="Які послуги є в Телсамарі?",a="Телсамар пропонує все, що потрібно на прикордонні: Корчму «Міцний Лагер» для нічлігу й підкріплення, розпорядника польотів зі сполученням по всьому центральному Каз Модану, крамарів і кузню просто неба. Тут є також кілька наставників ремесел і бою для шукачів пригод, що набираються досвіду.",al={"торговці телсамара","що є в телсамарі","наставники телсамара"}},{q="Куди веде дорога через Телсамар?",a="Дорога з півночі на південь, що йде на захід від містечка, на півдні веде тунелем у Дун Мороґ, просто до Айронфорджа. А якщо йти нею на північ, вона виведе мандрівників крізь Браму Алґаз у болотистий Багнокрай.",al={"дорога телсамара","куди веде шлях","подорож із телсамара"}},{q="Чому містечко наймає стільки найманців?",a="Місцеві горяни не дають ради кільком новим загрозам. Агресивні троги Кам'яного Уламка заполонили південні розкопки, на околицях поселення нишпорять дикі звірі, а організовані огри почали тиснути дедалі сильніше, тож влада містечка мусить оголошувати винагороди для вільних бійців.",al={"чому в телсамарі завдання","хто нападає на телсамар"}},{q="Яка тутешня страва найславетніша?",a="Містечко славиться серед мисливців і мандрівників Кров'яними ковбасками Телсамара — ситною дворфійською стравою, яку готує Відра Гартстоув у Корчмі «Міцний Лагер» із тельбухів і м'яса місцевих звірів.",al={"їжа телсамара","кривава ковбаса лох модан"}}},fp="9,303,19.471.0,23.430.0,41.290.0,43.220.0,43.293.0,40.198.0"}
P.entries["subzone:theramore-isle"] = {n="Острів Терамор",s="Острів Терамор — добре укріплена людська портова цитадель біля східного узбережжя Багна Пилоброду. Його заснувала Леді Джайна Праудмур для біженців, що врятувалися від загибелі Лордерону, і нині це головний бастіон Альянсу на півдні Калімдору.",h="Острів Терамор — добре укріплена людська портова цитадель біля східного узбережжя Багна Пилоброду.",kw={"острів терамор","джайна праудмур","альянс","багно пилоброду","дейлін праудмур","кул тірас","третя війна"},ang={["class:Mage"]="Як особисті володіння архімагині Джайни Праудмур, Терамор має потужні канали таємної магії й слугує важливим осередком традицій Кірін-Тору та телепортації в західній півкулі.",["faction:Alliance"]="Острів Терамор — головний осередок влади Альянсу в центральному Калімдорі: безпека, важливі поромні сполучення й добре захищена гавань серед ворожої глушини."},sec={{t="Притулок на Заході",b="Після того як Погибель під час Третьої війни спустошила Даларан і Лордерон, Леді Джайна Праудмур повела флот уцілілих через Велике Море до берегів Калімдору. Здолавши Палаючий Легіон на Горі Гіджал пліч-о-пліч з орками й нічними ельфами, її союз людей, дворфів і високих ельфів відступив до туманних околиць Багна Пилоброду. На скелястому острові неподалік берега вони збудували Острів Терамор — квітуче портове місто під захистом високих кам'яних мурів і особистої цитаделі Джайни, створене, щоб уберегти те, що лишилося від північних королівств."},{t="Неспокійний мир",b="Історія Терамору сповнена напруги з сусідньою Ордою Тралла в Дуротарі. Коли великий адмірал Дейлін Праудмур прибув із флотом Кул Тірасу, він захопив острів і розв'язав неспровоковану кампанію, щоб винищити орків. Не бажаючи, щоб ненависть зруйнувала мир, який так тяжко дістався Калімдору, Джайна відступила вбік і дозволила Орді вбити свого батька в мурах Терамору, аби зберегти мир. Нині місто тримає крихке перемир'я з Дуротаром, хоча прихована образа серед моряків-ветеранів і таємні підбурювання культу Палаючого Клинка загрожують розірвати цю делікатну угоду."}},faq={{q="Хто править Островом Терамор?",a="Островом Терамор править Леді Джайна Праудмур. Видатна чарівниця родом із Даларану й Кул Тірасу, під час Третьої війни вона привела вцілілих із Лордерона до Калімдору й тепер опікується і військовою обороною міста, і його дипломатичними зв'язками.",al={"хто править терамором","правитель терамора","джайна терамор"}},{q="Чому люди збудували місто серед болота?",a="Після Битви за Гору Гіджал уцілілій людській експедиції потрібна була зручна для оборони прибережна позиція, щоб дати прихисток своєму народові й утримувати флот. Скелястий острів біля Багна Пилоброду мав глибоководну гавань і природну відокремленість від загроз із суходолу, тож став ідеальною твердинею, попри жалюгідне болото довкола.",al={"чому терамор у болоті","чому пилотрясина","чому збудували тут"}},{q="Чи ворожий Терамор до Орди?",a="Терамор — твердиня Альянсу, тож його вартові одразу ворожі до мандрівників Орди. Проте офіційно Леді Джайна Праудмур і Вождь Тралл підтримують хиткий дипломатичний мир, шануючи межі одне одного, попри ненависть, що досі жевріє між їхніми народами.",al={"чи може орда в терамор","відносини терамора з ордою","чи люди терамора воюють"}},{q="Що сталося тут із Великим Адміралом Даліном Праудмуром?",a="Адмірал Далін Праудмур відібрав Терамор у своєї доньки Джайни, щоб воювати з молодою Ордою. Розуміючи, що його похід знищить їх усіх, Джайна відступила, дозволивши Траллу й Рекссару штурмувати острівну цитадель і вбити Адмірала в бою.",al={"смерть дейліна","що сталося з батьком джайни","дейлін праудмур терамор"}}},fp="14,243,18.596.0,15.611.1,25.247.0,39.330.0,34.284.0,54.262.0"}
P.entries["subzone:thistlefur-hold"] = {n="Твердиня Будякохутрих",s="Твердиня Будякохутрих — печерне лігво в північній частині Села Будякохутрих у західно-центральному Ашенвалі. Фурболги Будякохутрі, що живуть тут, колись були мирними ведмедями лісу, але піддалися скверні й нападають на кожного чужинця, який наближається.",h="Твердиня Будякохутрих — печерне лігво в північній частині Села Будякохутрих у західно-центральному Ашенвалі.",kw={"твердиня будякохутрих","фурболги","ідол ремулоса","руул сноугуф","печера","ашенваль"},ang={["class:Druid"]="Те, як фурболги Будякохутрі під впливом Ідола Ремулоса піддалися божевіллю, трагічно нагадує, як легко в Ашенвалі можна зіпсувати охоронців природи.",["faction:Horde"]="Для Орди лігво — це водночас і рятувальна операція, і пошук награбованого: воїни мають проникнути всередину, щоб звільнити Руула Сноугуфа й повернути вкрадені тролячі обереги."},sec={{t="Осквернене лігво",b="Твердиня Будякохутрих, що ховається в північній частині Села Будякохутрих, — серце володінь племені. Тутешні фурболги збожеволіли, відколи до їхніх рук потрапив Ідол Ремулоса, і впали у звірячу лють, що робить їх небезпечними і для мандрівників, і для сусідів. Глибоко у звивистих печерах плем'я тримає награбовані реліквії — зокрема тролячі обереги, що цікавлять Темний Спис, — а також бранців у дерев'яних клітках, як-от ув'язненого тауренського воїна Руула Сноугуфа."}},faq={{q="Що таке Твердиня Будякохутрих?",a="Твердиня Будякохутрих — підземний печерний комплекс у північному кінці Села Будякохутрих, у західній частині центрального Ашенвалю. Тут живе найбільше ворожих фурболгів із племені Будякохутрих.",al={"інформація про твердиню будякохутрих","що це за печера","печера будякохутрих"}},{q="Чому фурболги у Твердині Будякохутрих ворожі?",a="Фурболгів Будякохутрих спотворив Ідол Ремулоса — артефакт, який вони зберігали в себе. Його лиховісний вплив затьмарив їм розум і змусив кидатися на всіх чужинців.",al={"чому будякохутрі злі","скверна будякохутрих","чому фурболги нападають"}},{q="Хто ув'язнений у твердині?",a="Руул Сноугуф, молодий таурен-воїн, потрапив у полон до племені Будякохутрих. Він сидить замкнений у дерев'яній клітці глибоко в печерах і чекає, поки його визволять герої Орди.",al={"бранець будякохутрих","таурен у твердині будякохутрих","хто такий рул сніговиття"}},{q="Чому Орда цікавиться Твердинею Будякохутрих?",a="Орда хоче визволити полоненого таурена Руула Сноугуфа й повернути цінні тролячі обереги, які фурболги поховали в глибинах печери.",al={"завдання орди будякохутрих","тролячі амулети будякохутрих"}}},fp="15,256,15.531.0,24.193.0,48.200.0,31.160.0,47.153.0"}
P.entries["subzone:thistlefur-village"] = {n="Село Будякохутрих",s="Село Будякохутрих — розлоге поселення в лісі на північ від Астранаару, у західно-центральному Ашенвалі. Це головна домівка племені фурболгів Будякохутрих, які стали жертвою темної скверни й люто нападають на кожного чужинця, що наближається до їхніх лігв.",h="Село Будякохутрих — розлоге поселення в лісі на північ від Астранаару, у західно-центральному Ашенвалі.",kw={"село будякохутрих","фурболги","дал бладкло","рорґіш джаул","астранаар","ашенваль"},ang={["class:Druid"]="Занепад племені Будякохутрих похмуро нагадує про скверну, яка досі вражає духів і звірів Ашенвалю, тож Коло Кенарія мусить невтомно очищати край.",["race:NightElf"]="Століттями нічні ельфи жили в злагоді з місцевими племенами фурболгів. Тож бачити, як Будякохутрі піддаються лютій скверні так близько від Астранаару, для Вартових — і сердечний біль, і гостра загроза безпеці."},sec={{t="Оселя, поглинута скверною",b="Село Будякохутрих, що лежить трохи на північ від Астранаару — прихистку нічних ельфів, — колись було частиною мирних лісових громад, споконвічних для Ашенвалю. Проте зловісна скверна, що просочилася в прадавні ліси, цілком поглинула плем'я Будякохутрих. Тепер геть збожеволілі й украй ворожі фурболги люто стережуть стежки, що в'ються крізь їхнє поселення. Плем'я кориться двом надзвичайно лютим ватажкам — Далові Бладкло й Рорґішу Джаулу, чия невгамовна агресія становить постійну загрозу для мандрівників і ближніх поселень."}},faq={{q="Де розташоване Село Будякохутрих?",a="Село Будякохутрих лежить у західній частині центрального Ашенвалю, глибоко серед лісистих пагорбів, просто на північ від нічноельфійського містечка Астранаар.",al={"розташування села будякохутрих","де будякохутрі","будякохутрі на мапі"}},{q="Чому тутешні фурболги нападають на мандрівників?",a="Фурболгів Будякохутрих охопило темне спотворення, що шириться лісами Ашенвалю. Збожеволілі від цієї мерзенної сили, вони бачать ворога в кожному чужинці й нападають на всякого, хто наближається до їхніх земель.",al={"чому будякохутрі ворожі","зіпсовані фурболги будякохутрих","чому нападають"}},{q="Хто очолює фурболгів Будякохутрих?",a="Плем'я очолюють два особливо люті й жорстокі вожді-воїни, Дал Бладкло і Рорґіш Джаул. Вони тримають у залізному кулаці і село, і довколишні лігва.",al={"бос будякохутрих","лідери будякохутрих","хто веде будякохутрих"}},{q="Чи загрожує Село Будякохутрих Астранаару?",a="Так. Село лежить просто на північ від Астранаару, тож агресивні й непередбачувані спотворені фурболги постійно загрожують нічноельфійським розвідникам, обозам і вартовим на центральних дорогах.",al={"загроза будякохутрих астранаару","небезпека для астранаару"}}},fp="18,279,15.565.0,36.158.0,46.239.0,34.180.0,51.243.0"}
P.entries["subzone:thistlefuzz-arcanery"] = {n="Чародійня Тіслфаз",s="Чародійня Тіслфаз — відома майстерня й академія магічного мистецтва на схід від Великої Кузні в Айронфорджі. Її тримають переважно гноми, і це найкращий у столиці прихисток для зачаровувачів і вчених, що прагнуть вплітати магію в метал і пергамент. Її жваві покої гудуть чародійною енергією просто поруч із ревучими вогнями дворфійської промисловості.",h="Чародійня Тіслфаз — відома майстерня й академія магічного мистецтва на схід від Великої Кузні в Айронфорджі.",kw={"чародійня тіслфаз","айронфордж","зачарування","маги","гноми","магія"},ang={["class:Mage"]="Маги, що навідуються сюди, знайдуть звичні реагенти, тихі куточки для теоретичних роздумів і споріднених заклиначів посеред бойових, зброєю наповнених зал дворфійської столиці.",["race:Gnome"]="Для гномів, що живуть в Айронфорджі, Чародійня Тіслфаз — затишне нагадування про їхню любов до чародійної теорії, технічних студій і тонких дослідів посеред міста, де панує важке дворфійське залізо."},sec={{t="Чародійне ремесло в горі",b="Чародійня Тіслфаз, що тулиться одразу на схід від гуркітливої Великої Кузні, разюче контрастує з дзвоном ковадел дворфійських ковалів. На двох її поверхах збираються вчені, практики й учні, щоб опанувати тонкі дисципліни зачарування й магічних студій. Дворфи Айронфорджа воліють змінювати сталь м'язами й вогнем, а гноми Чародійні показують, як чисту чародійну енергію можна вплести просто у зброю, обладунки й дивовижні знаряддя. Це незамінний прихисток для заклиначів у гірській твердині."}},faq={{q="Де розташована Чародійня Тіслфаз?",a="Чародійня Тіслфаз стоїть на східному кільці Великої Кузні в центрі Айронфорджа. Її легко впізнати за магічними приладами й приладдям для накладання чарів біля входу.",al={"розташування чародійні","де тіслфаз","крамниця зачарувань айронфорджа"}},{q="Які послуги пропонує Чародійня?",a="Крамниця обслуговує майстрів магічних ремесел. Тут збираються наставники з накладання чарів, постачальники для чаротворців і вчені: вони навчають учнів, торгують рідкісними реагентами й ставлять досліди подалі від кіптяви кузень.",al={"що в чародійні тіслфаз","наставники тіслфаз"}},{q="Чому чародійна майстерня стоїть так близько до Великої Кузні?",a="Мати майстерню чарів просто біля Великої Кузні — дуже практично. Щойно викувані клинки, обладункові пластини й механічні деталі від дворфійських ковалів можна одразу віднести на схід і наділити захисними чарами та силою стихій.",al={"чому чародійня біля кузні","зв'язок чародійні з великою кузнею"}}},fp="20,374,28.565.0,38.185.0,46.231.0,63.264.0"}
P.entries["subzone:thistleshrub-valley"] = {n="Долина Будякових Кущів",s="Долина Будякових Кущів, що ховається на південному заході Танарісу, — химерна оаза колючої рослинності серед нескінченних дюн. Каньйон відомий дивним гаєм велетенських кактусів і ворожими ожилими будяковими кущами, що нападають на кожного, хто ступить на їхню порослу колючками територію.",h="Долина Будякових Кущів, що ховається на південному заході Танарісу, — химерна оаза колючої рослинності серед...",kw={"долина будякових кущів","кактуси","будякові кущі","травництво","танаріс","каньйон"},ang={["class:Druid"]="Друїдам люто ожилі будякові кущі можуть видатися захопливими: мимоволі постає питання, які первісні сили чи сили стихій підтримують їхнє буяння в цій безживній пустелі.",["profession:Herbalism"]="Для травників, що мандрують Танарісом, долина — справжня аномалія: тут серед густих гаїв колючих чагарів ростуть дивні й витривалі пустельні рослини."},sec={{t="Гай колючок",b="Більша частина Танарісу — посушлива пустка, геть позбавлена рослинності, але Долина Будякових Кущів на диво буяє життям. Велетенські квітучі кактуси височіють над дном каньйону й разюче контрастують із довколишнім морем піску. Проте це аж ніяк не мирна оаза. Долина отримала свою назву від ворожих живих рослинних створінь, що причаїлися в чагарях. Ці будякові кущі шмагають гострими, мов лезо, колючками кожного мандрівника, що наблизиться, тож пробиратися повз скелі до таємничої південної брами небезпечно."},{t="Вартові пустелі",b="Ожилі рослини в такому сухому кліматі здавна спантеличують мандрівників і пустельних знавців виживання. Хоч би що їх пробудило — забуті енергії стихій чи вперте пристосування до суворого клімату Танарісу, — будякові кущі лишаються вкрай затятими захисниками своєї території. Мандрівникам, що перетинають каньйон, доводиться мати справу не лише з цими розмаханими хащами колючок і коріння, а й із пустельними хижаками та отруйними зміями, що гніздяться серед височенних кактусів."}},faq={{q="Де розташована Долина Будякових Кущів?",a="Долина Будякових Кущів ховається в південно-західному куті Танарісу, затиснута під південним гірським хребтом біля таємничої запечатаної брами Ульдуму.",al={"розташування долини будякових кущів","де долина будякових кущів","знайти долину будякових кущів"}},{q="Чому в цій частині Танарісу стільки рослин?",a="На відміну від решти безплідної пустелі, долина має власний мікроклімат, де панують височенні кактуси й ожилі рослини. Як ці незвичайні будякові кущі так буйно розростаються в сухому пустельному піску — досі загадка південних дюн.",al={"чому тут стільки рослин","чому ростуть рослини"}},{q="Які істоти живуть у Долині Будякових Кущів?",a="Долину заполонили ворожі ходячі будякові кущі, агресивні пустельні квіти й усілякі отруйні плазуни, що ховаються під колючими заростями.",al={"моби долини будякових кущів","монстри долини будякових кущів"}},{q="Що це за величезна кам'яна споруда біля долини?",a="Одразу за долиною стоїть величезна запечатана споруда Титанів, яку часто називають брамою до Ульдуму. Для пустельних мандрівників вона й досі замкнена й загадкова.",al={"двері біля будякових кущів","брама титанів танаріс"}}},fp="19,294,17.559.0,23.453.0,37.153.0,56.254.0,43.162.0,52.160.0"}
P.entries["subzone:thondroril-river"] = {n="Річка Тондроріл",s="Річка Тондроріл — важливий природний кордон між Західними й Східними Чумними Землями. Вона бере початок у горах Північного Лордерона біля Тунелю Жахоппавутини, а її зачумлені води течуть на південь до Озера Дарроумер. Колись ця річка була жвавим торговим і подорожнім шляхом занепалого королівства, а тепер на її берегах никають жахливі звірі Погибелі й стоїть скромний притулок легендарного відлюдника.",h="Річка Тондроріл — важливий природний кордон між Західними й Східними Чумними Землями.",kw={"річка тондроріл","річка","тіріон фордрінг","озеро дарроумер","західні чумні землі","східні чумні землі"},ang={["class:Paladin"]="Східний берег Річки Тондроріл дає прихисток Тіріонові Фордрінгу — одному з батьків-засновників Срібної Длані, чия спадщина й досі відлунює попри вигнання.",["profession:Herbalism"]="Вогке, гниюче річище живить витривалі рослини, вражені чумою, як-от Сонцетрав'я, Сльози Артаса й Чумоцвіт, що ростуть біля каламутних берегів."},sec={{t="Річка, розітнута руїною",b="До падіння Лордерона Тондроріл був важливим водним шляхом, що з'єднував північні володіння зі Стратгольмом, а на півдні — з Озером Дарроумер. Нині річка позначає небезпечну межу між Західними й Східними Чумними Землями. Її води несуть заразу чуми, а на берегах кишать велетенські личинки, чумні кажани, хворі ведмеді й хижі черепахи-клацощелепи. Колись мальовниче річище стало смертельно небезпечною переправою для мандрівників."},{t="Вартові на березі",b="Хоч глушина вздовж Тондрорілу сувора й безжальна, надії вона не позбавлена цілком. На східному березі, у непримітній зарослій садибі, живе вигнаний паладин Тіріон Фордрінг. Багато років тому його позбавили титулів і змусили переховуватися, і тепер колишній лорд здалеку спостерігає за гниючою річкою та руїнами своєї батьківщини, випробовуючи силу й сумління шукачів пригод, яким досить завзяття, щоб перетнути зачумлене прикордоння."}},faq={{q="Де починається і де закінчується Річка Тондроріл?",a="Річка бере початок на висотах Північного Лордерона біля входу в Тунель Жахоппавутини, тече на південь через Чумні Землі й впадає просто в Озеро Дарроумер. За озером вона тече далі на південь уже як Річка Дарроумер.",al={"шлях річки тондроріл","куди тече тондроріл","витік тондроріла"}},{q="Які небезпечні істоти живуть на берегах річки?",a="Чума перетворила місцевих звірів на смертоносних потвор. Мандрівники раз у раз натрапляють на обох берегах на ненажерливих личинок, хворих чумних ведмедів, величезних кажанів-вампірів, склепових павуків і річкових черепах-кусак.",al={"монстри біля річки","моби тондроріла","загрози річки"}},{q="Хто цей старий, що живе на східному березі?",a="Самітник у напівзруйнованому фермерському будинку на східному березі — Тіріон Фордрінг, один із перших Лицарів Срібної Длані. Вигнаний з Альянсу ще за кілька років до Третьої війни, він живе в тихій самоті й стежить за Погибеллю.",al={"хто біля річки","старий відлюдник тондроріла","видавець завдань тондроріла"}},{q="Чому річка розділяє дві Чумні Землі?",a="Тондроріл прорізав широку природну ущелину через центральний Лордерон. Коли королівство стало землею Погибелі, картографи й уцілілі почали вважати річку чіткою межею між Західними та Східними Чумними землями.",al={"західний і східний кордон","межа чумних земель"}}},fp="16,386,19.461.0,20.446.1,46.248.0,51.217.0,47.240.0,46.241.0"}
P.entries["subzone:thoradin-s-wall"] = {n="Мур Торадіна",s="Мур Торадіна — величезний кам'яний вал, що поволі розсипається; він відокремлює Аратійське нагір'я від Передгір'я Гілсбреда. Його звелів збудувати тисячоліття тому король Торадін на світанку Імперії Аратор, щоб захистити перших людей від лютих набігів тролів Амані.",h="Мур Торадіна — величезний кам'яний вал, що поволі розсипається; він відокремлює Аратійське нагір'я від...",kw={"мур торадіна","торадін","аратор","тролі амані","стром","гілсбред","аратійське нагір'я"},ang={["race:Human"]="Стояти перед муром — урочиста зустріч із людською старовиною: це досі міцна кладка короля Торадіна, який першим об'єднав розпорошені людські племена.",["race:Troll"]="Зруйновані укріплення — сувора згадка про прадавні війни за землі, у яких людство зуміло зупинити панування лісових тролів."},sec={{t="Твердиня давнього Аратора",b="Зведений майже три тисячі років тому, Мур Торадіна позначає західний кордон давнього Строму — серця першої об'єднаної людської імперії. Король Торадін розумів, що молоді людські поселення вкрай вразливі до хижих набігів лісових тролів Амані. Звівши цей величезний кам'яний бар'єр через долину, Аратор захистив свої серцевинні землі й виковав оплот, де людство змогло вижити, а згодом і кинути виклик пануванню тролів на півночі."},{t="Століття занепаду",b="Нині прадавній мур геть занедбаний. Кам'яні вали розтинають величезні проломи, а зубці стерлися за тисячі років негоди, воєн і забуття. Відколи Аратор розпався на суперницькі королівства, а сусідній Лордерон зрештою впав під ударами Погибелі, кладку не доглядає жодна держава. Тепер мандрівники й бродячі розбійники вільно прослизають крізь зруйновані арки на шляху між Гілсбредом і диким Аратійським нагір'ям."}},faq={{q="Хто збудував Мур Торадіна?",a="Мур звели за наказом короля Торадіна — засновника й полководця, який майже три тисячоліття тому об'єднав людські племена й заснував імперію Аратор.",al={"хто збудував мур торадіна","творець муру торадіна","походження муру торадіна"}},{q="Навіщо взагалі збудували мур?",a="Король Торадін наказав звести його, щоб захистити першу людську столицю, Стром, і молоді поселення від лютих набігів сусідньої тролячої імперії Амані.",al={"призначення муру торадіна","навіщо збудували мур","для чого мур торадіна"}},{q="Чому мур сьогодні такий зруйнований?",a="Мур тисячі років нищили негода, війни й занедбаність. Коли імперія Аратор розпалася на незалежні людські королівства, велике прикордонне укріплення втратило стратегічне значення, і його покинули напризволяще.",al={"чому мур зламаний","хто зруйнував мур торадіна","чому в руїнах"}},{q="Які краї розділяє Мур Торадіна?",a="Мур утворює природний суходільний кордон між зеленими Передгір'ями Гілсбреда на заході й суворим Аратійським нагір'ям на сході.",al={"де мур торадіна","що розділяє мур","межа муру торадіна"}}},fp="15,288,28.497.0,18.490.0,26.154.0,42.172.0,37.241.0,43.140.0"}
P.entries["subzone:thorium-point"] = {n="Торієвий Мис",s="Торієвий Мис, що примостився на північних кручах Палючої Ущелини, — головний табір Братства Торію. З цієї нейтральної застави дворфи Темного Заліза, які відкололися від свого клану, наймають мандрівних шукачів пригод і завдають ударів у відповідь своїм родичам-тиранам, що засіли в глибині вулканічного згарища.",h="Торієвий Мис, що примостився на північних кручах Палючої Ущелини, — головний табір Братства Торію.",kw={"торієвий мис","братство торію","палюча ущелина","ковальство","темне залізо","нейтральний табір"},ang={["profession:Blacksmithing"]="Тутешні ковалі Темного Заліза знають ремісничі таємниці, яких прагнуть майстри по металу з усього світу, і діляться рідкісними кресленнями з тими, хто постачає їм вулканічну руду та складники.",["race:Dwarf"]="Дворфи Темного Заліза, які не намагаються вас одразу вбити, — неабияка рідкість. Проте мандрівники з клану Бронзбірда знають: цими вигнанцями рухає лише ремесло й бажання вижити, а не любов до Айронфорджа."},sec={{t="Плацдарм над попелом",b="Торієвий Мис, звідки видно випалені шлакові купи Палючої Ущелини, — скромний гірський табір, збудований з потреби. Тримає його Братство Торію — ренегатське угруповання дворфів Темного Заліза, що розірвало зв'язки зі своїми поневоленими братами в Місті Тінькузні. Не бажаючи схилятися ні перед Володарем вогню, ні перед Імператором Даґраном Тауріссаном, ці вигнанці мають кузню просто неба, жвавого розпорядника польотів і добре захищений периметр на північний схід від Хребта Вогняної Варти. Через відчайдушну боротьбу за виживання й прагнення вершин ковальського мистецтва Братство відкрило табір і для Альянсу, і для Орди: тут раді кожному, хто готовий видобувати руду з попелу чи трощити черепи дворфам Темного Заліза."},{t="Перепочинок для мандрівців",b="Торієвий Мис — не лише плацдарм для війни Братства з власними родичами, а й незамінне роздоріжжя в самому серці гірського пасма Редрідж. Табір безпечно височіє над ненажерливими павуками й вогняними елементалями, що нишпорять вулканічною улоговиною, і пропонує прямі польоти до великих міст, як-от Айронфордж і Стормвінд, а також до передових таборів у Пустищах, Палаючих Степах і далі. Для мандрівних найманців, рудошукачів і ремісників, які прагнуть здобути потаємну прихильність дворфійських майстрів-ковалів, цей задимлений скельний виступ — найбезпечніше вогнище в усій Ущелині."}},faq={{q="Хто контролює Торієвий Мис?",a="Заставою володіє Братство Торію — гурт дворфів Темного Заліза, які відкололися від своїх, відкинули владу вогняного імператора й прагнуть самі кувати свою долю, вільні від служіння стихіям.",al={"хто керує торієвим мисом","власник торієвого мису","хто живе на торієвому мисі"}},{q="Чому Торієвий Мис нейтральний і до Альянсу, і до Орди?",a="Братство Торію значно поступається числом ворожим родичам із Темного Заліза та звірам Палючої Ущелини. Наживати ворогів серед мандрівних шукачів пригод воно не може, тож вільно торгує й наймає найманців, хоч би якій фракції ті служили.",al={"чому орда може на торієвий мис","чи нейтральний торієвий мис","альянс і орда торієвий мис"}},{q="Які послуги доступні на Торієвому Мисі?",a="У таборі є розпорядники польотів із маршрутами до Каз Модану, Стормвінда й Лордерона, а ще прості торговці, робоча кузня з ковадлом і місцеві доручення проти дворфів Темного Заліза.",al={"політ торієвого мису","що на торієвому мисі","торговці торієвого мису"}},{q="Де саме в Палючій Ущелині розташований Торієвий Мис?",a="Він примостився біля північної скелястої стіни Палючої Ущелини, високо на північний схід від Хребта Вогняної Варти, і звідти видно дно кальдери.",al={"як знайти торієвий мис","розташування торієвого мису","де торієвий мис"}}},fp="13,297,24.703.0,26.603.0,27.202.0,60.250.0,45.198.0,48.134.0"}
P.entries["subzone:three-corners"] = {n="Три Кути",s="Три Кути — важливе роздоріжжя одразу за західним кордоном Гір Редріджу. Звідси дороги розходяться до трьох сусідніх містечок — Ґолдшира, Лейкшира й Даркшира, — і саме тут пролягає межа між серцем королівства та небезпечною дикою місцевістю Редріджу. Над перехрестям стоїть сторожова вежа Вартових Стормвінда, що стримує навалу зграй гнолів.",h="Три Кути — важливе роздоріжжя одразу за західним кордоном Гір Редріджу.",kw={"три кути","роздоріжжя","вартова вежа","гори редріджу","гноли"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що покидають відносно безпечний Ліс Елвінн, Три Кути — перша укріплена застава й суворе нагадування про те, як слабко Стормвінд тримає свої прикордонні землі.",["race:Human"]="Сторожова вежа пов'язує південні людські землі й служить важливим вузлом для гінців і торгівлі між Елвінном, Сутінколіссям і Редріджем."},sec={{t="Роздоріжжя трьох містечок",b="Розташовані на західному краю Гір Редріджу, Три Кути з'єднують три ключові поселення Альянсу: Ґолдшир у Лісі Елвінн на заході, Лейкшир на північному сході й Даркшир у Сутінколіссі на півдні. Через це стратегічне роздоріжжя Стормвінд звів посеред перехрестя Вартову Вежу. Місцеві вартові й розвідники, що несуть тут службу, намагаються очистити шляхи від агресивних гнолів Редріджу, які постійно загрожують мандрівникам і возам із припасами між краями."}},faq={{q="Чому це місце називається Три Кути?",a="Тут дорога розходиться на три шляхи до «трьох ширів» південного Стормвінда: Ґолдшира в Лісі Елвінн, Лейкшира в Редріджі та Даркшира в Сутінколіссі.",al={"походження назви три кути","чому три кути","історія трьох кутів"}},{q="Хто охороняє вежу на Трьох Кутах?",a="Заставу, відому як Вартова Вежа, тримають вартові Стормвінда. Вона слугує постом раннього попередження й оплотом проти гнолів, які спускаються з вершин Редріджу до кордону Елвінна.",al={"хто контролює три кути","охорона вежі","хто у вежі"}},{q="Які загрози чатують біля Трьох Кутів?",a="Гноли з довколишніх пагорбів постійно нишпорять уздовж дороги й нападають із засідок на мандрівників і гінців. Тутешні вартові раз у раз просять перехожих шукачів пригод проріджувати зграї гнолів, щоб дорогою можна було пройти.",al={"монстри трьох кутів","небезпеки трьох кутів","гноли трьох кутів"}}},fp="13,386,28.513.0,39.182.0,38.217.0,45.216.0"}
P.entries["subzone:thunder-axe-fortress"] = {n="Фортеця Громової Сокири",s="Фортеця Громової Сокири — укріплений комплекс у північно-західному Пустограї, твердиня демонічного культу Палаючого Клинка. У її кам'яних казармах, сторожових вежах і похмурих печерах культисти проводять темні ритуали, щоб викликати демонічних істот, і зберігають викрадені артефакти сили. Культ і досі загрожує кожному, хто перетинає ці безлюдні пустирі.",h="Фортеця Громової Сокири — укріплений комплекс у північно-західному Пустограї, твердиня демонічного культу...",kw={"фортеця громової сокири","пустограй","палаючий клинок","рука іруксоса","скіпетр світла","азор алдаморт","культисти"},ang={["class:Warlock"]="Експерименти Палаючого Клинка у фортеці показують, як далеко заходить безрозсудна демонологія — від підкорення нижчих демонів до силового відкриття розломів між площинами для могутніших істот.",["faction:Alliance"]="Розвідка у Фортеці Громової Сокири збігається із зусиллями Срібного світанку вберегти небезпечні артефакти на кшталт Скіпетра Світла, перш ніж культисти Скверни обернуть їх проти континенту."},sec={{t="Бастіон Палаючого Клинка",b="Фортеця Громової Сокири, що стоїть у північно-західному Пустограї, — пильно охоронюваний редут Палаючого Клинка. Кам'яні казарми, оборонні вежі й глибокі печери дають культу змогу тримати укріплену опору далеко від очей великих міст Калімдору. Тут культисти збирають енергію Скверни, викликають нижчих демонів і виношують задуми, як привести у світ значно небезпечніших істот."},{t="Викрадені реліквії й темні призови",b="У фортеці культ зберігає Руку Іруксоса — реліквію, пов'язану з демонічними порталами Шабашу Маннорока. А на одній зі сторожових веж провидець Палаючого Клинка вивчає викрадений Скіпетр Світла. Азор Алдаморт просить мандрівників повернути скіпетр, який, за чутками, забрали в наг."}},faq={{q="Хто контролює Фортецю Громової Сокири?",a="Фортецею володіє культ Палаючого Клинка — організація, віддана демонічній силі й залишкам Ради Тіней. На місці фортецею та її справами керують чорнокнижники, як-от Тираніс Малем.",al={"хто керує фортецею громової сокири","хто у фортеці громової сокири","бос фортеці громової сокири"}},{q="Що таке Скіпетр Світла?",a="Скіпетр Світла — стародавній артефакт, який, кажуть, здатен потопити в морі цілі міста. Азор Алдаморт просить мандрівників забрати його в провидця Палаючого Клинка, що вивчає скіпетр на вершині однієї з вартових веж фортеці.",al={"скіпетр світла","скіпетр світла наги","викрадений артефакт наг"}},{q="Як ця фортеця пов'язана із Шабашем Маннорока?",a="Культисти у Фортеці Громової Сокири тримають артефакт, відомий як Рука Іруксоса. Ця реліквія була безпосередньо пов'язана з демонічними порталами Шабашу Маннорока на півдні Пустограю й поєднувала демонічні задуми культу по всьому краю.",al={"зв'язок із шабашем маннорока","рука іруксоса"}}},fp="20,359,30.415.0,33.304.1,34.223.0,29.221.1,49.232.0"}
P.entries["subzone:thunder-bluff"] = {n="Тандер Блаф",s="Тандер Блаф — високо піднесена столиця тауренів, що здіймається на сотні футів над пагорбистими рівнинами Малгору. Заснований Кайрном Бладгуфом після Третьої війни, він служить об'єднаним прихистком і культурним серцем народу, який поколіннями кочував.",h="Тандер Блаф — високо піднесена столиця тауренів, що здіймається на сотні футів над пагорбистими рівнинами...",kw={"тандер блаф","столиця","таурени","кайрн бладгуф","малгор","плато","ґрімтотем","озерця видінь"},ang={["faction:Horde"]="Тандер Блаф дає Орді неодмінний бастіон у південному Калімдорі — надійний якір мудрості й ресурсів поруч з орківським Оргріммаром.",["race:Tauren"]="Для тауренів Тандер Блаф — перший справжній постійний дім після поколінь мандрів; тут їхні священні тотеми, духовні оселі й найвеличніші вожді."},sec={{t="Прихисток на плато",b="Незліченні покоління таурени жили кочовиками центрального Калімдору, яких раз у раз шарпали жорстокі загони кентаврів. Та доба втечі скінчилася під час Третьої війни, коли Кайрн Бладгуф уклав союз честі з Вождем Траллом і Новою Ордою. Разом вони відкинули кентаврську загрозу й зайняли родючі трави Малгору. Кайрн зібрав розпорошені племена й заснував Тандер Блаф на вершинах низки розлогих природних кам'яних плато. Нині місто з'єднане запаморочливими мотузяними мостами, а потрапити до нього можна хитромудрими дерев'яними підйомниками; воно дає і цілковитий захист, і жвавий осередок торгівлі та духовних зібрань."},{t="Єдність і туман, що згущується",b="Хоч Тандер Блаф і стоїть маяком злагоди, на його височинах живуть різні угруповання. Більшість племен шанує мудрість Кайрна Бладгуфа, та серед традиціоналістів, як-от Маґата Ґрімтотем та її рід на Узвишші Старійшин, тихо тліє незгода. Глибоко під поверхнею міста лежать підземні Озерця Видінь, де духоходці й шамани вдивляються у волю предків. Попри приховане суперництво племен, Тандер Блаф лишається справжньою духовною опорою Орди в Калімдорі: він приймає мисливців, що повертаються з Пусток, мандрівних ремісників і друїдів, які єднаються із Земною Матір'ю."}},faq={{q="Як мандрівники піднімаються до Тандер Блафа?",a="До міста дістаються величезними дерев'яними підйомниками на канатах і блоках, що стоять на південно-західній і північно-східній кручах, або прилітають просто на сідало вітряних вершників на вершині центральної столової гори.",al={"ліфт тандер блафа","як піднятися до тандер блафа","вхід у тандер блаф"}},{q="Чому таурени збудували місто на скелях?",a="Після століть безжальних набігів кентаврів на відкритій рівнині Кайрн Бладгуф обрав височенні кам'яні столові гори, щоб дати своєму кочовому народові неприступний прихисток над священними пасовиськами Малгору.",al={"чому місто на скелях","чому на висоті","оборона тандер блафа"}},{q="Хто править Тандер Блафом?",a="Тандер Блаф очолює Верховний Вождь Кайрн Бладгуф. Він об'єднав розпорошені племена й приніс мир у Малгор, а править, радячись із вождями племен і старійшинами з усіх пагорбів.",al={"лідер тандер блафа","хто вождь","кайрн тандер блаф"}},{q="Чи всі племена тауренів вірні Кайрну?",a="Переважна більшість шанує мудрість Кайрна, проте деякі — передусім плем'я Ґрімтотем на чолі зі старою відьмою Маґатою — сумніваються в союзі з Ордою й шукають для тауренів власного шляху.",al={"ґрімтотеми тандер блаф","племена тандер блафа","політичні суперники тавренів"}}},fp="13,279,23.664.0,25.602.0,41.205.0,46.220.0,24.188.0,38.215.0"}
P.entries["subzone:thunder-falls"] = {n="Громові водоспади",s="Громові водоспади — відлюдна гірська ущелина, схована серед північно-західних височин Лісу Елвінн. Затиснута між прямовисними скелями й живлена ревучими каскадами, вона приховує тиху хатину над річкою, що потрапила до рук місцевих розбійників.",h="Громові водоспади — відлюдна гірська ущелина, схована серед північно-західних височин Лісу Елвінн.",kw={"громові водоспади","водоспад","ущелина","хатина","розбійники","дзеркальне озеро","ліс елвінн"},sec={{t="Прихована гірська западина",b="Сховані серед зубчастих хребтів над Дзеркальним Озером, Громові водоспади — незвичайна географічна розколина. Ущелину прорізає стрімкий гірський потік, що вливається через недоступний північний каскад, а потім обривається з обох боків видовищними водоспадами. З одного боку вода падає в Дзеркальне Озеро, а нижня течія тече на захід, до суворих кордонів Вестфолу. Попри ревучі води, на березі стоять невелика хатина, причал і кузня просто неба, та нині мирну галявину привласнили собі розбійники."}},faq={{q="Як дістатися до Громових водоспадів?",a="Ідіть до північного берега Дзеркального Озера в Лісі Елвінн. Крута вузька стежка в'ється пагорбами праворуч від водоспаду Дзеркального Озера й виводить просто у відлюдну ущелину.",al={"як дістатися до громових водоспадів","розташування громових водоспадів","де громові водоспади"}},{q="Хто живе в хатині біля Громових водоспадів?",a="Схоже, відлюдна хатина колись належала самотньому рибалці чи поселенцю: тут є причал, човен на веслах і ковадло просто неба. Нині ж вона стала потаємним сховком для бандитів, що промишляють у глушині Лісу Елвінн.",al={"хто в хатині","будинок громових водоспадів","бандити хатини"}},{q="Куди тече річка біля Громових водоспадів?",a="Потік спадає вузькою гірською щілиною з верхнього каскаду. Нижче за течією він огинає хатину й падає ще одним крутим водоспадом біля східної межі Вестфолу.",al={"куди тече вода","річка громових водоспадів"}}},fp="13,246,24.529.0,31.232.0,42.247.0,43.207.0"}
P.entries["subzone:thunder-ridge"] = {n="Громовий Хребет",s="Громовий Хребет — суворий каньйон на заході Дуротару, просто на південний захід від Оргріммара, на берегах Річки Південної Люті. Колись буйний гай прадавніх дерев, де паслися стада громових ящерів, каньйон зазнав жорстокого вирубування від людських лісорубів і темного чаклунства. Нині розлючені звірі та культисти, що лишилися, невпинно загрожують сусіднім поселенням.",h="Громовий Хребет — суворий каньйон на заході Дуротару, просто на південний захід від Оргріммара, на берегах...",kw={"громовий хребет","дуротар","громові ящери","палаючий клинок","фіззл дарккло","уззек"},ang={["class:Warrior"]="Наставники воїнів, як-от Уззек, посилають учнів на Громовий Хребет, щоб випробувати їхню оборонну вправність проти грубої тілесної сили та ударів блискавок диких громових ящерів.",["faction:Horde"]="Хребет просто за західними кручами Оргріммара потрібно тримати чистим від агентів Палаючого Клинка на кшталт Фіззла Дарккло, щоб запобігти демонічному підриву на порозі столиці."},sec={{t="Пошрамоване святилище",b="Ще недавно Громовий Хребет був рідкісним зеленим прихистком у посушливому Дуротарі, який живили прадавні дерева. Його тиха рівновага розлетілася невдовзі після Третьої війни, коли людські зайди з Кул Тірасу почали рубати тутешній ліс, доводячи місцевих громових ящерів до шалу. Пізніше чаклунство Скверни в руках Палаючого Клинка довершило руйнування: воно здерло крони й лишило по собі голу, відкриту ущелину, де нині без упину блукають розлючені звірі, що плюються блискавками."},{t="Культисти та випробування сили",b="Мешканці Оргріммара не зводять із хребта насторожених очей. Палаючий Клинок тримає тут осередок культистів під проводом чорнокнижника Фіззла Дарккло, який демонічною магією сіє ще більше хаосу по Дуротару. Ветерани Орди, як-от Орґніл Соулскар, доручають розвідникам вистежити кабалу, а наставники воїнів, як-от Уззек, посилають майбутніх бійців у скелі перевірити свою стійкість проти розлючених громових ящерів."}},faq={{q="Що сталося з деревами на Громовому Хребті?",a="Колись Громовий Хребет укривав густий ліс, але його спустошили двічі. Спершу, невдовзі після заснування Дуротару, лісоруби з Кул Тірасу безжально вирубали прадавні дерева. Згодом Палаючий Клинок темною демонічною магією знищив уцілілі гаї, і ліс зник зовсім.",al={"чому громовий хребет голий","ліс громового хребта","вирубка громового хребта"}},{q="Чому громові ящери тут такі агресивні?",a="Громові ящери мирно жили серед прадавніх дерев хребта, доки чужинці не зруйнували їхній дім. Галас і нищення від людських лісорубів разом із залишками скверни після культистів Палаючого Клинка довели стада до шаленства, і тепер вони нападають на кожного, хто потикається в каньйон.",al={"злі ящери громового хребта","громоящери дуротару"}},{q="Хто такий Фіззл Дарккло?",a="Фіззл Дарккло — один із ватажків культу Палаючого Клинка, що розбив табір на Громовому Хребті. Звідти він зі своїми послідовниками проводить темні ритуали, щоб розхитати край, тож вожді Орди, як-от Орґніл Соулскар, оголосили нагороду за його голову.",al={"фіззл дарккло історія","хто такий дарккло","палаючий клинок громовий хребет"}},{q="Чи бився Рекссар на Громовому Хребті?",a="Так. Невдовзі після заснування Дуротару Чемпіон Орди Рекссар прийшов сюди по мерехтливу траву для провидця Дрек'Тара. У каньйоні Рекссар натрапив на людський табір лісорубів, через який ящери шаленіли, тож мусив перебити розлючених звірів і зібрати їхні яйця, щоб Дрек'Тар міг їх дослідити.",al={"рекскар громовий хребет","дрек'тар громовий хребет"}}},fp="13,391,19.466.0,30.418.1,44.317.0,47.331.0,23.279.0,34.309.0"}
P.entries["subzone:thunderhorn-water-well"] = {n="Водяна Криниця Тандергорнів",s="Водяна Криниця Тандергорнів — життєво важливе джерело води на хвилястих рівнинах центрального Малгору, на шляху між Селом Бладгуф і Тандер Блафом. Як і всі криниці долини, вона живить племена та стада, що бродять пасовищами. Берегти цю воду чистою й захищеною конче потрібно, щоб підтримувати життя на батьківщині тауренів.",h="Водяна Криниця Тандергорнів — життєво важливе джерело води на хвилястих рівнинах центрального Малгору, на...",kw={"водяна криниця тандергорнів","криниця","вода","малгор","венчурна компанія","духи води"},ang={["class:Shaman"]="Шамани глибоко шанують чисті джерела Малгору й уважають захист духів води та підземних течій священним обов'язком.",["race:Tauren"]="Для тауренів такі криниці, як Криниця Тандергорнів, — життєво важливі артерії, дар Земної Матері, що потребує постійної охорони від чужинських отруювачів і жадібних зайд."},sec={{t="Життєдайне джерело",b="Водяна Криниця Тандергорнів серед розлогих пасовищ центрального Малгору сягає просто в чисті водоносні шари, що живлять долину. Для кочових тауренів та їхніх новозаснованих сіл такі спільні криниці означають життя, поживу й щедрість Земної Матері. Вода на випалених сонцем рівнинах дорогоцінна, тож хто володіє криницями — той володіє самою землею. Зайди на кшталт Венчурної Компанії не раз накидали оком на ці джерела, намагаючись прибрати їх до рук задля промислового визиску й зруйнувати крихку рівновагу, за яку борються племена."}},faq={{q="Де розташована Водяна Криниця Тандергорнів?",a="Криниця стоїть у центральному Малгорі, при дорозі з півночі на південь між Селом Бладгуф і кручами Тандер Блафа.",al={"розташування водяної криниці тандергорнів","де криниця тандергорнів","криниця тандергорнів на мапі"}},{q="Чому ця криниця важлива для тауренів?",a="Криниці Малгору сягають чистих підземних вод долини й поять стада, прочан і поселення. Для тауренів вода — священний дар Земної Матері, і її треба берегти від чужої скверни й жадібності.",al={"чому криниця тандергорнів важлива","значення криниць тавренів","чому захищати криниці"}},{q="Хто загрожував криниці?",a="Гобліни з Венчурної Компанії намагалися захопити криницю, щоб прибрати до рук усю воду долини для своїх копалень і лісорубень неподалік, але місцеві таурени дали відсіч, відвоювали криницю й очистили її.",al={"хто напав на криницю","венчур ко криниця","вороги біля криниці тандергорнів"}}},fp="22,373,20.585.0,44.142.0,47.252.0,28.210.1"}
P.entries["subzone:tidefury-cove"] = {n="Бухта Шаленого Прибою",s="Бухта Шаленого Прибою — підступна смуга води й скелястих мілин уздовж південно-східного узбережжя Багна Пилоброду, на південь від Острова Терамор. Відома своїми небезпечними рифами й розбитими кораблями, вона слугує відлюдним прихистком для мандрівних макрур і самотніх рибалок.",h="Бухта Шаленого Прибою — підступна смуга води й скелястих мілин уздовж південно-східного узбережжя Багна...",kw={"бухта шаленого прибою","багно пилоброду","затока пилоброду","макрури","рифи","дейлін праудмур","тралл"},ang={["faction:Horde"]="Для Орди це узбережжя стало плацдармом останнього контрнаступу, який зламав морську агресію великого адмірала Праудмура й забезпечив молодому народові виживання.",["profession:Cooking"]="Багаті прибережні мілини й сусідство з майстром-рибалкою Натом Паґлом роблять цю частину Багна Пилоброду чудовим місцем для рибалок, що шукають цінного улову."},sec={{t="Цвинтар кораблів і рифів",b="Бухта Шаленого Прибою, захована в дальньому кінці Затоки Пилоброду між Островом Терамор і Вірмовим Болотом, — сумнозвісна небезпека для мореплавців. Зубчасті рифи й мінливі обмілини за ці роки поглинули чимало суден, і гнилі дерев'яні корпуси напівзатоплені лежать на лінії припливу. Нині розбитими кораблями повзають заповзятливі макрури, тож бухта стала небезпечною відлюдною смугою узбережжя, куди навідуються здебільшого загартовані збирачі поживи чи тихі відлюдники, що шукають спокою подалі від гамірних пристаней Терамору."},{t="Історичний плацдарм",b="Під час вторгнення в Дуротар береги Бухти Шаленого Прибою стали вирішальним полем битви. Кул-тіраська експедиція адмірала Дейліна Праудмура укріпила узбережжя грізною береговою фортецею й сторожовими вежами, щоб контролювати підступи до Терамору. Щоб зламати хватку Праудмура, Тралл зібрав об'єднані сили молодої Орди — орків, тролів Темного Списа й тауренів разом із Рекссаром і ограми Кам'яного Молота, — штурмом узяв узбережжя й розгромив кул-тіраський плацдарм, а тоді рушив просто на острівну фортецю."}},faq={{q="Де розташована Бухта Шаленого Прибою?",a="Бухта Шаленого Прибою лежить на південно-східному краю Багна Пилоброду, трохи на південь від Острова Терамор, і межує з узбережжям Вірмового Болота в південному кінці Затоки Пилоброду.",al={"розташування бухти шаленого прибою","де бухта шаленого прибою","бухта шаленого прибою на мапі"}},{q="Чому в Бухті Шаленого Прибою стільки уламків кораблів?",a="Бухта повна мілин і прихованих скелястих рифів, тож плавати тут дуже небезпечно. Кораблі, що підходять надто близько до берега, часто сідають на мілину, а хвилі й падальники швидко лишають від них самі розбиті корпуси.",al={"уламки кораблів шаленого прибою","розбиті кораблі шаленого прибою","затонулі кораблі затоки пилоброду"}},{q="Хто живе в Бухті Шаленого Прибою нині?",a="Окрім агресивних макрур на березі, найвідоміший мешканець бухти — славетний рибалка Нат Паґл, що тримає табір під назвою Причал Ната на одному з дальніх острівців.",al={"хто в бухті шаленого прибою","мешканці бухти шаленого прибою","де нат паґл"}},{q="Яка битва відбулася тут у минулому?",a="Під час походу адмірала Дейліна Праудмура проти нової Орди сили Кул Тірасу збудували тут добре укріплену прибережну твердиню. Орда Тралла, підсилена союзниками-тауренами й ограми, штурмом узяла й знищила базу, щоб розчистити шлях до Острова Терамор.",al={"битва бухти шаленого прибою","варкрафт 3 шалений прибій","вторгнення дуротару шалений прибій"}}},fp="13,267,30.529.0,21.548.0,31.167.0,42.233.0,33.183.0,40.256.0"}
P.entries["subzone:tidus-stair"] = {n="Сходи Тідуса",s="Сходи Тідуса — природне скельне утворення з широких кам'яних терас-сходинок над Узбережжям Крамарів, на південний схід від Раджета. Сховане біля Великого Моря, воно стало тихим прихистком для двох тауренів-шаманів, що єднаються з припливами й духами води.",h="Сходи Тідуса — природне скельне утворення з широких кам'яних терас-сходинок над Узбережжям Крамарів, на...",kw={"сходи тідуса","іслен вотерсір","магрен скайсір","шамани","узбережжя крамарів","пустки"},ang={["class:Shaman"]="Кожен шаман Орди рано чи пізно спускається цими прибережними сходинками, щоб знайти Іслен Вотерсір під час випробувань, які ведуть до Тотема Води.",["race:Tauren"]="Тиха присутність Іслен Вотерсір і Магрена Скайсіра показує, як таурени-провидці несуть духовну варту навіть далеко за межами Малгору."},sec={{t="Сходинки до моря",b="Сходи Тідуса, що спускаються до прибою на південний схід від Раджета, нагадують величезні обвітрені кам'яні сходинки, вирубані просто в прибережних кручах. Довколишні Пустки посушливі, курні й неспокійні, а на цій тихій ділянці над Узбережжям Крамарів панує шум хвиль. На терасах стоїть скромна хатина, де живуть таурени Іслен Вотерсір і Магрен Скайсір. Далеко від гамірних торгових доків гоблінів вони проводять дні за риболовлею, спостерігають за обрієм і шукають прозріння в прибережних духів води."}},faq={{q="Де розташовані Сходи Тідуса?",a="Сходи Тідуса лежать на східному узбережжі Пусток, просто на південний схід від гоблінського порту Раджет. Звідси видно води Узбережжя Крамарів.",al={"розташування сходів тідуса","де сходи тідуса","як дістатися до сходів тідуса"}},{q="Хто живе на Сходах Тідуса?",a="Тут мешкають двоє тауренів: Іслен Вотерсір і Магрен Скайсір. Вони живуть у простій приморській хижці на терасах, рибалять і спілкуються з природою.",al={"хто на сходах тідуса","нпс сходів тідуса","хто тут живе"}},{q="Чому Сходи Тідуса важливі для шаманів?",a="Шаманів Орди, які прагнуть опанувати стихію води, посилають через увесь Калімдор до Іслена Вотерсіра на Сходах Тідуса. Тут, біля відкритого океану, новачки вчаться відчувати припливи й шукають чисту воду, щоб прив'язати свій тотем води.",al={"шамани сходи тідуса","тотем води сходів тідуса","чому шамани приходять сюди"}},{q="Сходи Тідуса належать Орді чи нейтральні?",a="Тутешні таурени вірні Орді й допомагають шаманам Орди, хоча віддалені тераси лежать поза будь-якими офіційними військовими кордонами.",al={"чи сходи тідуса орди","фракція сходів тідуса"}}},fp="11,254,16.579.0,29.153.0,25.174.0,42.242.0,49.135.0"}
P.entries["subzone:timbermaw-hold"] = {n="Твердиня Деревопащих",s="Твердиня Деревопащих — укріплена мережа підземних тунелів, що сполучає Сквернолісся, Місячний Гай і Вінтерспрінг. Це оплот фурболгів Деревопащих — одного з останніх племен, що опираються демонічній скверні, яка чумою пройшлася північним Калімдором.",h="Твердиня Деревопащих — укріплена мережа підземних тунелів, що сполучає Сквернолісся, Місячний Гай і...",kw={"твердиня деревопащих","фурболги","деревопащі","сквернолісся","місячний гай","вінтерспрінг"},ang={["class:Druid"]="Твердиня — важливий гірський шлях між вашою священною обителлю в Місячному Гаю і пораненими нетрями Сквернолісся, де духи фурболгів відчайдушно потребують очищення.",["class:Shaman"]="Деревопащі затято зберегли незаплямовані духовні традиції й цілющі обряди, хоча просто за брамою їхніх печер гниє скверна."},sec={{t="Притулок серед тліну",b="Вирубана глибоко в корінні гір між Скверноліссям, Місячним Гаєм і Вінтерспрінгом, Твердиня Деревопащих — оплот, який боронять із відчаєм. Поки сусідні племена фурболгів під час Третьої війни піддалися мерзенній скверні Палаючого Легіону, клан Деревопащих перечекав це жахіття в цих кам'яних коридорах. Під землею вони були в безпеці, та мусили безсило дивитися, як улюблені ліси обертаються на зіпсовану подобу самих себе. Надзвичайно пильні й глибоко недовірливі до чужинців, фурболги люто стережуть кожен вхід до тунелів і чекають насильства від кожного, хто приходить із заражених лісів."},{t="Перехрестя півночі",b="Твердиня Деревопащих — не лише притулок племені, а й єдиний прямий гірський шлях, що сполучає отруєні низини Сквернолісся, священний притулок Місячного Гаю та крижані простори Вінтерспрінгу. Чужинці, які хочуть пройти тут і не бути розірваними вартовими племені, мусять довести свою добру волю. Ті, хто покаже, що бореться проти зіпсованих кланів фурболгів у краї, знайдуть у Деревопащих вірних союзників, готових поділитися прадавнім шаманським знанням і традиціями обробки шкіри."}},faq={{q="Чому фурболги у Твердині Деревопащих нападають на відвідувачів?",a="Плем'я Деревопащих не довіряє чужинцям відтоді, як їхні сусіди-родичі піддалися скверні Палаючого Легіону. Боячись, що чужинці сплутають їх зі здичавілими, оскверненими демонами фурболгами — або занесуть скверну до їхнього дому, — вони нападають на кожного, хто підходить до їхніх тунелів, доки чужинець не доведе своїх мирних намірів.",al={"чому деревопащі ворожі","деревопащі нападають на мене","як подружитися з деревопащими"}},{q="Які краї з'єднує Твердиня Деревопащих?",a="Головна печера має три основні виходи: на південному заході — до північного Сквернолісся, на півночі — до тихого Місячного Гаю, на сході — до засніжених долин Вінтерспрінга. Ще одна, замурована брама виходить на півночі Азшари.",al={"куди веде твердиня деревопащих","виходи твердині деревопащих","тунелі твердині деревопащих"}},{q="Як Деревопащі вціліли перед скверною Легіону?",a="Поки ліси Сквернолісся марніли від демонічної скверни, плем'я Деревопащих сховалося глибоко у своїх гірських печерах. Замкнувшись у твердині в розпал демонічного вторгнення, вони зберегли ясний розум і священні шаманські звичаї, тоді як сусідні клани поринули в безумство.",al={"чому деревопащі незіпсовані","деревопащі не зіпсовані"}},{q="Що це за запечатані дерев'яні двері у твердині?",a="Глибше в тунелях стоїть кругла дерев'яна загорожа, що перекриває бічну печеру. Її справжнє призначення невідоме, хоча мандрівники припускають, що вона відгороджує давніші тунелі, які ведуть до Курганних Глибин чи інших прадавніх підземних залів під Горою Гіджал.",al={"заблокована брама твердині деревопащих","замкнена брама деревопащих"}}},fp="14,250,24.597.0,23.517.0,54.342.0,40.232.0,49.316.0,47.257.0"}
P.entries["subzone:timbermaw-post"] = {n="Застава Деревопащих",s="Застава Деревопащих — невеликий табір фурболгів серед засніжених просторів Вінтерспрінгу, між Гарячими Джерелами Морозного Вогню та Озером Кел'Теріл. Хоч табір і названо на честь племені Деревопащих, якого не торкнулася скверна, тепер ним міцно заволоділи агресивні фурболги Зимопадів — ті, кого скверна таки поглинула.",h="Застава Деревопащих — невеликий табір фурболгів серед засніжених просторів Вінтерспрінгу, між Гарячими...",kw={"застава деревопащих","фурболги","деревопащі","зимопади","вінтерспрінг","скверна"},ang={["class:Druid"]="Для друїдів, які шанують фурболгів як давніх охоронців природи, табір, захоплений знавіснілими фурболгами Зимопадів, — разючий доказ того, що скверна Палаючого Легіону досі нікуди не зникла."},sec={{t="Застава в чужих руках",b="Застава Деревопащих стоїть трохи на південний схід від Гарячих Джерел Морозного Вогню, через дорогу від них, і на захід від замерзлого Озера Кел'Теріл. Вона — гірке нагадування про міжусобиці фурболгів Вінтерспрінгу. Хоч назва й походить від Деревопащих, мандрівників, що наближаються до табору, тут привітно не зустрінуть. Заставою заволоділо вороже плем'я Зимопадів, яке демонічна скверна зробила шаленим і лютим. Тепер табір кишить дикими фурболгами Зимопадів, і звідси вони дедалі зухваліше підступають до центральної дороги."}},faq={{q="Чому це місце зветься Заставою Деревопащих, якщо тут живуть фурболги Зимопаду?",a="Попри назву, табір контролює спотворене плем'я Зимопаду. Як його заснували — невідомо.",al={"чому застава деревопащих","хто володіє заставою деревопащих","фурболги застави деревопащих"}},{q="Де розташована Застава Деревопащих?",a="Вона лежить у центрі Вінтерспрінга, на південний схід від Гарячих Джерел Морозного Вогню, по той бік головної дороги, і просто на захід від Озера Кел'Теріл.",al={"розташування застави деревопащих","де застава деревопащих","застава деревопащих на мапі"}},{q="Чи ворожі фурболги на Заставі Деревопащих?",a="Так. Навіть якщо ви здобули прихильність справжнього племені Деревопащих, фурболги на цій заставі належать до ворожого племені Зимопаду й нападають на чужинців, щойно їх побачать.",al={"чи фурболги ворожі","чи дружня застава деревопащих","чи можна говорити з заставою деревопащих"}}},fp="14,295,19.525.0,65.110.0,32.137.0,43.188.0"}
P.entries["subzone:tinkers-court"] = {n="Двір Майстрів",s="Двір Майстрів — велика зала ради в самому серці Гномреґана. Колись гамірний осідок Великого Тінкера та його правлячої ради, тепер це похмура твердиня зрадника — Мехінженера Термаплаґа.",h="Двір Майстрів — велика зала ради в самому серці Гномреґана.",kw={"двір майстрів","гномреґан","термаплаґ","меккаторк","тронна зала"},ang={["profession:Engineering"]="Зала — тривожна вітрина спотвореної інженерії: тут повно смертоносних систем доставки бомб, а ще — смертельний облоговий обладунок, яким керує Термаплаґ.",["race:Gnome"]="Стояти в Дворі Майстрів — болюче нагадування про зраду: колись тут збиралися ватажки гномів, доки Сікко Термаплаґ не захопив залу серед опромінених руїн."},sec={{t="Осідок гномської ради",b="До катастрофи, що зруйнувала Гномреґан, Двір Майстрів був громадським і політичним серцем народу. Саме тут Великий Тінкер Ґелбін Меккаторк збирав радників і майстрів-винахідників, серед них Тінкмайстра Оверспарка, щоб обговорювати технічні досягнення, вирішувати громадські справи й спрямовувати гномське суспільство. Двір уособлював вершину гномської винахідливості й врядування і лежав одразу за промисловими цехами Інженерних Лабораторій і Стартового відсіку."},{t="Тронна зала Термаплаґа",b="Після катастрофічного радіаційного викиду, що прирік гномів на вигнання, Мехінженер Сікко Термаплаґ привласнив залу. Назвавши себе Королем Гномреґана, божевільний винахідник тепер сидить у Дворі Майстрів в оточенні спотворених механізмів, вірних гномів-прокажених і бомбометів. З цієї оскверненої зали ради він керує рештками своїх сил, тож двір — останній і найнебезпечніший поріг для кожного ударного загону, що прагне покласти край його владі."}},faq={{q="Для чого спочатку слугував Двір Майстрів?",a="Колись Двір Майстрів був місцем зборів і залою засідань обраного Великого Тінкера та правлячої ради Гномреґана. Ґелбін Меккаторк і високопоставлені радники, як-от Тінкмайстер Оверспарк, обговорювали тут міські справи й найсміливіші винаходи.",al={"історія двору майстрів","що таке двір майстрів","початкове призначення двору"}},{q="Хто контролює Двір Майстрів тепер?",a="Нині двір захопив Мехінженер Сікко Термаплаґ. Він називає себе Королем Гномреґана й утримує залу разом зі своїми оборонними машинами та опроміненими поплічниками.",al={"хто у дворі майстрів","бос двору майстрів","кімната термаштепселя"}},{q="Де в Гномреґані розташований двір?",a="Двір Майстрів лежить у найглибших закутках Гномреґана, за темними тунелями й нижніми рівнями, що з'єднуються і зі Стартовим відсіком, і з Інженерними Лабораторіями.",al={"де двір майстрів","як дістатися до двору майстрів","знайти двір майстрів"}},{q="Чому Альянсу так важливо дістатися Двору Майстрів?",a="Дійти до двору — кінцева мета відвоювання міста, адже звідти Мехінженер Термаплаґ керує своїми опроміненими поплічниками. Скинути його — перший вирішальний крок до звільнення Гномреґана.",al={"навіщо йти до двору майстрів","чому вбити термаштепселя","важливість двору майстрів"}}},fp="14,205,27.487.0,24.470.1,48.292.0,32.176.0,45.157.0,61.209.0"}
P.entries["subzone:tiragarde-keep"] = {n="Фортеця Тіраґард",s="Фортеця Тіраґард — укріплена людська твердиня на Дріботливому Узбережжі Дуротару, на південь від Гострого Пагорба. Збудована під час вторгнення Великого Адмірала Дейліна Праудмура, зруйнована цитадель досі утримується ворожою кул-тіраською морською піхотою під проводом Лейтенанта Бенедикта. Це зухвала, невиправна скалка в боці Орди просто на її рідній землі.",h="Фортеця Тіраґард — укріплена людська твердиня на Дріботливому Узбережжі Дуротару, на південь від Гострого...",kw={"фортеця тіраґард","кул тірас","люди","лейтенант бенедикт","праудмур","узбережжя","дуротар"},ang={["faction:Horde"]="Фортеця Тіраґард — відверта загарбницька база Альянсу просто на порозі Дуротару; штурмувати її вали й усунути Лейтенанта Бенедикта — обряд посвяти для молодих солдатів на службі Гострого Пагорба.",["race:Human"]="Гарнізон утілює незламну, мстиву спадщину Кул Тірасу й Адмірала Праудмура, ведучи вперту партизанську війну наперекір дипломатії Джайни Праудмур."},sec={{t="Бастіон Праудмура",b="Зведена під час походу Великого Адмірала Дейліна Праудмура на знищення щойно заснованого королівства Тралла, Фортеця Тіраґард дала флоту Кул Тірасу укріплений плацдарм на червоних берегах Дуротару. Хоч Орда зрештою прорвала облогу й убила Праудмура на Острові Терамор, фортецю так і не покинули повністю. Війська постачання під проводом Лейтенанта Бенедикта знову зайняли розтрощені кам'яні стіни, виконуючи незмінний наказ покійного Адмірала вести з орками безкомпромісну війну й цілком відкидаючи мир, укладений Леді Джайною Праудмур."},{t="Скалка в боці Дуротару",b="Нині блискучі білі зубці фортеці різко контрастують із багряними скелями Дуротару. Добре вишколені моряки та морські піхотинці Кул Тірасу патрулюють вали й влаштовують набіги на шляхи постачання біля Гострого Пагорба. Для Орди Фортеця Тіраґард — і тривала криза безпеки, і живий полігон. Командири орків і тролів без упину доручають молодим воїнам штурмувати фортецю й рубати солдатів Бенедикта, прагнучи стримати гарнізон, перш ніж люди зможуть розгорнути глибший наступ углиб суходолу."}},faq={{q="Чому в Дуротарі є люди?",a="Це моряки й морські піхотинці з Кул Тірасу, які прибули з Великим Адміралом Дейліном Праудмуром під час його вторгнення після Третьої війни. Вони не визнають миру з Ордою й тримають тут гарнізон, щоб дошкуляти оркам.",al={"чому в дуротарі люди","чому тут альянс","люди в тіраґарді"}},{q="Ці люди — частина війська Джайни з Терамору?",a="Ні. Хоча Джайна Праудмур править Островом Терамор і підтримує хиткий мир із Траллом, ці солдати виконують накази її покійного батька, Великого Адмірала Дейліна Праудмура. Будь-який мир з орками вони вважають неприпустимою зрадою.",al={"чи тіраґард терамор","чи це люди джайни праудмур","солдати терамора тут"}},{q="Хто командує Фортецею Тіраґард?",a="Твердинею командує Лейтенант Бенедикт, кул-тіраський офіцер, який виконує накази про вторгнення, залишені адміралом Праудмуром перед смертю: утримати узбережжя й нападати на Орду.",al={"бос тіраґарда","хто командує тіраґардом","лейтенант бенедикт"}},{q="Чому Орда досі просто не знищила їх?",a="Фортеця добре укріплена, а залога — дисципліновані й добре озброєні кул-тіраські вояки. Захисники з Гострого Пагорба часто вступають у сутички з гарнізоном і використовують його як полігон для новобранців, але повноцінна облога коштувала б великих втрат і відволікла б потрібні сили від охорони решти Дуротару.",al={"чому орда не знищила тіраґард","чому фортеця ще тут"}}},fp="14,360,20.550.0,26.519.0,32.220.0,53.232.0,28.177.0,43.324.0"}
P.entries["subzone:tkashi-ruins"] = {n="Руїни Ткаші",s="Руїни Ткаші — давні кам'яні рештки на південний захід від Експедиції Несінґварі на півночі Долини Стренглторну. Їх заполонили ворожі тролі з племені Кривавого Скальпа, і тепер це одна з його твердинь.",h="Руїни Ткаші — давні кам'яні рештки на південний захід від Експедиції Несінґварі на півночі Долини...",kw={"руїни ткаші","кривавий скальп","тролі джунглів","гемет несінгварі","долина стренглторну","реліквії"},ang={["race:Troll"]="Для племені Темного Списа такі місця, як Ткаші, — похмуре нагадування про прадавні руїни, що лишилися від ворожих родичів-Ґурубаші, а нині їх люто обороняють дикі недобитки Кривавого Скальпа."},sec={{t="Каміння Кривавого Скальпа",b="Розсипана кам'яна кладка Руїн Ткаші, що на південний захід від мисливського табору Гемета Несінгварі, позначає прадавні володіння тролів джунглів Стренглторну. Сьогодні тут міцно отаборилося плем'я Кривавого Скальпа: тролі люто боронять свою територію й правлять шаманські обряди серед ліан і зотлілого каміння. У своїх мисливських спогадах Гемет Несінгварі писав, що пройшов крізь руїни без жодних пригод, але нинішні мандрівники вважають тролів куди менш привітними: ті стережуть цінні племінні реліквії, закопані серед уламків."}},faq={{q="Хто живе в Руїнах Ткаші?",a="Руїни займає плем'я Кривавого Скальпу — ворожа громада тролів джунглів, що люто боронить напівзруйноване городище від чужинців і племен-суперників.",al={"хто тут","моби ткаші","тролі ткаші"}},{q="Де розташовані Руїни Ткаші?",a="Вони лежать на півночі Долини Стренглторну, трохи на південний захід від річкового броду біля Експедиції Несінґварі.",al={"розташування ткаші","де ткаші","знайти руїни ткаші"}},{q="Що пише про Ткаші Гемет Несінгварі?",a="У третьому розділі своїх спогадів «Зелені Пагорби Стренглторну» (а саме на сторінці 21) Несінгварі записує, що в перші дні в джунглях він і його мисливська ватага пройшли Руїни Ткаші без жодних пригод.",al={"несінґварі ткаші","зелені пагорби ткаші"}}},fp="12,203,24.548.0,30.167.0,35.107.0,62.230.0"}
P.entries["subzone:tor-kren-farm"] = {n="Ферма Тор'крена",kw={"ферма тор'крена","міша тор'крен","свиноферма","крон","кроколіски","річка південної люті","дуротар"},ang={["faction:Horde"]="Тиха трагедія на Фермі Тор'крена розкриває щоденні жертви простих поселенців Орди, що прагнуть приборкати дике порубіжжя Дуротару."},sec={{t="Самотня садиба",b="Вижити на сухій, нещадній червоній землі Дуротару ніколи не було просто, але Фермі Тор'крена ведеться гірше за інших. Садиба на південний схід від Громового Хребта розводить свиней у суворому кліматі, де бракує і корму, і води. На відміну від гамірних торгових постів чи добре захищених казарм Орди, ферма стоїть самотня й тиха, даючи скупий урожай у тіні сусідніх круч."},{t="A Mother's Worry",b="Misha Tor'kren's son Kron went west to hunt crocolisks along the Southfury River several days ago and has not returned. She had warned him about the vicious predators, but he left in anger. Now she asks passing adventurers to search for him or bring back a sign of his fate, fearing the worst but unable to begin mourning without knowing what happened."},{t="A Mother's Loss",b="When an adventurer brings back Kron's Amulet from the river's crocolisks, Misha recognizes it and says she now knows her son is dead. Knowing his fate, she can finally begin to mourn."}},faq={{q="Де розташована Ферма Тор'крена?",a="Ферма Тор'крена лежить на північному заході Дуротару, на південний схід від каньйону Громовий Хребет, на схід від Річки Південної Люті.",al={"розташування ферми тор'крена","де ферма тор'крена","знайти ферму тор'крена"}},{q="Хто живе на Фермі Тор'крена?",a="Misha Tor'kren tends the swine farm. Her son Kron is missing after setting out to hunt along the Southfury River.",al={"хто керує фермою тор'крена","нпс ферми тор'крена","хто така міша тор'крен"}},{q="Що сталося із сином Міші?",a="Kron went hunting crocolisks along the Southfury River days ago and has not returned. Misha asks travelers to find him or bring back a sign of his fate.",al={"син міші","смерть крона тор'крена","хто такий крон"}},{q="Що виробляє Ферма Тор'крена?",a="Це свиноферма, хоча суворий край і відлюддя роблять її прибутки значно скромнішими, ніж в інших тваринницьких господарствах Дуротару.",al={"бізнес ферми тор'крена","що за ферма тор'крена","свині тор'крена"}}},fp="13,240,18.429.0,16.352.0,15.183.1,31.128.0,27.113.0,29.152.0,32.135.0"}
P.entries["subzone:tower-of-althalaxx"] = {n="Вежа Альталакса",s="Вежа Альталакса — давній шпиль Високородних на півночі Темного Узбережжя, неподалік від берега. До Великого Розколу це був відлюдний прихисток чаклуна Атрікуса Нарассіна, а тепер його заполонили демонічні культисти й чорнокнижники, що практикують темні мистецтва.",h="Вежа Альталакса — давній шпиль Високородних на півночі Темного Узбережжя, неподалік від берега.",kw={"вежа альталакса","атрікус нарассін","культ темного берега","рада тіней","високородні","темне узбережжя"},ang={["class:Warlock"]="Темні обряди Культу Темного Берега показують, як далеко сягає вплив Ради Тіней на Калімдорі і як міцно вона тут укорінилася.",["race:NightElf"]="Вежа — похмуре нагадування про скверну Високородних і демонічне безумство, що досі тяжіють над землями предків, тож Дарнасус мусить утрутитися негайно."},sec={{t="Прихисток Високородного",b="Десять тисяч років тому королева Азшара оселила улюблених слуг із Високородних у приморських містах Амет'Аран і Башал'Аран і поставила над ними могутнього чаклуна Атрікуса Нарассіна. Віддаляючись від міських справ, Атрікус вирішив усамітнитися в сусідній Вежі Альталакса. Коли Великий Розкол зруйнував давній Калімдор, вежа встояла на пустельному березі Темного Узбережжя — тихі руїни забутої ельфійської магії."},{t="Темний Берег",b="Нині у вежі заворушилося зловісне чаклунство. Чорнокнижники, темні культисти, що звуть себе Культом Темного Берега, та їхні союзники-сатири зібралися в руїнах під проводом самого Атрікуса Нарассіна. Їхні обряди спрямовують демонічну магію й мучать неспокійних духів давніх мерців, служачи зловісним задумам, безпосередньо пов'язаним із демонічною Радою Тіней."}},faq={{q="Що таке Вежа Альталакса?",a="Це стародавня ельфійська вежа магів, збудована на півночі Темного Узбережжя за правління королеви Азшари. Нині її займають темні чаклуни й культисти.",al={"вежа альталакса","що таке альталакс","про вежу альталакса"}},{q="Хто спочатку збудував вежу й жив у ній?",a="Атрікус Нарассін, могутній чаклун із Високородних, якого королева Азшара призначила наглядати за поселеннями Амет'Аран і Башал'Аран неподалік. Коли обов'язки йому набридли, він усамітнився тут.",al={"хто жив у вежі","атрікус нарассін","хто збудував вежу"}},{q="Хто ці культисти, що займають вежу тепер?",a="Вони належать до Культу Темного Берега — секти чорнокнижників, культистів і сатирів, що правлять темні обряди в зруйнованій вежі.",al={"хто ці культисти","культ темного берега","вороги альталакса"}},{q="Чому тут привиди й закатовані духи?",a="Культисти проводять темні ритуали й чари поневолення душ, прирікаючи давно померлих ельфів стародавнього Темного Узбережжя на нестерпні муки заради своїх заклять.",al={"чому тут привиди","закатовані духи альталакса"}}},fp="18,265,19.473.0,15.397.1,31.141.0,44.189.0,45.131.0,47.156.0"}
P.entries["subzone:tower-of-arathor"] = {n="Вежа Аратора",s="Вежа Аратора — зруйнована вежа чарівника в колишньому магічному кварталі на південному заході Фортеці Стромгард. Колись це була майстерня Архімага Трелейна, але під час падіння міста її захопили, і тепер у ній засіли огри Каменекулаків.",h="Вежа Аратора — зруйнована вежа чарівника в колишньому магічному кварталі на південному заході Фортеці...",kw={"вежа аратора","архімаг трелейн","архімаг малін","руул ванстоун","каменекулаки","фортеця стромгард","агат"},ang={["class:Mage"]="Вежа — тверезе нагадування про долю магічного анклаву Стромґарда й водночас свідчення майстерності Архімага Трелейна, що вправно створював захисні конструкти зі стихій.",["faction:Alliance"]="За Фортецю Стромгард точиться боротьба; допомагаючи посланцям Архімага Маліна повернути втрачені артефакти Трелейна, ви не даєте могутнім магічним реліквіям потрапити до рук клану Каменекулаків."},sec={{t="Захоплений оплот",b="Цей шпиль звели в серці магічного кварталу Фортеці Стромгард і назвали на честь давньої Імперії Аратор; він довго служив чародіям королівства. Його найвідоміший мешканець, Архімаг Трелейн, створив чарівну захисну мережу, прив'язану до зачарованих самоцвітів, щоб оберігати своє святилище. Та коли після Третьої війни на Стромґард напали Синдикат і огри з клану Каменекулаків, королівство розкололося. Попри відчайдушні спроби Трелейна втримати вежу тайними оберегами, груба сила огрів його здолала. Рятуючи життя, архімаг утік із міста й покинув свої найцінніші чарівні артефакти, а шпиль дістався громилі Каменекулаків Руулу Ванстоуну та його посіпакам."},{t="Повернення втрачених реліквій",b="Навіть у вигнанні Трелейн не захотів кидати справу свого життя. Заручившись допомогою колишнього учня, Архімага Маліна з Кірін-Тору, він спорядив експедицію, щоб забрати з руїн свій філактерій, сферу й жаристий агат. Діючи з Притулку, посланці Маліна з'ясували, що огри розграбували камені, потрібні для керування самочинним захистом вежі. Якщо виготовити новий зачарований агат і покласти його на постаменти обабіч входу до вежі, можна пробудити закликаних водяних елементалів: вони виженуть огрів-загарбників і дадуть сміливим шукачам пригод повернути спадок архімага."}},faq={{q="Що таке Вежа Аратора?",a="Це вежа магів у південно-західних руїнах Фортеці Стромгард. Названа на честь стародавньої людської імперії Аратор, вона була осередком навчання магів королівства, доки її не захопили огри-загарбники.",al={"вежа аратора","вежа магів стромґарду","вежа араті"}},{q="Хто живе у вежі тепер?",a="Вежу й довколишній квартал магів займають огри-Каменекулаки. У шпилі мешкає огр-маг Руул Ванстоун зі своєю вартою: вони відшукали реліквії, що лишилися після колишнього господаря вежі, і тепер їх стережуть.",al={"хто у вежі аратора","моби вежі аратора","бос вежі аратора"}},{q="Хто такий Архімаг Трелейн?",a="Архімаг Трелейн — знаний чарівник Стромґарда, що жив і навчався у вежі. Він створив її охоронні системи, які живляться самоцвітами, і подався у вигнання, коли не зміг відстояти святилище від нападу Каменекулаків.",al={"архімаг трелейн","хто володів вежею","трелейн"}},{q="Як працює захист вежі?",a="Трелейн налаштував вежу так, що захист вмикається, коли до постаментів обабіч входу прикладають зачарований агат. Тоді магічна матриця викликає ворожих водяних елементалів, які б'ються з усіма чужинцями біля входу.",al={"як активувати захист вежі","захист трелейна","п'єдестали вежі"}}},fp="16,262,17.725.0,26.615.1,29.215.0,27.230.0,25.226.0,33.232.0"}
P.entries["subzone:tower-of-azora"] = {n="Вежа Азори",s="Вежа Азори — струнка чародійська вежа, що здіймається на сході Лісу Елвінн, на північ від Гарбузової Ділянки Брекуеллів. Під проводом Архімага Теокрітуса з людей цей анклав служить ученою заставою, втягнутою в мовчазну магічну ворожнечу з ворожою вежею в сусідніх Горах Редріджу.",h="Вежа Азори — струнка чародійська вежа, що здіймається на сході Лісу Елвінн, на північ від Гарбузової Ділянки...",kw={"вежа азори","вежа","теокрітус","архімаг","гноми","морґант","прозирання","ліс елвінн"},ang={["class:Mage"]="Для магів, що мандрують за межі Стормвінда, вежа пропонує відлюдний прихисток для студій, таємних наставників і місце в першому ряду перед небезпечним мистецтвом далекого прозирання.",["race:Gnome"]="Таємний шпиль у людських землях, який обслуговують гноми під проводом Архімага Теокрітуса, — гордий показ майстерності вашого народу в містичних мистецтвах."},sec={{t="Шпиль таємної пильності",b="Вежа Азори при східній дорозі до Гір Редріджу — таємне святилище, яке майже цілком обслуговують чаклуни-гноми. Під опікою Архімага Теокрітуса ці вчені вивчають дивні дивовижі й дають магічні настанови мандрівним чаклунам. Дика магічна аура довкола шпиля часом викривлює навколишню звірину, тож слугам-гномам доводиться давати раду зачарованому хатньому начинню та мутованим комахам, що повзуть повз двері."},{t="Ворожнеча з Ілґаларом",b="Під тихою вченою зовнішністю вежа веде тривалу війну прозирання й саботажу. На сході, на скелях Редріджу, стоїть лиховісна Вежа Ілґалара, якою править чаклун-відступник Морґант. Теокрітус і Морґант невпинно шпигують один за одним таємними засобами, залучаючи відважних шукачів пригод, щоб ті встановлювали реліквії прозирання на кшталт Ока Азори, пробивали захисні чари Ілґалара й стежили за темними задумами Морґанта."}},faq={{q="Хто править Вежею Азори?",a="Вежею керує Архімаг Теокрітус, вправний людський чарівник. Він порядкує слугами у шпилі й налагоджує їхній магічний захист від чаклунів-суперників.",al={"хто править вежею азори","хто головний","бос вежі азори"}},{q="Чому тут стільки гномів?",a="Слуги Азори — здебільшого гноми-дослідники й послушники, які допомагають Архімагу Теокрітусу в навчанні, магічних дослідах і господарстві, пильнуючи, щоб не сталося якоїсь магічної халепи.",al={"чому тут гноми","слуги азори елвін"}},{q="З ким ворогує вежа?",a="Вежа веде магічне суперництво з Вежею Ілґалара в Горах Редріджу, де живе лихий чаклун Морґант. Обидва шпилі шпигують один за одним за допомогою артефактів ясновидіння й змагаються за вплив.",al={"вороги азори","ворожнеча веж","за ким шпигує азора"}},{q="Що таке Око Азори на верхньому поверсі?",a="Око Азори — зачарований кристал для ясновидіння на столі у верхньому святилищі. Торкнувшись його, спостерігач може зазирнути крізь відстань і стежити за околицями Вежі Ілґалара.",al={"куля на верхньому поверсі","око азори","кришталева куля азори"}}},fp="14,299,27.497.0,21.444.1,29.185.0,34.181.0,34.218.0,42.200.0"}
P.entries["subzone:tower-of-eldara"] = {n="Вежа Ельдари",s="Вежа Ельдари — прадавній запечатаний шпиль нічних ельфів на далекому північно-східному мисі над Затокою Бур в Азшарі. Хоча її давно покинули, міцні кам'яні мури пережили Розкол і досі мовчки здіймаються над узбережжям, де нишпорять агресивні прибережні звірі.",h="Вежа Ельдари — прадавній запечатаний шпиль нічних ельфів на далекому північно-східному мисі над Затокою Бур в...",kw={"вежа","ельдара","азшара","затока бур","калдореї","високородні","розкол"},ang={["class:Mage"]="Як і багато споруд Високородних по всій Азшарі, запечатана вежа, найпевніше, колись гула від таємних студій, аж доки її не замкнули від втручання смертних.",["race:NightElf"]="Вежа Ельдари — щемке нагадування про велику імперію, якою правили ваші предки, перш ніж Королева Азшара й Високородні зруйнували прадавній світ."},sec={{t="Реліквія прадавньої Азшари",b="Вежа Ельдари, що стоїть на краю віддаленої скелі на північний схід від Затоки Бур, — самотнє свідчення величезної калдорейської імперії, яка колись панувала на цьому узбережжі. Як і більшість зруйнованих споруд Азшари, вона занепала після Великого Розколу тисячі років тому. Нині вхід міцно зачинений і загороджений від зовнішнього світу, тож ніщо не підказує, які реліквії чи зали приховані всередині. Довколишні береги повні небезпек: тут невпинно никають мурлоки, клешнясті макрури й хижі гідри, що відлякують усіх, крім найвідважніших мандрівників."}},faq={{q="Що таке Вежа Ельдари?",a="Це стародавня нічноельфійська вежа на північно-східній кручі Азшари, звідки видно Затоку Бур. Її збудували ще до Великого Розколу як частину розлогої імперії калдореїв, що колись охоплювала цей край.",al={"лор вежі ельдари","що це за вежа","вежа ельдари"}},{q="Чи можна потрапити у Вежу Ельдари?",a="Ні. Вежа зачинена й надійно запечатана від чужинців. Хай які зали чи сховища вціліли всередині, сучасним дослідникам туди дороги немає.",al={"чи можна зайти у вежу ельдари","як відчинити вежу ельдари","чи відкрита вежа"}},{q="Які загрози чатують навколо вежі?",a="Скелясті кручі й піщані пляжі довкола мису постійно патрулюють ворожі мурлоки, панцирні макрури й прибережні гідри.",al={"моби біля вежі ельдари","вороги навколо ельдари","істоти затоки штормів"}},{q="Де саме розташована вежа?",a="Її можна знайти на самому краєчку суходолу, що вдається у Велике Море, на північний схід через води Затоки Бур в Азшарі.",al={"розташування вежі ельдари","де вежа ельдари","як знайти ельдару"}}},fp="15,292,26.615.0,28.229.0,34.147.0,37.147.0,35.140.0"}
P.entries["subzone:trade-district"] = {n="Торговий Квартал",s="Торговий Квартал — гамірне торговельне серце Стормвінда, що лежить одразу за головною брамою й Долиною Героїв. Це головний осередок і для шукачів пригод, і для містян: тут міський банк, аукціонний дім, реєстр гільдій і різноманітні крамниці.",h="Торговий Квартал — гамірне торговельне серце Стормвінда, що лежить одразу за головною брамою й Долиною Героїв.",kw={"торговий квартал","аукціонний дім","банк","гільдії","крамниці","стормвінд"},ang={["faction:Alliance"]="Для поборників Альянсу Торговий Квартал — головний осередок, де можна скористатися банком, торгувати через Аукціонний дім, організовувати гільдії й вирушати в політ над Східними Королівствами."},sec={{t="Роздоріжжя торгівлі",b="Пройшовши під кам'яними арками з Долини Героїв, мандрівники потрапляють просто в Торговий Квартал. Ця жвава відкрита площа — головний ринок і логістичний вузол Стормвінда. У її центрі стоїть Аукціонний дім, а неподалік — Скарбниця Стормвінда, головний банк міста, і популярна таверна «Позолочена Троянда». Квартал пов'язує воєнний анклав Старого Міста, тиху Соборну Площу й чародійні вулиці Кварталу магів, тож монети, сировина й спорядження для пригод швидко обертаються королівством."},{t="Базари й зали гільдій",b="Уздовж брукованих вулиць і каналів обабіч можна придбати будь-який необхідний товар. Зброярі в «Арсеналі Веллера» й «Збройні Левового Серця» постачають клинки й кольчуги, лукарі продають луки в «Порожньому Сагайдаку», а ремісничі ятки пропонують усе — від свіжих квітів до добірних витриманих вин із Виноробні Ґалліни. Одразу за брамою Центр для гостей Стормвінда реєструє нові статути й узори табардів для організованих гільдій шукачів пригод, а піднятий пандус на східному боці веде до Сідала Грифона, поєднуючи торговельне життя столиці з рештою земель Альянсу."}},faq={{q="Де розташований Торговий Квартал?",a="Торговий Квартал лежить одразу за головною міською брамою й Долиною Героїв. Він з'єднується із Соборною Площею на північному заході, Старим Містом на сході та Кварталом магів за каналами на південному заході.",al={"розташування торгового кварталу","де торговий квартал","як дістатися до торгового кварталу"}},{q="Де знайти банк і заїзд?",a="Лічильна палата Стормвінда (головний банк міста) і заїзд «Позолочена троянда» стоять уздовж південно-західного краю Торгового Кварталу, просто біля головної вулиці.",al={"банк торгового кварталу","де позолочена троянда","банк стормвінда"}},{q="Де в Стормвінді зареєструвати гільдію чи створити табард?",a="У Центрі для відвідувачів Стормвінда: він ліворуч, щойно ви входите в Торговий Квартал від міської брами. Там працюють Голова Гільдії та майстри, що виготовляють табарди.",al={"гільдмайстер стормвінда","реєстратор гільдій","створити гільдію"}},{q="Де в Торговому Кварталі сісти на грифона?",a="Кам'яний пандус на східному боці Торгового Кварталу веде просто нагору до Сідала Грифона, звідки розпорядник польотів відправляє грифонів по всьому королівству й далі.",al={"майстер польотів стормвінда","сідало грифона стормвінд","де майстер польотів"}}},fp="14,293,26.599.0,23.612.0,36.228.0,38.188.0,60.170.0,58.169.0"}
P.entries["subzone:trade-quarter"] = {n="Торговий Квартал",s="Торговий Квартал — центральне осердя Андерсіті, що лежить просто під підйомниками з Руїн Лордерона. Це живе економічне серце Відступників: тут головні банківські сховища, аукціонний ринок і найважливіші міські служби. Від цього кільцевого вузла склепінчасті коридори розходяться до навколишніх кварталів.",h="Торговий Квартал — центральне осердя Андерсіті, що лежить просто під підйомниками з Руїн Лордерона.",kw={"торговий квартал","андерсіті","банк","аукціон","корчма","відступники"},ang={["faction:Horde"]="Для посланців-орків, тауренів чи тролів, що прибувають до Галявин Тірісфалю, Торговий Квартал — чужий, тінистий торговий осередок їхніх північних союзників.",["race:Undead"]="Торговий Квартал уособлює те, як швидко Відступники повернули цивілізований лад: підземні темниці вони перетворили на квітучий ринок, що фінансує їхнє виживання."},sec={{t="Серце склепів",b="Спустившись із розтрощеної поверхні Лордерона, мандрівники сходять із підйомників у відлунний кам'яний простір Торгового Кварталу. Квартал має ярусне кругле планування: на центральному майданчику — міська скарбниця й центральний банк, обрамлені мостами над отруйними стічними каналами. На навколишніх терасах гудуть торговці, гільдійні реєстратори й аукціоністи, що торгуються в моторошному присмерку. Навіть найпростіший нічліг тут сповнений прагматизму Відступників: місцева корчма пропонує не м'які ліжка, а дерев'яні труни без оббивки. Від цього центрального вузла кам'яні арки ведуть до спеціалізованих кварталів міста, тож саме тут неминуче перетинаються всі справи столиці."}},faq={{q="Де розташований Торговий Квартал?",a="Торговий Квартал займає самісінький центр Андерсіті. Спустившись у столицю підйомниками під Руїнами Лордерона, ви одразу виходите на верхнє кільце кварталу.",al={"розташування торгового кварталу","як знайти торговий квартал","де торговий квартал"}},{q="Які послуги є в Торговому Кварталі?",a="Тут є центральний банк Андерсіті, аукціон на зовнішньому кільці, головний заїзд, приборкувач кажанів для польотів, реєстратори гільдій і наставники різних ремесел, зокрема міський наставник кулінарії.",al={"послуги торгового кварталу","що в торговому кварталі","де банк підміської"}},{q="Чому в заїзді стоять труни?",a="Тілу Відступників не потрібен справжній сон, і багато хто з них має звички, що пасують їхньому неживому стану. Заїзд пропонує прості дерев'яні труни без оббивки замість звичайних ліжок — звична зручність для мерців, хоча живих гостей це неабияк бентежить.",al={"труни в корчмі підміської","чому скриньки в корчмі","ліжка підміської"}},{q="Хто цей торговець, що ховається під мостами?",a="Джеремая Пейсон заробляє на життя під одним із центральних мостів, що ведуть до банку. Поки звичайні купці нагорі торгують зброєю й ремісничими товарами, Пейсон продає цікавим перехожим живих тарганів-улюбленців.",al={"джеремая пейсон","хлопець із тарганами підміської","хто продає тарганів"}}},fp="13,354,19.694.0,35.206.0,45.214.0,33.269.0,46.212.0"}
P.entries["subzone:tradesmen-s-terrace"] = {n="Тераса Ремісників",s="Південна Тераса Ремісників — гамірне торговельне серце Дарнасуса, що розкинулося вздовж південного краю міста. Під розлогими дерев'яними склепіннями столиці нічних ельфів тут зібралися майстри, купці й місцевий аукціонний дім. Тераса — головна торгова ланка, що пов'язує ремісників із шукачами пригод, які мандрують Тельдрассилом і далеко за його межами.",h="Південна Тераса Ремісників — гамірне торговельне серце Дарнасуса, що розкинулося вздовж південного краю міста.",kw={"тераса ремісників","дарнасус","аукціонний дім","торгівля","крамниці","купці"},ang={["faction:Alliance"]="Мандрівникам з Альянсу, що прибувають через Селище Рут'теран, тераса дає доступ до банку, аукціоністів і найпотрібніших товарів, перш ніж вирушити вглиб Калімдору.",["race:NightElf"]="Для нічних ельфів Тераса Ремісників — рідкісний осередок жвавої міської торгівлі, влаштований так, щоб зберегти мирні крони Дарнасуса без галасливої промисловості інших рас."},sec={{t="Торговий осередок Дарнасуса",b="Південна Тераса Ремісників займає південну частину Дарнасуса й зосереджує в собі все торговельне життя столиці. Більша частина міста віддана тихому спогляданню, диким святилищам і духовним обов'язкам, а тут збираються крамарі, ремісники й купці, що обслуговують і місцевих калдореїв, і мандрівників з усього Альянсу. Тут є головний аукціонний дім Дарнасуса, крамниці з припасами й товарами для ремесел — тож саме тут збираються в дорогу ті, хто вирушає в дикі краї. Широкі стежки ведуть звідси на північ, просто до Тераси Воїна, і на захід — до спокійних вод Храмових Садів і величного Храму Місяця."},{t="Майстри й торгівці",b="Калдорейські ремесла понад усе шанують гармонію з природою, і тутешні крамниці віддзеркалюють цю тонку рівновагу. Навіть у буденній торгівлі тераса обходиться без ревучих горнил і чаду, звичних для дворфійських чи людських майстерень: тут віддають перевагу тихому каменю, дбайливо дібраній деревині й тканим виробам. Для шукачів пригод, яким потрібні торгові угоди, лагодження спорядження чи матеріали з густих віт Тельдрассила, тераса — головний діловий осередок північного Калімдору."}},faq={{q="Що таке Тераса Ремісників?",a="Тераса Ремісників — південний торговий квартал Дарнасуса, торговий осередок нічноельфійської столиці. Тут зосереджено більшість міських купців і майстрів, а також центральний аукціон.",al={"що це за місце","тераса ремісників інформація","тераса ремісників дарнасус"}},{q="Де в Дарнасусі аукціон?",a="Аукціон Дарнасуса розташований саме тут, на Терасі Ремісників. Він відкриває мандрівникам, торговцям і місцевим доступ до торгівлі всього міста й Альянсу.",al={"аукціон дарнасуса","де аукціонний дім дарнасуса","де аукціон"}},{q="Як звідси дістатися інших кварталів?",a="Стежки від Тераси Ремісників ведуть на північ до Тераси Воїна і на захід — до Храмових Садів і височенного Храму Місяця.",al={"виходи з тераси ремісників","куди веде тераса","як піти з тераси ремісників"}},{q="Які торговці є в цьому кварталі?",a="На терасі багато крамарів загального товару, постачальників ремісничих матеріалів і майстрів, що дбають про щоденні потреби, лагодження й товари з усього Тельдрассила.",al={"торговці тераси ремісників","що можна купити","крамниці ремісників"}}},fp="19,370,31.671.0,20.467.0,28.216.0,40.158.0,45.140.0,49.169.0"}
P.entries["subzone:train-depot"] = {n="Депо потяга",s="Депо потяга — підземний транспортний вузол одразу під наземними входами до Гномреґана в Дун Мороґу. Колись гамірний осередок гномського залізничного руху, тепер воно кишить ворожими гномами-прокаженими й трогами-загарбниками.",h="Депо потяга — підземний транспортний вузол одразу під наземними входами до Гномреґана в Дун Мороґу.",kw={"депо потяга","гномреґан","дун мороґ","троги","намдо біззфіззл"},ang={["profession:Engineering"]="Інженери, що шукають рідкісні креслення, часто розвідують нижні платформи депо, де серед уламків досі торгують уцілілі гноми-крамарі на кшталт Намдо Біззфіззла.",["race:Gnome"]="Для гномів-вигнанців покинуте депо — трагічне видовище, що показує руїну досконалих транспортних систем, які колись об'єднували їхній підземний мегаполіс."},sec={{t="Зруйнований транспортний вузол",b="Депо потяга, що лежить біля підніжжя великого підйомника з Дун Мороґу, колись було головним вузлом залізничного сполучення в підземному диві Гномреґана. Сьогодні платформи й колії лежать у руїнах. Викиди, що опромінили місто, перетворили робітників, які лишилися, на шалених гномів-прокажених, а підземні троги заполонили колії. Дослідники, що спускаються до зруйнованого міста, мусять пройти цей плацдарм, щоб дістатися глибших секторів, як-от Годинникового Ходу, Вантажної Кімнати й внутрішніх інженерних цехів."}},faq={{q="Де розташоване Депо потяга?",a="Депо потяга лежить просто під підйомником, що спускається з поверхні Дун Мороґа. Це один із зовнішніх порогів, які треба минути, перш ніж заглибитися в серце Гномреґана.",al={"розташування депо потяга","як дістатися до депо потяга","вхід у депо потяга"}},{q="Які істоти населяють Депо потяга тепер?",a="Депо заполонили дикі троги, що прорили ходи з глибин землі, і нещасні гноми-прокажені, які втратили розум під час радіоактивної катастрофи.",al={"вороги депо потяга","моби депо потяга","хто в депо потяга"}},{q="Куди ведуть шляхи з Депо потяга?",a="Проходи ведуть на захід до Годинникового Ходу й Вантажної Кімнати, а в північній майстерні є чорний хід униз, до верхніх Інженерних Лабораторій.",al={"виходи з депо потяга","куди веде депо потяга","зв'язки депо потяга"}},{q="Хто ховається в Депо потяга?",a="Намдо Біззфіззл, постачальник інженерного приладдя, примудряється виживати, сховавшись під північним краєм головної платформи на нижньому рівні депо.",al={"намдо біззфіззл","нпс депо потяга","торговець депо потяга"}}},fp="11,222,20.566.0,33.171.0,43.153.0,45.154.0,33.145.0"}
P.entries["subzone:tundrid-hills"] = {n="Тундридські Пагорби",s="Тундридські Пагорби — суворий засніжений відтинок високогір'я в південно-центральному Дун Мороґу, просто на захід від Кар'єру Гол'Болар. Скелясті перевали, де водиться небезпечна гірська звірина, випадкові мандрівники перетинають нечасто.",h="Тундридські Пагорби — суворий засніжений відтинок високогір'я в південно-центральному Дун Мороґу, просто на...",kw={"тундридські пагорби","високогір'я","хижаки","мисливці","дун мороґ","навпростець"},ang={["class:Hunter"]="Обвіяні вітрами скелі — суворі мисливські угіддя, повні витривалих звірів, що пристосувалися до нещадного гірського холоду Дун Мороґу.",["race:Dwarf"]="Для горян Айронфорджа ці висоти — повсякчасне нагадування, що дика глушина й ворожі тролі Морозогриви тиснуть упритул до серця Дун Мороґу."},sec={{t="Підступна глушина",b="Простягшись між Долиною Холодного Хребта та низинами східного Дун Мороґу, Тундридські Пагорби пропонують суворий шлях навпростець тим, хто хоче оминути головні дороги через Харанос. Та за зручність доводиться дорого платити. Зубчастими засніженими схилами нишпорять люті хижаки, тож ці землі небезпечні для необачних мандрівників, які сходять з уторованої стежки, не оголивши зброї."}},faq={{q="Де розташовані Тундридські Пагорби?",a="Тундридські Пагорби простягаються в південно-центральній частині Дун Мороґа, на захід від Кар'єру Гол'Болар. Вони утворюють природну височину на південь від головної дороги, що веде з Хараноса на схід.",al={"розташування тундридських пагорбів","де тундридські пагорби","тундридські пагорби на мапі"}},{q="Навіщо комусь іти через Тундридські Пагорби?",a="Шукачі пригод іноді долають ці суворі хребти навпростець між Долиною Холодного Хребта й східним Дун Мороґом, оминаючи звичні шляхи між поселеннями, хоча це набагато небезпечніше, ніж триматися доріг, які патрулює варта.",al={"навіщо йти через тундридські пагорби","скорочення тундридськими пагорбами"}},{q="Які загрози чатують у Тундридських Пагорбах?",a="На пагорбах живуть люті місцеві звірі, звиклі до морозних висот, тож мало хто ходить сюди без зброї напоготові.",al={"що тут живе","вороги тундридських пагорбів","монстри тундридських пагорбів"}}},fp="13,232,24.401.0,36.205.0,50.237.0,47.126.0"}
P.entries["subzone:twilight-base-camp"] = {n="Сутінковий Базовий Табір",s="Сутінковий Базовий Табір — укріплена застава культу Молота Присмерку в посушливих пустелях Силітусу. Це діюче місце обрядів, де культисти збираються, щоб спілкуватися зі стихійними силами й утілювати свій апокаліптичний задум. Табір вирізняють дивні Камені Вітру й добре озброєні фанатики культу.",h="Сутінковий Базовий Табір — укріплена застава культу Молота Присмерку в посушливих пустелях Силітусу.",kw={"сутінковий базовий табір","молот присмерку","камені вітру","культисти","силітус","стихії"},ang={["class:Paladin"]="Темні апокаліптичні обряди культистів — пряма загроза миру, що вимагає праведного суду Святого Світла.",["class:Shaman"]="Відверте спотворення й поневолення духів стихій біля Каменів Вітру в таборі — образа для кожного шамана, відданого збереженню духовної гармонії."},sec={{t="Оплот загибелі",b="Сутінковий Базовий Табір, що стоїть серед безлюдних пісків Силітусу, — один із кількох анклавів, які заснував культ Молота Присмерку. Застава аж кишить фанатиками, геомантами й закликачами каменю, які віддали себе виклику руйнівних стихійних сил. Оточений гострозубими обрядовими каменями, табір слугує плацдармом, звідки ватажки на кшталт Сутінкового Хранителя Гавунта й Сутінкового Володаря Еверуна спрямовують зусилля, щоб наблизити кінець Азероту, — і відкрито кидають виклик силам Цитаделі Кенаріуса, що намагаються повернути краю рівновагу."},{t="Камені Вітру",b="По всій заставі розкидані загадкові пам'ятки, відомі як Камені Вітру, — від менших провідників сили до великих монолітів. Таємничими закляттями й регаліями культу Молот Присмерку крізь ці осередки затягує хаотичних духів стихій просто у фізичний світ. Зірвати ці обряди — найперша мета для мандрівників і розвідників, які прагнуть не дати впливу культу поширитися Калімдором."}},faq={{q="Що таке Сутінковий Базовий Табір?",a="Це укріплена застава апокаліптичного культу Молот Присмерку в пустелях Силітусу, де культисти правлять темні ритуали й викликають могутніх елементальних істот.",al={"сутінковий табір силітус","що таке сутінковий базовий табір","табір культистів силітусу"}},{q="Хто контролює цей табір?",a="Заставу тримають фанатики Молота Присмерку під проводом наглядачів, як-от Сутінкового Хранителя Гавунта та рідкісного ватажка — Сутінкового Володаря Еверуна.",al={"хто веде сутінковий табір","лідер сутінкового табору","хто головний"}},{q="Що це за дивні камені в таборі?",a="Це вітрові камені — містичні провідники різного розміру, за допомогою яких культисти пробивають межі між світами й змушують елементальних істот служити собі.",al={"вітрові камені","менший вітровий камінь","більший вітровий камінь силітус"}},{q="Навіщо Молот Присмерку прийшов у Силітус?",a="Культ вабить прадавня хаотична енергія, що дрімає під пісками Силітусу. Він прагне пробудити темні сили й викликати елементалів, щоб накликати загибель світу.",al={"навіщо молот присмерку в силітусі","мета сутінкового культу"}}},fp="18,330,17.529.0,15.444.0,31.173.0,23.164.0,40.165.0,42.188.0"}
P.entries["subzone:twilight-outpost"] = {n="Сутінкова Передова",s="Сутінкова Передова — укріплений табір культу Молота Присмерку серед південно-західних пісків Силітусу. Він лежить трохи на північний захід від прадавньої Стіни Скарабея і слугує плацдармом, де культисти правлять темні обряди, щоб спілкуватися зі стихійними жахіттями й викликати їх.",h="Сутінкова Передова — укріплений табір культу Молота Присмерку серед південно-західних пісків Силітусу.",kw={"сутінкова передова","молот присмерку","камені вітру","стіна скарабея","культисти","силітус"},ang={["class:Paladin"]="Нігілістичний фанатизм Молота Присмерку — образа Світла, і він вимагає святого гніву, щоб очистити пустелю від їхніх мерзенних викликів.",["class:Shaman"]="Молот Присмерку псує й підкоряє духів стихій через свої Камені Вітру, зневажаючи природну рівновагу стихій, яку прагнуть зберегти шамани."},sec={{t="Оплот шепотів",b="Сутінкова Передова, захована в південно-західній частині Силітусу, — одна з кількох великих твердинь культистів, розкиданих пустелею. Розташована в тіні велетенської Стіни Скарабея й на захід від Табору Бронзоборода, застава аж кишить фанатичними сутінковими месниками, геолордами й закликачами каменю. Під проводом ватажків на кшталт Сутінкового Хранителя Екзетера й рідкісного Сутінкового Володаря Еверуна ці фанатики невтомно трудяться на службі своїх божевільних апокаліптичних господарів."},{t="Камені Вітру",b="По всьому табору розкидані загадкові Камені Вітру — від Менших до Великих провідників. За допомогою зачарованих культистських регалій і мерзенних заклять культ використовує ці моноліти, щоб прорватися в Царство Стихій і витягти звідти командирів Безодні та володарів стихій. Для шукачів пригод, яким стане сміливості проникнути в лави культу, зірвати ці виклики — один із головних способів дати відсіч впливу культу в пустелі."}},faq={{q="Де розташована Сутінкова Передова?",a="Сутінкова Передова лежить у далекому південно-західному куті Силітусу, на північний захід від стародавньої Стіни Скарабея і просто на захід від дворфійського Табору Бронзоборода.",al={"розташування сутінкової передової","де сутінкова передова","знайти сутінкову передову"}},{q="Хто займає Сутінкову Передову?",a="Табір займає культ Молот Присмерку. У його лавах — різні смертні фанатики: сутінкові месники, геолорди, закликачі каменю й сутінкові майстри, а керують ними такі ватажки, як Сутінковий Хранитель Екзетер і Сутінковий Володар Еверун.",al={"хто на сутінковій передовій","вороги сутінкової передової","культисти в силітусі"}},{q="Що за Вітрові Камені є в таборі?",a="Вітрові Камені — від Менших до Великих — це містичні осердя, якими культ проламує межі стихійних світів. Культисти спрямовують крізь ці камені темну енергію, щоб викликати в Азерот могутніх повелителів стихій і командирів Безодні.",al={"що таке вітрові камені","більший вітровий камінь силітус","менший вітровий камінь силітус"}},{q="Чому Молот Присмерку збирається біля Стіни Скарабея?",a="Культ вабить могутня й прадавня темна енергія, що дрімає під Силітусом. Табори біля Стіни Скарабея дають йому змогу проводити ритуали виклику елементалів і приборкувати хаотичні сили, що вирують за запечатаною брамою.",al={"чому культисти в силітусі","мета молота присмерку в силітусі"}}},fp="16,286,21.497.0,15.480.0,38.178.0,34.248.0,43.239.0,59.241.0"}
P.entries["subzone:twilight-post"] = {n="Сутінкова Застава",s="Сутінкова Застава — укріплений табір, який культ Молота Присмерку заснував на північному заході Силітусу. Вона лежить далеко на захід від Цитаделі Кенаріуса й на північний захід від Сутінкового Базового Табору та має велике значення для обрядів виклику стихій. Шукачі пригод, що сюди навідуються, стикаються з фанатичними культистами та Каменями Вітру, через які ті зв'язуються з потойбічними силами.",h="Сутінкова Застава — укріплений табір, який культ Молота Присмерку заснував на північному заході Силітусу.",kw={"сутінкова застава","молот присмерку","камені вітру","культисти","силітус","еверун"},ang={["class:Druid"]="Коло Кенарія пильно стежить за тим, як множаться застави культу: темні стихійні обряди культистів загрожують ще більше розхитати крихку, пошрамовану рівновагу Силітусу.",["class:Shaman"]="Молот Присмерку спотворює священне спілкування зі стихіями, силоміць викликаючи й підкоряючи духів через Камені Вітру, які можна знайти в таких заставах, як ця."},sec={{t="Оплот стихійного фанатизму",b="Сутінкова Застава, захована серед пустельних пісків північно-західного Силітусу, — форпост культу Молота Присмерку. Табір населяють добре озброєні захисники й обрядовці, серед них сутінкові месники, геолорди й закликачі каменю. Їх очолюють Сутінковий Хранитель Майна та рідкісний фанатик Сутінковий Володар Еверун. Як і інші табори, розкидані пустелею, застава зосереджена довкола прадавніх провідників виклику — Менших, звичайних і Великих Каменів Вітру. Темними обрядами й спілкуванням зі стихіями культисти використовують ці камені, щоб благати й підкоряти стихійних жахіть з потойбічних царств, загрожуючи хиткому миру, який підтримує в краї Коло Кенарія."}},faq={{q="Де розташована Сутінкова Застава?",a="Сутінкова Застава лежить у далекому північно-західному куті Силітусу, чималенько на захід від Цитаделі Кенаріуса й на північний захід від більшого Сутінкового Базового Табору.",al={"розташування сутінкової застави","де сутінкова застава","сутінкова застава на мапі силітусу"}},{q="Хто займає Сутінкову Заставу?",a="Заставу тримає культ Молот Присмерку. Тут перебувають, зокрема, Сутінковий Хранитель Майна і Сутінковий Володар Еверун, яких захищають лави сутінкових месників, геолордів і закликачів каменю.",al={"хто на сутінковій заставі","моби сутінкової застави","вороги сутінкової застави"}},{q="Що за вітрові камені є в таборі?",a="Вітрові камені — Менші, звичайні й Великі — це магічні провідники, за допомогою яких Молот Присмерку викликає елементальних істот і змушує їх служити собі.",al={"що таке вітрові камені","вітрові камені силітусу","менший вітровий камінь сутінкової застави"}},{q="Що Молот Присмерку робить у Силітусі?",a="Молот Присмерку зібрався в пустельних пустках Силітусу, щоб пробудити прадавні темні сили, які дрімають під пісками, і говорити з ними, а ще — поповнити свої лави, викликаючи елементалів.",al={"чому культисти в силітусі","мета молота присмерку силітус"}}},fp="13,369,31.701.0,31.167.0,31.203.0,43.193.0,51.197.0"}
P.entries["subzone:twilight-s-run"] = {n="Сутінковий Прохід",s="Сутінковий Прохід — відлюдна підземна печера, видовбана в північних горах Силітусу під Мисом Стаґгелма. Її зайняли фанатики культу Молота Присмерку, і тут, подалі від суворих пустельних вітрів, вони мають потаємний прихисток і обрядову твердиню.",h="Сутінковий Прохід — відлюдна підземна печера, видовбана в північних горах Силітусу під Мисом Стаґгелма.",kw={"сутінковий прохід","печера","молот присмерку","мис стаґгелма","вайрал підлий","силітус"},ang={["class:Paladin"]="У потаємних глибинах Сутінкового Проходу ховаються затяті нігілісти, чия служба темним силам — образа священних заповідей Світла."},sec={{t="Підземна твердиня",b="Сутінковий Прохід, захований у північних урвищах під Мисом Стаґгелма, дає культистам Молота Присмерку природний бастіон серед продутих вітрами небезпек Силітусу. Замість того щоб перечікувати піщані бурі чи битися з роями силітидів, що снують дюнами на поверхні, культисти ховаються в цих затінених тунелях: тут вони спілкуються з темними силами, стережуть обрядові матеріали й збирають свої загони. Під проводом наглядачів на кшталт Вайрала Підлого члени культу пильно й вороже стережуть печеру, готові вбити кожного цікавого мандрівника чи розвідника, що підійде надто близько до їхнього підземного табору."}},faq={{q="Де розташований Сутінковий Прохід?",a="Сутінковий Прохід — печера в північних горах Силітусу, просто біля скелястого підніжжя під Мисом Стаґгелма.",al={"де сутінковий прохід","розташування сутінкового проходу","як знайти сутінковий прохід"}},{q="Хто займає Сутінковий Прохід?",a="Печеру повністю контролюють прислужники Молота Присмерку, серед них Вайрал Підлий, сутінкові верховні володарі й сутінкові полум'яні жнеці.",al={"хто всередині сутінкового проходу","моби сутінкового проходу","хто живе в сутінковому проході"}},{q="Що культ робить у печері?",a="Культ використовує печеру як захищений редут і робочу заставу в Силітусі: тут він ховається від пустельної негоди й веде далі свою апокаліптичну справу.",al={"мета сутінкового культу печера силітус","чому культисти в сутінковому проході"}}},fp="14,256,22.649.0,32.120.0,28.159.0,41.158.0"}
P.entries["subzone:twilight-shore-darkshore"] = {n="Сутінковий Берег (Темне Узбережжя)",s="Сутінковий Берег — порізана смуга узбережжя на півдні Темного Узбережжя, що тягнеться на південь від Довгої Обмілини аж до кордону з Ашенвалем. Його похмурі, оповиті туманом пляжі перериваються стрімкими морськими кручами, острівцями й підступним прибоєм. Тут кишать агресивні племена мурлоків і ненажерливі морські хижаки на кшталт трешадонів.",h="Сутінковий Берег — порізана смуга узбережжя на півдні Темного Узбережжя, що тягнеться на південь від Довгої...",kw={"сутінковий берег","мурлоки","трешадони","узбережжя","темне узбережжя"},ang={["race:NightElf"]="Сутінковий Берег — самотній, оповитий туманом поріг між проклятими руїнами Темного Узбережжя й священними лісами предків в Ашенвалі."},sec={{t="Підступне узбережжя",b="Сутінковий Берег, що тягнеться на південь від Довгої Обмілини, повз руїни Амет'Арану, до Ашенвалю, — одна з найсуворіших і найнегостинніших ділянок Темного Узбережжя. Сірий пісок поступається гострим, побитим хвилями кручам і розкиданим скелястим острівцям. Тутешні води славляться ворожістю: той, хто попливе біля берега, наразиться на напади ревнивих трешадонів і морських повзунів, а на самих пляжах панують численні табори агресивних мурлоків."}},faq={{q="Де розташований Сутінковий Берег?",a="Він охоплює найпівденнішу прибережну смугу Темного Узбережжя: починається на південь від Довгого Розмиву (приблизно на захід від стародавніх руїн Амет'Аран) і тягнеться на південь аж до скелястих кордонів Ашенвалю.",al={"розташування сутінкового берега","де сутінковий берег","сутінковий берег на мапі"}},{q="Які загрози чатують на Сутінковому Березі?",a="На березі оселилися агресивні племена мурлоків, а в холодному прибої водяться войовничі трешадони, причаєнці й велетенські краби, що полюють на необережних мандрівників.",al={"моби сутінкового берега","небезпеки сутінкового берега","що на сутінковому березі"}},{q="Чому тут така нерівна місцевість?",a="На відміну від пласкіших і просторіших пляжів північніше, Сутінковий Берег порізаний гострими прибережними скелями, кам'янистими мілинами й острівцями біля берега — їх виточили невпинні удари хвиль Прихованого Моря.",al={"чому тут скелі","рельєф сутінкового берега"}}},fp="26,345,23.464.0,36.214.0,51.187.0,34.200.0"}
P.entries["subzone:twilight-vale"] = {n="Сутінкова Долина",s="Сутінкова Долина охоплює густі, затінені південні ліси Темного Узбережжя, що тягнуться до кордону з Ашенвалем. У її мороці никають осквернені фурболги, скажені ведмеді й люті нічні шаблезуби, тож сходити з дороги тут небезпечно. Це похмурий поріг між отруєним узбережжям і священними лісами на півдні.",h="Сутінкова Долина охоплює густі, затінені південні ліси Темного Узбережжя, що тягнуться до кордону з Ашенвалем.",kw={"сутінкова долина","фурболги","нічні шаблезуби","ведмеді","скверна","темне узбережжя"},ang={["class:Druid"]="Друїди, що мандрують між Темним Узбережжям і Ашенвалем, на власні очі бачать хворобу, що вразила створінь долини, — і це підкреслює, як нагально треба очистити землю.",["race:NightElf"]="Занепад південних лісів тяжко гнітить нічних ельфів, які оплакують осквернення місцевих звірів і падіння своїх сусідів-фурболгів так близько від порога Ашенвалю."},sec={{t="Небезпечний поріг",b="Сутінкова Долина, що простягається від давніх руїн Амет'Арану аж до кордону з Ашенвалем, огортає південь Темного Узбережжя вічними сутінками. Скверна, що охоплює північний Калімдор, глибоко вгризлася в місцевих звірів. Скажені ведмеді блукають поряд з дикими нічними шаблезубами, а темним лісом никають ворожі племена фурболгів. І вартові, і мандрівники радять триматися головної дороги: варто ступити між дерева бодай на кілька кроків — і чекай швидкої смертельної засідки."}},faq={{q="Де розташована Сутінкова Долина?",a="Сутінкова Долина — південна частина Темного Узбережжя. Вона починається одразу на південь від руїн Високородних — Амет'Аран — і тягнеться аж до прикордонного перевалу в Ашенваль.",al={"розташування сутінкової долини","де сутінкова долина","сутінкова долина на мапі"}},{q="Які загрози чатують у цьому лісі?",a="Долину заполонили хворі звірі й ворожі племена. Мандрівники натраплять на скажених ведмедів, агресивних нічних шаблезубів і спотворених фурболгів, які нападають на кожного, хто вдерся на їхні землі.",al={"монстри сутінкової долини","що в сутінковій долині","небезпеки сутінкової долини"}},{q="Чи безпечно подорожувати долиною?",a="Жодна глушина на Темному Узбережжі не буває цілком безпечною, але триматися второваної ґрунтової дороги набагато безпечніше, ніж продиратися крізь хащі. Зійшовши з битого шляху, ви опинитеся просто на шляху диких звірів.",al={"чи безпечна сутінкова долина","безпечний шлях з темного берега в ашенвейл"}},{q="Чому звірі в долині спотворені?",a="Темне Узбережжя тяжко постраждало від Третьої війни й руйнівної магії, що досі витає над північним Калімдором. Отруєна вода й залишки темної магії довели місцевих звірів до безуму, а мирних фурболгів зробили лютими.",al={"чому ведмеді скажені на темному березі","скверна фурболгів сутінкової долини"}}},fp="13,357,20.517.0,35.178.0,32.199.0,38.220.0,42.220.0"}
P.entries["subzone:twin-colossals"] = {n="Колоси-Близнюки",s="Колоси-Близнюки — пара височенних плато з прямовисними стінами, що панують над північно-західним обрієм Фераласу. Вони здіймаються високо над лісовим наметом, а вузький прохід між їхніми кручами — головний суходільний шлях, що сполучає Фералас із посушливими безводними землями Пустограю на півночі.",h="Колоси-Близнюки — пара височенних плато з прямовисними стінами, що панують над північно-західним обрієм...",kw={"колоси-близнюки","фералас","пустограй","марлі вішраннер","діамантова голова","парашути"},ang={["race:NightElf"]="Запаморочливі висоти й зіпсовані місячні колодязі неподалік нагадують про прадавню історію Фераласу та про тіні, що дедалі глибше підкрадаються в дикі землі."},sec={{t="Стовпи тропічного лісу",b="Колоси-Близнюки височіють над західними околицями Фераласу — це найвищі форми рельєфу в краї. Їхні прямовисні скелясті стіни чітко вирізняються на тлі неба й слугують безпомильними орієнтирами для мандрівників, що рушають на південь із Пустограю. Нижні схили зливаються з густими джунглями й землями, що тягнуться до Забутого Узбережжя, а вершини — це відлюдні плато високо над лісовим долом."},{t="Підкорення висот",b="Видертися прямовисними скелями пішки неможливо, проте вершини не зовсім безлюдні. Відважна нічна ельфійка на ім'я Марлі Вішраннер допомагає мандрівникам дістатися східного піку. Ті, хто підніметься, знайдуть на кам'яному плато тихий ставок — щоправда, у ньому живе незвично велика макрура на ім'я Діамантова Голова. А щоб шукачі пригод могли повернутися на землю, Калін Віндфлайт пропонує міцні парашути для спуску назад у джунглі."}},faq={{q="Де розташовані Колоси-Близнюки?",a="Колоси-Близнюки стоять на північному заході Фераласу, обабіч головної дороги, що веде на північ до Пустограю. Довколишня місцевість тягнеться на захід до Забутого Узбережжя.",al={"розташування колосів-близнюків","де колоси-близнюки","колоси на мапі"}},{q="Як дістатися на вершину Колосів-Близнюків?",a="На прямовисні кам'яні скелі звичайним способом не видертися. Мандрівники покладаються на нічну ельфійку Марлі Вішраннер, яка магією переносить їх на східну вершину.",al={"як залізти на колоси-близнюки","дістатися вершини колосів","завдання на вершину"}},{q="Хто живе на східній вершині?",a="На вершині східного піку ви знайдете Каліна Віндфлайта, що продає парашути для безпечного спуску, а ще глибокий ставок, у якому живе величезна макрура на прізвисько Діамантова Голова.",al={"нпс на вершині колосів","хто на плато","діамантова голова фералас"}},{q="Як безпечно спуститися з вершини?",a="Калін Віндфлайт продає на східній вершині особливі Колосальні парашути: з ними мандрівники можуть стрибнути зі скель і плавно спланувати в джунглі Фераласу.",al={"спуск із колосів-близнюків","стрибок із колосів","парашут колосів"}}},fp="14,286,25.426.0,20.464.0,37.172.0,47.153.0,32.181.0,40.173.0"}
P.entries["subzone:tyr-s-hand-abbey"] = {n="Абатство Руки Тіра",s="Абатство Руки Тіра — доглянуте святилище всередині укріпленого бастіону Руки Тіра на південному сході Східних Чумних Земель. Ним володіють фанатики Багряного Хрестового Походу, і воно слугує допоміжним осередком богослужіння й навчання поряд із величною Багряною Базилікою.",h="Абатство Руки Тіра — доглянуте святилище всередині укріпленого бастіону Руки Тіра на південному сході Східних...",kw={"абатство руки тіра","рука тіра","багряний хрестовий похід","головна зала","бібліотечне крило","зала зброї"},ang={["class:Paladin"]="Для святих воїнів абатство — трагічне спотворення спадщини Срібної Длані: колись освячене місце молитви стало бастіоном фанатизму й кровожерливості.",["class:Priest"]="Бібліотечне Крило зберігає рештки класичного вчення Святого Світла, хоч і пропущені крізь викривлений і нав'язливий фільтр Багряного Хрестового Походу."},sec={{t="Святилище фанатиків",b="Поки велична Багряна Базиліка панує над обрисами Руки Тіра, абатство є тихішим, практичним осередком побожності й військової доктрини Багряного Хрестового Походу. Його архітектура дуже схожа на традиційні споруди Святого Світла, як-от Абатство Нортшира в Лісі Елвінн: центральна Головна Зала, а обабіч неї — Зала Зброї та окреме Бібліотечне Крило. Попри невпинні жахіття Чумних Земель, Похід ретельно доглядає абатство й люто захищає його монастирські галереї від усіх чужинців."}},faq={{q="Для чого слугує Абатство Руки Тіра?",a="Це допоміжна релігійна й господарська споруда Багряного Хрестового Походу в Руці Тіра. Головні церемонії відбуваються у великій Базиліці, а абатство дає житло й місце для тренувань і навчання — тут є Зала Зброї та Бібліотечне Крило.",al={"що це за будівля","призначення абатства руки тіра","що відбувається в абатстві"}},{q="Чому воно схоже на Абатство Нортшира?",a="Обидві споруди збудовано за типовими лордеронськими й стормвіндськими проєктами монастирів Церкви Святого Світла: будівля поділена на головну залу зібрань, крило для бойових вправ і сховище священних текстів.",al={"клон нортширу","чому схоже на нортшир","планування абатства"}},{q="Хто контролює абатство зараз?",a="Абатство повністю в руках Багряного Хрестового Походу. Як і все добре укріплене місто Рука Тіра, його люто обороняють солдати-хрестоносці, жерці й паладини, що нападають на кожного, хто не носить їхніх барв.",al={"хто володіє абатством руки тіра","чи багряний похід тут"}},{q="Чи можна вдарити в дзвін на дзвіниці?",a="У вежі абатства висить дзвін, над яким з'являється курсор взаємодії, як над тривожними дзвонами в портових містах на кшталт Буті Бей, але поки що удар по ньому не дає ні звуку, ні жодного відгуку.",al={"церковний дзвін","дзвін дзвіниці","взаємодія з дзвоном"}}},fp="16,280,24.533.0,34.242.0,39.246.0,33.231.0,40.199.0"}
P.entries["subzone:uldaman"] = {n="Ульдаман",s="Ульдаман, висічений глибоко під північними горами Пустищ, — прадавнє сховище титанів, що сягає часів упорядкування світу. Нещодавно розпечатане дворфськими копачами, воно таїть у своїх залах поховану правду про походження дворфів — а разом із нею лютих трогів і пильних кам'яних вартових.",h="Ульдаман, висічений глибоко під північними горами Пустищ, — прадавнє сховище титанів, що сягає часів...",kw={"ульдаман","титани","троги","земляни","диски норґаннона","архедас","дворфи","пустища"},ang={["profession:Mining"]="Оброблені титанами зали мають багаті жили рідкісних земель і металів, яких тисячоліттями ніхто не торкався, хоча видобуток означає ризик потрапити в засідку трогів чи під удар пробуджених кам'яних вартових.",["race:Dwarf"]="Ульдаман — поріг до вашої найдавнішої спадщини. Поколіннями клани Айронфорджа гадали, звідки вони взялися; відповідь викарбувано на кам'яних дисках, похованих у цих кишучих трогами залах."},sec={{t="Сховище перших творінь",b="Ульдаман звели вартові титанів як підземну твердиню й дослідницький осередок. Коли перші досліди з формування живого каменю породили потворних трогів, титани запечатали свої невдалі творіння в стазисних камерах сховища й почали заново — і врешті створили кам'яношкірих землян. У найглибших залах з часом опинилися важливі архіви, зокрема легендарні Диски Норґаннона, які стережуть кам'яний хранитель Архедас і велетка Айроная. Згодом кам'яношкірі земляни дали початок дворфам, а їхня колиска лежала похована й забута під пагорбами."},{t="Розкопки й смута",b="Коли шукачі з Айронфорджа пробилися крізь зовнішні ворота Ульдамана, їхні кайла ненароком розкололи стазисні камери. Полчища пробуджених трогів заполонили верхні тунелі, відкинули дворфські загони й відрізали перші ділянки розкопок. Хаосу додали дворфи Темного Заліза, що прийшли в руїни по артефакти неймовірної сили для свого вогняного володаря Рагнароса. Нині глибокі шахти лишаються полем бою між ворожими загонами копачів, кровожерними трогами й конструктами титанів, які прокидаються, щоб розтрощити будь-якого зайду, хай якого він клану чи мети."}},faq={{q="Що таке Ульдаман?",a="Ульдаман — величезна підземна споруда титанів на північному кордоні Пустищ. Її збудували на світанку світу, щоб ізолювати невдалі експерименти титанів і зберігати величезні історичні записи, передусім Диски Норґаннона.",al={"лор ульдамана","що це за місце","про ульдаман"}},{q="Чому Ульдаман важливий для дворфів?",a="Дворфійські перекази кажуть, що їхні предки, кам'яношкірі земляни, були створені в спорудах титанів на кшталт Ульдаману. Якщо знайти й розшифрувати Диски Норґаннона, поховані в серці руїн, можна дізнатися остаточну правду про походження дворфів.",al={"чому дворфам важливий ульдаман","походження дворфів","диски норганнона"}},{q="Чому руїни кишать трогами?",a="Троги були першою спробою титанів створити кам'яних слуг. Коли експеримент не вдався, титани замкнули їх у стазисних сховищах Ульдаману. Шахтарі з Айронфорджа випадково пробили ці загони, і троги вирвалися в коридори та довколишні гори.",al={"звідки трогги","чому тут трогги","походження троггів"}},{q="Що тут роблять дворфи Темного Заліза?",a="Загони Темного Заліза шукають стародавні артефакти титанів, сподіваючись відкопати могутні реліквії, як-от Диски Норґаннона, для свого стихійного господаря — Володаря вогню Рагнароса.",al={"темне залізо в ульдамані","чому тут темне залізо"}},{q="Хто охороняє найнижчі зали?",a="Найглибше сховище стереже Архедас — величезний кам'яний хранитель, якому доручено берегти комплекс і його знання разом із легіоном живих кам'яних конструктів і големів.",al={"архедас","бос ульдамана","страж ульдамана"}}},fp="7,287,32.582.0,22.547.1,16.243.0,40.249.0,35.280.0,42.181.0,31.187.0"}
P.entries["subzone:undercity"] = {n="Андерсіті",s="Вирізане під розтрощеним палацом Столиці, Андерсіті служить розлогою підземною твердинею Відступників. Колись плетиво королівських склепів, підземель і каналізації, розширене Погибеллю, його захопила Сильвана Віндраннер і перекувала на добре укріплену столицю своєї вільної нежиті.",h="Вирізане під розтрощеним палацом Столиці, Андерсіті служить розлогою підземною твердинею Відступників.",kw={"андерсіті","столиця","сильвана","катакомби","підземне місто","лордерон","відступники"},ang={["faction:Horde"]="Підземне місто — головний військовий бастіон Орди у Східних Королівствах, хоч його тьмяні, просякнуті аптекарськими випарами ходи випробовують витримку гостей із Калімдору.",["race:Undead"]="Андерсіті — живе серце цивілізації Відступників: прихисток, збудований із руїн і склепів вашого колишнього життя, де ви захищені і від Погибелі, і від живих."},sec={{t="Від королівських склепів до бастіону Погибелі",b="До Третьої війни підземні ходи під Столицею — стольним містом Лордерону — знали як Андерсіті: величезну мережу каналізації, королівських катакомб і підземель. Саме тут Альянс колись ув'язнив полоненого вождя Орґріма Думгаммера, і тут найбідніші городяни перебивалися в темряві. Під час падіння Лордерону принц Артас Менетіл наказав своїй Погибелі розширювати ці глибини до підземного осідку влади. Коли Король-Ліч прикликав Артаса до Нортренду, лицар смерті лишив будівництво незавершеним."},{t="Столиця Відступників",b="Серед громадянської війни в Чумних Землях Сильвана Віндраннер згуртувала ту нежить, чий розум вирвався з лещат Короля-Ліча. Скинувши жахолордів і вигнавши суперників, новоназвані Відступники заявили права на підземний комплекс. Вони довершили покручений лабіринт катакомб, розпочатий Погибеллю, і укріпили його в неприступну твердиню під мовчазними руїнами колишнього королівства. Нині Темна Леді править своїм народом з його отруєних залів."}},faq={{q="Чи було Андерсіті тут ще до того, як його захопила нежить?",a="Так, хоча й набагато меншим. За часів Королівства Лордерон під палацом були стародавні королівські склепи, темниці й міська каналізація, де жили бідняки й де тримали знатних в'язнів — серед них і полоненого вождя орків Оргріма Думхаммера.",al={"походження андерсіті","чи андерсіті завжди тут було","історія андерсіті"}},{q="Хто насправді збудував сучасне Андерсіті?",a="Розбудову почав принц Артас Менетіл, який хотів зробити тут осередок влади Погибелі в Лордероні. Коли Артаса відкликали до Нортренду, Сильвана Віндраннер і її Відступники захопили недобудовані тунелі й роками розкопували та укріплювали їх, доки ті не стали містом-фортецею, яке ми бачимо сьогодні.",al={"хто створив андерсіті","хто збудував андерсіті","будівництво андерсіті"}},{q="Чому жити під землею, а не відбудувати місто нагорі?",a="Руїни Столичного Міста на поверхні відкриті для нападів Багряного Хрестового Походу, решток Погибелі й Альянсу. Підземні катакомби від природи легко обороняти, вони сховані від чужих очей і добре пасують нежиті, якій не потрібні ні денне світло, ні тепло, ні свіже повітря.",al={"чому жити під землею","чому не відбудувати лордерон","чому андерсіті"}},{q="Хто править Андерсіті?",a="Містом править Леді Сильвана Віндраннер, Королева Баньші й володарка Відступників, з королівських покоїв глибоко в надрах комплексу.",al={"лідер андерсіті","хто править андерсіті","хто керує андерсіті"}}},fp="9,323,36.548.0,20.498.0,54.279.0,40.314.0,58.283.0,24.141.0"}
P.entries["subzone:undercroft"] = {n="Підземний Склеп",s="Підземний Склеп — давня поховальна крипта на південно-західних пагорбах Східних Чумних Земель. Колись це була гідна гробниця Лордерона, а тепер її осквернила зграя тролів-нежиті на чолі із Зелдарром Вигнанцем. Серед осквернених катакомб лежить несправжня могила, яку давно викопали, щоб інсценувати смерть вигнаного паладина Тіріона Фордрінга.",h="Підземний Склеп — давня поховальна крипта на південно-західних пагорбах Східних Чумних Земель.",kw={"підземний склеп","зелдарр вигнанець","тролі","тіріон фордрінг","могила","крипта"},ang={["class:Paladin"]="Для святих воїнів зійти до Підземного Склепу означає побачити і трагічний удаваний похорон вигнаного героя Тіріона Фордрінга, і огидне осквернення священних крипт підлим кодлом Зелдарра.",["race:Troll"]="Тролі-мандрівники побачать у Зелдаррові Вигнанцеві та його неупокоєних родичах похмуре, збочене знущання з тролівських традицій і священних обрядів, якими вшановують померлих предків."},sec={{t="Осквернена гробниця",b="Підземний Склеп, вирубаний у скелястих урвищах на південний захід від Перехрестя Коріна, від початку будували як останній притулок для шанованих мерців Лордерона. Падіння королівства позбавило його святості, і тепер у гробниці гніздиться зграя диких тролів-нежиті. На чолі з велетенською потворою Зелдарром Вигнанцем ці мародери-гулі використовують підземні зали як лігво, звідки полюють по всіх Чумних Землях. Вони навіть наважуються грабувати поховальні ями Каплиці Надії Світла, щоб збирати свіжі трупи для своїх зловісних практик."},{t="Вдавана могила",b="Окрім жахливого непроханого мешканця, Підземний Склеп ховає зворушливу таємницю часів Другої війни: несправжню могилу з ім'ям Тіріона Фордрінга. Після суду за зраду й подальшого вигнання союзники Фордрінга влаштували тут його символічний похорон, щоб родина зберегла своє становище, а сам збезчещений паладин міг зникнути з очей. У цьому земляному ошуканстві лежить особиста пам'ятка з минулого Тіріона, захована там, де шукати наважаться лише ті, хто знає правду."}},faq={{q="Що таке Підземний Склеп?",a="Підземний Склеп — усипальниця на південному заході Східних Чумних земель. Колись її збудували, щоб ховати місцеву знать і полеглих воїнів Лордерона, але тепер вона зруйнована, і в ній оселилися жахи нежиті.",al={"де підземний склеп","що це за склеп","підземний склеп східні чумні землі"}},{q="Хто займає склеп тепер?",a="Склеп заполонила ватага тролів-нежиті на чолі з величезним лютим тролем-нежиттю на ім'я Зелдарр Вигнанець. Тунелі слугують їм лігвом між грабіжницькими набігами по всьому краю.",al={"хто в підземному склепі","моби підземного склепу","тролі підземного склепу"}},{q="Звідки у Східних Чумних землях тролі-нежить?",a="Погибель здіймала на півночі Лордерона переважно людей та ельфів, але неподалік живуть племена тролів, як-от Мохолупи й Сухокорі. Тролі-нежить, як Зелдарр і його ожилі поплічники, блукають кручами, грабують поховання й полюють на необережних мандрівників.",al={"чому тут тролі","лор заелдарру","тролі-нежить східних чумних земель"}},{q="Чому тут на могилі ім'я Тіріона Фордрінга?",a="Це несправжня, показна могила. Коли Альянс Лордерона позбавив Тіріона звання й вигнав, у Підземному Склепі влаштували удаваний похорон, щоб його родина зберегла честь і могла оголосити його мертвим, поки він потай жив у сховку.",al={"могила тіріона","чи тіріон мертвий","гробниця фордрінга"}},{q="Чому тролі з Підземного Склепу нападають на Каплицю Надії Світла?",a="Зелдарр Вигнанець часом водить нічні набіги на могильні ями біля Каплиці Надії Світла. Він хоче відкопати й викрасти свіжопохованих мерців, щоб поповнити свою ватагу чи нагодувати її моторошний голод.",al={"набіги заелдарру","рейд на могильну яму","тролі надія світла"}}},fp="10,351,22.536.0,18.491.1,23.240.0,27.189.0,55.269.0,46.268.0,54.222.0"}
P.entries["subzone:uplands"] = {n="Узвишшя",s="Узвишшя — горбиста височина на північному сході Гір Альтерак, колишня житниця занепалого Королівства Альтерак. Коли королівство впало, родючі пагорби цілком опинилися під владою Синдикату. Нині тут найміцніший осередок цієї злочинної організації, що укріпила кілька таборів на схилах.",h="Узвишшя — горбиста височина на північному сході Гір Альтерак, колишня житниця занепалого Королівства Альтерак.",kw={"узвишшя","синдикат","альтерак","барон вардус","кошара дандреда","розбійники"},ang={["class:Rogue"]="Узвишшя — головний осідок влади Синдикату, і тут добре видно, як позбавлена маєтків знать перетворила цілу мережу місцевих бандитів на організований і смертоносний картель.",["race:Human"]="Ці пагорби — похмуре нагадування про падіння Альтераку: колишня квітуча житниця людства тепер задихається від головорізів і розбитих сподівань."},sec={{t="Від житниці до розбійницької твердині",b="Перш ніж Друга війна розколола Альтерак, пагорби Узвишшя славилися як житниця королівства — вони постачали зерно й худобу гірським фортецям. Коли серце держави поринуло в руїну й ганьбу, чесний люд покинув хутори. Замість нього тут постав Синдикат на чолі з позбавленими маєтків альтерацькими вельможами та головорізами, що вирішили силою повернути вкрадену спадщину. Тепер Узвишшя — край, де Синдикат зосередив найбільше сил, всіяний таборами, патрулями й заставами на кшталт Кошари Дандреда на західних рубежах."},{t="Осідок тіней",b="Оскільки Синдикат міцно тримає ці пагорби, високопоставлені змовники часто керують справами саме з Узвишшя. Такі постаті, як Барон Вардус, пов'язаний із темним проводом, що спрямовує рештки альтерацької знаті, координують пересування розбійників, набіги на сусідні долини й опір і Альянсу, і Орді. Мандрівників, що забредуть на північно-східні хребти, одразу вороже зустрічають розбійники з великої дороги, що окопалися тут і вважають увесь цей гірський край своєю суверенною землею."}},faq={{q="Для чого спочатку слугувало Узвишшя?",a="Колись Узвишшя було головним хліборобським краєм Королівства Альтерак. Його пологі пагорби годували все королівство, доки війна й зрада не довели країну до загибелі.",al={"історія узвишшя","чим було узвишшя","призначення узвишшя"}},{q="Хто контролює Узвишшя тепер?",a="Узвишшя тримає Синдикат. Колишня знать Альтераку та її мережа бандитів розбили на цих пагорбах кілька таборів, і саме тут Синдикат найсильніший.",al={"хто живе на узвишші","хто тримає узвишшя","фракції узвишшя"}},{q="Де розташоване Узвишшя?",a="Узвишшя охоплює північно-східні височини Гір Альтерак, а на західному краю межує з Кошарою Дандреда.",al={"розташування узвишшя","де узвишшя","як знайти узвишшя"}},{q="Хто такий Барон Вардус?",a="Барон Вардус — впливовий вельможа й один із ватажків Синдикату. Він керує справами на Узвишші й командує бандитами та змовниками, які прагнуть повернути собі Альтерак.",al={"барон вардус історія","хто такий вардус","барон узвишшя"}}},fp="7,390,32.608.0,17.495.0,41.202.0,29.202.0,29.119.0,20.175.0"}
P.entries["subzone:ursolan"] = {n="Урсолан",s="Урсолан — розлоге поселення фурболгів Деревопащих у західній Азшарі, одразу на схід від Твердині Деревопащих. Табір, розділений навпіл глибоким яром, шанує ведмежого Прадавнього Урсола й слугує важливою твердинею для незіпсованих фурболгів, які захищають свої землі від чужинців.",h="Урсолан — розлоге поселення фурболгів Деревопащих у західній Азшарі, одразу на схід від Твердині Деревопащих.",kw={"урсолан","фурболги","деревопащі","урсол","азшара","ведмідь","прадавні"},ang={["class:Druid"]="Друїди глибоко шанують покровителів Урсолана, адже ведмежі Прадавні-близнюки Урсол і Урсок — ключові постаті в шануванні природи й опануванні Ведмежої подоби.",["race:NightElf"]="Хоча нічні ельфи шанують ведмежих Прадавніх, на місці не все гладко: дослідники з Талрендіса вивчають яр під насторожено-пильними поглядами фурболгів."},sec={{t="Оплот Ведмедя",b="Урсолан, що розкинувся на скелястих кручах західної Азшари, — східна частина володінь племені Деревопащих: через Твердиню Деревопащих він сполучається з Ведмежою Головою на півдні. Табір названо на честь шанованого ведмежого Прадавнього Урсола, і він — рідкісний острівець здорового глузду серед фурболгів Калімдору, більшість яких стала жертвою демонічної скверни. Селище лежить по обидва боки глибокої ущелини, де Деревопащі пильно стережуть кордони від непроханих гостей — зокрема від настирливих дослідників із табору нічних ельфів Талрендіс."}},faq={{q="Хто живе в Урсолані?",a="В Урсолані живуть фурболги Деревопащих — одне з останніх племен фурболгів, яким вдалося встояти перед демонічною скверною, що мучить Калімдор.",al={"хто в урсолані","мешканці урсолана","фурболги урсолана"}},{q="Чому це місце називається Урсолан?",a="Поселення назване на честь Урсола, одного з двох ведмежих напівбогів-близнюків, яких фурболги глибоко шанують.",al={"походження назви урсолан","на честь кого урсолан","значення урсолан"}},{q="Що це за глибока ущелина, що перетинає табір?",a="Урсолан розтинає глибокий шрам у землі. Унизу, в цьому яру, часто можна побачити біологів з нічноельфійського табору Талрендіс неподалік, які проводять польові дослідження.",al={"яр в урсолані","ущелина урсолана","прірва урсолан"}},{q="Як Урсолан пов'язаний з рештою земель Деревопащих?",a="Урсолан лежить просто на схід від азшарського входу до Твердині Деревопащих і через гірські тунелі з'єднує північні володіння племені з Ведмежою Головою на півдні.",al={"зв'язок урсолана","як дістатися до твердині деревопащих з урсолана"}}},fp="7,290,19.587.0,21.161.0,32.110.0,48.175.0,64.164.0"}
P.entries["subzone:uther-s-tomb"] = {n="Гробниця Утера",s="Гробниця Утера — священне місце спочинку Утера Світлоносця на вершині Пагорба Скорботи в Західних Чумних Землях. Її звели вцілілі послідовники Утера після його загибелі в недалекому Андоргалі, і цей пам'ятник — один із небагатьох оплотів Святого Світла, що лишилися посеред зачумленого краю, де блукають привиди.",h="Гробниця Утера — священне місце спочинку Утера Світлоносця на вершині Пагорба Скорботи в Західних Чумних...",kw={"гробниця утера","утер світлоносець","пагорб скорботи","андоргал","тел'даніс","срібна длань","паладин"},ang={["class:Paladin"]="Постати перед статуєю Утера — справжнє паломництво для кожного паладина: так ушановують батька ордену, чия жертва втілює чесноти Срібної Длані.",["faction:Alliance"]="Гробниця — незгасне свідчення спадку загиблого Лордерону й місце тихих роздумів для мандрівників Альянсу, які не бояться жахів Чумних Земель."},sec={{t="Оплот серед мору",b="Гробниця Утера на Пагорбі Скорботи, на південь від руїн Андоргала, позначає місце останнього спочинку легендарного паладина, який заснував Лицарів Срібної Длані. Після падіння Лордерону Утер прийняв останній бій в Андоргалі, захищаючи королівську урну з прахом короля Теренаса Менетіла II від принца Артаса Менетіла та Погибелі. Артас убив свого колишнього наставника й осквернив урну, щоб перенести в ній рештки Кел'Тузада. Вцілілі воїни винесли тіло Утера й поховали його в кам'яному святилищі. Хоча зараза невпинно поглинає довколишні землі, гробниці дивом не торкнувся тлін, а невсипущу варту при ній несе Верховний Жрець Тел'даніс."},{t="Спадок Світлоносця",b="До пам'ятника веде Шлях Утера, а в його центрі здіймається велична кам'яна статуя паладина: в одній руці він тримає фоліант Святого Світла, у другій — бойовий молот. Прочани, що долають ці небезпечні дороги, часто навідуються до гробниці, щоб ушанувати Утера, помолитися чи поміркувати про відданість, якою жили перші паладини."}},faq={{q="Хто похований у цій гробниці?",a="Тут спочиває Утер Світлоносець. Він був верховним командувачем і засновником Лицарів Срібної Длані — першого ордену паладинів в історії людства — і наставником принца Артаса Менетіла, доки Лордерон не впав під ударом Погибелі.",al={"хто такий утер","хто похований тут","утер світлоносець"}},{q="Як загинув Утер?",a="Утера вбив в Андоргалі його колишній учень Артас Менетіл, що повернувся з Нортренду лицарем смерті. Утер поліг, затято захищаючи урну з прахом батька Артаса, короля Теренаса Менетіла II.",al={"хто вбив утера","як загинув утер","артас убиває утера"}},{q="Хто такий Верховний Жрець Тел'даніс?",a="Верховний Жрець Тел'даніс — відданий доглядач пам'ятника. Він тихо й побожно чатує над місцем спочинку Утера, не боячись нежиті довкола, щоб святиня лишалася прихистком Світла.",al={"тел'даніс","жрець біля гробниці утера","хто захищає гробницю"}},{q="Чому чума не осквернила гробницю?",a="Незгасна святість пам'яті Утера й незламна сила Святого Світла освячують цю землю. Поки ліси довкола Пагорба Скорботи всохли й згнили, сама святиня лишається неушкодженим притулком від пошесті.",al={"чому гробниця утера чиста","чому немає чуми біля гробниці"}}},fp="12,311,23.713.0,25.330.0,27.242.0,18.229.0,30.213.0,43.252.0"}
P.entries["subzone:valgan-s-field"] = {n="Поле Валґана",s="Поле Валґана — покинута пшенична ферма на півночі Срібнолісся з видом на Озеро Лордамер. Колись мальовнича садиба, тепер вона спустіла, і її заполонили дикі воргени-Мунрейджі, яких випустив Архімаг Аруґал.",h="Поле Валґана — покинута пшенична ферма на півночі Срібнолісся з видом на Озеро Лордамер.",kw={"поле валґана","воргени","мунрейджі","аруґал","ферма","срібнолісся"},ang={["class:Mage"]="Покинуті дослідження Аруґала на фермі — тверезе застереження про катастрофічні небезпеки неприборканих викликів і магії інших вимірів.",["race:Undead"]="Для Відступників очищення Поля Валґана вкрай важливе, щоб убезпечити дорогу через Срібнолісся й повернути записи Аруґала, перш ніж його жахливі вихованці поширяться далі на північ."},sec={{t="Зруйнована садиба",b="Поле Валґана, що лежить трохи на захід від Осяйного Узмор'я й на північ від ближньої річки, колись було заможною пшеничною фермою з чудовим видом на Озеро Лордамер. Те мирне життя зникло, коли Погибель прокотилася Лордероном і змусила господаря, Валґана, тікати — або загинути. Без догляду зруйновані будівлі потрапили в пазурі диких воргенів-Мунрейджів, що спускаються з Фортеці Шадовфенг. Ще до Третьої війни тут якийсь час жив маг Аруґал, і рештки його таємних досліджень тепер привертають увагу Відступників."}},faq={{q="Хто такий Валґан?",a="Валґан — фермер-людина, якому до Третьої війни належало це господарство і який на ньому працював. Коли Погибель прокотилася північним Лордероном, Валґан чи то загинув, чи то втік, а покинута ферма занепала.",al={"валґан","хто такий валґан","історія поля валґана"}},{q="Чому на Полі Валґана блукають воргени?",a="Дику зграю Місячної Люті, що заполонила ферму, викликав у Срібнолісся Архімаг Аруґал. Він нацькував звірів на Погибель, але швидко втратив над ними владу, коли ті розбіглися лісом, і збожеволів від провини.",al={"чому воргени на полі валґана","воргени місячної люті валґан","хто привів воргенів"}},{q="Чому Відступників цікавить ця ферма?",a="До війни Архімаг Аруґал жив на цій фермі й залишив тут цінні книги заклять. Відступники шукають ці втрачені записи, щоб зрозуміти страхітливу магію Аруґала й навчитися їй протидіяти.",al={"завдання поля валґана","чому відступникам важливе поле валґана","фермерська книга заклять аруґала"}},{q="Які рідкісні загрози з'являються біля ферми?",a="Окрім зграй воргенів Місячної Люті, що бродять полями, околицями ферми часом нишпорить небезпечний звір на ім'я Найтлаш.",al={"найтлаш","рідкісні поля валґана","монстри валґана"}}},fp="14,230,18.546.0,15.210.0,38.231.0,45.200.0,39.157.0"}
P.entries["subzone:valley-of-bones"] = {n="Долина Кісток",s="Долина Кісток — безлюдний каньйон серед скель Шен'драласу, повний пилу, давніх решток і неспокійної нежиті. Тут блукають духи кентаврів клану Маґрам і ходять дозором темні некроманти, а над усім панують велетенські грудні клітки загадкових прадавніх істот, відомих як Мертві Голіафи.",h="Долина Кісток — безлюдний каньйон серед скель Шен'драласу, повний пилу, давніх решток і неспокійної нежиті.",kw={"долина кісток","кентаври","маґрам","некроманти","нежить","мертві голіафи"},ang={["class:Priest"]="Осквернення духів у долині жахливе: темні чаклуни спотворюють природний перехід смерті, прив'язуючи душі Маґрам до землі й здіймаючи покручених кістяних слуг."},sec={{t="Каньйон неспокійних мерців",b="Долина Кісток, захована в південній частині краю, цілком виправдовує свою похмуру назву. Запиленими ярами бродять кістяні жахіття, яких підняли й підкорили собі некроманти-кентаври, що черпають силу з темного чаклунства. Поруч із ними блукають безлюддям духи загиблих кентаврів Маґрам — прикуті до цієї безплідної землі ще довго після своєї насильницької смерті. Зловісності каньйонові додають Мертві Голіафи — два величезні скелети, що прихилилися до скелястих урвищ. Їхнє справжнє походження досі лишається цілковитою загадкою і для вчених, і для мандрівників."}},faq={{q="Що таке Мертві Велетні?",a="Мертві Велетні — колосальні рештки двох величезних невідомих істот, що лежать попід стінами каньйону. Мало хто знає, до якого виду вони належали чи коли загинули, хоча самі їхні розміри свідчать про звірів з давньої, забутої епохи.",al={"гігантські кістки","величезні скелети дезолас","лор мертвих велетнів"}},{q="Чому тут привиди кентаврів?",a="Це духи клану Маґрам, одного з войовничих племен кентаврів, що споконвіку живуть на цих посушливих рівнинах. Нескінченні міжкланові війни та некроманти-кентаври, які тривожать мертвих, позбавили ці душі спокою, і тепер вони блукають каньйоном примарами.",al={"привиди маґрам","чому духи кентаврів","нежить-кентаври"}},{q="Хто керує скелетами в долині?",a="У каньйоні некроманти-кентаври правлять темні обряди: вони піднімають скелетів-прислужників і командують ними, щоб ті стерегли скелі й допомагали утримувати позиції серед мертвих.",al={"хто командує скелетами","некроманти долини кісток"}}},fp="15,323,29.534.0,27.259.0,34.289.0,41.162.0"}
P.entries["subzone:valley-of-fangs"] = {n="Долина Ікол",s="Долина Ікол — скелястий вузький прохід між високими кам'яними стовпами в центрі Пустищ. Вона славиться лютими хижаками, що никають її запиленим дном, а ще дає прихисток невеличкому відлюдному табору мандрівних майстрів-винахідників і вигнанців.",h="Долина Ікол — скелястий вузький прохід між високими кам'яними стовпами в центрі Пустищ.",kw={"долина ікол","пустища","мартек","гобліни","пуми","вовки","койоти"},ang={["class:Hunter"]="Безліч витривалих пум і вовків робить долину чудовими мисливськими угіддями, де можна вистежувати здобич і приручати суворих звірів Пустищ.",["profession:Engineering"]="Гобліни-майстри, що отаборилися в Долині Ікол, приваблюють допитливих інженерів, які шукають нестандартних знань посеред посушливих пустирів."},sec={{t="Підступний прохід",b="Долина Ікол, що лежить між двома велетенськими скельними утвореннями в самому серці Пустищ, завдячує назвою і гострим обрисам довколишніх скель, і небезпечним звірам, що бродять її дном. Здичавілі скельні койоти, хижі пуми й люті вовки нишпорять запиленим коридором, тож самотнім мандрівникам тут небезпечно. Попри ворожу живність, кілька неприкаяних постатей — зокрема орк Мартек Вигнанець і його спільники-гобліни Ріґґлфаз і Джаззрік — розбили тут неофіційний табір і майструють на самоті, далеко від місцевих застав."}},faq={{q="Де розташована Долина Ікол?",a="Долина Ікол лежить у центрі Пустищ, затиснута між двома величезними природними скелями на південь від головного північного хребта.",al={"розташування долини ікол","де долина ікол","долина ікол на мапі"}},{q="Хто живе в Долині Ікол?",a="Тут є невеликий придорожній табір, де живуть самотній орк Мартек Вигнанець і його товариші — гобліни-майстри Ріґґлфаз і Джаззрік.",al={"хто в долині ікол","табір долини ікол","нпс долини ікол"}},{q="Чому подорожувати долиною небезпечно?",a="На дні долини повно агресивних звірів, звичних для Пустищ, — передусім хижих пум, вовків і койотів, що нападають на мандрівників із засідок серед вузьких проходів.",al={"небезпеки долини ікол","моби долини ікол","що нападає в долині ікол"}},{q="Чому Мартек і гобліни оселилися саме тут?",a="Вигнаний і змушений блукати пустками, Мартек Вигнанець знайшов тихий, зручний для оборони закуток між скелями разом із гоблінами-спільниками, охочими торгувати й майструвати подалі від цікавих очей великих фракцій.",al={"чому мартек тут","чому табір у долині ікол","мартек вигнанець"}}},fp="15,247,18.594.0,37.138.0,33.139.0,46.176.0,43.208.0"}
P.entries["subzone:valley-of-heroes"] = {n="Долина Героїв",s="Долина Героїв — монументальний південний в'їзд до Стормвінда, що веде мандрівників кам'яним мостом через рів. Обабіч височіють статуї на честь провідників Експедиції Альянсу до Дренору, і долина водночас вражає гостей і служить добре укріпленим контрольним пунктом.",h="Долина Героїв — монументальний південний в'їзд до Стормвінда, що веде мандрівників кам'яним мостом через рів.",kw={"долина героїв","статуї","експедиція альянсу","дренор","брама","стормвінд"},ang={["class:Paladin"]="Статуя Генерала Туральйона — глибоке натхнення для паладинів: вона увічнює одного з перших поборників Лицарів Срібної Длані.",["faction:Alliance"]="Кожен громадянин Великого Альянсу шанує долину як урочисте свідчення співпраці народів: тут пліч-о-пліч ушановано мучеників-людей, високих ельфів і дворфів."},sec={{t="Пам'ятник утраченим",b="Статуї вздовж мосту, зведені під час великої відбудови Стормвінда після Другої війни, вшановують командирів Експедиції Альянсу. Ці поборники пройшли крізь Темний Портал на Дренор, рідний світ орків, щоб назавжди запечатати розлам, і віддали життя, аби Азерот вижив. Мандрівники, що прямують на північ до Торгового Кварталу, проходять під ликами Архімага Хадґара, Курдрана Вайлдгаммера, Рейнджер-капітана Аллерії Віндраннер, Командувача Сил Даната Троллбейна й Верховного Генерала Туральйона."},{t="Бастіон міста",b="Окрім урочистої ролі, долина — головне оборонне вузьке місце, що захищає Стормвінд від вторгнення суходолом. Підступи пильнує Генерал Маркус Джонатан, командир міської варти, що верхи на коні стежить за всіма, хто в'їжджає й виїжджає через велику браму. Обабіч пильнують інші командири, серед них Майор Меттінґлі та Польовий Маршал Стоунбрідж, разом із шеренгами досвідчених вартових, щоб столиця лишалася захищеною від зовнішніх загроз."}},faq={{q="Кого зображують статуї обабіч шляху?",a="П'ять колосальних пам'ятників зображують легендарних командирів Синів Лотара, які очолили Експедицію Альянсу до Дренору: Верховного Генерала Туральйона, Капітанку рейнджерів Аллерію Віндраннер, Архімага Хадґара, Курдрана Вайлдгаммера і Командувача військ Даната Тролбейна.",al={"статуї стормвінда","хто ці герої","статуї долини","імена на статуях"}},{q="Чому ці пам'ятники поставили біля міської брами?",a="Статуї звели під час відбудови міста після Другої війни як вічну шану героям, яких вважали загиблими, коли Дренор розірвало на шматки. Вони нагадують кожному, хто входить у місто, яку високу ціну заплачено за безпеку королівства.",al={"чому пам'ятники біля брами","призначення долини героїв"}},{q="Хто командує вартою біля входу?",a="Генерал Маркус Джонатан, верховний командувач Міської Варти Стормвінда, сам наглядає за безпекою долини з передової, а допомагають йому такі офіцери, як Майор Меттінґлі і Польовий Маршал Стоунбрідж.",al={"капітан варти","хто на коні","хто керує обороною стормвінда"}},{q="Куди веде Долина Героїв?",a="Дорога на північ через міст виводить мандрівників просто в гамірний Торговий Квартал Стормвінда, а на південь — за браму, до мальовничих лісів Елвінна.",al={"куди веде міст","напрямки брами стормвінда"}}},fp="16,306,22.531.0,16.488.0,36.259.0,49.242.0,50.219.0,37.175.0"}
P.entries["subzone:valley-of-honor"] = {n="Долина Честі",s="Долина Честі — бойове осердя й квартал воїнів Оргріммара, що ховається в північно-східних каньйонах столиці. Тут розташовані міські казарми, гільдії воїнів і мисливців та розпорядники битв, що скеровують сили Орди по всьому Азероту. Серед гарячих кузень, тренувальних кіл і тихих вод Орда гартує свою силу й пам'ятає свою бойову спадщину.",h="Долина Честі — бойове осердя й квартал воїнів Оргріммара, що ховається в північно-східних каньйонах столиці.",kw={"долина честі","оргріммар","воїни","мисливці","зала хоробрих","розпорядники битв"},ang={["class:Hunter"]="Зала Мисливця й місця для приборкування звірів роблять долину обов'язковою зупинкою, щоб поповнити набої, відточити влучність і залишити улюбленців у стайні.",["class:Warrior"]="Долина Честі — ваша духовна домівка в Оргріммарі: тут Зала Хоробрих, досвідчені бойові наставники й зброярі, що кують обладунки для передових загонів Орди."},sec={{t="Серце потуги Орди",b="Долина Честі, захована за високими гребенями каньйону, — головний військовий квартал Оргріммара. Тут повсякдення визначають брязкіт тренувальної зброї й дзвін ковальських ковадел. Над долиною панує Зала Хоробрих — місце збору бувалих воїнів і розпорядників битв, що координують походи на таких фронтах, як Долина Альтерак та Ущелина Бойової Пісні. Поруч розташовані вишкільні місця для приборкувачів звірів і мисливців, тож район цілком присвячений спорядженню, муштрі й мобілізації захисників передової Орди."},{t="Ремесло, торгівля й перепочинок",b="Окрім зброї й плаців, долина забезпечує й постачання війни. «Палаюче Ковадло» та «Гірнича справа Червоного Каньйону» постачають обладунки й сире залізо, а інженери майструють неподалік у «Механічній майстерні Ноґґа». Між службою вояки й прийшлі шукачі пригод закидають вудки в напрочуд спокійне відлюдне озерце долини, знаходячи хвилини тиші подалі від курявої метушні Долини Сили."}},faq={{q="Яке призначення Долини Честі?",a="Це військове серце Оргріммара. Тут є міські казарми, наставники воїнів і мисливців, зброярі та розпорядники битв, які відправляють бійців на головні фронти.",al={"призначення долини честі","що тут","що в долині честі"}},{q="Де знайти розпорядників битв в Оргріммарі?",a="Розпорядники битв Орди перебувають у Залі Хоробрих у Долині Честі. Звідти бійців записують і відправляють на битви по всьому Азероту.",al={"де майстри битв оргріммара","пвп оргріммар","черга на поле бою оргріммар"}},{q="Яким ремеслам навчають у Долині Честі?",a="У долині є наставники й постачальники ковальства, гірництва й рибальства, а також гоблінські фахівці з інженерії, що працюють у Механічній майстерні Ноґґа.",al={"професії долини честі","наставники тут","ковальство оргріммара"}},{q="Що таке «Хвіст Виверни»?",a="«Хвіст Виверни» — місцева таверна й заїзд на краю долини, де втомлені воїни, мисливці й мандрівники можуть поїсти, випити й відпочити.",al={"хвіст виверни","корчма долини честі","таверна долини честі"}}},fp="15,383,26.559.0,25.391.0,43.206.0,44.187.0,52.169.0,26.160.0"}
P.entries["subzone:valley-of-kings"] = {n="Долина Королів",s="Долина Королів — пишний каньйон у південно-західному куточку Лох Модану, просто на південь від проходу до Дун Мороґу. Це пильно охоронювана брама до вогняної Палючої Ущелини, обабіч якої стоять монументальні кам'яні постаті, висічені на згадку про Війну Трьох Молотів. Мандрівники тут ступають під давньою дворфійською історією, водночас наражаючись на загрозу від загарбників Блекрок і трогів.",h="Долина Королів — пишний каньйон у південно-західному куточку Лох Модану, просто на південь від проходу до Дун...",kw={"долина королів","мадоран бронзбірд","кардрос вайлдгаммер","війна трьох молотів","палюча ущелина","лох модан"},ang={["faction:Alliance"]="Долина — північний оплот проти загроз, що збираються в пустищах Редріджу: вона не дає жевріючим небезпекам Палючої Ущелини вихлюпнутися в мирний Каз Модан.",["race:Dwarf"]="Для дворфів Айронфорджа Долина Королів — свята земля, що уособлює нерозривний союз Бронзбірдів і Вайлдгаммерів проти віроломства Темного Заліза."},sec={{t="Охоронці південного перевалу",b="Найвеличніша окраса долини — дві колосальні статуї, що зображують короля Мадорана Бронзбірда й Верховного Тана Кардроса Вайлдгаммера. Висічені на спільне замовлення їхніх синів після смерті обох, ці кам'яні велетні дивляться на перевал до випалених південних земель. Вони стоять як тривкий пам'ятник спільній перемозі у Війні Трьох Молотів і вічне застереження кланові Темного Заліза, нагадуючи кожному, хто дивиться на південь, про руїну, яку накликав на Гори Редріджу виклик Рагнароса."},{t="Брама до Палючої Ущелини",b="Долина Королів — не лише шлях між Проходом Південної Брами й Долиною Кам'яного Уламка: тут стоїть важка залізна брама, що веде вниз, до Палючої Ущелини. Через ворожих орків Блекрок, дворфів Темного Заліза й вулканічні небезпеки по той бік браму тримають суворо замкненою під охороною айронфорджських горян. Горянин Пебблбітті пильнує поріг і завертає всіх, окрім найзагартованіших шукачів пригод, які доведуть, що мають силу вижити в пеклі по той бік."}},faq={{q="Кого зображують дві велетенські статуї?",a="Дві величезні статуї зображують короля Айронфорджа Мадорана Бронзбірда і Верховного Тана Хардроса Вайлдгаммера. Їхні сини разом замовили ці пам'ятники після смерті батьків, щоб уславити союз, який переміг у Війні Трьох Молотів.",al={"статуї долини королів","дворфійські статуї лох модан","хто ці статуї"}},{q="Чому статуї дивляться на південь?",a="Їх поставили так, щоб вони дивилися просто на південні землі, спустошені, коли клан Темного Заліза викликав Рагнароса. Двоє королів стоять як захисний щит і вічне застереження Темному Залізу та будь-яким іншим ворогам, що спробують вторгнутися в північні землі дворфів.",al={"чому статуї дивляться на південь","призначення статуй","статуї дивляться на пекучу ущелину"}},{q="Як пройти крізь замкнену браму в південному кінці?",a="Браму до Палючої Ущелини тримають замкненою заради безпеки мандрівників. Вам треба поговорити з вартовою брами, Горянин Пебблбітті, і довести свої здібності, виконавши її доручення, — лише тоді вона дасть ключ.",al={"як відчинити браму пекучої ущелини","ключ горця пебблбітті","долина королів брама замкнена"}},{q="Куди веде ця долина?",a="Долина з'єднує Прохід Південної Брами, що веде до Дун Мороґа, кишачу трогами Долину Кам'яного Уламка на сході й розпечені безплідні землі Палючої Ущелини за добре укріпленою південною брамою.",al={"зв'язки долини королів","куди веде долина"}}},fp="15,419,30.518.0,29.508.0,39.257.0,40.286.0,57.257.0,28.206.0"}
P.entries["subzone:valley-of-spears"] = {n="Долина Списів",s="Долина Списів — скелястий каньйон у західному Пустограї, твердиня клану кентаврів Мародін. Оточена крутими кручами й охоронюваними перевалами, долина веде просто до Мародону — священної усипальниці предків усіх кентаврів.",h="Долина Списів — скелястий каньйон у західному Пустограї, твердиня клану кентаврів Мародін.",kw={"долина списів","пустограй","мародін","мародон","кентаври","заетар","принцеса терадрас"},ang={["faction:Alliance"]="Альянс обережно стежить за цим краєм, особливо відтоді, як ворожий клан Мародін полонив мандрівників-дослідників, зокрема гномку Меліззу Брімбаззл.",["race:Tauren"]="Дикість кентаврів поколіннями була лихом для племен Калімдору; пробираючись цією твердинею, таурени опиняються віч-на-віч із самим серцем давньої ворожнечі."},sec={{t="Твердиня Мародін",b="Долина Списів, що врізається в скелясті висоти західного Пустограю, — твердиня клану Мародін. Пішки сюди можна дістатися лише вузькими, легкими для оборони гірськими перевалами з півдня та сходу, тож ця замкнена долина — природний бастіон для кентаврів. Мандрівники, що наважуються пройти повз скелясті вузькі проходи, натрапляють на густі табори ворожих кочовиків, які стережуть підступи до своєї найшанованішої святині."},{t="Поріг Мародону",b="У південно-західному кінці долини ховається вхід до Мародону — священної печери з гробницею Заетара, батька кентаврів, де мешкає Принцеса Терадрас. Через це сусідство Мародін боронять каньйон із фанатичною люттю і від ворожих кланів, і від сторонніх зайд. Кожен, кому не пощастить необачно забрести в долину, — як-от легковажні гноми-картографи чи розвідники, — часто опиняється в полоні або гине."}},faq={{q="Хто контролює Долину Списів?",a="Долина — головні володіння клану Мародін, однієї з ворогуючих громад кентаврів, що борються за панування в Пустограї.",al={"хто тут живе","кентаврів клан долини списів","база мараудайн"}},{q="Куди веде Долина Списів?",a="На крайньому південному заході долини лежить вхід до Мародону — священної печери предків і усипальниці кентаврів.",al={"як потрапити до мараудону","вхід у мараудон","що в кінці долини списів"}},{q="Як потрапити в долину?",a="Долину оточують прямовисні гірські хребти, і потрапити в неї можна лише пішки — вузькими гірськими проходами на сході й на півдні.",al={"вхід у долину списів","як зайти","проходи в долину списів"}},{q="Чи хтось ув'язнений у долині?",a="Так, нещасну гномку на ім'я Мелізза Брімбаззл захопили кентаври Мародін і тримають у своїх таборах.",al={"меліза бримбазл","бранець у долині списів","гномський в'язень"}}},fp="16,264,27.419.0,25.457.0,34.130.0,37.139.0,28.136.0,32.131.0"}
P.entries["subzone:valley-of-spirits"] = {n="Долина Духів",s="Долина Духів, що тулиться до західних скель Оргріммара, — давній осідок племені Темного Списа в столиці Орди. Повна хатин під стріхою, тотемних стовпів-тікі й спокійних озерець, вона разюче відрізняється від навколишнього червоного каменю й закутої в залізо орочої архітектури.",h="Долина Духів, що тулиться до західних скель Оргріммара, — давній осідок племені Темного Списа в столиці Орди.",kw={"долина духів","оргріммар","темний спис","тролі","травництво","знахарі"},ang={["profession:Herbalism"]="Тихі водні протоки й особливі притулки долини роблять її головним у місті осередком, де можна набратися мудрості від місцевих майстрів-травників.",["race:Troll"]="Для племені Темного Списа цей мирний анклав — важливий клаптик дому й культурної самобутності серед височенних червоних каньйонів орочої столиці."},sec={{t="Дім для Темного Списа",b="Долина Духів відгалужується на захід від гамірної Долини Сили — це пишний і тихий анклав, відданий тролям Темного Списа. Коли плем'я оселилося в Дуротарі разом з орками Тралла, ця спокійна кишеня серед скель стала їхнім міським місцем збору. Тролячі ремісники, духовидці й чаклуни збираються біля дерев'яних містків і звивистих потічків, займаючись своїми мистецтвами подалі від сухої спеки головних вулиць."},{t="Хранителі ремесла",b="Окрім осель і тихих озерець, у долині живуть знавці магії й диких ремесел. Знахарі, травники й заклиначі збираються в притулках на кшталт Притулку духів і Оселі Темного Терну. У глибині долини розташована Брама Кігтя, що відчиняється просто на відкриті рівнини Пусток і дає швидкий прохід мандрівцям, мисливцям і подорожнім, що блукають за стінами каньйону."}},faq={{q="Хто живе в Долині Духів?",a="У долині живуть переважно тролі Темного Списа, які оселилися в Дуротарі разом з орками. Тут ви знайдете їхніх ремісників, духовних провідників, травників і мисливців серед характерних тролячих хиж і різьблених тотемів-тікі.",al={"хто тут живе","мешканці долини духів","тролі в оргріммарі"}},{q="Куди веде Брама Пазура?",a="Брама Пазура стоїть у глибині Долини Духів і слугує західним виходом з Оргріммара. Пройшовши крізь неї, ви потрапите просто в долину Річки Південної Люті й на рівнини Пусток.",al={"вихід брами пазура","чорна брама оргріммара","брама долини духів"}},{q="Які послуги й наставники є тут?",a="У Долині Духів є наставники й торговці з травництва, кулінарії та різних мисливських і магічних мистецтв. Вони працюють у таких помітних спорудах, як Притулок духів і Притулок Темного Терну.",al={"наставники долини духів","що в долині духів"}}},fp="17,303,24.453.0,20.401.0,35.238.0,31.199.0,42.204.0"}
P.entries["subzone:valley-of-strength"] = {n="Долина Сили",s="Долина Сили — гамірна центральна площа Оргріммара, що зустрічає кожного, хто минає височенну головну браму міста. Тут розташовані міський банк, центральний аукціонний дім і корчма «Зламане Ікло», тож долина — живе торговельне й адміністративне серце столиці Орди.",h="Долина Сили — гамірна центральна площа Оргріммара, що зустрічає кожного, хто минає височенну головну браму...",kw={"долина сили","оргріммар","банк","аукціонний дім","корчма","орда"},ang={["faction:Horde"]="Як головний майдан за брамою Оргріммара, Долина Сили — перше місце, де мандрівники Орди зустрічаються, щоб торгувати й збирати охочих у походи."},sec={{t="Брама міста",b="Ступіть за укріплену дерев'яну браму Оргріммара — і ви в Долині Сили. Висічена глибоко в червоній скелі каньйонів Дуротару, ця долина — головний майдан Орди. Шукачі пригод, купці й воїни з усіх союзних народів сходяться на її курявих площах: діляться бойовими історіями за кухлем у корчмі «Зламане Ікло» чи полагоджують важливі торгові справи в центральному банку й на аукціоні. Це гамірне свідчення сили та єдності, які орки виборювали на своїй новій батьківщині."},{t="Осередок торгівлі й проводу",b="Окрім оборонного значення, долина — головне торжище столиці. Крамниці на кшталт «Шкіри й сталі Сорана» продають обладунки, а різні торговці постачають припаси для довгих переходів Пустками. На кожному розі пильно чатують вояки: вони показують дорогу новоприбулим і стежать за порядком серед різних народів, що знайшли прихисток під стягом Тралла."}},faq={{q="Що таке Долина Сили?",a="Це головний вхід і центральна долина Оргріммара, одразу за головною брамою міста. Тут є найважливіші міські служби: банк, аукціон, крамарі загального товару й заїзд «Зламаний Бивень».",al={"огляд долини сили","що це за місце","район входу в оргріммар"}},{q="Де розташована Фортеця Ґроммаш відносно цієї долини?",a="Фортеця Ґроммаш стоїть не в Долині Сили, а північніше, в Долині Мудрості. Це резиденція Вождя Тралла й верховне командування Орди.",al={"де тралл","розташування фортеці ґроммаш","трон вождя"}},{q="Які послуги тут є?",a="У долині є головний банк міста, аукціон, ремісниче приладдя, торговці обладунками у «Збройні шкіри й сталі Сорана», нічліг у «Зламаному Бивні» та загальні товари.",al={"зручності долини сили","торговці долини сили","що тут є"}},{q="Хто охороняє Долину Сили?",a="Долину пильно патрулюють рубаки Оргріммара — досвідчені воїни-орки, що підтримують порядок, захищають каравани й показують мандрівникам дорогу лабіринтом міста-каньйону.",al={"оркові воїни оргріммара","вартові долини сили","оборона міста"}}},fp="18,289,21.508.0,24.385.0,31.222.0,55.164.0,30.183.0,34.180.0"}
P.entries["subzone:valley-of-the-watchers"] = {n="Долина Вартових",s="Долина Вартових, схована на далекому півдні пустелі Танаріс, — випалений сонцем каньйон із монументальною кам'яною кладкою. У його кінці стоїть колосальна запечатана кам'яна брама, що веде в таємничий комплекс Ульдуму, а стережуть її неповороткі велетні й прадавні кам'яні вартові.",h="Долина Вартових, схована на далекому півдні пустелі Танаріс, — випалений сонцем каньйон із монументальною...",kw={"долина вартових","ульдум","титани","дюнний трощитель","велетні","танаріс"},ang={["race:Dwarf"]="Для дворфів-дослідників і членів Ліги Дослідників масивна кам'яна брама — ще один спокусливий шматок головоломки в пошуках їхніх творців-титанів."},sec={{t="Запечатаний поріг",b="Долина Вартових позначає південну межу, де мінливі піски Танарісу сходяться з гористим краєм континенту. Над каньйоном панує масивна брама з прадавнього каменю, щільно замкнена від зовнішнього світу. Вважають, що цей запечатаний портал стереже вхід до Ульдуму — підземної споруди загадкових титанів. Запорошеними підступами бродять громадні гірські велетні — Дюнні Трощителі, тож хоч би що лежало поховане під пісками, його не потурбують ні мандрівники, ні грабіжники гробниць, ні вчені."}},faq={{q="Що за величезною кам'яною брамою тут?",a="Монументальні двері — вхід до Ульдуму, стародавньої підземної споруди, яку Титани звели задовго до початку писаної історії смертних. Поки що механізми повністю запечатані, тож справжній вміст і призначення споруди лишаються цілковитою загадкою.",al={"брама ульдуму","що таке ульдум","що за дверима"}},{q="Чи можна відчинити браму Ульдуму?",a="Ні. Величезна кам'яна брама абсолютно непрохідна. Жоден відомий у Калімдорі смертний ключ, закляття чи сила не здатні обійти захист Титанів, що тримає комплекс замкненим.",al={"чи можна відчинити браму ульдуму","відчинити двері ульдуму","як зайти в ульдум"}},{q="Чому долиною бродять велетні?",a="Дном каньйону бродять колосальні гірські велетні, відомі як Трощителі Дюн. Їх вабить потужна земна енергія цієї місцевості, і вони люто стережуть підступи, розчавлюючи всіх шукачів пригод, що підходять надто близько до південних скель.",al={"чому велетні бродять долиною","гірські велетні танаріс","велетні долини"}},{q="Де в Танарісі розташована ця долина?",a="Долина лежить на крайньому південному краю Танарісу, на південь від Долини Будякових Кущів і зяючих проваль Узбережжя Південного Розлому, і врізається просто у височенну південну гірську стіну.",al={"розташування долини вартових","як знайти долину вартових","де брама"}}},fp="22,298,20.543.0,40.246.0,32.171.0,42.217.0,40.191.0"}
P.entries["subzone:valley-of-trials"] = {n="Долина Випробувань",s="Схована за суворими червоними скелями південного Дуротару, Долина Випробувань служить полігоном для нових новобранців Орди. Молоді орки та їхні союзники — тролі Темного Списа — приходять сюди довести свою силу й заслужити місце серед воїнів Калімдору. Ті, хто переживе сувору звірину й приховані загрози долини, виходять готовими боронити свою молоду державу.",h="Схована за суворими червоними скелями південного Дуротару, Долина Випробувань служить полігоном для нових...",kw={"долина випробувань","стартова локація","орки","тролі","лігво","скорпіди","саркот","дуротар"},ang={["race:Orc"]="Долина — обряд посвяти для кожного молодого орка, що шукає честі; вона відлунює воїнськими традиціями Дренору на новоствореній батьківщині.",["race:Troll"]="Втративши дім на Островах Відлуння через Залазана, тролі Темного Списа навчаються в цьому каньйоні пліч-о-пліч із союзниками-орками, щоб заслужити своє місце в Орді."},sec={{t="Горнило піску й каменю",b="Долина Випробувань створена, щоб відсіяти слабких, перш ніж ті ступлять у ширші простори Дуротару. Під наглядом вождів і наставників, що стоять у висіченому в скелі прихистку, відомому як Лігво, молодих бійців кидають у випалену сонцем балку полювати на скорпідів, винищувати войовничих вепрів і наводити лад серед ледачих робітників, що заготовляють скупий ліс. Випробування безкомпромісне: хто доведе свою вправність, здобуває право вирушити далі справжнім солдатом Орди, а хто зазнає невдачі — лишається біліти під пустельним сонцем."},{t="Тінь на півночі",b="Колись відлюдний тренувальний майданчик нещодавно набув значно зловіснішого відтінку. У природних печерах уздовж північних скель укорінилися культисти Палаючого Клинка, прикликаючи в долину дрібних демонічних фамільярів. Хоч наставники й використовують цих зайд як живу бойову практику для новобранців, присутність магії Скверни так близько до порога Оргріммара живить темні чутки, що Рада Тіней знову намагається запустити пазурі в орківський народ."}},faq={{q="Яке призначення Долини Випробувань?",a="Це традиційний полігон для новобранців Орди — насамперед молодих орків і тролів Темного Списа. У її захищених каньйонах нові шукачі пригод виконують суворі завдання, щоб показати бойову вправність, інстинкт виживання та вірність, перш ніж їм дозволять вирушити в решту Дуротару.",al={"чому тут орки","що це за місце","призначення долини випробувань"}},{q="Що таке Лігво?",a="Лігво — печера, висічена в скелях приблизно посередині долини. У ній розташувалися наставники класів, торговці та наглядачі на кшталт Ґорнека, які скеровують новобранців, споряджають їх і стежать за їхніми успіхами під час перших випробувань.",al={"лігво","печера в долині випробувань","хто в лігві"}},{q="Чому на тренувальному майданчику для новачків є демони?",a="Культисти Палаючого Клинка влаштували таємний ковен у північних печерах. Хоч наставники й використовують їхніх слабких фамільярів, щоб випробовувати новобранців, присутність культу натякає, що потаємні сили на кшталт Ради Тіней шукають опори просто на порозі Дуротару.",al={"чому демони в долині випробувань","палаючий клинок у дуротарі","демони в північній печері"}},{q="Хто такий Саркот?",a="Саркот — незвично великий отруйний скорпід, що живе на скелястих висотах долини. Через його лють і смертоносність наставники доручають перспективним новобранцям уполювати його, щоб перевірити їхню відвагу, і принести на доказ його понівечену клешню.",al={"лор саркота","велетенський скорпід","завдання саркот"}}},fp="16,385,28.558.0,23.490.1,44.300.0,16.231.0,53.276.0,15.251.0"}
P.entries["subzone:valor-s-rest"] = {n="Спочинок Звитяги",s="Спочинок Звитяги — невеличка застава й кладовище на східному порозі Силітусу. Її стережуть члени Кола Кенарія, і це перший прихисток, який бачать мандрівники, коли з Кратера Ун'Ґоро спускаються в продуту вітрами пустелю.",h="Спочинок Звитяги — невеличка застава й кладовище на східному порозі Силітусу.",kw={"спочинок звитяги","кладовище","коло кенарія","силітус","кратер ун'ґоро","застава"},ang={["class:Druid"]="Як застава Кола Кенарія, Спочинок Звитяги уособлює невсипущу варту вашого ордену над зловісним неспокоєм у південній пустелі.",["faction:Alliance"]="Хоча Спочинок Звитяги невеликий і через нейтралітет Кола Кенарія спільний з Ордою, це бажаний перший прихисток, коли ви вибираєтеся з диких хащ Ун'Ґоро."},sec={{t="Брама до дюн",b="Спочинок Звитяги, що стоїть на східному кордоні Силітусу біля схилу, який веде вниз із Кратера Ун'Ґоро, — поріг цього безлюдного прикордоння. Коло Кенарія тримає табір як нейтральний плацдарм, тож тут знаходять прихисток і члени Альянсу, і члени Орди, які наважуються вирушити в посушливу пустелю. Помітне кладовище — сумне нагадування про небезпеку, що чигає по всій пустелі, де жахіття-комахи й прадавні загрози випробовують навіть найзагартованіші експедиції."}},faq={{q="Де розташований Спочинок Звитяги?",a="Спочинок Звитяги лежить біля східного входу до Силітусу. Це найперше поселення, яке трапляється на шляху, що піднімається з північно-західного кута Кратера Ун'Ґоро в пустелю.",al={"розташування спочинку звитяги","як знайти спочинок звитяги","де спочинок звитяги"}},{q="Хто контролює Спочинок Звитяги?",a="Заставу утримує Коло Кенарія. Як нейтральні доглядачі, що вивчають і охороняють край, вони дозволяють користуватися табором мандрівникам і з Альянсу, і з Орди.",al={"хто керує спочинком звитяги","фракція спочинку звитяги","табір кола кенарія силітус"}},{q="Чим примітний цей табір?",a="Найпомітніше в Спочинку Звитяги — цвинтар, де поховано тих, кого забрала безжальна пустеля та її комахоподібні мешканці, що підступають дедалі ближче.",al={"кладовище спочинку звитяги","що в спочинку звитяги"}},{q="Чи безпечний Спочинок Звитяги від довколишніх звірів?",a="Хоча це й застава, околиці табору потерпають від уже знайомої навали комах — це перше застереження про рій, що чатує глибше в Силітусі.",al={"чи безпечний спочинок звитяги","чи нападають на спочинок звитяги"}}},fp="12,240,20.489.0,30.203.0,26.171.0,41.165.0,51.188.0"}
P.entries["subzone:valormok"] = {n="Валормок",s="Валормок — віддалена застава Орди в суворих північно-західних землях Азшари. Це обвітрене поселення на північ від Табору Галдарр слугує базою для розвідників і шукачів пригод, які наважуються ходити проклятими прадавніми руїнами узбережжя.",h="Валормок — віддалена застава Орди в суворих північно-західних землях Азшари.",kw={"валормок","орда","азшара","застава","рімторі","зрада","помста"},ang={["faction:Horde"]="Валормок — головний притулок для шукачів пригод з Орди серед підступних руїн Азшари: тут є майстри польотів і завдання, що кличуть до помсти.",["race:Orc"]="Застава — суворе випробування витривалості для орків, які служать далеко від Оргріммара й зобов'язані честю помститися за зраджених побратимів."},sec={{t="Хиткий плацдарм",b="Валормок, що приліпився серед осінніх дерев Азшари, — ознака обережного інтересу Орди до ворожого й майже покинутого краю. Життя тут похмуре й повне небезпек: табір ледь укріплений і постійно відкритий для сатирів, наг і хижих звірів, що никають довкола. Та попри всі негаразди, воїни застави тримаються, і вона стала важливим вузлом польотів та передовим оплотом, що з'єднує Оргріммар із дикішими просторами північного Калімдору."},{t="Зрада і відплата",b="Нещодавно табір пережив нищівну зраду. Белґром Рокмол відрядив воїнів Орди разом з ельфійкою крові на ім'я Магус Рімторі шукати серед руїн прадавні скарби й могутні реліквії. Рімторі обернулася проти свого супроводу й вирізала воїнів, щоб забрати артефакти собі. Тепер ті, хто вцілів у Валормоку, на чолі з Аґ'тором Бладфістом замишляють помсту Рімторі та її поплічникам, що окопалися в сусідньому Талассійському Базовому Таборі."}},faq={{q="Що таке Валормок?",a="Валормок — відлюдне поселення Орди на північному заході Азшари. Тут є важливий розпорядник польотів, а сам табір слугує базою для мандрівників Орди, що досліджують прадавню прибережну глушину.",al={"валормок ашар","що це за табір","база орди в ашарі"}},{q="Хто очолює табір?",a="Заставою керує Аґ'тор Бладфіст, воїн-орк, якому доручено утримувати позиції Орди й помститися за вбитих товаришів.",al={"хто керує табором","лідер валормока","агтор кривавий кулак"}},{q="Чому тут загинуло стільки воїнів Орди?",a="Белґром Рокмол послав воїнів супроводжувати ельфійку крові Магус Рімторі в пошуках реліквій. Рімторі зрадила й вирізала свій супровід, щоб забрати силу й багатства Азшари собі, і гарнізон дуже порідшав.",al={"що сталося з вартою","різанина у валормоку","зрада рімторі"}},{q="Куди літає розпорядник польотів?",a="Розпорядник вітряних вершників у Валормоку пропонує прямі польоти по всьому Калімдору, зокрема до Оргріммара, Тандер Блафа, Перехрестя, Застави Розщепленого Дерева, Застави Кривавої Отрути й Евірлука.",al={"польоти валормока","куди летіти з валормока"}}},fp="8,262,21.473.0,25.457.1,17.213.0,25.151.0,44.241.0,40.190.0"}
P.entries["subzone:vault-of-ironforge"] = {n="Сховище Айронфорджа",s="Сховище Айронфорджа — головний банк і скарбниця дворфійської столиці. Воно розташоване в гамірних Торгових Рядах, просто навпроти аукціонного дому, і тут городяни й мандрівники з усього Альянсу надійно зберігають свої статки. Роботою Сховища опікуються Дініта й шанована родина Стоунмантлів.",h="Сховище Айронфорджа — головний банк і скарбниця дворфійської столиці.",kw={"сховище айронфорджа","банк","торгові ряди","стоунмантли","дініта","айронфордж"},ang={["faction:Alliance"]="Сховище, що стоїть просто навпроти міського аукціонного дому, — наріжний камінь торгівлі Альянсу: завдяки йому шукачі пригод завжди мають кошти й припаси.",["race:Dwarf"]="Для дворфів Сховище — предмет гірської гордості: воно уособлює непорушну безпеку й давню славу надійного охоронця дворфійських статків."},sec={{t="Серце дворфійської торгівлі",b="Висічене глибоко в гірській скелі Торгових Рядів, Сховище Айронфорджа — символ дворфійської фінансової надійності й майстерності. Торгівля в місті квітне, тож мандрівники, вояки й купці щодня приходять сюди, щоб покласти на зберігання монети, реліквії й припаси під пильним оком міської варти й касирів. Під наглядом Дініти й надійної родини Стоунмантлів ця установа дарує клієнтам з Альянсу цілковитий спокій."}},faq={{q="Для чого слугує Сховище Айронфорджа?",a="Сховище — центральний банк і сховок для цінностей міста Айронфордж. Містяни й мандрівники Альянсу довіряють йому своє золото, спорядження й дорогоцінне майно, що надійно лежить за важкими кам'яними стінами гори.",al={"призначення сховища","банк айронфорджа","що це за місце"}},{q="Хто керує банком?",a="Банк тримає Дініта разом із членами родини Стоунмантл, які приймають вклади, проводять оборудки й зберігають речі відвідувачів.",al={"банкіри","хто керує сховищем","родина стоунмантл"}},{q="Де розташоване Сховище?",a="Ви знайдете його просто в Громадському кварталі Айронфорджа, через площу від гамірного міського Аукціонного дому.",al={"розташування сховища","де банк айронфорджа","як знайти сховище"}}},fp="18,358,25.425.0,40.231.0,22.142.0,27.130.0"}
P.entries["subzone:venomweb-vale"] = {n="Долина Отруйного Павутиння",s="Долина Отруйного Павутиння — тіниста долина у східних Галявинах Тірісфалю, одразу на південь від Багряного Монастиря. Колись пишний ліс, повний дичини, долина виродилася в уражене чумою гніздо, яке заполонили агресивні отруйні павуки. Невідомо більшості перехожих, вона зберігає й давню спадщину — як священне місце зібрань Ради Тірісфалю.",h="Долина Отруйного Павутиння — тіниста долина у східних Галявинах Тірісфалю, одразу на південь від Багряного...",kw={"долина отруйного павутиння","павуки","срі'скалк","рада тірісфалю","хранитель","еґвінн","лейтенант сандерс","тірісфаль"},ang={["class:Mage"]="Для адептів таємних мистецтв долина — священна земля: саме тут історично збиралася Рада Тірісфалю, де обирали й наділяли силою Хранителів давнини, зокрема Еґвінн.",["race:Undead"]="Мандрівникам з-поміж Відступників, що прямують до Багряного Монастиря, доводиться оминати і смертельну отруту виводку Срі'скалка, і пильні патрулі хрестоносців Лейтенанта Сандерса на півночі."},sec={{t="Уражений чумою притулок",b="Перш ніж чума поглинула Лордерон, ця долина була мирним куточком соковитої трави й зелених дерев, який любили місцеві мисливці, що вистежували оленів і кроликів. Сьогодні в краєвиді панують гниль і повзучий морок. Велетенські отруйні павуки кишать серед дерев і улоговин на чолі зі страхітливим павуком Срі'скалком. Північний край долини межує із землями Багряного Хрестового Походу, де темні гончаки нишпорять біля укріпленого Багряного Табору під командуванням Лейтенанта Сандерса."},{t="Спадщина Ради",b="Задовго до того, як павуки заполонили улоговини, долина була таємним місцем зібрань давньої Ради Тірісфалю. Саме тут найпершого Хранителя Тірісфалю наділили силою битися з демонічними вторгненнями. У відчайдушній і хибній спробі убезпечити своє святилище від зайд один із членів ради вивів і випустив смертоносних павуків, що й досі мучать цю улоговину. Дивна брила котячого золота — наслідок давньої невдалої трансмутації учня Фалріка — досі позначає відлюдне місце, де Хранителька Еґвінн колись збиралася з Радою."}},faq={{q="Чому в Долині Отруйного Павутиння стільки павуків?",a="Ці павуки — не просто дикі звірі чи породження чуми Погибелі. Століття тому один із членів таємної Ради Тірісфалю магією створив їх і випустив у божевільній спробі захистити своє відлюдне місце зборів від непроханих гостей. Павуки розплодилися й заполонили долину.",al={"звідки павуки в долині отруйного павутиння","чому стільки павуків","хто створив павуків"}},{q="Як Рада Тірісфалю пов'язана з цією долиною?",a="Долина Отруйного Павутиння була звичним таємним місцем зборів Ради Тірісфалю. У цій тихій долині ельфійські та людські маги сходилися, щоб наділити своєю спільною силою захисників світу, зокрема найпершого Хранителя Тірісфалю.",al={"рада тіріфалю долина","місце зустрічі охоронців","історія ради отруйного павутиння"}},{q="Хто панує над павуками в долині?",a="Павучим виводком верховодить величезний смертоносний павук на ім'я Срі'скалк, що чатує в затінених улоговинах під спаплюженими кронами долини.",al={"бос павуків отруйного павутиння","срі'скалк","лідер павуків тіріфалю"}},{q="Яка історія пов'язана з каменем із «золота дурнів» у долині?",a="Століття тому учень на ім'я Фалрік під час навчання випадково перетворив валун на «золото дурнів» — пірит. Цей дивний орієнтир став точним місцем зустрічей, де славетна Хранителька Аеґвінн сходилася з Радою Тірісфалю.",al={"камінь золота дурнів","камінь зустрічі еґвін","камінь золота фалріка"}}},fp="13,355,17.469.0,21.590.0,47.285.0,60.264.0,36.143.0,58.241.0"}
P.entries["subzone:venture-co-base-camp"] = {n="Базовий Табір Венчурної Компанії",s="Базовий Табір Венчурної Компанії, загублений у густих джунглях на півночі Долини Стренглторну, — передова опорна точка горезвісно жадібного гоблінського синдикату. Наймані наглядачі й робітники тут нещадно визискують буйну природу: рубають ліс, полюють на місцеву звірину й видобувають із довколишніх водойм цінні обкатані кристали.",h="Базовий Табір Венчурної Компанії, загублений у густих джунглях на півночі Долини Стренглторну, — передова...",kw={"венчурна компанія","базовий табір","гобліни","вирубка лісу","кристали","долина стренглторну"},ang={["class:Druid"]="Венчурна Компанія — уособлення неприборканого промислового плюндрування: вона роздирає незаймані оселища джунглів і руйнує місцеву рівновагу природи заради грубого механічного зиску.",["profession:Mining"]="Табір — промисловий осередок розвідки надр у джунглях: тут старателі компанії шукають сировину й рідкісні обкатані кристали."},sec={{t="Промисловий наступ",b="Венчурна Компанія сумно відома по всьому Азероту безжальною гонитвою за наживою й цілковитою зневагою до природи. У цьому таборі в джунглях парові машини й нашвидкуруч збиті гоблінські халупи вгризаються в прадавній полог лісу. Під охороною озброєних найманців бригадири й робітники керують видобутком ресурсів у довколишніх долинах: особливо їх цікавлять цінні обкатані кристали, які знаходять неподалік, а всі джунглі, що стоять на заваді, вони просто вирубують під корінь."}},faq={{q="Що Венчурна Компанія робить у Долині Стренглторну?",a="Венчурна Компанія — ласий до наживи синдикат, що займається гірництвом, лісозаготівлею та інженерією. На півночі Стренглторну вона розбила табір, щоб вирубувати густі джунглі, зводити важкі споруди й добувати цінні мінерали — передусім обкатані водою кристали, які знаходять біля місцевих потоків.",al={"чому гобліни тут","призначення венчур ко","венчурна компанія стренґлторн"}},{q="Чи пов'язані тутешні гобліни з картелем Стімвідл із Буті Бей?",a="Ні. Венчурна Компанія — окреме хижацьке підприємство, ніяк не пов'язане з Бароном Ревілґазом і картелем Стімвідл. На відміну від торгових князів Буті Бей, які плекають вигідні торговельні зв'язки, Венчурна Компанія покладається на безжальне визискування й ворожа майже до всіх, хто заважає її прибуткам.",al={"чи венчур ко бутті бей","чи дружні до бутті бей","венчур ко стімвіддл"}},{q="Що лежить за базовим табором?",a="Поруч із базовим табором розташований Операційний Центр Венчурної Компанії — краще укріплена застава з важкими лісозаготівельними машинами, запасами деревини й старшими керівниками компанії, які керують вирубкою в усьому краї.",al={"куди веде табір","що поруч із табором","операційний центр венчур ко"}}},fp="21,365,23.487.0,56.301.0,74.338.0,31.230.0"}
P.entries["subzone:venture-co-mine"] = {n="Шахта Венчурної Компанії",s="Шахта Венчурної Компанії, схована у східних кручах Малгору, — самовільна промислова копальня, якою заправляють жадібні гоблінські пройдисвіти. Хоч таурени відмовили їм у праві на видобуток, Венчурна Компанія все одно вгризлася в пагорби, загрожуючи природній рівновазі рівнин.",h="Шахта Венчурної Компанії, схована у східних кручах Малгору, — самовільна промислова копальня, якою...",kw={"шахта венчурної компанії","венчурна компанія","гобліни","фіззпрокет","малгор","копальня","лісозаготівля"},ang={["profession:Engineering"]="За шахтними тунелями, на верхній лісовій вирубці, причаївся Твізвік Спрокетґрайнд — майстровий, готовий поділитися механічними секретами ремесла подалі від допитливих корпоративних очей.",["race:Tauren"]="Шахта — глибока образа Земній Матері: вона приносить кіптяву, гуркіт і безоглядні рубці в прабатьківські долини, які племена поклялися берегти."},sec={{t="Небажана промисловість",b="Коли Венчурна Компанія попросила права вигрібати з Малгору корисні копалини, таурени навідріз відмовили. Корпоративний картель знехтував ними й усе одно прорив тунелі глибоко в східну гірську стіну під орудою Наглядача Фіззпрокета. Розлогий комплекс має три входи: наземний тунель під охороною найманих горлорізів, стрімкий оглядовий виступ на скелі та верхній прохід до невеликої лісозаготівлі. Машини, дим і купи шлаку, що насуваються на край, — відверте осквернення священної землі."},{t="Дедалі більші апетити",b="Гірнича справа була для картелю лише першою ставкою. Внутрішні документи свідчать, що Магнат Раздунк і правління Венчурної Компанії заохочували Фіззпрокета розширитися до повномасштабних лісозаготівель і обіцяли передові гоблінські подрібнювачі, щоб зачистити хвилясті пагорби. Тауренські скороходи напали на корпоративний караван із припасами біля Озера Кам'яного Бика й спалили його, щоб загальмувати розширення, та картель негайно вислав збирачів відшукати вантаж. Аби зупинити руйнування, племена вдалися до прямої відплати наглядачам шахти."}},faq={{q="Чому гобліни видобувають руду в Малгорі?",a="Венчурна Компанія просила дозволу добувати копалини в Малгорі, але таурени їй відмовили. Не бажаючи зважати ні на права корінних мешканців, ні на рівновагу природи, картель нишком завіз робітників і машини в східні скелі, щоб грабувати пагорби без жодного дозволу.",al={"чому гобліни в мулґорі","причина венчур ко мулґор","хто керує шахтою"}},{q="Хто керує цією копальнею?",a="Усіма справами Венчурної Компанії в Малгорі керує Наглядач Фіззпрокет зі свого поста біля головного входу. Накази він отримує просто від правління компанії та Магната Раздунка.",al={"бос шахти","хто очолює шахту","наглядач фізспрокет"}},{q="Що сталося з обозом біля озера?",a="Таурени-скороходи влаштували засідку й підпалили обоз Венчурної Компанії біля північного берега Озера Кам'яного Бика, щоб машини не дісталися до шахти. Гобліни негайно відрядили рятувальні загони, щоб перебрати обгорілі уламки й повернути свій вантаж.",al={"історія каравана","караван озера кам'яного бика","хто спалив караван"}},{q="Що ще гобліни планують тут збудувати?",a="Окрім того, щоб видовбувати руду зі скель, вони, як видно з внутрішніх донесень, планують звести лісопилку й пустити шредери, щоб вирубати дерева Малгору заради ще більших прибутків.",al={"плани венчур ко","гоблінські подрібнювачі мулґор","плани лісопилки"}}},fp="16,280,17.506.0,19.546.1,34.290.0,37.192.0,48.266.0,44.184.0"}
P.entries["subzone:vice"] = {n="Лещата",s="Лещата — сувора безлюдна місцина на Перевалі Мертвого Вітру вздовж дороги до Каражану. Це територія огрів Мертвого Вітру, які тримають тут грубі земляні насипи й розкидані стійбища наперекір похмурій відлюдності краю. Мандрівникам доводиться мати справу і з їхньою грубою жорстокістю, і з напрочуд вправними знавцями темної магії з-поміж них.",h="Лещата — сувора безлюдна місцина на Перевалі Мертвого Вітру вздовж дороги до Каражану.",kw={"лещата","огри","мертвий вітер","перевал мертвого вітру","каражан","чорнокнижники"},ang={["class:Mage"]="Те, що огри оселилися просто біля дороги до Каражану, змушує Кірін-Тор замислитися: чи не впливають залишкові енергії вежі Медіва на місцевих звірів і клани?",["class:Warlock"]="Огри Мертвого Вітру з Лещат несподівано вправно володіють темною магією — виходить, навіть відлюдні клани громил здатні черпати руйнівну енергію Скверни."},sec={{t="Безлюдна твердиня",b="Лещата, що простягаються південними просторами Перевалу Мертвого Вітру, — це безплідна земля, зубчасті скелі й грубі насипи, зведені кланом огрів Мертвого Вітру. Довколишній каньйон майже цілком покинутий на мстивих привидів і стерв'ятників, але ці огри вперто закріпилися просто біля головної дороги до Каражану. Чому вони обрали такий похмурий і понівечений магією пустир — досі загадка, але кожен, хто йде між Сутінколіссям і Болотом Скорботи, швидко переконується: свої табори вони боронять із лютою жорстокістю."},{t="Груба сила й темні мистецтва",b="На відміну від звичайних грабіжників із великої дороги, огри з Лещат мають і важку бойову силу, і небезпечний таємний хист. Поряд із кремезними громилами чорнокнижники Мертвого Вітру серед земляних насипів практикують грубе, але смертоносне чаклунство Скверни. Те, що вони оселилися так близько до покинутої оселі Медіва, свідчить про жагу до залишкової магічної сили, тож каньйон стає смертельною пасткою і для мандрівних учених, і для самотніх розвідників."}},faq={{q="Що таке Лещата?",a="Лещата — суворий куточок на півдні Перевалу Мертвого Вітру: земляні горби, розкидані багаття й кам'янисті яри, які повністю контролюють огри Мертвого Вітру.",al={"що таке лещата","лещата мертвого вітру","район лещат"}},{q="Чому тут живуть огри?",a="Ніхто достеменно не знає, чому огри обрали для житла таку непривітну, моторошну ущелину. Можливо, їхніх чорнокнижників вабить залишкова магічна енергія, що досі струменить від Каражана неподалік, а може, вони просто користуються відлюдною гірською дорогою, щоб грабувати перехожих мандрівників.",al={"чому тут огри","мотиви огрів мертвого вітру","чому огри в лещатах"}},{q="Куди веде дорога через Лещата?",a="Стежка через Лещата в'ється глибше між скелями південного Перевалу Мертвого Вітру й веде просто до зловісної брами Каражана — покинутої вежі Хранителя Медіва.",al={"куди веде дорога лещат","куди йде шлях","шлях крізь лещата"}},{q="Яких небезпек слід чекати в Лещатах?",a="Мандрівникам трапляться агресивні огри Мертвого Вітру, що патрулюють дорогу й обороняють свої горби. Окрім кремезних бійців, у клані є небезпечні чорнокнижники, що володіють прокляттями й магією тіней.",al={"загрози лещат","вороги лещат","що нападає в лещатах"}}},fp="4,362,21.584.0,25.419.0,17.170.0,30.270.0,42.183.0,49.215.0"}
P.entries["subzone:vile-reef"] = {n="Мерзенний Риф",s="Мерзенний Риф — підводна мілина з яскравих коралів біля західного узбережжя Долини Стренглторну, неподалік від Базового Базового Табору Ґром'ґол. Під водою тут оселилися агресивні мурлоки — серед прадавніх затонулих руїн тролів, велетенських молюсків і решток кораблів.",h="Мерзенний Риф — підводна мілина з яскравих коралів біля західного узбережжя Долини Стренглторну, неподалік...",kw={"мерзенний риф","мурлоки","коралі","вівтар припливів","перли","ґром'ґол"},ang={["faction:Horde"]="Риф лежить просто біля берега навпроти Базового Базового Табору Ґром'ґол і становить постійну морську загрозу для кораблів постачання й берегових патрулів Орди в Долині Стренглторну.",["race:Troll"]="Затонула кам'яна кладка й прадавній Вівтар Припливів — сумне нагадування про давно втрачені прибережні землі, якими колись володіли тролі джунглів."},sec={{t="Затонуле каміння й коралові рифи",b="Мерзенний Риф простягається під хвилями Великого Моря просто навпроти берега, де стоїть Базовий Табір Ґром'ґол, і славиться буйним морським життям та небезпечними мешканцями. Дно всіяне вивітреною кладкою затонулих руїн тролів, а серед них стоїть загадковий Вівтар Припливів. Між коралових уступів і уламків кораблів чатують зграї мурлоків, які люто боронять мілководдя й нападають на кожного пірнальника, що зважиться спуститися на глибину по велетенських молюсків і рідкісні блакитні перли."}},faq={{q="Де розташований Мерзенний Риф?",a="Мерзенний Риф лежить у Великому Морі біля західних берегів Долини Стренглторну, просто на північний захід від Базового Базового Табору Ґром'ґол.",al={"розташування мерзенного рифу","де мерзенний риф","як знайти мерзенний риф"}},{q="Які істоти населяють Мерзенний Риф?",a="Риф кишить ворожими мурлоками, що плавають серед коралів і затонулих споруд, а на морському дні лежать велетенські молюски.",al={"моби мерзенного рифу","монстри мерзенного рифу","хто живе в мерзенному рифі"}},{q="Які руїни є тут під водою?",a="На морському дні лежать рештки стародавніх тролячих руїн і Вівтар Припливів — пам'ятки тролячої цивілізації, яку давно поглинув океан.",al={"руїни мерзенного рифу","затонулі руїни стренґлторну","де вівтар припливів"}},{q="Навіщо шукачі пригод пірнають до Мерзенного Рифу?",a="Нирці ризикують у водах, де кишать мурлоки, щоб дослідити прибережні уламки кораблів, оглянути Вівтар Припливів і зібрати велетенських молюсків, у яких іноді ховаються дорогоцінні блакитні перлини.",al={"навіщо пірнати на мерзенний риф","скарби мерзенного рифу","сині перлини стренґлторну"}}},fp="9,250,28.513.0,31.132.0,37.150.0,37.158.0,43.178.0"}
P.entries["subzone:vul-gol-ogre-mound"] = {n="Огрський Курган Вул'Ґол",s="Огрський Курган Вул'Ґол — улоговина на півдні Сутінколісся, яку захопили огри Скалкокулаків на чолі з громилою Ззарк'Вулом. Колись тут стояли людські садиби, а тепер зруйновані хати й підземна печера завалені тушами та награбованим добром клану.",h="Огрський Курган Вул'Ґол — улоговина на півдні Сутінколісся, яку захопили огри Скалкокулаків на чолі з...",kw={"вул'ґол","огри","розщеплений кулак","ззарк'вул","курган","сутінколісся"},ang={["faction:Alliance"]="Для мандрівників Альянсу, що йдуть південним шляхом до Долини Стренглторну, стримування огрів Скалкокулаків у Вул'Ґолі — запорука того, що шлях постачання крізь і так підступний ліс лишиться відкритим.",["race:Human"]="Розтрощені рештки садиб в улоговині — гірке нагадування про те, скільки земель Королівство Стормвінд утратило в Сутінколіссі за останнє покоління."},sec={{t="Сплюндрована садиба",b="Захований у тіні на південний захід від роздоріжжя, звідки дорога веде до Долини Стренглторну, Огрський Курган Вул'Ґол — осідок клану Скалкокулаків в Сутінколіссі. Колись улоговина була мирними нивами, але її мешканці давно втекли або загинули, лишивши по собі порожні хатини, які тепер захопили незграбні огри й облаштували собі грубі сховища. У печері під пагорбом купи вбитих чорних ведмедів свідчать про ненажерливий апетит клану. Ватажок Ззарк'Вул панує над табором і збирає дивні дрібнички поряд із буденним награбованим скарбом."},{t="Загроза на південному кордоні",b="Знесилена Нічна Варта мусить розтягувати свої поріділі лави, щоб захищати Даркшир від скажених воргенів і неспокійних мерців, тож Командир Алтея Ебонлок і її ополчення покладаються на сторонніх найманців, які проріджують огрів Скалкокулаків, доки ті не рушили на північ. Проте огри нажили собі ворогів не лише серед міської варти. Вони пограбували відлюдника Аберкромбі, поцупивши скриню з його алхімічним приладдям, і привернули увагу допитливих магів, що шукають чарівні лінзи, якими, кажуть, володіє ватажок Ззарк'Вул."}},faq={{q="Хто живе в Огрському Кургані Вул'Ґол?",a="Курган займає огрський клан Скалкокулаків на чолі з кремезним вождем Ззарк'Вулом. Вони живуть серед зруйнованих людських хат і глибоко в земляній печері.",al={"хто на кургані вул'ґол","вороги вул'ґол","огри в сутінколіссі"}},{q="Чому Нічна Варта досі не вигнала огрів?",a="Нічній Варті бракує людей, щоб великими силами вирушити в південну улоговину. Даркширу звідусіль загрожують нежить, воргени й жахи Хутора Аддла, тож ополчення наймає мандрівних шукачів пригод, щоб проріджувати Скалкокулаки, замість ризикувати міською вартою.",al={"чому нічна варта не прожене огрів","даркшир проти вул'ґол"}},{q="Хто жив тут до огрів?",a="Колись поселенці-люди обробляли цей родючий куточок на півдні Сутінколісся — ще тоді, коли край звався Світлоліссям. Коли на землю впало прокляття, ферми занепали, а огри-загарбники захопили покинуті будівлі.",al={"зруйновані будівлі вул'ґол","історія вул'ґол"}},{q="Навіщо відлюдник Аберкромбі послав мене сюди?",a="Огри Скалкокулаків напали із засідки на відлюдника Аберкромбі й поцупили ящик із його травами та знаряддям для бальзамування. Сам він битися з ними не може, тож посилає мандрівників у курган повернути вкрадене.",al={"аберкромбі огри","скриня аберкромбі"}},{q="Де розташований курган?",a="Вул'Ґол лежить на крайньому півдні Сутінколісся, трохи на південний захід від роздоріжжя, звідки дорога відгалужується на південь до кордону Долини Стренглторну.",al={"розташування вул'ґол","як дістатися до вул'ґол"}}},fp="18,272,20.578.0,31.517.0,36.171.0,49.266.0,32.239.0,44.227.0,27.151.0"}
P.entries["subzone:wailing-caverns"] = {n="Печери Стогонів",s="Сховані в кручах над Оазою Буйних Вод у Пустках, Печери Стогонів — розлога мережа підземних джерел і печер. Колись їх дослідив друїд нічних ельфів Наралекс, щоб повернути посушливим рівнинам буйну життєву силу, але натомість комплекс перетворився на викривлене лігво жахіть, мутованої звірини й спотворених друїдів.",h="Сховані в кручах над Оазою Буйних Вод у Пустках, Печери Стогонів — розлога мережа підземних джерел і печер.",kw={"печери стогонів","наралекс","друїди ікла","смарагдове жахіття","леді анакондра","оаза буйних вод"},ang={["class:Druid"]="Для друїдів печери — трагічне застереження про добрі наміри, спотворені Смарагдовим Жахіттям: Наралекса треба або пробудити, або впокорити його збожеволілих учнів.",["faction:Horde"]="Спотворені води загрожують крихким оазам, на яких тримаються життя й подорожі в Пустках, тож очищення печер — нагальна справа для безпеки довколишніх поселень."},sec={{t="Скислий Сон",b="Свою назву печери дістали через моторошні, тужливі стогони, що вириваються з розколин у скелях, коли підземні гейзери вибухають парою. Друїд нічних ельфів Наралекс разом із вірними послідовниками вирушив у ці глибокі водні тунелі, сподіваючись підключитися до підземної мережі й спрямувати силу Смарагдового Сну, щоб безплідні савани розквітли. Натомість свідомість Наралекса потрапила в пастку Смарагдового Жахіття. Гнійна скверна просочується назовні крізь сплячого друїда, спотворюючи джерела й перетворюючи місцевих звірів на неприродних потвор-мутантів."},{t="Друїди Ікла",b="Коли сон Наралекса обернувся божевіллям, нав'язливе Жахіття позбавило розуму його найближчих учнів. Зрікшись давніх традицій, вони утворили Друїдів Ікла на чолі з такими ватажками, як Леді Анакондра, прийняли отруйні зміїні подоби й боронять свого сплячого господаря від кожного, хто спробує перервати його транс. Тепер підземні водні шляхи загрожують отруїти оази по всіх Пустках, привертаючи увагу і стурбованих союзників із Кола Кенарія в Тандер Блафі, і заповзятливих гоблінів у Раджеті."}},faq={{q="Чому вони звуться Печерами Стогонів?",a="Печери названо за моторошні стогони й зойки, що лунають, коли підземні струмені пари прориваються крізь вузькі тріщини в кам'яному склепінні. Луна розносить їх величезними кам'яними залами, наче крики болю.",al={"чому стогони","значення печер стогонів","чому вони стогнуть"}},{q="Хто такий Наралекс і чому він тут спить?",a="Наралекс — нічний ельф-друїд, що хотів перетворити Пустки на буйний ліс, поєднавши підземні джерела зі Смарагдовим Сном. Проте в трансі його здолало Смарагдове Жахіття, і він мимоволі став провідником спотворення.",al={"хто такий наралекс","сплячий друїд","чому наралекс спить"}},{q="Хто такі Друїди Ікла?",a="Це колишні учні Наралекса, яких Смарагдове Жахіття довело до божевілля, поки їхній учитель спав. Вони перейняли подобу змій, завзято обороняють спотворену печеру й прагнуть поширити по всьому краю своє викривлене бачення природи.",al={"лор друїдів ікла","хто такі друїди ікла","змієві друїди"}},{q="Чому звірів у печерах називають «девіантними»?",a="Енергія Жахіття, що сочиться від Наралекса, отруїла джерела й перетворила звичайних рапторів, кроколісків і гадюк на химерні девіантні форми з дивним забарвленням, підвищеною агресією та незвичною лускою й шкурою.",al={"збочені звірі","що таке збочений","чому збочені"}}},fp="15,337,17.558.0,22.526.1,37.203.0,43.254.0,32.256.0,43.234.0"}
P.entries["subzone:war-quarter"] = {n="Воєнний Квартал",s="Воєнний Квартал — північно-західний район Андерсіті, командний пункт і бойовий вишкільний осередок Відступників. У його відлунних кам'яних залах вояки, жерці й ремісники Лордерона відточують зброю й тіньову магію, захищаючи своє молоде королівство. Тут розташовані зали навчання воїнів і жерців, майстри зброї й важке виробництво.",h="Воєнний Квартал — північно-західний район Андерсіті, командний пункт і бойовий вишкільний осередок...",kw={"воєнний квартал","андерсіті","воїни","жерці","ковальство","вівтар темряви"},ang={["class:Warrior"]="Воєнний Квартал — ваш головний прихисток в Андерсіті: тут є майстри зброї, досвідчені бойові наставники й важкі збройні, що підготують вас до жорстоких боїв на передовій Лордерона.",["profession:Blacksmithing"]="Тут є і наставники, і розпечені ковадла, тож Воєнний Квартал — головний осередок для ковалів, що кують зброю й лати для війни Відступників."},sec={{t="Гарнізон Відступників",b="Воєнний Квартал займає північно-західну частину підземного міста й слугує оплотом бойової сили Відступників. Під його похмурими кам'яними арками рядові вартові й добірні поборники збираються, щоб вправлятися в збройному бою. На відміну від звичних казарм у королівствах живих, цей військовий осередок поєднує безжальну залізну війну з моторошними обрядами тіні: тут стоїть зловісний Вівтар Темряви, де духовна дисципліна зливається з військовими прагненнями."},{t="Горно й сталь",b="Окрім гільдій воїнів і жерців, квартал — серце воєнного виробництва Андерсіті. Об кам'яні стіни безупинно відлунює брязкіт клинків і обладунків — це працюють ковалі, плавильники й майстри зброї району. Тут залізо, видобуте глибоко в землі, перетворюють на спорядження для сил, що захищають руїни Лордерона від Погибелі й Багряного Хрестового Походу."}},faq={{q="Яке призначення Воєнного Кварталу?",a="Воєнний Квартал — військовий штаб Андерсіті. Тут є тренувальні майданчики для воїнів і жерців, а також важливі ремісничі осередки ковальства й гірництва, що забезпечують військо Відступників зброєю та обладунками.",al={"що таке воєнний квартал","призначення воєнного кварталу","навіщо йти у воєнний квартал"}},{q="Чому жерці перебувають у Воєнному Кварталі?",a="Жерці Відступників зосереджуються переважно на магії Тіні й використовують її як могутню зброю пліч-о-пліч зі своїми воїнами, а не тримають пастирські святилища. Те, що вони поруч із військом і Вівтарем Темряви, показує, як тісно переплетені віра й війна в обороні Відступників.",al={"де жерці нежиті","чому жерці у воєнному кварталі","наставники жерців підміської"}},{q="Що таке Вівтар Темряви?",a="Вівтар Темряви — осередок темної духовної сили у Воєнному Кварталі. Він пов'язаний з темними обрядами й навчанням Відступників і живить магію тіней, якою володіють їхні жерці й поборники.",al={"вівтар темряви підміська","вівтар воєнного кварталу"}},{q="Де в Андерсіті розташований Воєнний Квартал?",a="Воєнний Квартал займає північно-західну чверть круглого Андерсіті, на північний захід від центрального Торгового Кварталу, між Магічним Кварталом на сході й Апотекаріумом на півдні.",al={"де воєнний квартал","розташування воєнного кварталу","напрямки до воєнного кварталу"}}},fp="11,390,21.477.0,15.390.0,39.237.0,43.313.0,30.216.0,50.196.0"}
P.entries["subzone:war-room"] = {n="Воєнна Кімната",s="Захована глибоко у Фортеці Стормвінда, Воєнна Кімната — стратегічний нервовий центр війська Альянсу. Оточена зброєю, історичними воєнними фоліантами й тактичними мапами, вона служить місцем, де генерали й стратеги стежать за далекими фронтами й координують оборону королівства.",h="Захована глибоко у Фортеці Стормвінда, Воєнна Кімната — стратегічний нервовий центр війська Альянсу.",kw={"воєнна кімната","фортеця стормвінда","стратегія","мапи","альянс","стормвінд"},ang={["class:Warrior"]="Серед важкого озброєння й стратегічних мап командири-воїни оцінять ретельну воєнну організацію, що панує у фортеці.",["faction:Alliance"]="Для солдатів і поборників Альянсу Воєнна Кімната — тактичний мозок оборони королівства від загроз, що досі тліють у Східних Королівствах і далі."},sec={{t="Нервовий центр фортеці",b="Відгалужуючись від величних покоїв Фортеці Стормвінда, Воєнна Кімната облаштована саме для воєнної логістики й планування походів на найвищому рівні. Її кам'яні стіни прикрашають ряди зброї — мечі, мушкетони й навіть важкі гармати. На столах поруч складено купи воєнних трактатів та історичних хронік — як-от розповіді про Другу війну, Падіння Стормвінда й Битву за Ґрім Батол. У центрі кімнати стоїть великий стіл із тактичною мапою, за яким командувачі оцінюють розташування сил Альянсу по всьому Азероту, поки королівський двір вирішує державні справи за кілька кроків звідси."}},faq={{q="Де розташована Воєнна Кімната?",a="Воєнна Кімната міститься у Фортеці Стормвінда, за центральними коридорами королівської твердині. Її легко впізнати за міцними укріпленнями, стояками зі зброєю та великим столом для стратегічного планування.",al={"розташування воєнної кімнати","як знайти воєнну кімнату","де кімната карт"}},{q="Яке призначення цієї кімнати?",a="Це штаб стратегічного планування війська Альянсу в Стормвінді. Тут збираються вищі командири, щоб розглядати донесення розвідки, узгоджувати пересування військ і вивчати минулі й теперішні війни.",al={"для чого воєнна кімната","призначення воєнної кімнати","чому у фортеці воєнна кімната"}},{q="Які історичні відомості можна тут знайти?",a="У кімнаті зберігаються кілька важливих історичних томів Альянсу про переломні війни, зокрема розповіді про Темний Портал і Падіння Стормвінда, Битву за Ґрім Батол і Війну Павука.",al={"книги воєнної кімнати","книги фортеці стормвінда","історичні томи"}}},fp="8,279,24.633.0,30.209.0,33.216.0,39.208.0"}
P.entries["subzone:warpwood-quarter"] = {n="Квартал Кривого Лісу",s="Квартал Кривого Лісу — східна частина зруйнованого міста Високородних Елдре'Таласу, нині відомого як Лютопащ. Колись тут плекали рослини й доглядали пишні ельфійські сади, а тепер квартал перетворився на покручені руїни, отруєні демонами, де буяє навіжена рослинність і хазяйнують зіпсовані сатири.",h="Квартал Кривого Лісу — східна частина зруйнованого міста Високородних Елдре'Таласу, нині відомого як Лютопащ.",kw={"квартал кривого лісу","лютопащ","алззін дикоформ","сатири","лоза скверни","плід родючості","пусіллін"},ang={["class:Druid"]="Покручена доля древніх Кривого Лісу й перетворення Плоду Родючості на мерзенну Лозу Скверни — трагічна образа вчення Кенарія, тож друїди з Місячного Гаю прагнуть очистити квартал.",["race:NightElf"]="Бачити, як величні оранжереї Елдре'Таласу обернулися на кубло сатирів, — похмуре нагадування про скверну, що звалила прадавню Імперію Високородних."},sec={{t="Зіпсований сад",b="Колись Квартал Кривого Лісу славився величними ботанічними дивами, а тепер став задушливим лісом покручених древніх і смертоносних хльостунів. Квартал підкорив Алззін Дикоформ — сатир, що спрямував свою темну магію на осквернення прадавнього Плоду Родючості. Під його лиховісним впливом рослини стали потворними й хижими, зали переповнили мерзенні уламки Лози Скверни, а до зруйнованих покоїв потяглися демони, бунтівні біси й поневолені демонами раби."},{t="Стежки крізь хащі",b="Зазвичай дослідники потрапляють до кварталу через центральний Зруйнований Майдан Лютопащу, проте під Павільйоном Ларісс на сході ховається зарослий підземний чорний хід. Пробираючись кварталом, доводиться мати справу не лише з покрученими вартовими Алззіна, а й із невловимими мешканцями на кшталт пустотливого біса Пусілліна: його крадіжки заводять переслідувачів у небезпечні гонитви до найвіддаленіших закутків руїн."}},faq={{q="Що таке Квартал Кривого Лісу?",a="Квартал Кривого Лісу — східне крило Лютопаща, стародавнього міста Високородних Ельдре'Талас. Колись його звели довкола розкішних оранжерей, але тепер він заріс і спотворився під дією демонічної енергії.",al={"що таке квартал кривого лісу","район кривого лісу","лор східного лютопаща"}},{q="Хто править цим кварталом?",a="Кварталом володіє сатир Алззін Дикоформ. Він приборкав енергію скверни, щоб спотворити місцеві рослини й легендарний Плід Родючості, і перетворив рослинних вартових кварталу на лютих викривлених древніх.",al={"хто контролює кривий ліс","альзін формувальник","бос кривого лісу"}},{q="Як потрапити до Кварталу Кривого Лісу?",a="Головний вхід — із Зруйнованого Торгових Рядів в Лютопащі. Другий, потаємний задній вхід виходить тунелем під Павільйоном Ларісс на сході Фераласу; щоб його відімкнути, потрібен Ключ-Півмісяць.",al={"вхід у кривий ліс","як потрапити до східного лютопаща","вхід у павільйон ларісс"}},{q="Чому біс Пусіллін бігає руїнами?",a="Пусіллін — злодійкуватий біс, що чатує біля входу до кварталу. Коли непрохані гості його помічають, він дражнить їх і тікає глибше в руїни, глузуючи з шукачів пригод аж до Прихованого Закутка.",al={"пусіллін","хто такий пусіллін","біс біжить лютопащем"}}},fp="16,281,18.474.0,31.427.0,29.199.0,24.234.0,38.206.0,50.210.0"}
P.entries["subzone:warrior-s-terrace"] = {n="Тераса Воїна",s="Тераса Воїна — східний район Дарнасуса, водночас бойовий вишкільний осередок і укріплена брама столиці. Вона височіє над дорогою вглиб Тельдрассила, і тут розташовані міські розпорядники битв, наставники воїнів і загони Вартових.",h="Тераса Воїна — східний район Дарнасуса, водночас бойовий вишкільний осередок і укріплена брама столиці.",kw={"тераса воїна","дарнасус","воїни","вартові","ковальство","розпорядники битв"},ang={["class:Warrior"]="Для воїнів, що навчаються в столиці нічних ельфів, цей район — ваша оперативна база: тут ви знайдете наставників бойового мистецтва, місця для поєдинків і розпорядників битв.",["profession:Blacksmithing"]="На терасі працюють міські наставники ковальства й кузні, де кують обладунки та зброю для гарнізону."},sec={{t="Щит Дарнасуса",b="Тераса Воїна, яку іноді називають Залою Правосуддя, лежить на східному порозі Дарнасуса й слугує головним оборонним бастіоном проти вторгнень із диких хащ Тельдрассила. Важкоозброєні Вартові верхи на нічних шаблезубах стережуть її високі арковані брами й пильно наглядають за прибулими. На відкритих майданах тераси молоді бійці вправляються поруч із бувалими ветеранами — на просторих полях для поєдинків і стрільбищах. Район дбає й про практичні військові потреби: тут працюють зброярі, майстри обладунків і розпорядники битв, які скеровують сили нічних ельфів по всьому світу."}},faq={{q="Яке призначення Тераси Воїна?",a="Тераса Воїна — військове серце Дарнасуса і його головний оборонний вхід. Тут працюють міські наставники бойових мистецтв і розпорядники битв, є майданчики для двобоїв і стрільбища, а Вартові стережуть східну браму, що веде на розлогі гілки Тельдрассила.",al={"призначення тераси воїна","що таке тераса воїна","чому тераса воїна"}},{q="Куди веде дорога через східну браму?",a="Велика брама на східному краю тераси веде просто з Дарнасуса на лісові стежки Тельдрассила й з'єднує відлюдну столицю з поселеннями внизу, як-от Доланаар і Селище Рут'теран.",al={"куди веде східна брама","брама тераси воїна","східна брама дарнасуса"}},{q="Хто охороняє квартал?",a="Квартал і його брами охороняють передусім Вартові — добірне постійне військо нічних ельфів. Багато з них патрулюють тераси й брами верхи на закутих у броню нічних шаблезубах.",al={"хто охороняє терасу воїна","вартові тераси воїна","вартові дарнасуса"}},{q="Які інші квартали з'єднані з Терасою Воїна?",a="Мости й переходи з'єднують Терасу Воїна з Терасою Майстрів на півночі, Терасою Ремісників на півдні та пишними Храмовими Садами на заході, ближче до центру міста.",al={"зв'язки тераси воїна","як дістатися до тераси воїна","що поєднується з терасою воїна"}}},fp="17,256,19.626.0,45.284.0,50.225.0,24.191.0,55.206.0"}
P.entries["subzone:warsong-labor-camp"] = {n="Трудовий Табір Бойової Пісні",s="Трудовий Табір Бойової Пісні — відокремлена застава Орди для заготівлі деревини, що сховалася на південному сході Ашенвалю. Тут працюють лісоруби Бойової Пісні під охороною орківських вартових: вони рубають ліс, щоб живити розбудову Дуротара, попри ворожість довколишнього лісу.",h="Трудовий Табір Бойової Пісні — відокремлена застава Орди для заготівлі деревини, що сховалася на південному...",kw={"трудовий табір бойової пісні","деревина","лісоруби","орда","дуротар","ашенваль"},ang={["faction:Horde"]="Деревина, яку заготовляють ці лісоруби, конче потрібна для будівництва й утримання Оргріммара, тож їхня віддалена ділянка — важлива економічна артерія на спірній території.",["race:NightElf"]="Табір — незагойна рана на тілі живого лісу Ашенвалю: тут вирубують гаї предків, щоб живити воєнну машину Дуротара."},sec={{t="Деревина для Орди",b="Трудовий Табір Бойової Пісні, що лежить на схід від Озера Впалого Неба й на південний захід від Курганного Лігва Дор'Даніл, існує з однією важливою метою — заготовляти густий ліс Ашенвалю. Сухі рівнини Дуротара майже не дають придатної деревини, щоб будувати міста на кшталт Оргріммара, тож клан Бойової Пісні змушений просуватися вглиб спірних лісів. Тут працюють витривалі лісоруби й орківська охорона, і табір живе майже відрізаним від світу, перемелюючи прадавні дерева попри постійну загрозу з боку розвідників нічних ельфів і бойових загонів Альянсу."},{t="Вразлива застава",b="Табір лежить далеко від головної дороги й укріплених баз на кшталт Застави Розщепленого Дерева, тож він надзвичайно вразливий. Нападники Альянсу часто б'ють по робітниках і вартових, знаючи, що підкріплення швидко не прийде. Для нічних ельфів кожне зрубане дерево — святотатство, тож цей звичайний лісоповал перетворився на вічну гарячу точку війни в краї."}},faq={{q="Де розташований Трудовий Табір Бойової Пісні?",a="Трудовий табір лежить на південному сході Ашенвалю, на схід від Озера Впалого Неба й на південний захід від Курганного Лігва Дор'Даніл.",al={"розташування трудового табору бойової пісні","де трудовий табір бойової пісні","знайти трудовий табір"}},{q="Яке призначення цього табору?",a="Застава заготовляє деревину. Орки-лісоруби валять і обробляють прадавні дерева Ашенвалю, щоб забезпечити будівельним матеріалом Оргріммар та інші поселення Дуротару.",al={"чому орки тут","що вони тут роблять","призначення табору бойової пісні"}},{q="Чому на табір так часто нападають?",a="Табір стоїть відокремлено, далеко від великих укріплень Орди. Нічні ельфи люто ненавидять вирубку своїх священних лісів, а герої Альянсу часто нападають на заставу, бо через її віддаленість варта поблизу не встигає швидко прийти на допомогу.",al={"напади альянсу на трудовий табір","чому нападають","чи безпечний табір"}},{q="Чи Громмаш Хеллскрім заснував цей табір?",a="Вождь Тралл ще під час Третьої війни послав Громмаша Хеллскріма й клан Бойової Пісні в Ашенваль саме по деревину. Трудовий Табір продовжує ту давню лісозаготівлю.",al={"чи ґром заснував табір","ґром хеллскрім трудовий табір","історія табору"}}},fp="18,280,20.518.0,20.390.0,40.113.0,33.189.0,36.258.0,40.223.0"}
P.entries["subzone:warsong-lumber-camp"] = {n="Лісозаготівельний Табір Бойової Пісні",s="Лісозаготівельний Табір Бойової Пісні — укріплена орківська лісорубня в глибині Ашенвалю, де клан Бойової Пісні заготовляє деревину для Орди. Його опора — укріплена Фортеця Карґатія, і табір водночас є економічною артерією для ближніх поселень Орди та невгамовною провокацією для нічних ельфів. Безупинний гул гоблінських подрібнювачів, що вгризаються в прадавнє віття, робить цю галявину однією з головних гарячих точок лісової війни.",h="Лісозаготівельний Табір Бойової Пісні — укріплена орківська лісорубня в глибині Ашенвалю, де клан Бойової...",kw={"лісозаготівельний табір бойової пісні","фортеця карґатія","подрібнювачі","деревина","орда","ашенваль"},ang={["faction:Horde"]="Деревина, заготовлена тут, іде на будівельні матеріали для Застави Розщепленого Дерева й на укріплення, що оберігають майбутнє Орди на Калімдорі.",["race:NightElf"]="Вищання подрібнювачів і падіння дерев у таборі — прямий, жорстокий замах на священну рівновагу Ашенвалю, і Вартові заприсяглися покласти цьому край."},sec={{t="Серце лісозаготівель",b="Лісозаготівельний Табір Бойової Пісні, вирубаний просто в густих кронах східного Ашенвалю, — промисловий рушій, що живить розширення Орди на Калімдорі. Орки-робітники й наймані гоблінські інженери оголюють ліс гуркітливими подрібнювачами, перетворюючи велетенські стовбури на деревину для стін застав на кшталт сусідньої Застави Розщепленого Дерева й для розбудови молодої держави Дуротар. Табір добре укріплений від постійних контрударів нічних ельфів: його серце — частоколи Фортеці Карґатія та псарня, де тримають лютих бойових вовків клану. Для Бойової Пісні кожне зрубане дерево — це виживання й сила; для корінних Вартових кожне лезо пилки — святотатство."},{t="Спадщина війни",b="Присутність клану Бойової Пісні в цих лісах сягає Третьої війни, коли Ґром Хеллскрім уперше привів своїх воїнів у священні гаї, щоб добувати деревину для Орди. Ця перша вирубка розпалила лють напівбога Кенарія й накликала давній гнів нічних ельфів. Хоч нинішній табір працює під прапорами Орди Тралла, стара ворожнеча палає так само люто. Оточені дикою пущею, ворожими ельфами й демонічною скверною довкола сусіднього Пагорба Вогню Скверни, захисники табору цілодобово при зброї: вони рубають дерева з сокирами напоготові й будь-якої миті готові кинути колоди, щоб відбити чергову засідку."}},faq={{q="Чому Орда рубає ліс в Ашенвалі?",a="Землі, де оселилася Орда, — передусім Дуротар і Пустки — посушливі й бідні, і там бракує міцної деревини для будівель, частоколів і бойових машин. Ашенваль дає величезний, майже невичерпний запас добірного дерева, без якого не вижили б і не розросталися орківські застави на кшталт Застави Розщепленого Дерева та столиця Оргріммар.",al={"чому рубати ліс","причини вирубки бойової пісні","навіщо орді дерево"}},{q="Що таке Фортеця Карґатія?",a="Фортеця Карґатія — укріплена твердиня, на якій тримається Лісозаготівельний Табір Бойової Пісні. Тут є казарми, командний пункт і надійний оплот, куди пеони й наглядачі можуть відступити й відбиватися від засідок нічних ельфів, коли Вартові чи місцеві звірі нападають на лісосіку.",al={"призначення фортеці карґатія","форт у лісозаготівлі","фортеця бойової пісні ашенвейл"}},{q="Чому нічні ельфи такі ворожі до цього табору?",a="Для нічних ельфів Ашенваль — священна земля предків під захистом духів природи й древніх. Валити прадавні дерева галасливими, димними гоблінськими машинами для них — свавільне нищення й відверта наруга, тож вони безперестанку ведуть партизанську війну, щоб вигнати орків Бойової Пісні з лісу.",al={"реакція нічних ельфів","чому ельфи нападають на лісозаготівлю","напади вартових"}},{q="Яку роль відіграють у таборі гобліни?",a="Гобліни-найманці й техніки забезпечують лісозаготівлю особливою технікою, передусім паровими шредерами. Ці машини дають змогу клану Бойової Пісні валити й очищати від гілля величезні прадавні дерева так швидко, як звичайними сокирами ніколи не вдалося б.",al={"гобліни бойової пісні","чому тут подрібнювачі","гоблінські машини ашенвейл"}}},fp="19,433,20.678.0,15.661.0,38.357.0,23.276.0,48.307.0,38.272.0"}
P.entries["subzone:waterspring-field"] = {n="Поле Водяного Джерела",s="Поле Водяного Джерела — життєво важлива водокачна установка на півночі Танарісу, яку гобліни Ґаджетзана збудували, щоб черпати воду з підземних водоносних шарів. Та замість постачати воду до містечка, що бурхливо розростається, поле опинилося в руках безжальних бандитів-Пустельних Блукачів, які тепер тримають при собі найцінніший ресурс пустелі.",h="Поле Водяного Джерела — життєво важлива водокачна установка на півночі Танарісу, яку гобліни Ґаджетзана...",kw={"поле водяного джерела","пустоброди","вода","ґаджетзан","бандити","танаріс"},ang={["profession:Engineering"]="Збудовані гоблінами механічні водокачні вежі — вражаючий зразок пустельної гідравліки.",["race:Human"]="Бандити-Пустельні Блукачі, що захопили вежі, — здебільшого люди-розбійники, які покинули північні королівства, щоб вибороти собі жорстоке життя під пустельним сонцем."},sec={{t="Вкрадена оаза",b="У розпеченій пустці Танарісу ніщо не цінується дорожче за прісну воду. Прагнучи забезпечити свій торговий осередок, що дедалі розростається, гобліни картелю Стімвідл із Ґаджетзана звели на Полі Водяного Джерела ряд промислових водокачних веж, щоб качати воду з підземних запасів. Їхні плани зруйнувалися, коли Пустельні Блукачі — велика зграя людей-розбійників і пустельних мародерів — захопили все поле. Тепер бандити стережуть захоплені насоси, не шкодуючи життя, і Ґаджетзанові доводиться шукати найманих клинків, готових повернути воду."}},faq={{q="Хто збудував тут водонапірні вежі?",a="Вежі збудували гобліни з Ґаджетзана. Вони хотіли качати прісну воду з глибоких підземних запасів, щоб забезпечити своє пустельне поселення й промисли.",al={"хто збудував тут","гоблінські насоси","вежі поля водяного джерела"}},{q="Чому на Полі Водяного Джерела засіли бандити?",a="Кочовики-Пустельні Блукачі захопили поле й заволоділи машинами. Контроль над головним джерелом прісної води на півночі Танарісу дає їм повну владу над довколишніми мандрівниками й купцями.",al={"хто бандити","пустельні мандрівники водяного джерела","чому тут мандрівники пустелі"}},{q="Чому Ґаджетзан не відбиває поле сам?",a="Ґаджетзан наймає шукачів пригод, щоб ті відтіснили бандитів-Пустельних Блукачів і повернули бурдюки з водою. Чому туди не посилають міських вишибал, невідомо.",al={"чому ґаджетзан не воює","гоблінська варта водяного джерела"}}},fp="17,294,14.538.0,32.178.0,53.215.0,51.162.0"}
P.entries["subzone:wavestrider-beach"] = {n="Пляж Хвилеходів",s="Пляж Хвилеходів — випалена сонцем смуга узбережжя на східному краю Танарісу. Він простягається між Портом Стімвідла й піратською твердинею в Бухті Загублених такелажників; на його пісках живуть агресивні ракоподібні, а з берега видно далекі морські сутички.",h="Пляж Хвилеходів — випалена сонцем смуга узбережжя на східному краю Танарісу.",kw={"пляж хвилеходів","порт стімвідла","бухта загублених такелажників","краби","пірати","танаріс"},sec={{t="Підступне узбережжя",b="Пляж Хвилеходів, що тягнеться вздовж океанської межі східного Танарісу, з'єднує гоблінське поселення Порт Стімвідла на півночі зі скелями, які захищають Бухту Загублених такелажників на півдні. Це аж ніяк не тихий курорт: берег потерпає від лютих сталещелепих клацунів і пустельних повзунів, що снують розпеченим піском. А в глибокій воді неподалік від берега палаючі кораблі застигли в нескінченній морській битві — похмуре застереження про піратське насильство, що панує в цих прибережних водах."}},faq={{q="Де розташований Пляж Хвилеходів?",a="Пляж Хвилеходів простягається вздовж східного узбережжя Танарісу, просто між причалами Порту Стімвідла на півночі та гирлом Бухти Загублених такелажників на півдні.",al={"розташування пляжу хвилеходів","де пляж хвилеходів","пляж хвилеходів танаріс"}},{q="Які істоти бродять тутешнім піском?",a="Пляж заполонили агресивні морські падальники, зокрема місцеві пустельні повзуни й закуті в панцир сталещелепі черепахи-кусаки, що нишпорять у прибої.",al={"моби пляжу хвилеходів","краби пляжу хвилеходів"}},{q="Що це за палаючі кораблі вдалині?",a="Дивлячись із пляжу в море, мандрівники бачать два охоплені вогнем кораблі, що досі б'ються між собою. Вони свідчать про розгул піратства у водах довкола сховків Флібустьєрів Південних морів.",al={"палаючі кораблі танаріс","кораблі у вогні біля пляжу хвилеходів"}},{q="Чи безпечно подорожувати Пляжем Хвилеходів?",a="Тут досить небезпечно. Через агресивних черепах-кусак і крабів біля води та близькість володінь піратів Південних морів необережні дослідники можуть швидко опинитися в скруті.",al={"чи небезпечний пляж хвилеходів","безпека пляжу хвилеходів"}}},fp="17,279,23.508.0,35.182.0,37.153.0,44.213.0,44.204.0"}
P.entries["subzone:weathered-nook"] = {n="Обвітрений Закуток",s="Обвітрений Закуток — відлюдна розколина з прихистком, що примостилася високо над дном каньйону під північними скелями Тисячі Голок. Звідси видно безкрає море кам'яних шпилів, і тут знаходять скромну домівку та тихий притулок самотні таурени, які шукають спокійних роздумів далеко від гамірних поселень.",h="Обвітрений Закуток — відлюдна розколина з прихистком, що примостилася високо над дном каньйону під північними...",kw={"обвітрений закуток","тисяча голок","відлюдники","дорн плейнстокер","прейт клаудсір","таурени"},ang={["faction:Horde"]="Мандрівники Орди, що досліджують висоти стін каньйону, знайдуть тут, під північними скелями, привітних одноплемінників.",["race:Tauren"]="Для тауренів-мандрівників Обвітрений Закуток уособлює тихий дух самостійності: це мирне місце над каньйоном, де можна єднатися зі стихіями, далеко від людних мостів Застави Вільного Вітру."},sec={{t="Прихисток на скелях",b="Обвітрений Закуток, видовбаний у прямовисній пісковиковій стіні на північ від Застави Вільного Вітру, легко проминути, коли йдеш улоговиною каньйону внизу. Природний схил в'ється вгору стіною й виводить на захищений уступ і печеру, куди не дістають вітри. Тут немає ні військової застави, ні великого поселення — закуток слугує скромною оселею для самотніх мандрівників, як-от Дорн Плейнстокер і Прейт Клаудсір, даруючи безпеку, усамітнення й широкий краєвид на обвітрені плато-голки."}},faq={{q="Де розташований Обвітрений Закуток?",a="Закуток ховається під північною скельною стіною Тисячі Голок. Від Застави Вільного Вітру йдіть на північ до височенної скелі, а потім уздовж скель на схід, доки не знайдете звивистий підйом на стіну столової гори.",al={"як знайти обвітрений закуток","розташування обвітреного закутка","де закуток"}},{q="Хто живе в Обвітреному Закутку?",a="Це притулок Дорна Плейнстокера і Прейта Клаудсіра — тауренів-відлюдників, які обрали цей віддалений уступ над каньйоном замість людних веж Застави Вільного Вітру.",al={"хто тут","мешканці обвітреного закутка","нпс закутка"}},{q="Чи пов'язаний Обвітрений Закуток з Ордою?",a="Мешканці закутка — таурени й природно тримаються своїх родичів, але це не офіційний гарнізон Орди. Це скромний особистий табір і житло, тихо заховане в глушині.",al={"чи це табір орди","орда обвітрений закуток"}}},fp="14,319,19.505.0,36.227.0,32.191.0,48.189.0"}
P.entries["subzone:weazel-s-crater"] = {n="Кратер Візела",s="Кратер Візела — глибока вибоїна в твердій солі північної частини Мерехтливих Низин. Його походження загадкове, а в западині живуть солекамінні василіски.",h="Кратер Візела — глибока вибоїна в твердій солі північної частини Мерехтливих Низин.",kw={"кратер візела","мерехтливі низини","василіски","ракетні автомобілі","траса","кратер"},ang={["profession:Engineering"]="Глибока западина лежить серед експериментальних гоночних машин і уламків Мерехтливих Низин. Інженерам, що навідуються на трасу, є всі підстави уважно вивчити цю небезпечну місцевість."},sec={{t="Вибухова спадщина",b="На сліпучо-білих просторах Мерехтливих Низин експериментальні гоблінські й гномські ракетні автомобілі повсякчас розсувають межі механічного здорового глузду. Рівнини всіяні уламками, випаленою землею й вибоїнами від ударів, але Кратер Візела вирізняється з-поміж них самим розміром і глибиною. Звідки взявся кратер, невідомо. Нині уламки здебільшого вляглися, а западину облюбували для гріння на сонці агресивні солекамінні василіски."}},faq={{q="Звідки взявся Кратер Візела?",a="Походження кратера невідоме. Причину не встановлено.",al={"як утворився кратер візела","походження кратера візела","чому тут кратер"}},{q="Хто нині живе в кратері?",a="Нині западину населяють небезпечні солекамінні василіски, що чатують на кам'янистих краях і дні ями.",al={"моби кратера візела","що всередині кратера"}}},fp="15,163,17.446.0,28.58.0,29.127.0"}
P.entries["subzone:webwinder-path"] = {n="Стежка Павутинника",s="Стежка Павутинника — звивиста гірська дорога в Горах Кам'яного Кігтя, що з'єднує тролячу заставу Малака'джин з Озером Міркфаллон. Вона пролягає крізь дикі скелі й густі високогірні ліси, де живуть агресивні павуки та тутешні звірі.",h="Стежка Павутинника — звивиста гірська дорога в Горах Кам'яного Кігтя, що з'єднує тролячу заставу Малака'джин...",kw={"стежка","павуки","громові ящери","малака'джин","озеро міркфаллон","гори кам'яного кігтя"},ang={["class:Hunter"]="На стежці водяться дужі громові ящери, міцні гірські барани й отруйні павуки-ткачі, тож це чудовий шлях, щоб розвідувати й приручати звірів Кам'яного Кігтя.",["faction:Horde"]="Стежка — важлива сухопутна артерія просто на порозі Малака'джина, що з'єднує ваших розвідників із глибшими долинами Кам'яного Кігтя."},sec={{t="Підступний шлях",b="Стежка Павутинника, що біжить від поселення Орди Малака'джин до Озера Міркфаллон, — одна з головних доріг крізь нижні Гори Кам'яного Кігтя. Як і годиться за назвою, шлях славиться густим павутинням, натягнутим високо серед крон і зубчастих скель. Мандрівникам на цій звивистій дорозі доводиться пильно дивитися під ноги, ділячи второвану стежку з гірськими павуками, що чатують на здобич, агресивними громовими ящерами та войовничими баранами, які стережуть свою територію."}},faq={{q="Куди веде Стежка Павутинника?",a="Стежка Павутинника тягнеться від застави тролів Темного Списа Малака'джин на півдні до Озера Міркфаллон вище в горах на півночі.",al={"розташування стежки павутинника","де стежка павутинника","що з'єднує стежка павутинника"}},{q="Чому вона зветься Стежкою Павутинника?",a="Назву дорога отримала через сила-силенну павуків у цьому краї. Павуки плетуть величезні лабіринти блискучого шовку високо на деревах і на скелястих уступах обабіч дороги.",al={"чому павутинник","чому вона так зветься"}},{q="Які істоти бродять стежкою?",a="Окрім отруйних павуків, що плетуть павутину над дорогою, мандрівники часто натрапляють на громових ящерів, гірських баранів і звичайну гірську дрібноту.",al={"що тут живе","звірі стежки павутинника","моби стежки павутинника"}},{q="Чи безпечна Стежка Павутинника?",a="Аж ніяк. Місцеві хижаки люті й ревно стережуть свої угіддя, а дорога проходить просто повз табір Орди в Малака'джині, тож для мандрівників Альянсу, що піднімаються сюди з Пусток, вона дуже небезпечна.",al={"чи небезпечна стежка павутинника","чи може альянс ходити стежкою павутинника"}}},fp="14,242,26.465.0,31.145.0,32.195.0,31.166.0,33.205.0"}
P.entries["subzone:weeping-cave"] = {n="Плакуча Печера",s="Плакуча Печера — смердючий підземний грот серед пагорбів на північному сході Західних Чумних Земель, трохи на захід від Річки Тондроріл. Колись це були звичайні природні печери, а тепер із їхніх стін сочиться отруйна гниль, і в них кишать потворні грибні звірі та слизуни.",h="Плакуча Печера — смердючий підземний грот серед пагорбів на північному сході Західних Чумних Земель, трохи на...",kw={"плакуча печера","річка тондроріл","оболонка","слизуни","західні чумні землі","гниль"},ang={["class:Druid"]="Плакуча Печера — потворне перекручення природи: тут підземну флору й стихійні сили чума нежиття спотворила до решти й обернула на люті потвори."},sec={{t="Кубло гнилі",b="Плакуча Печера, видовбана в крутих урвищах над Річкою Тондроріл, дістала свою назву через воду, що безперервно скрапує крізь кам'яне склепіння, — воду, яка давно стала смердючою й отруєною. Чума Погибелі просочила ґрунт нагорі наскрізь, і отруйний бруд стікає вниз, у темряву. Вогкими тунелями всередині блукають гнилі страхіття, зотлілі велетні та їдкі слизуни, а з ними — загадковий спотворений елементаль, відомий просто як Оболонка."}},faq={{q="Де розташована Плакуча Печера?",a="Плакуча Печера лежить у північно-східному куті Західних Чумних Земель, серед скелястих хребтів трохи на захід від Річки Тондроріл, біля кордону зі Східними Чумними землями.",al={"розташування плакучої печери","де плакуча печера","знайти плакучу печеру"}},{q="Які істоти живуть у печері?",a="Печеру заполонили шкутильгаючі рослиноподібні гидоти — гнилі велетні й жахи, що розкладаються, — а ще отруйні повзучі слизовики та рідкісний закатований елементаль на ім'я Оболонка.",al={"монстри плакучої печери","що всередині плакучої печери","моби плакучої печери"}},{q="Чому її звуть Плакучою Печерою?",a="Зі стелі печери постійно капає вода, і здається, ніби камінь плаче. Проте після чуми ці потічки перетворилися на смердючу гнилу сочівку, у якій буйно розростається отруйна пліснява.",al={"чому вона плакуча","значення плакучої печери"}},{q="Хто така Оболонка?",a="Оболонка — рідкісна спотворена елементальна істота з глибин Плакучої Печери, викривлена й понівечена алхімічною пошестю, що досі отруює довколишню землю й воду.",al={"оболонка","оболонка плакуча печера","рідкісна оболонка"}}},fp="12,256,12.485.0,34.189.0,37.198.0,34.226.0,16.188.0"}
P.entries["subzone:wellspring-lake"] = {n="Озеро Джерела",s="Озеро Джерела — тиха прісна водойма високо в гіллі Тельдрассила, на північний схід від Дарнасуса. Живлене природними джерелами з глибин Світового Дерева, воно дає початок звивистій Річці Джерела. Колись мирний притулок рибалок нічних ельфів, береги озера стали жертвою скверни, що збурює живність Тельдрассила.",h="Озеро Джерела — тиха прісна водойма високо в гіллі Тельдрассила, на північний схід від Дарнасуса.",kw={"озеро джерела","річка джерела","деревляники","риболовля","дарнасус","тельдрассил","скверна"},ang={["class:Druid"]="Друїди вивчають збурених деревляників і звірів біля Озера Джерела, щоб зрозуміти джерело неприродної хвороби, яка шириться водами й ґрунтом Тельдрассила.",["race:NightElf"]="Для калдореїв перетворення мирних гаїв на кшталт Озера Джерела на небезпечні лігва чудовиськ — болісне нагадування, що з їхнім молодим Світовим Деревом щось глибоко не так."},sec={{t="Споганений притулок",b="Озеро Джерела під кроною між Дарнасусом і Галявиною Оракула калдореї здавна плекали як тихий прихисток для риболовлі й роздумів. Його прозорі води беруть початок із підземних джерел, що біжать велетенським гіллям Світового Дерева, а далі стікають на північ Річкою Джерела. Та останнім часом підступна пошесть почала охоплювати довколишні хащі. Агресивні павуки, нічні шаблезуби, що нишпорять довкола, і збурені деревляники тепер бродять берегами, і колись ідилічний ставок став підступним місцем для необачних мандрівників."}},faq={{q="Де розташоване Озеро Джерела?",a="Озеро Джерела лежить на півночі Тельдрассила, на північний схід від столиці Дарнасус і трохи на південний схід від Галявини Оракула.",al={"де озеро джерела","розташування озера джерела","як дістатися до озера джерела"}},{q="Звідки береться вода в озері і куди витікає?",a="Озеро живлять природні джерела, що б'ють із глибини коренів і деревини самого Тельдрассила. Надлишок води стікає в Річку Джерела, що тече на північ до краю дерева.",al={"куди стікає озеро джерела","витік річки джерела","джерело води озера джерела"}},{q="Чому біля Озера Джерела небезпечно?",a="Колись це було тихе місце, яке полюбляли рибалки-калдореї, але спотворення, що шириться Світовим Деревом, довело місцевих звірів до шаленства. Тепер берегом нишпорять нічні шаблезуби, велетенські лісові павуки й спотворені деревляники — духи кори.",al={"що живе біля озера джерела","моби озера джерела","чому озеро джерела ворожить"}},{q="Хто колись збирався біля Озера Джерела?",a="Місцеві рибалки з нічних ельфів часто приходили до озера поміркувати в тиші й порибалити, доки недавня пошесть не розлютила звірів і не зробила береги небезпечними.",al={"історія озера джерела","нічноельфійські рибалки на озері"}}},fp="15,384,16.584.0,33.127.0,45.193.0,49.252.0,38.161.0"}
P.entries["subzone:wellspring-river"] = {n="Річка Джерела",s="Річка Джерела витікає з природного джерела в Тельдрассилі й біжить на північ з Озера Джерела, аж поки не зривається з гілля велетенським водоспадом в океан далеко внизу. Колись мирне джерело прісної води для всієї живності Світового Дерева, її береги стали небезпечними через збурену місцеву живність.",h="Річка Джерела витікає з природного джерела в Тельдрассилі й біжить на північ з Озера Джерела, аж поки не...",kw={"річка джерела","озеро джерела","водоспад","деревляники","тельдрассил","світове дерево"},ang={["class:Druid"]="Зіпсутий, знавіснілий стан тутешніх деревляників річки — тривожна ознака хвороби, що повзе всією живою системою Тельдрассила.",["race:NightElf"]="Прісні потоки, що течуть із серця Тельдрассила, утілюють життєву силу нової домівки калдореїв, тож неспокій на їхніх берегах глибоко тривожить."},sec={{t="Води Світового Дерева",b="Живлена глибокими природними джерелами в гіллі Тельдрассила, Річка Джерела несе воду на північ з Озера Джерела через зелений ліс, а тоді велично падає з краю великого дерева в море внизу. Попри мирне довкілля, береги річки стають дедалі небезпечнішими. Деревляники, що живуть уздовж води, знавісніли й стали ворожими: вони люто нападають на мандрівників і друїдів, які намагаються підійти до річки."}},faq={{q="Куди тече Річка Джерела?",a="Річка Джерела витікає з Озера Джерела на північ. Зрештою вона досягає краю крони Тельдрассила й обривається величезним водоспадом, що падає аж в океан унизу.",al={"куди тече річка","призначення річки джерела","куди тече річка джерела"}},{q="Чому деревляники вздовж річки нападають на перехожих?",a="Деревляники на Річці Джерела стали непередбачуваними й шаленими і кидаються на кожного, хто проходить поруч. Ця агресія — частина ширшого неспокою серед природних мешканців Тельдрассила, що непокоїть місцевих друїдів нічних ельфів.",al={"чому деревляники агресивні","скажені деревляники джерела","чому деревляники ворожі"}},{q="Звідки береться вода в річці?",a="Річку живить безпосередньо Озеро Джерела, а його наповнює природне прісне джерело, що б'є з глибини живого стовбура й гілок Світового Дерева.",al={"звідки вода річки джерела","джерело води"}}},fp="16,318,24.486.0,37.221.0,57.249.0,44.173.0"}
P.entries["subzone:westbrook-garrison"] = {n="Гарнізон Вестбрук",s="Гарнізон Вестбрук — застава вартових Стормвінда на західному краю Лісу Елвінн, поблизу кордону з Вестфолом. Її тримає перевантажена, погано забезпечена жменька вартових під проводом Помічника Рейнера, і це перша лінія оборони королівства проти гнолів Річколапів, що насуваються, і розбійників-відступників.",h="Гарнізон Вестбрук — застава вартових Стормвінда на західному краю Лісу Елвінн, поблизу кордону з Вестфолом.",kw={"гарнізон вестбрук","застава","вартові стормвінда","помічник рейнер","гоґґер","гноли","ліс елвінн"},ang={["class:Warrior"]="Обложені вартові Вестбруку — образ перенапруженого королівства, що стримує хижаків глушини самою лише впертістю, і тут удосталь простої, брутальної роботи із зачистки бойових загонів гнолів.",["faction:Alliance"]="Для захисників Альянсу, що вирушають з Елвінну до Вестфолу, убезпечити околиці Вестбруку й забрати винагороду за Гоґґера вкрай важливо, щоб західні кордони серця королівства лишалися безпечними."},sec={{t="Обложений прикордонний пост",b="Гарнізон Вестбрук, що стоїть там, де Ліс Елвінн починає рідшати в бік Вестфолу, — важливий, але знесилений спостережний пункт. Оскільки більшу частину армії Стормвінда відрядили за кордон або скувала політична інертність у столиці, застава лишилася критично нечисленною. Помічник Рейнер і його жменька вартових мусять патрулювати західні дороги, водночас відбиваючись від знахабнілих злодіїв і лютих гнолів Річколапів, що заполонили південні ліси. Не маючи змоги добитися офіційного підкріплення від Маршала Дуґана в Ґолдширі, гарнізон майже цілком покладається на мандрівних шукачів пригод, щоб убезпечити шлях."},{t="Загроза Узлісся",b="Головна загроза Вестбруку — дедалі більша присутність гнолів, зосереджена на південь від Узлісся. Зграї знахабніли настільки, що нападають просто на обози з припасами й садиби, згуртовані під проводом грізного ватажка гнолів, відомого як Гоґґер. Переважений числом і грубою силою війська Гоґґера, гарнізон вивісив по всій своїй території високу винагороду, відчайдушно шукаючи здібних бійців, готових вирушити в пагорби й убити звіра, перш ніж той просунеться далі на схід."}},faq={{q="Чому в Гарнізоні Вестбрук так бракує людей?",a="Більшість війська Стормвінда воює за кордоном, а через нерішучість Дому Вельмож у столиці місцеві гарнізони не отримують ні свіжих сил, ні припасів. Командирам Вестбрука доводиться покладатися на мандрівних шукачів пригод, щоб латати дірки.",al={"чому так мало вартових","підкріплення вестбрука","помічник рейнер бракує людей"}},{q="Хто командує гарнізоном?",a="Справами в Гарнізоні Вестбрук керує Помічник Рейнер. Він підпорядковується безпосередньо Маршалові Дуґану в Ґолдширі, хоча на його прохання про підкріплення здебільшого не відповідають.",al={"хто командує вестбруком","роль помічника рейнера","командир вестбрука"}},{q="Яким загрозам протистоїть гарнізон?",a="Гарнізон має справу з бандитами, що просочуються з Вестфолу, і лютими гнолами-Річколапами, які стоять табором у довколишніх лісах на чолі зі своїм небезпечним ватажком Гоґґером.",al={"загрози вестбруку","гноли вестбрука","хто нападає на вестбрук"}},{q="Як пов'язані Вестбрук і Вестфол?",a="Гарнізон Вестбрук — остання застава Лісу Елвінн на західній дорозі перед мостом до Вестфолу. Він стереже кордон від беззаконня, що наростає на заході.",al={"чи вестбрук у вестфоллі","межа з вестфоллом"}}},fp="18,300,25.608.0,27.516.0,42.261.0,34.192.0,36.176.0,52.187.0"}
P.entries["subzone:westfall-lighthouse"] = {n="Маяк Вестфолу",s="Маяк Вестфолу стоїть на скелястому острівці біля південно-західного берега Вестфолу й колись застерігав кораблі від підступних мілин Великого Моря. Нині живих доглядачів маяка вже немає: їх вигубив жорстокий напад горезвісного мурлока Старого Мутноокого, і за вогнем наглядає лише дух Капітана Ґрейсона.",h="Маяк Вестфолу стоїть на скелястому острівці біля південно-західного берега Вестфолу й колись застерігав...",kw={"маяк вестфолу","вестфол","капітан ґрейсон","старий мутноокий","мурлоки","привид"},ang={["faction:Alliance"]="Маяк — промовистий символ того, що руки Стормвінда вже не сягають так далеко: самотніх слуг королівства покинули без військової підтримки на поталу диким прибережним тварюкам."},sec={{t="Вогонь в імлі",b="Маяк, зведений на підступних південно-західних скелях Вестфолу, довго вказував безпечний шлях кораблям, що йшли узбережжям поблизу Стормвінда. Та коли закон і порядок у краї розвалилися, а королівські патрулі порідшали, прибережні небезпеки розрослися без упину. Спершу маяк доглядала родина наглядачів, але войовничі племена мурлоків витіснили їх углиб суходолу. Сім'я мужньо повернулася, щоб знову запалити вогонь, однак сумнозвісний мурлок-грабіжник Старий Мутноокий зібрав родичів у другий, безжальний наступ — родину вирізали, а маяк згас."},{t="Примарна варта",b="Після трагедії маяк не лишився зовсім покинутим. На скелястому виступі блукає привид Капітана Ґрейсона — прикутий до місця, де він безпорадно дивився, як гине родина. Він не може спочити, доки маяк темний, а берегом повзають чудовиська, тож просить шукачів пригод зібрати мастило з големів жнив, щоб підтримувати вогонь, і вистежити Старого Мутноокого, аби помститися за полеглих доглядачів."}},faq={{q="Чому Маяк Вестфолу покинутий?",a="Місцеві мурлоки вигнали людську родину, що доглядала маяк. Коли родина повернулася, щоб знову запалити вогонь, Старий Мутноокий повів другий набіг і вирізав усю сім'ю на очах у Капітана Ґрейсона.",al={"що сталося з доглядачами","хто жив на маяку","чому маяк у руїнах"}},{q="Хто такий Капітан Ґрейсон?",a="Капітан Ґрейсон — привид, що блукає острівцем біля маяка. Скутий провиною й обов'язком після загибелі доглядачів, він просить відважних мандрівників збирати олію, щоб маяк світив, і полювати на прибережних мурлоків, винних у вбивстві.",al={"привид на маяку","хто привид","капітан ґрейсон історія"}},{q="Хто такий Старий Мутноокий?",a="Старий Мутноокий — надзвичайно хитрий і лютий ватажок мурлоків, що нишпорить узбережжям Вестфолу. Він зібрав прибережні племена, щоб захопити маяк і перебити доглядачів.",al={"мутноокий","бос мурлоків","хто вбив доглядачів"}},{q="Чи маяк досі працює?",a="Механічний ліхтар досі працює й уночі кидає над океаном широкий промінь світла, а Капітан Ґрейсон просить мандрівників принести олію, щоб вогонь не згас.",al={"чи горить маяк","чи працює маяк"}}},fp="19,333,20.561.0,17.438.1,41.213.0,23.244.0,20.183.0,35.184.0"}
P.entries["subzone:whelgar-s-excavation-site"] = {n="Місце Розкопок Велґара",s="Місце Розкопок Велґара — дворфійські археологічні розкопки на західних пагорбах Багнокраю. Експедиція мала відкопати прадавні реліквії титанів і доісторичні таємниці, але скінчилася катастрофою, коли кар'єр заполонили люті плямисті раптори. Уцілілі копачі тепер застрягли на гребені над розкопками, відрізані від своїх знахідок.",h="Місце Розкопок Велґара — дворфійські археологічні розкопки на західних пагорбах Багнокраю.",kw={"місце розкопок велґара","багнокрай","раптори","ліга дослідників","розкопки","гавань менетіл"},ang={["profession:Mining"]="Величезні оголені стіни кар'єру й розкопана корінна порода — чудові жили для гірників, які наважаться працювати під гарчання голодних рапторів.",["race:Dwarf"]="Кожні розкопки, покинуті на поталу диким звірам, — образа для Ліги Дослідників. Повернути дослідження Велґара — означає захистити вашу спадщину й відвоювати викрадені таємниці титанів."},sec={{t="Зруйнована експедиція",b="Дворфійські рудошукачі, що шукали прадавні скам'янілості й таємниці землян, вирили величезний кар'єр між Гаванню Менетіл і Дун Модром. Та розкопані доісторичні рештки накликали гнів місцевих плямистих рапторів. Не маючи ні сил, ні спорядження, археологи відступили на гребінь над розкопками, покинувши намети, інструменти й відкопані реліквії серед хижаків, що там никають."}},faq={{q="Чому розкопки покинули?",a="Дворфи-археологи випадково потривожили угіддя агресивних плямистих рапторів. Коли ці люті звірі заполонили розкоп, уцілілі робітники сховалися на хребті над ним.",al={"чому покинуто","що сталося з розкопками","чому залишили розкопки"}},{q="Що тут шукали дворфи?",a="Дворфи шукали доісторичні скам'янілості й підземні артефакти, сподіваючись знайти давні підказки про свою спадщину Титанів і далеке минуле світу.",al={"що шукають дворфи","мета розкопок","ціль велґара"}},{q="Які загрози бродять розкопом тепер?",a="Дно кар'єру й довколишні хребти кишать плямистими рапторами, серед них — і грізний раптор Гарчозуб.",al={"що в розкопках","моби розкопок","раптори багнокраю"}},{q="Куди поділися вцілілі археологи?",a="Уцілілі робітники разом із Шукачем Велґаром застрягли на хребті над розкопом і шукають відважних шукачів пригод, які повернули б їхні втрачені дослідження.",al={"де велґар","де дворфи","де вцілілі розкопок"}}},fp="25,349,19.434.0,38.196.0,39.169.0,34.113.0,38.170.0"}
P.entries["subzone:whispering-forest"] = {n="Шепітливий Ліс",s="Шепітливий Ліс — відлюдний гірський ліс, схований за стрімкими скелями на захід від Похоронного Подзвону. Майже відрізаний від решти Галявин Тірісфалю, він ховає моторошну живність, таємниче відьмине коло й глибоко вкорінену скверну, що спить далеко під землею.",h="Шепітливий Ліс — відлюдний гірський ліс, схований за стрімкими скелями на захід від Похоронного Подзвону.",kw={"шепітливий ліс","відьмине коло","гриби","лицар скорботи","високі ельфи","тіньова долина","фортеця бандаріон","тірісфаль"},ang={["class:Druid"]="Сяйливе відьмине коло вирізняється як один із небагатьох проблисків природної магії, що лишилися в ураженому чумою Лордероні.",["race:Undead"]="Схований одразу за Похоронним Подзвоном і піднаглядний Варті Тіра у Фортеці Бандаріон, відлюдний ліс ховає забуті небезпеки — мовчазну загрозу просто на порозі Андерсіті."},sec={{t="Прихована долина",b="Шепітливий Ліс, який ховають Камінь Північного Лику й Фортеця Бандаріон, здається зовсім чужим довколишньому ураженому чумою королівству. Хоч тут водяться хворі олені й мандрівні хижаки, тут також є тихе озеро й дивне коло велетенських грибів, що світяться моторошною енергією під завислою хмарою імли. Примарний Лицар Скорботи блукає відьминим колом, прив'язаний до нього клятвою, серед природної магії, яка немов кидає виклик зруйнованій Погибеллю землі."},{t="Тінь під лісом",b="Попри зовнішнє диво, ліс отруєний давнім жахом. Століття тому високі ельфи ненадовго спробували оселитися в Галявинах Тірісфалю, та їх прогнало приховане зло, що спить глибоко під землею й почало зводити їх з розуму. Довкола місцевого озера нишпорять мурлоки Темноплавців й трешадон-нежить Блайтскаллер, а зруйноване поселення Тіньова Долина уражене некромантичними рештками. Навіть божевільні блукальці по всьому Лордерону бурмочуть налякані застереження про всепоглинальну темряву, що спочиває під корінням Тірісфалю."}},faq={{q="Де розташований Шепітливий Ліс?",a="Ліс лежить у горах на заході Галявин Тірісфалю, трохи на захід від Похоронного Подзвону й на південь від Падіння Тіра. Його відгороджує Камінь Північного Схилу — крутий хребет, на якому стоїть Фортеця Бандаріон.",al={"розташування шепітливого лісу","де шепітливий ліс","як дістатися до шепітливого лісу"}},{q="Що відбувається біля кола велетенських грибів?",a="Коло велетенських грибів світиться дивною енергією під хмарою туману, що висить над ним. Примарний Лицар Жалоби, зв'язаний клятвою, блукає цим колом, але що це за магія насправді — невідомо.",al={"коло грибів тіріфаль","кільце фей-драконів","ритуал фей"}},{q="Хто пильнує ліс?",a="Висоти Фортеці Бандаріон над лісом тримає Варта Тіра — орден паладинів-Відступників. А біля самого чарівного кола клятва прирікає примарного Лицаря Жалоби блукати лісом.",al={"хто охороняє шепітливий ліс","бандаріон шепітливий ліс"}},{q="Чому високі ельфи колись давно покинули цей край?",a="Коли високі ельфи вперше висадилися на берегах Лордерона, вони спробували заснувати поселення в Тірісфалі. За кілька років якась тривожна сила, похована глибоко під землею, почала підточувати їхній розум, і вони мусили покинути галявини й рушити на північ.",al={"високі ельфи тіріфаль","чому ельфи покинули тіріфаль","безумство під тіріфалем"}},{q="Що таке Тіньова Долина?",a="Тіньова Долина — зруйноване село на південний захід від лісового озера. Його займають Потьмянілі разом із безмозкою нежиттю, яку вразив некромантичний уламок кристала, що лишився з часів сутичок за участю Андерсіті.",al={"тіньова долина тіріфаль","зруйноване село шепітливого лісу"}}},fp="17,273,15.481.0,28.542.1,39.205.0,42.216.0,28.197.0,52.261.0,19.221.0"}
P.entries["subzone:whispering-gardens"] = {n="Шепітливі Сади",s="Шепітливі Сади займають терасований схил трохи на південь від Багряного Монастиря на північному сході Галявин Тірісфалю. Колись це було місце тихих роздумів, а потім тут відбулася жорстока сутичка між першими захисниками Походу й величезним військом Погибелі. Нині хрестоносці патрулюють зарослі стежки, а в повітрі досі бринять ледь чутні голоси полеглих.",h="Шепітливі Сади займають терасований схил трохи на південь від Багряного Монастиря на північному сході Галявин...",kw={"шепітливі сади","багряний монастир","галявини тірісфалю","привиди","хрестоносці","погибель"},ang={["class:Priest"]="Жерці, що ходять цими терасами, відчувають духовний слід святих захисників, які загинули страшною смертю в боротьбі з Погибеллю, — їхні душі навіки прив'язані до вітрів.",["race:Undead"]="Для Відступників сади — живе вогнище фанатичного опору Багряних просто на порозі Тірісфалю, де досі витає дух тієї самої війни, що прирекла Лордерон."},sec={{t="Битва, що відлунює в імлі",b="Ще до того, як Багряний Хрестовий Похід остаточно відступив за мури Монастиря, на цих терасованих схилах спалахнула запекла битва з армією нежиті, що наступала. Сутичка забрала безліч життів з обох боків. Мандрівники, що проходять садами в сутінках, розповідають, що чують у вітрі дивний тихий шепіт, — кажуть, це неспокійне відлуння воїнів і жерців, які загинули, захищаючи святу землю."},{t="Застава Хрестоносців",b="Попри моторошну присутність привидів, Багряний Хрестовий Похід пильно стереже сади. Багряні розвідники, маги й охоронці чатують на стежках, щоб перехоплювати зайд, які підходять із нижніх галявин. Для фанатиків із сусіднього монастиря ці зарослі сходи — і оборонний вал, і урочисте нагадування про безупинну війну з нежиттю."}},faq={{q="Де розташовані Шепітливі Сади?",a="Шепітливі Сади лежать на північному сході Галявин Тірісфалю й укривають схил одразу на південь від входу до Багряного Монастиря.",al={"розташування шепітливих садів","де шепітливі сади","як дістатися до шепітливих садів"}},{q="Чому їх звуть Шепітливими Садами?",a="Назва походить від ледь чутного примарного шепоту в сутінковому повітрі. Кажуть, це блукають духи захисників і нежиті, що полягли в кривавій битві на цих схилах.",al={"чому шепітливі сади","що за шепіт","назва шепітливих садів"}},{q="Яка битва тут відбулася?",a="Тут точилася відчайдушна битва між першими загонами, з яких згодом постав Багряний Хрестовий Похід, і військом Погибелі. Бійці гинули сотнями, перш ніж Погибель зупинили під стінами монастиря.",al={"битва шепітливих садів","що сталося в шепітливих садах"}},{q="Хто контролює сади тепер?",a="Сади контролює Багряний Хрестовий Похід. Багряні розвідники, хранителі й маги патрулюють тераси, захищаючи південні підступи до своєї твердині.",al={"хто живе в шепітливих садах","монстри шепітливих садів"}}},fp="18,364,28.432.0,16.379.0,41.143.0,43.180.0,28.211.0,29.156.0"}
P.entries["subzone:whispering-shore"] = {n="Шепітливий Берег",s="Шепітливий Берег — похмура смуга узбережжя в західних Галявинах Тірісфалю; одразу на південь від нього лежить Хутір Соллідена. Колись тихий і щедрий притулок рибалок Лордерона, його холодні води відтоді захопило люте плем'я мурлоків.",h="Шепітливий Берег — похмура смуга узбережжя в західних Галявинах Тірісфалю; одразу на південь від нього лежить...",kw={"шепітливий берег","узбережжя","мурлоки","муад","рибалки","хутір соллідена","тірісфаль"},ang={["race:Undead"]="Для Відступників, що убезпечують західні Галявини Тірісфалю, навала мурлоків на Шепітливому Березі — некерована загроза просто вздовж межі їхніх володінь."},sec={{t="Зруйнована гавань",b="До того як Третя війна прокотилася північним Лордероном, Шепітливий Берег славився серед місцевих як улюблена рибальська гавань, відома спокійними водами й багатими уловами. Сьогодні крижані бризки Великого Моря б'ються об порожній берег, позбавлений свого мирного минулого. Води стали холодними й темними, без колишньої щедрості, і кожен нещасний мандрівник, що спуститься з пагорбів, ризикує потрапити в засідку ревнивих до своєї території прибережних мешканців."},{t="Загроза мурлоків",b="Пляж тепер міцно тримає ватага ворожих мурлоків, що безжально нападають на кожного, хто наближається до прибою. На чолі з лютим вождем на ім'я Муад ці водяні падложери агресивно стережуть мілини й припливні обмілини, становлячи постійну небезпеку для сусідніх доріг і для сусіднього Хутора Соллідена."}},faq={{q="Де розташований Шепітливий Берег?",a="Шепітливий Берег тягнеться вздовж західного узбережжя Галявин Тірісфалю, просто на північ від Хутора Соллідена.",al={"розташування шепітливого берега","де шепітливий берег","шепітливий берег на мапі"}},{q="Що було на Шепітливому Березі до Погибелі?",a="За часів Королівства Лордерон берег був улюбленим тихим куточком місцевих рибалок, яких вабили багаті прибережні води.",al={"історія шепітливого берега","для чого шепітливий берег","минуле шепітливого берега"}},{q="Хто контролює Шепітливий Берег тепер?",a="Узбережжя захопило плем'я агресивних мурлоків на чолі з особливо лютим ватажком Муадом. Вони нападають на кожного, хто наближається до води.",al={"хто живе на шепітливому березі","вороги шепітливого берега","моби шепітливого берега"}},{q="Чи можна досі спокійно рибалити на Шепітливому Березі?",a="Берег уже не той мирний прихисток, яким був колись. Води тут холодні й темні, давно втратили колишнє багатство, а ворожі мурлоки завзято стережуть узбережжя.",al={"риболовля на шепітливому березі","риба шепітливого берега"}}},fp="16,263,14.468.0,17.299.0,38.111.0,59.136.0,38.171.0,54.183.0"}
P.entries["subzone:whitereach-post"] = {n="Застава Білого Рубежу",s="Застава Білого Рубежу — невеликий табір Орди при запорошеній дорозі каньйоном Тисячі Голок. Ця скромна придорожня станція неподалік від Табору Е'ток дає змогу перепочити й пильно стежить за суворим пустельним шляхом. Для мандрівників між Фераласом і солончаками це острівець безпеки Орди під грізними пісковиковими стовпами.",h="Застава Білого Рубежу — невеликий табір Орди при запорошеній дорозі каньйоном Тисячі Голок.",kw={"застава білого рубежу","тисяча голок","орда","придорожня станція","фералас","табір е'ток"},ang={["faction:Horde"]="Застава Білого Рубежу — важливе місце відпочинку й розвідувальна точка для мандрівників Орди, що йдуть небезпечними каньйонами Тисячі Голок.",["race:Tauren"]="Тауренські розвідники допомагають оберігати цей придорожній табір, щоб одноплемінники, які мандрують між Малгором, Фераласом і Мерехтливими Низинами, мали де безпечно відпочити."},sec={{t="Придорожня станція в каньйонах",b="Застава Білого Рубежу, що примостилася при второваній дорозі глибинами Тисячі Голок, — одна з кількох скромних опор Орди, відвойованих у суворої місцевості. Розташована поблизу Табору Е'ток, застава допомагає Орді надійно триматися на дні каньйону й стежити за рухом між обвітреними столовими горами. Вона не така укріплена, як великий підйомник чи головні племінні поселення, проте для гінців, розвідників і шукачів пригод, що перетинають спірні пустища, без неї не обійтися."}},faq={{q="Що таке Застава Білого Рубежу?",a="Застава Білого Рубежу — невелика застава Орди на головній стежці каньйону в Тисячі Голок, неподалік від Табору Е'ток.",al={"білий рубіж","табір білого рубежу","де застава білого рубежу"}},{q="Яка фракція контролює Заставу Білого Рубежу?",a="Її контролює Орда; утримують заставу переважно таурени-розвідники, що наглядають за стежками ущелини.",al={"чи білий рубіж орди","фракція білого рубежу"}},{q="Хто тут несе службу?",a="На заставі служать місцеві розвідники й мандрівники Орди, зокрема таурен Канаті Ґрейклауд, що стежить за проходом каньйоном.",al={"нпс білого рубежу","хто живе на заставі білого рубежу"}}},fp="15,351,27.506.0,24.134.0,39.105.0,32.131.0"}
P.entries["subzone:wild-shore"] = {n="Дикий Берег",s="Дикий Берег — найпівденніше узбережжя Долини Стренглторну, де джунглі сходяться з хвилями Південних Морів. Тут збираються й стоять на якорі Буканіри Кривавого Вітрила, чиї кораблі пришвартовані на мілинах.",h="Дикий Берег — найпівденніше узбережжя Долини Стренглторну, де джунглі сходяться з хвилями Південних Морів.",kw={"дикий берег","криваве вітрило","пірати","ґорлаш","південні моря","долина стренглторну"},ang={["class:Rogue"]="Табори Кривавого Вітрила й кораблі на якорі — чудова нагода спорожнити кілька чужих кишень і придивитися до суперників-зірвиголів, що діють поза законом картелю Стімвідл."},sec={{t="Край Південних Морів",b="Дикий Берег тягнеться вздовж самого південного краю материка — там, де Долина Стренглторну обривається в Південні Моря. На північному заході лежить укріплена бухта Буті Бей, а на сході мілка протока відділяє материковий пляж від Острова Ягуеро. Далі берег простягається на північний схід, до Кришталевого Берега. Це глухе місце лежить поза досяжністю гармат Нападників Чорної Води, тож узбережжя стало розсадником піратства й диких небезпек."},{t="Пірати й велетні",b="Берег міцно тримають Буканіри Кривавого Вітрила: вони ставлять свої дерев'яні кораблі на якір у прибої й розбивають табори просто на піску. Ці зірвиголови використовують пляжі як базу для своїх операцій, переховують тут контрабанду й готують напади на суперників-гоблінів. Мандрівникам доводиться остерігатися й природних небезпек узбережжя — хижих звірів і Ґорлаша, колосального морського велетня, що бреде прибоєм і розчавлює кожного, хто забариться біля лінії припливу."}},faq={{q="Де розташований Дикий Берег?",a="Дикий Берег — найпівденніше узбережжя Долини Стренглторну у Східних Королівствах. Він лежить на південь від Буті Бей, і звідти видно Південні Моря аж до Острова Ягуеро.",al={"розташування дикого берега","де дикий берег","дикий берег на мапі"}},{q="Хто контролює Дикий Берег?",a="Узбережжям володіють Буканіри Кривавого Вітрила. Вони тримають кілька своїх кораблів на мілководді й мають табори на піщаних пляжах.",al={"хто живе на диких берегах","фракції дикого берега","пірати дикого берега"}},{q="Хто такий Ґорлаш?",a="Ґорлаш — величезний морський велетень, що бродить мілинами вздовж Дикого Берега й загрожує і необережним морякам, і піратам на пляжі.",al={"ґорлаш велетень","хто велетень на пляжі","ґорлаш дикий берег"}},{q="Як Дикий Берег пов'язаний з Буті Бей?",a="Буті Бей від Дикого Берега відділяє скелястий мис. Буті Бей — твердиня Нападників Чорної Води й картелю Стімвідл, тож сусідній Дикий Берег став природним плацдармом для їхніх заклятих ворогів — Буканірів Кривавого Вітрила.",al={"зв'язок із бутті бей","дикий берег бутті бей"}}},fp="10,236,22.488.0,18.462.0,32.178.0,28.153.0,15.141.0,44.249.0"}
P.entries["subzone:wildbend-river"] = {n="Річка Дикого Закруту",s="Річка Дикого Закруту — отруєний потік, що петляє південними лісами Темного Узбережжя поблизу Гаю Прадавніх. Стікаючи просто з осквернених висот Сквернолісся, її води несуть демонічну отруту до моря, загрожуючи довколишній дикій природі.",h="Річка Дикого Закруту — отруєний потік, що петляє південними лісами Темного Узбережжя поблизу Гаю Прадавніх.",kw={"річка дикого закруту","річка кривавої отрути","сквернолісся","гай прадавніх","темне узбережжя"},ang={["class:Druid"]="Друїди, що вивчають наслідки Третьої війни для природи, насторожено стежать за річкою, з'ясовуючи, як глибоко скверна Сквернолісся проникає в рослини й тварин нижче за течією.",["race:NightElf"]="Забруднені води, що стікають зі Сквернолісся, загрожують прадавньому корінню Темного Узбережжя, тож береги річки — постійний клопіт для стражів нічних ельфів."},sec={{t="Отруйний гірський потік",b="Річка Дикого Закруту прорізає південь Темного Узбережжя й тече на захід повз священний Гай Прадавніх, а потім впадає в море. Замість живити ліс чистою водою, вона несе скверну з гір. Річка — пряме продовження Річки Кривавої Отрути зі Сквернолісся: вона мчить скелястими кряжами, несучи мерзенні отруєні стоки в природу Темного Узбережжя. Нічні ельфи пильно стежать за її берегами, виглядаючи спотворених звірів і повзуче поширення демонічної пошесті."}},faq={{q="Чому Річка Дикого Закруту осквернена?",a="Річка бере початок високо в горах Сквернолісся, де її звуть Річкою Кривавої Отрути. Під час Третьої війни Сквернолісся наскрізь просякло демонічною магією, і ці мерзенні стоки спадають скелями на Темне Узбережжя вже як Річка Дикого Закруту.",al={"чому вода осквернена","отрута річки дикого закруту","брудна вода темного берега"}},{q="Куди тече річка?",a="Спадаючи зі східних хребтів, що відділяють Сквернолісся від Темного Узбережжя, річка в'ється південною частиною Темного Узбережжя повз Гай Прадавніх і впадає у Приховане Море.",al={"де річка дикого закруту","шлях річки дикого закруту","розташування річки"}},{q="Чи шкодить річка Гаю Прадавніх?",a="Річка тече поблизу Гаю Прадавніх і постійно загрожує древнім захисникам, що вкоренилися там. Нічні ельфи невтомно стримують пошесть, щоб отруєна вода не згноїла священні гаї.",al={"вода гаю прадавніх","чи гай прадавніх зіпсований"}}},fp="14,267,23.531.0,36.253.0,26.186.0,48.248.0"}
P.entries["subzone:wildmane-water-well"] = {n="Водяна Криниця Вайлдмейнів",s="Водяна Криниця Вайлдмейнів — найпівнічніша зі священних криниць, розкиданих по Малгору; вона лежить одразу на північ від плато Тандер Блафа. Життєво важлива для рівнин і їхніх стад, вона стала гарячою точкою, на яку націлилися гоблінські пройдисвіти, прагнучи перекрити тауренам джерело життя.",h="Водяна Криниця Вайлдмейнів — найпівнічніша зі священних криниць, розкиданих по Малгору; вона лежить одразу на...",kw={"водяна криниця вайлдмейнів","криниця","отрута","венчурна компанія","тандер блаф","малгор","очищення"},ang={["class:Druid"]="Спроби гоблінів отруїти прісну воду Малгору загрожують крихкій рівновазі рівнин і вимагають друїдської пильності, щоб очистити й зцілити землю.",["race:Tauren"]="Священні криниці Малгору — дар Земної Матері. Захистити Криницю Вайлдмейнів від осквернення й отрути — священний обов'язок кожного молодого сміливця."},sec={{t="Джерело життя в облозі",b="Поколіннями кочові таурени покладалися на священні криниці, викопані по золотавих рівнинах Малгору, щоб напувати свій народ і мандрівні стада кодо. Криниця Вайлдмейнів стереже північні простори одразу за тінню Тандер Блафа. Її надзвичайна важливість робить її принадною ціллю для ворогів племен. Гобліни Венчурної Компанії споганили її своїми отрутами, аби прибрати до рук водопостачання всього краю, і лише обряд очищення з тотемом, виготовленим тауренами, зможе знову зробити її води чистими."}},faq={{q="Де розташована Водяна Криниця Вайлдмейнів?",a="Водяна Криниця Вайлдмейнів стоїть на рівнинах Малгору, просто на північ від височенних столових гір Тандер Блафа. Це найпівнічніша зі священних криниць, що живлять край.",al={"розташування криниці вайлдмейнів","де криниця вайлдмейнів","криниця вайлдмейнів на мапі"}},{q="Чому криниця важлива для тауренів?",a="На рівнинах прісна вода — це життя. Таурени вважають криниці священними: вони поять їхні поселення, мандрівних мисливців і великі стада кодо, що кочують рівнинами Малгору.",al={"чому таврени дбають про криницю","криниця вайлдмейнів священна"}},{q="Хто намагався зіпсувати криницю чи захопити її?",a="Гобліни Венчурної Компанії отруїли криницю, щоб прибрати до рук воду Малгору, і тепер таурени мусять очистити її священним тотемом.",al={"хто напав на криницю","вороги криниці вайлдмейнів","хто отруїв криницю вайлдмейнів"}}},fp="19,292,23.543.0,41.184.0,40.191.0,46.157.0"}
P.entries["subzone:windbreak-canyon"] = {n="Каньйон Вітролому",s="Каньйон Вітролому — звивиста ущелина на півночі Тисячі Голок, між Заставою Вільного Вітру й Мерехтливими Низинами. Славиться він різкими протягами й гострим камінням, а ще — гніздами вітряних змій, якими він кишить. Мандрівникам на головній дорозі варто обережно ступати біля входу до каньйону, щоб на них не напали згори.",h="Каньйон Вітролому — звивиста ущелина на півночі Тисячі Голок, між Заставою Вільного Вітру й Мерехтливими...",kw={"каньйон вітролому","вітряні змії","тисяча голок","застава вільного вітру","вивітрений закуток","гнізда"},ang={["class:Hunter"]="Вітряні змії, що гніздяться по всьому каньйону, дають мисливцям чудову нагоду вивчити й приборкати спритних звірів, що плюються блискавками."},sec={{t="Зміїне гніздо серед Голок",b="Каньйон Вітролому, врізаний у стрімкі північні стіни, тягнеться чималим відтинком на схід від Застави Вільного Вітру. Ущелина не дає прихистку — навпаки, вона жене посвистливі вітри між скельними шпилями, створюючи ідеальні сідала для диких вітряних змій. Хижаки відкладають кладки на кам'яних виступах і нападають на необачних мандрівників, що відбилися від головної дороги. Ті, хто наважиться заглибитися в каньйон, знайдуть і звивисті стежки, що здіймаються вгору, до Вивітреного Закутка."}},faq={{q="Де розташований Каньйон Вітролому?",a="Каньйон Вітролому лежить на північному боці Тисячі Голок, приблизно між Заставою Вільного Вітру та східними підступами до Мерехтливих Низин.",al={"розташування каньйону вітролому","де каньйон вітролому","вітролом на мапі"}},{q="Які істоти живуть у Каньйоні Вітролому?",a="У каньйоні панують агресивні дикі вітряні змії, що гніздяться серед скель і захищають свої кладки від чужинців.",al={"монстри вітролому","що в каньйоні вітролому","моби вітролому"}},{q="Куди веде стежка в каньйоні?",a="Стежки, що піднімаються вглиб каньйону, ведуть мандрівників до Обвітреного Закутка, що ховається у скелях угорі.",al={"стежка вітролому","слід у каньйоні вітролому","куди веде вітролом"}}},fp="16,342,29.499.0,26.143.0,40.124.0,44.116.0"}
P.entries["subzone:windfury-ridge"] = {n="Хребет Люті Вітру",s="Хребет Вітрофурій — суворе високогір'я, що обступає пасовища Малгору. Сумнозвісний лютими гарпіями, а також хижими вовками й пумами, він становить постійну небезпеку для подорожніх, зате дарує тауренським майстрам цінне пір'я.",h="Хребет Вітрофурій — суворе високогір'я, що обступає пасовища Малгору.",kw={"хребет люті вітру","гарпії","вітрофурії","пір'я","вовки","пуми","малгор"},ang={["class:Hunter"]="Круті схили й хитрі хижаки — чудовий ранній полігон для вистежування, приборкання звірів і бою на відстані.",["race:Tauren"]="Хребет — водночас постійна морока для молодих мисливців і джерело важливих обрядових прикрас, якими вшановують шлюби та сезонні зібрання."},sec={{t="Небезпечне сідало",b="Хребет Вітрофурій різко здіймається над тихими рівнинами Малгору й править за мисливські угіддя гарпій Вітрофурій. Ці люті крилаті створіння гніздяться високо в кручах і охоче кидаються згори на необачних мандрівників, що обходять пагорби. Скелясту місцевість також населяють степові вовки й дикі гірські пуми, тож хребет — один із найпідступніших кордонів тауренського серця краю. Попри небезпеку, хоробрі тауренські воїни часто полюють на гарпій: їхнє яскраве, переливчасте пір'я дуже цінують по всьому Тандер Блафу, прикрашаючи ним обрядові шати для пишних бенкетів і весільних святкувань."}},faq={{q="Чим небезпечний Хребет Вітрофурій?",a="Хребет кишить хижими пумами й степовими вовками, але найдокучливіша загроза — зграя агресивних гарпій, що гніздяться на висотах. Вони пікірують зі скель, щоб схопити чи розтерзати тих, хто підходить надто близько до їхніх гнізд.",al={"чому хребет вітрофурій небезпечний","небезпеки хребта вітрофурій","монстри хребта вітрофурій"}},{q="Чому таурени полюють на гарпій на Хребті Вітрофурій?",a="Окрім того, що таурени захищають свої кордони від гарпій, вони полюють на гарпій Вітрофурій заради яскравого пір'я. Це барвисте пір'я здавна збирають і вплітають в обрядові головні убори й прикраси для свят і весіль.",al={"чому вбивати гарпій вітрофурій","пір'я гарпій мулґор","полювання на гарпій"}},{q="Де розташований Хребет Вітрофурій?",a="Хребет Вітрофурій тягнеться високими кручами пасторального Малгору, на крайній півночі краю, за Тандер Блафом.",al={"розташування хребта вітрофурій","де хребет вітрофурій","хребет вітрофурій на мапі"}}},fp="14,245,16.644.0,36.267.0,53.250.0,32.131.0"}
P.entries["subzone:windshear-crag"] = {n="Круча Вітрорізу",s="Круча Вітрорізу — вщент сплюндрована долина в центрі Гір Кам'яного Кігтя, яку Венчурна Компанія позбавила прадавнього лісу. Колись тут шумів пишний ліс, а тепер це промислова пустка, де гудуть подрібнювачі, течуть каламутні стоки й лютують бригади лісорубів. У тіні машин місцеві кобольди риють руду, а гірські перевали з'єднують цей пошрамований край з Ашенвалем.",h="Круча Вітрорізу — вщент сплюндрована долина в центрі Гір Кам'яного Кігтя, яку Венчурна Компанія позбавила...",kw={"круча вітрорізу","венчурна компанія","ґерензо ренчвісл","суперкосар","кобольди","брауґ дімспіріт"},ang={["faction:Horde"]="Мандрівники Орди, що прямують до Ашенвалю, зустрічають біля Стежки Глибокого Кігтя Брауґа Дімспіріта, який перевіряє, як добре вони знають історію Калімдору.",["profession:Engineering"]="Промислове обладнання по всій кручі відкриває безжальні гоблінські торгові таємниці та смертоносні креслення Суперкосаря, які створив Ґерензо Ренчвісл."},sec={{t="Промислова розруха",b="Ще недавно Круча Вітрорізу була густим пралісом на схилах Кам'яного Кігтя. Та спокійна дика місцина зникла, щойно сюди по наживу прийшла Венчурна Компанія. Тепер улоговина повна зрізаних пнів, їдкого смогу й брязкоту машин. Усім лісозаготівельним підприємством керує Ґерензо Ренчвісл — прокажений гном, чий інженерний геній створив Суперкосар 6000: механічне страхіття, здатне за мить перетворити величезні стовбури на тріски. З високого помосту над отруєним Озером Скельної Заводі Ґерензо керує цією неприборканою роботою, що оголює гору дочиста, і наживає собі ворогів і серед інженерів-суперників, і серед місцевих мешканців."},{t="Копальні й гірські перевали",b="Окрім робочих лісосік, Круча Вітрорізу таїть інші небезпеки й роздоріжжя. На південному сході лежить Шахта Зрізаного Вітру, де войовничі кобольди довбають скелю, видобуваючи злитки димного заліза, і люто кидаються на кожного, хто наблизиться до їхньої здобичі. У північно-східних околицях кручі мандрівники знайдуть Стежку Глибокого Кігтя — підземний тунель, що веде просто під хребтами в Ашенваль. Біля цього затіненого проходу стоїть тауренський старійшина Брауґ Дімспіріт, який перевіряє знання історії та рішучість мандрівників Орди, що рушають крізь спірні вершини."}},faq={{q="Хто керує тут лісозаготівлею?",a="Лісозаготівлею на місці командує Ґерензо Ренчвісл, геніальний, але заражений інженер із гномів-прокажених. Він працює за контрактом із Венчурною Компанією й наглядає за кручею з дерев'яного помосту, зведеного просто над Озером Скельної Заводі.",al={"хто керує лісозаготівлею","хто бос вітрорізу","лор ґерензо рентжсвіста"}},{q="Що таке Супержнець 6000?",a="Супержнець 6000 — передовий механічний прототип для лісозаготівлі, який сконструював Ґерензо Ренчвісл. Створений, щоб валити ліс із небаченою швидкістю, він за лічені миті перемелює прадавні гірські дерева на тирсу, пришвидшуючи суцільну вирубку.",al={"супержнець 6000","що за великий подрібнювач","жнивар венчур ко"}},{q="Чому Спілка Винахідників з Андермайну полює на Ґерензо?",a="Директор Спілки Винахідників в Андермайні Ріддлвокс хоче смерті Ґерензо, і наказ передає гоблін Зіз Фіззікс, який уже допоміг викрасти креслення Супержнеця 6000. Торгові князі Андермайну не схвалюють того, що Венчурна Компанія водиться з гномом.",al={"чому спілка винахідників полює на ґерензо","мотиви зіза фізікса","помста спілки винахідників"}},{q="Куди веде печера на північному сході?",a="Печера в північно-східному куті — це Стежка Глибокого Пазура. Вона пролягає крізь підземне коріння гір і дає змогу пішки пройти між Кручею Вітрорізу й густими лісами Ашенвалю.",al={"куди веде стежка глибокого кігтя","вихід із печери вітрорізу","тунель у кручі вітрорізу"}},{q="Що за кобольди копають на південному сході?",a="Кобольди Вітрорізу захопили місцеву шахту в південно-східному куті кручі. Вони завзято обороняють свою підземну ділянку й видобувають поклади, з яких виходять злитки димчастого заліза для місцевих ковалів.",al={"кобольди вітрорізу","чому тут кобольди","димчасті залізні зливки"}}},fp="14,403,22.687.0,25.571.0,42.252.0,30.259.0,54.272.0,42.194.0,45.204.0"}
P.entries["subzone:winterfall-village"] = {n="Село Зимопадів",s="Село Зимопадів — розлогий табір фурболгів серед снігових заметів на сході Вінтерспрінгу, одразу на схід від Евірлука. Колись фурболги Зимопадів жили в мирі, як і їхні родичі з інших ведмежих племен Калімдору, але під владою Верховного Вождя Зимопаду вони поринули в безумство й люту скверну.",h="Село Зимопадів — розлогий табір фурболгів серед снігових заметів на сході Вінтерспрінгу, одразу на схід від...",kw={"село зимопадів","фурболги","зимопади","верховний вождь зимопаду","вінтерспрінг","евірлук","скверна"},ang={["class:Druid"]="Глибока скверна, що вразила плем'я Зимопадів, — гірка трагедія, адже фурболги були давніми союзниками нічних ельфів і Кола Кенарія, доки їх не охопило демонічне безумство.",["race:NightElf"]="Занепад племені Зимопадів — ще один болісний розлам у давніх узах між нічними ельфами й корінними народами Калімдору."},sec={{t="Поглинуте плем'я",b="Село Зимопадів розкинулося на сніжних терасах на схід від гоблінського торговельного містечка Евірлук і є головним оплотом фурболгів Зимопадів у Вінтерспрінгу. Як і їхніх родичів, розсіяних північним Калімдором, цей ведмежий народ спотворила й звела з розуму скверна, що лишилася після вторгнення Палаючого Легіону. Плем'я, яким із відлюдної печери на найвищій терасі селища править Верховний Вождь Зимопаду, зреклося звичаїв предків. Замість того щоб мирно спілкуватися з дикими духами снігів, розлючені фурболги тепер нападають на мандрівників, патрулюють гірські перевали й погрожують кожному, хто наблизиться до їхньої скутої морозом домівки."}},faq={{q="Що таке Село Зимопадів?",a="Це головне поселення фурболгів-Зимопадів на засніжених схилах трохи на схід від гоблінської застави Евірлук у Вінтерспрінгу.",al={"інформація про село зимопадів","що це за місце","фурболжине місто вінтерспрінг"}},{q="Чому тутешні фурболги ворожі?",a="Фурболги-Зимопади піддалися спотворенню після Третьої війни. Демонічна скверна, яку лишив по собі Палаючий Легіон, викривила їхній розум, позбавила мирних звичаїв і зробила їх люто ворожими до всіх чужинців.",al={"чому фурболги злі","зіпсовані фурболги","чому нападають"}},{q="Хто очолює село?",a="Плем'ям править Верховний Вождь Зимопаду, що наглядає за своїми підданими з невеликої печери на самій вершині поселення.",al={"хто бос","лідер зимопадів","вождь"}},{q="Чому Евірлук турбується через це село?",a="Село лежить загрозливо близько до Евірлука. Збожеволілі фурболги постійно нападають на каравани, порушують місцеві торгові шляхи й загрожують гоблінським копальням і торгівлі по всьому східному Вінтерспрінгу.",al={"гобліни евірлука","чому евірлук воює з зимопадами"}}},fp="18,312,16.671.0,27.142.0,34.235.0,22.141.0,42.222.0"}
P.entries["subzone:winterhoof-water-well"] = {n="Водяна Криниця Вінтергуфів",s="Водяна Криниця Вінтергуфів — життєво важливе джерело прісної води на краю Хвилястих Рівнин у південному Малгорі. Вкрай потрібна місцевій живності й кочовим тауренським племенам, криниця нещодавно опинилася під загрозою з боку хижої Венчурної Компанії, що прагне отруїти й прибрати до рук водопостачання краю.",h="Водяна Криниця Вінтергуфів — життєво важливе джерело прісної води на краю Хвилястих Рівнин у південному...",kw={"водяна криниця вінтергуфів","криниця","хвилясті рівнини","венчурна компанія","малл тандергорн","очищення","малгор"},ang={["class:Shaman"]="Очищення криниці вимагає гармонії стихій і стає наочним уроком того, як тотемами зцілювати поранених духів води.",["race:Tauren"]="Оборона й очищення прабатьківських криниць — одне з перших випробувань молодих сміливців, що бережуть землю від чужинського визиску."},sec={{t="Життєва артерія під загрозою",b="У посушливих просторах центрального Калімдору вода — це життя, і підземні криниці Малгору живлять і стада рівнин, і стійбища тауренів. Водяна Криниця Вінтергуфів, названа на честь одного з шанованих племен рівнин, сягає глибоких водоносних шарів під Хвилястими Рівнинами. На жаль, її стратегічна вага розпалила жадобу Венчурної Компанії. Замість ділити землю чи домовлятися безжальний гоблінський картель спробував отруїти воду, щоб здобути важіль тиску на довколишні землі."},{t="Очищення й оборона",b="Щоб протистояти промисловій диверсії Венчурної Компанії, тауренські старійшини й шамани підняли молодих сміливців по всьому Малгору. Малл Тандергорн виготовив священні тотеми, здатні нейтралізувати промислові отрути й відновити духовну та тілесну рівновагу криниці. Очищення криниці для тауренів — не просто боротьба за виживання, а духовний обов'язок: земля та її води мають лишатися неспаплюженими чужинською жадобою."}},faq={{q="Де розташована Водяна Криниця Вінтергуфів?",a="Криниця стоїть на півдні Малгору, на самому краю Хвилястих Рівнин, на південь від Села Бладгуф.",al={"розташування криниці вінтергуфів","де криниця вінтергуфів","знайти криницю вінтергуфів"}},{q="Хто отруїв Водяну Криницю Вінтергуфів?",a="Криницю отруїла Венчурна Компанія. Безсовісна гоблінська торгова організація намагалася зіпсувати воду, щоб прибрати до рук місцеві багатства й послабити корінних тауренів.",al={"хто отруїв криницю вінтергуфів","чому криниця отруєна","хто зіпсував воду"}},{q="Як очистити отруєну криницю?",a="Криницю очищають ритуалом із зачарованим тотемом, який виготовив Малл Тандергорн: його первісна магія виганяє з води мерзенну отруту Венчурної Компанії.",al={"очистити криницю вінтергуфів","полагодити криницю","очищення вінтергуфів"}},{q="Чому криниці такі священні для тауренів?",a="Вони не лише напувають племена й кочові стада: джерела води в Малгорі вважають дарами Земної Матері. Отруїти їх — це водночас пряма загроза життю і тяжка духовна наруга.",al={"чому таврени дбають про криниці","лор криниць тавренів"}}},fp="21,315,21.547.0,24.439.1,43.111.0,39.188.0,38.178.0,44.226.0"}
P.entries["subzone:witch-hill"] = {n="Відьмин Пагорб",s="Відьмин Пагорб — похмуре, оповите туманом узвишшя в серці Багна Пилоброду, на шляху до Терамору. Найбільше воно відоме відлюдним Маєтком Болотних Вогників, розкиданими таборами ворожих мурлоків-Багноплавців і зловісними чутками про темних привидів.",h="Відьмин Пагорб — похмуре, оповите туманом узвишшя в серці Багна Пилоброду, на шляху до Терамору.",kw={"відьмин пагорб","багно пилоброду","маєток болотних вогників","мурлоки","багноплавці","привиди","джарл"},ang={["class:Warlock"]="Чорнокнижники, що йдуть дорогою до Терамору, можуть відчути: темні чутки про привидів, які огортають цей похмурий пагорб, з'явилися недарма.",["faction:Alliance"]="Відьмин Пагорб межує з головним суходільним шляхом до Острова Терамор, тож його племена мурлоків і темні сутності — постійна морока для мандрівників і гінців."},sec={{t="Сплюндроване узвишшя",b="Відьмин Пагорб, що здіймається над застояними водами Багна Пилоброду, лежить приблизно на третині шляху вздовж півострова, який веде на південний схід до Острова Терамор. Узвишшя майже не дає захисту від болотяних небезпек: навколишні води захопили агресивні мурлоки-Багноплавці. У його центрі стоїть Маєток Болотних Вогників — самотня й моторошна оселя відлюдника, відомого як Джарл «Болотне Око». Мандрівники, що проходять цим пагорбом, часто розповідають про дивні явища й темні присутності, які тут не зникають."},{t="Привиди пагорба",b="За тихою, похмурою зовнішністю Відьмин Пагорб сповнений темних чуток. До безлюдної землі липнуть оповідки про привидів, підживлюючи місцеву параною. Ті, хто наважиться піднятися на пагорб, мусять протистояти не лише первісній дикості Багноплавців, а й окультним загрозам, від яких ніяково стає навіть досвідченим патрулям Терамору."}},faq={{q="Де розташований Відьмин Пагорб?",a="Відьмин Пагорб лежить у Багні Пилоброду, приблизно на третині шляху вздовж півострова, що з'єднує західні болота з Островом Терамор.",al={"розташування відьминого пагорба","де відьмин пагорб","як знайти відьмин пагорб"}},{q="Хто живе на Відьминому Пагорбі?",a="Найпомітніший мешканець — дивакуватий відлюдник Джарл «Болотне Око», що живе в Маєтку Болотних Вогників посеред пагорба. А низини довкола заполонили табори мурлоків-Багноплавців.",al={"хто тут живе","мешканці відьминого пагорба","мешканець маєтку болотних вогників"}},{q="Чому це місце звуть Відьминим Пагорбом?",a="Цей пагорб здавна має лиху славу через темну магію, дивні вогні й надприродні небезпеки, а моторошна самотність Маєтку Болотних Вогників лише її посилює.",al={"чому відьмин пагорб","чи є тут відьма","лор відьминого пагорба"}},{q="Яких загроз мандрівникам слід стерегтися на Відьминому Пагорбі?",a="Мандрівникам слід остерігатися мурлоків-Багноплавців, що ставлять табори довкола пагорба, а також тривожних чуток про привидів, які ходять про це місце.",al={"небезпеки відьминого пагорба","вороги відьминого пагорба","моби відьминого пагорба"}}},fp="10,243,15.515.0,24.315.1,28.146.0,24.195.0,34.151.1,57.154.0"}
P.entries["subzone:witherbark-village"] = {n="Село Сухокорів",s="Село Сухокорів — поселення лісових тролів довкола відлюдного озера в південно-східних пагорбах Аратійського нагір'я. Тут живе вороже плем'я Сухокорів, і звідси тролячі загони вирушають у набіги і на рештки Альянсу в Стромґарді, і на заставу Орди в Гаммерфоллі.",h="Село Сухокорів — поселення лісових тролів довкола відлюдного озера в південно-східних пагорбах Аратійського...",kw={"село сухокорів","сухокори","лісові тролі","залас візербарк","каменекулаки","аратійське нагір'я"},ang={["faction:Horde"]="Сухокори не виявляють новій Орді жодної шани: вони раз у раз б'ються з розвідниками з Гаммерфолла й загрожують подорожнім на східних перевалах.",["race:Troll"]="Тролі Темного Списа не знайдуть тут рідні: лісові тролі Сухокорів дивляться на тролів джунглів і на Орду з глибоко вкоріненою ворожістю."},sec={{t="Твердиня лісових тролів",b="Село Сухокорів, що стоїть на березі тихого гірського озера, — дім лютих лісових тролів із племені Сухокорів. Поки рибалки, метальники сокир і знахарі живуть у хатинах уздовж берега, племінні ватажки на кшталт Заласа Візербарка та смертоносні тіньові мисливці керують справами з величезної печери за селом. Сухокори уклали вигідний для себе союз з аратійськими ограми Каменекулаків і разом із ними відвойовують землі по всьому нагір'ю — вони навіть міцно закріпилися серед руїн Фортеці Стромгард. Ревниві до своїх земель, вони кидаються на кожного чужинця, що забреде в їхній куток долини."}},faq={{q="Хто живе в Селі Сухокорів?",a="Селом володіє плем'я Сухокорів — місцеві лісові тролі. У них є мисливці за головами, метальники сокир, рибалки й знахарі, що обороняють озеро й довколишні стежки.",al={"хто такі сухокори","тролі сухокори","хто контролює село сухокорів"}},{q="Що у великій печері за селом?",a="Печера — осідок племінної влади. Звідти, з глибини тунелів, Вождь Залас Візербарк і небезпечні мисливці тіней керують набігами й обороною племені.",al={"печера сухокорів","печера за селом сухокорів","залас сухокор"}},{q="Чому тролі-Сухокорі співпрацюють з ограми?",a="Сухокорі уклали нетривкий союз із розрахунку з місцевими ограми-Каменекулаками. Об'єднавши сили, вони можуть тиснути на ослаблених людських захисників Стромґарда й загрожувати місцевим суперникам, як-от Орді в Гаммерфоллі.",al={"союз сухокорів з ограми","тролі й кулакоскелі","чому тролі в союзі з ограми"}},{q="Чи дружні Сухокорі до Орди?",a="Ні. Як і більшість лісових тролів, що походять від Амані, Сухокорі плекають гірку ненависть до сучасної Орди та її тролів Темного Списа й воюють з Ордою в Гаммерфоллі. На мандрівників Орди вони нападають, щойно побачать.",al={"чи сухокори орди","чи може орда говорити з сухокорами","репутація сухокорів"}}},fp="18,309,31.664.0,32.208.0,49.179.0,49.248.0,41.217.0"}
P.entries["subzone:woodpaw-den"] = {n="Лігво Лісолапів",s="Лігво Лісолапів — сувора твердиня гнолів на півночі Фераласу, трохи на північ від прадавніх Руїн Даркмісту. Поселення — головне місце збору гнолів Лісолапів та їхніх найлютіших ватажків зграї, тож це небезпечний закуток дикої природи під густим лісовим наметом.",h="Лігво Лісолапів — сувора твердиня гнолів на півночі Фераласу, трохи на північ від прадавніх Руїн Даркмісту.",kw={"лігво лісолапів","гноли","вудпов","фералас","руїни даркмісту","зграя"},ang={["race:NightElf"]="Для калдореїв із Твердині Перистого Місяця дике розростання гнолівських зграй біля прадавніх святинь предків, як-от Руїни Даркмісту, — вічний клопіт, який треба пильно стримувати.",["race:Tauren"]="Мисливці з Табору Моджаче вважають лютий клан Лісолапів небезпечним суперником у змаганні за дичину й землі серед прадавніх лісів Фераласу."},sec={{t="Серце зграї",b="Лігво Лісолапів, що стоїть серед височенного гілля Фераласу, — укріплене осердя місцевих гнолів Лісолапів. На відміну від менших розвідницьких таборів, розкиданих уздовж стежок у джунглях, цей табір пильно охороняють досвідчені ватажки зграї. Тутешні гноли люто боронять свою територію і від непроханих шукачів пригод, і від дикої природи, що підступає дедалі ближче. Лігво лежить трохи на північ від ельфійських решток у Руїнах Даркмісту і становить для мандрівників, що намагаються перетнути серце краю, постійну хижу загрозу."}},faq={{q="Що таке Лігво Лісолапів?",a="Лігво Лісолапів — помітне поселення й табір гнолів-Лісолапів на півночі Фераласу, трохи на північ від Руїн Темного Туману. Тут живе багато небезпечних альф зграї.",al={"лігво лісолапів фералас","гнолячий табір фералас","де лігво лісолапів"}},{q="Які істоти тут живуть?",a="У лігві живуть переважно гноли з клану Лісолапів, передусім грізні альфи Лісолапів, що ведуть зграю й захищають її від чужинців.",al={"хто тут живе","моби лігва лісолапів","вороги лігва лісолапів"}},{q="Які орієнтири є поблизу?",a="Просто на південь лежать стародавні нічноельфійські руїни, відомі як Руїни Темного Туману. Сам табір оточують густі вологі ліси, типові для центрального Фераласу.",al={"орієнтири біля лігва лісолапів","що поруч із лігвом лісолапів"}}},fp="11,283,17.551.0,20.194.0,25.150.0,26.177.0"}
P.entries["subzone:woodpaw-hills"] = {n="Пагорби Лісолапів",s="Пагорби Лісолапів — суворий лісистий край на південному сході Фераласу, який захопили гноли Лісолапів. Колись тут безроздільно панувало плем'я, а тепер пагорби стали гарячою лінією фронту: знизу прогризаються комахоподібні жахіття, а лісовим наметом ступають прадавні кам'яні велетні.",h="Пагорби Лісолапів — суворий лісистий край на південному сході Фераласу, який захопили гноли Лісолапів.",kw={"пагорби лісолапів","гноли","вудпов","силітиди","гірські велетні","фералас"},ang={["faction:Horde"]="На відміну від нейтральних скельних велетнів біля західного узбережжя, гірські велетні, що патрулюють Пагорби Лісолапів, люто ненавидять усіх із Орди, хто заходить углиб краю."},sec={{t="Обложена твердиня",b="Густі ліси Пагорбів Лісолапів — споконвічна територія клану гнолів Лісолапів. Колись гієноподібні гноли бродили цими схилами, не знаючи суперників, але їхнє панування розсипалося під натиском з різних боків. На південному сході жахливі рої силітидів прорвалися з-під землі у Звивистій Глибині, відтіснили гнолів і змусили їхніх ватажків відступити глибше, до Лігва Лісолапів. Наче цього мало, лісами на схилах тепер бродять прадавні гірські велетні — пережиток Третьої війни, коли їх покликали з гір відбивати Палаючий Легіон, — і розчавлюють кожного мандрівника чи зайду з Орди, що трапиться їм на шляху."}},faq={{q="Хто живе на Пагорбах Лісолапів?",a="Пагорби займає переважно клан гнолів-Лісолапів, що тримає укріплені табори по всьому лісі. Схилами також ходять прадавні гірські велетні, а з південно-східних околиць насуваються комахи-силітиди.",al={"хто живе на пагорбах лісолапів","вороги пагорбів лісолапів","гноли фералас"}},{q="Чому цим лісом ходять гірські велетні?",a="Гірські велетні колись спустилися з вершин, щоб допомогти нічним ельфам під час Третьої війни, коли Палаючий Легіон вторгся в Калімдор. Демонічне вторгнення відбито, але ці кремезні вартові лишилися в лісах і люто стережуть дикі землі від чужинців.",al={"велетні пагорбів лісолапів","чому тут велетні","гірські велетні фералас"}},{q="Що загрожує тутешнім гнолам?",a="Лісолапів витісняє раптова навала комах-силітидів, що вигризають вулики у Звивистій Глибині. Рої, що підступають, вигнали гнолів із кількох таборів, і найсильніші альфи мусили укріпитися в Лігві Лісолапів.",al={"з чим борються гноли","проблеми лісолапів","комахи нападають на гнолів фералас"}},{q="Де ватажки клану Лісолапів?",a="Через рої силітидів, що насуваються на пагорби, проводирі племені покинули відкриті табори. Альфи Лісолапів відступили в захищені підземні печери Лігва Лісолапів.",al={"де ватажки лісолапів","боси гнолів фералас","знайти вожака лісолапів"}}},fp="13,267,24.645.0,31.233.0,51.279.0,36.267.0,35.199.0"}
P.entries["subzone:workshop-entrance"] = {n="Вхід до Майстерні",s="Вхід до Майстерні, відомий як чорний хід до Гномреґана, — прохід одразу за Депо потяга. Він дає досвідченим шукачам пригод та інженерам інший шлях у глибини опроміненого міста, оминаючи головну браму й виходячи поблизу Інженерних Лабораторій.",h="Вхід до Майстерні, відомий як чорний хід до Гномреґана, — прохід одразу за Депо потяга.",kw={"вхід до майстерні","майстерня","гномреґан","чорний хід","інженерні лабораторії","депо потяга"},ang={["profession:Engineering"]="Цей коридор веде просто до Інженерних Лабораторій, тож він — спокусливий шлях проникнення для майстрів, що шукають новітніх креслень.",["race:Gnome"]="Кожні потаємні двері до Гномреґана — можливе місце прориву, щоб повернути втрачені майстерні й відібрати дослідні машини в сил Мехінженера Термаплаґа."},sec={{t="Чорний хід до міста",b="Розташований по той бік величезної печерної зали Майстерні, одразу за Депо потяга, Вхід до Майстерні дає прямий шлях до промислового серця Гномреґана. З одного боку від нього відкривається прохід до Вантажної Кімнати, а сам цей хід веде просто до Інженерних Лабораторій, оминаючи укріплені вхідні брами, за які біля поверхні змагаються прокажені гноми й троги. Для ударних загонів, що намагаються відвоювати підземну столицю, можливість обійти перший периметр крізь ці бічні двері може виявитися вирішальною."}},faq={{q="Де розташований Вхід до Майстерні?",a="Вхід до Майстерні міститься в дальньому кінці цеху, за Депо потяга в зовнішніх коридорах Гномреґана. Звідси прохід до Вантажної Кімнати буде ліворуч від вас.",al={"розташування входу до майстерні","де чорний хід","чорний хід гномреґана"}},{q="Чому це місце називають чорним ходом?",a="Це запасний вхід у глибини Гномреґана: він дає змогу оминути головні передні зали й виводить непроханих гостей просто до Інженерних Лабораторій.",al={"чому чорний хід","чорний вхід гномреґана","задній вхід"}},{q="Куди веде цей прохід усередині міста?",a="Пройшовши крізь нього, ви спуститеся коридором просто в сектор Інженерних Лабораторій глибоко в Гномреґані.",al={"куди веде прохід","шлях через чорний хід","що за входом"}}},fp="17,299,24.500.0,39.193.0,37.176.0,45.115.0"}
P.entries["subzone:writhing-deep"] = {n="Звивиста Глибина",s="Звивиста Глибина — величезний комплекс комашиного вулика, прогризений у південно-східному Фераласі. Тут живуть силітиди Зукк'аш, і їхня підземна нора стає дедалі більшою загрозою і для місцевої дичини, і для навколишніх таборів. Невпинне розростання цих підземних хижаків порушило рівновагу пишного лісу.",h="Звивиста Глибина — величезний комплекс комашиного вулика, прогризений у південно-східному Фераласі.",kw={"звивиста глибина","силітиди","зукк'аш","вулик","фералас","табір моджаче"},ang={["faction:Horde"]="Силітиди, що розходяться зі Звивистої Глибини, прямо загрожують Табору Моджаче: вони женуть оскаженілих гнолів і комашиних розвідників просто на ваші шляхи постачання."},sec={{t="Рій Зукк'аш",b="Захована у вологих низинах південно-східного Фераласу, Звивиста Глибина — головна колонія силітидів Зукк'аш. На відміну від звичайних лісових звірів долини, ці цокотливі комахи риють лабіринти тунелів і люто стережуть кладки смолистих яєць. Вулик агресивно розростається на сусідні землі, і це розхитало життя дикої фауни та розлютило місцеві зграї гнолів: вигнані зі своїх місць, оскаженілі хижаки підступають неприємно близько і до стежок Орди, і до тутешніх святинь."}},faq={{q="Які істоти населяють Звивисту Глибину?",a="Провалля заполонили силітиди Зукк'аш — агресивна порода велетенських комах: робітники, копачі, жалоносці й оси, яких очолюють небезпечні поборники виводку, як-от Жаложал і Кірот.",al={"моби звивистої глибини","що живе в звивистій глибині","силітиди фералас"}},{q="Чому Звивиста Глибина загрожує Табору Моджаче?",a="Рій Зукк'аш розростається й вдирається в довколишні мисливські угіддя гнолів. Перелякані гноли тікають на північ просто до Табору Моджаче, і для застави Орди це стає дедалі гострішою загрозою.",al={"табір моджаче звивиста глибина","чому нападати на орду","гноли фералас"}},{q="Де розташована Звивиста Глибина?",a="Звивиста Глибина лежить на південному сході Фераласу, на південь від головної дороги й на схід від височенних лісистих пагорбів.",al={"розташування звивистої глибини","де звивиста глибина","вулик фераласу"}}},fp="13,343,18.510.0,41.199.0,50.221.0,35.131.0"}
P.entries["subzone:writhing-haunt"] = {n="Гнітюче поле",s="Гнітюче поле — зачумлена ферма на схід від Руїн Андоргала в Західних Чумних Землях. Колись ця родюча земля годувала Лордерон, а тепер її захопила Погибель і перетворила на отруйне джерело чумних випарів.",h="Гнітюче поле — зачумлена ферма на схід від Руїн Андоргала в Західних Чумних Землях.",kw={"гнітюче поле","чумний казан","разарх","малґріс діпрівер","андоргал","західні чумні землі"},ang={["class:Druid"]="Чумні випари осквернили родючу орну землю, тож Гнітюче поле — пряма наруга над природним ладом, і казан мусить замовкнути.",["faction:Alliance"]="Бачити, як угіддя під Андоргалом під владою Погибелі обернулися на зачумлену пустку, — гірке нагадування про падіння Лордерону."},sec={{t="Поле хвороби",b="Як і багато старих людських хуторів довкола Андоргала, ферма, що тепер зветься Гнітючим полем, упала швидко, ще в Третю війну. Нині на цих полях не родить хліб — тут збирають гниль. Погибель поставила величезний чумний казан просто посеред зораної землі, і той безупинно випускає в повітря задушливі хворобливі випари. Порослими бур'яном борознами блукають гнилі й крижані гулі та смердючі зомбі, які під командою Володаря Казана Разарха стережуть цю машинерію."},{t="Спостерігач серед руїн",b="Попри всюдисущу загрозу Погибелі й задушливі міазми з казана, живі не зовсім покинули ферму. В одній із напівзруйнованих хат переховується Малґріс Діпрівер. Він шукає спосіб знешкодити заразу, що дедалі ширшає, і завдати удару чумній машинерії, тож пильно стежить за роботою казана й чекає на звитяжних мандрівників, готових кинути виклик Разархові й зірвати мерзенні задуми Погибелі."}},faq={{q="Чим було Гнітюче поле до чуми?",a="До Третьої війни Гнітюче поле було родючою людською фермою, що постачала зерно й худобу до Андоргала неподалік і всьому Королівству Лордерон.",al={"історія гнітючого поля","чим була ця ферма","стара ферма андорґала"}},{q="Чому посеред поля стоїть величезний казан?",a="Казан поставила Погибель, щоб варити чумні випари й розносити їх околицями, отруюючи ґрунт, воду й усе живе довкола.",al={"чумний казан гнітючого поля","чому тут казан","зелений дим ферми"}},{q="Хто контролює Гнітюче поле?",a="Місцем керує Володар Казана Разарх, неживий слуга Погибелі, що стереже чумний казан разом із юрбою гулів і зомбі.",al={"хто керує гнітючим полем","бос гнітючого поля","разарх"}},{q="Хто ховається у фермерському будинку?",a="У покинутому будинку переховується Малґріс Діпрівер: він стежить за казаном і налагоджує зусилля, щоб зруйнувати задуми Погибелі в цьому краї.",al={"нпс у домі","мулґріс діпріввер","хто такий мулґріс"}}},fp="14,246,18.499.0,22.450.0,46.181.0,57.182.0,32.151.0,31.162.0"}
P.entries["subzone:wyrmbog"] = {n="Вірмове Болото",s="Вірмове Болото — небезпечна південна частина Багна Пилоброду, одразу на південь від Драконячої Мряки. Тут панують смердюча трясовина й зубчасті кам'яні шпилі; це плацдарм і буферна територія чорних драконів. У навколишніх хребтах видовбано печери давніх вірмів — зокрема матері виводку Оніксії та старійшини Емберстрайфа.",h="Вірмове Болото — небезпечна південна частина Багна Пилоброду, одразу на південь від Драконячої Мряки.",kw={"вірмове болото","багно пилоброду","оніксія","емберстрайф","чорні дракони","лігво оніксії"},ang={["faction:Alliance"]="Для чемпіонів Альянсу, що полюють на чорних драконів, Вірмове Болото — останній підступний плацдарм перед порогом Оніксії.",["faction:Horde"]="Розвідники Вождя Тралла насторожено стежать за Вірмовим Болотом, знаючи, що чорні дракони, які гніздяться так близько до Пусток і Терамору, загрожують крихкій рівновазі в Калімдорі."},sec={{t="Серце виводку",b="Вірмове Болото — найщільніше заселена чорними драконами територія на півдні Калімдору. Там, де відкриті води Багна Пилоброду поступаються випаленій багнюці й велетенським кісткам, у смердючому повітрі патрулюють дракончики й дорослі дракони. Болото задихається від отруйних випарів і хижих звірів, яких присутність драконів довела до сказу. Мандрівники, яким стане дурості забрести сюди, опиняються просто в тіні Лігва Оніксії та просторого лігва Емберстрайфа."}},faq={{q="Що таке Вірмове Болото?",a="Вірмове Болото — підступний південний край Багна Пилоброду, на південь від Драконячої Мли. Тут аж кишить посланцями чорної драконячого роду.",al={"вірмове болото","що таке вірмове болото","де вірмове болото"}},{q="Які дракони живуть у Вірмовому Болоті?",a="Тут панує чорна драконячий рід. Болото патрулюють численні чорні драконороди, молоді дракони й дракончата, а старші вірми, як-от Емберстрайф, і праматір виводку Оніксія мають лігва вздовж його південного краю.",al={"хто живе у вірмовому болоті","дракони вірмового болота","які дракони тут"}},{q="Де розташоване Лігво Оніксії відносно Вірмового Болота?",a="Вхід до Лігва Оніксії ховається серед скелястих шпилів і печерних отворів уздовж південного краю Вірмового Болота.",al={"розташування лігва оніксії","де оніксія","вхід до оніксії"}},{q="Хто такий Емберстрайф?",a="Емберстрайф — прадавній чорний дракон, що живе в печері, видовбаній у скелях Вірмового Болота, і слугує могутнім вартовим у володіннях праматері виводку.",al={"емберстрайф","хто такий емберстрайф","лігво емберстрайфа"}}},fp="7,368,18.455.0,16.160.0,31.218.0,54.122.0,19.174.0"}
P.entries["subzone:xavian"] = {n="Ксавіан",s="Ксавіан — давній зруйнований храмовий комплекс нічних ельфів на північному сході Ашенвалю, який захопили сатири. Це головний осередок влади сатирів у лісі: руїни просякнуті демонічною скверною, а тут правлять темні обряди, спрямовані проти лісу.",h="Ксавіан — давній зруйнований храмовий комплекс нічних ельфів на північному сході Ашенвалю, який захопили...",kw={"ксавіан","сатири","принц рейз","гілка кенарія","ксавіус","ашенваль"},ang={["class:Druid"]="Сатири тут викрали Гілку Кенарія й отруюють землю обрядами скверни; друїдів кличуть повернути артефакт і зцілити духовні рани гаю.",["race:NightElf"]="Бачити, як спотворені нащадки Високородних оскверняють зали давнього храму, — гірка образа для кожного нічного ельфа, що вимагає швидкої відплати."},sec={{t="Престол тіні",b="Ксавіан, що сховався серед північно-східних пагорбів Ашенвалю, на захід від Лісової Пісні й на північ від Сатирнаару, — найголовніший оплот сатирів у краї. Колись це був священний ельфійський храм, але його кам'яні арки й тераси осквернили прислужники Палаючого Легіону. Ватажки сатирів, серед них Принц Рейз і Ґелтарис, керують своїми родичами з цих руїн. Вони правлять по всій території осквернювальні ритуали і навіть використовують викрадену олію Бойової Пісні, щоб іще дужче отруїти священний ліс. Місцевість названа на честь Ксавіуса — радника Високородних, що став першим сатиром під час Війни Прадавніх, після того як підвів Саргераса."},{t="Полеглий авангард",b="Скверні, що розходиться від Ксавіана, протистоять, але виклик сатирам має гірку ціну. Вартові й лісові охоронці пильно стежать за твердинею, знаючи, що її підступність значно перевершує сусідні гнізда на кшталт Нічного Потоку. Нещодавно дріади-захисниці спробували проникнути в руїни, щоб повернути священну Гілку Кенарія, але зазнали тяжких втрат. Шукачі пригод, що прорвуться на зовнішні тераси, можуть знайти вмирущу дріаду Анілію, яка впала, намагаючись завадити оскверникам використати святі реліквії в темних закляттях."}},faq={{q="Чому це місце зветься Ксавіан?",a="Твердиню названо на честь Лорда Ксавіуса, придворного з Високородних при королеві Азшарі, який допоміг привести Палаючий Легіон в Азерот під час Війни Прадавніх. Розгнівавши Саргераса, Ксавіус був перетворений на найпершого сатира, і це демонічне прокляття перекинулося на інших йому подібних.",al={"походження ксавіану","на честь кого ксавіан","ксавій ксавіан"}},{q="Що тут роблять сатири?",a="Сатири використовують Ксавіан як головний командний осередок в Ашенвалі. Вони проводять темні ритуали, щоб поширити демонічну скверну прадавнім лісом, і використовують для цього осквернені священні реліквії, як-от викрадену Гілку Кенарія, а ще мастило для машин, поцуплене в орків Бойової Пісні.",al={"що тут роблять сатири","ритуали сатирів ксавіану"}},{q="Хто ця вмираюча дріада, що лежить на землі?",a="Її звуть Анілія. Вона була серед дріад, які намагалися повернути в сатирів викрадену Гілку Кенарія. У сутичці її смертельно поранили, і тепер вона лежить серед руїн, благаючи когось повернути священну гілку, поки її остаточно не осквернили.",al={"поранена дріада ксавіану","хто така анілія","дріада ксавіану"}},{q="Чим Ксавіан відрізняється від Сатирнаару чи Нічного Потоку?",a="Сатирнаар і Нічний Потік — помітні табори сатирів в Ашенвалі, але Ксавіан — політичне й обрядове серце їхніх сил у лісі. Тут, серед руїн, отаборилися високопоставлені ватажки сатирів, як-от Ґелтарис і Принц Рейз.",al={"ксавіан проти сатирнаару","інші табори сатирів","чому ксавіан важливий"}}},fp="6,267,16.643.0,19.565.1,31.293.0,31.277.0,43.264.0,51.247.0"}
P.entries["subzone:yojamba-isle"] = {n="Острів Йоджамба",s="Острів Йоджамба — кілька невеликих тропічних острівців біля північно-західного узбережжя Долини Стренглторну, неподалік від вод, що ведуть до Вестфолу. Тут отаборилося учене Плем'я Зандалар, яке закріпилося на острові, щоб стежити за кризою, що дедалі глибшає в джунглях. Звідси зандаларі шукають охочих поборників і з Орди, і з Альянсу, готових протистояти прадавнім жахам, що прокидаються в Зул'Ґурубі.",h="Острів Йоджамба — кілька невеликих тропічних острівців біля північно-західного узбережжя Долини Стренглторну...",kw={"острів йоджамба","плем'я зандалар","зандаларі","гаккар","зул'ґуруб","тролі"},ang={["faction:Alliance"]="Шукачі пригод з Альянсу можуть здивуватися, натрапивши на мирний табір тролів так близько від Вестфолу, проте перед лицем згубної загрози Душолупа зандаларі відклали політику вбік.",["race:Troll"]="Для тролів Темного Списа зустріч із зандаларі — це зустріч із прадавнім корінням тролячої цивілізації, чиї традиції, престиж і вимоги викликають глибоку шану."},sec={{t="Посланці Зандалару",b="Більшість тролів, яких можна зустріти в Долині Стренглторну, ворожі до чужинців, але Плем'я Зандалар на Острові Йоджамба тримається хиткого нейтралітету. Зандаларі — прадавні жерці й хранителі переказів тролячої цивілізації, і вони з дедалі більшим жахом спостерігали, як тролі Ґурубаші в Зул'Ґурубі звернулися до Гаккара Душолупа. Знаючи, що повністю викликаний бог крові загрожує кінцем світу, зандаларі вирушили далеко від своєї прабатьківщини, щоб облаштувати тут базу, і закликають кожного вмілого шукача пригод — хоч до якої фракції він належить — допомогти приборкати цю загрозу."},{t="Стережені води",b="Острів спокійно лежить біля узбережжя на північний захід від Мерзенного Рифу й руїн, що бовваніють на материкових пляжах. На півночі ховається величезна потаємна морська брама Бухти Айронклад, а на довколишніх мілинах раз у раз з'являються морські чудовиська. Попри непевне розташування, табір зандаларі — тиха оаза, де екзотичні ритуали, священні вівтарі й прадавні знання дають розраду й силу тим, хто готується вирушити в найтемніші руїни джунглів."}},faq={{q="Чому тролі на Острові Йоджамба дружні?",a="Ці тролі належать до Племені Зандалар — шанованої касти жерців і літописців тролячого народу. На відміну від Кривавого Скальпу чи Череполомів, що ревно стережуть свої землі вглибині краю, зандаларці прибули з невідкладною місією — зупинити Гаккара Душолупа в Зул'Ґурубі, і розуміють, що для цього їм потрібна допомога чужих героїв і з Орди, і з Альянсу.",al={"чому тролі йоджамби дружні","чому тролі йоджамби не нападають","дружні тролі зандалару"}},{q="Де розташований Острів Йоджамба?",a="Острів Йоджамба лежить у далекому північно-західному морі біля Долини Стренглторну, неподалік від узбережжя на північний захід від Мерзенного Рифу, біля морської межі, де південне море сусідить із Вестфолом.",al={"розташування острова йоджамба","як дістатися до йоджамби","де йоджамба"}},{q="Що тут робить Плем'я Зандалар?",a="Зандаларці розбили передовий табір, щоб стежити за небезпечним відродженням Гаккара Душолупа в Зул'Ґурубі. З Острова Йоджамба їхні посланці набирають, споряджають і нагороджують могутніх шукачів пригод, готових увійти в стародавнє тролляче місто й здолати спотворене жрецтво, перш ніж Гаккар обрушить на Азерот усю свою силу.",al={"мета зандалару","чого хоче плем'я зандалар","чому тут зандалар"}}},fp="12,441,26.594.0,14.489.0,44.376.0,30.198.0,42.338.0"}
P.entries["subzone:yorgen-farmstead"] = {n="Хутір Йорґенів",s="Хутір Йорґенів — занедбана ферма на півдні Сутінколісся, що занепала разом із рештою неспокійного краю. Колись вона належала фермерові Свену Йорґену, а тепер її захопили розбійники Братства Дефіас.",h="Хутір Йорґенів — занедбана ферма на півдні Сутінколісся, що занепала разом із рештою неспокійного краю.",kw={"хутір йорґенів","свен йорґен","дефіас","ферма","сутінколісся"},ang={["class:Rogue"]="Приховані вбивці Дефіас, що стережуть хутір, роблять місцину підступною й показують, як легко розбійницькі агенти перетворюють занедбані садиби на замасковані сховки.",["faction:Alliance"]="Те, що ферма Свена дісталася Братству Дефіас, показує, як глибоко розбійницькі мережі проникли в Сутінколісся, поки Нічна Варта ледве тримає лад у Даркширі."},sec={{t="Зруйнована садиба",b="Хутір Йорґенів, що лежить серед похмурих лісів південного Сутінколісся, колись був справним господарством Свена Йорґена. Як і багато відрізаних садиб краю, ферма не встояла перед небезпеками, що насувалися. Свен був змушений покинути свої землі й відійти на північ, до тимчасового табору на Темному Березі. За його відсутності покинуте обійстя захопили розбійники, що шукали опори подалі від очей влади Стормвінда."},{t="Дефіас проникають",b="Порожнім хутір не лишився: Братство Дефіас перетворило його на свій плацдарм. Розбійники в масках і потайні головорізи чаяться серед трухлявих огорож і витертих негодою прибудов, ховаючись під густими кронами. Мандрівникам, що наближаються до хутора, слід ступати обережно: убивці Дефіас патрулюють околиці й влаштовують засідки на кожного, хто вдереться до їхнього новоздобутого сховку."}},faq={{q="Кому належить Хутір Йорґенів?",a="Хутір заснував і обробляв Свен Йорґен. Коли на його дім упала біда, а небезпека дедалі зростала, Свен утік до самотнього табору північніше, на Темному Березі.",al={"хто тут жив","чий хутір йорґенів","ферма свена йорґена"}},{q="Хто займає хутір тепер?",a="Покинуту садибу захопило Братство Дефіас. Кишенькові злодії, бандити й непомітні вбивці нишпорять зарослими подвір'ями й стайнями, тож навідуватися на хутір дуже небезпечно.",al={"хто на хуторі йорґенів","які вороги тут","хто живе тут тепер"}},{q="Куди подівся Свен Йорґен?",a="Свен покинув ферму, і тепер його можна знайти в скромному таборі на Темному Березі — на півночі, біля річки, що розділяє Сутінколісся й Ліс Елвінн.",al={"де свен","розташування свена йорґена","знайти свена йорґена"}},{q="Що Братство Дефіас робить у Сутінколіссі?",a="Братство Дефіас поширило свої справи далеко за межі Вестфолу. Розрізнені сільські поселення й ослаблена місцева оборона дають його агентам змогу ставити таємні табори й сховки поза досяжністю маршалів Стормвінда.",al={"дефіас у сутінколіссі","чому тут бандити","братство дефіас ферма"}}},fp="16,252,18.482.0,19.423.0,30.205.0,31.192.0,25.172.0,42.229.0"}
P.entries["subzone:zalashji-s-den"] = {n="Лігво Залашджі",s="Лігво Залашджі — відлюдна печера на східному узбережжі Танарісу. Тут самотньо живе Залашджі — загадковий нага, що оселився далеко від звичних місць, де збираються його зміїсті родичі.",h="Лігво Залашджі — відлюдна печера на східному узбережжі Танарісу.",kw={"лігво залашджі","залашджі","наги","печера","танаріс","узбережжя"},ang={["race:NightElf"]="Для нічних ельфів будь-яка поява проклятих, спотворених наг на берегах Калімдору — похмуре нагадування про прадавніх Високородних і Розкол."},sec={{t="Самотнє лігво",b="Ця прибережна печера, видовбана в стрімких кручах уздовж східного берега Танарісу, дає притулок лише одному мешканцеві — Залашджі. По всьому Калімдору наги відомі тим, що збираються в дисципліновані бойові загони чи прибережні застави, але Залашджі живе тут зовсім сам. Мало хто знає, чому він обрав своїм володінням цю відлюдну печеру, далеко від головних поселень і пустельних руїн краю, проте кожному мандрівникові, що бреде прибоєм, варто наближатися до входу в печеру з обережністю."}},faq={{q="Де розташоване Лігво Залашджі?",a="Печера лежить на східному узбережжі Танарісу, у глибині скелястих круч, що межують з океаном.",al={"розташування лігва залашджі","де лігво залашджі","печера залашджі"}},{q="Хто такий Залашджі?",a="Залашджі — нага-одинак, що облаштував собі дім у цій відлюдній прибережній печері й тримається пустельного берега подалі від великих загонів наг.",al={"хто такий залашджі","лор залашджі","що таке залашджі"}},{q="Чи пов'язані з цією печерою якісь завдання?",a="Відомих завдань, що вели б шукачів пригод до Лігва Залашджі, немає. Воно лишається цікавим орієнтиром для дослідників, що мандрують східними околицями Танарісу.",al={"завдання лігва залашджі","чи є тут завдання","завдання залашджі"}},{q="Чому нага живе сам у Танарісі?",a="Справжні його мотиви невідомі. Наги зазвичай збираються біля затонулих руїн чи в упорядкованих таборах, а Залашджі тримається осторонь у цьому самотньому приморському лігві.",al={"чому залашджі сам","нага в танарісі","чому залашджі тут"}}},fp="14,211,15.496.0,32.117.0,16.142.0,47.162.0,38.165.0"}
P.entries["subzone:zoram-gar-outpost"] = {n="Застава Зорам'гар",s="Застава Зорам'гар — укріплений плацдарм Орди на західному краю Ашенвалю, на Зорамському Узмор'ї. Цей важливий прибережний табір дає Орді вихід до Прихованого Моря й пильнує загрози краю — наг, що наступають, і зловісні глибини неподалік.",h="Застава Зорам'гар — укріплений плацдарм Орди на західному краю Ашенвалю, на Зорамському Узмор'ї.",kw={"застава зорам'гар","зорамське узмор'я","орда","наги","чорноглибинні печери","ашенваль"},ang={["faction:Alliance"]="Зорам'гар — укорінена присутність Орди на узбережжі Ашенвалю, небезпечний опорний пункт постачання поблизу прадавніх земель нічних ельфів.",["faction:Horde"]="Застава — ваш головний прихисток у північно-західному Ашенвалі: тут можна сховатися, відпочити й полетіти на вітрокрилі серед небезпечних нетрів."},sec={{t="Оплот на узмор'ї",b="Застава Зорам'гар, що стоїть на північно-західному краю Ашенвалю, де прадавній ліс обривається в море, — відокремлений прибережний плацдарм Орди на Зорамському Узмор'ї. Затиснутий між землями нічних ельфів у глибині суходолу й морськими небезпеками біля берега, табір слугує базою для розвідників, мисливців і шаманів, яким доручено стежити за місцевими загрозами. Життя на заставі — нескінченна варта: наги раз у раз нишпорять на мілинах, а з підземних печер, відомих як Чорноглибинні Печери, трохи далі вздовж берега, ширяться культисти й первісні жахи."},{t="Стратегічне значення",b="Оскільки Зорам'гар лежить на околиці, звідси можна полетіти до інших важливих володінь Орди: Застави Розщепленого Дерева, Перехрестя й Тандер Блафа. Застава невелика, але саме вона тримає шляхи постачання Орди на західному узбережжі."}},faq={{q="Навіщо Орда заснувала Заставу Зорам'гар?",a="Орда розбила табір, щоб закріпитися на західному узбережжі Ашенвалю. Він дає змогу наглядати за морем уздовж Зорамського Узмор'я і слугує надійним опорним пунктом проти агресивних наг, що заполонили берег.",al={"чому зорам'гар тут","призначення зорам'гара","навіщо орда збудувала зорам'гар"}},{q="Яким загрозам протистоїть застава?",a="Найближча загроза — наги-Гнівохвости, що повзають Зорамським Узмор'ям. Крім того, сутінкові культисти й звірині жахіття з руїн храму неподалік — Чорноглибинних Печер — постійно чатують, готові вдарити.",al={"загрози зорам'гару","вороги зорам'гара"}},{q="Куди можна полетіти з застави?",a="Вітряні вершники із Застави Зорам'гар літають по всьому центральному Калімдору: до Застави Розщепленого Дерева, Притулку Сонячної Скелі, Перехрестя й столиці тауренів Тандер Блафа.",al={"польоти зорам'гара","куди летіти із зорам'гара"}},{q="Як застава пов'язана з Чорноглибинними Печерами?",a="Чорноглибинні Печери лежать трохи на північ від застави, серед прибережних руїн. Війська Орди в Зорам'гарі стежать за спотворенням, що сочиться із затопленого храму, і посилають туди шукачів пригод, щоб протистояти культистам та їхньому чудовиську Аку'маю.",al={"чорноглибинні печери біля зорама","чи чорноглибинні печери біля зорам'гара"}}},fp="17,302,23.568.0,20.255.0,46.229.0,35.235.0,49.185.0,63.250.0"}
P.entries["subzone:zoram-strand"] = {n="Зорамське Узмор'я",s="Зорамське Узмор'я — продуване вітрами узбережжя на північно-західному краю Ашенвалю, над Прихованим Морем. Колись тут стояло давнє місто нічних ельфів, яке поглинув Великий Розкол, а нині берег заполонили наги Гнівохвості, уламки кораблів і викинуті на сушу морські велетні. Тут же — вхід до затопленого храмового комплексу Чорноглибинних Печер.",h="Зорамське Узмор'я — продуване вітрами узбережжя на північно-західному краю Ашенвалю, над Прихованим Морем.",kw={"зорамське узмор'я","наги","гнівохвості","великий розкол","чорноглибинні печери","ашенваль"},ang={["faction:Horde"]="Оборона підступів до Застави Зорам'гар — запорука того, що Орда втримається на північному узбережжі Ашенвалю й на морі проти невгамовного виводка Гнівохвостих.",["race:NightElf"]="Узмор'я тверезо нагадує про давній світ, утрачений під час Розколу: священні реліквії й затоплені храми Елуни тепер топчуть наги."},sec={{t="Руїни розколотого узбережжя",b="Десять тисяч років тому ці береги прикрашало величне місто нічних ельфів Зорам — доки Великий Розкол не роздер Калімдор і не скинув поселення в океанські глибини. Сьогодні приплив раз у раз викидає давні реліквії, уламки розбитих суден і туші величезних морських звірів. Наги Гнівохвості заполонили пляжі й припливні калюжі, люто стережучи затоплені руїни й давні артефакти від кожного, хто наважиться наблизитися."},{t="Спірне узбережжя",b="Попри загрозу наг, на узмор'я тягнуться і мандрівники з глибини суходолу, і подорожні, що йдуть уздовж берега. На півдні лежить укріплений табір Орди — Застава Зорам'гар, чиї воїни безперервно б'ються за це узбережжя. Глибоко в печерах неподалік — Чорноглибинні Печери, давній храм Елуни, що потрапив до темних рук, тож узмор'я стало місцем збору для розвідників, учених і шукачів скарбів, які не бояться прибою."}},faq={{q="Чим був Зорам до свого знищення?",a="До Великого Розколу десять тисяч років тому Зорам був величним містом нічних ельфів. Катаклізм розтрощив узбережжя й занурив місто в Приховане Море, і від нього лишилися тільки щербаті руїни та викинуті на берег статуетки.",al={"історія зорама","стародавній зорам","чим був зорам"}},{q="Хто контролює Зорамське Узмор'я сьогодні?",a="Сам берег здебільшого заполонили наги-Гнівохвости, що люто обороняють мілини й прадавні руїни. Орда тримає укріплений плацдарм на Заставі Зорам'гар на південних скелях, а піском нишпорять небезпечні звірі — гідри й краби.",al={"хто живе на зорамському узмор'ї","вороги зорамського узмор'я","хто контролює зорамське узмор'я"}},{q="Де вхід до Чорноглибинних Печер?",a="Вхід до Чорноглибинних Печер ховається в затоплених гротах уздовж Зорамського Узмор'я. Мандрівники заходять у прибережні печери біля самої води, щоб дістатися спуску до затонулого храму.",al={"розташування чорноглибинних печер","як знайти чорноглибинні печери","вхід чорноглибинних печер зорам"}},{q="Чому тут стільки викинутих на берег морських істот?",a="Бурхливі припливи й темні течії Прихованого Моря часто викидають на берег величезних морських створінь. Дослідники й природознавці обох фракцій нерідко вивчають ці рештки, щоб з'ясувати, що змушує океанських велетнів гинути на скелях.",al={"завдання з викинутими істотами","мертві кити зорамського узмор'я","викинуті на берег істоти"}}},fp="12,345,27.453.0,21.453.0,39.239.0,36.269.0,43.202.0,49.251.0"}
P.entries["subzone:zul-farrak"] = {n="Зул'Фаррак",s="Зул'Фаррак — розлоге, розпечене сонцем місто з пісковику, сховане в північно-західних скелях Танарісу. Тролі Піщаної Люті, давно відрізані від решти свого роду, боронять цю прадавню твердиню з фанатичним завзяттям, темним вуду й ордою нежиті, піднятої з піщаних могил.",h="Зул'Фаррак — розлоге, розпечене сонцем місто з пісковику, сховане в північно-західних скелях Танарісу.",kw={"зул'фаррак","піщана лють","фарракі","ґаз'рілла","сержант блай","танаріс"},ang={["faction:Alliance"]="Людей і дворфів-дослідників часто вабить сюди бажання здобути прадавні реліквії або врятувати найманців із Ґаджетзана, які зникли в руїнах.",["race:Troll"]="Тролі Піщаної Люті вважають тролів Темного Списа жалюгідними зрадниками, що вступили в союз із чужоземними загарбниками, а старійшини Темного Списа, як-от Майстер Ґадрін, із похмурою тривогою спостерігають за своїми зіпсованими пустельними родичами."},sec={{t="Висохлий уламок",b="До того як Великий Розкол розтрощив прадавній Калімдор, Танаріс був буйними джунглями, що належали Імперії Ґурубаші, а Зул'Фаррак — одним із її визначних поселень. Відрізані від братів, коли моря розкололи світ, місцеві тролі Фарракі пристосувалися до розпеченої посушливої пустки й за тисячоліття перетворилися на загартованих піщаних тролів, якими вони є сьогодні. Прагнучи повернути втрачену велич, їхні жерці нині вдаються до жорстокого різновиду темної містики: вони викопують власних мерців, щоб зібрати армію ходячих трупів у своїх вибілених сонцем мурах."},{t="Легенди пісків",b="Ґаджетзаном ходять чутки про скарби й жахи, сховані за пильно стереженою брамою Зул'Фаррака. Тролячі перекази розповідають про Сул'траза Хльостача — легендарний палаш, розламаний на два окремі клинки, що досі ховаються десь у місті. Ще тривожніші оповіді про загін найманців на чолі із Сержантом Блаєм, який забрів до міста й потрапив у полон, а також чутки про Ґаз'ріллу — прадавню гідру-напівбога, що дрімає у священному ставку в самому серці міста."}},faq={{q="Яке плем'я тролів тут живе?",a="Зул'Фаррак тримає плем'я Піщаної Люті (його ще звуть фарраками). Колись воно належало до південної імперії Ґурубаші, але Великий Розкол перетворив їхній буйний край на пустелю, і тролі мусили пристосуватися до розпечених пісків.",al={"хто живе в зул'фаррак","плем'я піщаних тролів","які це тролі"}},{q="Чому всередині стільки зомбі й могил?",a="Доведені до відчаю й відрізані від світу, знахарі й мисливці тіней Піщаної Люті вдалися до темної некромантії. Вони почали піднімати своїх полеглих родичів як неживих рабів, щоб поповнити лави й воювати по всьому Танарісу.",al={"чому нежить у зул'фаррак","зомбі піщаної люті","тролячі могили"}},{q="Що за прадавнє чудовисько спить у місті?",a="Це Ґаз'рілла, колосальна гідра-напівбог. Вона дрімає в глибокому священному басейні посеред міста, і Піщана Лють їй поклоняється, хоча ходять тривожні чутки, що звіра можна викликати, якщо мати належний обрядовий інструмент.",al={"гідра зул'фаррак","давня істота в басейні","газрілла"}},{q="Що таке Сул'траз Батіг?",a="Сул'траз Батіг — легендарний клинок із прадавніх тролячих переказів, відомий тим, що висмоктує силу й волю з кожного, кого вразить. Давно тому його розбили на два окремі мечі, Джанґ'траз і Санґ'траз, і, за чутками, обидва зберігаються в місті.",al={"піщаний меч","сул'траз","легенда меча зул'фаррак"}}},fp="10,278,20.544.0,19.472.0,32.231.0,48.238.0,49.237.0,30.273.0"}
P.entries["subzone:zul-gurub"] = {n="Зул'Ґуруб",s="Зул'Ґуруб — прадавнє місто храмів, що ховається глибоко в джунглях на північному сході Долини Стренглторну. Колись воно було славетним серцем неосяжної Імперії Ґурубаші, а нині стало небезпечною твердинею, де тролі джунглів замишляють викликати у світ прадавню жахливу сутність.",h="Зул'Ґуруб — прадавнє місто храмів, що ховається глибоко в джунглях на північному сході Долини Стренглторну.",kw={"зул'ґуруб","гаккар","душолуп","атал'аї","імперія ґурубаші","джин'до зурочник"},ang={["faction:Horde"]="Орда пильно стежить за темними обрядами Зул'Ґурубу, розуміючи, що повернення бога крові загрожує самому існуванню довколишніх поселень і племен по всьому Стренглторну.",["race:Troll"]="Для племені Темного Списа Зул'Ґуруб — це і трагічний пам'ятник занепалій величі предків, і страшне застереження про згубну ціну служіння Гаккарові."},sec={{t="Серце занепалої імперії",b="Тисячі років тому Зул'Ґуруб безроздільно панував як квітуча столиця всієї Імперії Ґурубаші, що єднала племена тролів джунглів під своїми величними кам'яними зикуратами. Той золотий вік обірвався приблизно за півтори тисячі років до відкриття Темного Порталу, коли люта громадянська війна розірвала імперію на шматки. Радикальна секта жерців, Атал'аї, прагнула викликати Гаккара Душолупа — кровожерливого прадавнього бога, — щоб захопити абсолютну владу. Вірні племена об'єдналися, перемогли Атал'аїв і вигнали їх на північ, до Болота Скорботи, проте ця війна зламала імперії хребет, і Зул'Ґуруб перетворився на жорстоку тінь колишньої величі."},{t="Нависла тінь Душолупа",b="Хоч фанатичних шанувальників Гаккара й вигнали, вони так і не зреклися своєї темної відданості. Згодом вони збагнули, що фізичний аватар їхнього страхітливого божества можна викликати лише з прадавнього ритуального осередку — самого Зул'Ґурубу. У місті темні чаклуни, як-от Джин'до Зурочник, прагнуть поневолити верховних жерців Ґурубаші, щоб ті правили кривавими обрядами в ім'я Гаккара. Джунглі довкола руїн кишать надзвичайно агресивними тролями Ґурубаші, яких доведено до вбивчого шалу, тож місто храмів стало осередком жаху для кожного, хто наважиться — зі сміливості чи з дурості — підійти до його меж."}},faq={{q="Що таке Зул'Ґуруб?",a="Зул'Ґуруб — стародавнє місто-храм на північному сході Долини Стренглторну. Тисячі років тому воно було столицею великої імперії Ґурубаші, а нині це небезпечна зруйнована твердиня, де живе вороже плем'я Ґурубаші.",al={"історія зґ","що таке зґ","про зул'ґуруб"}},{q="Хто такий Гаккар Душолуп?",a="Гаккар Душолуп — прадавній і страшний бог крові. Йому поклоняється фанатична тролляча секта Атал'аї. Гаккар вимагає нескінченної крові й жертв, а його культисти здавна прагнуть темними ритуалами в Зул'Ґурубі привести в Азерот його тілесне втілення.",al={"гаккар","кривавий бог","хто душолуп"}},{q="Чому імперія Ґурубаші занепала?",a="Приблизно за півтори тисячі років до відкриття Темного Порталу імперію роздерла нищівна громадянська війна. Радикальні жерці Атал'аї спробували викликати Гаккара; інші тролі зрештою вигнали їх, але імперія після цієї війни так і не оговталася.",al={"чому занепала імперія ґурубаші","громадянська війна ґурубаші","падіння зул'ґуруб"}},{q="Чи можуть шукачі пригод безпечно досліджувати руїни?",a="Ні. Зул'Ґуруб надзвичайно небезпечний. Тролі Ґурубаші, що живуть у руїнах, люто агресивні й охоплені кривавим запалом. Шукачі скарбів і артефактів раз у раз зникають за кам'яними мурами, і мало хто з них повертається.",al={"чи зґ безпечний","скарби зґ","дослідження зґ"}}},fp="9,278,26.656.0,36.594.1,18.239.0,29.263.0,38.281.0,41.249.0"}
P.entries["subzone:zul-mashar"] = {n="Зул'Машар",s="Зул'Машар — давнє поселення лісових тролів, сховане в північно-східному куті Східних Чумних Земель. Колись горда столиця племені Мохолупів, після нескінченних війн із людськими королівствами й спустошення Чумою нежиття воно перетворилося на безлюдні руїни. Нині його останні захисники стоять перед підступним занепадом: Погибель діє зсередини, перетворюючи їх на рабів-нежить.",h="Зул'Машар — давнє поселення лісових тролів, сховане в північно-східному куті Східних Чумних Земель.",kw={"зул'машар","мохолупи","лісові тролі","мазра'алор","зикурат","треш'джин","погибель"},ang={["race:Troll"]="Для тролів Темного Спису лихо Мохолупів у Зул'Машарі — похмуре нагадування про долю відокремлених племен, які чіпляються за давню ворожнечу замість шукати союзників у світі, що змінюється.",["race:Undead"]="Відступники дивляться на Зул'Машар із насторожливим прагматизмом і стежать, чи вистоїть занепале плем'я Мохолупів, чи неминуче поповнить лави Погибелі свіжими лісовими тролями-зомбі."},sec={{t="Твердиня, що падає",b="Задовго до того, як Погибель прокотилася північним Лордероном, Зул'Машар був осередком влади лісових тролів Мохолупів. Постійні прикордонні сутички з людьми Лордерона поступово підточили їхню могутність і розкололи їхні володіння. Коли Чума нежиття накрила край, вона вдарила по Мохолупах так само безжально, як і по їхніх смертних ворогах. Великий ступінчастий зикурат Мазра'Алор досі стоїть, але Зул'Машар — лише порожня шкаралупа колишньої слави. Під проводом Воєначальника Треш'джина та Зул'Бріна Ворпбранча останні тролі вперто чіпляються за свій давній дім і здебільшого не бачать, що вплив Погибелі вже просочується в їхні лави й тихцем обертає їхніх родичів на гниючих потвор."},{t="Проникнення з тіні",b="Справжня загроза для Зул'Машара — не пряма облога Погибелі, а гниль, що повзе зсередини. Поки Мохолупи намагаються стерегти свій зикурат і зберегти незалежність на зруйнованій півночі, серед них ширяться агенти й потайна зараза. Серед руїн діють розвідники на кшталт Лазутчика Гамеї, живі воїни один за одним піддаються нежиттю, і колись горда твердиня ось-ось цілком потрапить під владу Короля-Ліча — без жодної великої битви."}},faq={{q="Хто контролює Зул'Машар?",a="Зул'Машар тримає плем'я лісових тролів Мохолупів на чолі з Воєначальником Треш'джином і Зул'Бріном Ворпбранчем. Проте їхня влада дедалі слабшає, бо чума нежиті проникає в їхню спільноту.",al={"хто живе в зул'машарі","правителі зул'машара","вожаки мохоскубів"}},{q="Що таке Мазра'Алор?",a="Мазра'Алор — помітний ступінчастий троллячий зикурат у Зул'Машарі. Це архітектурне серце й духовний осередок прадавньої столиці племені Мохолупів.",al={"мазра'алор","піраміда зул'машару","тролячий зіґурат східні чумні землі"}},{q="Чому Зул'Машар у руїнах?",a="Зул'Машар підточили довгі, виснажливі війни з людським королівством Лордерон, а потім його спустошила Чума Нежиття. Пошесть занапастила довколишні землі, а Мохолупи опинилися відрізаними від світу й ослабленими.",al={"чому зул'машар зруйнований","що сталося з зул'машаром"}},{q="Чи тролі тут у союзі з Погибеллю?",a="Ні, живі Мохолупи ворожі до чужинців і борються за свої прадавні землі. Проте Погибель потай заражає їхніх одноплемінників і перетворює на нежить, крок за кроком вигризаючи плем'я зсередини.",al={"чи мохоскуби з погибеллю","тролі працюють з погибеллю"}}},fp="10,422,20.765.0,29.512.1,24.206.0,19.182.0,27.225.0,44.225.0"}
P.entries["topic:alliance-of-lordaeron"] = {n="Альянс Лордерона",s="Альянс Лордерона — історична велика коаліція семи людських королівств, дворфів Каз Модану, вершників на грифонах із клану Вайлдгаммерів, гномів і високих ельфів, створена, щоб протистояти Старій Орді в Другій війні. Під військовим проводом Верховного Головнокомандувача Андуїна Лотара й дипломатичним — Короля Теренаса Менетіла II вона розгромила орківських загарбників і вберегла Східні Королівства. Хоча політичні розколи й спустошення, що їх принесла Погибель, розірвали її під час Третьої війни, її спадщина заклала основу сучасного Альянсу.",h="Альянс Лордерона — історична велика коаліція семи людських королівств, дворфів Каз Модану, вершників на...",kw={"альянс лордерона","андуїн лотар","теренас менетіл","друга війна","срібна длань","стара орда"},ang={["class:Paladin"]="Лицарів Срібної Длані Архієпископ Алонсус Фаол і Андуїн Лотар створили саме для того, щоб вони стали божественними ударними військами Альянсу Лордерона.",["faction:Alliance"]="Пам'ять про Альянс Лордерона — філософська основа й героїчні ідеали сучасного Альянсу з осередком у Стормвінді.",["race:Dwarf"]="І Бронзбірди Айронфорджа, і Вайлдгаммери Орлиного Піку викували свої нинішні зв'язки з людською цивілізацією в битвах Другої війни.",["race:Human"]="Альянс — єдиний раз від часів давньої Імперії Аратор — об'єднав усі Сім Королівств під одним стягом, доки місцеві чвари й Погибель їх не розкидали."},sec={{t="Коаліція, народжена з попелу",b="Після жахливого розграбування Стормвінда в Першій війні лорд-регент Андуїн Лотар перевіз через Велике Море знекровлених біженців із півдня до Столичного Міста. Коли він виклав їхню справу перед Королем Теренасом Менетілом II, правителі півночі зібралися на Раду Семи Націй. Давнє суперництво, прикордонні чвари й відокремленість — передусім Ґілнеасу й Альтераку — загрожували зірвати зустріч ще до її початку. Лише нагальна звістка про те, що Орда підкорює Каз Модан, і палке благання жерця Туральйона вивели правителів із самовдоволення. Обравши Лотара нейтральним Верховним Головнокомандувачем, сім людських націй зв'язали себе відчайдушною угодою."},{t="Друга війна й новий авангард",b="Перед лицем жорстоких орківських воїнів, темних чорнокнижників і страхітливих червоних драконів Альянс викував цілком нові воєнні доктрини. Архієпископ Алонсус Фаол і Лотар заснували Лицарів Срібної Длані, підносячи святих паладинів на кшталт Утера Світлоносця й Тіріона Фордрінга, щоб протистояти темній магії Орди. Коли війна прокотилася Пригір'ям і облогу Орлиного Піку було знято, Курдран Вайлдгаммер присягнув, що його люті вершники на грифонах пануватимуть у небі. Невдовзі після того визволили дворфів Бронзбірд і гномів Гномреґана, і вони приєдналися до слідопитів із високих ельфів під проводом Аллерії Віндраннер. Попри підступну зраду короля Перенольда з Альтераку, велика коаліція відкинула Орду до Шпиля Блекрок і зламала її панування."},{t="Розкол і руїна",b="Перемога принесла гіркоту, а не тривалий мир. Спалахнули запеклі суперечки через високі податки, потрібні, щоб утримувати табори для інтернованих орків і відбудовувати сплюндроване королівство Стормвінд. Не бачачи для себе вигоди, Ґілнеас збудував Стіну Ґреймейна й розірвав зв'язки, Стромґард вийшов через територіальні суперечки й чвари щодо полонених, а Кель'Талас сховався за своїми зачарованими рунними каменями. Коаліція, що лишилася під проводом Короля Теренаса, намагалася перечекати політичну бурю, але була вщент зруйнована під час Третьої війни, коли Лордероном прокотилися Культ Проклятих і Чума нежиття. Зрада Артаса Менетіла вирвала серце з королівства й поклала край золотій добі північного краю."}},faq={{q="Що таке Альянс Лордерона?",a="Це військово-політичний союз семи людських королівств, дворфів Айронфорджа й Орлиного Піку, гномів Гномреґана та високих ельфів Кель'Таласу, створений для боротьби з Ордою Оргріма Думхаммера в Другій війні.",al={"що таке альянс лордерона","хто в першому альянсі","історія великого альянсу"}},{q="Чому Альянс створили в Столичному Місті, а не в Стормвінді?",a="Під час Першої війни Стормвінд повністю захопили й зруйнували. Регент Лорд Андуїн Лотар повів уцілілих кораблями на північ, до Лордерона, щоб попередити короля Теренаса Менетіла II про чужинську загрозу.",al={"чому лордерон","стормвінд у другій війні","чому лотар пішов на північ"}},{q="Хто очолював Альянс Лордерона?",a="Король Теренас Менетіл II приймав союзників у себе й спрямовував політичну дипломатію, а сера Андуїна Лотара призначили Верховним Командувачем усіх союзних військ. Дейлін Праудмур був Великим Адміралом флотів.",al={"лідер альянсу лордерона","верховний командувач","хто керував"}},{q="Чому Альтерак зрадив Альянс?",a="Боячись, що Орду не зупинити, король Ейден Перенольд потай уклав угоду з Вождем Оргрімом Думхаммером. Альтерак пропустив Орду через свої гірські перевали в обмін на обіцянку, що його пощадять.",al={"зрада перенольда","що зробив альтерак","альтерак друга війна"}},{q="Чому Альянс Лордерона розпався?",a="Після Другої війни суперечки про витрати на табори для інтернованих орків і відбудову Стормвінда змусили Ґілнеас, Стромґард і Кель'Талас вийти з союзу. Рештки Альянсу загинули в Третій війні, коли принц Артас і Погибель знищили Лордерон.",al={"чому розпався альянс","що сталося зі старим альянсом","чому ґілнеас пішов"}},{q="Чим він відрізняється від сучасного Альянсу?",a="Альянс Лордерона цілком зосереджувався в північних королівствах довкола Столичного Міста й Даларану. Сучасний Альянс має осердя у відбудованому південному королівстві Стормвінд і включає нічних ельфів Калімдору, хоча й черпає натхнення з первісного союзу Лотара.",al={"старий і новий альянс","різниця між альянсами","чи це нинішній альянс"}}},fp="21,534,25.690.0,35.746.0,17.715.0,35.249.0,65.211.0,34.218.0,36.235.0,45.262.0,49.283.0"}
P.entries["topic:alterac-kingdom"] = {n="Альтерак (королівство)",s="Альтерак — одне із семи історичних людських королівств, що лежало високо в суворих Горах Альтерак. Під час Другої війни його правитель, Король Ейден Перенольд, уклав зрадницьку угоду зі Старою Ордою, щоб уберегти своє королівство, — і це призвело до військового розгрому й остаточного занепаду країни. Сьогодні її зруйнована столиця лежить покинута серед снігів, а позбавлені маєтків вельможі й розбійники ведуть партизанську війну під стягом Синдикату.",h="Альтерак — одне із семи історичних людських королівств, що лежало високо в суворих Горах Альтерак.",kw={"альтерак","ейден перенольд","синдикат","друга війна","зрада","гори альтерак"},ang={["class:Rogue"]="Гірські долини колишнього Альтераку — розбійницький притулок для таємних агентів, поділений між шляхетними головорізами Синдикату й потаємними вбивцями Маєтку Рейвенголдт.",["faction:Alliance"]="Для Альянсу Альтерак — гірке нагадування про зраду, яка в Другій війні мало не коштувала людству всього. Пам'ять про неї живить незгасну ворожість до розбійників Синдикату, що намагаються повернути родові маєтки.",["race:Human"]="Для людей північних королівств падіння Альтераку — трагічний урок боягузтва й розбрату, що показує, як легко страх розбиває єдність, викувану проти чужинських загарбників."},sec={{t="Народ серед скель",b="Альтерак постав тисячі років тому як араторське місто-держава після Тролячих воєн. Поселенці скористалися стратегічними гірськими перевалами й торговими заставами, а коли імперія розпалася, заснували незалежне королівство. Хоч і суворий та гористий, Альтерак межував із багатими землями Лордерона й Стромґарду й сягав аж до берегів Озера Дарроумер. Він здавна виставляв витривалих гірських вояків, але давні прикордонні чвари зі Стромґардом Тораса Тролбейна політично ізолювали королівство від сусідів задовго до того, як відчинився Темний Портал."},{t="Велика зрада",b="Коли сер Андуїн Лотар створював Альянс Лордерона, Король Ейден Перенольд приєднався до нього вкрай неохоче. Коли Орда Оргріма Думхаммера сунула на північ, Перенольд вирішив, що людство приречене, і таємно домовився з Вождем. В обмін на безпеку Альтераку Перенольд відчинив укріплені гірські перевали, плів змови проти військ Альянсу й навіть послав вояків і моряків допомагати Орді в облозі Лордерона. Ця зрада дала оркам змогу дістатися Столичного Міста значно раніше, ніж очікували, і, коли правда відкрилася, Альянс був вражений до глибини душі."},{t="Руїна й Синдикат",b="Розплата була швидкою. Війська Стромґарду рушили в гори, викрили зраду Перенольда й зламали військо Альтераку. Король Теренас Менетіл II запровадив у переможеній країні воєнний стан, а суперечки про те, хто має успадкувати трон, роками паралізували дипломатів Альянсу. Після падіння королівства Король Перенольд помер у ганьбі. Його син, Лорд Аліден Перенольд, згуртував озлоблену, вигнану знать і заснував Синдикат. Вдягнені в помаранчеве вбрання своєї загиблої батьківщини, ці розбійники й найманці нині безжально борються, щоб повернути родові володіння в Гілсбреді та Альтераку."}},faq={{q="Що сталося з Королівством Альтерак?",a="Альтерак занепав під час Другої війни, коли його король Ейден Перенольд зрадив людство й перейшов на бік Старої Орди. Війська Альянсу на чолі зі Стромґардом увійшли в королівство й розбили його військо. Корону скасували, край віддали під воєнний стан, а народ розпорошився серед руїн.",al={"падіння альтерака","чому альтерак зруйновано","доля альтерака","хто знищив альтерак"}},{q="Чому король Перенольд зрадив Альянс?",a="Ейден Перенольд вірив, що Альянсові не здолати Орду. Боячись повного знищення свого гірського королівства, він потай уклав союз із Вождем Оргрімом Думхаммером. Думхаммер пообіцяв, що Альтерак не зачеплять, а після падіння Лордерона він дістане захист і незалежність; натомість Орда отримала вільний прохід через гори.",al={"чому перенольд зрадив","мотиви перенольда","причина зради альтерака"}},{q="Як Синдикат пов'язаний з Альтераком?",a="Синдикат — злочинне продовження альтеракської знаті, засноване сином короля Перенольда, Лордом Аліденом Перенольдом. Організація прагне силою повернути родинні маєтки й землі в Гілсбреді та Альтераку. Їхні впізнавані помаранчеві маски — історичний національний колір Альтераку.",al={"зв'язок синдикату з альтераком","хто керує синдикатом","чому помаранчеві маски"}},{q="Чи всі альтеракці підтримали зраду?",a="Ні. Чимало альтеракських вояків спершу вирушили на війну й полягли, вірно б'ючись під проводом Андуїна Лотара в Гілсбреді. Коли король Стромґарда Торас Тролбейн притиснув генерала Гата, той неохоче підтвердив зраду Перенольда й послав своїх вояків допомогти зупинити наступ орків гірськими перевалами.",al={"чи альтеракці були вірні","чи всі зрадили альянс","генерал гат"}},{q="Які традиційні кольори й символи Альтераку?",a="Національний колір Альтераку — помаранчевий. Цей герб і барви носило королівське військо в Другій війні, а нині їх зберігає Синдикат, чиї члени носять помаранчеві маски й каптури.",al={"прапор альтерака","кольори альтерака"}},{q="Хто зараз контролює Місто Альтерак?",a="Зруйнована столиця, Місто Альтерак, не має ні визнаного монарха, ні законної влади. Це здебільшого руїни, де хазяйнують розбійники Синдикату, огри й дикі гірські звірі, а гарнізону Альянсу, здатного втримати високі перевали, там немає.",al={"хто править альтераком тепер","руїни міста альтерак","хто живе в місті альтерак"}}},fp="17,429,21.595.0,18.579.0,22.621.0,40.314.0,43.342.0,41.301.0,41.297.0,50.202.0,36.245.0"}
P.entries["topic:argent-dawn"] = {n="Срібний Світанок",s="Срібний Світанок — нейтральний лицарський орден, присвячений викоріненню лиховісних загроз в Азероті, передусім Погибелі й Палаючого Легіону. Його заснували вцілілі Лицарі Срібної Длані, що відкинули фанатичну одержимість Багряного Хрестового Походу, і він приймає звитяжців будь-якого народу чи фракції, які шанують справу Світла. Від укріпленого прихистку в Каплиці Надії Світла до далеких застав у Калімдорі — вони стоять на передовій боротьби з темрявою.",h="Срібний Світанок — нейтральний лицарський орден, присвячений викоріненню лиховісних загроз в Азероті...",kw={"срібний світанок","каплиця надії світла","срібна длань","багряний хрестовий похід","погибель","чумні землі","максвелл тіросус"},ang={["class:Paladin"]="Для святих воїнів Срібний Світанок — незаплямована спадщина Срібної Длані, що зберегла співчуття, жертовність і обов'язок, коли Багряний Хрестовий Похід піддався божевіллю.",["faction:Alliance"]="Світанок має офіційні посольства в Стормвінді й Дарнасусі й пропонує воякам Альянсу праведний шлях — відвоювати Лордерон із рук Короля-Ліча.",["faction:Horde"]="Хоча Світанок заснували колишні лицарі Лордерона, він без упереджень приймає звитяжців Орди, тож це один із небагатьох шляхів для героїв Орди безпосередньо воювати в Чумних Землях.",["race:Undead"]="Відступники, що зневажають Погибель, знаходять у таборах Світанку рідкісний прагматичний прихисток: тут ваші дії проти Кел'Тузада важать куди більше, ніж ваша гнила плоть."},sec={{t="Розкол віри",b="Коли загинув Верховний Лорд Александрос Моґрейн, а Лордерон обернувся на руїни, розбиті рештки Лицарів Срібної Длані погрузли в запеклих суперечках. Багато вцілілих піддалися горю й параної та перетворилися на ксенофобський Багряний Хрестовий Похід. Та ветерани на кшталт Лорда Максвелла Тіросуса й П'юргарта розуміли, що колишні побратими зреклися справжніх засад Святого Світла. Не бажаючи ні збожеволіти, ні покинути мертве королівство, вони відкололися й заснували Срібний Світанок — орден, що присягнув боронити Азерот разом із кожним, хто готовий битися, хай то Альянс чи Орда."},{t="Передова Чумних Земель",b="Головна твердиня Світанку — Каплиця Надії Світла посеред отруєних просторів Східних Чумних земель. З цього освяченого бастіону орден веде нескінченну війну з некромантами й легіонами скелетів Кел'Тузада. Утримуючи передові табори — Табір Студеного Вітру й табір біля Бастіону в Галявинах Тірісфалю, — офіцери Світанку видають шукачам пригод зачаровані доручення й платять винагороду за Камені Погибелі, відібрані в полеглої нежиті. Хоча Світанкові бракує чисельності Багряного Хрестового Походу, він тримає рубіж завдяки витривалості, єдності й непохитній дисципліні."},{t="Пильність по всьому Азероту",b="Лордерон лишається головним полем бою, але Срібний Світанок пильно стежить і за Калімдором, і за столицями світу. Він має дипломатичні представництва в Стормвінді, Дарнасусі й гоблінському торговому містечку Евірлук. Далі посланці на кшталт Делґрена Очищувача протистоять демонічним культам на Темному Узбережжі й в Ашенвалі, а розвідники в Пустограї та затоплених руїнах Чорноглибинних Печер розслідують зловісні загрози, пов'язані з Радою Тіней і культом Молота Присмерку."},{t="Хиткі перемир'я й приховані вороги",b="Перед загрозою знищення Погибеллю прагматичне угруповання в ордені — Братство Світла — намагається втримати холодне перемир'я з Багряним Хрестовим Походом. Та стосунки й далі вкрай напружені. Високі офіцери на кшталт Герцога Ніколаса Зверенгоффа потай схвалюють таємні удари по проводу Багряних у Стратгольмі, щоб вичистити те, що вони вважають єретичним божевіллям. До того ж темні сили невпинно намагаються проникнути в лави Світанку — зокрема таємні агенти, що викрадають некромантські таємниці з передової для підступних господарів деінде."}},faq={{q="Чим Срібний Світанок відрізняється від Багряного Хрестового Походу?",a="Обидва ордени постали з решток Срібної Длані після падіння Лордерона. Багряний Хрестовий Похід став фанатичним і ворожим до чужинців: усіх сторонніх і нелюдів він вважає можливими носіями чуми. Срібний Світанок відмовився зрікатися справжніх засад Святого Світла й відкрив свої лави для рас і Альянсу, і Орди, щоб разом боротися зі злом.",al={"срібний світанок проти багряного походу","чому розкололися","різниця між світанком і походом"}},{q="Що робити з каменями Погибелі?",a="Офіцери Срібного Світанку приймають камені Погибелі як доказ служби проти нежиті. Ці моторошні знаки засвідчують перемоги над Погибеллю й допомагають орденові розпізнавати своїх союзників.",al={"для чого камені погибелі","камені погибелі срібного світанку","здати камені погибелі"}},{q="Чи можуть гравці Орди вступити до Срібного Світанку чи співпрацювати з ним?",a="Так. Срібний Світанок суворо нейтральний і стоїть поза політичними союзами. Він охоче приймає орків, тролів, тауренів і навіть Відступників, готових боротися з Погибеллю й Палаючим Легіоном, і тримає вербувальні пункти, як-от Бастіон на кордоні Тірісфалю.",al={"чи орда може вступити до срібного світанку","чи срібний світанок лише для альянсу","срібний світанок дружній до орди"}},{q="Що вони роблять на Калімдорі?",a="Світанок вважає своїм обов'язком захищати весь Азерот, а не лише Лордерон. Його агенти вирушили на Темне Узбережжя, в Ашенваль і Пустограй, щоб знищувати культи Ради Тіней, протистояти змовникам Молота Присмерку й пильнувати, щоб не сталося демонічних вторгнень.",al={"срібний світанок у калімдорі","срібний світанок ашенвейл","чому в темному березі срібний світанок"}},{q="Що таке Братство Світла?",a="Братство Світла — войовнича гілка Срібного Світанку під проводом Командира Еліґора Донбрінґера. Воно підтримує робочі, хоч і напружені, стосунки з Багряним Хрестовим Походом, щоб обидві сили спрямовували свою лють на Кел'Тузада, а не одна на одну.",al={"братство світла","братство світла срібний світанок","фракція еліґора"}}},fp="11,489,17.602.0,30.596.0,24.503.0,29.576.1,71.356.0,32.182.0,52.287.0,32.260.0,37.283.0"}
P.entries["topic:arthas-menethil"] = {n="Артас Менетіл",s="Колись золотий принц Лордерону й уславлений паладин Срібної Длані, Артас Менетіл збився з праведного шляху під час Третьої війни, переслідуючи демонів, що стояли за чумою. Заволодівши проклятим рунічним клинком Фростморном на крижаній півночі, він віддав свою душу, убив батька, короля Теренаса, і очолив нищення рідної землі як темний поборник Погибелі.",h="Колись золотий принц Лордерону й уславлений паладин Срібної Длані, Артас Менетіл збився з праведного шляху...",kw={"артас","менетіл","король-ліч","фростморн","стратгольм","лордерон","срібна длань","погибель"},ang={["class:Paladin"]="Артас — найбільша трагедія й ганьба Срібної Длані: його падіння спотворило самі засади справедливості й захисту, які так прагнув прищепити Утер.",["faction:Alliance"]="Зрада Артаса коштувала Альянсу Лордерону найбільшого королівства, столиці та легендарного ордену паладинів, на якому колись трималася людська віра.",["race:Human"]="Загибель Лордерону розколола людський рід навпіл: біженці розсіялися по всьому світу, а Стормвінд лишився останнім великим осередком людської могутності.",["race:Undead"]="Відступники ненавидять Артаса як нікого: під проводом королеви Сильвани вони вирвалися з-під ментальної влади темного принца й тепер прагнуть помститися за своє прокляття."},sec={{t="Золотий принц",b="Син короля Теренаса Менетіла II, Артас змалку мав утілювати ідеали Альянсу Лордерону. Бою його навчав Мурадін Бронзбірд, а під опікою Утера Світлоносця юнака прийняли до Ордену Срібної Длані. І знать, і простолюд шанували його як майбутнє людства. Відважний, умілий і запеклий захисник свого народу, він уперто відбивав набіги орків клану Блекрок і ватаг лісових тролів. Та під сяйливою зовнішністю ховалися непоступлива гордість і нав'язливий страх поразки."},{t="Погибель і Очищення Стратгольма",b="Коли загадкова Чума нежиття охопила північ Лордерону, Артас разом із чарівницею Джайною Праудмур мчав краєм, щоб спинити її поширення. Простеживши шлях зараженого зерна від Брілла до Андоргала, він убив некроманта Кел'Тузада — і лише тоді натрапив на величезну змову, яку плів жахолорд Мал'Ганіс. Опинившись у Стратгольмі серед заражених містян, Артас обрав холодну жорстокість замість моральної стриманості й наказав вирізати всіх мешканців міста, перш ніж ті обернуться на нежить. Нажахані його безумством, Утер і Джайна покинули його, а місто тим часом палало."},{t="Падіння і піднесення",b="Одержимий помстою, Артас вистежив Мал'Ганіса аж до крижаних пустель Нортренду. Там він знову зустрівся з Мурадіном і знайшов рунічний клинок Фростморн; щоб здолати демона, він знехтував його страшним прокляттям. Клинок відтяв душу Артаса, і той став маріонеткою Короля-Ліча. Повернувшись до Столичного Міста лицарем смерті, Артас пронизав рунічним клинком серце батька й утопив Лордерон у попелі та нежитті. Він розгромив Срібну Длань, стер з лиця землі Даларан і проклав криваву стежку крізь Кель'Талас, а тоді вирушив назад до Крижаного Трону, щоб злитися воєдино зі своїм темним володарем."}},faq={{q="Ким був Артас Менетіл до свого падіння?",a="Артас був кронпринцом Королівства Лордерон і спадкоємцем короля Теренаса Менетіла II. У дев'ятнадцять років його прийняли до Лицарів Срібної Длані, і його вважали одним із найкращих молодих паладинів і мечників королівства.",al={"передісторія артаса","ким був принц артас","артас принц лордерона"}},{q="Чому Артас вирізав Стратгольм?",a="Мешканці міста вже з'їли зерно, заражене Чумою Нежиття, тож неминуче мали встати безмозкою нежиттю під владою Мал'Ганіса. Вважаючи милосердя неможливим, Артас наказав негайно перебити все населення, щоб не постало військо Погибелі.",al={"чому артас знищив стратгольм","очищення стратгольма","чистка стратгольма"}},{q="Як Артас став на шлях зла?",a="Одержимий бажанням знищити Мал'Ганіса, Артас вирушив до Нортренду й заволодів Фростморном — проклятим рунним клинком, викуваним Королем-Лічем. Клинок висмоктав його душу й прив'язав його розум до Нер'жула, перетворивши на лицаря смерті, що очолив авангард Погибелі.",al={"як артас став злим","падіння артаса","чому артас став лицарем смерті"}},{q="Що сталося з королем Теренасом?",a="Скорившись Фростморну, Артас повернувся до Столичного Міста, вдаючи переможця. У тронній залі, під дзвін дзвонів і дощ пелюсток троянд, він вихопив рунний клинок і проштрикнув рідного батька.",al={"артас убиває батька","смерть короля теренаса","що сталося з теренасом"}},{q="Які стосунки були в Артаса з Джайною Праудмур?",a="Вони дружили з дитинства, а замолоду їх пов'язало взаємне кохання. Артас поклав край їхньому залицянню, віддавши перевагу обов'язку, хоча вони й далі були глибоко прив'язані одне до одного, доки його жорстокість у Стратгольмі не відштовхнула її.",al={"артас і джайна","чи джайна любила артаса","романс артаса"}},{q="Де Артас зараз?",a="Захистивши Крижаний Трон від мисливця на демонів Іллідана, Артас піднявся на Крижану Корону, розбив крижану в'язницю Короля-Ліча й злив свою сутність із Нер'жулом. Тепер він править Погибеллю з Нортренду.",al={"де артас","поточний статус артаса","чи артас живий"}}},fp="15,401,17.537.0,27.586.1,23.592.2,40.244.0,32.293.0,32.257.0,30.220.0,53.247.0,26.218.0"}
P.entries["topic:black-dragonflight"] = {n="Чорна драконячий рід",s="Колись непохитні Охоронці Землі, яким титани доручили берегти глибокі підземні царства Азероту, чорні дракони впали в божевілля й зраду. Зіпсований підступним шепотом ув'язнених Древніх Богів, їхній ватажок Нелтаріон став Детвінгом і обернув свій виводок на одну з найруйнівніших і найненависніших сил світу. Сьогодні його вцілілі нащадки плетуть змови з тіні й ведуть таємні війни проти королівств смертних.",h="Колись непохитні Охоронці Землі, яким титани доручили берегти глибокі підземні царства Азероту, чорні дракони...",kw={"чорна драконячий рід","детвінг","нелтаріон","охоронець землі","древні боги","чорні дракони"},ang={["class:Shaman"]="Шамани дивляться на чорних драконів із глибоким сумом і відразою, знаючи, що ті орудують священною силою стихії землі не задля гармонії, а щоб обертати камінь і магму на знаряддя мук.",["faction:Alliance"]="Альянс мусить постійно пильнуватися від політичних підривних дій, адже чорна драконячий рід не раз намагалася розбестити людську знать і скористатися аристократичними амбіціями при людських дворах.",["faction:Horde"]="Орда плекає давню образу на підступи зграї: вона натерпілася від її маніпуляцій у минулих війнах і стикається з її підземними виводками серед скель Калімдору та Східних Королівств."},sec={{t="Занепалі захисники",b="Давним-давно титан Каз'ґорот благословив Нелтаріона, створивши чорну драконячу зграю, щоб вона пильнувала землю, здіймала гори й стерегла глибокі печери Азероту. Віками чорні дракони стояли поруч з іншими зграями як терплячі, непохитні охоронці. Та тісний зв'язок із підземними основами світу їх і занапастив. Живучи в найглибших западинах, вони опинилися небезпечно близько до похованих в'язниць Древніх Богів. Століттями темний шепіт підточував розум шляхетного Охоронця Землі, аж поки не звів його з розуму й не перетворив увесь його виводок на жорстокі знаряддя руйнування."},{t="Зрада й вогонь",b="Під час давньої Війни Прадавніх Нелтаріон розбив єдність драконячого роду й обернувся проти родичів як Детвінг Руйнівник. Відтоді чорна зграя веде нещадну, злобну війну проти червоної, синьої, зеленої й бронзової зграй, які вважають її жорстокість цілковитим оскверненням життя. Замість плекати ґрунт, чорні дракони тепер орудують розплавленою магмою, чорною магією й пекучою сіркою, щоб випалювати землі, які колись доглядали, і втішаються, сіючи розбрат, горе й безкінечні чвари в краях смертних."},{t="Людські личини й інтриги смертних",b="На відміну від багатьох звірів, що покладаються лише на пазурі й полум'я, чорні дракони — майстри маніпуляцій. Вони часто приймають гуманоїдну подобу — найчастіше вишуканих темноволосих людей із пронизливим поглядом, — щоб проникати до королівських дворів і зал рад. Підштовхуючи правителів до пихи, сіючи розбрат між шляхетними домами й нашіптуючи отруйні поради вразливим вухам, зграя влаштовує падіння цивілізацій смертних зсередини: вона воліє, щоб королівства самі себе розірвали, перш ніж прилетять її молоді дракони спалити рештки."}},faq={{q="Чому чорні дракони злі?",a="Їхній прадавній обов'язок тісно пов'язав їх із підземними глибинами Азероту — саме там, де були ув'язнені прадавні Древні Боги. Упродовж тисячоліть божевільний шепіт цих сутностей просочувався в розум Нелтаріона, перетворюючи його захисні інстинкти на параною й злобу, аж поки вся його зграя не пішла за ним у спотворення.",al={"чому чорні дракони погані","хто зіпсував смертокрила","божевілля чорних драконів"}},{q="Якою силою володіють чорні дракони?",a="Титан Каз'ґорот дав їм владу над землею, тож вони повелівають каменем, магмою й силами земних глибин. Спотворені, вони володіють нестабільною земною стихійною силою, яку звуть чорною магією: видихають пекучий вогонь і розплавлений камінь, а їхня важка луска постійно пашить жаром.",al={"магія чорних драконів","здібності чорних драконів","що вміють чорні дракони"}},{q="Чи вдаються чорні дракони до перевтілень?",a="Так. Чорні дракони — майстри проникнення й політичних інтриг. Найчастіше вони приймають подобу вродливої знатної людини з темним волоссям і темними очима: так можна вільно ходити між придворними, маніпулювати монархами й розпалювати міжусобиці, не виказуючи своєї справжньої драконячої природи.",al={"чи дракони приймають людську подобу","маски чорних драконів","чорні дракони під виглядом людей"}},{q="Як упізнати ім'я чорного дракона?",a="Чорні дракони зазвичай дотримуються певних традицій найменування: чоловічі імена часто закінчуються на «-іон» (як-от Нелтаріон), а жіночі — на «-ія» (як-от Оніксія). Багато хто також бере слова, що нагадують про попіл, тінь, камінь чи руїну.",al={"правила імен чорних драконів","імена чорних драконів","як називають чорних драконів"}},{q="Чому інші драконячі роди їх ненавидять?",a="Під час Війни Прадавніх Хранитель Землі зрадив інші зграї й перебив тисячі своїх родичів. Особливо їх зневажає червона драконячий рід: вогненна злоба й спотворювальний вплив чорних для неї — протиприродна наруга над самим життям.",al={"червоний і чорний драконячий рід","чому дракони воюють між собою","громадянська війна драконячих родів"}},{q="Хто зараз очолює чорну драконячу зграю?",a="Їхній прадавній Аспект, Детвінг, зник з очей після давніх поразок, і його небезпечне потомство розпорошилося на окремі угруповання. Нині помітні його нащадки — як-от Нефаріан і Оніксія — переслідують власні безжальні цілі: поневолити суперників, підкорити королівства й виводити темних створінь.",al={"хто лідер чорних драконів","де смертокрил","хто править чорними драконами"}}},fp="18,450,21.607.0,17.534.0,33.551.1,27.329.0,35.302.0,31.302.0,39.259.0,41.265.0,37.306.0"}
P.entries["topic:blackrock-clan"] = {n="Клан Блекрок",s="Клан Блекрок — войовничий орківський клан, відомий суворою військовою дисципліною, неперевершеним ковальством і головною роллю в Першій і Другій війнах. Сьогодні клан глибоко розколотий: частина ветеранів іде за Траллом у Новій Орді, а люте угруповання ренегатів, відоме як Темна Орда, займає верхні вершини Гори Блекрок під проводом Ренда Блекгенда.",h="Клан Блекрок — войовничий орківський клан, відомий суворою військовою дисципліною, неперевершеним ковальством...",kw={"клан блекрок","блекгенд","ренд блекгенд","темна орда","гора блекрок","оргрім думхаммер"},ang={["faction:Alliance"]="Сили Альянсу воювали з кланом Блекрок у трьох війнах — від спалення Стормвінда до кривавих облог Гори Блекрок і Каз Модану.",["faction:Horde"]="Тралл вважає екстремістів Блекрок на чолі з Рендом загрозою самому існуванню миру й честі Нової Орди й таврує їх як ренегатів, що чіпляються за демонічне рабство.",["profession:Blacksmithing"]="Легендарне ковальство клану Блекрок сформувало сучасне орківське облогове ремесло й важкі латні обладунки — плід століть виплавки особливих руд у кузнях, що живляться силою стихій.",["race:Orc"]="Блекрок дав двох найвеличніших Вождів в історії орків, але його рештки у Східних Королівствах — гірке нагадування про Стару Орду, що жила кров'ю."},sec={{t="Ковадло Старої Орди",b="Клан Блекрок, що походить із суворих печер Ґорґронду на Дренорі, прославився жорсткою ієрархією, важкими обладунками й майстерністю кузні. Під проводом очільника клану Блекгенда він був жорстоким ядром Старої Орди під час вторгнення в Азерот і взяв в облогу Стормвінд. Коли Оргрім Думхаммер убив Блекгенда, щоб звільнити Орду від прямої влади ляльковода Ґул'дана, провід і кланом, і Ордою міцно лишився в руках Блекрок упродовж виснажливих кампаній Другої війни."},{t="Розколота спадщина",b="Після катастрофічної поразки Орди біля Гори Блекрок клан розпався. Багатьох воїнів зігнали до таборів для інтернованих Альянсу, звідки їх згодом визволив Тралл і прийняв до своєї оновленої Нової Орди. Проте нерозкаяні згуртувалися довкола синів Блекгенда — Ренда й Мейма. Це угруповання відступило на висоти Шпиля Блекрок і разом із рештками Драконячої Пащі та інших кланів-ренегатів утворило ворожу Темну Орду."},{t="Загроза у Шпилі",b="Сьогодні Ренд Блекгенд зі свого трону у Шпилі Блекрок проголошує себе справжнім Вождем. Темна Орда тримає хитке й підступне перемир'я з дворфами Темного Заліза, що ховаються в розпечених глибинах унизу, водночас воюючи і з Альянсом, і з Ордою Тралла. Непримиренні рештки клану, торкнуті демонічною скверною, бачили й у Лордероні: вони прагнуть відродити темні жертовні обряди."}},faq={{q="Чи орки Блекрок належать до Орди Тралла?",a="Дехто так, але більшість тих, кого можна зустріти у Східних Королівствах, — ні. Шановані ветерани Блекрок, як-от Ейтріґґ і Варок Саурфанг, служать Траллові на Калімдорі, але основна частина клану, що окопалася в Горі Блекрок, іде за Рендом Блекгендом і вважає Нову Орду Тралла слабкими зрадниками.",al={"чи блекрок у орді","чи блекроки дружні","тралл і клан блекрок"}},{q="Хто зараз очолює клан Блекрок?",a="У Горі Блекрок Дал'ренд (Ренд) Блекгенд очолює відколоту Темну Орду й претендує на провід у клані, яким колись командував його батько. Ті орки Блекрок, що влилися в Нову Орду, підкоряються безпосередньо Вождю Траллу.",al={"лідер блекрок","хто очолює блекрок","ренд блекгенд лідер"}},{q="Чому їх звуть кланом Блекрок?",a="Їх назвали на честь надзвичайно міцної руди чорного кольору, яку видобували на їхній прабатьківщині в Ґорґронді на Дренорі. Їхні ковалі навчилися виплавляти цей неймовірно твердий мінерал і кували з нього чудову зброю, що зробила їх легендарними воїнами.",al={"походження назви блекрок","чому блекрок","руда блекрок"}},{q="Що таке Темна Орда?",a="Темна Орда — відступницьке угруповання, що займає Верхній Шпиль Блекрока. До неї входять нерозкаяні орки Блекрок, ветерани Чорнозубого Вишкіру та союзні орки Драконячої Пащі. На чолі з Рендом Блекгендом вони відкидають владу Тралла й прагнуть підкорити Азерот під стягом Старої Орди.",al={"що таке темна орда","орда ренда","темна орда блекрок"}},{q="Що сталося з Блекгендом?",a="Під час Першої війни Оргрім Думхаммер викликав Вождя Блекгенда на двобій мак'ґора, щоб позбавити Раду Тіней її маріонеткового правителя. Оргрім розтрощив Блекгендові череп легендарним молотом Думхаммер і здобув і титул Вождя, і провід над кланом Блекрок.",al={"смерть блекгенда","хто вбив блекгенда","оргрім убиває блекгенда"}},{q="Чому орки Блекрок є в Лордероні?",a="Розпорошені загони клану після Другої війни втекли на північ або переховувалися в Лордероні. Деякі з цих ватаг знову звернулися до поклоніння демонам і темних жертвоприношень, накликавши на себе гнів Альянсу, а згодом — і Погибелі в Третій війні.",al={"орки блекрок в альтераку","блекроки в лордероні","блекроки поклоняються демонам"}}},fp="14,380,26.512.0,18.457.0,23.422.0,46.285.0,44.239.0,39.248.0,23.278.0,27.265.0,42.255.0"}
P.entries["topic:bronzebeard-clan"] = {n="Клан Бронзбірд",s="Клан Бронзбірд — правлячий королівський рід дворфів і переважна частина населення Айронфорджа. Після перемоги в давній Війні Трьох Молотів вони налагодили міцні зв'язки з людством і гномами, а нині, під проводом Короля Маґні Бронзбірда, є наріжним каменем Альянсу.",h="Клан Бронзбірд — правлячий королівський рід дворфів і переважна частина населення Айронфорджа.",kw={"клан бронзбірд","маґні бронзбірд","айронфордж","війна трьох молотів","мурадін","мойра"},ang={["profession:Blacksmithing"]="Бронзбірди славляться по всьому Азероту неперевершеною майстерністю виплавки, виготовлення зброї й важких обладунків.",["race:Dwarf"]="Кожен дворф-шукач пригод походить із королівства Бронзбірдів або служить йому — як непохитний захисник Каз Модану на службі Короля Маґні.",["race:Gnome"]="Коли Гномреґан упав під навалою трогів, Бронзбірди беззастережно дали гномам прихисток у Містечку Майстрів в Айронфорджі.",["race:Human"]="Людство й Бронзбірдів здавна пов'язують міцні узи — спільні бойові традиції й взаємна торгівля."},sec={{t="Війна Трьох Молотів",b="Колись суспільство дворфів в Айронфорджі процвітало під владою Верховного Короля Модимуса Анвілмара. Коли близько 230 років тому король помер від старості, приховане суперництво вибухнуло громадянською війною. Тан Мадоран Бронзбірд очолював традиційний гарнізон і найбільше постійне військо Айронфорджа, тож зумів вигнати з-під гори і Вайлдгаммерів, і клан Темного Заліза. Коли тан-чаклун Тауріссан пішов у наступ, щоб знову підкорити Каз Модан, Мадоран Бронзбірд повів свій клан у вирішальну кампанію, що розгромила військо Темного Заліза й закріпила панування Бронзбірдів над Айронфорджем."},{t="Опора Альянсу",b="Людські королівства вперше зустріли Бронзбірдів майже дві тисячі років тому, і взаємна повага виросла зі спільної майстерності в обробці металу, торгівлі й пристрасті до битви. Коли в Другій війні континентом прокотилася Орда орків, Король Маґні Бронзбірд привів своє королівство до Альянсу Лордерона. Попри жорстокі облоги, які довелося витримати в підземній твердині, інженери, стрільці й підривники Бронзбірдів дали вирішальну вогневу міць і зброю, що допомогли переломити хід війни."},{t="Горе на Високому Престолі",b="Нині Король Маґні править із Високого Престолу у Великій Кузні, але його правління затьмарює втрата. Його молодший брат, Мурадін Бронзбірд, був посланцем Альянсу в Лордероні й зник у крижаних пустищах Нортренду разом із принцом Артасом Менетілом — його вважають загиблим відтоді, як принц заволодів проклятим клинком Фростморном. Наче цього мало, зникла й донька Маґні, Принцеса Мойра, тож рід стоїть перед непевним спадкуванням, поки клан досліджує давні розкопки титанів, щоб збагнути власне походження."}},faq={{q="Хто править кланом Бронзбірд?",a="На Високому Престолі біля Великої Кузні сидить Король Маґні Бронзбірд. Ветеран Другої війни й майстер-коваль, він очолює і свій клан, і союзних дворфів Каз Модану.",al={"лідер бронзбірдів","хто король айронфорджа","нинішній король бронзбірд"}},{q="Як клан Бронзбірд здобув владу в Айронфорджі?",a="Після смерті Верховного Короля Модімуса Анвілмара близько 230 років тому між трьома великими кланами спалахнула громадянська війна. Командуючи головним постійним військом Айронфорджа, Тан Мадоран Бронзбірд вигнав із гори Вайлдгаммерів і Темне Залізо, а згодом розгромив загарбницьке військо Темного Заліза під проводом Тауріссана.",al={"війна трьох молотів","дворфійська громадянська війна","чому правлять бронзбірди"}},{q="Чим Бронзбірди відрізняються від інших дворфійських кланів?",a="Бронзбірди живуть в Айронфорджі й уособлюють традиційних гірських дворфів, вправних у важких латах, вогнепальній зброї та підземному будівництві. Вайлдгаммери ж живуть серед скель і в небі як вершники на грифонах, а ворожі дворфи Темного Заліза — майстри темного чаклунства й вогняної магії під Горою Блекрок.",al={"різниця кланів дворфів","айронфордж проти вайлдгаммерів","види дворфів"}},{q="Що сталося з Мурадіном Бронзбірдом?",a="Мурадін Бронзбірд вирушив до Нортренду посланцем і дослідником Альянсу. Він допомагав принцові Артасу Менетілу шукати рунний клинок Фростморн і, за повідомленнями, загинув, коли прокляту зброю зняли з п'єдесталу.",al={"де мурадін","чи мурадін живий","доля мурадіна"}},{q="Чому Бронзбірди так віддані археологічним розкопкам?",a="Учені Бронзбірдів знайшли реліквії, що пов'язують їхніх предків із прадавніми кам'яними землянами. Прагнучи дізнатися коріння свого народу й природу перетворення, відомого як прокляття плоті, клан фінансує розкопки й експедиції по всьому Азероту.",al={"чому дворфи копають","дворфійські розкопки","походження землян"}},{q="Де осідок влади королівської родини Бронзбірд?",a="Королівський трон, відомий як Високий Престол, стоїть у серці Айронфорджа біля Великої Кузні, де король Маґні вершить державні справи в оточенні радників і королівської варти.",al={"де тронна зала","розташування високого престолу","трон бронзбірдів"}}},fp="16,288,28.587.0,24.508.0,22.541.1,31.177.0,54.306.0,67.316.0,37.228.0,59.251.0,54.185.0"}
P.entries["topic:brotherhood-of-northshire"] = {n="Братство Нортшира",s="Братство Нортшира — святий людський орден клириків Церкви Святого Світла з осідком в Абатстві Нортшира в Лісі Елвінн. Спершу відомий як Клирики Нортшира, орден зазнав катастрофічних утрат у Першій війні, а згодом був відроджений під проводом Архієпископа Алонсуса Фаола. Сьогодні Братство — і духовний прихисток, і головне місце вишколу для молодих захисників Альянсу.",h="Братство Нортшира — святий людський орден клириків Церкви Святого Світла з осідком в Абатстві Нортшира в Лісі...",kw={"братство нортшира","абатство нортшира","алонсус фаол","святе світло","срібна длань","ліс елвінн"},ang={["class:Paladin"]="Трагічна різанина беззбройних клириків Нортшира в Першій війні безпосередньо спонукала Архієпископа Фаола створити Лицарів Срібної Длані.",["class:Priest"]="Абатство Нортшира — колиска клерикальної традиції Стормвінда, де давні вчення про зцілення, сповідь і Святе Світло плекали задовго до Першої війни.",["race:Human"]="Для поколінь мешканців Стормвінда Братство давало духовну розраду в скруті, а його абатство стало скромним початком для найвидатніших звитяжців королівства."},sec={{t="Клирики Першої війни",b="Століття тому побожні місіонери вирушили з Лордерона на південь, до королівства Стормвінд, і заснували Абатство Нортшира, щоб служити людям і втішати край Святим Світлом. Спершу відомі як Святий Орден Клириків Нортшира, вони славилися легендарним співчуттям — навіть доглядали поранених гнолів і тролів джунглів під час давніх прикордонних воєн. Коли Орда орків пройшла крізь Темний Портал, клирики хоробро вирушили на передову без обладунків і зброї, щоб зцілювати поранених вояків. Оскільки їхнє зцілення підтримувало військо Стормвінда, орки безжально полювали саме на них. Орден було знекровлено, абатство пограбовано й спалено, а вцілілі клирики мусили втекти на північ, за море, до Саутшора разом із сером Андуїном Лотаром."},{t="Іскра паладинства",b="Різанина клириків Нортшира сколихнула людські королівства. Зрозумівши, що сама віра без обладунків і бойової виучки не встоїть проти сокири, Архієпископ Алонсус Фаол вирішив створити воїнів, які поєднували б священну силу Світла з бойовою майстерністю лицаря. Залучивши вцілілих клириків і побожних лицарів, Фаол заснував Лицарів Срібної Длані — так з'явилися перші паладини людства. Тож жертва полеглих цілителів Нортшира стала самою основою святих воїнів, що зламали Орду в Другій війні."},{t="Відбудова й нинішній обов'язок",b="Після повернення Стормвінда й знищення Темного Порталу Архієпископ Фаол наглядав за відбудовою Абатства Нортшира й перетворив орден на Братство Нортшира. Нині, у 25 році після відкриття Темного Порталу, Абатство Нортшира — тихий, але важливий осередок, де новобранці збираються, щоб почати службу королівству. Під проводом таких постатей, як Жриця Анетта, Брат Саммуель і Брат Пакстон, Братство дбає про духовне здоров'я долини, береже давні тексти у своїй бібліотеці й навчає нове покоління захисників протистояти розбійникам, вовкам і тіням, що згущуються над Лісом Елвінн."}},faq={{q="Що таке Братство Нортшира?",a="Це чернечий орден Церкви Святого Світла з осідком в Абатстві Нортшира в Лісі Елвінн. Колись відомі як Клірики Нортшира, вони дають духовну настанову, лікують поранених і навчають нових шукачів пригод Альянсу, що лише починають свій шлях.",al={"хто такі братство нортшира","лор братства нортшира","клірики нортшира"}},{q="Що сталося з першими кліриками під час Першої війни?",a="Клірики пішли в Першу війну як цілителі на полі бою, без обладунків. Зрозумівши, що людських воїнів, яких підтримує свята магія, нелегко здолати, орки насамперед почали вирізати кліриків. Абатство захопили й зруйнували, і лише жменька кліриків утекла через Велике Море до Лордерона.",al={"клірики нортшира перша війна","що сталося з абатством","руйнування абатства нортшира"}},{q="Як клірики Нортшира надихнули паладинів?",a="Бачачи, як легко Орда вбиває кліриків без обладунків, Архієпископ Алонсус Фаол зрозумів, що Альянсу потрібні святі воїни, здатні вижити в жорстокому бою. Він поєднав духовну відданість кліриків із бойовою майстерністю лицарів і заснував Лицарів Срібної Длані.",al={"створення паладинів","походження срібної длані","алонсус фаол паладини"}},{q="Хто сьогодні очолює Абатство Нортшира чи навчає там?",a="В абатстві живуть кілька помітних членів Братства: Брат Пакстон, що завідує припасами й переписує тексти для бібліотеки, Жриця Анетта, що навчає майбутніх жерців, і Брат Саммуель, що наставляє паладинів-новачків.",al={"хто в абатстві нортшира","наставники абатства нортшира","брат пакстон"}},{q="Що це за похід до Мертвих Копалень під час Першої війни?",a="Огрський вождь на ім'я Турок викрав із Нортшира священний Фоліант Божественності. Сер Андуїн Лотар очолив похід у Мертві Копальні Вестфолу, щоб повернути його, але потрапив у пастку, доки його не врятували війська Стормвінда, які й повернули книгу до абатства.",al={"том божественності мертві копальні","андуїн лотар мертві копальні","турок мертві копальні"}},{q="Чи пов'язані вони з Братством Дефіас?",a="Ні, це цілковиті протилежності. Хоча в обох назвах є слово «братство», Братство Нортшира — святий релігійний орден, вірний Стормвінду, а Братство Дефіас — злочинний синдикат розбійників і бандитів, що тероризує села.",al={"братство нортшира дефіас","чи вони дефіас","нортшир дефіас"}}},fp="25,437,28.769.0,25.601.0,27.628.0,38.260.0,59.298.0,52.294.0,53.246.0,62.254.0,45.251.0"}
P.entries["topic:burning-blade-clan"] = {n="Клан Палаючого Клинка",s="Колись давній орківський клан, що славився смертоносними майстрами клинка й у ранніх війнах поринув у хаотичне шаленство, Палаючий Клинок нині здебільшого живе як зловісний культ демонопоклонників. Проникнувши до Дуротару й Пусток за вказівками Ради Тіней, його послідовники загрожують крихкому мирові краю. Тим часом жменька шляхетних майстрів клинка зреклася демонічної порчі й служить Вождеві Траллу в Новій Орді.",h="Колись давній орківський клан, що славився смертоносними майстрами клинка й у ранніх війнах поринув у...",kw={"палаючий клинок","ніру файрблейд","рада тіней","тіньова розколина","майстри клинка","дуротар"},ang={["class:Warlock"]="Культ уособлює безрозсудне демонічне поневолення, через яке чорнокнижникам Орди — як-от тим, що навчаються в Тіньовій Розколині в Ніру Файрблейда, — доводиться ховатися й терпіти пильну підозру.",["faction:Horde"]="Палаючий Клинок — незгасний привид зіпсованого демонічного минулого Орди, що загрожує Дуротару й Пусткам зсередини.",["race:Orc"]="Падіння клану — гірке нагадування про прокляття крові, яке різко контрастує з вірними честі майстрами клинка, що шукають спокути на службі Траллові."},sec={{t="Від клану до стихійної люті",b="Палаючий Клинок походить із земель Дренору, як і клани на кшталт Бойової Пісні, і здавна славився смертоносною традицією своїх майстрів клинка. Та коли його воїни випили кров Маннорота й у Першій війні пройшли крізь Темний Портал до Азероту, розум клану розколовся. До Другої війни вони вже ледве були впорядкованою спільнотою й поводилися радше як шалена стихійна сила. Кочові й навіжені, вони кидалися в бій, геть не дбаючи про виживання, і їх доводилося стримувати ограм, доки не наставав час спустити їх із прив'язі. Зрештою Альянс розгромив і розсіяв їх біля Темного Порталу."},{t="Розколота спадщина",b="Після Другої війни вцілілі рештки Палаючого Клинка різко розкололися. Дисциплінований загін майстрів клинка урочисто присягнув визволити свій народ із демонічного рабства й віддав свої клинки безпосередньо Вождеві Траллу як його особиста почесна варта. Та значно більша частина розпорошеного клану цілком підпала під владу Палаючого Легіону й Ради Тіней і перетворилася на таємний культ чорнокнижників, служителів Скверни й змовників, що ховаються по всьому Калімдору."},{t="Загроза в Дуротарі",b="Сучасний культ має ковени по всьому Калімдору й не дає спокою щойно прибулим оркам і тролям Темного Списа від перших днів у Долині Випробувань. Чорнокнижники Палаючого Клинка засіли на Громовому Хребті й тримають велику схованку в Череп-скелі біля східних воріт Оргріммара. Їхні культисти гуртуються довкола темних реліквій на кшталт Демонічного Зерна й збирають душі для демонічних обрядів, тож вони — головна внутрішня загроза стабільності молодої Орди в Дуротарі й Пустках."},{t="Зрадник у Розколині",b="Поки Тралл розбудовує Нову Орду, головний натхненник культу сидить у нього просто під носом. Ніру Файрблейд, нібито чорнокнижник Орди, що мешкає в Тіньовій Розколині, потай очолює Палаючий Клинок як посланець Ради Тіней. Ніру використовує пішаків, зокрема Пекучий Клинок із Провалля Лютого Вогню, яким не шкода пожертвувати, щоб зберегти личину нешкідливого дослідника, що допомагає Вождеві. Та Ніру не здогадується, що Тралл уже розкусив його зрадницьку вірність і пильно за ним стежить."}},faq={{q="Що таке клан Палаючого Клинка?",a="Спочатку це був орківський клан з Дренору, відомий добірними майстрами клинка; під час Першої і Другої воєн його поглинула жага крові. Нині ця назва передусім означає культ поклонників демонів, що діє по всьому Калімдору на користь Ради Тіней, хоча нечисленні майстри клинка, які стали на шлях виправлення, служать Орді Тралла.",al={"лор палаючого клинка","хто такі палаючий клинок","передісторія палаючого клинка"}},{q="Хто насправді очолює Палаючий Клинок?",a="Культ підкоряється Раді Тіней, а його осередками в Дуротарі й Пустках керують чорнокнижники й заклиначі демонів, що приховують свого справжнього господаря. Пошепки кажуть, що нитки керівництва ведуть неприємно близько до самого Оргріммара.",al={"лідер палаючого клинка","хто очолює палаючий клинок"}},{q="Чому вони нападають на молодих орків у Долині Випробувань?",a="Палаючий Клинок облаштував осередок у північних печерах Долини Випробувань, щоб заважати молодим оркам і тролям проходити обряди посвяти. За допомогою мерзенних фамільярів і темних медальйонів культисти плекають скверну в самому серці земель Орди.",al={"палаючий клинок долина випробувань","чому культисти в долині випробувань"}},{q="Чим Палаючий Клинок відрізняється від Пекучого Клинка?",a="Пекучий Клинок — секта, що засіла глибоко в Проваллі Лютого Вогню під Оргріммаром. Це менше відгалуження, а Палаючий Клинок — ширший культ, що діє по всьому Дуротару й Пустках. Хто керує сектою, можна з'ясувати, дослідивши провалля.",al={"пекучий клинок проти палаючого","різниця пекучого і палаючого клинка"}},{q="Чи всі члени Палаючого Клинка — культисти, що поклоняються демонам?",a="Ні. Хоча культисти становлять більшість, горді майстри клинка первісного клану відкололися ще до Третьої війни. Вони заприсяглися визволити свій народ із демонічного рабства й тепер вірно б'ються в лавах Нової Орди як особиста почесна варта Тралла.",al={"чи всі палаючі клинки погані","майстри клинка палаючого клинка добрі"}}},fp="18,452,27.647.0,14.507.0,21.475.0,24.501.1,31.336.0,37.241.0,56.249.0,67.245.1,56.253.0"}
P.entries["topic:cenarius"] = {n="Кенарій",s="Кенарій, Володар Лісу, — прадавній напівбог, син Елуни й Малорна, який відкрив нічним ельфам таємниці друїдства. Тисячі років він був великим покровителем смертних друїдів і охоронцем дикої природи, аж доки не поліг у бою під час Третьої війни.",h="Кенарій, Володар Лісу, — прадавній напівбог, син Елуни й Малорна, який відкрив нічним ельфам таємниці...",kw={"кенарій","напівбог","друїди","елуна","малфуріон","смарагдовий сон","ашенваль","третя війна"},ang={["class:Druid"]="Шлях кожного друїда веде просто до Кенарія — вічного покровителя, чиї уроки Малфуріонові заклали основи друїдства.",["race:NightElf"]="Калдореї шанують Кенарія як божественного наставника й союзника, а його смерть від рук орків Пісні Війни лишається непрощенною трагедією.",["race:Orc"]="Убивство Кенарія Ґромом Хеллскрімом — суворе нагадування про прокляття крові й руйнівну ціну служіння демонам.",["race:Tauren"]="Міфи тауренів тепло згадують Кенарія — прадавню спорідненість і спільну шану до Земної Матері ще до світанку новітньої історії."},sec={{t="Син неба і землі",b="Кенарій народився від Елуни, богині місяця, і великого білого оленя-напівбога Малорна. Оскільки Кенарій був прив'язаний до світу смертних, Елуна віддала його під опіку Малорна, а Ізера Сновидиця прийняла його як названа мати й вела безмежними стежками Смарагдового Сну. Наділений владою над живим деревом і землею, Кенарій став батьком Хранителів Гаю та дріад і назавжди пов'язав свій рід із дикими куточками Калімдору."},{t="Перший друїд",b="Хоча Кенарій недовго навчав прадавніх нічних ельфів і перших тауренів, смертні раси раз у раз відверталися від природи заради величних споруд таємної магії. Через тисячоліття троє юнаків — Малфуріон Стормрейдж, його брат-близнюк Іллідан і Тіранда Віспервінд — вирушили на пошуки легендарного напівбога. Кенарій розгледів виняткове серце Малфуріона й виховав із нього першого смертного друїда. Коли Королева Азшара та її Високородні випустили в світ Палаючий Легіон під час Війни Прадавніх, Кенарій зібрав диких напівбогів Калімдору, щоб пліч-о-пліч зі смертними боронити світ."},{t="Загибель в Ашенвалі",b="Десять тисячоліть після Великого Розколу Кенарій оберігав Калімдор і разом із Малфуріоном плекав Коло Кенарія. Ця пильна варта обірвалася під час Третьої війни, коли клан Пісні Війни почав вирубувати ліс в Ашенвалі. Обурений нищенням священних гаїв, Кенарій відкинув загарбників — аж доки Ґром Хеллскрім і його воїни не скуштували демонічної крові Маннорота. Сповнені демонічної люті, осквернені орки здолали напівбога й убили його, і на захисників природи впала темна тінь."}},faq={{q="Хто такий Кенарій?",a="Кенарій — прадавній напівбог природи, покровитель друїдів і вартовий дикої природи Азероту. Син місячної богині Елуни й напівбога Малорна, він виріс під опікою Аспекта драконів Ізери й став найвищим поборником диких земель.",al={"хто такий кенарій","лор кенарія","передісторія кенарія"}},{q="Хто діти Кенарія?",a="Його сини — Хранителі Гаю, як-от Хранитель Ремулос і Орданус, а доньки — чарівні дріади. Кентаври ведуть свій родовід від його сина Заетара, тож Кенарій — їхній дід.",al={"діти кенарія","хранителі гаю батько","доньки кенарія"}},{q="Як Малфуріон навчився друїдства в Кенарія?",a="Ще до Війни Прадавніх Малфуріон разом з Ілліданом і Тірандою розшукав легендарного напівбога. Побачивши в Малфуріонові рідкісну відданість і врівноваженість, Кенарій навчив його священних мистецтв природи, і той став першим смертним друїдом.",al={"малфуріон перший друїд","як малфуріон навчився друїдства"}},{q="Що сталося з Кенарієм під час Третьої війни?",a="Під час Третьої війни орки клану Бойової Пісні рубали ліс в Ашенвалі й накликали на себе гнів Кенарія. Прагнучи будь-що здолати силу напівбога, вождь Гром Хеллскрім напився з озерця, отруєного кров'ю Маннорота, і, здобувши демонічну силу, вбив Кенарія.",al={"як помер кенарій","хто вбив кенарія","смерть кенарія"}},{q="Як Кенарій пов'язаний із тауренами?",a="Прадавні биковидні предки тауренів жили в центральному Калімдорі поруч із Кенарієм. Коли їхні нащадки згодом знову зустрілися з напівбогом, ті, хто вчився в нього, опанували перші ази друїдської магії природи.",al={"таурени кенарій","чи кенарій навчав тавренів"}},{q="Що таке Коло Кенарія?",a="Коло Кенарія — чернечий орден друїдів, що береже рівновагу природи, вивчає Смарагдовий Сон і охороняє священні ліси. Його заснував на честь Кенарія його учень Малфуріон Стормрейдж.",al={"що таке коло кенарія","хто заснував коло кенарія"}}},fp="8,281,23.470.0,15.548.0,21.537.0,16.261.0,28.206.0,47.246.0,43.271.0,44.232.0,28.227.0"}
P.entries["topic:centaur"] = {n="Кентаври",s="Кентаври — жорстока гуманоїдна раса з кінським тілом, чиї кочові клани панують на посушливих рівнинах центрального Калімдору. Народжені з трагічного союзу напівбога Заетара й принцеси землі Терадрас, вони століттями зганяли тауренів на край вимирання, доки не втрутилася щойно прибула Орда орків.",h="Кентаври — жорстока гуманоїдна раса з кінським тілом, чиї кочові клани панують на посушливих рівнинах...",kw={"кентаври","заетар","терадрас","мародон","колкари","кайрн бладгуф","таурени"},ang={["class:Druid"]="Кентаври — трагічне збочення природної рівноваги: у них тече кров Кенарія через його полеглого сина Заетара, але по собі вони лишають тільки спустошення й різанину.",["faction:Horde"]="Відбивати набіги кентаврів у Пустках і Дуротарі — питання виживання й ушанування засадничої угоди між Траллом і Кайрном Бладгуфом.",["race:Tauren"]="Для вашого народу кентаври — не просто звірі: це давні мучителі, що мало не винищили ваших предків і століттями гнали вас через Пустки, доки Орда не принесла порятунок."},sec={{t="Проклятий рід",b="Кентаври з'явилися близько тисячі ста років тому під пустищами Пустограю. Коли Принцеса Терадрас, донька володарки стихій Теразейн, прокинулася й виснажила навколишню землю, зі Смарагдового Сну прийшов напівбог Заетар, щоб дізнатися причину. Вони уклали протиприродний союз, і їхні нащадки стали першими кентаврами. Нажаханий їхньою потворною, дикою вдачею, Заетар не зміг приховати відрази. Розлючені батьковою огидою, кентаври вбили його. Убита горем Терадрас поховала дух Заетара у своєму підземному святилищі — Мародоні, — але захищала й плекала своїх лютих дітей, які швидко розплодилися по всьому Калімдору."},{t="Століття різанини",b="Щойно з'явившись, кентаври почали розходитися з Пустограю й вести жорстоку війну на виснаження проти корінних народів Калімдору. Найбільше потерпіли кочові таурени: вигнаних із родючої батьківщини предків — Малгору, — їх безжально гнали через Пустки. Загони кентаврів полювали на тауренів, мов на здобич, палили поселення й убивали задля розваги. На час Третьої війни століття невпинного переслідування довели тауренів до межі вимирання: вони відчайдушно тікали саваною від нескінченних грабіжників."},{t="Поворот долі",b="Усе змінилося, коли Вождь Тралл і щойно прибула Орда орків висадилися в Калімдорі. Тралл уклав угоду з Кайрном Бладгуфом, поєднавши орківську сталь із силою тауренів. Разом вони розгромили агресивні загони Колкарів, зламали їхню владу над рівнинами й дали тауренам змогу безпечно заснувати Тандер Блаф і повернути Малгор. Цей союз поклав край кочовому вигнанню тауренів і встановив борг крові й честі, що назавжди прив'язав їх до Орди."},{t="Розколота загроза",b="Попри нищівні поразки, кентаври лишаються активною загрозою в центральному Калімдорі. Їхнє суспільство поділене на ворогуючі клани — передусім Колкарів, Ґелкісів, Маґрамів і Мародін, — кожен на чолі з ханом, і всі вони погрузли в безкінечній кровній ворожнечі за землі й воду. Внутрішні чвари не дають їм об'єднатися в нестримну орду, але люті загони й далі нападають на торгові каравани й поселення в Дуротарі, Пустках, Тисячі Голок і на межах Малгору."}},faq={{q="Звідки взялися кентаври?",a="Вони народилися від союзу Заетара, сина Кенарія, і Принцеси Терадрас — принцеси стихії землі. Потворні й люті від народження, перші кентаври вбили свого батька, побачивши відразу в його очах. Тоді Терадрас поховала його дух у священних печерах Мародону.",al={"походження кентаврів","хто створив кентаврів","лор створення кентаврів"}},{q="Чому кентаври так ненавидять тауренів?",a="Кентаври агресивно розселилися з Пустограю й понад тисячу років нападали на корінні народи рівнин. Вони полювали на тауренів для розваги й вигнали їх із Малгору в нескінченне кочове вигнання по Пустках, ледь не винищивши весь народ, поки не втрутилися орки.",al={"ворожнеча кентаврів і тавренів","чому кентаври полюють на тавренів","війна кентаврів і тавренів"}},{q="Які є клани кентаврів?",a="Головні клани на Калімдорі — Колкар, Ґелкіс, Маґрам, Мародін і Ґалак. Кожен веде свій провід від перших ханів, що його заснували, і клани раз у раз ведуть між собою криваві чвари.",al={"племена кентаврів","клани кентаврів","фракції кентаврів"}},{q="Де нині можна зустріти кентаврів?",a="Серце їхніх земель — пустище Пустограй, де лежить їхня святиня Мародон. Проте агресивні ватаги й застави кентаврів трапляються по всіх Пустках, у Дуротарі й Тисячі Голок.",al={"де кентаври","місця кентаврів","зони кентаврів"}},{q="Чи можна з кентаврами домовитися чи укласти союз?",a="Здебільшого кентаври вважають усі інші раси слабкою здобиччю, яку треба поневолити чи знищити. Проте запеклим суперництвом між кланами іноді можна скористатися: наприклад, клани Пустограю, як-от Маґрам чи Ґелкіс, часом приймали допомогу чужинців, щоб знищити своїх ненависних родичів.",al={"чи дружні кентаври","чи можна союзувати з кентаврами","дружні кентаври"}},{q="Ким є для кентаврів Принцеса Терадрас?",a="Терадрас — їхня мати й шанована покровителька. Глибоко в Мародоні вона оберігає дух їхнього вбитого батька Заетара й час від часу наповнює своїх нащадків стихійною люттю, підштовхуючи їх загарбувати нові землі Калімдору.",al={"мати кентаврів","терадрас і кентаври","принцеса терадрас лор"}}},fp="7,311,16.680.0,22.569.0,14.483.0,18.507.0,28.296.0,39.299.0,36.209.0,36.200.0,39.295.0,41.250.0"}
P.entries["topic:cult-of-the-damned"] = {n="Культ Проклятих",s="Культ Проклятих — потаємна кліка смертних фанатиків, некромантів і аристократів, відданих Королю-Лічу. Заснований на півночі Лордерона ще до Третьої війни, він отруїв запаси зерна, що породили Погибель, і спричинив падіння найвеличнішого королівства людства. Нині вцілілі культисти доглядають чумні казани й некромантські академії по всіх Чумних Землях і водночас активно проникають у міста живих.",h="Культ Проклятих — потаємна кліка смертних фанатиків, некромантів і аристократів, відданих Королю-Лічу.",kw={"культ проклятих","кел'тузад","король-ліч","чума нежиття","андоргал","сколомансія"},ang={["class:Mage"]="Культ — болісна пляма на честі Кірін-Тор, адже його заснував один із шанованих архімагів самого Даларана — Кел'Тузад.",["class:Paladin"]="Культ Проклятих — найбільше блюзнірство проти Святого Світла: він орудує мерзенною некромантією, щоб розбещувати живих і тривожити вічний спочинок мертвих.",["faction:Alliance"]="Розвідники й вояки Альянсу мусять постійно пильнувати, бо лазутчики культу й досі намагаються сіяти чуму й хаос у містах живих на кшталт Стормвінда.",["race:Human"]="Кожна людина пам'ятає падіння Лордерона; Культ Проклятих — гірке нагадування, що людство підкорили не самі лише демони, а й зрадники з його власних міст і маєтків.",["race:Undead"]="Для Відступників культисти — жалюгідні песики, що добровільно віддають свободу господареві, чиї ментальні кайдани Відступники так тяжко розбивали."},sec={{t="Хвороба душі",b="Культ Проклятих створив вигнаний архімаг Кел'Тузад, відгукнувшись на телепатичний шепіт Короля-Ліча, що лунав із Крижаного Трону. Повернувшись до Лордерона з величезними статками й забороненими темними мистецтвами, Кел'Тузад проповідував дві фальшиві благі звістки: зубожілим, зневіреним низам він обіцяв соціальну рівність і звільнення від злиднів, а багатим землевласникам, як-от шляхетному Дому Баровів, — вічне життя й непохитну владу над їхніми володіннями. Насправді і злидарі, і багатії були худобою на заріз, зв'язаною культом смерті, створеним, щоб зрадити батьківщину зсередини."},{t="Отруєний урожай",b="Діючи в цілковитій таємниці з підземель під Каер Дарроу, культисти відточували некротичне ремесло, будували масивних гидот і довершували Чуму нежиття, привезену з Нортренду на південь. Вони вдарили по житниці Лордерона, отруївши зерносховища Андоргалу. Коли отруєне борошно звичайними торговими шляхами розійшлося по оселях Іствілду, прості люди хворіли й за кілька днів помирали — а тоді підводилися незграбними невільниками під телепатичним батогом Короля-Ліча. Коли принц Артас убив Кел'Тузада в Андоргалі, мережа культистів уже так глибоко вкоренилася, що загибель королівства була вирішена."},{t="Нинішня загроза",b="Хоча Артас поплив до Нортренду й зійшов на Крижаний Трон, Культ Проклятих і далі діє на півночі Лордерона під командуванням воскреслого архіліча Кел'Тузада. З тіней Стратгольма й залів Сколомансії живі культисти правлять темні обряди, доглядають отруйні чумні казани на зруйнованих фермах і намагаються вбивати і Багряних хрестоносців, і Відступників. Оскільки вони досі дихають, ці послідовники непомітно ходять поселеннями живих, отруюють колодязі, зривають постачання й готують нових рекрутів, щоб живити машину Погибелі."}},faq={{q="Чому живі смертні вступають до культу, що перетворює людей на нежить?",a="Кел'Тузад грав на людських слабкостях. Зубожілим низам він обіцяв новий лад цілковитої рівності й порятунок від злиднів, а багатим вельможам, як-от Барон Рівендер і родина Баров, — безсмертя й вічну владу. Більшість посвячених до останнього не знали справжньої, жахливої природи чуми — аж поки повертати назад ставало запізно.",al={"чому вступають до культу проклятих","мотиви культистів","чому служать погибелі"}},{q="Чому культистів лишають живими, а не вбивають і піднімають?",a="Живі агенти дуже корисні Королю-Лічу. Вони можуть непомітно ходити людськими поселеннями, торгувати звичними купецькими шляхами, купувати припаси й підточувати королівства зсередини. До того ж у вченні культу нежиття вважається славетною нагородою, яку треба заслужити відданою службою.",al={"чому культисти люди","чому не нежить","живі культисти"}},{q="Де осідок Культу Проклятих?",a="Їхній головний освітній і духовний оплот — Сколомансія в катакомбах під Каер Дарроу. Окрім цієї академії, чимало культистів діє в руїнах Стратгольма, біля чумних казанів у Західних і Східних Чумних землях, а також у таємних осередках, захованих у поселеннях живих.",al={"штаб культу","де культ","головна база культу"}},{q="Хто заснував Культ Проклятих?",a="Архімаг Кел'Тузад, колишній високопоставлений член Кірін-Тору з Даларану. Після осуду за заборонені некромантичні студії він вирушив на північ, щоб зв'язатися з Королем-Лічем, а той наділив його величезною силою й відіслав назад до Лордерона збирати смертний авангард Погибелі.",al={"хто заснував культ проклятих","засновник культу","культ кел'тузада"}},{q="Як Культ Проклятих поширює чуму нині?",a="Спершу культисти поширювали чуму через заражене зерно, яке відправляли з Андоргала, а тепер покладаються переважно на величезні чумні казани на фермах Чумних Земель. Володарі казанів із культу варять мерзенні зілля, що безперестанку випускають отруйні хмари пошесті: вони душать землю й піднімають полеглих мерців.",al={"як чума поширюється","чумні казани","як культ нападає"}},{q="Як культ ставиться до Відступників?",a="Вони — закляті вороги. Відступники вирвалися з-під телепатичної влади Короля-Ліча й прагнуть помститися Погибелі. Культисти вважають Відступників викраденою власністю й єретиками і постійно намагаються їх знищити або відвоювати руїни Лордерона для Крижаного Трону.",al={"культ проти відступників","відступники й культ проклятих"}}},fp="18,457,22.652.0,20.632.0,18.609.0,62.368.0,74.313.0,38.324.0,35.291.0,56.309.0,48.283.0"}
P.entries["topic:dark-iron-clan"] = {n="Клан Темного Заліза",s="Клан Темного Заліза — давнє угруповання попелястошкірих дворфів, що править із вулканічних глибин Гори Блекрок. Вигнані з Айронфорджа під час Війни Трьох Молотів, вони ненароком викликали Рагнароса, Володаря вогню, який поневолив їхню імперію. Сьогодні під проводом Імператора Даґрана Тауріссана вони ведуть таємні війни і з Альянсом, і з Ордою, служачи своєму вогняному господареві-стихії.",h="Клан Темного Заліза — давнє угруповання попелястошкірих дворфів, що править із вулканічних глибин Гори...",kw={"клан темного заліза","даґран тауріссан","рагнарос","глибини блекрок","мойра бронзбірд","війна трьох молотів"},ang={["faction:Alliance"]="Альянс вважає Темне Залізо нагальною загрозою самому своєму існуванню — не лише через постійні прикордонні набіги, а й через викрадення спадкової принцеси Айронфорджа Мойри Бронзбірд.",["faction:Horde"]="Орда запекло б'ється з військами Темного Заліза в Пустищах і Палаючих Степах — обидві сторони прагнуть панувати над руїнами довкола Шпиля Блекрок.",["profession:Blacksmithing"]="Ковалі Темного Заліза — неперевершені майстри вогняної металургії; їхні особливі ковадла й горни Темного Заліза глибоко в Глибинах Блекрок потрібні, щоб викувати легендарну зброю.",["race:Dwarf"]="Для Бронзбірда дворфи Темного Заліза — споконвічні зрадники й чаклуни, чиї давні образи досі загрожують кордонам Айронфорджа від Лох Модану до Дун Мороґу.",["race:Gnome"]="Присутність Посла Темного Заліза глибоко в занепалому Гномреґані викликає підозри щодо причетності клану до його падіння."},sec={{t="Війна Трьох Молотів",b="Давним-давно три угруповання дворфів жили разом в Айронфорджі під владою Верховного Короля Модимуса Анвілмара. Коли король помер, спалахнула громадянська війна. Бронзбірди здолали обох суперників, вигнавши і Вайлдгаммерів, і Темне Залізо тана-чаклуна Тауріссана. Поклявшись помститися, Тауріссан заснував поселення в Горах Редріджу, а його дружина-чаклунка Моґґуд повела військо на Ґрім Батол. Коли обидва наступи провалилися й об'єднані війська Бронзбірдів і Вайлдгаммерів рушили на його твердиню, Тауріссан, рятуючись, спробував вивільнити апокаліптичну підземну сутність. Його обряд пробив серцевину світу й звільнив Рагнароса, Володаря вогню."},{t="Розколоті землі й неволя",b="Відродження Рагнароса жорстоко розтрощило навколишні вершини й вирізьбило палаючу кальдеру Гори Блекрок, обрамлену Палючою Ущелиною й Палаючими Степами. Тан-чаклун загинув у катаклізмі, а вцілілі дворфи Темного Заліза опинилися у вічному рабстві в Володаря вогню. Століттями в нижніх залах гори вони будували розлогу підземну столицю — Місто Тінькузні. Їхні майстри й чаклуни стали знавцями кам'яних големів, темного чаклунства й парових облогових машин і обертали розплавлені стихії довкола на зброю під пильним оком вогненних вартових і володарів стихій."},{t="Тінь, що шириться",b="У 25 році після відкриття Темного Порталу Імператор Даґран Тауріссан править кланом зі свого Імператорського Престолу глибоко в Глибинах Блекрок. Потай плануючи скинути Рагнароса, об'єднавши сили всіх дворфських земель, Тауріссан тим часом виконує накази Володаря вогню й готується до тотальної війни. Лазутчики й загони Темного Заліза завдають ударів далеко від своєї гори, вдираючись у Лох Модан, Дун Мороґ, Пустища й Багнокрай. Їхні сили й навіть посол є в Гномреґані, хоча яку саме роль вони відіграли в його падінні, незрозуміло."},{t="Викрадена принцеса",b="Напруга сягнула межі, коли Принцесу Мойру Бронзбірд, доньку й єдину спадкоємицю Короля Маґні, викрали агенти Темного Заліза дорогою до Лейкширу. Маґні вірить, що його доньку зачарували й тримають заручницею проти її волі в Глибинах Блекрок. Чутки, що просочуються з Міста Тінькузні, малюють куди складнішу картину: принцеса стала нареченою імператора й посіла владне місце серед тих самих дворфів, яких зневажає її батько."}},faq={{q="Де столиця Темного Заліза?",a="Їхня столиця — Місто Тінькузні, вирубане глибоко в підземних печерах Глибин Блекрок під Горою Блекрок. Тут височіють величезні кам'яні споруди, є зали Сенату, казарми й Імперський Престол.",al={"де живе темне залізо","дім темного заліза","назва столиці темного заліза","розташування тіньової кузні"}},{q="Чому дворфи Темного Заліза мають темну шкіру й очі, що світяться?",a="У дворфів Темного Заліза попелясто-сіра або темна шкіра й червоні очі, що світяться. Вони живуть під Горою Блекрок, але точна причина такого вигляду не встановлена.",al={"чому темне залізо виглядає інакше","зовнішність дворфів темного заліза","чому вони попелясті"}},{q="Хто такий Імператор Даґран Тауріссан?",a="Імператор Даґран Тауріссан — прямий нащадок першого Чаклуна-Тана Тауріссана. Він править кланом Темного Заліза з Глибин Блекрок і підкоряється безпосередньо повелителю стихій Рагнаросу, хоча потай мріє вирватися з-під ярма Володаря вогню.",al={"даґран тауріссан","хто очолює темне залізо","король темного заліза"}},{q="Навіщо клан Темного Заліза викликав Рагнароса?",a="Під час Війни Трьох Молотів Чаклун-Тан Тауріссан опинився перед неминучою поразкою, коли об'єднані війська Айронфорджа й Ґрім Батолу рушили на його місто. Відчайдушно шукаючи зброю проти ворогів, він провів прадавній ритуал, що випадково вивільнив сплячого Володаря вогню, розтрощив гори й поневолив його народ.",al={"як викликали рагнароса","тауріссан викликав рагнароса","чому викликали вогненного володаря"}},{q="Що таке Братство Торію?",a="Братство Торію — відколоте угруповання ремісників Темного Заліза, які відійшли від клану й влади Володаря вогню. Маючи осідок на Торієвому Мисі в Палючій Ущелині, вони торгують із чужинцями й шукають власної долі, чим заробили вічну ворожнечу колишніх родичів.",al={"братство торію темне залізо","чи братство торію це темне залізо","дружні дворфи темного заліза"}},{q="Чому дворфи Темного Заліза б'ються в Гномреґані?",a="У занепалому Гномреґані можна натрапити на загони Темного Заліза, зокрема на Посла Темного Заліза. Їхня присутність натякає на зв'язок із Сікко Термаплаґом, але яку саме роль вони відіграли в катастрофі — неясно.",al={"темне залізо в гномреґані","посол темного заліза в гномреґані","чому темне залізо з троггами"}},{q="Чи Темне Залізо в союзі з орками Блекрок?",a="Ні. Колись вони терпіли Стару Орду у верхньому шпилі, але тепер Темне Залізо й орки Блекрок з верхніх рівнів ведуть запеклу війну за територію. Темне Залізо тримає глибини, а орки Ренда Блекгенда — верхню цитадель.",al={"союз темного заліза з орками","темне залізо проти блекрок","хто володіє чорною горою"}},{q="Чому Темне Залізо напало на Ґрім Батол?",a="Під час Війни Трьох Молотів Чаклунка Модґуд повела військо Темного Заліза, щоб знищити клан Вайлдгаммерів у Ґрім Батолі. Хоча Модґуд загинула від руки Хардроса Вайлдгаммера, її мерзенні чари так глибоко прокляли фортецю, що Вайлдгаммери вже ніколи не змогли там жити.",al={"модґуд ґрім батол","чому ґрім батол покинули","прокляття ґрім батола"}}},fp="14,398,28.659.0,27.655.0,16.538.1,19.449.1,39.218.0,61.166.0,33.269.0,43.340.0,32.276.0,49.203.0,50.245.0,41.270.0"}
P.entries["topic:dark-iron-dwarf"] = {n="Дворфи Темного Заліза",s="Дворфи Темного Заліза — окрема гілка дворфів, яку вирізняють попеляста шкіра, палаючі червоні очі й вроджена спорідненість із вогнем. Вигнані з Айронфорджа після громадянської Війни Трьох Молотів, вони живуть глибоко в Горі Блекрок, де їхнє суспільство потрапило під тиранічну владу Володаря вогню, Рагнароса.",h="Дворфи Темного Заліза — окрема гілка дворфів, яку вирізняють попеляста шкіра, палаючі червоні очі й вроджена...",kw={"дворфи темного заліза","рагнарос","місто тінькузні","братство торію","коло закону","гора блекрок"},ang={["faction:Alliance"]="Розвідники Альянсу насторожено стежать за Темним Залізом, вважаючи його імперські війська агресивною загарбницькою загрозою просто біля південних воріт володінь Айронфорджа.",["faction:Horde"]="Орда вважає Темне Залізо небезпечними фанатиками, що засіли в Горі Блекрок і прямо загрожують шляхам постачання Орди через Пустища й сусідні перевали.",["profession:Blacksmithing"]="Майстри Темного Заліза — легендарні ковалі, що мають виключну майстерність роботи з рудою Темного Заліза, яку можна розплавити й обробити лише в пекучому жарі Чорної Кузні Гори Блекрок.",["race:Dwarf"]="Для дворфів Бронзбірд з Айронфорджа Темне Залізо — давня родинна ворожнеча, що переросла в загрозу самому існуванню й тягнеться від кривавого заколоту часів Війни Трьох Молотів."},sec={{t="Вогняна спадщина й вигнання",b="На відміну від своїх родичів — Бронзбірдів і Вайлдгаммерів, — дворфи Темного Заліза мають темно-сіру чи чорну, мов сажа, шкіру й очі, що горять, мов жарини. Їхня історія розкололася під час Війни Трьох Молотів, коли їхній тан-чаклун Тауріссан прагнув підкорити Айронфордж. Розбитий і вигнаний на південь, до Гір Редріджу, Тауріссан спробував викликати темні сили, щоб помститися за поразку, і ненароком випустив Рагнароса, Володаря вогню, з Царства Стихій. Катастрофічне викликання розтрощило навколишні вершини, обернувши їх на вулканічне пустище Гори Блекрок, і прикувало народ Темного Заліза до вогняного рабства."},{t="У тіні Володаря вогню",b="Життя в глибокому підземному Місті Тінькузні — жорстоке й безжальне. Колись дворфи Темного Заліза були просто честолюбними й хитрими, але покоління під Горою Блекрок у гнітючій аурі Рагнароса спотворили значну частину їхньої культури на жорстокість, параною й тиранію. Закон Темного Заліза знає лише один вирок за провини — суд двобоєм у безжальному Колі Закону. Отруєння й політичні інтриги настільки поширені, що мандрівники Темного Заліза за звичаєм носять власні харчі, а не довіряють їжі чужинців."},{t="Відколоті й вигнанці",b="Не всі дворфи Темного Заліза служать Імператорові Даґрану Тауріссану й культу Рагнароса. Угруповання незгодних відкололися, щоб іти власним шляхом. Найпомітніше серед них — Братство Торію, гільдія майстрів-ковалів із Торієвого Мису в Палючій Ущелині, які відкололися від головного клану й наймають сторонніх шукачів пригод проти колишніх господарів. Інші працюють найманцями, шпигунами чи торговими інженерами разом із нейтральними організаціями на кшталт Венчурної Компанії."}},faq={{q="Чому в дворфів Темного Заліза сіра шкіра й червоні очі?",a="Темно-сіра шкіра й вогненні червоні очі, що світяться, — природні риси, які відрізняють їх від гірських і горбових дворфів. Життя глибоко під землею й століття поруч зі стихійним вогнем Рагнароса ще більше підкреслили їхню вулканічну природу.",al={"зовнішність темного заліза","чому темне залізо так виглядає","червоні очі темного заліза"}},{q="Чи всі дворфи Темного Заліза злі?",a="Не обов'язково. Хоча імперське суспільство Темного Заліза підступне й кориться волі Рагнароса, історичні постаті, як-от легендарний зодчий Франклорн Форджрайт, і такі угруповання, як бунтівне Братство Торію, виявляють честь, звитягу й власну волю, вільну від спотворення Володаря вогню.",al={"чи всі темне залізо погані","добрі дворфи темного заліза","чи можуть бути добрими"}},{q="Де столиця дворфів Темного Заліза?",a="Осердя їхньої цивілізації — Місто Тінькузні, глибоко в підземних печерах Глибин Блекрок у Горі Блекрок. Звідти Імператор Даґран Тауріссан наглядає за своєю імперією в тіні Розплавленого Ядра.",al={"столиця темного заліза","де живе темне залізо","місто темного заліза"}},{q="Що таке Коло Закону?",a="Коло Закону — арена, де вершиться правосуддя Темного Заліза. У їхньому суспільстві за злочини проти клану карають смертю. Обвинувачених змушують сплатити кров'ю, б'ючись із хвилями лютих звірів і гладіаторів, — це випробування майже ніхто з в'язнів не переживає.",al={"коло закону","арена темного заліза","суд тіньової кузні"}},{q="Що таке Братство Торію?",a="Братство Торію — відступницьке угруповання ремісників Темного Заліза, які полишили службу Рагнаросу. Отаборившись на Торієвому Мисі в Палючій Ущелині, вони діляться неперевершеними знаннями вогняної металургії й секретами ковальства Темного Заліза з шукачами пригод, готовими підточувати імперський клан.",al={"лор братства торію","хто братство торію","дворфи торієвого мису"}}},fp="15,328,24.618.0,27.536.0,22.482.0,53.271.0,31.303.0,46.226.0,28.293.0,32.295.0"}
P.entries["topic:darkspear-tribe"] = {n="Плем'я Темного Списа",s="Темний Спис — плем'я тролів джунглів, що приєдналося до Орди Тралла, коли його вигнали з прадідівської домівки в Долині Стренглторну, а Тралл урятував його від морської відьми у Великому морі. Під проводом Тіньового Мисливця Вол'джина з тимчасового притулку в Селі Сен'джин вони нині становлять основу Орди в Калімдорі й Східних Королівствах. Та попри союз, вони досі борються за те, щоб відвоювати свою нову домівку, Острови Відлуння, у зрадника-знахаря Залазана.",h="Темний Спис — плем'я тролів джунглів, що приєдналося до Орди Тралла, коли його вигнали з прадідівської...",kw={"темний спис","тролі","вол'джин","тралл","острови відлуння","залазан","село сен'джин","орда"},ang={["class:Shaman"]="Шамани Темного Списа поєднують давнє поклоніння первісним духам-лоа зі стихійними вченнями, перейнятими від союзників-орків і тауренів, а такі постаті, як Дже'ню Санкреа, представляють плем'я в Земляному Кільці.",["faction:Horde"]="Від вершників на кажанах, що боронять небо, до травників, що варять зілля в Горах Кам'яного Кігтя, — Темний Спис приносить містичну хитрість і потайність, які врівноважують неприборкану бойову міць Орди.",["race:Orc"]="Зв'язок між орками й тролями викувано в крові Третьої війни. Тралл вважає Вол'джина своїм найближчим побратимом, а розвідники й знахарі Темного Списа вірно служать пліч-о-пліч із войовничими кланами Дуротару.",["race:Troll"]="Як троль Темного Списа, ви несете важкий тягар народу-вигнанця, що відбудовується на чужих берегах. Кожен удар по Залазанові на Островах Відлуння чи по лютих родичах-ґурубаші в Долині Стренглторну допомагає вашому племені вижити."},sec={{t="Вигнання й порятунок",b="Колись Темний Спис був меншим і не таким жорстоким племенем у розколотій Імперії Ґурубаші в Долині Стренглторну. Століттями він терпів війни й голод у протистоянні з лютими сусідами — племенами Кривавих Скальпів і Череполомів. Вигнані в море, тролі оселилися на далеких островах, але й там зіткнулися з мурлоками, мореплавцями з Кул Тірасу й морською відьмою-нагою Зар'джірою. Їхнього старого вождя Сен'джина схопили й принесли в жертву в темних обрядах під водою, але перед смертю він провістив, що орк, Вождь Тралл, поведе Темний Спис до нової долі. Флот Тралла, що пропливав повз, урятував уцілілих, і вони присягнули новій Орді на вічну вірність і відпливли на захід, до Калімдору."},{t="Падіння Островів Відлуння",b="Діставшись Дуротару, Темний Спис облаштував домівку на тропічних Островах Відлуння біля самого узбережжя. Та спокій тривав недовго. Спершу флот адмірала Дейліна Праудмура тимчасово витіснив їх у трясовини Багна Пилоброду, доки сили Орди не знищили загарбників. А тоді прийшла ще гірша зрада — зсередини. Знаний знахар на ім'я Залазан вдався до викривленого вуду й підкорив собі розум родичів. Щоб уберегти вільних одноплемінників, син і наступник Сен'джина, Вол'джин, наказав знову евакуюватися. Нині Темний Спис живе в прибережному таборі — Селі Сен'джин — і посилає поборників через воду, щоб убити Залазана й визволити поневолених братів."},{t="Вуду й нова Орда",b="На відміну від своїх родичів-людожерів із джунглів, Темний Спис швидко перейняв Ордині цінності честі й заснував поселення — Малака'джин у Горах Кам'яного Кігтя, Село Тіньової Здобичі в Пустограї та Заставу Зорам'гар в Ашенвалі. В Оргріммарі їхня духовна домівка — Долина Духів, де тіньові мисливці й знахарі спілкуються з лоа. Їх шанують за розвідників, вершників на кажанах і могутні прокльони, але давні звичаї вкорінені глибоко: деякі старовинні обряди, на які союзники дивляться косо, досі тихцем справляють у темряві."}},faq={{q="Чому тролі Темного Списа в Орді?",a="Під час Третьої війни флот Вождя Тралла сховався від лютої бурі на островах Темного Списа. Коли морська відьма наг Зар'джира та її мурлоки полонили і тролів, і орків, Тралл звільнив їх. Вождь Сен'джин загинув під час утечі, але в передсмертному видінні побачив, як Тралл виводить Темний Спис у безпечне місце. На знак вдячності син Сен'джина Вол'джин присягнув Орді у вірності свого племені.",al={"чому тролі темного списа в орді","темний спис тралл походження","як тролі приєднались до орди"}},{q="Хто зараз очолює плем'я Темного Списа?",a="Плем'я очолює Вол'джин, син шанованого загиблого вождя Сен'джина. Вол'джин — хитрий мисливець тіней і один із найближчих, найдовіреніших радників Вождя Тралла. Він радить Орді з Долини Духів в Оргріммарі й керує боротьбою за повернення Островів Відлуння.",al={"лідер темного списа","хто вождь тролів","ватажок тролів"}},{q="Чому Темний Спис живе в Селі Сен'джин, а не на Островах Відлуння?",a="Острови Відлуння мали стати постійним притулком племені в Дуротарі, але плем'я зрадили зсередини. Збожеволілий від жаги влади знахар Залазан темною магією поневолив розум своїх одноплемінників. Щоб не різати своїх зачарованих родичів, Вол'джин наказав вільним тролям Темного Списа відступити на материковий берег і заснувати Село Сен'джин як базу для відсічі.",al={"чому темний спис у сен'джині","що сталося з островами відлуння","чому острови відлуння ворожі"}},{q="Звідки походить Темний Спис?",a="Темний Спис походить із джунглів Долини Стренглторну, де був частиною розколотої імперії Ґурубаші. Нечисленніші й не такі безжальні, як племена-суперники, як-от Кривавий Скальп і Череполоми, вони терпіли безкінечні війни й голод, доки їх зовсім не витіснили зі Східних Королівств.",al={"де походить темний спис","первісний дім темного списа","темний спис стренґлторн"}},{q="Чи тролі Темного Списа досі практикують канібалізм?",a="Офіційно ні. Щоб жити в злагоді з Ордою Тралла й шанувати союз, Темний Спис зрікся канібалізму й полювання за головами як звичаю племені. Проте столітня спадщина джунглів не зникає за одну ніч, і досі пошепки кажуть, що темніші давні обряди потай справляють подалі від цікавих очей.",al={"чи темний спис канібали","троллячий канібалізм","чи тролі орди їдять людей"}},{q="Яким божествам поклоняється Темний Спис?",a="Темний Спис шанує лоа — могутніх первісних духів і богів-звірів. Їхня віра охоплює великий пантеон, який вшановують обрядами вуду знахарі й мисливці тіней.",al={"релігія темного списа","боги темного списа","лоа тролів"}}},fp="15,479,19.685.0,26.687.1,24.559.0,42.400.0,40.289.0,71.376.0,45.301.0,47.315.0,38.190.0"}
P.entries["topic:defias-brotherhood"] = {n="Братство Дефіас",s="Братство Дефіас — розгалужена злочинна мережа бандитів, розбійників і вбивць, що веде підпільний заколот проти королівства Стормвінд. Спершу його утворили майстри Гільдії Каменярів, яких ошукали з платою за відбудову столиці, але згодом вони скотилися до лютих розбійників, що тероризують південні ферми. Зі своєї прихованої твердині глибоко під Вестфолом вони прагнуть скинути продажний Дім Вельмож і сплюндрувати королівство.",h="Братство Дефіас — розгалужена злочинна мережа бандитів, розбійників і вбивць, що веде підпільний заколот...",kw={"братство дефіас","едвін венкліф","гільдія каменярів","вестфол","мертві копальні","дім вельмож"},ang={["class:Paladin"]="Лицарі Срібної Длані та провідники церкви на кшталт Дуторіана Ралла закликають паладинів боронити беззахисних поселенців на кшталт Дафни Стілвелл від безжальних розбійників Дефіас у Вестфолі.",["class:Rogue"]="Майстер Матіас Шоу й SI:7 пильно стежать за Дефіас, адже посланці Венкліфа не поступаються королівським розвідникам ні в зламуванні замків, ні в потайності, ні в смертоносних підземних засідках.",["faction:Alliance"]="Заколот загрожує стабільності всього королівства: він душить постачання зерна з Вестфолу, розхитує золоті копальні й підточує віру людей у провід Стормвінда.",["race:Human"]="Для людей королівства Дефіас — гірке нагадування про внутрішню гниль Стормвінда: трагедія, у якій чесних будівничих міста аристократична жадібність перетворила на головорізів."},sec={{t="Від каменярів до грабіжників",b="Після Другої війни Гільдію Каменярів найняли відбудувати Стормвінд — із димучих руїн у величну кам'яну столицю. Коли шедевр завершили, Дім Вельмож відмовився виплатити обіцяне, посилаючись на непосильні воєнні борги. Голова гільдії Едвін Венкліф заступився за своїх робітників і вимагав справедливої платні, але вельможі відповіли наказом розпустити Гільдію Каменярів. Заворушення на вулицях міста обернулися трагедією: випадковий камінь влучив у Королеву Тіффін Рінн і вбив її. Охоплений горем і люттю, Король Варіан Рінн вигнав робітників зі Стормвінда. Позбавлені заробітку й оголошені поза законом, Венкліф і зневірені робітники згуртувалися, пов'язали обличчя червоним шовком на знак крові скривджених і взялися грабувати на дорогах, щоб забрати те, що, як вони вважали, їм належить."},{t="Тінь над Вестфолом",b="Поки королівське військо було розпорошене, Венкліф перетворив занедбані ферми Вестфолу на базу Братства. Бандити захопили село Мунбрук і заволоділи покинутими підземними тунелями Мертвих Копалень. Агенти Дефіас захопили місцеві шахти, вигнали фермерів із садиб перепрограмованими жнивними големами й посолили землю, щоб заморити край голодом. Коли Корона не змогла чи не захотіла послати вояків на захист сільських мешканців, місцеві фермери утворили на Сентінел Гілл Народне ополчення й ведуть відчайдушну війну на виснаження з ворогом, що тепер переважає їх і числом, і зброєю."},{t="Павутина змов",b="Братство давно переросло просту ватагу вигнаних робітників. Венкліф найняв гоблінів-найманців наглядати за озброєнням, уклав союзи з гнолами Річколапів і кобольдами Елвінна й торгує з головорізами-піратами на кшталт Буканірів Кривавого Вітрила. Розбійники Дефіас грабують перевезення золота по всьому Лісу Елвінн, а їхні агенти навіть закріпилися в Сутінколіссі, де викопали проклятий артефакт у Погибелі Роланда. Та найгірше — вплив Братства сягає самого серця столиці: воно тішиться таємною підтримкою підступних аристократів у Домі Вельмож і влаштовує викрадення, що б'ють по найвищих посадах Альянсу."},{t="Джаґернаут у Мертвих Копальнях",b="Під Мунбруком лежить Бухта Айронклад, де гобліни-інженери Венкліфа потай складають величезний закутий у залізо бойовий корабель — Джаґернаут Дефіас. Голова гільдії хоче вивести цю плавучу фортецю підземними прибережними протоками й обстріляти Стормвінд із моря, обернувши на уламки власну величну архітектуру. Змова сягає й королівського двору: продажні вельможі на кшталт Лорда Ґреґора Лесковара служать заколотникам очима й вухами, а придворні інтриги Леді Катрани Престор навмисно тримають королівство розколотим і сліпим до флоту, що росте під Вестфолом."}},faq={{q="Чому Дефіас носять червоні хустки?",a="Червону шовкову хустку обрали Едвін Венкліф і вигнані каменярі як символ непокори. Вона уособлює кров пригнобленого робочого люду, який відбудував Стормвінд, а натомість дістав від знаті порушені обіцянки, насильство й вигнання.",al={"що означають маски дефіасу","чому червоний шовк","значення червоних хусток"}},{q="Чому Братство нападає на невинних фермерів, а не на вельмож?",a="Хоча Братство постало зі справжніх кривд, завданих знаттю, роки беззаконного вигнання перетворили його на жорстоку злочинну імперію. Відчай, жадібність і набір безжальних головорізів і гоблінів обернули його до грабунку місцевих господарств, палення врожаїв і захоплення копалень, щоб годувати свою воєнну машину.",al={"чому дефіас нападає на фермерів","чому шкодять вестфоллу","мотиви дефіасу"}},{q="Хто такий Едвін Венкліф?",a="Едвін Венкліф — геніальний голова Гільдії Каменярів, який керував відбудовою Стормвінда після Другої війни. Навчений скрадатися й діяти підступом, він заснував Братство Дефіас, коли Дім Вельмож відмовився платити робітникам. Тепер він керує справами Братства з глибин Мертвих Копалень.",al={"хто такий венкліф","едвін венкліф лор","лідер дефіасу"}},{q="Чому Стормвінд не посилає військо проти Дефіас?",a="Скарбниця королівства виснажена, а військо Стормвінда розпорошене по гарнізонах у далеких краях, як-от Стренглторн. Політичний глухий кут у Домі Вельмож ще більше паралізує трон, тож сільські Вестфол і Сутінколісся мусять захищатися самі силами добровольців.",al={"де армія стормвінда","чому немає вартових у вестфоллі","чому народне ополчення"}},{q="Що таке Народне ополчення?",a="Народне ополчення — добровольча самооборона, яку організували Ґраян Стаутмантл і змучені фермери Сентінел Гілла. Оскільки Стормвінд майже не дав вояків, щоб вибити Дефіас із Вестфолу, місцеві взялися за зброю, щоб боронити власну землю.",al={"народне ополчення вестфолл","ґріан стаутмантл ополчення","армія сентінел гілла"}},{q="Що Дефіас будують у Мертвих Копальнях?",a="У підземній печері, відомій як Бухта Айронклад, гобліни-інженери й майстри-відступники будують Джаґернаут Дефіас — величезну броньовану бойову галеру. Венкліф хоче привести цей корабель у Гавань Стормвінда й зрівняти столицю з землею.",al={"корабель мертвих копалень","що будує дефіас у мертвих копальнях","джаґернот дефіасу"}},{q="Чи мали Дефіас якийсь стосунок до зникнення короля?",a="Що сталося з королем Варіаном Рінном, лишається загадкою. Він зник дорогою на мирні переговори в Терамор, і на троні лишився малий Андуїн під опікою регента.",al={"чи дефіас викрав варіана","зниклий король дефіас","зниклий дипломат дефіас"}}},fp="18,480,24.860.0,24.622.0,21.670.1,33.630.2,36.256.0,68.328.0,22.332.0,60.306.2,29.267.0,50.264.1,66.169.2"}
P.entries["topic:druid"] = {n="Друїд",s="Друїди — охоронці природи, що черпають силу безпосередньо з диких духів, небесних світил і Смарагдового Сну. Майстри зміни подоби, вони набувають вигляду первісних звірів, щоб захищати землю чи загоювати тяжкі рани. Друїдство плекають переважно нічні ельфи, а нещодавно його відродили таурени; друїди ставлять збереження природи понад будь-яку вірність смертним.",h="Друїди — охоронці природи, що черпають силу безпосередньо з диких духів, небесних світил і Смарагдового Сну.",kw={"друїд","зміна подоби","коло кенарія","кенарій","смарагдовий сон","малфуріон стормрейдж"},ang={["class:Druid"]="Як охоронець рівноваги, друїд іде тонкою межею між звіриною люттю, цілющою магією життя й небесною руйнівною силою, черпаючи мудрість безпосередньо від Кенарія й зі Смарагдового Сну.",["race:NightElf"]="Десять тисячоліть друїди-калдореї були тихими сплячими охоронцями Калімдору, що берегли рівновагу природи під проводом Малфуріона Стормрейджа й напівбога Кенарія.",["race:Tauren"]="Під проводом Верховного Друїда Гамуула Рунтотема таурени відновили давній зв'язок із дикою природою й приєдналися до Кола Кенарія у священному Місячному Гаю, щоб іти шляхом Земної Матері."},sec={{t="Охоронці дикої природи",b="Друїдство — значно більше, ніж бойове мистецтво: це давній спосіб життя, вкорінений у глибокому єднанні з природою й напівбогом Кенарієм. Друїди орудують сирою силою природи: велять корінню обплутувати ворогів, спрямовують небесне сяйво місяця й зірок і закликають цілющі рослини, щоб зрощувати кістки й плоть. Їхній обов'язок — берегти космічну рівновагу й захищати вільну дику природу від визиску й порчі."},{t="Дар зміни подоби",b="Головна прикмета друїда — надприродне мистецтво зміни подоби. Завдяки духовній відданості друїди спрямовують у себе первісну сутність звірів Азероту. Вони набувають товстої шкури ведмедя, щоб витримувати нищівні удари, прослизають у гнучку подобу хижого кота, щоб нападати з тіні, або приймають водяну й пташину подоби, щоб долати моря й небо. У звіриній подобі їхні пащі рідко можуть вимовити слова смертних, зате фізичною силою вони не поступаються верховним хижакам дикої природи."},{t="Коло Кенарія",b="Десять тисяч років тому Кенарій уперше навчив друїдства Малфуріона Стормрейджа, а згодом смертне друїдство впорядкувало Коло Кенарія. Зі свого осідку у священному Місячному Гаю Коло наглядає за друїдськими практиками по всьому Калімдору, лишаючись незалежним від фракцій смертних і політичних чвар. Довгий час у ньому переважали лише чоловіки нічних ельфів, що століттями спали в Смарагдовому Сні, але після Третьої війни до його лав прийняли і жінок нічних ельфів, і тауренів."}},faq={{q="Хто був першим смертним друїдом?",a="Малфуріон Стормрейдж першим зі смертних опанував друїдські мистецтва під безпосереднім наставництвом напівбога Кенарія — приблизно десять тисяч років тому, ще до Війни Прадавніх.",al={"перший друїд","хто заснував друїдизм","малфуріон перший друїд"}},{q="Як таурени можуть ставати друїдами?",a="Після Третьої війни провідник тауренів Гамуул Рунтотем заприятелював із Малфуріоном Стормрейджем і навчився шляхів дикої природи, ставши першим за майже двадцять поколінь тауреном-друїдом. Попри заперечення Фандрала Стаґгелма, Хранитель Ремулос прийняв тауренів до Кола Кенарія.",al={"лор тавренів-друїдів","чому таурени друїди","хамуул рунототем друїд"}},{q="Що таке Коло Кенарія?",a="Коло Кенарія — провідний орден друїдів Азероту, заснований, щоб упорядковувати дикі практики й захищати природу. Воно не залежить ні від Альянсу, ні від Орди: його члени підкоряються архідруїдам Кола й мирно збираються в священному Місячному Гаю.",al={"лор кола кенарія","що за орден місячної поляни"}},{q="Чи можуть друїди говорити в подобі звіра?",a="Зазвичай ні. Коли друїд перекидається на звіра, його голосові органи стають звірячими, тож звичайна мова смертних неможлива, хоча жменька рідкісних, надзвичайно могутніх друїдів знайшла магічні способи обійти це обмеження.",al={"чи можуть друїди говорити в формі ведмедя","розмова в зміненій подобі"}},{q="Що таке Смарагдовий Сон?",a="Смарагдовий Сон — зелене, незаймане царство, що віддзеркалює Азерот таким, яким він був би без жодного дотику цивілізації. Друїди нічних ельфів здавна поринали в багатовікову сплячку, щоб блукати його стежками й спілкуватися з духами природи.",al={"лор смарагдового сну","де сплять друїди"}},{q="Чому друїди колись спали століттями?",a="Отримавши благословення Світового Дерева Нордрассіл, друїди нічних ельфів спускалися в Курганні Лігва, щоб століттями блукати Смарагдовим Сном і допомагати зеленій драконячому роду Ізери плекати духовну рівновагу Азероту, доки Третя війна не змусила їх прокинутися.",al={"сплячка друїдів","курганні лігва сплять","довгий сон"}}},fp="5,382,20.432.0,25.508.0,19.487.0,31.183.0,29.291.0,28.270.0,38.242.0,26.232.0,50.252.0"}
P.entries["topic:druids-of-the-fang"] = {n="Друїди Ікла",s="Друїди Ікла — відколоте угруповання друїдів — нічних ельфів, що піддалися порчі глибоко в Печерах Стогонів. Колись учні далекоглядного Верховного Друїда Наралекса, вони покинули Коло Кенарія після того, як зв'язок їхнього наставника зі Смарагдовим Сном обернувся мерзенним жахіттям. Під проводом самопроголошеного Лорда Серпентіса вони тепер набувають зміїної подоби й прагнуть переробити Пустки на свій спотворений рай.",h="Друїди Ікла — відколоте угруповання друїдів — нічних ельфів, що піддалися порчі глибоко в Печерах Стогонів.",kw={"друїди ікла","наралекс","лорд серпентіс","печери стогонів","жахіття","пустки"},ang={["class:Druid"]="Друїди Ікла показують, яка тяжка небезпека чатує, коли Смарагдовий Сон спотворено, — і що буває, коли друїд зрікається гармонії Кенарія заради спотворених, нестандартних звіриних подоб.",["race:NightElf"]="Бачити, як брати-калдореї в самому серці Калімдору вироджуються в дикий зміїний культ, охоплений жахіттям, — гірке горе й ганьба для традицій нічних ельфів.",["race:Tauren"]="Верховний Друїд Гамуул Рунтотем і друїди-таурени Тандер Блафа щиро прагнуть покласти край загрозі Ікла, бо вважають осквернення вод Пусток образою Земної Матері."},sec={{t="Шляхетне бачення, що обернулося отрутою",b="Пустки не завжди були посушливим пустищем, і Верховний Друїд Наралекс прагнув повернути їм пишну, зелену красу, якою вони колись були. Наралекс повів відданий орден молодих друїдів у підземні глибини Печер Стогонів, щоб зачерпнути сили з природних підземних розломів і джерел. Поринувши у викликаний сон, Наралекс сподівався спрямувати живі енергії Смарагдового Сну у водні потоки й повернути спалену саванну нагорі до буйного життя."},{t="Падіння в жахіття",b="Під час трансу Наралекса щось пішло страшенно не так. Замість чистого спокою Смарагдового Сну в його сон проникло зловісне, викривлене жахіття. Ця темрява просочилася печерами, швидко спотворюючи місцевих звірів і отруюючи підземні джерела. Замість утекти по допомогу до Кола Кенарія, учні Наралекса піддалися впливу жахіття, і їхні розуми й душі змінювалися разом із підземним світом."},{t="Піднесення Ікла",b="Найкращий учень Наралекса, колись відданий послідовник, відкинув первісне вчення наставника й прийняв порчу під іменем Лорда Серпентіса. Згуртувавши занепалих учнів у Друїдів Ікла, Серпентіс узяв первісну, отруйну подобу гадюк і змій замість традиційних подоб ведмедя й кота, освячених Кенарієм. Культ фактично ув'язнив свого сплячого Верховного Друїда, маючи намір живитися його жахіттям, щоб силоміць переробити Пустки на свій рай, де панують змії."}},faq={{q="Хто такі Друїди Ікла?",a="Це спотворений орден друїдів нічних ельфів, що увійшли в Печери Стогонів під проводом Архідруїда Наралекса. Замість зцілити Пустки вони збожеволіли, коли транс Наралекса торкнувся темного жахіття, і перетворилися на фанатичних відступників, що поклоняються зміям.",al={"лор друїдів ікла","хто такі друїди ікла","друїди печер стогонів"}},{q="Навіщо вони спочатку увійшли в Печери Стогонів?",a="Наралекс і його учні хотіли скористатися багатими підземними джерелами печер. Спрямувавши в ці води буйну життєву силу Смарагдового Сну, вони сподівалися знову перетворити посушливі Пустки на квітучий зелений ліс.",al={"чому вони в печерах стогонів","мета наралекса","чому зцілити пустовиська"}},{q="Хто очолює Друїдів Ікла?",a="Їх очолює Лорд Серпентіс. Колись найкращий і найздібніший учень Архідруїда Наралекса, Серпентіс цілком поринув у безумство, коли вдарило жахіття, і проголосив себе ватажком новоствореного ордену Друїдів Ікла.",al={"лідер друїдів ікла","лор лорда серпентіса","хто їх очолює"}},{q="Яку звірячу подобу вони приймають?",a="На відміну від звичайних друїдів Кола Кенарія, що перекидаються на ведмедів, котів чи грозових круків, Друїди Ікла черпають силу в отруйних зміях і гадюках, вдаючись до зміїної магії й лютих зміїних перевтілень.",al={"змієва подоба друїдів","зміна подоби друїдів ікла","подоба змія"}},{q="Як до них ставиться Коло Кенарія?",a="Коло Кенарія вважає Друїдів Ікла небезпечним збоченням і культом. Провідники, як-от Архідруїд Гамуул Рунтотем, і вірні учні Наралекса, що лишилися, поспішають знищити ватажків Ікла й очистити спотворення, поки воно не занапастило край.",al={"думка кола кенарія","чи вони частина кола кенарія","хамуул про ікла"}},{q="Що сталося з Наралексом?",a="Наралекс досі лежить у глибокому, болісному сні в самому серці Печер Стогонів. Учні тримають його там і черпають із його безкінечного жахіття силу, що викривлює печери й їхню власну магію.",al={"чи наралекс мертвий","статус наралекса","де наралекс"}}},fp="18,438,31.478.0,22.515.1,18.522.1,31.269.0,50.231.0,33.224.0,31.222.0,39.267.0,25.215.0"}
P.entries["topic:dwarf"] = {n="Дворф",s="Дворфи — кремезна, витривала раса, що походить від живого каменю давніх, викуваних титанами землян, і нині населяє засніжені гірські королівства Каз Модану й не тільки. Відомі майстерністю в обробці каменю, металургії й нищівному бою на передовій, вони — одна з найзапекліших і найнадійніших опор Альянсу. За правління Короля Маґні Бронзбірда їхня розлога підземна столиця Айронфордж — живе серце дворфського суспільства.",h="Дворфи — кремезна, витривала раса, що походить від живого каменю давніх, викуваних титанами землян, і нині...",kw={"дворфи","айронфордж","каз модан","війна трьох молотів","земляни","маґні бронзбірд"},ang={["class:Paladin"]="Дворфи-паладини несуть Святе Світло з гірською рішучістю, поєднуючи людське богослов'я з незламною бойовою дисципліною Каз Модану.",["faction:Alliance"]="Незліченні мінеральні багатства Айронфорджа, неперевершене облогове ремесло й незламна піхота — північний оплот Альянсу.",["profession:Blacksmithing"]="Дворфи славляться як найкращі ковалі Азероту: вулканічний жар Великої Кузні допомагає їм гартувати легендарну зброю й обладунки.",["profession:Mining"]="Народжені з живого каменю, дворфи мають вроджене чуття на багаті рудні жили й давні самоцвіти, поховані в підземних глибинах.",["race:Dwarf"]="Кожен дворф несе тягар спадщини народжених із каменю: торує шлях крізь давню кровну ворожнечу кланів і відкопує таємниці титанів, що визначають саму вашу сутність.",["race:Gnome"]="Дворфи — ваші найдавніші й найвірніші союзники: вони допомагали зводити перші кам'яні споруди Гномреґана, а тепер дають вашому народові прихисток у Містечку Майстрів."},sec={{t="Сини гори",b="Давним-давно підземні істоти, викувані титанами й відомі як земляни, прокинулися від віковічного сну в сховищах Ульдаману, перетворені Прокляттям Плоті на істот із крові й кісток. Назвавшись дворфами, вони повернули собі високі скелі Каз Модану, названого на честь титана Каз'ґорота, і висікли під вершинами Дун Мороґу величну підземну твердиню Айронфордж. Наділені неймовірною природною витривалістю, гострим оком на камінь і руду та любов'ю до гучних вогнищ і міцного елю, дворфи беруться і до ремесла, і до війни з однаковим завзяттям."},{t="Війна Трьох Молотів",b="Століття тому, після смерті Верховного Короля Модимуса Анвілмара, єдність дворфів розлетілася на друзки. В Айронфорджі спалахнула громадянська війна між трьома суперниками: кланами Бронзбірд, Вайлдгаммер і Темного Заліза. Коли Бронзбірди втримали гору й вигнали родичів, тан-чаклун Темного Заліза Тауріссан розв'язав згубну війну помсти проти обох суперників. Доведений до відчаю під Горами Редріджу, Тауріссан ненароком викликав Рагнароса, Володаря вогню, і спалив власне королівство, перетворивши його на вулканічні пустища Палючої Ущелини й Палаючих Степів. Уцілілих дворфів Темного Заліза поневолили під Горою Блекрок, а спустошені Вайлдгаммери переселилися на північ, до Орлиного Піку в Пригір'ї."},{t="Непохитний щит Альянсу",b="Коли в Другій війні континентом прокотилася Орда орків, Король Маґні Бронзбірд замкнув ворота Айронфорджа перед жорстокими облогами, а дворфські війська взялися до зброї пліч-о-пліч з Альянсом Лордерона. Славетні важкими латами, смертоносними мушкетами й безстрашними вершниками на грифонах, дворфські воїни відіграли ключову роль у розгромі Орди. Сьогодні Королівство Айронфордж лишається одним із найнепохитніших захисників Альянсу: воно приймає у своїх залах вигнаних родичів-гномів і завзято розкопує руїни титанів у Каз Модані, щоб розгадати таємниці свого давнього походження."}},faq={{q="Звідки походять дворфи?",a="Дворфи — нащадки землян, прадавньої раси істот із живого каменю, яких створили хранителі-титани. Замкнені в підземних сховищах Ульдаману, земляни впродовж тисячоліть піддалися Прокляттю Плоті й прокинулися смертними дворфами, що вирушили заселяти гори Каз Модану.",al={"походження дворфів","лор дворфів","як створили дворфів","землян"}},{q="Хто зараз править дворфами?",a="Король Маґні Бронзбірд править Королівством Айронфордж і кланом Бронзбірд від Великої Кузні. Він провів свій народ крізь Другу і Третю війни й лишається однією з головних опор Великого Альянсу.",al={"хто король дворфів","лідер дворфів","король айронфорджа","маґні бронзбірд"}},{q="Які три головні дворфійські клани?",a="Три великі клани — це Бронзбірди, що правлять Айронфорджем і Дун Мороґом; Вайлдгаммери, що живуть просто неба в Пригір'ї й літають на грифонах; і Темне Залізо, що живе глибоко під Горою Блекрок під вогненною владою Рагнароса.",al={"дворфійські клани","три молоти","бронзбірд вайлдгаммер темне залізо","клани айронфорджа"}},{q="Чому дворфи Темного Заліза — вороги?",a="Під час Війни Трьох Молотів Темне Залізо намагалося знищити і клан Бронзбірд, і клан Вайлдгаммер. Опинившись перед поразкою, їхній чаклун-тан викликав Рагнароса, Володаря вогню, що розтрощив їхню батьківщину й прирік клан на служіння стихійному вогню й тіні під Горою Блекрок.",al={"чому темне залізо злі","клан темного заліза лор","дворфи тіньової кузні"}},{q="Чому гноми живуть в Айронфорджі?",a="Дворфів і гномів пов'язує тісна дружба від першої зустрічі століття тому: вони обмінювалися таємницями обробки каменю й механічної інженерії. Коли Гномреґан упав під навалою трогів і від отруйної радіації, король Маґні дав Великому Тінкерові Ґелбіну Меккаторку та його біженцям притулок у Містечку Майстрів.",al={"чому гноми в айронфорджі","гноми айронфорджа","що сталося з гномреґаном"}},{q="Чи шанують дворфи Святе Світло?",a="Так. Перші людські експедиції з імперії Аратор століття тому принесли дворфам філософію Святого Світла. Дворфи щиро її прийняли й заснували ордени паладинів і жерців, чия побожність не поступається лордеронській і стормвіндській.",al={"релігія дворфів","дворфи й святе світло","чи дворфи вірять у світло"}}},fp="5,471,20.582.0,28.742.0,32.603.0,43.312.0,32.224.0,38.259.0,38.306.0,39.297.0,34.261.0"}
P.entries["topic:emerald-dream"] = {n="Смарагдовий Сон",s="Смарагдовий Сон — неосяжне, вічно мінливе царство духів, що відбиває Азерот у його первісному стані, геть не торкнутому цивілізацією. Під опікою Аспекта драконів Ізери та її зеленої зграї він слугує духовним кресленням природи й священним краєм, де друїди спілкуються з колообігом життя.",h="Смарагдовий Сон — неосяжне, вічно мінливе царство духів, що відбиває Азерот у його первісному стані, геть не...",kw={"смарагдовий сон","ізера","зелена зграя","друїди","дикі боги","великий колообіг"},ang={["class:Druid"]="Смарагдовий Сон — священне джерело вашої сили, де ваш орден спілкується з Дикими Богами й вивчає тонку рівновагу Великого Колообігу.",["race:NightElf"]="Десять тисяч років ваші друїди-чоловіки спали у священних курганах, щоб мандрувати Сном разом з Ізерою, лишаючи Вартовим і Жрицям стерегти світ наяву.",["race:Tauren"]="Ваші друїди мандрують краєм снів, щоб спілкуватися з духами землі, бачачи в ньому неприборкану колиску творіння Земної Матері."},sec={{t="Дзеркало первісного Азероту",b="Існуючи поза фізичним світом, але прив'язаний до його серцебиття, Смарагдовий Сон відбиває, яким був би Азерот, якби розумні істоти ніколи не вирубували його лісів і не будували міст на його камені. Створений під час давнього впорядкування світу, він — вічно мінлива дика природа з незайманими лісами, безкраїми рівнинами й первісними річками. Час і відстань у Сні майже нічого не важать: дні у фізичному світі можуть відчуватися як десятиліття в духовному, а орієнтири змінюють обриси, мов туман, перед очима смертних."},{t="Царство Сновидиці",b="Після впорядкування світу титани довірили цю зелену площину Ізері Сновидиці — великому Аспекту зеленої драконячого роду. Покликана спрямовувати розвиток і природний ритм Азероту, Ізера перебуває в нескінченному трансі й дивиться зачарованим сонним зором, що бачить і світ наяву, і його дзеркальне духовне відображення. Зелені дракони стережуть рідкісні природні портали, що з'єднують фізичний світ зі Сном, і вічно пильнують межу між сном і пробудженням."},{t="Друїди й сновидіння",b="Для смертних друїдів Смарагдовий Сон — джерело їхнього ремесла. Спрямовуючи магію природи, друїди можуть переносити свої духи в Сон, лишаючи тіла спочивати в безпеці курганів роками чи навіть століттями. У цьому дикому царстві вони спілкуються з давніми духами природи й Дикими Богами, глибоко осягаючи Великий Колообіг життя й смерті. Вправні мандрівники Сну вчаться у своїх сонних подобах долати фізичні закони — долати величезні відстані чи прослизати крізь тверді перепони, коли заманеться."}},faq={{q="Що таке Смарагдовий Сон?",a="Смарагдовий Сон — ефемерне, духовне відображення Азероту. Він зберігає незаймане, дике первісне креслення світу таким, яким той був, доки цивілізовані раси не змінили його обличчя, і слугує прихистком для духів природи й зеленої драконячого роду.",al={"що таке смарагдовий сон","лор смарагдового сну","пояснення сну"}},{q="Хто править Смарагдовим Сном?",a="Аспект драконів Ізера пильнує Сон разом із зеленою драконячою зграєю. Проте вона не має над ним цілковитої влади. Дика, глибинна будова Сну живе власним прадавнім ритмом, що скеровує Ізерине піклування, а не кориться її волі.",al={"хто контролює смарагдовий сон","правитель смарагдового сну","ізера сон"}},{q="Як смертні потрапляють у Смарагдовий Сон?",a="Більшість смертних входить туди через глибокий друїдський сон, переносячи дух у сновидну подобу, а тіла лишаючи під захистом у курганах. По всьому Азероту є й рідкісні тілесні портали, які охороняє зелена драконячий рід, хоча ступати в них небезпечно.",al={"відвідати смарагдовий сон","як зайти в сон","форма сновидця"}},{q="Чи можна щось змінити всередині Сну?",a="Сновидці можуть думкою й магією тимчасово змінювати довкілля, але ці зміни ніколи не тривають довго. Первісне креслення Сну неминуче бере своє, стираючи будь-який тривкий слід смертних.",al={"чи можна змінити смарагдовий сон","змінити сон"}},{q="Чому друїди сплять століттями?",a="Друїди поринають у тривалу сплячку, щоб блукати Смарагдовим Сном, спілкуватися з духами природи, вчитися в Диких Богів і допомагати зеленій драконячому роду з покоління в покоління підтримувати рівновагу природних циклів Азероту.",al={"чому друїди сплять","сплячка друїдів","курганні лігва сплять"}},{q="Куди йдуть духи звірів після смерті?",a="Духи багатьох звірів, Диких Богів і створінь природи після смерті вирушають у Смарагдовий Сон. Такі місця, як Ґ'Ганір, Дерево-Матір, слугують небесними прихистками, де дикі духи знаходять спочинок у Великому Колообігу.",al={"потойбіччя тварин","духи диких богів","духи звірів"}}},fp="13,315,30.527.0,24.513.0,23.543.0,26.252.0,28.262.0,39.274.0,39.223.0,34.227.0,41.219.0"}
P.entries["topic:explorers-league"] = {n="Ліга Дослідників",s="Ліга Дослідників — славетна дворфська археологічна гільдія з осідком у Залі Дослідників в Айронфорджі. Заснована за Короля Маґні Бронзбірда й очолювана його братом-мандрівником Бранном, Ліга прагне розкрити забуте походження дворфського народу. Її розлогі розкопки охоплюють увесь Азерот: вони відкривають давні руїни титанів, але часто розпалюють місцеві конфлікти.",h="Ліга Дослідників — славетна дворфська археологічна гільдія з осідком у Залі Дослідників в Айронфорджі.",kw={"ліга дослідників","зала дослідників","бранн бронзбірд","маґні бронзбірд","ульдаман","бель модан"},ang={["faction:Alliance"]="Окрім наукової цікавості, Ліга діє як неофіційна розвідувальна рука у віддалених краях і тихо передає зашифровані знахідки SI:7 у Стормвінді.",["profession:Mining"]="Дворфські шукачі значною мірою покладаються на гірничі традиції, щоб кріпити тунелі, обстежувати пласти й видобувати делікатні механізми титанів із суцільної скелі.",["race:Dwarf"]="Кожне місце розкопок і кожен артефакт титанів наближають дворфський народ до розуміння свого давнього походження від творців і того, як він вийшов із каменю.",["race:Tauren"]="Безрозсудне використання динаміту Лігою в Калімдорі осквернило землі предків роду Стоунспайр, доводячи, що її невпинне копання часто йде коштом землі."},sec={{t="Нова мета дворфів",b="Століттями дворфи Каз Модану спрямовували свою грізну енергію на гірництво, обробку каменю й інженерію. Та все круто змінилося, коли відкопали давні руїни, що натякали на забуту спадщину, яка пов'язує дворфів із легендарними творцями-титанами. Прагнучи розгадати таємницю походження свого народу, Король Маґні Бронзбірд постановив, що дворфське ремесло має круто повернути до археології. Разом із братом Бранном Маґні заснував Гільдію Дослідників — нині широко відому як Ліга Дослідників, — щоб прочісувати світ у пошуках реліквій, забутих міст і слідів давніх предків."},{t="Зала й розкопки",b="Діяльністю Ліги керують із просторої Зали Дослідників в Айронфорджі: щоденними справами опікується Верховний Дослідник Мунін Маґеллас, поки Бранн Бронзбірд досліджує далекі краї. По всьому Каз Модану й поза ним шукачі ведуть великі розкопки. Такі місця, як Місце розкопок Айронбенда в Лох Модані чи Місце Розкопок Велґара в Багнокраї, відкривають величезні скам'янілі літописи й давню архітектуру. Проте шукачі часто опиняються в облозі звірів, вигнаних з угідь, трогів і ворожих угруповань, що зазіхають на підземні реліквії."},{t="Сутички на рубежах",b="Агресивні експедиції Ліги викликали запеклий опір за межами дворфських земель. У Калімдорі такі розкопки Ліги, як Бель Модан на півдні Пусток, вигнали місцевих тауренів роду Стоунспайр важкими промисловими вибухами, розпалили жагу помсти й розгнівали місцевих духів землі. У посушливих Пустищах шукачі Ліги відкрито б'ються з кланом Темного Заліза за величезні сховища титанів Ульдаману. Агенти Ліги також потай діляться відомостями з таємною мережею SI:7 у Стормвінді — тож їхні розкопки по всьому світу часто перетинаються з високою політикою Альянсу."}},faq={{q="Що таке Ліга Дослідників?",a="Ліга Дослідників — організація з Айронфорджа, що займається розвідкою земель, археологією й дослідженням походження дворфів. Вона веде розкопки по всіх Східних Королівствах і на Калімдорі, щоб відкопати реліквії стародавнього світу.",al={"гільдія дослідників","дворфійські дослідники","хто така ліга дослідників","ліга дослідників"}},{q="Хто очолює Лігу Дослідників?",a="Король Маґні Бронзбірд допоміг заснувати гільдію, але її офіційний очільник — його наймолодший брат, славетний мандрівник Бранн Бронзбірд. Коли Бранн, як часто буває, мандрує світом, справами в Залі Дослідників в Айронфорджі керує Верховний Дослідник Мунінн Маґеллас.",al={"лідер ліги дослідників","роль бранна бронзбірда","мунін маґеллас"}},{q="Чому король Маґні заснував Лігу?",a="Коли дивні підземні руїни засвідчили, що дворфи народилися не просто зі звичайного гірського каменю, король Маґні спрямував величезну частину дворфійських ремесел на археологію, щоб відкрити справжню, міфічну спадщину свого народу.",al={"чому дворфи копають","походження дворфів","навіщо археологія"}},{q="Чи можуть до Ліги вступати не-дворфи?",a="Так. Хоча Ліга й лишається переважно дворфійською — за членами, проводом і духом, — до неї вступають і представники інших рас Альянсу, зокрема заповзяті гноми на кшталт Клоппера Візбенґа, а також довірені польові помічники на різних континентах.",al={"гноми в лізі дослідників","інші раси в лізі","хто може вступити"}},{q="Чому таурени воюють із Лігою Дослідників?",a="Поспішаючи з розкопками на Калімдорі, дворфи-шукачі в Бель Модані вдалися до потужної вибухівки й витіснили корінне плем'я тауренів Кам'яного Шпиля, спустошивши їхнє поселення й розгнівавши місцевих духів землі свавільним нищенням священної землі.",al={"бел модан таурени","дворфи проти тавренів","ворожнеча кам'яного шпиля"}},{q="Що таке Ульдаман і чому він важливий для Ліги?",a="Ульдаман — величезна підземна споруда титанів, похована під Пустищами. Ліга вважає його перлиною своїх досліджень і вірить, що його запечатані зали зберігають незаперечні докази перетворення й прадавнього створення дворфійського народу.",al={"розкопки ульдамана","ліга бедлендс","руїни титанів ульдаман"}}},fp="17,379,26.600.0,21.569.0,16.607.0,30.254.0,32.280.0,36.246.0,32.248.0,50.252.0,54.257.0"}
P.entries["topic:first-war"] = {n="Перша війна",s="Перша війна — спустошливий п'ятирічний конфлікт, під час якого Орда орків вийшла з Темного Порталу й ущент знищила людське королівство Стормвінд. Таємно влаштована одержимим демоном Охоронцем Медівом і чорнокнижником Ґул'даном, вона завершилася вбивством Короля Ллейна Рінна I й утечею вцілілих людей на північ, до Лордерона.",h="Перша війна — спустошливий п'ятирічний конфлікт, під час якого Орда орків вийшла з Темного Порталу й ущент...",kw={"перша війна","стормвінд","медів","ґул'дан","блекгенд","андуїн лотар","ллейн рінн"},ang={["class:Paladin"]="Різанина клириків Абатства Нортшира в цьому конфлікті довела, що сама свята віра не допоможе вижити в жорстокому рукопашному бою, — і безпосередньо надихнула на створення Лицарів Срібної Длані.",["class:Warlock"]="Ґул'дан і його Рада Тіней спрямовували завоювання Орди чаклунством Скверни, показуючи, яке величезне, світоруйнівне спустошення можуть принести демонічні угоди.",["faction:Alliance"]="Цілковите знищення Стормвінда стало похмурою пересторогою, що переконала північні народи покинути відокремленість і об'єднатися в Альянс Лордерона.",["race:Human"]="Перша війна — найчорніша година в історії Стормвінда, коли королівство впало, короля вбили, а вцілілі втекли за море безгрошовими біженцями.",["race:Orc"]="Для орків Перша війна стала першим кривавим завоюванням в Азероті, заплямованим кривавим прокляттям Маннорота й прихованими підступами Ради Тіней Ґул'дана."},sec={{t="Відкриття Порталу",b="До війни королівство Стормвінд довгі роки жило в мирі після Війни з гнолами, під захистом своїх лицарів і клириків Абатства Нортшира. Ця стабільність розлетілася на друзки, коли Охоронець Медів, потай одержимий володарем демонів Саргерасом, зв'язався з орком-чорнокнижником Ґул'даном на Дренорі. Разом вони створили Темний Портал у трясовині Чорного Болота. Гнана демонічною кров'ю й повільним умиранням рідного світу, Орда орків масово ринула до Азероту. Перші чутки вважали загарбників мстивими духами чи дивним різновидом тролів, але розвідувальні дозори сера Андуїна Лотара швидко підтвердили: прибуло дисципліноване, кровожерливе військо."},{t="Війна за Стормвінд",b="Під відкритим проводом Вождя Блекгенда й таємним маніпулюванням Ради Тіней Ґул'дана Орда заполонила південні землі королівства. Спроба орків просунутися в Долину Стренглторну проти тролів Ґурубаші провалилася, але їхня кампанія людськими землями виявилася катастрофічною. Орда завойовувала край за краєм, доки під владою людей не лишився тільки Ліс Елвінн. Блекгенд розпочав перший прямий штурм Стормвінда, але сер Андуїн Лотар відбив навалу блискучим несподіваним фланговим контрударом із моря, ненадовго врятувавши столицю від знищення."},{t="Зрада й падіння",b="Перелом настав, коли Лотар і молодий маг Хадґар викрили зраду Медіва, увірвалися до Каражану й убили Охоронця. Смерть Медіва кинула Ґул'дана в кому, і це дало Оргрімові Думхаммеру змогу кинути виклик Блекгендові й убити його в двобої мак'ґора. Перебравши всю владу, Думхаммер розгромив Раду Тіней і рушив на Стормвінд у другу облогу. Під час штурму напіворкиня-вбивця Ґарона вбила Короля Ллейна Рінна I в його твердині. Стормвінд пограбували й спалили дотла, і Лотарові довелося зібрати вцілілих і втекти на північ, через Велике Море, до Лордерона."}},faq={{q="Як орки взагалі потрапили в Азерот?",a="Чорнокнижник Ґул'дан на Дренорі та Хранитель Медів в Азероті разом за допомогою темної магії скверни прорвали тканину вимірів між світами й звели Темний Портал у Чорних Драговинах.",al={"як орки потрапили сюди","походження темного порталу","початок першої війни"}},{q="Чому інші людські королівства не допомогли Стормвінду?",a="Стормвінд лишився сам, бо далекі північні королівства вважали чутки про зеленошкірих загарбників вигадками чи місцевими чварами. Лише після падіння Стормвінда, коли Лотар прибув до Лордерона з кораблями, повними біженців, північні королі об'єдналися.",al={"чому немає альянсу","чи лордерон допоміг","підкріплення для стормвінда"}},{q="Хто вбив короля Ллейна?",a="Короля Ллейна Рінна I вбила в його ж фортеці Ґарона Галфорсен — посланниця, якій король довіряв. Цей удар під час останньої облоги зламав дух людей.",al={"хто вбив ллейна","смерть короля ллейна","гарона вбила короля"}},{q="Чи билися орки в Першій війні ще з кимось, окрім людей?",a="Так. На початку війни Орда просунулася на південь, у Долину Стренглторну, але її відкинули в запеклому бою тролі джунглів Ґурубаші.",al={"чи орки воювали з тролями","ґурубаші в першій війні","інші раси першої війни"}},{q="Хто переміг у Першій війні?",a="Повну перемогу здобула Орда. Королівство Стормвінд зрівняли із землею, короля Ллейна вбили, а вцілілих людей довелося масово вивозити морем на північ, до Лордерона.",al={"переможець першої війни","хто переміг у вк1","наслідок першої війни"}},{q="Що сталося з Вождем Блекгендом?",a="Коли Ґул'дан після смерті Медіва впав у безпам'ятство, Оргрім Думхаммер викликав Блекгенда на мак'ґору — двобій честі, — убив його й очолив Орду.",al={"як помер блекгенд","виклик оргріма думгаммера","вождя вбито"}}},fp="9,374,21.668.0,21.602.0,22.608.1,51.194.0,51.273.0,22.177.0,58.154.0,22.191.0,36.173.0"}
P.entries["topic:forsaken"] = {n="Відступники",s="Відступники — угруповання розумної нежиті з вільною волею, що відкололося від Погибелі після Третьої війни. На чолі з Королевою Баньші Леді Сильваною Віндраннер вони живуть у підземному Андерсіті, висіченому під руїнами столиці Лордерона. Хоча в усьому Азероті їм глибоко не довіряють, вони підтримують хиткий союз із розрахунку з Ордою.",h="Відступники — угруповання розумної нежиті з вільною волею, що відкололося від Погибелі після Третьої війни.",kw={"відступники","сильвана віндраннер","андерсіті","королева баньші","апотекаріум","нежить"},ang={["faction:Alliance"]="Для Альянсу Відступники — кошмарні пародії на полеглих друзів і рідних із Лордерона, що тримають колишні королівські землі й відповідають на жести примирення отрутою й сталлю.",["faction:Horde"]="Тралл уклав союз із розрахунку з Андерсіті заради земель на Сході, але багато орків і тролів ставляться до похмурих аптекарських дослідів і некромантської культури Відступників із глибокою підозрою.",["race:Tauren"]="Ваші старійшини, передусім Верховний Друїд Гамуул Рунтотем, із співчуття обстоювали прийняття Відступників до Орди, сподіваючись, що ваші шаманські й друїдські обряди колись полегшать чи зцілять їхній трагічний стан.",["race:Undead"]="Це ваш народ: приречений ходити землею в гниючій плоті, відкинутий колишньою ріднею, але згуртований під проводом Темної Леді, щоб вибороти власну державу."},sec={{t="Розбиті кайдани",b="Коли після Третьої війни хватка Короля-Ліча над його північними арміями послабла, тисячі мерців серед отруєних руїн Лордерона раптом повернули собі розум і спогади. Нажахані різаниною, яку їх змушували чинити, поки вони були рабами його волі, ці колишні громадяни побачили, що живі їх зневажають і полюють на них. Леді Сильвана Віндраннер, занепала генерал-слідопит Кель'Таласу, обернена на нечестиву баньші, згуртувала ці неприкаяні душі, захопила катакомби під Столичним Містом і назвала свій новий народ Відступниками."},{t="Союз із розрахунку",b="Оточена невблаганними ворогами — передусім фанатичним Багряним Хрестовим Походом і Погибеллю, — Сильвана розіслала посланців шукати союзників. Тих, кого послали до Стормвінда, вбили ще до того, як вони дійшли до воріт. Та за Великим Морем, у Калімдорі, Верховний Друїд Гамуул Рунтотем і старійшини тауренів радили співчуття, вірячи, що проклятий народ ще може знайти спокуту чи ліки через землю. Попри тяжкі сумніви Вождя Тралла й Кайрна Бладгуфа, Орда прийняла Відступників і здобула важливий північний плацдарм у Східних Королівствах."},{t="Темні лабораторії",b="Показуючи калімдорським союзникам готовність до співпраці, Відступники водночас дбають про власне похмуре виживання. Під Андерсіті, в Апотекаріумі, Королівське Аптекарське Товариство невтомно працює над «Новою Чумою», достатньо сильною, щоб знищити і Погибель, і загрози з боку живих. Тим часом звитяжці Відступників на кшталт Натаноса Блайткаллера ведуть запеклі війни в Чумних Землях, Передгір'ї Гілсбреда й Багряному Монастирі, щоб убезпечити кордони своєї держави."}},faq={{q="Чи Відступники — частина Погибелі?",a="Ні. Відступники вирвалися з-під влади Короля-Ліча над їхнім розумом після Третьої війни. Вони ненавидять Погибель і вважають Короля-Ліча Артаса своїм найзапеклішим ворогом, люто воюючи з його прислужниками по всіх Чумних Землях.",al={"різниця з погибеллю","чи відступники погибіль","чи нежить зла"}},{q="Де столиця Відступників?",a="Їхня столиця — Андерсіті, величезне підземне місто під руїнами Столичного Міста в Галявинах Тірісфалю. Війська Сильвани розширили королівські склепи й каналізацію, перетворивши їх на укріплений притулок, захищений від сонця й загроз поверхні.",al={"столиця нежиті","місто відступників","де живе нежить"}},{q="Чому Орда прийняла Відступників?",a="Архідруїд Гамуул Рунтотем і таурени палко за них заступалися, бачачи надію на спокуту й сподіваючись, що сили землі зцілять їхню недугу. Маґата Ґрімтотем теж підтримала угоду. Вождь Тралл погодився, бо Орді конче потрібен був стратегічний військовий плацдарм у Східних Королівствах.",al={"чому нежить в орді","як відступники приєдналися до орди","тралл і відступники"}},{q="Хто править Відступниками?",a="Леді Сильвана Віндраннер, Королева Баньші. Колишня генерал-рейнджерка високих ельфів, що полягла, захищаючи столицю Кель'Таласу, вона звільнила нежить, яка мала власну волю, і править з Андерсіті разом зі своїм радником-жахолордом Варіматрасом.",al={"лідер нежиті","королева відступників","хто править відступниками"}},{q="Чи всі Відступники — колишні люди?",a="Переважна більшість — колишні люди з полеглого королівства Лордерон, яких убили й підняли під час навали Погибелі. Проте серед їхнього проводу є й колишні ельфи, як-от Сильвана, і кожен, хто схилить коліно перед Темною Леді, знайде місце в їхніх лавах.",al={"раси нежиті","чи відступники лише люди","яка раса відступників"}},{q="Чому Багряний Хрестовий Похід так ненавидить Відступників?",a="Багряний Хрестовий Похід не бачить жодної різниці між свідомими Відступниками й безмозкою Погибеллю. Його фанатики вважають усю нежить гидотою, яку треба очистити вогнем і святим гнівом, хоч би яку волю чи вірність вона мала.",al={"багряний похід нежить","хрестовий похід проти відступників","чому багряні нападають"}}},fp="8,367,15.572.0,26.566.0,17.474.1,37.240.0,30.241.0,40.318.0,23.222.0,35.267.0,55.226.0"}
P.entries["topic:frostmane-tribe"] = {n="Плем'я Морозогривів",s="Плем'я Морозогривів — це люті крижані тролі, корінні мешканці студених вершин Дун Мороґу. Століття тому дворфи Айронфорджа загнали їх у печери та на віддалені хребти, і відтоді вони ведуть невпинну партизанську війну, щоб повернути дім предків.",h="Плем'я Морозогривів — це люті крижані тролі, корінні мешканці студених вершин Дун Мороґу.",kw={"морозогриви","крижані тролі","дун мороґ","тролі","твердиня морозогривів","мерехтливий хребет"},ang={["profession:Cooking"]="Скелясті вепри та звірі, яких тримають біля таборів Морозогривів, дають грубу дичину для похідних харчів серед пронизливих снігів Дун Мороґу.",["race:Dwarf"]="Для дворфів Морозогриви — постійне нагадування про кровну ворожнечу предків. Сама королева Еймір загинула в засідці тролів Морозогривів, тож оборона Дун Мороґу для горян — справа глибоко особиста.",["race:Troll"]="Хоч тролі Темного Списа й поділяють загальну спадщину тролів, відлюдні Морозогриви — дикі крижані тролі, яким байдуже до спорідненості: гостей з Орди вони мають за зайд на своїх священних вершинах."},sec={{t="Вигнанці високих скель",b="Задовго до того, як клан Бронзбірдів об'єднався під Айронфорджем, тролі Морозогриви панували над засніженими просторами Дун Мороґу. Піднесення і розширення дворфійського королівства розтрощило їхнє царство, і вцілілі крижані тролі відступили на замерзлі хребти й скелі. Ця принизлива поразка розпалила гірку ненависть, що передається з покоління в покоління й досі не згасла. Морозогриви бачать у кожному горянині, мандрівнику й хуторі ворога-загарбника, якого треба вигнати або вбити."},{t="Слушна нагода",b="Десятиліттями Сенат Айронфорджа мав Морозогривів лише за набридливу прикрість, що чаїться в пагорбах. Та раптова поява трогів з глибин під Дун Мороґом внесла безлад у дворфійську оборону. Відчувши слушну мить, поки горяни перевантажені, а дворфійські війська воюють у війнах Альянсу за кордоном, Морозогриви почали нові жорстокі набіги з твердинь на кшталт Твердині Морозогривів і Мерехтливого Хребта, щоб повернути давні землі."},{t="Нальотчики долин",b="Сенат Айронфорджа зрештою помітив зростання загрози й послав Ґреліна Вайтбірда з братом Сеніром дати їй раду. З печер Твердині Морозогривів і висот Мерехтливого Хребта тролі б'ють по дворфах, а в Долині Холодного Хребта воєначальники на кшталт Ґрік'ніра Холодного керують зухвалими нападами на горян."}},faq={{q="Хто такі тролі-Морозогриви?",a="Це плем'я крижаних тролів, споконвічних мешканців засніжених скель Дун Мороґа. Століття тому вони панували в цьому краї, доки дворфійські війська не розбили їх і не загнали на високі хребти.",al={"лор морозогривів","хто такі морозогриви","тролі дун мороґу"}},{q="Чому Морозогриви зараз нападають на дворфів?",a="Дворфійські горяни виснажені навалами трогів і військовими обов'язками перед Альянсом, тож Морозогриви бачать нагоду повернути свої прадавні мисливські угіддя й помститися Айронфорджу.",al={"чому морозогриви нападають","повстання морозогривів","напади тролів дун мороґу"}},{q="Хто очолює плем'я Морозогривів?",a="Плем'я ходить у набіги з Твердині Морозогривів і Мерехтливого Хребта, а його бойові ватаги ведуть агресивні ватажки, як-от Ґрік'нір Холодний, що дошкуляє дворфам Долини Холодного Хребта.",al={"лідер морозогривів","вождь морозогривів","хто керує морозогривами"}},{q="Що сталося з Твердинею Морозогривів?",a="Твердиня Морозогривів досі лишається оплотом племені — печерою тролів на пагорбах Дун Мороґа, звідки Морозогриви ходять у набіги. Сенат Айронфорджа послав Ґреліна Вайтбірда та його брата Сеніра впоратися із загрозою.",al={"трогги твердині морозогривів","що сталося з печерою тролів","чому тролі пішли"}},{q="Що таке мерехтлива трава і навіщо тролі її збирають?",a="Мерехтлива трава — витривала рослина, що росте під лютими вітрами Мерехтливого Хребта. Морозогриви вирощують і збирають її для священних племінних обрядів, а дворфійські пивовари цінують її як складник міцного стауту.",al={"мерехтлива трава","морозогриви мерехтлива трава","навіщо мерехтлива трава"}},{q="Чи Морозогриви в союзі з Ордою?",a="Ні. Морозогриви — незалежні крижані тролі, що люто ненавидять усіх чужинців і нападають на мандрівників і дослідників, хоч би якій фракції ті служили.",al={"чи морозогриви орди","фракція морозогривів","морозогриви дружні до орди"}}},fp="15,246,24.488.0,20.499.0,22.347.1,29.182.0,48.202.0,30.171.0,32.230.0,53.217.0,41.148.0"}
P.entries["topic:grimtotem-tribe"] = {n="Плем'я Ґрімтотем",s="Плем'я Ґрімтотем — войовничий, затято відданий давнім звичаям клан тауренів, що відмовляється офіційно присягнути Орді Тралла. Їх легко впізнати за темними шкурами й лютим бойовим розфарбуванням; вони прагнуть вигнати з Калімдору чужі раси й будь-якою ціною повернути землі пращурів. Поки їхня матріарх, Стара Відьма Маґата Ґрімтотем, мешкає на вершині Тандер Блафа й веде місцеву політичну гру, її родичі нападають на поселення по всьому Калімдору.",h="Плем'я Ґрімтотем — войовничий, затято відданий давнім звичаям клан тауренів, що відмовляється офіційно...",kw={"ґрімтотем","таурени","маґата ґрімтотем","стара відьма","тандер блаф","тисяча голок","шпиль темної хмари"},ang={["faction:Alliance"]="Ґрімтотеми зневажають усіх, хто приходить до Калімдору, і без розбору нападають на торговців Альянсу та поселення нічних ельфів.",["faction:Horde"]="Не вважайте їх союзниками через чорні шкури: у Пустках, горах і болотах Калімдору воїни Ґрімтотем нападуть із засідки на розвідників Орди, щойно їх побачать.",["race:Tauren"]="Ґрімтотеми — відкрита ганьба для Бладгуфів та інших племен. Кайрн дає їм притулок у Тандер Блафі заради єдності тауренів, проте їхня жага війни загрожує цю саму єдність зруйнувати.",["race:Undead"]="Маґата Ґрімтотем — одна з небагатьох тауренських провідниць у Тандер Блафі, хто відкрито шукає прихильності Відступників: разом із фахівцями Королівського Аптекарського Товариства вона сприяє дослідженням незвичайних чум."},sec={{t="Окреме плем'я",b="На відміну від своїх мирних родичів, які шанують Земну Матір із благоговінням, Ґрімтотеми вірять, що Калімдор належить лише тауренам. Змалку їх навчають не терплячої гармонії Великого Полювання, а безжальності, потайності й смертоносного бою. Вони відчувають глибоку зневагу до інших рас, що оселилися на їхніх споконвічних землях. Хоча Кайрн Бладгуф прийняв їх у Тандер Блафі, прагнучи об'єднати всіх тауренів, клан Ґрімтотем — єдине велике плем'я, яке так і не приєдналося офіційно до Орди Тралла й досі обстоює власні замкнені й жорстокі задуми."},{t="Нападники з диких земель",b="У диких краях, далеко від пильного ока Тандер Блафа, ворожість Ґрімтотемів відкрито переростає в насильство. У Горах Кам'яного Кігтя вони вирізають місцеві поселення й загрожують заставам постачання Орди. Серед високих столових гір Тисячі Голок, довкола Шпиля Темної Хмари, вони постійно тривожать Заставу Вільного Вітру й замишляють захопити каньйон. Зустріч із ними у Фераласі не менш небезпечна: Ґрімтотеми без вагань нападають на мандрівників Орди, каравани Альянсу й навіть на інших тауренів. Гарнізони Орди в Притулку Сонячної Скелі й Таборі Моджаче раз у раз оголошують нагороди та посилають воїнів знищувати цих жорстоких вигнанців."},{t="Тіні й аптекарі",b="За личиною духовної порадниці, яку носить Маґата, ховається заплутане павутиння інтриг. Стара Відьма палко підтримує суперечливі зв'язки тауренів із Відступниками: прилюдно вона запевняє, що хоче зцілити нежить, а потай шукає отруйні чуми та артефакти Високородних. У Тисячі Голок розвідники із Застави Вільного Вітру перехоплюють таємне листування між закутаними в плащі гінцями та вождями Ґрімтотемів у Шпилі Темної Хмари."}},faq={{q="Чому Ґрімтотеми ворожі, якщо їхня провідниця живе в Тандер Блафі?",a="Плем'я Ґрімтотем так і не вступило до Орди офіційно. Кайрн Бладгуф терпить Маґату Ґрімтотем на високих столових горах Тандер Блафа, сподіваючись зберегти мир між усіма тауренами, але мандрівні воїни племені відкидають будь-яку дипломатію з чужими. У Горах Кам'яного Кігтя, Тисячі Голок і Фераласі вони нападають на кожного, хто ступає на їхні прадавні землі, навіть на інших тауренів.",al={"чому ґрімтотеми червоні","чому ґрімтотеми нападають на орду","чи ґрімтотеми дружні"}},{q="Як відрізнити Ґрімтотема від інших тауренів?",a="Таурени Ґрімтотем майже всі мають чорну як смола шерсть. Вони також відомі тим, що розмальовують тіла й обличчя характерними різкими бойовими візерунками яскраво-білого, темно-червоного чи синього кольору.",al={"вигляд ґрімтотема","колір хутра ґрімтотемів"}},{q="Хто очолює Ґрімтотемів?",a="Ними править Стара Відьма, Маґата Ґрімтотем, могутня шаманка, що живе на Узвишші Старійшин у Тандер Блафі. Владу вона здобула, вийшовши заміж за попереднього вождя, який невдовзі загинув за нез'ясованих обставин, зірвавшись під час сходження.",al={"лідер ґрімтотемів","стара відьма"}},{q="Яка мета Ґрімтотемів?",a="Ґрімтотеми прагнуть очистити Калімдор від тих, кого вважають нижчими чужинськими расами, — зокрема орків, людей і нічних ельфів — і повернути всі прадавні землі тауренів. На відміну від народу Кайрна, вони вірять, що цю землю слід захопити лише силою, обманом і владою над стихіями.",al={"чого хочуть ґрімтотеми","мотиви ґрімтотемів"}},{q="Чому Маґата Ґрімтотем співпрацює з Відступниками?",a="Прилюдно Маґата стверджує, що підтримує Відступників, бо шаманство тауренів і мудрість землі можуть зцілити їхню недугу й повернути їм людяність. Насправді ж вона прагне скористатися їхнім знанням смертельних отрут, гнилі й темної магії, щоб позбутися ворогів і зміцнити свою владу на Калімдорі.",al={"маґата й нежить","ґрімтотеми й відступники"}}},fp="15,454,13.612.0,19.624.0,24.439.1,69.362.0,53.184.0,24.239.0,27.288.0,50.293.1"}
P.entries["topic:grommash-hellscream"] = {n="Громмаш Хеллскрім",s="Громмаш Хеллскрім — легендарний ватажок клану Пісні Війни, близький побратим Вождя Тралла й перший орк, що випив кров Маннорота. Хоч його жага битви колись прикувала його народ до Палаючого Легіону, він спокутував провину орківської раси, вбивши повелителя демонів в Ашенвалі ціною власного життя.",h="Громмаш Хеллскрім — легендарний ватажок клану Пісні Війни, близький побратим Вождя Тралла й перший орк, що...",kw={"громмаш хеллскрім","гром","ґоргаул","маннорот","клан пісні війни","ашенваль","спокута"},ang={["class:Warrior"]="Воїни вивчають бойову майстерність Грома й володіння Ґоргаулом як вершину воїнської агресії, бачачи в ньому і страшну ціну неприборканої люті, і чисту силу незламного бойового духу.",["faction:Horde"]="Для Орди Гром утілює трагічну дугу її заснування: лютий воїн, чия безоглядна вдача завела їх у темряву, але чия незламна відвага купила їм виживання й свободу в Калімдорі.",["race:NightElf"]="Нічні ельфи згадують Грома з гіркотою, що не минає: для них він — ошалілий від демонів загарбник, який осквернив священні гаї Ашенвалю й убив напівбога Кенарія.",["race:Orc"]="Орки шанують Громмаша як свого остаточного рятівника. Його жертва в Ашенвалі розірвала демонічне Прокляття Крові, що тримало расу в рабстві поколіннями, і дозволила Новій Орді ходити з гордістю й вільною волею."},sec={{t="Перший ковток і залізна воля",b="Ще до того, як Темний Портал з'єднав світи, Гром Хеллскрім вів клан Пісні Війни з незламною люттю; його вирізняли чорна як смола татуйована щелепа й смертоносний змах дворучної сокири Ґоргаул. Коли Ґул'дан і Рада Тіней піднесли на Дренорі чашу демонічної сили, Гром першим із ватажків випив кров володаря ями Маннорота. Той фатальний ковток прирік орківську расу на демонічне рабство й палючу жагу крові. Та, на відміну від багатьох ватажків, що загинули чи цілком піддалися, Гром мав залізну волю, яка зберегла його лютий дух цілим: він пережив жахи старої Орди, плекаючи невимовний біль за тим, що його народ віддав."},{t="Братерство в нетрях",b="Залишений на Дренорі під час Другої війни, Гром пізніше пройшов крізь Темний Портал — лише для того, щоб застрягти, коли розлом було зруйновано. Майже п'ятнадцять років Гром і його вцілілі воїни Пісні Війни ховалися від Альянсу Лордерону, терплячи млявість і відчай, що охопили орків, коли демонічна кров вивітрилася. Надія спалахнула знову, коли молодий утікач на ім'я Тралл розшукав його в глушині. Побачивши силу й шляхетне серце Тралла, Гром навчив його гордої спадщини їхнього народу. Разом з Орґрімом Думхаммером вони згуртували розрізнені клани, розбили людські табори для інтернованих і запалили народження Нової Орди."},{t="Падіння й остання спокута",b="Прибувши до Калімдору під час Третьої війни, Гром знову дав волю невгамовній агресії в давніх лісах Ашенвалю. Оточений нічними ельфами й напівбогом Кенарієм, Гром піддався вдруге — випив із оскверненого джерела, насиченого кров'ю Маннорота, щоб урятувати свій клан. Знову поневолений повелителем демонів, Гром обернувся проти власного народу, доки Тралл і Джайна Праудмур не схопили його й не очистили його розбещений дух давніми шаманськими й таємними обрядами. Цілком повернувшись до тями й пригнічений безмірною провиною, Гром переслідував Маннорота до Каньйону Падіння Демона. У відчайдушному останньому ударі він увігнав Ґоргаул у груди повелителя демонів, навіки розірвавши демонічне прокляття, тоді як пекельний вогонь забрав його життя."}},faq={{q="Хто такий Громмаш Хеллскрім?",a="Громмаш «Гром» Хеллскрім — вождь клану Бойової Пісні й довірений соратник Тралла. Він прославився своєю гострою як бритва сокирою Ґоргаул і зажив лихої слави як перший орк, що уклав демонічну угоду, випивши крові Маннорота. Згодом він спокутував свою провину, вбивши Маннорота на Калімдорі й звільнивши весь орківський народ від Кровного Прокляття.",al={"хто такий ґром","ким був хеллскрім","передісторія ґрома хеллскріма"}},{q="Як загинув Гром?",a="Гром загинув у Каньйоні Падіння Демона в Ашенвалі пліч-о-пліч із Траллом. Зійшовшись із володарем безодні Манноротом, Гром злетів у повітря й розрубав груди демона Ґоргаулом. Смертельний удар розтрощив серце демона, але вибух демонічного пекельного вогню смертельно поранив Грома, і той помер, проголосивши, що нарешті звільнив себе й свій народ.",al={"смерть ґрома","як загинув ґром хеллскрім","хто вбив ґрома"}},{q="Як Гром пов'язаний із Траллом?",a="Коли Тралл утік із табору для інтернованих у Дурнгольді, Гром був першим вождем клану, якого він зустрів. Гром узяв молодого орка під крило й навчив його орківських традицій, мови й культури. Тралл бачив у Громі старшого брата й духовного наставника, а Гром у Траллі — провидця, здатного повернути їхньому розбитому народові честь.",al={"тралл і ґром","як тралл знав ґрома","чи тралл і ґром були друзями"}},{q="Чому щелепа Грома татуйована в чорне?",a="Ставши вождем клану Бойової Пісні ще на Дренорі, Гром за обрядом витатуював нижню щелепу суцільним смоляно-чорним кольором. Усе життя це був виразний знак його влади й залізної волі, і завдяки йому лютий бойовий клич Грома на полі бою впізнавали з першої миті.",al={"чорна щелепа ґрома","чому щелепа ґрома чорна","татуйована нижня щелепа ґрома"}},{q="Чому Гром випив демонічної крові вдруге?",a="Коли його клан рубав ліс в Ашенвалі, нічні ельфи та напівбог Кенарій, чия божественна природа робила його майже невразливим для смертної зброї, винищили більшість орків. Відчайдушно прагнучи врятувати клан, Гром знайшов озерце, отруєне кров'ю Маннорота. Знаючи страшну ціну, він усе одно напився з нього, щоб здобути демонічну лють, потрібну для перемоги над Кенарієм.",al={"чому ґром знову пив","ґром орки хаосу","ґром двічі пив кров"}},{q="Де похований Громмаш?",a="Гром спочиває в Каньйоні Падіння Демона на південному сході Ашенвалю — саме там, де він здолав Маннорота. Над його могилою стоїть кам'яний пам'ятник з епітафією, яку написав Тралл, вславлюючи його мужність і остаточну жертву заради Орди.",al={"могила ґрома","пам'ятник ґрома","де гробниця ґрома"}}},fp="19,333,33.698.0,26.659.0,25.718.0,28.350.0,17.360.0,36.354.0,34.287.0,45.383.0,25.260.0"}
P.entries["topic:harpy"] = {n="Гарпія",s="Гарпії — хижі птахоподібні гуманоїди, схожі на крилатих нічних ельфійок, що гніздяться в смердючих сідалах по всьому Калімдору та на високих гірських перевалах Альтераку. Вони славляться пронизливим вереском і буремною магією стихій, нападають на необачних мандрівників і спустошують землі, де оселяються. Хоча легенди нічних ельфів пов'язують їх із проклятими зрадницями королеви Азшари, учені виводять їхній рід від Авіани — Дикої Богині птахів.",h="Гарпії — хижі птахоподібні гуманоїди, схожі на крилатих нічних ельфійок, що гніздяться в смердючих сідалах по...",kw={"гарпії","авіана","дикі боги","калімдор","гори кам'яного кігтя","азшара"},ang={["class:Druid"]="Друїди відчувають до гарпій особливу скорботу й гнів, вбачаючи в них здеградованих, охоплених хаосом нащадків Авіани, які зреклися священної рівноваги й отруюють дику природу буремною магією.",["race:NightElf"]="Хоч гарпії й моторошно схожі на нічних ельфійок, вони — спотворення природних небес: паплюжать священні крони довкола Галявини Оракула на Тельдрассилі й глумляться над пам'яттю прадавньої богині Авіани.",["race:Orc"]="Гарпії Пилового Вітру, що гніздяться в Яру Сухої Балки та Каньйоні Гострого Вітру, без упину загрожують шляхам постачання між Селом Сен'джин, Гострим Пагорбом і Оргріммаром, тож там потрібні постійні збройні патрулі.",["race:Tauren"]="Гарпії Вітрофурій в Малгорі та Верескливий виводок у Тисячі Голок цілими поколіннями нападали на каравани тауренів і спустошували рівнини, тож племена ненавидять їх як заклятих ворогів."},sec={{t="Крилата напасть Калімдору",b="Гарпії мають торс і голову нічної ельфійки, поєднані з широкими пернатими крильми й лиховісними пазурами. Попри тендітні ельфійські риси — які, як не дивно, з віком стають лише вродливішими, — натура в них цілком дика. Спершу вони гніздилися серед скель Гір Кам'яного Кігтя, але згодом напористо розселилися по всьому Калімдору й тероризують посушливі каньйони Дуротару, священні крони Тельдрассила та висоти Малгору. На відміну від диких звірів, на яких полюють, гарпії не живуть у злагоді з природою: вони нищать довколишню рослинність і живність, перетворюючи свої гнізда на смердючі смітники, засіяні обгризеними дочиста кістками здобичі."},{t="Пташиний родовід і темна натура",b="Міфи нічних ельфів часто стверджують, що гарпії походять від віроломних служниць, яких королева Азшара прокляла ще до Великого Розколу. Проте глибші розвідки давнини свідчать, що насправді це заблукале потомство Авіани — прадавньої Дикої Богині птахів. Коли Авіана загинула у Війні Прадавніх, а Дерево-Матір Ґ'Ганір згоріло, чимало її пернатих нащадків піддалися хаосу й гіркій самотності, покинувши священне служіння небу. За тисячоліття цей відчай переріс у чисту злобу. Нині суспільство гарпій — безжальний матріархат, де претендентки на титул королеви мусять зраджувати, вбивати й мучити суперниць, аби втримати владу."},{t="Магія бурі й лихі звички",b="Гарпії не лише шматують плоть гострими, мов бритва, пазурами, а й володіють небезпечною магією вітру та блискавок, насилаючи на ворогів згори верескливі пориви шквалу. Це дуже хитрі мисливиці, що вміють розмовляти; часом вони виміняють у підземних істот на кшталт кобольдів знайдені дивовижі на яскраві самоцвіти й блискучі дрібнички. Необачних мандрівників іноді зачаровують їхні ельфійські постаті, та тілесний дотик украй небезпечний: поцілунок гарпії отруйний і швидко насилає люту виснажливу гарячку на кожного, хто нерозважливо втратив пильність."}},faq={{q="Звідки походять гарпії?",a="Гарпії походять із щербатих вершин Гір Кам'яного Кігтя в центральному Калімдорі. З цих прадавніх висот вони швидко розселилися, звивши гнізда на Тельдрассилі, у Пустках, Дуротарі, Малгорі, Фераласі, Тисячі Голок і навіть за Великим Морем — на засніжених скелях Долини Альтерак.",al={"походження гарпій","батьківщина гарпій","де живуть гарпії"}},{q="Чи справді гарпії споріднені з нічними ельфами?",a="Перекази Калімдору кажуть, що колись вони були нічними ельфійками, проклятими за зраду королеви Азшари, проте дворфійські дослідження й прадавні знання встановили, що гарпії насправді походять від Авіани, прадавньої богині птахів, що загинула у Війні Прадавніх.",al={"чи гарпії нічні ельфи","зв'язок гарпій з нічними ельфами","прокляття азшари"}},{q="Чому гнізда гарпій мають таку лиху славу?",a="На відміну від диких птахів, гарпії оскверняють землю довкола себе. Їхні гнізда — брудні, смердючі смітники з потолоченого листя, огидних нечистот, погризених кісток і решток необережних мандрівників і звірів, яких гарпії затягують зі стежок поблизу.",al={"запах гарпій","які гнізда гарпій","сідала гарпій"}},{q="Як шабаші гарпій обирають ватажок?",a="За владу серед гарпій точиться запекла боротьба. Щоб здобути й утримати титул королеви чи матріарха, гарпія мусить довести, що вона набагато безжальніша за своїх сестер по гнізду, вдаючись до зради, вбивств і невпинної жорстокості як до ворогів, так і до суперниць.",al={"матріарх гарпій","королева гарпій","хто веде гарпій"}},{q="Якою силою й тактикою володіють гарпії?",a="Звичайні гарпії пікірують згори з грубою зброєю чи гострими, як бритва, кігтями. А їхні чарівниці володіють бурхливою магією бурі: б'ють ворогів тріскучими блискавками, вихорами вітру й пронизливим вереском, що збиває з пантелику.",al={"здібності гарпій","магія гарпій","як б'ються гарпії"}},{q="Чи правда, що поцілунок гарпії небезпечний?",a="Так. Окрім кігтів і магії бурі, гарпії мають отруйний поцілунок. Мандрівник, якого ельфійські риси обличчя спокусили підпустити гарпію ближче, ризикує отримати сильну отруту, що викликає раптову виснажливу гарячку.",al={"поцілунок гарпії","отрута гарпій","лихоманка гарпій"}}},fp="5,429,26.681.0,29.656.0,31.567.0,38.326.0,44.256.0,32.244.0,41.242.0,46.228.0,44.218.0"}
P.entries["topic:highborne"] = {n="Високородні",s="Високородні, або кель'дореї, — аристократична каста чарівників давньої Імперії Калдореїв, що служила королеві Азшарі. Їхнє нерозважливе маніпулювання Колодязем Вічності привело на Азерот Палаючий Легіон, а це спричинило руйнівну Війну Прадавніх і Великий Розкол.",h="Високородні, або кель'дореї, — аристократична каста чарівників давньої Імперії Калдореїв, що служила королеві...",kw={"високородні","кель'дореї","азшара","колодязь вічності","війна прадавніх","великий розкол","наги","сатири"},ang={["class:Druid"]="Друїдизм постав як природна філософія, що протистояла нерозважливому визиску Колодязя Вічності Високородними, і заклав підвалини для зцілення Калімдору після падіння імперії.",["class:Mage"]="Високородні були першими смертними на Азероті, хто практикував таємну магію; їхні приголомшливі звершення й катастрофічні помилки встановили небезпечні правила сучасного чаклунства.",["class:Warlock"]="Високородні першими зі смертних Азероту вступили в перемовини з Палаючим Легіоном: виміняли космічні таємниці й уклали демонічні угоди, що проклали шлях сучасному вивченню магії Скверни.",["race:NightElf"]="Пам'ять про касту Високородних досі лишається глибоким шрамом на культурі нічних ельфів — саме через неї таємну магію по всьому Калімдору заборонено під страхом вигнання чи смерті."},sec={{t="Аристократи Колодязя",b="Ще до Розколу Високородні піднеслися як привілейований вищий стан, що оточував королеву Азшару. Вважаючи себе вищими за простих калдореїв завдяки добірним родоводам, розуму й пишним привілеям, вони суворо пильнували доступ до Колодязя Вічності. Вони навчилися черпати й формувати його первісну таємну енергію та звели по всьому давньому Калімдору величні міста. Невгамовна жага дедалі могутнішого чаклунства спонукала їх черпати з Колодязя все глибше, і його спокійні води стали бурхливими й темними."},{t="Зрада й Розкол",b="Хвилі таємної сили, що їх збурювало чаклунство Високородних, привернули увагу темного титана Саргераса й Палаючого Легіону. Азшара та її радник Ксавіус переконали Високородних, що демони перетворять світ на незаплямований рай, і ті відчинили величезну браму просто в самому Колодязі. Так почалася катастрофічна Війна Прадавніх. Поки демонічні орди вирізали населення, повстанці, яких згуртував Малфуріон Стормрейдж, боролися, щоб закрити портал, — і зрештою Колодязь Вічності обвалився сам у себе, розірвавши надконтинент на шматки."},{t="Розпорошені спадкоємці",b="Після Розколу шляхи Високородних розійшлися. Ті, кого разом з Азшарою затягло під хвилі, перетворилися на змієподібних наг, інші впали жертвою демонічних прокльонів і стали сатирами. Загін на чолі з Дат'Ремаром Санстрайдером допомагав повстанцям, але не захотів зректися таємної магії, тож зрештою його вигнали за море, де вигнанці заснували королівство високих ельфів Кель'Талас. Нині відособлені громади, як-от Шен'дралар, живуть замкнено в Ельдре'Таласі — зневажені реліквії імперії, яка ледь не знищила Азерот."}},faq={{q="Що означає «Високородні»?",a="Дарнаською мовою їх звуть кель'дорай, що дослівно означає «діти шляхетного роду». Вони обрали цю назву, щоб відрізнити свої аристократичні родоводи й магічний хист від решти суспільства калдореїв.",al={"значення квельдореї","що означає квельдореї","переклад високородних"}},{q="Чи споріднені сучасні нічні ельфи з Високородними?",a="Так. Високородні були лише знатною правлячою кастою стародавніх нічних ельфів, що володіла магією. Хіба що трохи блідіші й схильні до пишного вбрання, фізично це був той самий народ. Після Розколу суспільство нічних ельфів заборонило таємну магію й цілком скасувало касту.",al={"чи нічні ельфи високородні","різниця нічних ельфів і високородних","зв'язок нічних ельфів і високородних"}},{q="Як Високородні спричинили Війну Прадавніх?",a="Їхнє надмірне й нестримне використання Колодязя Вічності розсилало магічні хвилі космосом і привабило Палаючий Легіон. Спокушені обіцянками Саргераса — неперевершеною силою й досконалим світом, — Азшара та її вельможі спрямували силу Колодязя на створення порталу й запросили демонічне військо просто в Калімдор.",al={"чому прийшов палаючий легіон","як високородні закликали демонів","роль високородних у війні прадавніх"}},{q="Чи всі Високородні стали на бік королеви Азшари?",a="Ні. Кілька угруповань відкололися, побачивши демонічне спустошення. Чаклуни на чолі з Дат'Ремаром Санстрайдером перейшли до Опору калдореїв Малфуріона, а такі громади, як Шен'дралар в Ельдре'Таласі, дбали про виживання й оборону власних володінь.",al={"добрі високородні","чи високородні воювали проти азшари","опір високородних"}},{q="Що сталося з уцілілими Високородними після війни?",a="Їхній рід розпорошився різними долями. Багато хто з тих, хто пішов на дно разом із Зін-Азшарі, став нагами, інших перетворено на сатирів, а прихильників Дат'Ремара вигнали до Східних Королівств, де вони стали високими ельфами. Дехто, як-от Шен'дралар у Лютопащі, досі живе замкнено серед прадавніх руїн.",al={"що сталося з високородними","де високородні тепер","нащадки високородних"}},{q="Хто такі Шен'дралар?",a="Шен'дралар — прадавня секта вчених і чародіїв із Високородних, які під час Великого Розколу відстояли південне місто Ельдре'Талас. Відрізані від королеви Азшари й основного суспільства калдореїв, вони замкнулися в місті, яке нині зветься Лютопащ, і зберігають своє безсмертя за допомогою темного чаклунства.",al={"високородні лютопащ","ельфи ельдре'таласу","хто живе в лютопащі"}}},fp="9,286,23.503.0,30.551.0,28.516.0,27.225.0,48.296.0,52.312.0,42.273.0,55.307.0,24.330.0"}
P.entries["topic:horde"] = {n="Орда",s="Орда — союз народів-вигнанців, яких Вождь Тралл об'єднав заради спільного виживання й свободи. Її опора — шаманські узи орків, тролів Темного Списа й тауренів Калімдору, а ще фракція тримає непевний союз із розрахунку з Відступниками в Лордероні. Обтяжена давніми кривдами й ворожими сусідами, Орда цінує силу, дію та честь понад політичні інтриги.",h="Орда — союз народів-вигнанців, яких Вождь Тралл об'єднав заради спільного виживання й свободи.",kw={"орда","тралл","оргріммар","таурени","темний спис","відступники","дуротар","нова орда"},ang={["faction:Alliance"]="Для людей, дворфів і ельфів Орда досі лишається зборищем жахливих дикунів і віроломних мерців, яким не можна довірити жодного миру.",["race:Orc"]="Нова Орда — шлях вашого народу до спокути: під стягом Тралла ви скидаєте спадщину демонічної крові й повертаєте собі шаманську честь предків.",["race:Tauren"]="Пліч-о-пліч з орками у війнах із кентаврами племена вберегли свої священні землі в Малгорі й знайшли вірних духовних братів.",["race:Troll"]="Флот Тралла врятував плем'я Темного Списа від загибелі на рідному острові, і відтоді тролі присвятили свої списи й тіні виживанню Орди.",["race:Undead"]="Членство Відступників в Орді — життєво важливий щит від Живих, які прагнуть очистити Лордерон, хоча багато хто в Калімдорі мовчки й насторожено придивляється до ваших методів."},sec={{t="Відроджений союз",b="Сучасна Орда мало схожа на демонічне військо, що пройшло крізь Темний Портал у Першій і Другій війнах. Звільнивши свій народ з-під влади Палаючого Легіону, Вождь Тралл повів орків через Велике Море до Калімдору, щоб збудувати духовну батьківщину на традиціях предків і честі. Дорогою Тралл уклав міцні узи з тролями Темного Списа Вол'джина, що втратили домівку, і племенами тауренів Кайрна Бладгуфа: пліч-о-пліч вони відбивали вторгнення кентаврів і демонів під час Третьої війни."},{t="Калімдорське ядро",b="У Калімдорі орки вибороли собі край Дуротар і звели фортецю-столицю Оргріммар, а тролям Темного Списа дали прихисток на сусідніх Островах Відлуння. Трохи південніше, на пишних рівнинах Малгору, кочові таурени об'єдналися довкола Тандер Блафа під проводом Верховного Вождя Кайрна Бладгуфа. Ці три раси поєднує шаманське благоговіння, глибокий зв'язок із природою та спільна потреба вижити, тож вони бачать одне в одному не тактичну перевагу, а справжню родину, скріплену пролитою кров'ю та духовною повагою."},{t="Союз із розрахунку",b="За морем, у зруйнованих землях Лордерону, Леді Сильвана Віндраннер вивела вільних Відступників з-під влади Погибелі. Відчайдушно шукаючи союзників проти вцілілих людських фракцій і залишків Погибелі, Сильвана відрядила посланців і до Стормвінда, і до Орди. Люди її вісників відпровадили ні з чим, але архідруїд Гамуул Рунтотем доводив, що нежить можна духовно спасти. Кайрн Бладгуф переконав Тралла, і той прийняв Відступників до Орди, здобувши життєво важливий військовий форпост у Східних Королівствах, хоч у калімдорських лавах і досі не вщухають сумніви."},{t="Холодна війна",b="Хоча Тралл сподівається на тривалий мир з Альянсом, спадщина Старої Орди кидає тінь, від якої не втекти. Для людей і дворфів орки досі лишаються кровожерливими загарбниками, а нежиті не можна довіряти ніколи. Сутички за цінний ліс в Ашенвалі та бої на кордонах занурили обидві фракції в напружену, крихку холодну війну. Тралл особисто спрямовує походи проти демонічних культів на кшталт Палаючого Клинка, щоб довести, що Орда розірвала зв'язки з Легіоном, але глибоко вкорінена ненависть може від найменшої іскри знову розпалити повномасштабну війну."}},faq={{q="Чим Стара Орда відрізняється від Нової?",a="Стара Орда була схибленим на крові загарбницьким військом, яким Палаючий Легіон маніпулював, щоб вторгнутися в Азерот у Першій і Другій війнах. Нова Орда, заснована Вождем Траллом, відкинула демонічне спотворення, повернулася до шаманства предків і перетворилася на оборонний союз вигнанців, що шукають виживання, землі й духовного відродження.",al={"стара й нова орда","чим ця орда інша","чи це та сама орда"}},{q="Хто очолює Орду?",a="Верховна влада належить Вождеві Траллу, що перебуває в Долині Мудрості в Оргріммарі. Тралл керує військовими й дипломатичними справами всієї Орди, але спирається на поради й провід Верховного Вождя тауренів Кайрна Бладгуфа, Мисливця Тіней Вол'джина з племені Темного Списа й Леді Сильвани Віндраннер, володарки Відступників.",al={"лідер орди","вождь орди","хто править ордою"}},{q="Чому Відступники належать до Орди?",a="Оточена ворожими рештками Альянсу й Погибеллю в Лордероні, Сильвана Віндраннер розіслала посланців шукати союзників, щоб вижити. Архідруїд Гамуул Рунтотем вірив, що Відступників можна духовно зцілити, і закликав Кайрна Бладгуфа за них заступитися. Кайрн переконав Тралла, що вагався, прийняти їх, і Орда здобула важливий оборонний плацдарм у Східних Королівствах.",al={"чому нежить в орді","як відступники приєдналися до орди","таурени допомогли нежиті"}},{q="Де столиця Орди?",a="Укріплене місто Оргріммар, вбудоване в скелі північного Дуротару на Калімдорі, — адміністративний і військовий осередок Орди. Тут стоїть трон Тралла й живуть посланці тролів, тауренів і Відступників.",al={"столиця орди","головне місто орди","де править тралл"}},{q="Чи Орда й Альянс зараз воюють?",a="Формально між ними діє хиткий мир, укладений після Битви за Гору Гіджал. Проте прикордонні сутички за деревину в Ашенвалі, територіальні тертя в Горах Альтерак і глибока історична ненависть тримають обидві сторони в тліючій холодній війні з місцевими зіткненнями.",al={"чи ми воюємо з альянсом","війна орди й альянсу класика","мир чи війна"}},{q="Чи всі тролі належать до Орди?",a="Ні. Головне троляче плем'я в Орді — Темний Спис, що припливло до Калімдору разом із Траллом. Більшість інших тролячих племен Азероту ворожі, хоча деякі, як-от плем'я Ревантуск із Пригір'я, мають окрему угоду про дружбу й взаємну оборону, не вступаючи до Орди офіційно.",al={"які тролі в орді","чи лісові тролі в орді","тролі орди"}}},fp="5,427,14.534.0,17.497.0,26.598.0,10.560.0,63.341.0,20.348.0,39.389.0,34.233.0,53.310.0,34.308.0"}
P.entries["topic:house-of-nobles"] = {n="Дім Вельмож",s="Дім Вельмож — спадкова аристократична рада, що допомагає правити королівством Стормвінд із Фортеці Стормвінда. Вельможі мають величезний вплив на землеволодіння, податки й торгівлю краю, і саме їхня відмова заплатити робітникам, які відбудували місто, розпалила криваві заворушення, з яких постало Братство Дефіас.",h="Дім Вельмож — спадкова аристократична рада, що допомагає правити королівством Стормвінд із Фортеці Стормвінда.",kw={"дім вельмож","стормвінд","братство дефіас","едвін венкліф","катрана престор","оніксія","знать"},ang={["class:Rogue"]="Запеклі чвари знаті, брудні оборудки й ганебні таємниці дають удосталь роботи посередникам, кишеньковим злодіям і славетному торговцеві сирами Еллінгові Тріасу.",["class:Warlock"]="Стормвіндським знавцям темних мистецтв, що збираються під «Зарізаним Ягням», доводиться відповідати на небажані розпитування впливових вельмож.",["faction:Alliance"]="Попри вплив при дворі Стормвінда, Дім Вельмож мало важить для Великого Альянсу загалом, хоча його скнарість постійно загрожує стабільності південних людських земель.",["race:Human"]="Для людей Вестфолу й Сутінколісся Дім Вельмож — це пихаті пани, що зручно вмостилися в мармуровому палаці, поки прості люди проливають кров, захищаючи свої господарства від розбійників і чудовиськ."},sec={{t="Аристократи королівства",b="Дім Вельмож, до якого входять наймогутніші патриціанські роди Стормвінда, є головним дорадчим органом Корони. Оскільки аристократії належить більшість орних земель в Елвінні, Вестфолі та Сутінколіссі, вона має непомірну владу над торгівлею, місцевими магістратами й королівськими указами. Хоча офіційно королівством правлять юний король Андуїн Рінн і Верховний Лорд Болвар Фордрагон, рада раз у раз зв'язує трону руки бюрократичною тяганиною, присвоюючи собі право відкладати суди, блокувати страти й утручатися в управління провінціями."},{t="Повстання робітників",b="Після Другої війни Дім Вельмож найняв очільника гільдії Едвіна Венкліфа та Гільдію Каменярів, щоб відбудувати Стормвінд із попелу. Та водночас знать наробила величезних боргів, розширюючи військові кордони королівства на південь, до Стренглторну. Коли сяйна столиця постала знову, вельможі відмовилися платити за рахунком і не виплатили робітникам належного. Обурені зрадою, каменярі збунтувалися на вулицях. Камінь, кинутий у тому сум'ятті, влучив у королеву Тіффін Рінн і вбив її; тоді знать вигнала гільдію, і розорені робітники подалися до Вестфолу, де заснували Братство Дефіас."},{t="Бюрократичний параліч",b="Поки короля Варіана немає, вельможі здебільшого полишили віддалені землі королівства напризволяще, а королівською владою користуються для дріб'язкових чвар. Урядовці Даркшира кипіють від гніву, бо Дім Вельмож скасував їхній смертний вирок грабіжникові могил Декстренові Ворду й наказав помилувати його та перевести до В'язниці Стормвінда. Так само на невизначений час відклали страту ватажка орків Блекрок Тарґорра Жахливого — лише тому, що якийсь підступний вельможа хоче використати цю потвору як пішака в політичній грі. Місцевим вартовим лишається тільки дивитися, як Стормвінд гниє зсередини."},{t="Шепіт зради",b="Упертість ради — далеко не проста жадібність. Насправді Леді Катрана Престор — а потай чорна драконка Оніксія — систематично маніпулює Домом Вельмож, щоб паралізувати королівство. Підживлюючи пиху аристократів під час перемовин із каменярами й підбурюючи їх притримувати королівську скарбницю, вона спланувала і внутрішній занепад держави, і викрадення короля. Високопоставлені аристократи, як-от Лорд Ґреґор Лесковар, у тіні трону змовляються з Братством Дефіас, щоб жодне королівське військо не вирушило рятувати віддалені містечка."}},faq={{q="Що таке Дім Вельмож?",a="Дім Вельмож — правлячі аристократичні збори Стормвінда, до яких входять знатні землевласницькі родини, чиї титули й місця передаються в спадок. Вони радять монархові й контролюють чималу частину внутрішньої політики королівства, податки й трудові закони.",al={"що таке дім вельмож","вельможі стормвінда","лор дому вельмож"}},{q="Чому Дім Вельмож відмовився платити Каменярам?",a="Знать украй виснажила скарбницю Стормвінда, фінансуючи дорогі військові походи на південь — в Елвінн і Стренглторн. Коли Едвін Венкліф виставив рахунок за відбудову Стормвінда, вельможі не змогли заплатити, запропонували лише дещицю обіцяного, а згодом наказали розпустити гільдію.",al={"чому не заплатили каменярам","чому вельможі обдурили венкліфа","неоплачений дефіас"}},{q="Хто вбив королеву Тіффін Рінн?",a="Під час заворушень каменярів, спричинених відмовою Дому Вельмож платити, невідомий бунтар кинув у натовп камінь із бруківки. Він влучив королеві Тіффін Рінн у голову й убив її на місці, назавжди перекресливши будь-які мирні переговори між короною й робітниками.",al={"як померла тіффін","смерть королеви тіффін","хто кинув камінь у королеву"}},{q="Чому Стормвінд не посилає війська на допомогу Вестфолу чи Сутінколіссю?",a="Дім Вельмож тримає в руках гаманець королівства й адміністративні дозволи. Знать раз у раз блокує фінансування, військові відрядження й допомогу віддаленим землям, лишаючи місцеві загони, як-от Народне ополчення й Нічну Варту, цілком напризволяще.",al={"чому немає допомоги сутінколіссю","чому стормвінд ігнорує вестфолл","чому стормвінд не шле армію"}},{q="Хто такий Лорд Баурлес К. Вішок?",a="Лорд Баурлес К. Вішок — впливовий вельможа, що домагається розслідування щодо чорнокнижників під «Зарізаним Ягням». Наслідки його розслідування розкриваються в ланцюжку завдань для чорнокнижників.",al={"лорд вішок","баурлес вішок","вельможа вбитий чорнокнижниками"}},{q="Чи всі вельможі обернулися проти Каменярів?",a="Ні. Королева Тіффін Рінн спершу підтримувала каменярів, як і граф С. Дж. Ерлґадін, що завзято домагався кращої платні й умов праці для них. Ерлґадіна так обурила зрада гільдії його побратимами-вельможами, що він зрікся і титулу, і місця, покинув світське товариство й приєднався до експедиції Гемета Несінгварі в Стренглторні.",al={"чи вельможі допомагали каменярам","граф ерлґадін","вельможі на боці каменярів"}}},fp="15,309,24.565.0,16.656.0,22.612.1,19.582.1,28.278.0,58.318.0,30.286.0,61.284.1,32.197.1,48.334.0"}
P.entries["topic:human"] = {n="Людина",s="Люди — витривала раса смертних, що легко пристосовується й значною мірою визначила історію Східних Королівств. Колись людство об'єднувала давня Імперія Аратор, та згодом його цивілізація розпалася на Сім Королівств, і нині Стормвінд — головний уцілілий оплот людей у складі Альянсу.",h="Люди — витривала раса смертних, що легко пристосовується й значною мірою визначила історію Східних Королівств.",kw={"люди","людство","аратор","сім королівств","стормвінд","лордерон","андуїн рінн"},ang={["class:Mage"]="Людське чарівництво бере початок із Тролячих війн, коли високі ельфи навчили першу Сотню людських магів, що згодом привело до заснування Даларана.",["class:Paladin"]="Лицарів Срібної Длані заснували в Лордероні людські святі отці й лицарі, щоб боротися з жахіттями Другої війни.",["faction:Alliance"]="Людська дипломатія й рішучість викували Альянс Лордерону, і Стормвінд досі лишається політичним і військовим серцем фракції.",["faction:Horde"]="Люди стали першими ворогами, яких зустріли орки, пройшовши крізь Темний Портал, — і це поклало початок трьом жорстоким війнам за виживання на Азероті.",["race:Human"]="Ви, людина, успадковуєте спадщину полеглого Аратору й зруйнованого Лордерону; оборона й виживання королівств смертних тепер лежать саме на плечах Стормвінда."},sec={{t="Імперія Аратор",b="Тисячоліття тому перші люди жили розпорошеними кочовими племенами, яким постійно загрожували лісові тролі Амані. Розуміючи, що роз'єднаність означає загибель, воєначальник Торадін із племені Араті об'єднав розрізнені клани дипломатією та завоюваннями й заснував Імперію Аратор зі столицею у фортеці Стром. Під час Тролячих війн обложені високі ельфи Кель'Таласу уклали союз з Аратором і навчили сотню людей таємної магії. Разом вони розгромили тролячі війська, утвердили владу людства над центральними землями й заклали підвалини для майбутніх союзів смертних."},{t="Розпад на Сім Королівств",b="Коли Аратор зміцнів і розбагатів, його віддалені поселення перетворилися на могутні самодостатні міста-держави. З часом централізована імперія розпалася на сім окремих держав: Ґілнеас, Альтерак, Даларан, Лордерон, Кул Тірас, Стормвінд і Стромґард (споконвічний дім Строму). Хоча ці народи жваво торгували з дворфами, гномами й ельфами, мир був крихким. Суперечки за землі, прикордонні сутички — як-от одвічні гірські чвари між Альтераком і Стромґардом — та придворні інтриги виснажували королівства й породили глибоке суперництво, яке тривало, доки зовнішні катастрофи не змусили їх діяти."},{t="Навала й руїна",b="Поява орочої Орди з Темного Порталу поклала край внутрішнім чварам людства. Під час Першої війни Стормвінд зрівняли із землею, а його біженці подалися на північ, щоб попередити інші королівства. У відповідь король Теренас Менетіл II допоміг скувати Альянс Лордерону, об'єднавши сили людей, дворфів, гномів і високих ельфів, щоб здолати Орду в Другій війні. Хоча Стормвінд ретельно відбудували, біда прийшла знову: у Третю війну чума Погибелі спустошила Лордерон, а Даларан упав, і північні людські королівства лишилися в димних руїнах."},{t="Хитке сьогодення",b="Нині Стормвінд — наймогутніше з уцілілих людських королівств і наріжний камінь Великого Альянсу. Проте мир досі недосяжний. Король Варіан Рінн загадково зник дорогою на дипломатичну зустріч, і королем коронували його десятирічного сина Андуїна Рінна, а регентом став Верховний Лорд Болвар Фордрагон. На півночі вцілілі лордеронці розпорошені або загинули, а Ґілнеас ховається за велетенською Стіною Ґреймейна, тож увесь тягар захисту людства лягає на Стормвінд."}},faq={{q="Які були Сім Королівств людства?",a="Сім Королівств постали, коли стародавня імперія Аратор розпалася на незалежні міста-держави: Лордерон, Стормвінд, Стромґард, Даларан, Кул Тірас, Ґілнеас і Альтерак. Кожне розвинуло власну культуру — від мореплавних флотів Кул Тірасу до магічних академій Даларану.",al={"сім людських королівств","людські народи","королівства аратору"}},{q="Звідки походять люди?",a="Люди з'явилися тисячі років тому як кочові племена, що блукали лісами й нагір'ями півночі Східних Королівств, особливо довкола Галявин Тірісфалю, а згодом об'єдналися в першу людську державу під проводом полководця Торадіна.",al={"походження людей","стародавні люди","предки людей"}},{q="Що сталося з королівством Лордерон?",a="Під час Третьої війни Лордерон спустошила чума нежиття, яку несла Погибель, а зрадив його власний принц, Артас Менетіл. Нині за його зруйновану столицю й довколишні землі змагаються нежить-Відступники, Погибель і такі рештки, як Багряний Хрестовий Похід.",al={"чому лордерон зруйновано","падіння лордерона","доля лордерона"}},{q="Хто нині править людством і Стормвіндом?",a="Король Варіан Рінн зник за підозрілих обставин, тож на троні як номінальний правитель сидить його юний син Андуїн Рінн, а регентом править Верховний Лорд Болвар Фордрагон разом із королівською радницею Леді Катраною Престор.",al={"хто править стормвіндом","король стормвінда","правитель стормвінда"}},{q="Чому високі ельфи навчили людей магії?",a="Під час давніх Тролячих воєн високим ельфам Кель'Таласу загрожувало знищення від тролів Амані. Відчайдушно потребуючи військової підмоги, вони уклали угоду з Торадіном, правителем Аратора: навчити сотню людей таємної магії в обмін на людські війська.",al={"ельфи навчили людей магії","перші людські маги","магія війн тролів"}},{q="Яку роль відіграли люди у створенні Альянсу?",a="Коли в Першій війні Стормвінд упав під ударом орків, людські біженці згуртували північні королівства. Під проводом короля Теренаса з Лордерона й Лорда Лотара зі Стормвінда людські держави об'єдналися з дворфами Айронфорджа, гномами й високими ельфами, створивши Альянс Лордерона.",al={"створення альянсу","походження альянсу лордерона","як почався альянс"}}},fp="5,297,21.619.0,28.619.0,17.572.0,20.504.0,41.281.0,38.227.0,42.272.0,43.221.0,42.269.0,50.266.0"}
P.entries["topic:hunter"] = {n="Мисливець",s="Майстри виживання в дикій природі й смертельно влучні стрільці, мисливці мандрують неприборканими куточками Азероту разом із лютими звірами-супутниками. Озброєні луками, рушницями чи арбалетами, вони вправно виснажують ворогів здалеку, а хитрі пастки й первісні аспекти допомагають їм керувати перебігом бою. Чи то вистежуючи невловиму здобич на засніжених вершинах, чи то підкрадаючись до неї густими лісами, вони покладаються на кмітливість і зв'язок із природою.",h="Майстри виживання в дикій природі й смертельно влучні стрільці, мисливці мандрують неприборканими куточками...",kw={"мисливець","мисливці","звір-супутник","вихованець","пастки","стрільба","слідопит"},ang={["class:Hunter"]="Ваша сила — у зв'язку з дикою природою та звіром-супутником. Опануйте свій арсенал далекого бою, тримайте дистанцію, а вихованець нехай утримує увагу ворога.",["race:Dwarf"]="Дворфи-стрільці славляться влучністю з важких рушниць: вони долають підступні гірські перевали Каз Модану разом із лютими полярними ведмедями.",["race:NightElf"]="Тисячоліттями Вартові-калдореї патрулюють прадавні ліси з луками й вірними шаблезубими котами, боронячи священні гаї від чужої порчі.",["race:Orc"]="Орочі приборкувачі звірів шанують традиції виживання, що їх предки викували в суворих світах, і творять нерозривні бойові узи з вірними вовками та вепрами.",["race:Tauren"]="Для тауренів полювання — священне духовне випробування витривалості й шанобливості: вони вшановують Земну Матір, виявляючи повагу до кожного звіра, що годує й одягає плем'я."},sec={{t="Спорідненість із дикою природою",b="У серці кожного мисливця живе інстинктивне співчуття до первісного світу. На відміну від тих, хто визискує природу чи ховається за кам'яними мурами, мисливці цілковито поринають у неприборкані краї. Вони вивчають звички, рухи й сильні сторони хижих звірів, здобуваючи їхню повагу, а не ламаючи їхній дух. Терпляче налагоджуючи зв'язок, мисливець приручає небезпечних істот — лютих крадливих котів, упертих гірських ведмедів і гострооких рапторів — і перетворює диких звірів на вірних союзників, що боронитимуть його до смерті."},{t="Влучні стрільці й слідопити",b="На полі бою мисливці диктують умови сутички з безпечної відстані. Озброєні луками, важкими арбалетами чи пристріляними рушницями, вони обрушують смертоносні залпи, що пробивають важкі обладунки ще до того, як нападник устигне наблизитися. Завдяки витонченим чуттям вони — незрівнянні слідопити, здатні помітити найслабший відбиток, запах чи слід, залишений здобиччю. Коли вороги намагаються скоротити відстань, мисливці ставлять морозні й вогняні пастки, влаштовують приголомшливі засідки чи спритно ухиляються, тримаючи супротивників саме там, де їм треба."},{t="Традиції різних народів",b="Шлях мисливця різниться в різних культурах Азероту. Вартові нічних ельфів утілюють давнє мистецтво стрільби й потайності під кронами Ашенвалю, вдаючись до луків і мистецтва тіней у тихій злагоді з дикою природою. Дворфи-стрільці долають крижані скелі Дун Мороґу разом із витривалими ведмедями й опановують інженерію пороху. А в Калімдорі слідопити-таурени й орки шанують давні кочові звичаї: переслідують здобич зі священною повагою й закликають духів звірів спрямовувати їхні постріли."}},faq={{q="Якою зброєю користуються мисливці?",a="Мисливці спеціалізуються на зброї дальнього бою: луках, арбалетах і рушницях. Зблизька вони вправно орудують і зброєю ближнього бою — древковою зброєю, посохами, сокирами й кинджалами, часто б'ються двома клинками або ставлять пастки, щоб відірватися й знову стріляти здалеку.",al={"зброя мисливців","що вдягають мисливці","луки й рушниці мисливців"}},{q="Як мисливці приручають звірів?",a="Мисливці покладаються на вроджене чуття й глибоке розуміння диких створінь. Спостерігаючи за поведінкою звіра, підходячи без лихих намірів і виявляючи силу й повагу, вони можуть заспокоїти небезпечного хижака й стати його товаришем на все життя, навчивши битися пліч-о-пліч.",al={"як приручити звіра","приборкання звірів","приручити тварину"}},{q="Які обладунки носять мисливці?",a="Мисливці починають свій шлях у легких, гнучких шкіряних обладунках, щоб лишатися спритними на бездоріжжі. Набуваючи досвіду й стикаючись із дедалі смертоноснішими загрозами, вони вчаться носити міцні кольчуги, що краще захищають і не надто сковують рухи.",al={"тип обладунків мисливця","чи можуть мисливці вдягати кольчугу","спорядження мисливця"}},{q="Що таке аспекти мисливця?",a="Аспекти — первісні прийоми, за допомогою яких мисливець налаштовує свої чуття й рефлекси на вроджені сильні сторони диких створінь. Закликаючи ці аспекти, мисливець може бігти зі швидкістю гепарда, цілитися пильно, мов яструб, чи перейняти захисну спритність мавпи.",al={"аспекти мисливця","аспект гепарда","тваринні аспекти мисливця"}},{q="Що станеться, якщо ворог підійде до мисливця надто близько?",a="Зблизька мисливцям доводиться скрутно, бо стріляти там важко. Щоб вижити, вони покладаються на крижані й вогняні пастки, приголомшливі засоби й удари зброєю ближнього бою, щоб сповільнити, поранити чи збити з пантелику нападників, поки самі вони чи їхні звірі відриваються на відстань.",al={"мертва зона мисливця","ближній бій мисливця","мисливець у рукопашній"}},{q="Які раси сповідують шлях мисливця?",a="Полювання знане майже в усіх культурах, хоча набирає різних форм. В Альянсі за лук і рушницю беруться нічні ельфи й дворфи. В Орді орки, таурени й тролі шанують вистежування й владу над звірами як найважливіші традиції виживання, успадковані від предків.",al={"хто може бути мисливцем","раси мисливців","ігрові раси мисливців"}}},fp="6,447,21.552.0,28.548.0,26.535.0,28.286.0,27.282.0,27.289.0,24.283.0,52.290.0,44.266.0"}
P.entries["topic:juggernaught"] = {n="Джаґернаут",s="Джаґернаут — величезний важкоброньований бойовий корабель, наїжачений потужними корабельними гарматами. Спершу його сконструювали огри як залізне ядро флоту Старої Орди в Другій війні: ці плавучі фортеці мали трощити прибережні твердині й торгові шляхи. Масивна залізна обшивка та бортові залпи облогової сили зробили їх легендарною зброєю морської війни.",h="Джаґернаут — величезний важкоброньований бойовий корабель, наїжачений потужними корабельними гарматами.",kw={"джаґернаут","бойовий корабель","бухта айронклад","мертві копальні","едвін венкліф","друга війна"},ang={["class:Rogue"]="Джаґернаут у Мертвих Копальнях — вершина зухвалості Едвіна Венкліфа: спорудити флагманський бойовий корабель просто під носом у SI:7 та Варти Стормвінда.",["faction:Alliance"]="Недобудований джаґернаут, знайдений під Вестфолом, викриває серйозну загрозу безпеці Стормвінда й двору короля Андуїна.",["faction:Horde"]="Джаґернаути — славетна сторінка морської спадщини Орди часів Другої війни, що довела: груба інженерна сила здатна кинути виклик морському пануванню Альянсу.",["race:Human"]="Зраджені відбудовники Стормвінда, що під проводом Венкліфа стали розбійниками, вклали найкращі будівельні й мулярські вміння у спорудження жахливого бойового корабля, захованого під пагорбами Вестфолу."},sec={{t="Жах Другої війни",b="Орки ніколи не були мореплавцями, тож коли під час Другої війни Орді знадобився флот, здатний перетнути Велике Море й кинути виклик морській перевазі Альянсу, вона значною мірою покладалася на винахідливість огрів. Так з'явився огрівський джаґернаут — основа армади Орди. Набагато повільніші й незграбніші за прудкі тролячі есмінці, ці велетні несли потужну броню та нищівні бортові батареї, що розбивали корпуси кораблів Альянсу й обертали прибережні укріплення на руїни."},{t="Бухта Айронклад",b="Під пагорбами Вестфолу, глибоко в підземних печерах Мертвих Копалень, захована Бухта Айронклад. Там, подалі від сторонніх очей і королівських інспекторів, майстри Едвіна Венкліфа потай будували повністю озброєний джаґернаут. Споруджуючи важкий бойовий корабель у підземній печері, що виходила просто у відкрите море, Дефіас розраховували обійти сухопутну оборону Стормвінда й завдати раптового удару з моря в саме серце королівства."}},faq={{q="Що таке джаґернаут?",a="Джаґернаут — величезний, важкоброньований військовий корабель, озброєний важкими гарматами для обстрілу. Його вперше створила Орда за допомогою огрів під час Другої війни: це плавуча фортеця, що має долати ворожі флоти й трощити берегові укріплення.",al={"джаґернот варкрафт","оркський лінкор","огровий джаґернот"}},{q="Чому в Мертвих Копальнях стоїть величезний корабель?",a="Едвін Венкліф і Братство Дефіас використовували відлюдну печеру Бухту Айронклад у Мертвих Копальнях як потаємну корабельню. Будівництво джаґернаута під землею вберігало його від патрулів Альянсу, поки над кораблем тривала робота.",al={"корабель у мертвих копальнях","чому човен у копальнях","корабель мертвих копалень"}},{q="Що Едвін Венкліф збирався робити з кораблем?",a="Корабель — частина справ, які Венкліф веде під Вестфолом. Що він для нього задумав, розкриває розслідування щодо Братства Дефіас.",al={"план венкліфа з кораблем","чому дефіас збудували корабель","призначення джаґернаута дефіас"}},{q="Хто першим винайшов джаґернаут?",a="Стара Орда будувала джаґернаути з допомогою огрів під час Другої війни. Орки мали мало досвіду в мореплавстві, і ці величезні бойові кораблі стали важкою силою їхнього флоту.",al={"хто створив джаґернаути","огрові кораблі лор","походження флоту орди"}},{q="Як корабель вийде з печери Мертвих Копалень?",a="Бухта Айронклад сполучається з відкритими водами Великого Моря прихованим прибережним каналом серед скелястих берегів Вестфолу, тож добудований корабель може вийти просто в океан.",al={"як корабель мертвих копалень піде","вихід залізної бухти","водний вихід мертвих копалень"}},{q="Чи Орда досі використовує джаґернаути?",a="Під час Третьої війни орківські бойові кораблі досі звалися джаґернаутами. Вони давали флотові Орди важку вогневу міць; чи використовують такі судна нині, невідомо.",al={"сучасні джаґернаути орди","бойові кораблі орди"}}},fp="12,390,24.532.0,13.479.1,23.268.0,46.236.1,51.129.1,41.190.0,50.205.1,39.193.0"}
P.entries["topic:kobold"] = {n="Кобольд",s="Кобольди — низькорослі щуроподібні підземні гуманоїди, що снують шахтами й печерами по всьому Азероту. Вони славляться одержимою відданістю лойовим свічкам, прилаштованим на голові; поодинці боягузливі, але небезпечні у зграї, вони люто боронять свої копальні від кожного, хто зазіхає на їхнє світло.",h="Кобольди — низькорослі щуроподібні підземні гуманоїди, що снують шахтами й печерами по всьому Азероту.",kw={"кобольди","свічка","шахти","копальні","ліс елвінн","лох модан","шахта срібного потоку"},ang={["faction:Horde"]="Коли засновували Оргріммар, нори кобольдів під сухою землею наробили чимало безладу на будівництві, а клани на кшталт Ґравелснаутів і досі докучають прикордонним заставам Калімдору.",["profession:Mining"]="Кожен гірник, що працює на землях людей чи дворфів, неминуче натрапить на кубла кобольдів, адже ці істоти самі тягнуться до багатих жил міді, олова й срібла.",["race:Dwarf"]="Ліга Шахтарів раз у раз наймає шукачів пригод, щоб вигнати кобольдів із клану Тунельних Пацюків із гірських копалень, як-от Шахти Срібного Потоку в Лох Модані.",["race:Human"]="Для королівства Стормвінд кобольди — постійний господарський клопіт: вони захопили важливі місцеві копальні — Фарґодіп, Яшмову копальню та Ехо-Рідж."},sec={{t="Шахтарі темряви",b="Заввишки ледве чотири фути, кобольди — брудні підземні збирачі, що все життя вгризаються в землю. Хоч вони й бачать у сутінках, найглибші штольні цілковито темні, тож кожен кобольд прилаштовує собі на голову грубу свічку. Загнаний у кут наодинці кобольд — боягуз, але плодяться вони величезною кількістю й працюють із невтомною енергією. Розлючені, вони несамовито б'ють щурячими хвостами й навалюються на прибульців шаленими юрбами, забиваючи ворогів до смерті важкими залізними кайлами."},{t="Ти не брати свічка!",b="Для кобольда свічка — значно більше, ніж джерело світла: це щит самого існування. Вони відчувають глибокий первісний жах перед непроглядними тунелями, вірячи, що неосвітлена темрява просто поглине їх. Ватажків часто обирають за довжиною свічки, яку ті носять, а майстри збирають вушну сірку й витоплений жир, щоб ґноти не згасали. У кобольдів навіть сонце вважають найвищим міфом — «Свічкою без ґнота», великим вічним вогнем, що висить під склепінням величезної синьої печери."},{t="Підземні шкідники королівств",b="У Східних Королівствах кобольди часто захоплюють промислові копальні. У Лісі Елвінн клан, витіснений із Гір Редріджу — зокрема гнолами Річколапів і Братством Дефіас, — захопив копальні Ехо-Рідж, Фарґодіп і Яшмової копальні. У Лох Модані клан Тунельних Пацюків відібрав у дворфійської Ліги Шахтарів Шахту Срібного Потоку. Навіть у Калімдорі кобольди дошкуляють промисловим розкопкам: працюють на Венчурну Компанію в Горах Кам'яного Кігтя чи відкопують дивні мінерали в Тисячі Голок."}},faq={{q="Чому кобольди так дбають про свої свічки?",a="Кобольди панічно бояться цілковитої темряви. У їхніх переказах темрява — живий хижак, що гасить життя й ковтає шахтарів живцем. Полум'я свічки — їхній єдиний захист від тіньових глибин, тож вони одержимо оберігають свої ґноти.",al={"чому свічки","свічки кобольдів","ти не бери свічку значення"}},{q="Звідки взялися кобольди?",a="За словами дворфійського дослідника Бранна Бронзбірда, кобольди походять від трогів. За покоління пристосування до підземного життя вони стали меншими, схожими на гризунів і навчилися прокопуватися крізь вузькі шпарини.",al={"походження кобольдів","звідки кобольди","еволюція кобольдів"}},{q="Чи кобольди в союзі з Братством Дефіас?",a="Не з власної волі й не як рівні партнери. Кобольдів, що заполонили шахти Лісу Елвінн і Вестфолу, здебільшого залякали й поневолили гноли-Річколапи, яких Братство Дефіас найняло, щоб зірвати видобуток у краї й прибрати до рук його копалини.",al={"кобольди дефіас","чи кобольди працюють на дефіас","фарґодіп дефіас"}},{q="Як кобольди обирають ватажків?",a="Окрім далеких відокремлених племен, кобольди зазвичай визначають провід за розміром свічки. Копача з найвищою, найдовше палаючою свічкою на голові клан визнає вождем.",al={"лідер кобольдів","бос кобольдів","як кобольди обирають вождів"}},{q="Чи є кобольди на Калімдорі, а не лише у Східних Королівствах?",a="Так. Кобольди заполонили підземні печери під Оргріммаром ще тоді, коли місто засновували, працюють у Шахті Зрізаного Вітру Венчурної Компанії в Горах Кам'яного Кігтя й риють нори по всій Тисячі Голок.",al={"кобольди в калімдорі","кам'яний кіготь кобольди","кобольди оргріммара"}},{q="Що їдять кобольди?",a="Кобольди живуть із тієї підземної дрібноти, яку вдається знайти. Вони полюють на щурів і розводять їх, збирають печерних личинок і світні печерні гриби, а іноді пресують гриби в грубі коржики, які їдять із сиропом.",al={"що їдять кобольди","раціон кобольдів"}}},fp="6,328,18.510.0,19.505.0,34.501.0,48.267.0,27.224.0,47.243.0,36.210.0,62.205.0,20.217.0"}
P.entries["topic:lich-king"] = {n="Король-Ліч",s="Король-Ліч — володар і психічний повелитель нежиті Погибелі, що править із Крижаного Трону далеко на півночі, у Крижаній Короні. Цю сутність викував демон Кіл'джеден із духу орка-шамана Нер'жула; згодом вона заманила принца Артаса Менетіла в зіпсуття, і все завершилося їхнім фатальним злиттям на крижаних вершинах Нортренду.",h="Король-Ліч — володар і психічний повелитель нежиті Погибелі, що править із Крижаного Трону далеко на півночі...",kw={"король-ліч","нер'жул","артас менетіл","крижаний трон","погибель","фростморн","кел'тузад","нортренд"},ang={["class:Paladin"]="Орден Срібної Длані розтрощила спотворювальна сила Короля-Ліча, що перетворила його найвизначнішого поборника на лицаря смерті, який убив Утера Світлоносця.",["class:Priest"]="Погибель — похмуре збочення святості Світла, що нагадує служителям святої віри про страшну ціну, сплачену в полеглих парафіях Лордерону.",["race:Human"]="Для людей Король-Ліч — найбільша трагедія: принц Артас, спадкоємець трону Лордерону й паладин Срібної Длані, в ім'я цієї сутності вбив власного батька й знищив своє королівство.",["race:Undead"]="Відступники існують лише тому, що телепатична хватка Короля-Ліча ослабла, і королева Сильвана веде свій народ із палкою ненавистю до колишнього господаря на крижаній півночі."},sec={{t="Народження Крижаного бога",b="Коли орк-шаман Нер'жул спробував утекти з конаючого світу Дренор, він потрапив просто в лапи Кіл'джедена Ошуканця. Повелитель демонів розшматував тіло Нер'жула, а його змучену душу ув'язнив у брилі твердого, мов діамант, льоду, викинутій із Викривленого Нижнього Світу. Шпурнута на Азерот, крижана брила впала в північні пустища Нортренду й утворила Крижаний Трон. Кіл'джеден задумав, що Король-Ліч викує нездоланний авангард нежиті, який зруйнує королівства смертних і не загрузне в чварах, що згубили Орду орків. Натомість Нер'жул, наділений величезною телепатичною силою, одразу почав плекати власні задуми, як вирватися на волю."},{t="Падіння Лордерону",b="Жахолорди пильно стерегли цю сутність, тож Нер'жулові доводилося діяти потай. Простягнувши свій розум, він заволодів вигнаним архімагом Кірін-Тору Кел'Тузадом, і той заснував у Лордероні Культ Проклятих. Через котли із зараженим зерном Погибель поширила по північних королівствах Чуму Нежиття. Ця криза втягнула принца Артаса Менетіла: у відчайдушному прагненні врятувати свій народ він удався до безжальної жорстокості, яка завершилася сумнозвісною різаниною в Стратгольмі. Засліплений жагою помсти жахолордові Мал'Ганісу, Артас погнався за ним до Нортренду, де на нього чекав проклятий рунний клинок Фростморн, щоб украсти його душу й перетворити на першого лицаря смерті Погибелі."},{t="Зрада й піднесення",b="Хоч Королеві-Лічу й довелося закликати Архімонда та тимчасово віддати командування Палаючому Легіону, він передбачав пиху демонів. Артас підштовхнув мисливця на демонів Іллідана Стормрейджа заволодіти Черепом Ґул'дана й убити Тіхондріуса, що зрештою посприяло загибелі Архімонда на Горі Гіджал. Після цього Кіл'джеден у відчаї доручив Іллідану знищити Крижаний Трон. Коли тріщини в крижаному шпилі послабили силу Нер'жула — і Сильвана Віндраннер зі своїми Відступниками вирвалися на волю, — Король-Ліч покликав свого поборника додому. Артас повернувся до Нортренду, переміг Іллідана біля підніжжя Крижаної Корони, піднявся на шпиль і розтрощив лід, щоб злитися з Нер'жулом в одну жахливу свідомість."}},faq={{q="Хто зараз Король-Ліч?",a="Король-Ліч — злита сутність принца Артаса Менетіла й орківського шамана Нер'жула. Артас розбив крижану в'язницю на вершині Крижаного Трону в Крижаній Короні й надів Шолом Панування, поєднавши своє смертне тіло й темну душу з духом Нер'жула в єдиного всевладного володаря Погибелі.",al={"нинішній король-ліч","хто править погибеллю","чи артас король-ліч"}},{q="Навіщо Палаючий Легіон його створив?",a="Кіл'джеден створив Короля-Ліча, щоб послабити захисників Азероту перед повномасштабним демонічним вторгненням. Попереднє вторгнення провалилося через чвари в смертній Орді, а телепатично кероване військо мертвих обіцяло цілковиту покору й повне виснаження смертних армій.",al={"навіщо створили короля-ліча","мета кіл'джедена","походження легіону погибелі"}},{q="Де перебуває Король-Ліч?",a="Він сидить на Крижаному Троні на вершині льодовика Крижаної Корони, глибоко у віддаленому замерзлому континенті Нортренд, далеко за Великим Морем на північ від Лордерона.",al={"де крижаний трон","місцезнаходження короля-ліча","де він живе"}},{q="Як Сильвана вирвалася з-під його влади?",a="Коли Іллідан Стормрейдж ударив по Крижаному Трону могутнім чаклунством, магічний лід тріснув, і сила Короля-Ліча почала витікати. Коли його телепатична хватка послабла, частина нежиті повернула собі вільну волю, згуртувалася довкола Сильвани Віндраннер і заснувала Відступників.",al={"як сильвана вирвалася","як відступники звільнилися","втрата контролю погибеллю"}},{q="Що таке Фростморн?",a="Фростморн — проклятий рунний клинок, що краде душі; його послали з Крижаного Трону, щоб заманити смертного поборника. Він заманив принца Артаса Менетіла заволодіти ним у Нортренді, пожер душу принца й перетворив його на першого серед лицарів смерті Погибелі.",al={"який меч мав артас","лор фростморна","рунний клинок"}},{q="Хто такий Нер'жул?",a="Нер'жул — старий орківський шаман із Дренору. Коли він спробував утекти з гинучого рідного світу крізь розриви вимірів, його схопив демон Кіл'джеден, що здер із нього плоть і перетворив його дух на всевидючу свідомість, яка стала Королем-Лічем.",al={"нер'жул лор","хто такий нер'жул","первісний король-ліч"}}},fp="9,344,23.676.0,21.713.0,24.730.0,31.301.0,38.296.0,31.167.0,45.283.0,20.268.0,17.265.0"}
P.entries["topic:light"] = {n="Світло",s="Світло — безмежна первісна космічна сила, чия енергія поєднує й сповнює все живе у всесвіті. У світі смертних воно проявляється як свята магія й відгукується на силу волі, медитацію та непохитну віру, загоюючи плоть, захищаючи союзників і виганяючи темряву.",h="Світло — безмежна первісна космічна сила, чия енергія поєднує й сповнює все живе у всесвіті.",kw={"світло","святе світло","свята магія","жерці","паладини","елуна","ан'ше"},ang={["class:Paladin"]="Паладини не просто творять заклинання: вони сповнюють Світлом свою бойову дисципліну й смертні тіла, обрушуючи його розпечену лють на Погибель і демонічне зло.",["class:Priest"]="Жерці — духовні пастирі й провідники Світла: глибокою медитацією та молитвою вони загоюють плоть, зміцнюють зламаний дух і захищають союзників.",["faction:Alliance"]="Церква Святого Світла — духовна основа Стормвінда й Айронфорджа, що дарує надію в добу, затьмарену падінням Лордерону.",["race:NightElf"]="Нічні ельфи спрямовують святу енергію не через церковну доктрину, а через шанування місячної богині Елуни та її срібного сяйва.",["race:Tauren"]="Таурени шанують Ан'ше — золоте праве око Земної Матері — у своєму традиційному поклонінні сонцю."},sec={{t="Первісна сила",b="Світло — всюдисущий космічний океан живої енергії, старший за матеріальний всесвіт. У чистому стані, за межею реальності, воно не знає ні злоби, ні доброзичливості й не розрізняє любові та праведної ненависті. Потрапляючи на Азерот, воно проявляється як свята магія. Його сила тече крізь живі душі, мов сполучна тканина, що єднає серця смертних. Хоча смертні часто уявляють його свідомим захисником, насправді Світло відгукується на абсолютну переконаність душі, що до нього звертається."},{t="Знаряддя віри",b="Щоб спрямовувати Світло, потрібні глибоке самозречення, дисциплінована медитація й непохитна сила волі. Його служителі — найвідоміші з них жерці Церкви Святого Світла та святі паладини — роками вчаться ставати чистими, порожніми посудинами для його сяйва. Завдяки їхній відданості Світло проявляється як цілюще тепло, що загоює рани смертних, як сяйні заслони, що прихищають невинних, чи як пекучий вогонь, що вражає демонів і повсталих мерців."},{t="Багато облич сяйва",b="Люди й дворфи шанують Світло через офіційні святі писання, а інші культури прилучаються до його сяйва через власні духовні традиції. Нічні ельфи спрямовують священне місячне сяйво, служачи богині Елуні, і творять святу магію, що очищає й захищає. Таурени ж шанують сонячне божество Ан'ше у своїх власних духовних традиціях."}},faq={{q="Що таке Світло?",a="Світло — фундаментальна космічна енергія, що існує в усьому сущому. Це первісне джерело життя й позитивної енергії, що пов'язує розумні душі. Смертні закликають його, щоб творити святу магію для зцілення, захисту й боротьби.",al={"лор святого світла","що таке святе світло","пояснення світла"}},{q="Чи має Світло власну свідому волю чи розум?",a="Світло — первісна космічна сила, а не бог. Хоча смертні часто говорять про «волю Світла» й вважають його покровителем, що веде їх, моралі смертних воно не має. Воно відгукується безпосередньо на певність, силу волі й віру заклинача.",al={"чи світло живе","чи має світло розум","чи світло бог"}},{q="Чому злі фанатики можуть користуватися Світлом?",a="Бо Світло відгукується на переконання, а не на абстрактну праведність. Якщо заклинач безумовно вірить, що його справа праведна, і дух його не роздвоєний, Світло потече крізь нього — навіть якщо його вчинки безжальні чи хибні.",al={"чому багряні мають світло","чи погані можуть користуватися світлом","злі паладини світло"}},{q="Як Світло діє на нежить?",a="Holy magic is a powerful weapon against the Scourge, but it can also heal undead bodies. Channeling the Light or receiving its healing causes undead intense pain; it does not automatically burn away their flesh.",al={"світло проти нежиті","чому світло шкодить погибелі","чи нежить може користуватися світлом"}},{q="Як жерці й паладини вчаться ним володіти?",a="Володіння Світлом потребує суворої дисципліни розуму, ясності почуттів і років медитації. Заклинач мусить угамувати власне его й цілком зосередити дух, ставши чистим провідником, крізь який свята магія ллється у світ.",al={"як користуватися святою магією","джерело магії паладинів","навчання жреців світла"}},{q="Чи пов'язана магія Елуни зі Світлом?",a="Так. Місячне сяйво, яке спрямовують жриці Елуни, проявляється як різновид святої магії: воно так само зцілює, захищає й очищує, як і чари паладинів і церковних жерців.",al={"чи елуна свята магія","елуна і світло","місячне світло святе світло"}}},fp="5,269,14.536.0,20.457.0,22.350.0,18.240.0,45.257.0,41.245.0,37.211.0,46.251.0,40.214.0"}
P.entries["topic:llane-wrynn-i"] = {n="Ллейн Рінн I",s="Король Ллейн Рінн I правив Стормвіндом під час катастрофічної Першої війни, і його правління скінчилося падінням королівства та його власним трагічним убивством. Улюблений народом і гордий монарх, він уперто не вірив, що його друг Медів зрадив людство, і саме це зрештою прирекло оборону столиці.",h="Король Ллейн Рінн I правив Стормвіндом під час катастрофічної Першої війни, і його правління скінчилося...",kw={"ллейн рінн","король ллейн","стормвінд","перша війна","ґарона","медів","андуїн лотар"},ang={["class:Rogue"]="Убивство короля Ллейна, скоєне вбивцею Ґароною, — один із найвідоміших і найнищівніших ударів клинка в історії Азероту.",["class:Warrior"]="Король Ллейн бився пліч-о-пліч зі своїм Поборником, Андуїном Лотаром, особисто керуючи обороною Стормвінда з передових рубежів Фортеці.",["faction:Alliance"]="Трагічне вбивство короля Ллейна й падіння Стормвінда змусили вцілілих податися на північ, що й спричинило створення Великого Альянсу Лордерону для протидії Орді.",["race:Human"]="Для народу Стормвінда король Ллейн лишається трагічним героєм, чию жертву вшановують у всьому відродженому місті, — зокрема й в імені сина короля Варіана, Андуїна Ллейна Рінна."},sec={{t="Принц нерозважливої відваги",b="Син короля Баратена Рінна, юний принц Ллейн зростав разом з Андуїном Лотаром і Медівом. Коли тролі Ґурубаші почали жорстоко нападати на поселення Вестфолу, Ллейн знехтував оборонною політикою батька й повів своїх товаришів у джунглі Долини Стренглторну, щоб убити воєначальника Джок'нона. Ця зухвала непокора розпалила повномасштабне вторгнення Ґурубаші. Баратен загинув, очоливши відчайдушний контрнаступ під міською брамою, але Медів утрутився й нищівним чаклунством знищив авангард тролів. Після цієї дорогої перемоги Ллейн зійшов на трон Стормвінда."},{t="Перша війна",b="Коли з південних боліт з'явилися загадкові зеленошкірі істоти, король Ллейн відрядив Лотара розвідати Чорне Багно. Дрібні сутички переросли в Першу війну: Орда захопила Світлолісся, Вестфол і Редрідж. Гінців, посланих до Лордерону й інших північних людських королівств, відпроваджували ні з чим — їхні благання підточували давня відособленість Стормвінда й аристократичні інтриги. Попри все це, Ллейн разом із Лотаром організував зухвалий контрнаступ, що прорвав першу облогу Стормвінда Ордою й завдав загарбникам першої великої поразки."},{t="Зрада у Фортеці",b="Зрештою непохитна вдача Ллейна засліпила його перед справжньою небезпекою в найближчому оточенні. Навіть коли учень Медіва Хадґар і посланниця Ґарона відкрили, що Темний Портал відчинив сам Страж, Ллейн не повірив у зраду друга дитинства. Невдовзі Оргрім Думхаммер об'єднав Орду й прорвав зовнішню оборону Стормвінда. Поки Ллейн керував обороною з Фортеці Стормвінда, Ґарона, скорившись чарам Ради Тіней, убила короля в його власній тронній залі, вирізавши йому серце й прирікши місто на загибель."}},faq={{q="Хто такий король Ллейн Рінн I?",a="Король Ллейн Рінн I правив Королівством Стормвінд під час Першої війни. Він був батьком короля Варіана Рінна й дідом юного принца Андуїна Ллейна Рінна. Він загинув, захищаючи свій народ під час першого падіння Стормвінда.",al={"хто такий ллейн","лор ллейна рінна","король ллейн"}},{q="Як загинув король Ллейн?",a="Ллейна вбили у Фортеці Стормвінда під час останньої облоги Першої війни. Його вбила Ґарона Галфорсен, напіворчиха-посланниця, яку він вважав вірним другом і довіреною особою, але чиїм розумом керувала Рада Тіней.",al={"хто вбив короля ллейна","смерть ллейна","як загинув ллейн"}},{q="Які стосунки були в Ллейна з Медівом і Лотаром?",a="Ллейн, Медів і Андуїн Лотар у дитинстві були нерозлучними друзями й разом шукали пригод на півдні Азероту. Їхня довічна дружба обернулася трагедією: Лотар став найвірнішим поборником Ллейна, а цілковита відмова Ллейна повірити, що Медів може його зрадити, призвела монарха до загибелі.",al={"ллейн медів лотар","друзі дитинства ллейна"}},{q="Чому інші людські королівства не допомогли Ллейнові в Першій війні?",a="Стормвінд давно вів відособлену зовнішню політику, яку північні держави вважали зарозумілою. Коли Ллейн попереджав про зеленошкірих загарбників, правителі Лордерона відкидали ці звістки як перебільшення якогось громадянського заколоту, і Стормвінд мусив битися сам.",al={"чому лордерон не допоміг ллейну","альянс у першій війні"}},{q="Як Варіан урятувався під час падіння Стормвінда?",a="Після вбивства короля Ллейна й прориву у Фортецю Стормвінда поборник Андуїн Лотар зібрав уцілілих містян і юного сина Ллейна, принца Варіана Рінна. Лотар привів їх до гавані й утік із ними на північ через Велике Море, до Лордерона.",al={"що сталося з варіаном після ллейна","втеча варіана зі стормвінда"}},{q="Що Медів подарував Ллейнові, коли той дорослішав?",a="Коли Ллейн досяг повноліття як принц Стормвінда, Медів прокинувся від довгого сну й подарував йому зачарований обсидіановий пісковий годинник. Пісок у ньому сипався безкінечно, а верхня колба ніколи не порожніла — на знак вічного процвітання Стормвінда.",al={"подарунок медіва ллейну","пісочний годинник ллейна"}}},fp="13,302,26.609.0,13.604.0,20.575.2,27.240.0,23.242.0,51.289.0,68.270.0,44.249.0,44.253.0"}
P.entries["topic:lordaeron"] = {n="Лордерон",s="Лордерон — великий північний субконтинент Східних Королівств, колись славетне серце людської цивілізації та Альянсу. Після спустошення Третьої війни його колишні королівства лежать у руїнах, а за них змагаються нежить Погибелі, Відступники Сильвани Віндраннер і відчайдушні рештки живих.",h="Лордерон — великий північний субконтинент Східних Королівств, колись славетне серце людської цивілізації та...",kw={"лордерон","чумні землі","андерсіті","тірісфаль","столичне місто","погибель","відступники"},ang={["class:Paladin"]="Орден Срібної Длані народився в Лордероні, у каплиці Алонсуса Фаола. Кожна дорога й руїна цих північних земель просякнута історією перших паладинів.",["faction:Alliance"]="Колись Альянс носив ім'я цього краю. Нині повернення опорних пунктів у Гілсбреді та боротьба з Погибеллю в Чумних Землях — болісна битва за людську спадщину.",["faction:Horde"]="Завдяки союзникам-Відступникам Орда має важливий і спірний плацдарм на півночі Східних Королівств: оточує застави Альянсу й протистоїть решткам Погибелі.",["race:Human"]="Для людей Альянсу Лордерон — священна трагедія. Він був колискою Святого Світла й очільником першого Альянсу, і бачити його зали захопленими нежиттю — невичерпне джерело скорботи й люті.",["race:Undead"]="Колись, за життя, це була ваша батьківщина. Ви ходите зруйнованими дворами Столичного Міста не як заїжджі мандрівники, а як законні спадкоємці Лордерону, що під проводом Леді Сильвани повертають собі своє."},sec={{t="Колиска північного людства",b="Лордерон отримав назву на честь Лордейна — шанованого полководця давньої Імперії Аратор, який віддав життя під час Тролячих війн. Край простягається від суворого Аратійського нагір'я на півдні, через мальовничі ліси й річки, аж до Кель'Таласу на півночі; тут постали квітучі королівства — Лордерон, Даларан, Ґілнеас та Альтерак. Здавна він славився родючими полями Тірісфалю й Гілсбреда, гірськими твердинями та священною колискою Святого Світла."},{t="Погибель і падіння",b="Під час Третьої війни Лордерон став епіцентром вторгнення Короля-Ліча. Через заражене зерно Культ Проклятих перетворив незліченних північан на бездумних мерців-потвор. Принц Артас Менетіл піддався темряві: повернувшись із Нортренду, він убив свого батька, короля Теренаса Менетіла II, і влаштував повну різанину в Столичному Місті. Квітучий край швидко зогнив і перетворився на спотворене жахіття, відоме як Чумні Землі."},{t="Спірна пустка",b="Нині Лордерон — жорстоке поле бою, де вірність розколота. Під руїнами Столичного Міста Леді Сильвана Віндраннер і Відступники облаштували Андерсіті, заснувавши незалежне королівство вільної нежиті в союзі з Ордою. На сході бездумна Погибель Короля-Ліча чіпляється за сплюндровані замки й твердині. А тим часом людські фанатики Багряного Хрестового Походу, вцілілі поселення Альянсу в Гілсбреді та дикі лісові тролі без упину б'ються за те, що лишилося."}},faq={{q="Що таке Лордерон?",a="Лордероном називають і весь північний субконтинент Східних Королівств, і власне колишнє людське королівство, що колись правило його центральними землями. Цей край простягається від Мосту Тандол на кордоні Араті на північ до Кель'Таласу й охоплює гори, ліси й озера.",al={"чи лордерон континент","що означає лордерон","географія лордерона"}},{q="Хто зараз контролює Лордерон?",a="Жодна сила не контролює весь субконтинент. Сильвана Віндраннер і Відступники тримають Галявини Тірісфалю й Срібнолісся зі свого підземного Андерсіті. Погибель зберігає величезну силу в Чумних Землях під проводом Кел'Тузада, а Багряний Хрестовий Похід, союзники Королівства Стормвінд у Гілсбреді та різні тролячі племена тримають окремі прикордонні клапті землі.",al={"хто править лордероном","хто володіє лордероном нині","нинішній правитель лордерона"}},{q="Що сталося з живими людьми Лордерона?",a="Більшість населення Лордерона загинула в Третій війні від чуми нежиття чи війська Погибелі Артаса. Багатьох із тих мерців підняли й поневолили, а згодом вони повернули собі розум і стали Відступниками. Уцілілі живі втекли на південь, до Стормвінда, відпливли на Калімдор із Джайною Праудмур або приєдналися до войовничих громад на кшталт Багряного Хрестового Походу.",al={"куди поділися люди лордерона","чи люди лордерона загинули","що сталося з лордероном"}},{q="Чому субконтинент назвали Лордероном?",a="Його назвали на пам'ять про Лордейна, полководця стародавньої імперії Аратор. Під час давніх Тролячих воєн між людьми, високими ельфами й імперією Амані Лордейн пожертвував собою разом зі своїми воїнами, захищаючи товаришів, і назавжди вкарбував своє ім'я в перекази півночі.",al={"походження назви лордерон","на честь кого лордерон","назва лордейн"}},{q="Де розташоване Столичне Місто Лордерона?",a="Столичне Місто Лордерона стоїть на північному березі Озера Лордамер у Галявинах Тірісфалю. Його вулиці й палацові двори на поверхні лежать у мовчазних руїнах, а розлогі катакомби під ними Сильвана Віндраннер перетворила на Андерсіті — столицю Відступників.",al={"де було місто лордерон","столиця лордерона","розташування руїн лордерона"}},{q="Лордерон належить до Альянсу чи до Орди?",a="За нього точиться запекла боротьба. Історично саме Королівство Лордерон заснувало й очолило первісний Альянс Лордерона. Проте нині Андерсіті — офіційна столиця Орди, тож західний Лордерон став твердинею Орди, а сили Альянсу відчайдушно намагаються втримати свої нечисленні застави в Гілсбреді й Араті.",al={"чи лордерон альянсу чи орди","хто претендує на лордерон"}}},fp="9,314,27.480.0,24.463.0,21.506.0,26.306.0,33.356.0,57.377.0,41.280.0,39.286.0,47.330.0"}
P.entries["topic:mage"] = {n="Маг",s="Маги — вчені чарівники, що змінюють саму тканину реальності, вивчаючи таємну магію: жбурляють нищівний вогонь, керують морозом і чистою таємною енергією. Хоча вони тілесно тендітні й захищені лише тканинним убранням, уміння телепортуватися, створювати речі чарами й стримувати ворогів на полі бою робить їх грізними союзниками й страшними супротивниками. Їхнє мистецтво вимагає величезної розумової відданості: треба врівноважувати колосальну руйнівну силу з пам'яттю про небезпечну історію зловживань таємною магією.",h="Маги — вчені чарівники, що змінюють саму тканину реальності, вивчаючи таємну магію: жбурляють нищівний...",kw={"маг","маги","таємна магія","даларан","кірін-тор","вогонь","мороз","телепортація"},ang={["class:Mage"]="Ваше ремесло — це прискіплива розумова дисципліна: ви опановуєте вогонь, мороз і таємну силу, оберігаючи крихку рівновагу реальності.",["class:Paladin"]="Хоч ви й б'єтеся пліч-о-пліч із магами, Лицарі Срібної Длані здавна ставляться до їхніх світських таємних методів із глибокою пересторогою.",["class:Warlock"]="Багато чорнокнижників починали свій шлях як маги, доки не відкинули академічну стриманість і суворі укази Даларана заради демонічної сили.",["race:Human"]="Таємна спадщина людства сягає першої сотні магів, навчених під час Тролячих війн; їхні нащадки зробили Даларан величним осередком магічної науки.",["race:NightElf"]="Суспільство калдореїв суворо цурається таємної магії, надто добре пам'ятаючи, як королева Азшара та її маги-Високородні накликали руїну на давній Калімдор."},sec={{t="Знавці таємної магії",b="Шлях мага вимагає розуму, зосередженості й років наполегливого навчання. Замість спілкуватися з духами чи покладатися на божественну віру, маги ставляться до магії як до точної космічної науки. Черпаючи таємну енергію, чарівник може сплітати чисту руйнівну силу, викликати пекучі спалахи полум'я чи остуджувати повітря довкола, перетворюючи його на суцільну кригу й виючі хуртовини. Оскільки важкі обладунки заважають тонким рухам рук і зосередженості, потрібним для заклинань, маги носять легку тканину, покладаючись натомість на захисні чари, бар'єри мани й заклинання ухилення."},{t="Спадщина Даларана й Аратору",b="Магічна спадщина людей почалася майже три тисячоліття тому, під час Тролячих війн, коли чарівники високих ельфів навчили сотню людей з Імперії Аратор, щоб переламати хід боротьби проти Амані. Коли людей-чарівників ставало дедалі більше, налякані звичайні городяни змусили багатьох магів заснувати магократію Даларан. Під правлінням Кірін-Тору Даларан став головним сховищем магічних знань північних королівств і впорядкував традиції бойової магії, що згодом підтримала Альянс Лордерону в Першій і Другій війнах."},{t="Підозра й необхідність",b="Чарівникам ніколи не довіряли беззастережно. Від давньої катастрофи, спричиненої Високородними, до нищівного падіння Даларана в Третю війну — непередбачувана природа магії скрізь викликає настороженість. Церква Святого Світла здавна ставилася до чарівництва скептично, а консервативні лицарі часто вважали чарівників проклятими душами чи необхідним злом на полі бою. Попри цю підозру, цивільні й військові очільники визнають, що вправний маг дає неоціненну перевагу в бою, швидко перекидає цілі загони й забезпечує конче потрібний захист від надприродних загроз."}},faq={{q="На яких школах магії спеціалізуються маги?",a="Маги зосереджуються на трьох основних школах: таємній магії, вогні й кризі. Таємна магія змінює час, простір і саму дійсність: дає змогу перетворювати ворогів на тварин, телепортуватися й вивільняти зосереджені спалахи чистої сили. Вогняні чари завдають стрімкої, нищівної шкоди, спопеляючи цілі. Магія криги сповільнює, сковує й розбиває ворогів, допомагаючи тримати бій під контролем і не підпускати їх зблизька.",al={"спеціалізації магів","типи магії магів","тайна вогонь холод"}},{q="Чому маги носять лише тканинний одяг?",a="Складні закляття потребують вільних рухів, точних жестів рук і безперервного зосередження. Важкі матеріали — шкіра, кольчуга чи лати — заважають тілесній частині чарів і плину магічної енергії. Щоб відшкодувати свою фізичну вразливість, маги вдаються до магічних бар'єрів, крижаних щитів і заклять, що тримають ворогів на відстані.",al={"чому тканина","тип броні мага","чи можуть маги носити шкіру"}},{q="Як люди вперше навчилися таємної магії?",a="Під час давніх Тролячих воєн, приблизно 2800 років тому, людська імперія Аратор уклала союз із високими ельфами Кель'Таласу проти тролів Амані. В обмін на військову допомогу ельфійські маги навчили сотню людей основ таємної магії. Ця перша сотня виявилася нищівною в бою й започаткувала людську магічну традицію, що зрештою заснувала Даларан.",al={"перші людські маги","маги війн тролів","походження людської магії"}},{q="Які стосунки між магами й Церквою Святого Світла?",a="Напружені. Століттями правовірні члени Церкви Святого Світла ставилися до таємних наук і Кірін-Тору з підозрою, часом вважаючи їх єрессю. Паладини й побожні жерці часто вважають чародійство непередбачуваним і морально сумнівним заняттям, хоча й миряться з ним із потреби через його стратегічну воєнну силу.",al={"погляд церкви на магів","паладини й маги","святе світло та аркана єресь"}},{q="Чи маги Стормвінда належать до Кірін-Тору Даларану?",a="Історично Стормвінд мав власні традиції: спершу ними керували придворні чарівники, що діяли здебільшого незалежно від Даларану. Даларанський Кірін-Тор був незаперечним осередком магічної науки на півночі, а південні чарівники створили власні громади й посіли місця королівських радників, проте зв'язки між обома краями не переривалися.",al={"маги стормвінда й даларан","чародії азероту","чарівники стормвінда"}},{q="Чи можуть маги створювати їжу й миттєво переносити людей?",a="Так. Окрім руйнівних заклять, маги володіють широким набором корисної магії. Вони можуть сплітати таємну енергію, щоб творити свіжу їжу й воду просто з повітря, посилювати розум союзників і згинати простір, миттєво відкриваючи портали до великих міст світу.",al={"корисні заклинання магів","портали магів","створення води й їжі"}}},fp="4,472,22.574.0,33.567.0,23.632.0,45.398.0,35.380.0,48.389.0,72.354.0,50.349.0,53.257.0"}
P.entries["topic:medivh"] = {n="Медів",s="Медів — останній Страж Тірісфалю, давнього ордену, покликаного боронити Азерот від демонічного зіпсуття. Ще до народження його поневолив дух Темного Титана Саргераса, і саме Медів відчинив Темний Портал і привів у світ Орду орків, розв'язавши десятиліття катастрофічних воєн.",h="Медів — останній Страж Тірісфалю, давнього ордену, покликаного боронити Азерот від демонічного зіпсуття.",kw={"медів","страж тірісфалю","каражан","саргерас","темний портал","пророк","еґвінн"},ang={["class:Mage"]="Медів уособлює і вершину, і найбільшу небезпеку таємного мистецтва: кожен учений Кірін-Тору вивчає його катастрофічне падіння як застереження про неприборкану силу.",["class:Warlock"]="Зв'язок Медіва з Ґул'даном і його роль смертного провідника Саргераса досі лишаються легендарними прикладами заклику Скверни й маніпуляцій між світами.",["faction:Alliance"]="Народ Стормвінда згадує Медіва з гірким сумом — як улюбленого королівського товариша, що зрештою накликав на їхні землі згубну Орду.",["faction:Horde"]="Для Орди Тралла Медів — людський чаклун, чия угода з Ґул'даном відчинила Темний Портал і вперше привела орків у цей світ."},sec={{t="Проклята спадщина",b="Медів народився від могутньої Стражниці Еґвінн і придворного чарівника Ніеласа Арана. Століттями раніше Еґвінн билася з полеглим Титаном Саргерасом у Нортренді, не відаючи, що його темна сутність прослизнула в її тіло, щоб дочекатися спадкоємця. Коли Медівові виповнилося чотирнадцять, величезна магічна спадщина, передана матір'ю, вибухнула жахливим спалахом сили, і хлопець на ціле десятиліття поринув у кому під наглядом кліриків Абатства Нортшира."},{t="Падіння Каражана",b="Прокинувшись, Медів оселився у відлюдній вежі Каражан і став придворним магом свого друга дитинства, короля Стормвінда Ллейна Рінна. Та темний дух усередині нього поволі підточував його розум. Прагнучи сіяти руйнацію, Медів крізь зорі зв'язався з орком-чорнокнижником Ґул'даном і Радою Тіней. Разом вони спрямували величезну магічну силу й розірвали простір, відчинивши Темний Портал: так Орда прийшла до Східних Королівств, і спалахнула Перша війна. Зрештою Медіва вбили в його ж вежі найближчий друг, Андуїн Лотар, і його учень Хадґар."},{t="Спокута Пророка",b="Смерть смертного тіла звільнила Медіва від Саргераса, і він повернувся з-за межі смерті, щоб спокутувати свої злочини. Під час Третьої війни він постав у подобі загадкового Пророка в плащі з воронячого пір'я й нашіптував королю Теренасу Менетілу та Вождю Траллу застереження про повернення Палаючого Легіону. Лордерон знехтував його благаннями, але Пророк повів Орду Тралла й біженців Джайни Праудмур через Велике Море до Калімдору, об'єднав орків, людей і нічних ельфів для вирішального бою на Горі Гіджал, а тоді розчинився в легендах."}},faq={{q="Хто такий Медів?",a="Медів був останнім людським Хранителем Тірісфалю, наділеним величезною таємною силою, щоб захищати Азерот. Він був сином Маґни Аеґвінн і задумав відкриття Темного Порталу.",al={"хто такий медів","лор медіва","останній охоронець"}},{q="Чому Медів відкрив Темний Портал?",a="Ще до народження Медівом заволодів дух Темного Титана Саргераса. Під цим лиховісним впливом він уклав угоду з чорнокнижником Ґул'даном: пообіцяв відкрити йому, де лежить Гробниця Саргераса, якщо Орда вторгнеться в Азерот і зруйнує королівства смертних.",al={"чому медів відкрив темний портал","медів зрадив стормвінд","навіщо привів орків"}},{q="Хто вбив Медіва?",a="Під час Першої війни в Каражані з Медівом зійшлися його близький друг Андуїн Лотар, учень Хадґар і напіворчиха-вбивця Ґарона. Хадґар пронизав серце Медіва, а Лотар відтяв йому голову, обірвавши його життя й відкинувши дух Саргераса назад у Викривлений Нижній Світ.",al={"як помер медів","хто вбив охоронця","смерть медіва"}},{q="Які стосунки були в Медіва з королівською родиною Стормвінда?",a="Медів виріс разом із принцом Ллейном Рінном і Андуїном Лотаром при королівському дворі Стормвінда. Замолоду ця трійця пліч-о-пліч билася з тролями Ґурубаші, а король Ллейн цілковито довіряв Медіву, тож його зрада стала для королівства нищівним ударом.",al={"медів і ллейн","чи медів був другом лотара"}},{q="Чи Медів досі живий?",a="Допомігши смертним расам перемогти Архімонда в Битві за Гору Гіджал, Медів пішов, щоб посісти своє місце серед легенд минулого. Де він відтоді — невідомо.",al={"де медів тепер","чи медів пророк","статус медіва"}},{q="Що таке Каражан?",a="Каражан — вежа, зведена на могутньому перетині силових ліній на Перевалі Мертвого Вітру. Її заснувала Аеґвінн, а згодом успадкував Медів. Після падіння Хранителя вежу сильно викривили таємна й демонічна енергія, і вона досі стоїть моторошною руїною.",al={"вежа медіва","що сталося з каражаном"}}},fp="6,299,17.469.0,20.596.0,24.506.1,15.190.0,36.274.0,18.276.0,56.263.0,22.183.1,17.269.0"}
P.entries["topic:mor-ladim"] = {n="Мор'Ладім",s="Мор'Ладім — небезпечний і мстивий воїн-скелет, що блукає Цвинтарем Воронячого Пагорба в Сутінколіссі. Колись він був шляхетним лицарем Морганом Ладімором, але, дізнавшись про загибель родини, збожеволів від горя й повстав у нежитті, щоб убивати кожного, хто трапиться йому на шляху.",h="Мор'Ладім — небезпечний і мстивий воїн-скелет, що блукає Цвинтарем Воронячого Пагорба в Сутінколіссі.",kw={"мор'ладім","морган ладімор","воронячий пагорб","сутінколісся","лицар срібної длані","нежить","даркшир"},ang={["class:Paladin"]="Колись Морган Ладімор був шляхетним воїном Світла й бився пліч-о-пліч з Утером Світлоносцем. Його падіння показує, як страшно дозволити скорботі й гніву затьмарити священні обітниці.",["faction:Alliance"]="Трагічна доля Моргана Ладімора — похмуре нагадування про те, як глибоко Третя війна розхитала південні королівства на кшталт Стормвінда: ветерани поверталися додому до зруйнованих родин."},sec={{t="Лицар Срібної Длані",b="Перш ніж стати жахом Воронячого Пагорба, Мор'Ладім жив як Морган Ладімор — відданий лицар і захисник беззахисних із Великого Селища, містечка, що нині зветься Даркширом. У вісімнадцять років він одружився з Ліс, і вони в мирі виховували трьох дітей, доки війна не покликала його на північ. Під час Третьої війни Морган вирушив до Лордерону пліч-о-пліч з Утером Світлоносцем і на власні очі побачив занепад Лицарів Срібної Длані, поширення чуми Кел'Тузада та трагічну загибель самого Утера."},{t="Падіння Моргана Ладімора",b="Повернувшись додому після війни, Морган побачив, що Сутінколісся поглинула темрява, а його садиба лежить у руїнах. Щось погнало його до Цвинтаря Воронячого Пагорба, і там, серед надгробків, він знайшов могили Ліс і двох їхніх дітей. Охоплений горем і люттю, Морган кинувся трощити надгробки. Коли доглядачі цвинтаря спробували його вгамувати, лицар у сліпому шалі порубав їх. А коли розум повернувся до нього, нажаханий власним злочином Морган встромив меч собі в серце. Присоромлені містяни поховали його тіло без жодного знаку, у віддаленому кутку цвинтаря."},{t="Гроза Воронячого Пагорба",b="Поховання не принесло Морганові спокою. Скуті тяжкою провиною за пролиту невинну кров і задушливим горем, його спотворені рештки піднялися з землі велетенським скелетом-ревенантом. Мандрівники й вартові Нічної Варти прозвали його Мор'Ладімом і швидко навчилися боятися цього імені. З родовим мечем Археусом у руках бездумний привид обходить оповиті туманом могили й рубає і звірів, і необачних шукачів пригод, що підходять надто близько до місця його спочинку."}},faq={{q="Ким був Мор'Ладім за життя?",a="Мор'Ладім колись звався Морган Ладімор — шляхетний паладин і лицар із Великого Селища, що бився пліч-о-пліч з Утером Світлоносцем під час Третьої війни в Лордероні.",al={"хто такий мор'ладім","історія мор'ладіма","лор моргана ладімора","ким був мор'ладім"}},{q="Чому Мор'Ладім ворожий?",a="Морган збожеволів від горя, знайшовши могили своєї родини. Він перебив невинних доглядачів цвинтаря й наклав на себе руки, а його душу ув'язнили провина й мука, ожививши тіло як кровожерну нежить.",al={"чому мор'ладім нападає","чому він злий","божевілля мор'ладіма"}},{q="Де блукає Мор'Ладім?",a="Він обходить розлогі стежки й склепи Цвинтаря Воронячого Пагорба на заході Сутінколісся і, бо маршрут у нього довгий, часто заскочує мандрівників зненацька.",al={"шлях мор'ладіма","де знайти мор'ладіма","місцезнаходження мор'ладіма"}},{q="Чи вся родина Моргана Ладімора загинула?",a="Ні. Його дружина Ліс і двоє дітей загинули, але третя дитина пережила занепад Сутінколісся — цього Морган у сліпому відчаї на цвинтарі зовсім не помітив.",al={"чи родина ладімора вціліла","донька моргана ладімора","хто вцілів із ладіморів"}},{q="Що за зброю носить Мор'Ладім?",a="Мор'Ладім володіє Археусом — добрим клинком, що вірно служив йому, лицареві, за життя, а в нежитті став знаряддям різанини.",al={"меч мор'ладіма","меч арцеус","який меч у мор'ладіма"}},{q="Хто хоче знищити Мор'Ладіма?",a="Командир Алтея Ебонлок і Нічна Варта Даркшира прагнуть його знищити, щоб захистити патрулі й мандрівників від його невпинних нападів на заході Сутінколісся.",al={"хто хоче вбити мор'ладіма","нічна варта мор'ладім","алтея ебонлок мор'ладім"}}},fp="9,293,27.494.0,27.585.1,25.457.0,26.170.1,25.238.1,26.161.0,40.171.1,37.156.1,30.172.0"}
P.entries["topic:muradin-bronzebeard"] = {n="Мурадін Бронзбірд",s="Мурадін Бронзбірд — брат Короля Маґні Бронзбірда й Бранна Бронзбірда, славетний воїн, дипломат і один із засновників Ліги Дослідників. Його шанували і в Каз Модані, і в Лордероні, а загинув він, як вважають, у крижаних пустках Нортренду, коли принц Артас Менетіл здобув проклятий рунічний меч Фростморн.",h="Мурадін Бронзбірд — брат Короля Маґні Бронзбірда й Бранна Бронзбірда, славетний воїн, дипломат і один із...",kw={"мурадін бронзбірд","маґні бронзбірд","ліга дослідників","нортренд","артас","фростморн","айронфордж"},ang={["class:Warrior"]="Мурадіна вважали одним із найкращих дворфійських дуелянтів і майстрів зброї свого часу — він сам навчав принца Артаса Менетіла мистецтва клинка.",["faction:Alliance"]="Мурадін викував товариські узи між Айронфорджем і північними людськими королівствами й став одним із героїв-засновників Альянсу.",["race:Dwarf"]="Дворфи Айронфорджа пам'ятають Мурадіна як взірець свого народу — хороброго, безмежно вірного, якого вела ненаситна цікавість до історії своїх творців."},sec={{t="Брат і посол",b="Мурадін вславився в Другій війні як важлива сполучна ланка між гірськими залами Каз Модану й Альянсом Лордерона. Він допоміг утримати Айронфордж під час облоги Орди й пройшов разом із силами Альянсу аж крізь Шпиль Блекрок до Темного Порталу. У мирні роки, що настали потім, Мурадін оселився в Столичному місті як офіційний посол Айронфорджа. Веселий, але грізний, він став невіддільною частиною палацу: зблизився з королем Теренасом Менетілом, підкорив серця королівських кухарів і взявся навчати юного принца Артаса фехтування й бойового мистецтва."},{t="Ліга Дослідників і Нортренд",b="Крім політики й війни, Мурадіна вирізняла невгамовна цікавість. Разом із братами він заснував дворфійську Лігу Дослідників, що мала шукати втрачені реліквії титанів і описувати найдальші закутки світу. Він закохався в пустельний, обвітрений континент Нортренд і часто вирушав на північ, щоб замальовувати давню архітектуру й описувати його лютих мешканців. Саме суворі таємниці Нортренду зрештою покликали його в останню експедицію — на пошуки переказів, реліквій і пошепки переказуваної легенди про забутий рунічний меч."},{t="Здобуття Фростморна",b="Коли принц Артас прибув до Нортренду, одержимий полюванням на жахолорда Мал'Ганіса, він знову зустрівся з Мурадіном і залучив його дворфійську експедицію. Артас прагнув сили Фростморна, щоб переламати хід війни, і не зважав на дедалі більшу тривогу Мурадіна, коли принц зрадив власних найманців і відкинув будь-яку честь. Біля вівтаря Фростморна Мурадін прочитав застереження, вирізьблене на крижаному постаменті, і благав колишнього учня повернути назад. Артас відмовився. Коли принц схопив рунічний меч, вибух нечестивого льоду збив Мурадіна з ніг, і той лишився лежати на підлозі печери, мабуть, мертвий."}},faq={{q="Хто такий Мурадін Бронзбірд?",a="Мурадін Бронзбірд — середній брат короля Маґні Бронзбірда й дослідника Бранна. Він був героєм-ветераном Другої війни, послом Айронфорджа в Лордероні й одним із засновників Ліги Дослідників.",al={"хто такий мурадін","лор мурадіна","брат маґні мурадін"}},{q="Що сталося з Мурадіном у Нортренді?",a="Мурадін супроводжував принца Артаса до печери з Фростморном. Коли Артас знехтував застереженнями Мурадіна й розбив крижану в'язницю рунного клинка, уламок зачарованого льоду від вибуху влучив у Мурадіна, і той, здавалося, загинув на місці. Артас покинув його тіло й забрав клинок.",al={"як помер мурадін","смерть мурадіна","чи артас убив мурадіна"}},{q="Які стосунки були в Мурадіна з принцом Артасом?",a="Служачи послом Айронфорджа в Столичному Місті, Мурадін узяв Артаса під свою опіку. Він навчав юного принца бою на мечах і пережив із ним чимало пригод, бачачи в Артасі майже названого сина чи улюбленого небожа, — аж до темного падіння Артаса в Нортренді.",al={"чи мурадін знав артаса","мурадін учитель артаса","мурадін і артас"}},{q="Яку роль Мурадін відіграв у Другій війні?",a="Мурадін був посередником Альянсу між Лордероном і Каз Моданом. Він обороняв Айронфордж під час облоги Орди, а потім рушив на південь з об'єднаним військом Альянсу, щоб битися біля Шпиля Блекрок і Темного Порталу.",al={"мурадін друга війна","битви мурадіна","чи мурадін воював проти орди"}},{q="Навіщо Мурадін узагалі вирушив до Нортренду?",a="Як засновника Ліги Дослідників, Мурадіна глибоко захоплювали археологія й прадавні руїни Нортренду. Він повернувся туди з експедицією, щоб розкрити забуту історію й пошукати реліквії, і зрештою натрапив на слід Фростморна.",al={"чому мурадін у нортренді","експедиція мурадіна","що шукав мурадін"}},{q="Як король Маґні сприйняв смерть Мурадіна?",a="Утрата Мурадіна вразила короля Маґні й увесь клан Бронзбірд. Удавана смерть Мурадіна обірвала колись теплі стосунки між Айронфорджем і принцом Артасом, а горе переросло в гірку лють проти Погибелі.",al={"реакція маґні на мурадіна","горе айронфорджа за мурадіном"}}},fp="19,345,24.628.0,35.562.0,27.596.1,28.218.0,38.295.0,51.278.0,42.218.0,51.255.0,44.218.0"}
P.entries["topic:murloc"] = {n="Мурлок",s="Мурлоки — земноводні двоногі гуманоїди, відомі булькотливими бойовими вигуками, ревно оберіганими прибережними селищами й раптовими нападами цілою зграєю. Хоча здавна вони жили в глибинах океану, дедалі більше мурлоків просувається вглиб суходолу вздовж узбереж, озер і річок Азероту, діючи значно злагодженіше й хитріше, ніж можна подумати з їхнього первісного вигляду.",h="Мурлоки — земноводні двоногі гуманоїди, відомі булькотливими бойовими вигуками, ревно оберіганими...",kw={"мурлоки","мурлок","наги","темний спис","узбережжя","бранн бронзбірд"},ang={["class:Shaman"]="Містики мурлоків мають вроджений, хоч і грубий, зв'язок з елементалями води й землі та підкоряють місцевих духів, щоб зміцнити свої прибережні селища.",["faction:Alliance"]="Поселенці у Вестфолі, на Темному Узбережжі й у Лейкширі раз у раз бачать, як мурлоки, що просуваються вглиб суходолу, беруть в облогу їхні кораблі, ферми й пристані.",["race:Troll"]="У племені Темного Списа гірка історія з мурлоками: ще до приєднання до Вождя Тралла прибережні племена брали тролів у полон і приносили в ритуальні жертви."},sec={{t="Істоти мілководдя",b="Мурлоки живуть у густонаселених селищах уздовж морських узбереж, річкових берегів і прісних озер. Заввишки в середньому близько чотирьох футів, вони мають опуклі, вкриті слизом тіла, широкі пащі, повні гострих іклів, і пильний зір, що пронизує непроглядну воду. Поодинокого мурлока рідко побачиш далеко від родичів: де з'явився один, там під поверхнею неодмінно чатує ще з десяток. Вони покладаються на переважну кількість і гостру грубу зброю."},{t="Похід углиб суходолу",b="Хоча давні родоводи свідчать, що мурлоки жили під хвилями ще до початку писаної історії, їхнє масове просування на землі Лордерону й Калімдору почалося відносно недавно. Історики зауважують, що це переселення підозріло збіглося з поверненням змієподібних наг із глибин океану. Деякі племена, схоже, поклоняються глибоководним потворам, що чекають в океанських безоднях. Чи то вони тікають від темніших жахів, чи то готують світ до пробудження своїх господарів — злагоджений наступ мурлоків на прісні води становить дедалі більшу загрозу."},{t="Прихований розум",b="Оскільки їхня невиразна мова звучить для чужинців як безглузде булькотіння, багато хто вважає мурлоків просто дикими шкідниками. Проте злагоджені засідки, опанування магії землі й води та громадський устрій свідчать про гостріший розум. Славетний дослідник Бранн Бронзбірд припускав, що мурлоки набагато розумніші, ніж гадають цивілізовані раси, і навмисно приховують свою кмітливість. Їхній вплив на світову історію незаперечний: саме напад мурлоків на плем'я Темного Списа спонукав Тралла втрутитися, і так постав союз орків і тролів, що збудував сучасну Орду."}},faq={{q="Чому мурлоки нападають усі разом?",a="Мурлоки рідко б'ються поодинці. Вони живуть тісними, людними поселеннями й відповідають на вторгнення гуртом, засипаючи ворогів переважною кількістю.",al={"мурлоки нападають юрбою","чому мурлоки збираються","агро мурлоків"}},{q="Чи мурлоки справді розумні?",a="Так, набагато розумніші, ніж свідчить їхній кумедний вигляд. Хоча їхнє гортанне булькотіння більшості незрозуміле, мурлоки виготовляють зброю, влаштовують продумані засідки й володіють стихійною магією води й землі. Учені на кшталт Бранна Бронзбірда вважають, що мурлоки навмисно дають чужинцям недооцінювати свій розум.",al={"чи мурлоки розумні","розум мурлоків","чи думають мурлоки"}},{q="Чому мурлоки просуваються з моря вглиб суходолу?",a="Спочатку мурлоки жили на дні океану, але поступово просунулися в прісні озера й річища. Історики підозрюють, що це переселення спричинило відродження наг чи глибоководні сутності, що дрімають у безодні й, пробуджуючись, наказують мурлокам захоплювати суходіл.",al={"чому мурлоки на суші","міграція мурлоків","чому мурлоки скрізь"}},{q="Як мурлоки допомогли створити Орду?",a="Під час Третьої війни плем'я мурлоків, що служило морській відьмі Зар'джирі, напало на тролів Темного Списа на їхньому острові. Вождь Тралл і його орки-воїни билися пліч-о-пліч із Сен'джином, захищаючи тролів. Ця битва скувала нерозривний зв'язок між орками й племенем Темного Списа й заклала підвалини сучасної Орди.",al={"орда й мурлоки","мурлоки темного списа","острів мурлоків тралла"}},{q="Хто такі мур'гули?",a="Мур'гули — мурлоки, з якими стикалися під час Третьої війни. Попри дивний вигляд і назву, це живі істоти.",al={"мур'гули","мурлоки третьої війни","хто такі мур'гули"}},{q="Що це за впізнаваний звук, який видають мурлоки?",a="Кидаючись на здобич чи здіймаючи тривогу, мурлоки видають гучне, мокре, переливчасте булькотіння (його часто записують як «Ааааауґгіббрґубуґбуґрґубурґл» чи «Рвл-рвл-рвл-рвл»). Це водночас і агресивна психологічна зброя, і миттєвий поклик, що скликає зграю.",al={"звук мурлоків","бойовий клич мурлоків","рвлрвлрвл"}}},fp="6,362,25.481.0,16.568.0,18.596.0,34.152.0,33.327.0,43.287.0,36.328.0,17.123.0,39.259.0"}
P.entries["topic:naga"] = {n="Наги",s="Наги — потворна змієподібна раса, що живе в глибинах океану під владою своєї давньої імператриці, королеви Азшари. Колись вони були елітою Високородних в Імперії Калдореїв, але десять тисяч років тому, під час Великого Розколу, перетворилися на земноводних потвор. Нещодавно вони вийшли з темних вод і захопили узбережжя Калімдору та Східних Королівств, щоб повернути свою забуту імперію на суходолі.",h="Наги — потворна змієподібна раса, що живе в глибинах океану під владою своєї давньої імператриці, королеви...",kw={"наги","азшара","назджатар","леді вашж","високородні","морська відьма","древні боги"},ang={["faction:Alliance"]="Альянс пам'ятає наг із руїн Даларана, де створіння Леді Вашж брали вцілілих у полон і посіяли розбрат між ельфами крові та військами великого маршала Ґарітоса.",["faction:Horde"]="Тралл і Орда відбивалися від нападників-наг від Островів Темного Списа до берегів Багна Пилоброду, де Леді Даркскейл вирізала людські поселення й нападала на околиці Дуротару.",["race:NightElf"]="Для нічних ельфів наги — потворне й болісне нагадування про пиху Високородних, що розтрощила Давній Калімдор. Бачити, як колишній двір Азшари виповзає на береги Темного Узбережжя й Ашенвалю, — гіркий заклик очистити світ від своїх давніх родичів.",["race:Troll"]="Тролі Темного Списа люто ненавидять наг відтоді, як під час плавання Великим Морем морська відьма Зар'джира вигнала їх із рідного острова; той напад забрав життя їхнього старого вождя Сен'джина."},sec={{t="Падіння Високородних",b="Десять тисячоліть тому знать Високородних правила Імперією Калдореїв зі своєї величної столиці Зін-Азшарі. Охоплені одержимістю таємною силою, королева Азшара та її найближчий двір черпали з Колодязя Вічності, щоб привернути погляд Темного Титана Саргераса, і накликали катастрофічне вторгнення, відоме як Війна Прадавніх. Коли Колодязь Вічності зруйнувався й спричинив Великий Розкол, палац поринув у нищівну безодню. Опинившись на межі цілковитої загибелі, Азшара уклала угоду зі злісними Древніми Богами в глибинах. Ціною виживання вона та її послідовники стали холодними, лускатими змієподібними істотами, прикутими до глибин."},{t="Глибини Назджатару",b="На морському дні, під шаленим Виром, уцілілі звели підводну імперію Назджатар. Плекаючи десятитисячолітню образу на світ суходолу, наги зберегли пиху Високородних, водночас змутувавши в окремі касти: кремезних, схожих на звірів воїнів і багаторуких морських відьом, що плетуть чари. Під невблаганним поглядом Азшари вони досконало опанували владу над морськими істотами, магію бурі та крижане чаклунство й поволі відновлювали сили, чекаючи нагоди вдарити по мешканцях суходолу."},{t="Повернення на поверхню",b="Наги порушили свою десятитисячолітню мовчанку під час Третьої війни. Орда Тралла вперше зіткнулася з морською відьмою Зар'джирою у Великому Морі, а Леді Вашж відгукнулася на заклик Іллідана Стормрейджа й повела загони наг руїнами Даларана. Нині табори наг напористо підступають до узбереж Азшари, Темного Узбережжя, Ашенвалю, Пустограю, Фераласу, Багна Пилоброду, Гілсбреда, Араті та Стренглторну. Ведені давньою зневагою й шепотом Древніх Богів, вони потай укладають союзи з Молотом Присмерку й лютими сатирами, щоб повернути те, що колись належало їм."}},faq={{q="Ким були наги до перетворення?",a="Колись наги були Високородними — аристократичною верхівкою стародавньої імперії нічних ельфів. Десять тисяч років тому, під час Великого Розколу, що знищив Колодязь Вічності, королева Азшара та її придворні тонули в морі, що обвалювалося. Древні Боги запропонували їм порятунок, перетворивши їхні тіла на зміїподібних водяних потвор.",al={"ким були наги","хто такі наги","походження наг"}},{q="Хто править нагами?",a="Нагами одноосібно править королева Азшара, колишня імператриця калдореїв. Зі свого підводного міста Назджатар під Виром вона керує морськими відьмами й воїнами. Навіть після тисячоліть потворного перетворення наги шанують її з фанатичною відданістю.",al={"лідер наг","королева наг","хто править нагами"}},{q="Чому наги зараз нападають на пляжі й узбережжя?",a="Десять тисячоліть ховаючись під хвилями, наги знову з'явилися під час Третьої війни. Вони вірять, що весь стародавній Калімдор по праву належить їм як справжнім спадкоємцям імперії калдореїв. Під проводом королеви Азшари й Древніх Богів вони прагнуть підкорити прибережні землі й завоювати раси поверхні.",al={"чому наги на суші","вторгнення наг","чому наги повернулися"}},{q="Чому наги-чоловіки й наги-жінки такі різні?",a="У суспільстві наг різко виражений статевий диморфізм. Жінки-наги зберегли розумову й магічну хитрість своїх предків-Високородних; часто вони мають чотири руки й величезний хист до таємної, крижаної й штормової магії. Чоловіки-наги більші — кремезні громили, вкриті важкою лускою й плавцями, створені передусім для бою й грубої сили.",al={"чоловіки й жінки наги","різниця наг","морські відьми наги"}},{q="Які стосунки між нагами й Ілліданом Стормрейджем?",a="Після Третьої війни Іллідан могутньою магією прикликав союзників із морських глибин. Леді Вашж відгукнулася з військом наг, шануючи давні зв'язки Високородних і потай виконуючи волю Древніх Богів, які хотіли розхитати світ поверхні. Наги допомагали Ілліданові на Розколотих Островах, у Лордероні й далі.",al={"чому наги допомагали ілліданові","іллідан і наги","леді ваш іллідан"}},{q="Де зараз можна натрапити на наг?",a="Наги тримають плацдарми на багатьох узбережжях. На Калімдорі вони кишма кишать в Азшарі, на Темному Узбережжі, в Ашенвалі, Пустограї, Фераласі й Багні Пилоброду. У Східних Королівствах їхні загони й вівтарі можна знайти на берегах Передгір'їв Гілсбреда, Аратійського нагір'я й Долини Стренглторну.",al={"де наги","місця наг","зони наг"}}},fp="4,418,21.669.0,18.551.0,15.600.0,48.346.0,19.289.0,50.333.0,46.348.0,64.323.0,40.311.0"}
P.entries["topic:new-horde"] = {n="Нова Орда",s="Нова Орда — сучасний союз, викуваний під проводом Вождя Тралла, що відмежувався від кровожерливої, зіпсованої демонами Старої Орди часів Першої й Другої воєн. Заснована на шаманських традиціях, честі та спільному виживанні, вона об'єднує звільнених орків, тролів Темного Списа, племена тауренів Калімдору й тримає хиткий союз із Відступниками в Лордероні.",h="Нова Орда — сучасний союз, викуваний під проводом Вождя Тралла, що відмежувався від кровожерливої, зіпсованої...",kw={"нова орда","тралл","орки","оргріммар","дуротар","шаманство","стара орда"},ang={["class:Shaman"]="Шаманство — духовний хребет Нової Орди: воно відроджує давні традиції, що єднають смертних зі стихіями й ледь не загинули за часів демонічного зіпсуття.",["faction:Alliance"]="Багато хто в Альянсі досі дивиться на Нову Орду крізь криваві спогади Першої й Другої воєн і не може повірити, що орки здатні зректися свого жорстокого минулого.",["faction:Horde"]="Нова Орда — прихисток для вигнанців. Членство в ній дає спільний захист, збереження культури й спільну присягу честі під проводом Вождя Тралла.",["race:Orc"]="Нова Орда — це спокута: нагода струсити млявість таборів інтернування, вшанувати жертву Ґрома Хеллскріма й жити вільними воїнами-шаманами."},sec={{t="Відроджена спадщина",b="Первісна Орда була зброєю, яку викували Палаючий Легіон і Рада Тіней: вони сповнили орків демонічною жагою крові й погнали крізь Темний Портал. Коли Друга війна скінчилася розгромом, уцілілих орків зігнали до таборів інтернування Альянсу, де вони поринули в млявість, що висисала душу. Зусиллями Оргріма Думхаммера, Ґроммаша Хеллскріма та юного шамана Тралла орки скинули демонічні кайдани, знову відкрили шаманство предків і вибороли собі свободу."},{t="Через Велике Море",b="Дослухавшись до пророчих видінь загадкового Пророка, Тралл повів свій народ через Велике Море до неприборканого континенту Калімдор. Дорогою Орда прийняла тролів Темного Списа на чолі з Сен'джином, що втратили домівку. Прибувши до Калімдору, Тралл уклав союз із Кайрном Бладгуфом і кочовими тауренами та допоміг відкинути ворожі племена кентаврів. Разом ці різні народи билися пліч-о-пліч із людьми й нічними ельфами на Горі Гіджал, зламали вторгнення Палаючого Легіону й вибороли собі новий дім — Дуротар."},{t="Сучасний союз",b="Нині Нова Орда прагне збудувати міцне суспільство зі своєї укріпленої столиці Оргріммара. Її опора — тісні узи між орками, тролями Темного Списа й тауренами, але задля виживання Траллові довелося піти й на незручні союзи — передусім із Сильваною Віндраннер і Відступниками в руїнах Лордерону. Тралл прагне хиткого миру з Альянсом, але давня ворожнеча, брак ресурсів і войовничі сили в обох фракціях тримають кордони на межі війни."}},faq={{q="Чим Нова Орда відрізняється від Старої?",a="Старою Ордою під час Першої і Другої воєн правили демонічне спотворення, темні чорнокнижники й жорстоке завоювання. Нова Орда, заснована Траллом, відверто відкинула Палаючий Легіон, відродила втрачене шаманське коріння орків і ставить на чільне місце честь, збереження культури й самовизначення.",al={"нова й стара орда","чим ця орда інша","різниця орди тралла"}},{q="Хто очолює Нову Орду?",a="Вождем є Тралл, син Дуротана. Він править із Долини Мудрості в Оргріммарі в тісній раді з Верховним Вождем тауренів Кайрном Бладгуфом і Мисливцем Тіней Вол'джином із тролів Темного Списа.",al={"вождь","хто лідер","роль тралла"}},{q="Які раси нині входять до Нової Орди?",a="Ядро Нової Орди — орки, тролі племені Темного Списа й таурени Малгору. За морем, у Східних Королівствах, нежить-Відступники під проводом Леді Сильвани Віндраннер входять до неї завдяки прагматичному військовому союзу.",al={"раси орди","хто в орді","члени орди"}},{q="Чому Відступники приєдналися до Нової Орди?",a="Оточена Багряним Хрестовим Походом, ворожими людьми й рештками Погибелі, Сильвана Віндраннер шукала могутніх союзників, щоб вижити. Таурени на чолі з Архідруїдом Гамуулом Рунтотемом заступилися за них в Оргріммарі, вірячи, що Відступники можуть спокутувати свою долю, і переконали Тралла прийняти їх у союз із розрахунку.",al={"нежить в орді","чому відступники в орді","чому нежить з траллом"}},{q="Чи орки досі спотворені демонічною кров'ю?",a="Ні. Коли Громмаш Хеллскрім і Тралл зійшлися з володарем безодні Манноротом в Ашенвалі, Гром ціною власного життя вбив демона. Загибель Маннорота раз і назавжди зламала кровне прокляття й звільнила кожного орка з демонічного рабства.",al={"демонічна кров","прокляття крові","чи орки ще злі"}},{q="Чи Нова Орда зараз воює з Альянсом?",a="Відкриту, повномасштабну війну офіційно стримує хиткий мир між Траллом і Леді Джайною Праудмур із Терамору. Проте в Ашенвалі, Долині Альтерак і Аратійській Улоговині точаться запеклі сутички: недовіра й суперечки за ресурси раз у раз погрожують перерости у відкриту війну.",al={"чи орда й альянс воюють","мир із альянсом","конфлікт орди й альянсу"}}},fp="9,351,15.518.0,22.511.0,20.493.0,54.293.0,24.221.0,46.251.0,40.319.0,44.253.0,52.303.0"}
P.entries["topic:night-elf"] = {n="Нічний ельф",s="Нічні ельфи, або калдореї, — давня й відлюдна раса, що походить із лісів північного Калімдору. Колись володарі розлогої магічної імперії, вони зреклися таємної магії після катастрофічної Війни Прадавніх і звернулися до шанування Елуни та шляху друїдизму. Після Третьої війни, пожертвувавши своїм безсмертям, щоб зупинити Палаючий Легіон, вони приєдналися до Альянсу, щоб захистити землі предків від зазіхань Орди.",h="Нічні ельфи, або калдореї, — давня й відлюдна раса, що походить із лісів північного Калімдору.",kw={"нічні ельфи","калдореї","елуна","кенарій","тельдрассил","нордрассіл","тіранда віспервінд","друїди"},ang={["class:Druid"]="Традиція нічних ельфів сформувала сучасний друїдизм під проводом напівбога Кенарія, пов'язавши охоронців-калдореїв зі Смарагдовим Сном і захистом природної рівноваги.",["faction:Horde"]="Через напористу заготівлю деревини в Ашенвалі люті Вартові й пильні друїди калдореїв стали одними з ваших найневблаганніших і найнебезпечніших супротивників у Калімдорі.",["race:NightElf"]="Ваш народ несе мудрість і тягар десяти тисячоліть і торує шлях у небезпечній новій дійсності, де смертність стала справжньою, ліси предків в облозі, а давні традиції проходять випробування.",["race:Troll"]="Тролі пам'ятають калдореїв як вискочнів-чаклунів, що тисячі років тому розтрощили великі імперії Амані й Ґурубаші, — так почалося давнє, запекле суперництво."},sec={{t="Діти зірок",b="Тисячоліття тому допитливе нічне плем'я оселилося на берегах Колодязя Вічності — величезного джерела чистої таємної енергії. Поколіннями космічна магія Колодязя змінювала їх, і вони стали високими, фіолетовошкірими, довговічними істотами, що назвали себе калдореями — «дітьми зірок». Їхнє раннє суспільство вели місячна богиня Елуна й лісовий напівбог Кенарій, які плекали їхній глибокий зв'язок із живою природою Калімдору."},{t="Імперія й Розкол",b="Минали століття, і правлячу касту — Високородних на чолі з королевою Азшарою — охопила одержимість розгадати безмежні таємниці Колодязя. Їхнє нерозважливе чаклунство розтрощило тролячі імперії й створило запаморочливі дива, але зрештою привернуло увагу Палаючого Легіону. Демонічне вторгнення, що настало потому, завершилося Великим Розколом: Колодязь обвалився сам у себе, розколов давній Калімдор на окремі континенти й знищив королівство Азшари. Нажахані лихом, уцілілі калдореї суворо заборонили таємну магію під страхом смерті чи вигнання."},{t="Довга варта й нова доба",b="Десять тисяч років нічні ельфи жили відлюдно. Друїди спали в Смарагдовому Сні, зцілюючи світ, а Жриці Елуни й Вартові стерегли ліси Калімдору під Світовим Деревом Нордрассіл. Ця відособленість скінчилася під час Третьої війни, коли Легіон повернувся й напав на Гору Гіджал. Калдореї пожертвували своїм безсмертям, щоб здолати Архімонда. Нині під проводом Верховної Жриці Тіранди Віспервінд і архідруїда Фандрала Стаґгелма нічні ельфи живуть у своєму юному Світовому Дереві, Тельдрассилі, і пліч-о-пліч з Альянсом боронять Ашенваль."}},faq={{q="Що означає «калдореї»?",a="Рідною дарнаською мовою слово «калдореї» означає «діти зірок». Цю назву прийняли перші нічні ельфи, оселившись довкола Колодязя Вічності й присвятивши себе місячній богині Елуні.",al={"значення калдореї","що таке калдореї","рідна назва нічних ельфів"}},{q="Звідки походять нічні ельфи?",a="Приблизно п'ятнадцять тисяч років тому відлюдне плем'я темних тролів оселилося на сяйних берегах Колодязя Вічності. За покоління під дією сирої магічної енергії озера їхні тіла й розум змінилися, і вони стали граційними, довговічними калдореями.",al={"походження нічних ельфів","звідки нічні ельфи","чи ельфи нащадки тролів"}},{q="Чому нічні ельфи не практикують таємну магію?",a="Десять тисяч років тому королева Азшара та її чаклуни-Високородні своїми необачними маніпуляціями з Колодязем Вічності привабили в Азерот демонічний Палаючий Легіон. Війна, що спалахнула, розколола світ під час Великого Розколу. Відтоді нічні ельфи заборонили таємну магію, щоб демони більше ніколи не знайшли Азерот.",al={"чому нічні ельфи без магії","заборона аркани нічних ельфів","чому нічні ельфи заборонили магію"}},{q="Чи нічні ельфи досі безсмертні?",a="Ні. Нічні ельфи здобули безсмертя й нестаріння від Світового Дерева Нордрассіл, яке благословили Аспекти драконів. Під час Битви за Гору Гіджал у Третій війні калдореї вивільнили прадавню силу Нордрассіла, щоб знищити демонічного владику Архімонда, і заплатили за це своїм безсмертям.",al={"чи нічні ельфи безсмертні","чи втратили безсмертя","скільки живуть нічні ельфи"}},{q="Де столиця нічних ельфів?",a="Столиця нічних ельфів — Дарнасус, збудований на величезній кроні Тельдрассила, колосального Світового Дерева, яке посадили біля північно-західного узбережжя Калімдору після Третьої війни.",al={"столиця нічних ельфів","де живуть нічні ельфи","розташування дарнасуса"}},{q="Чому нічні ельфи приєдналися до Альянсу?",a="Після століть відособленості калдореї билися пліч-о-пліч із людьми й дворфами проти Палаючого Легіону на Горі Гіджал. Після війни Орда взялася масово вирубувати священні ліси Ашенвалю, тож нічні ельфи уклали офіційний союз зі Східними Королівствами, щоб захистити свої кордони.",al={"чому нічні ельфи в альянсі","лояльність нічних ельфів","чому приєдналися до альянсу"}}},fp="9,467,21.454.0,28.575.0,30.590.0,26.232.0,36.275.0,44.339.0,31.324.0,39.177.0,42.313.0"}
P.entries["topic:night-watch"] = {n="Нічна Варта",s="Нічна Варта — знесилене міське ополчення, що боронить Даркшир і темні шляхи Сутінколісся. Покинуті Домом Вельмож у Стормвінді, ці місцеві добровольці самотужки протистоять блукаючій нежиті, здичавілим воргенам і прихованій некромантії. Їх очолює Командир Алтея Ебонлок, і без допомоги мандрівних шукачів пригод вони навряд чи стримали б темряву, що підступає до їхнього дому.",h="Нічна Варта — знесилене міське ополчення, що боронить Даркшир і темні шляхи Сутінколісся.",kw={"нічна варта","даркшир","сутінколісся","алтея ебонлок","ополчення","воргени","нежить"},ang={["class:Paladin"]="Паладини вважають, що підтримати відчайдушне чергування Нічної Варти — священний обов'язок, і святою магією захищають простих містян від нестримної некромантії.",["class:Warrior"]="Воїни бачать споріднені душі в загартованих ополченцях, які з простою сталлю й неабиякою витримкою стоять проти гулів, велетенських павуків і воргенів.",["faction:Alliance"]="Герої Альянсу, що приходять до Даркширу, бачать прикордонну громаду, яка без жодної офіційної допомоги від командування тримає рубіж проти кошмарних сил.",["race:Human"]="Для людей королівства біда Нічної Варти оголює гниль і недбалість стормвіндського шляхетського двору, який лишив своїх співгромадян помирати в темряві."},sec={{t="Покинуті короною",b="Коли лиха магія поглинула колись квітуче Велике Селище й перетворила тутешній ліс на Сутінколісся, королівство Стормвінд відвернулося від цього краю. Після зникнення короля Варіана Рінна королівський гарнізон відкликали до столиці. Залишившись без королівських військ і припасів, містяни створили власне добровольче ополчення — Нічну Варту — й присягнули втримати межі Даркширу від жахіть, що повзуть із лісу."},{t="Передова в тумані",b="Зі свого штабу в Даркширі вартові патрулюють дороги, вічно оповиті неприродним туманом. Вороги в них невтомні: ненажерливі скелети й гулі, що розповзаються з цвинтарів Воронячого Пагорба й Тихих Садів, а ще моторошні здичавілі воргени, які нишпорять біля Погибелі Роланда та в Гаю Брайтвуд. Ополченців і припасів значно менше, ніж потрібно, тож Варта вже втратила багатьох найкращих захисників у сутичках із безжальними ворогами на кшталт мандрівного воїна-скелета Мор'Ладіма."},{t="Варта Командира Ебонлок",b="Командир Алтея Ебонлок, донька мера Даркширу, керує обороною з похмурою розважливістю. Досвідченого підкріплення немає, тож вона залучає кожного здатного мандрівника, що прибуває до міста: проріджувати лави скелетів, винищувати голодні вовчі зграї чи розслідувати таємничі місцеві вбивства. Нічна Варта вважає себе останнім оплотом людського життя в краї: якщо її лави не встоять, Даркшир цілком поглине темрява."}},faq={{q="Чому Стормвінд не посилає війська на допомогу Нічній Варті?",a="Король Варіан Рінн зник, і Дім Вельмож Стормвінда опинився в політичному глухому куті. Заявивши, що військові сили мають лишатися довкола столиці й Лісу Елвінн, корона відкликала свої гарнізони, і мешканці Сутінколісся лишилися напризволяще.",al={"чому стормвінд не допомагає нічній варті","де армія стормвінда","чому сутінколісся покинуто"}},{q="Хто командує Нічною Вартою?",a="Командир Алтея Ебонлок очолює ополчення з контори Нічної Варти в Даркширі. Вона — донька мера, Лорда Елло Ебонлока, і сама організовує патрулі на дорогах, нагороди за голови й оборону по всьому Сутінколіссю.",al={"хто керує нічною вартою","командир нічної варти","хто головний у варті даркшира"}},{q="З якими загрозами Нічна Варта бореться найчастіше?",a="Найчастіше їй доводиться мати справу з ожилою нежиттю, що сунеться з Цвинтаря Тихих Садів і Воронячого Пагорба, зграями здичавілих вовків і таємничими вовкоподібними звірами — воргенами, що нишпорять Гаєм Брайтвуд і Погибеллю Роланда.",al={"вороги сутінколісся","з ким б'ються вартові","загрози нічної варти"}},{q="Хто такий Мор'Ладім і чому Варта його боїться?",a="Мор'Ладім — неприкаяний, надзвичайно могутній жах із нежиті, що вештається Цвинтарем Воронячого Пагорба. Він перебив кілька найсильніших патрулів Нічної Варти, тож це одна з найсмертоносніших і найстрашніших істот у краї.",al={"лор мор'ладіма","мор'ладім нічна варта","бос цвинтаря сутінколісся"}},{q="Вартові — професійні солдати чи добровольці?",a="Це місцеві добровольці: фермери, мисливці й містяни, що взялися за зброю, аби вижити. Хоча їх навчають місцеві ветерани, офіційної військової підтримки, королівського спорядження й регулярної платні вони не мають.",al={"чи вартові охорона","походження нічної варти","чи нічна варта армія"}},{q="Де штаб Нічної Варти?",a="Штаб розташований у серці Даркшира: тут Командир Алтея Ебонлок і її офіцери планують патрулі й отримують донесення від вартових на стежках.",al={"будівля нічної варти","де знайти вартових","зала варти даркшира"}}},fp="11,384,22.431.0,23.499.0,32.439.0,59.280.0,29.224.0,51.213.0,51.222.0,53.211.0,46.191.0"}
P.entries["topic:nordrassil"] = {n="Нордрассіл",s="Нордрассіл, «Корона Небес», — перше Світове Дерево, посаджене на вершині Гори Гіджал, щоб уберегти другий Колодязь Вічності. Благословенне Великими Драконячими Аспектами, воно на десять тисяч років дарувало нічним ельфам вічну молодість і безсмертя та глибокий зв'язок зі Смарагдовим Сном. Його жертва в кульмінації Третьої війни зламала наступ Архімонда, але дерево лишилося пораненим, а нічні ельфи — смертними.",h="Нордрассіл, «Корона Небес», — перше Світове Дерево, посаджене на вершині Гори Гіджал, щоб уберегти другий...",kw={"нордрассіл","світове дерево","гора гіджал","аспекти","безсмертя","архімонд","смарагдовий сон"},ang={["class:Druid"]="Укорінений над другим Колодязем Вічності, Нордрассіл завдяки зв'язку з Ізерою дозволяв друїдам легко переходити до Смарагдового Сну. Його рани досі суворо нагадують про ціну захисту природи.",["faction:Alliance"]="Присутність Альянсу на Горі Гіджал скувала відчайдушний союз, що вберіг Нордрассіл від Палаючого Легіону й приніс Калімдору порятунок.",["faction:Horde"]="Вождь Тралл повів Орду на схили Гори Гіджал разом із людьми й нічними ельфами, виборюючи для Малфуріона час, щоб привести в дію пастку біля підніжжя Нордрассілу.",["race:NightElf"]="Нордрассіл десять тисячоліть був колискою вашої цивілізації. Його жертва врятувала світ від Архімонда, але вперше змусила вас зіткнутися зі старінням, хворобами й смертністю."},sec={{t="Корона Небес",b="Десять тисяч років тому, на згарищі Великого Розколу, Іллідан Стормрейдж вилив флакони з водою першого Колодязя Вічності в гірське озеро на вершині Гори Гіджал і породив нове джерело таємної сили. Щоб ця чиста магія не зіпсувала світ і знову не привабила Палаючий Легіон, Драконячий Аспект Алекстраза посадила просто над водами жолудь Дерева-Матері Ґ'Ганір. З нього виріс Нордрассіл. Його коріння проросло глибоко під Азерот, запечатало мінливу енергію Колодязя й розлило по континентах лагідну животворну силу."},{t="Дари Аспектів",b="Благословення трьох Великих Драконячих Аспектів зробили Нордрассіл духовним і культурним серцем цивілізації нічних ельфів. Алекстраза наповнила дерево неперевершеною снагою, що дарувала калдореям життєву силу. Ізера пов'язала дерево зі Смарагдовим Сном, і друїди нічних ельфів могли легко й ясно входити в її сонне царство. А найголовніше — Ноздорму Позачасовий простер своє благословення на його віти: доки стоїть велетенське дерево, нічні ельфи не старітимуть і не стануть жертвою природних хвороб. Так цілий народ отримав тривке безсмертя."},{t="Падіння на Горі Гіджал",b="Спокій Нордрассілу скінчився з Третьою війною, коли владика демонів Архімонд рушив на Гору Гіджал, щоб розірвати дерево й заволодіти безмежною силою Колодязя. Коли смертні захисники опинилися на межі, Малфуріон Стормрейдж ухвалив найтяжче рішення. Засурмивши в Ріг Кенарія, він закликав тисячі духів природи й вивільнив чари, накопичені в самому Нордрассілі. Нищівний вибух, що прогримів услід, знищив Архімонда й розгромив Легіон. Нордрассіл уцілів і поволі загоюється, але його чари розвіялися — і нічні ельфи втратили своє безцінне безсмертя."}},faq={{q="Що означає «Нордрассіл»?",a="Дарнаською «Нордрассіл» означає «Корона Небес». Цю назву дерево дістало через свою величезну висоту: воно здіймається високо над вершиною священної Гори Гіджал.",al={"переклад нордрассіл","що означає нордрассіл мовою дарнасу","значення нордрассіл"}},{q="Де розташований Нордрассіл?",a="Нордрассіл стоїть на вершині Гори Гіджал на півночі Калімдору й коріниться просто у водах другого Колодязя Вічності, створеного Ілліданом Стормрейджем.",al={"розташування нордрассіла","де первісне світове дерево","де нордрассіл"}},{q="Чому нічні ельфи втратили безсмертя?",a="Щоб здолати демонічного владику Архімонда в Битві за Гору Гіджал, Малфуріон Стормрейдж вивільнив захисні чари й благословення, закладені в Нордрассілі. Вибух знищив Архімонда, але спалив благословення Аспектів драконів, поклавши край чарам вічного життя, які наклав Ноздорму.",al={"чому нічні ельфи не безсмертні","смертність нічних ельфів","втрата безсмертя"}},{q="Як Нордрассіл пов'язаний із Тельдрассилом?",a="Нордрассіл — перше Світове Дерево на вершині Гори Гіджал. Тельдрассил — набагато молодше Світове Дерево, яке виростили біля узбережжя Калімдору Архідруїд Фандрал Стаґгелм і Коло Прадавніх, відчайдушно сподіваючись замінити Нордрассіл і повернути втрачене безсмертя.",al={"нордрассіл проти тельдрассила","різниця тельдрассила й нордрассіла","чи тельдрассіл це нордрассіл"}},{q="Чи загинув Нордрассіл, коли здолали Архімонда?",a="Ні. Вибух тяжко обпалив і поранив Світове Дерево, але коріння Нордрассіла вціліло. Дерево досі стоїть на вершині Гори Гіджал і повільно заліковує рани, хоча його прадавні драконячі благословення розвіялися.",al={"чи нордрассіл мертвий","чи нордрассіл вцілів","нордрассіл знищено"}},{q="Які дракони благословили Нордрассіл?",a="Нордрассіл благословили три Аспекти драконів: Алекстраза Життєдавиця, що посадила його й дала йому життєву силу; Ізера Сновидиця, що пов'язала його зі Смарагдовим Сном; і Ноздорму Позачасовий, що подарував нічним ельфам вічну молодість.",al={"хто благословив нордрассіл","благословення драконів світовому дереву","які аспекти благословили нордрассіл"}}},fp="10,411,20.560.0,18.565.0,23.600.0,26.167.0,28.163.0,47.294.0,40.274.0,48.232.0,33.242.0"}
P.entries["topic:orc"] = {n="Орк",s="Орки — колись шаманський клановий народ із чужого світу Дренор, якого демонічний Палаючий Легіон ошукав і зіпсував, перетворивши на кровожерливу силу завойовників. Після вторгнення на Азерот, остаточної поразки й ув'язнення Вождь Тралл згуртував їх, щоб повернути духовну спадщину. У нову добу орки очолюють Орду зі свого щойно здобутого краю Дуротар, прагнучи честі й водночас борючись із тінню демонічного минулого.",h="Орки — колись шаманський клановий народ із чужого світу Дренор, якого демонічний Палаючий Легіон ошукав і...",kw={"орки","орк","дренор","тралл","дуротар","оргріммар","клан морозного вовка","маннорот"},ang={["class:Shaman"]="Для орків шаманство — не просто магія: це повернена душа їхньої культури й духовна спокута після десятиліть демонічного рабства.",["class:Warlock"]="Родичі дивляться на орків-чорнокнижників із глибокою недовірою й огидою, адже магія Скверни — саме та сила, що зіпсувала й поневолила їхній народ.",["faction:Alliance"]="Раси Альянсу досі дивляться на орків із глибокою підозрою й затаєною образою, пам'ятаючи різанину Першої й Другої воєн і руйнування Стормвінда.",["faction:Horde"]="Орки — військовий та ідейний хребет сучасної Орди: вони обстоюють честь і виживання разом із союзниками — тролями, тауренами й Відступниками."},sec={{t="Діти Дренору",b="До свого падіння орки жили кочовими мисливцями й збирачами, духовними кланами по всіх суворих просторах Дренору. Їхня культура трималася на шануванні предків і глибокому єднанні з духами стихій, а провадили їх передусім шановані шамани. Розрізнені клани — як-от Морозні Вовки, Пісня Війни й Тіньовий Місяць — зберігали крихкий мир, підтримуваний на зібраннях двічі на рік, відомих як свято Кош'гарг. Фізично грізне й глибоко горде, традиційне орче суспільство визначали виживання, честь і злагода зі стихіями, а не бездумні завоювання."},{t="Зіпсуття й великі війни",b="Доля орків розбилася, коли Кіл'джеден і чорнокнижник Ґул'дан влаштували їхнє зіпсуття. Обманом змушені випити кров демона Маннорота, орки опинилися в полоні надприродної жаги крові, від якої їхня природна бура шкіра стала хворобливо-зеленою. Скувавши з них першу Орду, демони ледь не винищили дренеїв Дренору, а тоді орки ринули крізь Темний Портал на Азерот. У Першій і Другій війнах падали людські королівства, а орочі армії дійшли до воріт Лордерону, але внутрішня зрада й згуртований Альянс Лордерону зрештою розгромили загарбників, а вцілілих зігнали до жалюгідних таборів інтернування."},{t="Новий початок у Калімдорі",b="Ув'язнення позбавило орків демонічного шалу, і вони лишалися млявими й зламаними, доки не втік Тралл — орк, вирощений у людському полоні. Віднайшовши зв'язок із шаманством, Тралл згуртував клан Морозного Вовка, звільнив родичів із таборів і заснував оновлену Орду. Дослухавшись до пророчих застережень, він повів свій народ через Велике Море до Калімдору. Там жертва Ґрома Хеллскріма назавжди зламала кривавий прокльон Маннорота. Нині орки вибороли собі посушливий край Дуротар і звели місто-фортецю Оргріммар, прагнучи зберегти тяжко здобуту честь серед нового напруження з Альянсом."}},faq={{q="Чому орки зелені?",a="Спочатку шкіра в орків була коричнева. Зелений колір — наслідок тривалого впливу магії скверни й демонічного спотворення, яке почали чорнокнижники Ради Тіней і закріпили вожді, випивши крові володаря безодні Маннорота.",al={"чому шкіра орків зелена","походження зелених орків","бурі й зелені орки"}},{q="Звідки взялися орки?",a="Орки не з Азероту: вони походять із чужого світу Дренор. В Азерот вони прийшли крізь Темний Портал, коли Ґул'дан і одержимий демоном людський чаклун Медів відкрили розлом між світами.",al={"рідний світ орків","чи орки з азероту","звідки орки"}},{q="Хто провідник орків?",a="Орків очолює Вождь Тралл, син Дуротана. Вирощений людьми як раб-гладіатор, Тралл знову відкрив для себе мистецтво шаманства предків, звільнив орків із таборів для інтернованих і привів нову Орду на Калімдор.",al={"вождь орків","лідер орків","хто веде орків"}},{q="Що таке кровне прокляття?",a="Кровне прокляття — демонічне рабство, якого зазнали орки, випивши крові аннігілана Маннорота. Воно вселило в них неконтрольовану жагу крові, що підживлювала їхні війни, але зрештою було зламане, коли Гром Хеллскрім пожертвував життям, щоб убити Маннорота.",al={"кров маннорота","прокляття кровожерливості орків","кров маннорота прокляття"}},{q="Чому орки живуть у Дуротарі?",a="Після Третьої війни Тралл оселив орків у суворому, посушливому прибережному краї, який назвав Дуротаром на честь свого батька Дуротана. Ця безжальна земля водночас слугує спокутою за минулі гріхи й кузнею, що тримає його народ сильним і витривалим.",al={"чому дуротар пустеля","чому оргріммар","чому дуротар"}},{q="Чи всі орки належать до Орди Тралла?",a="Ні. Тралл очолює Нову Орду, але є й клани-відступники. Клан Драконячої Пащі в Багнокраї досі тримається своїх звичаїв поневолення, а клан Блекрок під проводом Ренда Блекгенда й далі воює з Гори Блекрок, відкидаючи мир Тралла.",al={"злі орки","ворожі орки","чи всі орки дружні до орди"}}},fp="3,493,19.589.0,29.626.0,27.625.0,19.248.0,29.218.0,30.217.0,24.275.0,32.242.0,36.254.0"}
P.entries["topic:paladin"] = {n="Паладин",s="Паладини — святі лицарі Альянсу, що поєднують бойову майстерність із божественною магією. Закуті у важкі латні обладунки, вони б'ються зброєю, наснаженою Святим Світлом, щоб захищати невинних, зцілювати поранених і карати лиходіїв.",h="Паладини — святі лицарі Альянсу, що поєднують бойову майстерність із божественною магією.",kw={"паладин","паладини","святе світло","срібна длань","утер світлоносний","собор світла","аури"},ang={["class:Paladin"]="Кожен паладин-новак іде слідами Утера Світлоносця й Алонсуса Фаола, поєднуючи бойову готовність із присягою безкорисливого служіння.",["class:Priest"]="Жерців і паладинів єднає глибока духовна спорідненість: жерці пасуть паству проповідями й вірою, а паладини боронять її сталлю.",["faction:Alliance"]="Паладини — моральна опора Альянсу: вони згуртовують воїнів святими аурами й надихають надією на полі бою.",["race:Dwarf"]="Дворфи Айронфорджа нещодавно прийняли засади Срібної Длані й переконалися, що дисципліна Світла природно пасує до їхньої незламної вдачі.",["race:Human"]="Для людей паладини — незгасна душа Альянсу, що продовжує священний похід, викуваний серед жахіть Другої війни."},sec={{t="Витоки в Лордероні",b="Перших паладинів заснував під час Другої війни архієпископ Алонсус Фаол. Побачивши, яке спустошення спіткало побожних Кліриків Нортшира в Першій війні, Фаол зрозумів, що самі цілителі не виживуть у жорстокій війні з орками. Він зібрав доброчесних лицарів Лордерону й навчив уцілілих кліриків бойового мистецтва та божественної магії. Охрещені Лицарями Срібної Длані й очолювані Утером Світлоносцем, ці поборники давали людським королівствам і захист на полі бою, і духовне відродження."},{t="Поборники Святого Світла",b="Якщо жерці — голос Святого Світла, що проповідують віру й опікуються душами простого люду, то паладини — його збройна рука. Глибока переконаність дає їм чудодійні сили: вони поширюють довкола себе аури, що додають відваги, накладають на союзників освячені благословення й загоюють смертельні рани. У бою з несвятими жахіттями Світло палає в їхніх ударах, і паладини спопеляють нежить і демонів із праведною люттю."},{t="Спадщина на півдні",b="Падіння Лордерону в Третю війну розпорошило первісний орден, проте ідеали Срібної Длані живуть. Нині цю мантію перейняли люди Стормвінда й незламні дворфи Айронфорджа. Діючи з таких святилищ, як Собор Світла та Зала Таїнств, нові паладини присягають своїми мечами й щитами обстоювати справедливість і захищати Альянс від тіней, що згущуються."}},faq={{q="Чим жрець відрізняється від паладина?",a="Жерці — голос Світла: вони служать вірним і дають пастирську настанову через молитву й обряди. Паладини — рука й молот Світла: вони вдягають важкі лати й беруть до рук зброю, щоб безпосередньо вершити божественне правосуддя й захищати слабких на полі бою.",al={"паладин проти жреця","різниця жреця й паладина","чим паладини відрізняються від жерців"}},{q="Хто створив перших паладинів?",a="Архієпископ Алонсус Фаол заснував орден під час Другої війни. Побачивши, як у Першій війні вирізали Кліриків Нортшира, він набрав побожних лицарів і навчив уцілілих кліриків поєднувати бойову дисципліну зі святою магією під стягом Лицарів Срібної Длані.",al={"хто створив паладинів","засновник паладинів","походження срібної длані"}},{q="Які раси можуть бути паладинами?",a="Нині в Альянсі паладинами стають лише люди й дворфи. Спочатку орден був суто людським, але дворфи Айронфорджа прийняли вчення Святого Світла, і їх радо прийняли до Лицарів Срібної Длані.",al={"чи орда може бути паладинами","хто може бути паладином","раси паладинів"}},{q="Чому паладини такі дієві проти нежиті?",a="Святе Світло — прокляття для некротичного спотворення й демонічної енергії. Коли паладини спрямовують божественну силу, вона випалює пошесть і спопеляє нечестивих створінь, тож паладини — найперші поборники проти Погибелі та іншої погані.",al={"паладини проти нежиті","чому свята магія шкодить нежиті","паладини проти погибелі"}},{q="Що сталося з першими Лицарями Срібної Длані?",a="Орден зазнав нищівних втрат під час Третьої війни, коли чума спустошила Лордерон. Братство розкололося серед внутрішньої зради й політичних чвар, хоча вцілілі члени й нові посвячені в Стормвінді та Айронфорджі й далі несуть звання та ідеали ордену.",al={"що сталося зі срібною дланню","чи срібна длань зникла","падіння срібної длані"}},{q="Чи можуть члени Орди стати паладинами?",a="Ні. Традиції паладинів в Азероті глибоко вкорінені в церкві й лицарських орденах Альянсу. Раси Орди звертаються до шаманів, знахарів і воїнів, а не до лицарського шляху Святого Світла.",al={"паладини орди","чи орки можуть бути паладинами","чому в орді немає паладинів"}}},fp="7,232,20.572.0,27.459.0,21.421.0,54.301.0,31.291.0,28.244.0,46.234.0,57.285.0,41.223.0"}
